  Event_117279_ChoiceDesc1 = {
    Text = "[You Once Longed for Innocence] আপনার ডেকে 3টি 「(Skill.Arg1)」 স্থাপন করুন।"
  },
  Event_117279_Desc = {
    Text = "\nসাগর থেকে এক ফিকে সাদা কুয়াশা উঠছে, সবকিছুকে আবছা আবরণে ঢেকে দিচ্ছে।\nজীবন আর মৃত্যুর সীমানা পেরিয়ে, দ্বারভিত্তরের ও বাহিরের দূরত্ব অতিক্রম করে, বহু আগেই ম্লান হয়ে যাওয়া স্মৃতিচারণের ভেতর দিয়ে তুমি দেখতে পাও আলোকে পেছনে ফেলে রোদছাতা ধরা এক ভদ্রমহিলার ছায়ামূর্তি।\nতার সঙ্গে কাটানো সময় ইতোমধ্যেই ফুরিয়ে গেছে, ঠিক যেমন ফুরিয়ে গেছে তার সূক্ষ্ম অথচ উজ্জ্বল যৌবনের রঙ।\nযখন মিথ্যা সূর্য অবশেষে উদিত হয়, কুয়াশা ভেঙে শূন্যতায় মিলিয়ে যায়, আর স্বপ্নের ভেতর তার অবয়ব দুলে ওঠে, আলো আর মায়াস্বপ্নের বুদবুদে রূপান্তরিত হয়ে, নীরব বিদায় জানায় তোমাকে।"
  },
  Event_117279_Name = {
    Text = "মার্ফির মায়া"
  },
  Event_117280_ChoiceDesc1 = {
