  Event_118414_Desc = {
    Text = "পাশা গড়াচ্ছে, গড়গড়ে শব্দ তুলছে।\nকবে থামবে?\nতুমি জানো না, তবু তোমাকে একটি উত্তর দিতেই হবে।"
