  Event_118415_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118415_Desc = {
    Text = "তোমার সাড়া 「আকাশ」-কে কোমল করে তোলে।\nসে আলতো করে তোমার কপালে চুমু খায়।\nআর সেখানে, ঢেউ-আকৃতির এক ফুল ফুটে ওঠে।"
  },
  Event_118415_Name = {
    Text = "সাগরের আলিঙ্গন"
