  Event_118416_ChoiceDesc1 = {
    Text = "[মোহময় কল্পনা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_118416_ChoiceDesc2 = {
    Text = "[Maintain Sanity] প্রতি জাগরণকারীর জন্য, যার অ্যালিমাস 50 বা তার বেশি, 15টি করে কালো চিহ্ন লাভ করুন"
