  Event_118416_ChoiceDesc3 = {
    Text = "[Leave by Force] 3টি ওরিসনের মধ্যে 1টি অর্জন করো"
  },
  Event_118416_Desc = {
    Text = "হয়তো দীর্ঘ যুদ্ধ তোমাকে বিভ্রান্ত করে ফেলেছে, অথবা হয়তো তোমার মনই তোমার দেহকে বিশ্বাসঘাতকতা করেছে।\nএক ধরনের ভারশূন্যতা তোমার চিন্তাকে ভরে তোলে।\nএক মুহূর্তে, তোমার মন হয়ে ওঠে এক ক্যালেইডোস্কোপ—ঝলমলে, দীপ্তিময়, সব রঙের বিদ্যুৎচমকে ভরা।\nঅগণিত অন্তর্দৃষ্টি, ভাবনা আর কল্পনা ঢেউয়ের পর ঢেউয়ের মতো ভেসে আসে, তোমার মস্তিষ্কের প্রতিটি ফাঁক ভরে তোলে।\nএভাবে চলতে থাকলে, খুব শিগগিরই তোমার মস্তিষ্ক এই বিশৃঙ্খলায় ফেটে যাবে।"
  },
  Event_118416_Name = {
    Text = "চিন্তার ক্যালিডোস্কোপ"
  },
  Event_118417_ChoiceDesc1 = {
    Text = "[Join the Gamble] 「(Skill.Arg1)」 উন্নয়ন করো, জুয়ার আসরে প্রবেশ করো"
  },
  Event_118417_ChoiceDesc2 = {
    Text = "[Forget It] 25টি কালো চিহ্ন সংগ্রহ করো"
  },
  Event_118417_Desc = {
    Text = "অচৈতন্যের কুয়াশায়, তোমার চেতনা স্তর স্তর কুয়াশা ভেদ করে ভেসে গেল, বিক্ষিপ্ত হয়ে পড়ল অজানা শূন্যতায়।\nতোমার সামনে দুইটি পাশা নিক্ষেপ করা হল, অথচ যে অজানা জীব জোর করে তোমাকে এখানে টেনে এনেছে, তার অস্তিত্বই দৃষ্টির আড়ালে রইল।\nতুমি কেবল চারদিক থেকে ভেসে আসা বিশৃঙ্খল কণ্ঠস্বর শুনতে পেলে।\n「ফিরে যেতে চাও? তবে চল, এক দফা খেলা হোক।」\n「তোমার জীবনকে বাজি রেখে, ভাগ্যের সঙ্গে জুয়ার সূচনা হোক।」"
  },
  Event_118417_Name = {
    Text = "ভাগ্যের দাবা"
  },
  Event_118418_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118418_Desc = {
    Text = "অতিক্রম করা অভিজ্ঞতা ক্ষণস্থায়ী। তারা কোনো পূর্বাভাস ছাড়াই আসে, আর ঠিক ততটাই হঠাৎ মিলিয়ে যায়।\nতবু অন্তত তোমার মাথা অক্ষত আছে—ওটা সত্যিই বিস্ফোরিত হয়নি।"
