  },
  Event_118419_Desc = {
    Text = "তুমি হারোনি, আবার জেতোনি-ও; ফলাফল না ভালো, না মন্দ। \n「ড্র হলো...」 \nঅজানা জীবটি দীর্ঘশ্বাস ফেলল, তবু তার ভয়েসে অনুতাপের কোনো রেখা ছিল না। \n「কি সুন্দর এক ক্ষুদ্র বিনোদন।」"
  },
  Event_118419_Name = {
    Text = "ভাগ্যের দাবা"
  },
  Event_118420_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118420_Desc = {
    Text = "ধীরে ধীরে, উন্মত্ত সুর এক সুরেলা ও পবিত্র সঙ্গীতে রূপ নেয়।\nঅবশেষে তুমি বুঝতে পারো কেন একে 「পরিপূর্ণ স্তোত্র「 বলা হয়—\nকারণ তা সত্যিই নির্ভুল।"
  },
  Event_118420_Name = {
    Text = "「নিখুঁত」 স্তোত্র"
  },
  Event_118421_ChoiceDesc1 = {
    Text = "[Perceive the Brain] 3টি কমান্ড কার্ডের মধ্যে থেকে 1টি বেছে নিয়ে প্রার্থনাগাথা অর্জন করো: 「(EnchantConfig.Arg1)」"
  },
  Event_118421_ChoiceDesc2 = {
    Text = "[Perceive the Soul] 「(Skill.Arg1)」 উন্নয়ন করো, পুনরায় ছাপ দাও, সর্বোচ্চ 2 বার পর্যন্ত"
  },
  Event_118421_Desc = {
    Text = "মানুষের প্রথম খাঁচা তার নিজের দেহ।\nএই খাঁচার ভেতর মস্তিষ্কই শেষ এবং সবচেয়ে গুরুত্বপূর্ণ কারাগার।\n“সোনা, তুমি কি ভাবো শুধু বেঁচে আছো আর শ্বাস নিচ্ছো বলেই তুমি নিরাপদ?”\nযখন তোমার মস্তিষ্ক তোমার আত্মাকে বিশ্বাসঘাতকতা করবে, তখন তুমি এই পৃথিবীর সবচেয়ে যন্ত্রণাদায়ক নির্যাতন অনুভব করবে।\nআর এই নির্যাতন তোমার সারা জীবন সঙ্গী হয়ে থাকবে।"
  },
  Event_118421_Name = {
    Text = "মস্তিষ্কের কারাগার"
  },
  Event_118422_ChoiceDesc1 = {
    Text = "[Touch the Butterfly] 2টি কার্ড মুছে ফেলো"
  },
  Event_118422_ChoiceDesc2 = {
    Text = "[Drive Away the Butterfly] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকাশ লাভ করে"
  },
  Event_118422_ChoiceDesc3 = {
    Text = "[Leave] Arg1টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_118422_Desc = {
    Text = "গভীর সাগরে কোনো প্রজাপতি নেই। তারা এক ঘরে বন্দি মেয়েটির স্বপ্ন।\nএত সুন্দর, বাতাসে মুক্তভাবে নাচে তারা।\n「যদি… আমিও ওদের মতো উড়ে পালাতে পারতাম…」\nএকটি প্রজাপতি হাউমাউ করে কাঁদে, তার কান্না ডুবে যায় ডানা ঝাপটানোর শব্দ আর টাইপরাইটারের টকটক আওয়াজে।"
  },
  Event_118422_Name = {
    Text = "আত্মা প্রজাপতির ন্যায় নৃত্য করে"
  },
  Event_118423_ChoiceDesc1 = {
