  },
  Event_118423_ChoiceDesc2 = {
    Text = "[Loosen His Bonds] 「(Skill.Arg1)「 দু」বার উন্নয়ন করো, রৌপ্য সৃষ্টি 「(RelicConfig.Arg2)「 এবং 「(RelicConfig.Arg3)「 অর্জন করো"
