    Text = "[Help Him Break Free] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_118423_Desc = {
    Text = "「কেউ কেউ বলে, অন্তহীন কামনাই অগ্রগতির চালিকাশক্তি।\nকিন্তু যখন সেই কামনা এত প্রবল হয়ে ওঠে যে আর তাকে উপেক্ষা করা বা ছিন্ন করা যায় না... আমি অনুভব করি, তা ভেতর থেকে বদলে গিয়ে এক খাঁচায় পরিণত হয়।「\nঅন্ধকারের ভেতর থেকে এক দুর্বল কণ্ঠ উদ্ভাসিত হলো। তুমি বক্তার মুখ দেখতে পেলে না, দেখলে শুধু বাঁধা দুই হাতের জোড়া।\n「এই কামনাগুলো আমার ভয়, আমার দুর্বলতা, আমার আশা, আমার যন্ত্রণা—সবকিছুই গ্রাস করে খায়... আর তাতেই তারা আরও শক্তিশালী হয়ে ওঠে।「\nকণ্ঠটি শেষবারের মতো এক মরিয়া আর্তি জানাল।\n「আমি সবকিছু উৎসর্গ করতে প্রস্তুত! দয়ালু প্রাণ, অনুগ্রহ করে... আমাকে বাঁচাও। অথবা আমাকে মুক্তি দাও।「"
  },
  Event_118423_Name = {
    Text = "বন্ধনের বাসনা"
  },
  Event_118424_ChoiceDesc1 = {
    Text = "[Perceive the Brain] 3টি কমান্ড কার্ডের মধ্যে থেকে 1টি বেছে নিয়ে প্রার্থনাগাথা অর্জন করো: 「(EnchantConfig.Arg1)」"
  },
  Event_118424_Desc = {
    Text = "তুমি মস্তিষ্কের ভেতর এক ঝাঁকুনি অনুভব করলে।\n\"এর কি কোনো বিশেষ তাৎপর্য আছে?\"\nতুমি নিজেকেই জিজ্ঞাসা করলে, কিন্তু তোমার মস্তিষ্ক নীরব রইল।\nনিজেকে করা প্রতিটি জিজ্ঞাসার উত্তর মেলে না।"
  },
  Event_118424_Name = {
    Text = "মস্তিষ্কের কারাগার"
  },
  Event_118425_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118425_Desc = {
    Text = "তুমি মরিয়া হয়ে ওপরে সাঁতরে উঠে পৃষ্ঠ ভেদ করো।\nসাগরের গন্ধে ঘন বাতাস তোমার ফুসফুস ভরে দেয়—স্মরণ করিয়ে দেয় যে বিপদ এখনো ঘোরাফেরা করছে।\nকিন্তু তুমি জানো, সত্যিকারের আকাশ তোমার মাথার অনেক ওপরে।\nসত্য যেমন, কোমল মিথ্যে তাকে আড়াল করতে পারে না।"
  },
  Event_118425_Name = {
    Text = "সাগরের আলিঙ্গন"
  },
  Event_118426_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118426_Desc = {
    Text = "কামনার দড়িতে হাত ছোঁয়াতেই, আত্মার গভীর থেকে উঠে আসে তীক্ষ্ণ এক যন্ত্রণা।\nতোমার ভয়, দুর্বলতা, আশা আর যন্ত্রণা উথলে উঠে পাক খেতে খেতে রক্তমাখা এক দড়িতে রূপ নেয়, যা তোমার হাত বেঁধে ফেলে।\nসেই মুহূর্তে, তুমি এক কণ্ঠস্বর শোনো—বিদ্বেষমাখা উল্লাসে ভরা।\n「সৎ হৃদয়ের জন, তুমি পুরস্কৃত হবে... আর অভিশপ্তও।」"
  },
  Event_118426_Name = {
    Text = "বন্ধনের বাসনা"
  },
  Event_118427_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118427_Desc = {
    Text = "তোমার স্পর্শে প্রজাপতিগুলো কেঁপে ওঠে।\nসৃষ্টির পর থেকে তারা কখনো এমন কোমলতা জানেনি।\nঅতিশয়ে অভিভূত হয়ে তারা উড়তে ভুলে যায়।\nঅগণিত প্রজাপতি ঝরে পড়ে, আর তাদের ডানার আড়াল থেকে উন্মোচিত হয় লুকিয়ে থাকা টাইপরাইটারটি।\nঅসহায় সেই যন্ত্রটি, এখন প্রাণহীন, তার শেষ শক্তি দিয়ে লিখে গেছে মাত্র একটি শব্দ: 「স্বাধীনতা।」"
  },
  Event_118427_Name = {
    Text = "আত্মা প্রজাপতির ন্যায় নৃত্য করে"
  },
  Event_118428_ChoiceDesc1 = {
    Text = "[যুদ্ধের প্রস্তুতি]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমিত করুন「(Skill.Arg2)」"
  },
  Event_118428_ChoiceDesc2 = {
    Text = "[Try to Detour] 25টি কালো চিহ্ন অর্জন করো"
  },
  Event_118428_Desc = {
    Text = "তারাভরা গভীরে, সাগরচারীরা শতাব্দীর পর শতাব্দী তন্দ্রায় নিমগ্ন।\nঅসীম সাগর তাদের উন্মাদনা, তাদের সহনশীলতা, আর তাদের সর্বাধিক ভক্তিপূর্ণ বিশ্বাসের সাক্ষী।\nকেউই তাদের ঈশ্বরের মহা আগমনে বাধা দিতে পারবে না।\nযারা পথে দাঁড়াবে, সাগরচারীদের ক্রোধে তারা ছাইয়ে পরিণত হবে।"
  },
  Event_118428_Name = {
    Text = "নক্ষত্রের নিচে প্রতীক্ষা"
  },
  Event_118429_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118429_Desc = {
    Text = "তুমি স্বতঃস্ফূর্তভাবে কান দু’টি ঢেকে ফেলো।\nঅলৌকিকভাবে, তোমার আত্মার গভীর থেকে ওঠা সেই শব্দ স্তব্ধ হয়ে যায়।\nকিন্তু তা কেবলই অস্থায়ী।"
  },
  Event_118429_Name = {
    Text = "অপবিত্র বীণাধ্বনি"
  },
  Event_118430_ChoiceDesc1 = {
    Text = "[Revisit the Past] 3টি উন্নত প্রার্থনালিপি থেকে 1টি অর্জন করুন"
  },
  Event_118430_ChoiceDesc2 = {
    Text = "[Gaze into the Future] সোনালি রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 উন্নয়ন করো"
  },
  Event_118430_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_118430_Desc = {
    Text = "এই জগতে কিছুই অপরিবর্তিত থাকে না—\nদেবমাতার গড়া প্যারাডাইসও নয়।\nক্ষণিকের জন্য, তুমি সময়ের এক ফাটল দিয়ে কিছু এক ঝলক দেখতে পাও।\nঅতীত, বর্তমান ও ভবিষ্যৎ সেই ফাটলের ভেতর জড়িয়ে থাকে, অবিরাম রূপ বদলায়,\nপ্রতীক্ষা করে তোমার কৌতূহলী দৃষ্টির।"
  },
  Event_118430_Name = {
    Text = "সময়ের ফাটল"
  },
  Event_118431_ChoiceDesc1 = {
    Text = "[Tune] 100টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_118431_ChoiceDesc2 = {
    Text = "[এলোমেলো 2টি কমান্ড কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg1)」]"
  },
  Event_118431_Desc = {
    Text = "নিরাকার ইচ্ছা তোমার পছন্দকে প্রত্যাখ্যান করে। সে তোমাকে পথ বদলানোর আরেকটি সুযোগ দেয়—\nসাবধান, নিরাকার সুরও প্রাণ কেড়ে নিতে পারে।"
  },
  Event_118431_Name = {
    Text = "「নিখুঁত」 স্তোত্র"
  },
  Event_118432_ChoiceDesc1 = {
    Text = "[Feed the Rats] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 লাভ করুন, 1টি উপসর্গ বিকশিত করুন"
  },
  Event_118432_ChoiceDesc2 = {
    Text = "[Drive the Rats Away] 3টি কার্ড থেকে 1টিতে প্রার্থনাগাথা খোদাই করুন:「(EnchantConfig.Arg1)」, তবে 「(Skill.Arg2)」 বিকশিত করুন"
  },
  Event_118432_ChoiceDesc3 = {
    Text = "[Ignore the Rats] 25টি কালো চিহ্ন অর্জন করো"
  },
  Event_118432_Desc = {
    Text = "এই জাহাজের সবকিছুই সময় চক্রের ফাঁদে বন্দি।\nএখানে বেঁচে থাকার জন্য লড়তে থাকা সেই ঘৃণ্য, লোমশ ছোট ছোট প্রাণীগুলোও তাদের নিয়তি থেকে পালাতে পারে না।\nচক্রের পর চক্র, তারা চোখের সামনে যা পায় তাই গ্রাস করে, তবু তাদের ক্ষুধা কোনোদিন মেটে না।\n「খুব... ক্ষুধা...」\nইঁদুরের ঝাঁক থেকে বেরোয় অসুস্থ, কানে বিঁধে যাওয়া চিৎকার।\nঅন্তহীন পুনরাবৃত্তি তাদের করেছে ক্ষুধার্ত আর উন্মাদ—তাদের কিছু একটা খেতেই হবে।\nএখনই। অবিলম্বে।"
  },
  Event_118432_Name = {
    Text = "ক্ষুধার্ত ইঁদুরের দল"
  },
  Event_118433_ChoiceDesc1 = {
    Text = "[Avoid Their Gaze] Golden Relic 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো"
  },
  Event_118433_ChoiceDesc2 = {
    Text = "[Stare into the Eyes] এলোমেলোভাবে 2 জন জাগরণকারীর জাগরণ ঘটাও, তবে 「(Skill.Arg1)「 দু」বার বিকশিত করো।"
  },
  Event_118433_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_118433_Desc = {
    Text = "আকাশের নক্ষত্রপুঞ্জের মতোই, গভীর সাগরেও নিঃসন্দেহে অসংখ্য চোখ আছে।\nসেই চোখগুলো সাগরতলের মাছের, অপবিত্রকৃত গিল-জাতির, আর সাগর নিজস্ব।\nশ্‌, তাদের বিরক্ত কোরো না।\nবিরক্ত কোরো না, গভীর সাগরের উন্মাদনাকে।"
  },
  Event_118433_Name = {
    Text = "গভীর সাগরের চোখ"
  },
  Event_118434_ChoiceDesc1 = {
    Text = "[Ignore the Whispers]"
  },
  Event_118434_ChoiceDesc2 = {
    Text = "[Listen to the Whispers]"
  },
  Event_118434_ChoiceDesc3 = {
    Text = "[Make Something Up]"
  },
  Event_118434_Desc = {
    Text = "「তুমি কি ঈশ্বরের অনুগ্রহ কামনা করো? তুমি কি জানতে চাও নিজের অস্তিত্বের তাৎপর্য?」\nতোমার কানে এক দীর্ঘশ্বাস ভেসে আসে, যেন কোনো মানসিক বিকারগ্রস্তের আত্ম-স্বগতোক্তি, অথবা আকারহীন কিছুর অন্তরঙ্গ হুইসপার।\nবুদ্ধি ও সজাগতার আশ্রয়ে তুমি সেই কণ্ঠকে প্রত্যাখ্যান করো, তবু তা নিজেকেই বলে যেতে থাকে।\n「অনুগ্রহ করে ধৈর্য ধরে শোনো। যা তুমি জানতে চলেছ, তা হলো বিশ্বের পরিণতি-সংক্রান্ত সত্য...」"
  },
  Event_118434_Name = {
    Text = "নিরাকারের ধর্মোপদেশ"
  },
  Event_118435_ChoiceDesc1 = {
    Text = "[Perceive the Brain] 3টি কমান্ড কার্ডের মধ্যে থেকে 1টি বেছে নিয়ে প্রার্থনাগাথা অর্জন করো: 「(EnchantConfig.Arg1)」"
  },
  Event_118435_ChoiceDesc2 = {
    Text = "[Perceive the Soul] 「(Skill.Arg1)」 উন্নয়ন করো, এলোমেলোভাবে আবার ছাপ দাও"
  },
  Event_118435_Desc = {
    Text = "খুলি-আবৃত নিরাপদ আশ্রয়ে থাকা মস্তিষ্ক তোমার কাছে কিছু বার্তা প্রেরণ করল।\nতুমি জানো না, এই বার্তাগুলো স্নায়ু-সংবাহকের রূপান্তর আর জৈব-বিদ্যুৎ প্রবাহের পথে ক্ষয়ে গেছে কি না।\nএকটি মাত্র বিষয় নিশ্চিত—তুমি সেই তথ্য গ্রহণ করেছ, আর তোমার দেহের বস্তুগত উপস্থিতির মাধ্যমে নিজের অস্তিত্ব অনুভব করেছ।"
  },
  Event_118435_Name = {
    Text = "মস্তিষ্কের কারাগার"
  },
  Event_118436_ChoiceDesc1 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_118436_Desc = {
    Text = "\"ভালো উত্তর, কিন্তু দুর্ভাগ্যবশত, তা সংশোধন উত্তর নয়।\"\n\"সংশোধন উত্তরটা কী?\"\nঅজানা জীব তোমার জিজ্ঞাসার উত্তর দিল না, শুধু এক অবজ্ঞামিশ্রিত হাসি ছাড়ল।\n\"কে বলেছে তোমাকে, ভাগ্যের কোনো সংশোধন উত্তর আছে?\""
  },
  Event_118436_Name = {
    Text = "ভাগ্যের দাবা"
  },
  Event_118437_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118437_Desc = {
    Text = "「ভাবছ আমি কি তাদের ছিন্ন করার চেষ্টা করিনি? না—আকাঙ্ক্ষার বিরোধিতা তাকে আরও শক্তিশালী করে তোলে!」\nআকাঙ্ক্ষার দড়িগুলো টানটান হয়ে মাংসে কেটে বসে, আর সেই কণ্ঠস্বর এক মরিয়া আর্তনাদ ছেড়ে দেয়।\n「আমি কখনও তাদের থেকে মুক্ত হতে পারব না... কখনও না!」"
  },
  Event_118437_Name = {
    Text = "বন্ধনের বাসনা"
  },
  Event_118438_ChoiceDesc1 = {
    Text = "[Listen to the Singing] 25টি কালো চিহ্ন অর্জন করো, তবে 「(Skill.Arg2)」 উন্নয়ন করো, নির্বাচন চালিয়ে যাও"
  },
  Event_118438_ChoiceDesc2 = {
    Text = "[Ignore It] ত্যাগ করুন"
  },
  Event_118438_Desc = {
    Text = "কালো কাকটি কাঁদছে।\nকালো কাকটি চিৎকার করছে।\nকালো কাকটি হাহাকার করছে।\nতবু মানুষের কানে তা শুধু গানের মতোই শোনায়।\n\"আহ, কী নির্ভার গান। ইচ্ছে করে আমি যদি কাক হতাম, জগতের সব ঝামেলা থেকে দূরে।\""
  },
  Event_118438_Name = {
    Text = "অনুভূতিহীন বিলাপ"
  },
  Event_118439_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118439_Desc = {
    Text = "প্রজাপতিগুলো মিলিয়ে গেলে, অবশেষে তুমি নিচের টাইপরাইটারটাকে দেখতে পাও।\nওই করুণ, প্রাণহীন বস্তুটি তার শেষ নিঃশ্বাস দিয়ে টাইপ করেছে দুটি শব্দ: 「এখনই চলে যাও।」"
  },
  Event_118439_Name = {
    Text = "আত্মা প্রজাপতির ন্যায় নৃত্য করে"
  },
  Event_118440_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118440_Desc = {
    Text = "অতীতের ছায়ায়, নরম লোমশ কোট পরা এক মেয়ে তোমার দিকে হাত নাড়ে।\nতুমি তার কথা শুনতে পাও না, কিন্তু তার হাসি দেখতে পাও।"
  },
  Event_118440_Name = {
    Text = "সময়ের ফাটল"
  },
  Event_118441_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118441_Desc = {
    Text = "গভীর সাগর আবার ডুবে যায় নীরবতা আর ছায়ায়।\nসেই স্থিরতার মধ্যে তুমি আবারও শুনতে পাও হৃদস্পন্দন।\nএবার তা আসে তোমার ভেতর থেকে।\nঅন্যদের কাছে, তুমি কেবলই এক ধুকপুক করা হৃদয়, অতল গহ্বরে ভেসে বেড়ানো।"
  },
  Event_118441_Name = {
    Text = "যোগ্যতমের উদ্বর্তন"
  },
  Event_118442_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118442_Desc = {
    Text = "এইবার, বাধা নয়, সাগরচারীরাই ছাইয়ে পরিণত হয়।\nতারারা নীরবে দৃশ্যটির দিকে চেয়ে থাকে, যেমন তারা শতাব্দীর পর শতাব্দী ধরে থেকেছে, কোনো উত্তর না দিয়ে।"
  },
  Event_118442_Name = {
    Text = "নক্ষত্রের নিচে প্রতীক্ষা"
  },
  Event_118443_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118443_Desc = {
    Text = "সংখ্যায় বেশি হলেও, নোংরা ইঁদুরগুলোর সাহস তাদের শক্তির চেয়ে সামান্য।\nতোমার দৃঢ়চেতা ভঙ্গিতে ভীত হয়ে তারা আতঙ্কে বিক্ষিপ্ত হয়ে পড়ে।"
  },
  Event_118443_Name = {
    Text = "ক্ষুধার্ত ইঁদুরের দল"
  },
  Event_118444_ChoiceDesc1 = {
    Text = "[Reach Out a Helping Hand] এলোমেলোভাবে 1 জন জাগরণকারীকে জাগাও, তবে 「(Skill.Arg1)」 উন্নয়ন করো"
  },
  Event_118444_ChoiceDesc2 = {
    Text = "[Silently Observing] 3টি ওরিসনের মধ্যে 1টি প্রাপ্ত করো"
  },
  Event_118444_Desc = {
    Text = "একটি ধুকপুক করা হৃদয় ভেসে বেড়ায় পিচকালো গভীরে।\nওটা হয়তো কোনো সাঁতার কাটা মাছের, কিংবা কোনো ফুলকাওয়ালা প্রাণীর।\nতুমি স্পষ্ট দেখতে পাও না—শুধু স্পন্দিত হৃদয়টাকে, আর তার পেছনে ধীরে ধীরে খুলে যাওয়া রক্তাক্ত এক মুখ।\nশিকার করা বা শিকার হওয়া—এটাই প্রকৃতির নিয়ম,\nস্থলে হোক বা সাগরে।"
  },
  Event_118444_Name = {
    Text = "যোগ্যতমের উদ্বর্তন"
  },
  Event_118445_ChoiceDesc1 = {
    Text = "[হাত নেড়ে তাড়ান]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে অরিসন লাভ করে：「(EnchantConfig.Arg1)」，সংক্রমিত হয়「(Skill.Arg2)」"
  },
  Event_118445_ChoiceDesc2 = {
    Text = "[Let It Stay] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_118445_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_118445_Desc = {
    Text = "অন্ধকারের ভেতর থেকে ক্ষীণ এক শব্দের উদ্ভাসন ঘটে।\nওটা এক প্রজাপতি, ভদ্রভাবে জিজ্ঞেস করে:\n「আমি কি তোমার তালুতে বিশ্রাম নিতে পারি?」\n「আমি ভীষণ ক্লান্ত... একটু সময় বিশ্রাম নিতে চাই।」\nপ্রশ্ন করতে করতে প্রজাপতিটি অন্ধকার চিরে পাক খেতে খেতে তোমার দিকে এগিয়ে আসে।\nতার ডানা থেকে ঝরে পড়ে কালো, আঠালো তরল—সে যে ছায়াদের ভেতর দিয়ে এসেছে, তাদের উপহার।"
  },
  Event_118445_Name = {
    Text = "প্রজাপতির অনুরোধ"
  },
  Event_118446_ChoiceDesc1 = {
    Text = "[Leave] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_118446_Desc = {
    Text = "এক মুহূর্ত নীরবতার পর, কিছু একটা তোমার বুকে ছুড়ে দেওয়া হলো।\n\"এটা নাও, আর চলে যাও।\"\n\"ভাগ্য সবসময় সৌভাগ্যবানদের প্রতি উদার।\""
  },
  Event_118446_Name = {
    Text = "ভাগ্যের দাবা"
  },
  Event_118447_ChoiceDesc1 = {
    Text = "[নির্দেশনা অনুসরণ]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমিত করুন「(Skill.Arg2)」"
  },
  Event_118447_ChoiceDesc2 = {
    Text = "[নির্দেশনা উপেক্ষা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমিত করুন「(Skill.Arg2)」"
  },
  Event_118447_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_118447_Desc = {
    Text = "উৎসব শুরু হয়ে গেছে।\nআধ্যাত্মিক শিখা আর রক্তস্নাত আশীর্বাদের মাঝে, অগণিত বিশ্বাসী পরিণত হয়েছে জীবন্ত মশালে—\nঅলৌকিক আত্মারা জোনাকির মতো তোমার চারপাশে বিক্ষিপ্ত, জ্বলজ্বল করছে, অপেক্ষা করছে তোমার নির্বাচনের।"
  },
  Event_118447_Name = {
    Text = "আত্মার প্রদীপস্তম্ভ"
  },
  Event_118448_ChoiceDesc1 = {
    Text = "[Leave] 50টি কালো চিহ্ন অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গটি বিকাশ করো।"
  },
  Event_118448_Desc = {
    Text = "「অজ্ঞ মানুষগুলো!」\nসে-কণ্ঠ ক্ষুব্ধ এক অভিযোগ উচ্চারণ করল, তবে তা ক্রোধের পর্যায়ে পৌঁছায়নি।\nকারণ সে জানে, অজ্ঞদের জীবনেও আত্মজাগরণের ক্ষণ অনিবার্যভাবে আসে।\nতার শুধু সেই দিনের প্রতীক্ষায় থাকতে হবে।\nআর সেই দিন আসার আগে, সে তোমার উপর ঈশ্বরের সীল অঙ্কিত করবে, নিশ্চিত করবে তোমার আত্মার মালিকানা।"
  },
  Event_118448_Name = {
    Text = "নিরাকারের ধর্মোপদেশ"
  },
  Event_118449_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118449_Desc = {
    Text = "[@2 of @3……]\nজ্ঞান-এর এক প্লাবন, সেই নিন্দিত সুরের সঙ্গে, হুড়মুড়িয়ে ঢুকে পড়ে তোমার মস্তিষ্কে।\nকিন্তু তোমার নশ্বর দেহ তোমাকে সীমাবদ্ধ করে, মহাজাগতিক প্রজ্ঞা তোমার নাগালের বাইরে থেকে যায়।\nকি বেদনাদায়ক আক্ষেপ।"
  },
  Event_118449_Name = {
    Text = "অপবিত্র বীণাধ্বনি"
  },
  Event_118450_ChoiceDesc1 = {
    Text = "[Leave] 50টি কালো চিহ্ন অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গটি বিকাশ করো।"
  },
  Event_118450_Desc = {
    Text = "“আসলে, আমিও তোমাকে এই পৃথিবী সম্পর্কে একটি সত্য বলতে চাই…”\n“এই বিশ্ব সৃষ্টি করেছে এক উড়ন্ত পাস্তা-দেবতা, যার গঠনে আছে দুইটি প্রজ্ঞাময় মিটবল-চোখ আর অসীম সক্ষমতার প্রতীক পাস্তা…”\nতুমি গম্ভীর মুখে শোনা এক হাস্যকর গল্প বানিয়ে বলতে থাকো, অপর পক্ষের প্রতিক্রিয়ার প্রতীক্ষা করো।\nকিন্তু অনেকক্ষণ পরও ওদিক থেকে কোনো শব্দ শোনা যায় না।\n“হায়, মনে হয় উন্মত্ত বিশ্বাসীরা রসিকতা বোঝে না।”\nদীর্ঘশ্বাস ফেলে তুমি কেবল সরে যেতে বাধ্য হও।"
  },
  Event_118450_Name = {
    Text = "নিরাকারের ধর্মোপদেশ"
  },
  Event_118451_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118451_Desc = {
    Text = "তোমার সুরমিলন বিশৃঙ্খল শব্দাংশে সঙ্গতি আনতে ব্যর্থ হয়।\nতবু অদৃশ্য ইচ্ছা তোমার প্রচেষ্টাকে স্বীকার করেছে।\nএটাই এক সূচনা।"
  },
  Event_118451_Name = {
    Text = "「নিখুঁত」 স্তোত্র"
  },
  Event_118452_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118452_Desc = {
    Text = "তিনটি অবয়ব কাঁপছিল, নীরবে কাঁদছিল।\nতুমি তাদের বিশ্বাসে সন্দেহ এনেছিলে, আর সেটাই সেই উন্মত্ত ভক্তদের কাছে ছিল সবচেয়ে অমার্জনীয় অপরাধ।"
  },
  Event_118452_Name = {
    Text = "সর্বোৎকৃষ্ট নৈবেদ্য"
  },
  Event_118453_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118453_Desc = {
    Text = "ভবিষ্যতের প্রতিচ্ছবিতে, শুঁড়ওয়ালা মেয়েটি তোমার দিকে অবজ্ঞাভরে তাকিয়ে ধমক দিল।\n\"দেবমাতার প্রকৃত রূপকে অপবিত্র করা যায় না।\"\nতারপর, প্রতিচ্ছবিটি মিলিয়ে গেল, সময়-স্থান ফাটল মুহূর্তেই বন্ধ হয়ে গেল, আর তুমি একা রয়ে গেলে, ঠিক আগের দৃশ্যটি স্মরণ করতে করতে।"
  },
  Event_118453_Name = {
    Text = "সময়ের ফাটল"
  },
  Event_118454_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118454_Desc = {
    Text = "তুমি সাগরচারীদের এড়িয়ে সামনে এগিয়ে যাও।\nউপরে, তারারা সহস্রাব্দের মতোই নরম গ্লিমার ছড়িয়ে যায়।"
  },
  Event_118454_Name = {
    Text = "নক্ষত্রের নিচে প্রতীক্ষা"
  },
  Event_118455_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118455_Desc = {
    Text = "অজানা জীবটি তোমাকে বাধা দিল না।\n\"একদিন, তুমি আবারও ফিরে আসবে।\"\n\"কেউই নিয়তিকে অস্বীকার করতে পারে না।\""
  },
  Event_118455_Name = {
    Text = "ভাগ্যের দাবা"
  },
  Event_118456_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118456_Desc = {
    Text = "একটি দ্রুত, সিদ্ধান্তমূলক আঘাতে হাত দুটো ঢিলে হয়ে যায়।\nকিন্তু তুমি অন্যটির শেষ নিঃশ্বাসটুকু উপেক্ষা করো না।\nঅবশেষে, সে তার অন্তহীন আকাঙ্ক্ষা থেকে মুক্তি পায়।"
  },
  Event_118456_Name = {
    Text = "বন্ধনের বাসনা"
  },
  Event_118457_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118457_Desc = {
    Text = "অনুধাবিত না হওয়াই এই বিশ্বের অবধারিত পরিণতি।\nকেউই আরেক সত্তার সঙ্গে সম্পূর্ণ সহানুভূতি অনুভব করতে পারে না।"
  },
  Event_118457_Name = {
    Text = "অনুভূতিহীন বিলাপ"
  },
  Event_118458_ChoiceDesc1 = {
    Text = "[Listen to the Singing] 35টি কালো চিহ্ন অর্জন করো, তবে 「(Skill.Arg2)」 উন্নয়ন করো, নির্বাচন চালিয়ে যাও"
  },
  Event_118458_ChoiceDesc2 = {
    Text = "[Ignore It] ত্যাগ করুন"
  },
  Event_118458_Desc = {
    Text = "কালো কাকটি কাঁদছে।\nকালো কাকটি চিৎকার করছে।\nকালো কাকটি হাহাকার করছে।\nতবু মানুষের কানে তা শুধু গানের মতোই শোনায়।\n\"আহ, কী নির্ভার গান। ইচ্ছে করে আমি যদি কাক হতাম, জগতের সব ঝামেলা থেকে দূরে।\""
  },
  Event_118458_Name = {
    Text = "অনুভূতিহীন বিলাপ"
  },
  Event_118459_ChoiceDesc1 = {
    Text = "[Listen Closely] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_118459_ChoiceDesc2 = {
    Text = "[Plug Ears] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_118459_Desc = {
    Text = "আকৃতিহীন উন্মত্ততার ভেতর তুমি এক পিয়ানো দেখতে পাও।\nএক জোড়া অস্পষ্ট হাত নাচতে থাকে অদৃশ্য কী-এর ওপর, বাজায় এক অপবিত্র সুর।\nঅদ্ভুত সেই সঙ্গীত তোমার আত্মার গভীর থেকে প্রতিধ্বনি তোলে, শিরা-উপশিরা বেয়ে উঠে গিয়ে পৌঁছে তোমার কাঁপতে থাকা মস্তিষ্কে।"
  },
  Event_118459_Name = {
    Text = "অপবিত্র বীণাধ্বনি"
  },
  Event_118460_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118460_Desc = {
    Text = "সেই সব অনুপ্রেরণা, চিন্তা আর কল্পনা একসঙ্গে বোনা হয়ে গিয়ে মিশে যায় কল্পনাতীত উজ্জ্বলতম রঙে।\nতুমি দেখতে পাও তোমার দেহের ভেতরেই স্থান ভাঁজ খাচ্ছে, সময় ঘুরপাক খাচ্ছে তোমার ইশারায়।\nএই মুহূর্তে তুমি সর্বশক্তিমান, সর্বজ্ঞ—সময় আর স্থানের সঙ্গে একাকার।\nকিন্তু এমন শক্তির সবসময়ই মূল্য দিতে হয়।"
  },
  Event_118460_Name = {
    Text = "চিন্তার ক্যালিডোস্কোপ"
  },
  Event_118461_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118461_Desc = {
    Text = "অবিন্যস্ত আত্মা কর্কশ আর্তনাদে তোমার পথ দেখায়।\nএটা কি নিরাপদ? তুমি জানো না।\nতোমার একমাত্র নির্বাচন—সামনে এগিয়ে যাওয়া।"
  },
  Event_118461_Name = {
    Text = "আত্মার প্রদীপস্তম্ভ"
  },
  Event_118462_ChoiceDesc1 = {
    Text = "[Listen to the Singing] 40টি কালো চিহ্ন অর্জন করো, তবে 「(Skill.Arg2)」 উন্নয়ন করো, নির্বাচন চালিয়ে যাও"
  },
  Event_118462_ChoiceDesc2 = {
    Text = "[Ignore It] 25টি কালো চিহ্ন সংগ্রহ করে চলে যাও।"
  },
  Event_118462_Desc = {
    Text = "কালো কাকটি কাঁদছে।\nকালো কাকটি চিৎকার করছে।\nকালো কাকটি হাহাকার করছে।\nতবু মানুষের কানে তা শুধু গানের মতোই শোনায়।\n\"আহ, কী নির্ভার গান। ইচ্ছে করে আমি যদি কাক হতাম, জগতের সব ঝামেলা থেকে দূরে।\""
  },
  Event_118462_Name = {
    Text = "অনুভূতিহীন বিলাপ"
  },
  Event_118463_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118463_Desc = {
    Text = "অবিন্যস্ত আত্মা এক দীর্ঘশ্বাস ফেলে।\nধীরে ধীরে মিলিয়ে যায় সে, তবু সেই শোকময় শব্দ, প্রায় স্পর্শযোগ্য, গিয়ে বসে তোমার হৃদয়ের ওপর।\nধুপ, ধুপ—তোমার হৃদস্পন্দন আচার অনুষ্ঠানের সুরের সঙ্গে তাল মিলিয়ে যায়।"
  },
  Event_118463_Name = {
    Text = "আত্মার প্রদীপস্তম্ভ"
  },
  Event_118464_ChoiceDesc1 = {
    Text = "[Leave] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_118464_Desc = {
    Text = "「আহ, আহ, কী ভক্তিপূর্ণ মেষশাবক এটি!」\nওই কণ্ঠ দীর্ঘশ্বাস ফেলে, উল্লাসমিশ্রিত প্রশংসায় ভরা।\n「যখন আমার প্রভুর জাগরণ ঘটবে, তোমার মতো মেষশাবকেরা নিশ্চয়ই সেই মহিমান্বিত ও মহান দেবীয় রাজ্যে আশ্রয়ের স্থান পাবে...」"
  },
  Event_118464_Name = {
    Text = "নিরাকারের ধর্মোপদেশ"
  },
  Event_118465_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118465_Desc = {
    Text = "「আকাশ」 তোমার বেপরোয়া সত্তাকে আলিঙ্গন করে।\nএকদিন, পথহারা শিশুটি ফিরে আসবে মায়ের বুকে।\nকারণ তোমার পালানোর ঠাঁই নেই।"
  },
  Event_118465_Name = {
    Text = "সাগরের আলিঙ্গন"
  },
  Event_118466_ChoiceDesc1 = {
    Text = "[Accept the Embrace] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো"
  },
  Event_118466_ChoiceDesc2 = {
    Text = "[Reject the Embrace] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো"
  },
  Event_118466_ChoiceDesc3 = {
    Text = "[Swim to the Surface] 25টি কালো চিহ্ন অর্জন করো"
  },
  Event_118466_Desc = {
    Text = "বিশ্ব গলে গলে বেরিয়ে আসছে তোমার চোখ দিয়ে।\nএই মুহূর্তে, তোমাকে ঘিরে থাকা গভীর সাগরই হয়ে ওঠে 「আকাশ।」\nপ্রায় ডুবে যাওয়ার যন্ত্রণায়, এই গভীর নীল 「আকাশ」 তোমার দিকে ঝুঁকে আসে, তোমাকে আলিঙ্গন করতে উদগ্রীব।\nসে বিচার করে না—সে শুধু দেয়।"
  },
  Event_118466_Name = {
    Text = "সাগরের আলিঙ্গন"
  },
  Event_118467_ChoiceDesc1 = {
    Text = "[Scold Them] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 উন্নয়ন করো"
  },
  Event_118467_ChoiceDesc2 = {
    Text = "[তাদের সাড়া দাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_118467_ChoiceDesc3 = {
    Text = "[Ignore Them] 50টি কালো চিহ্ন অর্জন করো"
  },
  Event_118467_Desc = {
    Text = "তিনটি অস্পষ্ট আকারের আত্মা তোমার পথ রোধ করে দাঁড়াল।\nএকটি অবয়ব গম্ভীর ভঙ্গিতে তোমার দিকে নত হয়ে রক্ত প্রার্থনা করল। তোমার প্রবহমান রক্তই দেবতাদের নিকট সর্বোৎকৃষ্ট নৈবেদ্য।\nএকটি অবয়ব শীতল দৃষ্টিতে তোমার দিকে ছুরি তুলল, তোমার মাংস কেটে নেওয়ার অভিপ্রায়ে। সেই অরূপান্তরিত মানব-মাংস নিশ্চয়ই দেবতাদের অনুগ্রহ কুড়োবে।\nশেষ অবয়বটি নীরবে তোমার দিকে তাকিয়ে রইল, আশা করল তুমি নিজেই নিজের জীবন শেষ করবে, প্রমাণ করবে সবচেয়ে ভক্তিপূর্ণ বিশ্বাস।"
  },
  Event_118467_Name = {
    Text = "সর্বোৎকৃষ্ট নৈবেদ্য"
  },
  Event_118468_ChoiceDesc1 = {
