  Event_118469_ChoiceDesc2 = {
    Text = "[Leave] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_118469_ChoiceDesc3 = {
    Text = "[Leave] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_118469_Desc = {
    Text = "「না! আমরা এটা প্রত্যাখ্যান করি! আমাদের চাই আরও... সুস্বাদু কিছু।」\n「তাহলে তা হবে... তোমার রক্ত আর মাংস!」\nইঁদুরের ঝাঁক চিৎকার করতে করতে তোমার দিকে ঝাঁপিয়ে আসে।\nমনে হয়, উদ্বেল সুকোমল হৃদয় কখনও কখনও স্বস্তির চেয়ে বেশি বিপদ ডেকে আনে।"
  },
  Event_118469_Name = {
    Text = "ক্ষুধার্ত ইঁদুরের দল"
  },
  Event_118470_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118470_Desc = {
    Text = "তোমার শ্রদ্ধা অদেখা সেই চোখগুলোর অনুগ্রহ জিতে নেয়।\nঅদৃশ্য হওয়ার আগে তারা উত্তাল সাগর পেরিয়ে পাঠায় এক উপহার:\nগভীর সাগরের দাবির এক চিহ্ন, তোমার গায়ে অঙ্কিত।"
  },
  Event_118470_Name = {
    Text = "গভীর সাগরের চোখ"
  },
  Event_118471_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118471_Desc = {
    Text = "তোমার অটল দৃষ্টির নিচে ধীরে ধীরে নড়েচড়ে ওঠে গভীর সাগর।\nঅবিন্যস্ত ঢেউ তোমার চারপাশে ফেনিয়ে ওঠে, বয়ে আনে বর্ণনাতীত প্রলাপ।\nঅতল গহ্বরের ক্রোধ অনুভব করো—এক আশীর্বাদ আর অভিশাপ, জড়ানো একসঙ্গে।"
  },
