  Event_118473_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118473_Desc = {
    Text = "রক্ত, মাংস, জীবন।\nউৎসর্গ প্রস্তুত, এখন তোমার যা করার তা হলো নীরবে দেবীয় ভোজের প্রতীক্ষা।"
