  Event_118474_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118474_Desc = {
    Text = "প্রজাপতি তোমার প্রত্যাখ্যান বুঝতে পারে।\nতার রঙিন ডানায় লেপটে থাকা পিচের আস্তরণ কাঁপতে কাঁপতে সে টলমল উড়ে বেড়ায় অন্ধকারে।\nশীঘ্রই, ছায়া আবার তাকে গিলে ফেলে। এবার, তার আর লড়াই করার শক্তি নেই।"
  },
  Event_118474_Name = {
    Text = "প্রজাপতির অনুরোধ"
  },
  Event_118475_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118475_Desc = {
    Text = "প্রজাপতিটি তোমার তালুতে নেমে বসে, তার রঙিন ডানা থেকে ঝরে পড়া কালো আঠালো তরলের সঙ্গে।\nতুমি দীর্ঘশ্বাস ফেলতেই, উজ্জ্বল ডানাগুলো ধীরে ধীরে গলে যায়, তারের সঙ্গে মিশে এক অস্পষ্ট, বিশৃঙ্খল রূপ ধারণ করে।\nএই প্রজাপতি আর কখনও অন্ধকারকে চিনবে না।\nতোমার হাতের মুঠোয় সে শান্তিতে ঘুমিয়ে থাকে।"
  },
  Event_118475_Name = {
    Text = "প্রজাপতির অনুরোধ"
  },
  Event_118477_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118477_Desc = {
    Text = "কর্কশ কণ্ঠের কাকটি অবশেষে চোখ বন্ধ করল।\nঅস্বীকৃত ও অদেখা বিদ্বেষের মধ্যে, সে শেষ নিঃশ্বাস ফেলল, আর এক পুকুর কালো কাদায় পরিণত হলো।"
  },
  Event_118477_Name = {
    Text = "অনুভূতিহীন বিলাপ"
  },
  Event_118478_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118478_Desc = {
    Text = "「ধন্যবাদ...」 \nধুকপুক করা হৃদয়টি দিগন্তের দিকে লাফিয়ে ওঠে।\nশীঘ্রই, পিচকালো অ্যাকুওরের গভীর থেকে মাংস চিবোনোর শব্দ প্রতিধ্বনিত হতে থাকে।"
  },
  Event_118478_Name = {
    Text = "যোগ্যতমের উদ্বর্তন"
  },
  Event_118479_ChoiceDesc1 = {
    Text = "[Accept the Invitation] 「(Skill.Arg1)」 উন্নয়ন করো, অভিশপ্ত নিদর্শন 「(RelicConfig.Arg2)」 অর্জন করো"
  },
  Event_118479_ChoiceDesc2 = {
    Text = "[Refuse the Invitation] 1টি রেলিক ধ্বংস করার জন্য বেছে নিন এবং 1টি পুরস্কার লাভ করুন"
  },
  Event_118479_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_118479_Desc = {
    Text = "\"এই জাহাজের সবকিছুই এই অন্তহীন ভেঙে পড়া আর পুনরারম্ভ হওয়া প্যারাডাইসের অংশ হয়ে যেতে হবে।\"\nউন্মত্ত সুরগুলো তোমার মস্তিষ্কে অনুরণিত হলো, অদৃশ্য এক ইচ্ছার প্রত্যাদেশ যেন।\n\"এখানে কোনো অশ্রু নেই, কোনো বেদনা নেই, আছে কেবল নির্মল পবিত্র সঙ্গীত আর অনন্ত হাসি।\"\n\"তুমি কি এই প্যারাডাইসে যোগ দিতে চাও, এই নিখুঁত সুরের অংশ হয়ে উঠতে চাও?\""
  },
  Event_118479_Name = {
    Text = "「নিখুঁত」 স্তোত্র"
  },
  Event_118480_ChoiceDesc1 = {Text = "[Leave]"},
  Event_118480_Desc = {
    Text = "তোমার নীরবতায়, আত্মাগুলো নীরবে বিলীন হয়ে যায়।\nযারা বিশ্বাসীদের বোঝে না, তারা তাদের সময়ের যোগ্য নয়।"
  },
  Event_118480_Name = {
    Text = "সর্বোৎকৃষ্ট নৈবেদ্য"
  },
  Event_123616_ChoiceDesc1 = {
    Text = "[Claim Standard Relic]"
  },
  Event_123616_Desc = {
    Text = "সব অ্যাওয়েকনারের অ্যালিমাস 100-তে নির্ধারণ করো, কীফ্লেয়ার 1000-তে নির্ধারণ করো, এবং এইচপি 80%-এ স্থির করো。\n2টি কার্ড সরিয়ে ফেলো এবং 3টি উপসর্গ কার্ড সংযোজন করো。\nরক্তিম চুল্লি 12.5%-এ নির্ধারণ করো, 4টি কার্ড বেছে নিয়ে আল্ট্রা স্পেসে স্থাপন করো。\nস্ট্যান্ডার্ড রেলিক প্যাক অর্জন করো।"
  },
  Event_123616_Name = {
    Text = "সলতের পথ এড়িয়ে যাও"
  },
  Event_125696_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125696_Desc = {
    Text = "অকারণ ক্রোধ তোমাকে তাড়িত করে, তুমি হাত তুলে প্রাণপণে তাদের তাড়াও। তুমি এই ধাঁধায় অনেকক্ষণ আটকে আছ, হয়তো তুমি একটা তীব্র যুদ্ধের জন্য আকুল, এমনকি শুধু সমাপ্তির জন্যও আকুল……\nকিন্তু কাকের ঝাঁক কিছুই করেনি। তোমার দৃষ্টির সামনে, অতল অন্ধকার মিলিয়ে যায়।\nকাকের ঝাঁক মঞ্চের শেষ প্রান্তে অদৃশ্য হয়ে যায়, সেই জায়গায় যেখানে তুমি যেতে চলেছ।"
  },
  Event_125696_Name = {
    Text = "কাকের অতল গহ্বর"
  },
  Event_125697_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125697_Desc = {
    Text = "「ভীতু।」 নারী কণ্ঠটি তার হাসিতে বিদ্রূপ লুকানোর সামান্যতম চেষ্টাও করল না।\n「যাও, যত দূরে পারো চলে যাও।」"
  },
  Event_125697_Name = {
    Text = "ভাগ্যের তালা"
  },
  Event_125698_ChoiceDesc1 = {
    Text = "[তাড়ান]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে অরিসন লাভ করে：「(EnchantConfig.Arg1)」，সংক্রমিত হয়「(Skill.Arg2)」"
  },
  Event_125698_ChoiceDesc2 = {
    Text = "[শ্রবণ]রৌপ্য সৃষ্টি রেলিক 「(RelicConfig.Arg1)「 অর্জন করুন, 「(Skill.Arg2)「 সংক্রমিত হন"
  },
  Event_125698_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_125698_Desc = {
    Text = "অন্ধকার থেকে একটি মৃদু শব্দ ভেসে এলো। একটি প্রজাপতি তোমার হাতের তালুতে এসে বসলো। তুমি তাকে চিনতে পারলে।\n「মিস আরাকনে……আপনি কখনো আমাদের পরিত্যাগ করেননি, তাই না?」\nপ্রজাপতির সুন্দর নকশা, তোমার পাশের মানুষটির দিকে তাকিয়ে আছে।"
  },
  Event_125698_Name = {
    Text = "প্রজাপতির অবশিষ্ট জীবন"
  },
  Event_125699_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125699_Desc = {
    Text = "সেই শব্দ ও অক্ষরগুলো মৌমাছির ঝাঁকের মতো তোমার মস্তিষ্কে ঢুকে পড়ে। তুমি শ্বাস চেপে ধরে মনোযোগ কেন্দ্রীভূত করো, সেই অপ্রয়োজনীয় চিন্তাগুলোকে মাথা থেকে তাড়িয়ে দাও।\nউপেক্ষা করা পড়ার চেয়ে অনেক অনেক বেশি কঠিন, কিন্তু তুমি সেটা করতে পেরেছো।"
  },
  Event_125699_Name = {
    Text = "ডাইমেনশন টেলিগ্রাম"
  },
  Event_125700_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125700_Desc = {
    Text = "ওটা শত্রুর তৈরি মায়া!\nতুমি মাথা নাড়লে, সচেতন হয়ে উঠলে এবং আবার হাতের রুপার চাবি শক্ত করে ধরলে।"
  },
  Event_125700_Name = {
    Text = "মদের প্রতিবিম্ব"
  },
  Event_125701_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125701_Desc = {
    Text = "তুমি মনোযোগ দিয়ে সেই চোখের দিকে তাকাও, একদৃষ্টে দেখো, মন দিয়ে শোনো। তুমি অভিনেতার অন্তরে প্রবেশ করার চেষ্টা করো, তার ভোগ করা যন্ত্রণা অনুভব করো।\nতুমি এগিয়ে যাও, আরও কাছে। তুমি তার দেহ ভেদ করে তার আত্মাকে স্পর্শ করো……\nহঠাৎ চোখ মেলে দেখো, তুমি মঞ্চের মাঝখানে দাঁড়িয়ে, অশ্রু তোমার আঙুলের ডগা বেয়ে গড়িয়ে পড়ছে।\nসেটা ছিল দর্শকদের উদ্দেশ্যে তোমার আত্মার উন্মোচন।"
  },
  Event_125701_Name = {
    Text = "অভিনেতার অন্তর্কথা"
  },
  Event_125702_ChoiceDesc1 = {
    Text = "[তার সাথে আলোচনা করুন]1টি কমান্ড কার্ড মুছুন, Arg1 কালো সীল অর্জন করুন"
  },
  Event_125702_ChoiceDesc2 = {
    Text = "[নীরব থাকুন]"
  },
  Event_125702_Desc = {
    Text = "「আনন্দের সমাপ্তি অবশ্যই সুন্দর, কিন্তু সেই মিথ্যা আনন্দ কখনোই দর্শকদের হৃদয় স্পর্শ করতে পারে না……」\nনাট্যকার চোখ বন্ধ করে গভীর চিন্তায় মগ্ন হলেন। তিনি এই সমাপ্তিতে সন্তুষ্ট নন।"
  },
  Event_125702_Name = {
    Text = "নাটকের সমাপ্তি"
  },
  Event_125703_ChoiceDesc1 = {
    Text = "[Listen to the Singing] 35টি কালো চিহ্ন অর্জন করো, তবে 「(Skill.Arg2)」 উন্নয়ন করো, নির্বাচন চালিয়ে যাও"
  },
  Event_125703_ChoiceDesc2 = {
    Text = "[Ignore It] ত্যাগ করুন"
  },
  Event_125703_Desc = {
    Text = "「কিচির—কিচির—ভাগ্যের দেবী তাঁর চরকা ঘোরান।\nকিচির—কিচির—ভাগ্যের সুতো তাঁর হাতে একত্রিত হয়।」"
  },
  Event_125703_Name = {
    Text = "শেষ ভবিষ্যদ্বাণী"
  },
  Event_125704_ChoiceDesc1 = {
    Text = "[নিজে]ডেক থেকে এলোমেলোভাবে 3টি কমান্ড কার্ড পান এবং 1টি বেছে নিয়ে কপি করুন"
  },
  Event_125704_ChoiceDesc2 = {
    Text = "[উইলিয়াম]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，「(Skill.Arg2)」সংক্রমিত করো"
  },
  Event_125704_ChoiceDesc3 = {
    Text = "[কেউ না]25 কালো মুদ্রা অর্জন করুন"
  },
  Event_125704_Desc = {
    Text = "তুমি নিশ্চিত যে তুমি মাতাল হওনি, কিন্তু মদের দিকে তাকাতেই তুমি এক শান্ত হ্রদে তলিয়ে গেলে।\nমার্জিত পেয়ালায় একটি ছায়ামূর্তি প্রতিফলিত হলো—সে কে?"
  },
  Event_125704_Name = {
    Text = "মদের প্রতিবিম্ব"
  },
  Event_125705_ChoiceDesc1 = {
    Text = "[শ্রবণ]রৌপ্য সৃষ্টি রেলিক 「(RelicConfig.Arg1)「 অর্জন করুন"
  },
  Event_125705_ChoiceDesc2 = {
    Text = "[তাড়িয়ে দাও]75 কালো সিল অর্জন করুন, সংক্রমিত হন「(Skill.Arg2)」"
  },
  Event_125705_Desc = {
    Text = "যখন তুমি দেহের ভেতরের পদার্থদেহের শক্তির কাছে যাও, তোমার মনে একঝাঁক কাক আবির্ভূত হয়, তোমার বিক্ষুব্ধ মানসিক জগতে চক্কর দিতে থাকে।\n\nকাকের দল তোমাকে ঘিরে ধরে, মাথার উপরে একটি অতল গহ্বর উল্টো হয়ে ঘুরতে থাকে।\nদশ লক্ষ কাক একসাথে ডেকে ওঠে, যেন এক উপহাসমাখা ভবিষ্যদ্বাণী।"
  },
  Event_125705_Name = {
    Text = "কাকের অতল গহ্বর"
  },
  Event_125706_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125706_Desc = {
    Text = "তুমি এবং আরাকনে পাশের ভেঙে পড়া নিয়তিকে স্থিতিশীল করার চেষ্টা করো। তোমাদের প্রচেষ্টা সামান্যই ফলপ্রসূ হয়, কিন্তু এটুকুই যথেষ্ট। অর্জিত সময়কে কাজে লাগিয়ে, তোমরা নেফরিয়ার দিকে এগিয়ে যেতে থাকো।\nতুমি এখানে এসেছো, তাকে মুক্তি দেওয়ার জন্য।"
  },
  Event_125706_Name = {
    Text = "ভাগ্যের জালের পরিসমাপ্তি"
  },
  Event_125707_ChoiceDesc1 = {
