  },
  Event_125707_ChoiceDesc2 = {
    Text = "[Ignore It] ত্যাগ করুন"
  },
  Event_125707_Desc = {
    Text = "「তারা বিশাল জালের সাথে মৃত্যুবরণ করেছিল, নিঃশব্দে।」"
  },
  Event_125707_Name = {
    Text = "শেষ ভবিষ্যদ্বাণী"
  },
  Event_125708_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125708_Desc = {
    Text = "এটি অতল কারাগারে পাঠানো একটি টেলিগ্রাম।\n「তাড়াহুড়ো করো না, আমার সন্তানেরা। কারাগারের দ্বার শীঘ্রই উন্মুক্ত হবে, তোমাদের মুক্তি আসন্ন।」"
  },
  Event_125708_Name = {
    Text = "ডাইমেনশন টেলিগ্রাম"
  },
  Event_125709_ChoiceDesc1 = {
    Text = "[তাড়াও]এলোমেলোভাবে 1টি কমান্ড কার্ড অরিসন পায়：「(EnchantConfig.Arg1)」，「(Skill.Arg2)」সংক্রমিত করো"
  },
  Event_125709_ChoiceDesc2 = {
    Text = "[শ্রবণ]3টি নির্দেশ কার্ড থেকে 1টি বেছে নিয়ে মুদ্রাঙ্কন অর্জন করুন: 「(EnchantConfig.Arg1)」"
  },
  Event_125709_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_125709_Desc = {
    Text = "একটি প্রজাপতি আলতো করে তোমার হাতে এসে বসেছে। এর সুন্দর নকশাগুলো চোখের মতো, নীরবে তোমার দিকে তাকিয়ে আছে।\nহয়তো, সে তোমাকে কিছু বলতে চায়?"
  },
  Event_125709_Name = {
    Text = "প্রজাপতির ছোট্ট বিশ্রাম"
  },
  Event_125710_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125710_Desc = {
    Text = "বিশ জোড়া শোকার্ত চোখ তোমার দিকে তাকিয়ে আছে। কাকেরা গান থামিয়ে দিয়েছে, শেষ ভবিষ্যদ্বাণী নিয়ে এই টলমল জালটি ছেড়ে চলে গেছে।"
  },
  Event_125710_Name = {
    Text = "শেষ ভবিষ্যদ্বাণী"
  },
  Event_125711_ChoiceDesc1 = {
    Text = "[Lean Out] সোনার রেলিক 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_125711_ChoiceDesc2 = {
    Text = "[Give Up Checking] 50টি কালো চিহ্ন গ্রহণ করুন"
  },
  Event_125711_Desc = {
    Text = "রাস্তার কোণ ঘুরতেই আপনি একটি সাদামাটা প্রেক্ষাগৃহ দেখতে পেলেন। আপনার মনে পড়ে না লন্ডিনিয়ামে এমন কোনো দোকান ছিল।"
  },
  Event_125711_Name = {
    Text = "স্মৃতি প্রেক্ষাগৃহ"
  },
  Event_125712_ChoiceDesc1 = {
    Text = "[ভাগ্য মেনে নিন]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে মুদ্রাঙ্কন অর্জন করুন: 「(EnchantConfig.Arg1)」"
  },
  Event_125712_ChoiceDesc2 = {
    Text = "[ভাগ্যের বিরুদ্ধে প্রতিরোধ]「(Skill.Arg1)」 সংক্রমিত হন, পুনরায় অঙ্কিত করুন, সর্বাধিক 2 বার করা যাবে"
  },
  Event_125712_Desc = {
    Text = "「আহ, আমরা আবার দেখা করলাম, প্রিয়।」\nতুমি তোমার মস্তিষ্কে প্রতিধ্বনিত সেই তরুণী কণ্ঠস্বর উপভোগ করতে শুরু করেছ। এটি কোমল, প্রলোভনময়, যেন পোকামাকড় ধরার জাল।\n「এসো, বলো আমাকে, তুমি কি তোমার নিয়তি মেনে নিতে রাজি?」"
  },
  Event_125712_Name = {
    Text = "নিয়তির বন্দিশালা"
  },
  Event_125713_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125713_Desc = {
    Text = "「বোকা মানুষ, আমি কি তোমার খুব পরিচিত?」\nকালো বিড়ালটি বিরক্তভাবে তোমার দিকে একবার তাকিয়ে মুখ ফিরিয়ে নিল।\n「এখান থেকে চলে যাও। পরের বার আর এরকম বোকামি করো না।」"
  },
  Event_125713_Name = {
    Text = "রূপান্তর পরিবর্তন"
  },
  Event_125714_ChoiceDesc1 = {
    Text = "[ছবি তোলা]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে এনগ্রেভিং অর্জন করুন: 「(EnchantConfig.Arg1)」"
  },
  Event_125714_ChoiceDesc2 = {
    Text = "[ভঙ্গি পরিবর্তন]「(Skill.Arg1)」 সংক্রমিত হন, বিকল্প 1-এ প্রাপ্ত মুদ্রাঙ্কন পরিবর্তন করুন, দুইবার ব্যবহার করা যাবে"
  },
  Event_125714_Desc = {
    Text = "একটি ক্যামেরা একাকী মঞ্চের উপর দাঁড়িয়ে আছে, এর কালো লেন্স তোমার দিকে তাকিয়ে আছে, যেন কোনো যান্ত্রিক দেবতার সৃষ্ট রহস্যময় যৌগিক চোখ।\n「এই থিয়েটারে অনেকদিন কোনো দর্শক আসেনি... স্বাগতম! স্বাগতম! এসো একটা ছবি তুলি! সম্পূর্ণ বিনামূল্যে!」\nক্যামেরাটি উত্তেজিতভাবে চিৎকার করছে। এই অবহেলিত মঞ্চে, সে-ই একমাত্র নায়ক।"
  },
  Event_125714_Name = {
    Text = "দর্শক আসনের স্মৃতিচিত্র"
  },
  Event_125715_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125715_Desc = {
    Text = "「যে ব্যক্তি ভাগ্যকে প্রশ্ন করে না, সে কীভাবে ভাগ্যের উত্তর আশা করতে পারে?」"
  },
  Event_125715_Name = {
    Text = "ভাগ্যের তালা"
  },
  Event_125716_ChoiceDesc1 = {
    Text = "[চিন্তায় অচলাবস্থা ভাঙা]সিলভার সৃষ্টি রেলিক 「(RelicConfig.Arg1)「 অর্জন করুন, 「(Skill.Arg2)「 সংক্রমিত হন"
  },
  Event_125716_ChoiceDesc2 = {
    Text = "[স্বাভাবিকভাবে চলতে দাও]সোনালি সৃষ্টি রেলিক 「(RelicConfig.Arg1)「 অর্জন করুন, 「(Skill.Arg2)「 সংক্রমিত হন, 「(Skill.Arg3)「"
  },
  Event_125716_ChoiceDesc3 = {
    Text = "[Surface] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_125716_Desc = {
    Text = "একটি নতুন মঞ্চ, দুটি পরস্পর জড়িয়ে থাকা জীবন……পুলিশের চোখ এড়িয়ে পালানোর পথে, তুমি আরাকনে তোমাকে যা বলেছিল সেসব গুছিয়ে নিচ্ছ।\nজটিল চিন্তার ভিড়ে, তুমি শান্ত গভীর সমুদ্রে তলিয়ে যাও।"
  },
  Event_125716_Name = {
    Text = "নির্বিকার"
  },
  Event_125717_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125717_Desc = {
    Text = "প্রজাপতিটি তোমার কাঁধে এসে বসল, তোমার কানের কাছে ঘেঁষে এল। তুমি মনোযোগ দিয়ে শুনলে, কিন্তু শুধু তার ডানার স্পন্দনই শুনতে পেলে, যেন নিঃশব্দ এক দীর্ঘশ্বাস।\nতোমার শোনার মাঝেই সেই বর্ণিল ডানাদুটি ধীরে ধীরে গলে গেল, প্রজাপতিটি তোমার কাঁধে চিরনিদ্রায় শায়িত হলো।\nসে তোমাকে কী বলতে চেয়েছিল, তা তুমি আর কখনো জানতে পারবে না।"
  },
  Event_125717_Name = {
    Text = "প্রজাপতির অবশিষ্ট জীবন"
  },
  Event_125718_ChoiceDesc1 = {
    Text = "[চর্বণ]এলোমেলোভাবে 1টি জাগ্রত সত্তাকে জাগ্রত করুন, সংক্রমিত করুন「(Skill.Arg1)」"
  },
  Event_125718_ChoiceDesc2 = {
    Text = "[Refuse] 3টি প্রার্থনাগাথা থেকে 1টি খোদাই করো"
  },
  Event_125718_Desc = {
    Text = "「ক্ষুধা পেয়েছে, প্রিয় অতিথি?」\nবার কাউন্টারের পেছন থেকে একটি আঠালো কণ্ঠস্বর ভেসে এলো। তুমি পেছনে ফিরে তাকালে, কিন্তু কিছুই দেখতে পেলে না।\n「মিডনাইট মাস্ক বারের স্ন্যাকসও দূর-দূরান্তে বিখ্যাত। একবার চেখে দেখবে নাকি?」"
  },
  Event_125718_Name = {
    Text = "ভাগ্যের স্বাদ"
  },
  Event_125719_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125719_Desc = {
    Text = "আপনি এর উপরের লেখা যথেচ্ছভাবে পড়তে সাহস করলেন না, শুধু সেই সূক্ষ্ম খামটি মনোযোগ দিয়ে পর্যবেক্ষণ করলেন।\nখামের উপর মোমের সিলে একটি অস্পষ্ট বংশীয় প্রতীক খোদাই করা, তার উপরে সুন্দর অলংকৃত অক্ষরে লেখা রয়েছে:\n「নবজাত মিস আরাকনির প্রতি।」\n「আপনার বিশ্বস্ত বাটলার, এডগার।」"
  },
  Event_125719_Name = {
    Text = "শুভরাত্রি, মিস্টার এডগার"
  },
  Event_125720_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125720_Desc = {
    Text = "「তাই তো, আমি বুঝেছি, দিদি……」\n「নাট্যকার কখনোই চরিত্রের পরিণতি পুনর্লিখন করতে পারে না। সেই করুণ নিয়তি বহু আগেই নির্ধারিত হয়ে গেছে, এমনকি তুমিও কখনো তা বদলাতে পারোনি……」\nবিষাদের ফুঁপানি মিলিয়ে গেল। নাট্যকারের টাইপরাইটার একে একে প্রজাপতিতে রূপান্তরিত হয়ে শূন্য নিয়তির রঙ্গমঞ্চে ছড়িয়ে পড়ল, আর কোনো চিহ্ন রইল না।"
  },
  Event_125720_Name = {
    Text = "নাটকের সমাপ্তি"
  },
  Event_125721_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125721_Desc = {
    Text = "অপরিচিত অভিনেতা, বিপজ্জনক নৃত্যপদক্ষেপ……তাতে কী আসে যায়? নিয়তির চেয়ে খারাপ আর কিছু হতে পারে না।\nতুমি হাত বাড়িয়ে মঞ্চে পা রাখলে। পুতুলটি তোমার হাত ধরে আনন্দে নাচতে শুরু করল।\nতুমি করতালির শব্দ শুনতে পেলে।"
  },
  Event_125721_Name = {
    Text = "তিন জনের নৃত্য"
  },
  Event_125722_ChoiceDesc1 = {
    Text = "[Listen to the Singing] 25টি কালো চিহ্ন অর্জন করো, তবে 「(Skill.Arg2)」 উন্নয়ন করো, নির্বাচন চালিয়ে যাও"
  },
  Event_125722_ChoiceDesc2 = {
    Text = "[Ignore It] ত্যাগ করুন"
