  Event_125722_Desc = {
    Text = "「তারা নাচে। তারা গান গায়। কিচির—কিচির—」"
  },
  Event_125722_Name = {
    Text = "শেষ ভবিষ্যদ্বাণী"
  },
  Event_125723_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125723_Desc = {
    Text = "পথপ্রদর্শক, যুদ্ধসঙ্গী, এই নিঃসঙ্গ মাত্রায় একমাত্র সাথী।\nতোমরা একসাথে এখানকার সবকিছু সমাধান করবে, কাদাসে ফিরে যাবে। তুমি কখনো এই বিষয়ে সন্দেহ করোনি।"
  },
  Event_125723_Name = {
    Text = "মদের প্রতিবিম্ব"
  },
  Event_125724_ChoiceDesc1 = {
