  },
  Event_125724_ChoiceDesc2 = {
    Text = "[Forget It] 25টি কালো চিহ্ন সংগ্রহ করো"
  },
  Event_125724_Desc = {
    Text = "গলির মোড়ে, একজোড়া নোংরা হাত তোমাকে থামিয়ে দিল।\nজীর্ণ পোশাকের এক ভিখারি চুপিসারে তোমার কাছে এগিয়ে এল, তার চোখে পচা মাংস দেখা হায়েনার মতো লোভ।\n「এসো! একটা বাজি ধরো! তুমি যা জানতে চাও সব বলে দেব! শুধু তোমাকে জিততে হবে……」"
  },
  Event_125724_Name = {
    Text = "রাস্তার জুয়া"
  },
  Event_125725_ChoiceDesc1 = {
    Text = "[উপেক্ষা]1টি কমান্ড কার্ড মুছে ফেলুন, 25 কালো সিল অর্জন করুন"
  },
  Event_125725_ChoiceDesc2 = {
    Text = "[পড়ুন]ডেক থেকে একটি কার্ডের অনুলিপি তৈরি করুন, 「(Skill.Arg1)「 সংক্রমিত হন"
  },
  Event_125725_Desc = {
    Text = "টক টক টক, টক টক টক……\nবারের কোণটি জনশূন্য, টেলিপ্রিন্টার মিষ্টি সুরে বেজে চলেছে, যেন একটি সুমধুর পিয়ানো সঙ্গীত।"
  },
  Event_125725_Name = {
    Text = "ডাইমেনশন টেলিগ্রাম"
  },
  Event_125726_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125726_Desc = {
    Text = "「চুপ করো, আমি একটা বিড়াল, তোমাদের সেসব বোকা গল্প শুনতে চাই না।」\nকালো বিড়ালটা দীর্ঘশ্বাস ফেলে পেছন ফিরল।\n「এখান থেকে চলে যাও। পরের বার আর এরকম বোকামি করো না।」"
  },
  Event_125726_Name = {
    Text = "রূপান্তর পরিবর্তন"
  },
  Event_125727_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125727_Desc = {
    Text = "সে যা বলেছে হয়তো ভুল নয়, সেটাই তুমি, তোমার অন্তরের গভীরতম অন্ধকার ও কলুষিত চিন্তা।\nপ্রতিটি মানুষই স্বার্থপর, তুমি কখনোই অন্যরা যেমন ভাবে তেমন মহৎ ছিলে না।\nতুমি সেই হীন যন্ত্রণার স্বাদ গ্রহণ করছ। তুমি জানো যা অতীত তা অতীতেই রয়ে গেছে, আর তোমার মুক্তি সামনেই অপেক্ষা করছে।"
  },
  Event_125727_Name = {
    Text = "যন্ত্রণার বিস্তার"
  },
  Event_125728_ChoiceDesc1 = {
    Text = "[তার সাথে আলোচনা করুন]1টি কমান্ড কার্ড মুছুন, Arg1 কালো সীল অর্জন করুন"
  },
  Event_125728_ChoiceDesc2 = {
    Text = "[নীরব থাকুন]"
  },
  Event_125728_Desc = {
    Text = "「মহিমান্বিত পরিণতি কতটা বাস্তবসম্মত, কিন্তু আমাদের বাস্তবতা ইতিমধ্যেই এতটা করুণ, তাহলে কি গল্পের মধ্যেও আমরা তাকে একটি সুন্দর আশ্রয় দিতে পারি না……」\nনাট্যকার চোখ বন্ধ করে গভীর চিন্তায় মগ্ন হলেন। তিনি এই পরিণতিতে সন্তুষ্ট ছিলেন না।"
  },
  Event_125728_Name = {
    Text = "নাটকের সমাপ্তি"
  },
  Event_125729_ChoiceDesc1 = {
    Text = "[Leave] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_125729_Desc = {
    Text = "গড়গড়, পাশা পাশার পাত্রের ভেতরে উত্তেজিতভাবে নাচছে, ক্লান্ত না হওয়া পর্যন্ত নাচতেই থাকে।\n\n「কেন……কেন কেউ কখনো জিততে পারে না!……」"
  },
  Event_125729_Name = {
    Text = "রাস্তার জুয়া"
  },
  Event_125730_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125730_Desc = {
    Text = "তুমি যতটা সম্ভব এর কাছে গেলে, মনোযোগ দিয়ে এর কথা শুনতে চেষ্টা করলে।\nপ্রজাপতিটি ডানা ঝাপটে তোমার হাতের তালু থেকে উড়ে গেল।\nতুমি কিছুই শুনতে পেলে না।"
  },
  Event_125730_Name = {
    Text = "প্রজাপতির ছোট্ট বিশ্রাম"
  },
  Event_125731_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125731_Desc = {
    Text = "তোমার তাড়ানোর চেষ্টায় প্রজাপতিটি বিন্দুমাত্র বিচলিত হলো না।\nএটি একগুঁয়েভাবে তোমার হাতের তালু অনুসরণ করতে থাকল, শেষবারের মতো তুমি যখন হাত নাড়ালে, তখন অবশেষে সে চলে যাওয়ার সিদ্ধান্ত নিল।\nতোমার মনে একটু আফসোস হলো। হয়তো, তোমার উচিত ছিল ওর কথা শোনা?"
  },
  Event_125731_Name = {
    Text = "প্রজাপতির ছোট্ট বিশ্রাম"
  },
  Event_125732_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125732_Desc = {
    Text = "কালো ধোঁয়া হতাশভাবে কাঁপছে, ভিখারির যন্ত্রণাদায়ক কান্না ক্রমশ ক্ষীণ হয়ে আসছে।\nএকবার চোখের পলক ফেলতেই পাশা আর ভিখারি দুজনেই অদৃশ্য হয়ে গেল। জীর্ণ টুপির মধ্যে, খেলার পুরস্কার রেখে গেছে।"
  },
  Event_125732_Name = {
    Text = "রাস্তার জুয়া"
  },
  Event_125733_ChoiceDesc1 = {
    Text = "[উৎসবে যোগ দিন]「(Skill.Arg1)」 সংক্রমিত হন, অভিশপ্ত সৃষ্টি পান-「(RelicConfig.Arg2)」"
  },
  Event_125733_ChoiceDesc2 = {
    Text = "[সঙ্গীত বন্ধ করুন]1টি সৃষ্টি ধ্বংস করুন, 1টি পুরস্কার পান"
  },
  Event_125733_ChoiceDesc3 = {
    Text = "[কান চেপে ধরুন]50 কালো চিহ্ন পান"
  },
  Event_125733_Desc = {
    Text = "「আহ! সংগীত! একটি মহান নাটকে সংগীত ছাড়া কীভাবে চলে!!」\nবিসঙ্গত সুরের ঝংকার ভেঙে পড়া থিয়েটারে প্রতিধ্বনিত হয়, যেন এক বিশৃঙ্খল উৎসব। অতল নরক থেকে আসা অভিনেতারা এই অরাজক স্তুতিগানে নৃত্য করে, উল্লাস করে — এই সুরই তাদের বেঁচে থাকার অবলম্বন।"
  },
  Event_125733_Name = {
    Text = "ভাগ্যের স্তুতিগান"
  },
  Event_125734_ChoiceDesc1 = {
    Text = "[Tune] 100টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_125734_ChoiceDesc2 = {
    Text = "[এলোমেলো 2টি কমান্ড কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg1)」]"
  },
  Event_125734_Desc = {
    Text = "অদৃশ্য ভাগ্যের সুতো সুরের মাঝে নৃত্য করে, সেই বিশৃঙ্খল শব্দের ভিড়ে তুমি ধীরে ধীরে সেই মোহনীয় সুরটি ধরতে পারলে——হ্যাঁ, এটাই ভাগ্যের প্রকৃত ধ্বনি।\nঅতল গহ্বরের পরিত্যক্তরা তোমাকে উল্লাসে বরণ করে, তারা তোমাকে ঘিরে ধরে তাদের বিশৃঙ্খল উৎসবে নিয়ে যায়।\nঅভিনন্দন, ভাগ্যবান দর্শক! এখন, তুমি অভিনেতাদের সাথে মিলে ভাগ্যের কাছে বিদায় অভিবাদন জানাবে।"
  },
  Event_125734_Name = {
    Text = "ভাগ্যের স্তুতিগান"
  },
  Event_125735_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125735_Desc = {
    Text = "তুমি এই শব্দের অর্থ বুঝতে পারো না, কিন্তু তুমি জানো, এটাকে থামতে হবে।\nরূপালী আলো উন্মত্ত ধারালো ফলার মতো ঝলসে ওঠে, সেই ছন্দ যেন সুরের সাথে অদ্ভুতভাবে মিলে যায়।\nযখন তুমি সম্বিত ফিরে পাও, সুর কখন থেমে গেছে তা তুমি জানোই না। তুমি আর কোনো শব্দ শুনতে পাও না। তুমি শুধু রাতের অন্ধকার দেখো, শুধু নীরবতা শোনো।\nবিশৃঙ্খল কোলাহল আর পরম নীরবতা — কোনটি বেশি ভয়ংকর... গোপনরক্ষক?"
  },
  Event_125735_Name = {
    Text = "ভাগ্যের স্তুতিগান"
  },
  Event_125736_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125736_Desc = {
    Text = "তুমি হাত বাড়িয়ে দিলে, একটি প্রজাপতি আলতো করে তোমার হাতে এসে বসল।\nহ্যাঁ, ঠিক তাই। মৃত্যু, বিলীন হওয়া, ক্ষয়ে যাওয়া... প্রজাপতি গুটির মধ্য থেকে জন্ম নেয়, যন্ত্রণাই শিল্পের চিরন্তন উর্বর মাটি।\nএকজন প্রকৃত দর্শক হিসেবে, এটাই সেই সত্য যা তোমাকে অবশ্যই উপলব্ধি করতে হবে।"
  },
  Event_125736_Name = {
    Text = "বিলীনের মাঝে প্রস্ফুটিত"
  },
  Event_125737_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125737_Desc = {
    Text = "এটা হয়তো নেফরিয়ার আরেকটা চাল।\nপ্রজাপতি তোমার কথা বুঝতে পেরেছে, অন্ধকারে তার নীরব দীর্ঘশ্বাস প্রতিধ্বনিত হলো। কালো আঠালো তরলে ভেজা ডানা কেঁপে উঠল, এবং শীঘ্রই, প্রজাপতির ভারী ছায়া অসীম অন্ধকারে হারিয়ে গেল।\nসে তোমাকে কী জানাতে চেয়েছিল, তা তুমি আর কখনো জানতে পারবে না।"
  },
  Event_125737_Name = {
    Text = "প্রজাপতির অবশিষ্ট জীবন"
  },
  Event_125738_ChoiceDesc1 = {
