  },
  Event_125738_Name = {
    Text = "রাস্তার জুয়া"
  },
  Event_125739_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125739_Desc = {
    Text = "এখন চিন্তাগুলোকে এলোমেলোভাবে ভেসে উঠতে দেওয়া বিপজ্জনক। তুমি মাথা নাড়লে এবং তাড়াতাড়ি জলের উপরিভাগে ভেসে উঠলে……"
  },
  Event_125739_Name = {
    Text = "নির্বিকার"
  },
  Event_125740_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125740_Desc = {
    Text = "সব সুরের জন্য শ্রোতার প্রয়োজন হয় না, সব নিয়তির জন্য উত্তরের প্রয়োজন হয় না।\nতুমি দু'হাতে কান চেপে ধরে এই কোলাহলপূর্ণ মঞ্চ ছেড়ে চলে গেলে।\nসেই বেসুরো সঙ্গীতের অর্থ নিয়ে তোমার কৌতূহল এখনও থাকবে, কিন্তু তুমি জানো, তুমি একমাত্র সঠিক সিদ্ধান্তটিই নিয়েছ।"
  },
  Event_125740_Name = {
    Text = "ভাগ্যের স্তুতিগান"
  },
  Event_125741_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125741_Desc = {
    Text = "রূপালি আলো মায়া ভেদ করে, কালো বিড়ালগুলো কালো আঠালো তরলে পরিণত হয়।\nকালো বিড়ালের রূপ ধরে লুকানোর চেষ্টা করলেও তোমার চোখ এড়ানো সম্ভব নয়।"
  },
  Event_125741_Name = {
    Text = "রূপান্তর পরিবর্তন"
  },
  Event_125742_ChoiceDesc1 = {
    Text = "[ভাগ্য মেনে নিন]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে মুদ্রাঙ্কন অর্জন করুন: 「(EnchantConfig.Arg1)」"
  },
  Event_125742_Desc = {
    Text = "「কেউ সত্যিকার অর্থে ভাগ্যকে প্রতিরোধ করতে পারে না, প্রিয়। আমাদের কখনোই বেছে নেওয়ার অধিকার ছিল না।」\nনারীকণ্ঠটি হতাশ ও সুদূর হয়ে ওঠে। তুমি নিশ্চিত নও, সে তোমার সাথে কথা বলতে চাইছে, নাকি অন্য কোনো কিছুর সাথে।"
  },
  Event_125742_Name = {
    Text = "নিয়তির বন্দিশালা"
  },
  Event_125743_ChoiceDesc1 = {
