  },
  Event_125743_ChoiceDesc2 = {
    Text = "[Ignore It] ত্যাগ করুন"
  },
  Event_125743_Desc = {
    Text = "「পুতুলেরা সারিবদ্ধ হয়ে প্রবেশ করে, নিয়তির বিশাল জালে পা রাখে।」"
  },
  Event_125743_Name = {
    Text = "শেষ ভবিষ্যদ্বাণী"
  },
  Event_125744_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125744_Desc = {
    Text = "তুমি মাথা তুলে সেই ঘূর্ণিস্রোতের মতো অতল গহ্বরের দিকে তাকালে, কাকের ঝাঁকের দৈববাণী শোনার চেষ্টা করলে।\nকিন্তু কাকের ঝাঁক কিছুই বলল না। তোমার দৃষ্টির নিচে, গহ্বর মিলিয়ে গেল।\nকাকের ঝাঁক মঞ্চের শেষ প্রান্তে অদৃশ্য হয়ে গেল, সেই জায়গায় যেখানে তুমি যেতে চলেছ।"
  },
  Event_125744_Name = {
    Text = "কাকের অতল গহ্বর"
  },
  Event_125745_ChoiceDesc1 = {
    Text = "[প্রজাপতিকে সমর্থন করুন]2টি কার্ড মুছে ফেলুন"
  },
  Event_125745_ChoiceDesc2 = {
    Text = "[প্রজাপতির বিরোধিতা]অভিশপ্ত সৃষ্টি রেলিক「(RelicConfig.Arg1)」পান, 「(Skill.Arg2)」সংক্রমিত হন"
  },
  Event_125745_ChoiceDesc3 = {
    Text = "[Leave] Arg1টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_125745_Desc = {
    Text = "মঞ্চের পর্দা বাতাসে দুলছে। মৃতদেহ থেকে ঝরে পড়া কালো আঠালো তরলের মধ্যে তুমি একঝাঁক প্রজাপতি দেখতে পাও।\n「প্রকৃত শিল্প সর্বদা বিলীন হওয়ার মধ্যেই প্রস্ফুটিত হয়…… তাই না, রহস্যরক্ষক?」\nনর্তকীর মৃতদেহটি তোমার দিকে তাকিয়ে হাসছে। তুমি প্রজাপতির ডানা ঝাপটানোর শব্দ শুনতে পাও।"
  },
  Event_125745_Name = {
    Text = "বিলীনের মাঝে প্রস্ফুটিত"
  },
  Event_125746_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125746_Desc = {
    Text = "কুতর্ক কখনোই তোমাকে বিভ্রান্ত করতে পারে না, তুমি স্পষ্টভাবে জানো তুমি কোন পথে হাঁটছো, জানো তোমার গন্তব্য কোথায়।\nকণ্টক তোমার দেহ থেকে বিলীন হয়ে যায়। তুমি পথে পা বাড়াও, আগের মতোই।"
  },
  Event_125746_Name = {
    Text = "যন্ত্রণার বিস্তার"
  },
  Event_125747_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125747_Desc = {
    Text = "তুমি পিছন ফিরে দাঁড়ালে, পেছনের সেই চোখগুলোকে ভুলে যাওয়ার চেষ্টা করলে। কিন্তু তুমি বুঝতে পারলে, তোমার শরীর আর আগের মতো নিয়ন্ত্রণ করা যাচ্ছে না।\nতুমি জানো, সেই স্থির দৃষ্টি থেকে তুমি কখনোই পালাতে পারবে না।"
  },
  Event_125747_Name = {
    Text = "দর্শক"
  },
  Event_125748_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125748_Desc = {
    Text = "সম্মান হোক বা ভয়, আপনি সহজে স্পর্শ করতে চাননি, খামটি যথাস্থানে রেখে দিলেন। আপনি চলে যেতে উদ্যত হলে, খামের পেছনের অন্ধকার থেকে একটি ঘোলাটে কিন্তু কোমল কণ্ঠস্বর ভেসে এলো।\n「আপনি আমাকে এখনও মনে রেখেছেন, ধন্যবাদ, মিস আরাকনে……」"
  },
  Event_125748_Name = {
    Text = "শুভরাত্রি, মিস্টার এডগার"
  },
  Event_125749_ChoiceDesc1 = {
    Text = "[রক্ষার শক্তি]রৌপ্য সৃষ্টি রেলিক অর্জন করুন「(RelicConfig.Arg1)」"
  },
  Event_125749_ChoiceDesc2 = {
    Text = "[পলায়নের স্বাধীনতা]এলোমেলো 1টি কার্ড খোদাই লাভ করে: 「(EnchantConfig.Arg1)」"
  },
  Event_125749_ChoiceDesc3 = {
    Text = "[উত্তর দিতে অস্বীকার]50 কালো মোহর অর্জন করুন"
  },
  Event_125749_Desc = {
    Text = "মিডনাইট মাস্কের মদ তোমার মাথায় হামাগুড়ি দিয়ে ওঠে, শিকলের মতো তোমাকে বেঁধে ফেলে। সেই ঠান্ডা শিকলের ধারা বেয়ে, এক তরুণীর কণ্ঠস্বর তোমার মনে প্রতিধ্বনিত হয়।\n「বলো আমাকে, প্রিয়। তুমি যে ভাগ্য চাও, সেটা আসলে কী?」"
  },
  Event_125749_Name = {
    Text = "ভাগ্যের তালা"
  },
  Event_125750_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125750_Desc = {
    Text = "যতই জটিল বিষয় হোক না কেন, তোমাদেরকেই তা সমাধান করতে হবে।\nক্রমবর্ধমান ভারের অনুভূতির পাশাপাশি, তুমি এক নতুন শক্তিও অনুভব করলে।"
  },
  Event_125750_Name = {
    Text = "নির্বিকার"
  },
  Event_125751_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125751_Desc = {
    Text = "অপরিচিত অভিনেতা, বিপজ্জনক নৃত্যের পদক্ষেপ। হ্যাঁ, পালিয়ে যাওয়াই সবচেয়ে নিরাপদ।\nতুমি ঘুরে দৌড়াতে শুরু করলে, থিয়েটারের পর্দা সরিয়ে দিলে, তারপর দেখলে তুমি মঞ্চের উপর দাঁড়িয়ে আছ। পুতুলগুলো তোমার হাত ধরে আনন্দে নাচতে শুরু করল।\nভাগ্যের মঞ্চে কখনো কোনো পছন্দ থাকে না।"
  },
  Event_125751_Name = {
    Text = "তিন জনের নৃত্য"
  },
  Event_125752_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125752_Desc = {
    Text = "এখন সিনেমা দেখার সময় নয়।"
  },
  Event_125752_Name = {
    Text = "স্মৃতি প্রেক্ষাগৃহ"
  },
  Event_125753_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125753_Desc = {
    Text = "পথের বিপদ তোমার মনে সামান্যতম প্রভাবও ফেলেনি। তুমি পাশে ধ্বংসপ্রাপ্ত নিয়তির পাশ দিয়ে হেঁটে নেফরিয়ার দিকে এগিয়ে যাচ্ছ।\nতুমি এখানে এসেছ তাকে মুক্তি দিতে।"
  },
  Event_125753_Name = {
    Text = "ভাগ্যের জালের পরিসমাপ্তি"
  },
  Event_125754_ChoiceDesc1 = {
    Text = "[চিঠি পড়ুন]সোনালি রেলিক 「(RelicConfig.Arg1)「 অর্জন করুন, 「(Skill.Arg2)「 সংক্রমিত হন"
  },
  Event_125754_ChoiceDesc2 = {
    Text = "[চিঠি পড়ুন]3টি নির্দেশ কার্ড থেকে 1টি বেছে নিয়ে এনগ্রেভিং অর্জন করুন: 「(EnchantConfig.Arg1)」"
  },
  Event_125754_ChoiceDesc3 = {
    Text = "[Put it back] ৫০টি কালো মুদ্রা অর্জন করো"
  },
  Event_125754_Desc = {
    Text = "তোমাদের নড়াচড়ায় ঘন মাকড়সার জাল ছিঁড়ে যায়, এবং জালের মধ্য থেকে একটি পুরনো চিঠি পড়ে যায়।\nএর ভার পাতলা কাগজের চেয়ে অনেক বেশি ভারী।"
  },
  Event_125754_Name = {
    Text = "শুভরাত্রি, মিস্টার এডগার"
  },
  Event_125755_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125755_Desc = {
    Text = "কাকের চোখ থেকে অশ্রু ঝরে পড়ে। কাকের ঠোঁটের কোণ থেকে রক্ত গড়িয়ে পড়ে। কাক তার সমস্ত জীবনশক্তি ব্যয় করে, তোমার জন্য গেয়ে যায় তার শেষ ভবিষ্যদ্বাণী।"
  },
  Event_125755_Name = {
    Text = "শেষ ভবিষ্যদ্বাণী"
  },
  Event_125756_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125756_Desc = {
    Text = "「হেহে……হাহাহাহা!」\n「কেমন লাগলো, আমার অতিথি? ভাগ্যের এই স্বাদ, তুমি পাগলের মতো মনে করবে……」"
  },
  Event_125756_Name = {
    Text = "ভাগ্যের স্বাদ"
  },
  Event_125757_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125757_Desc = {
    Text = "「বিরক্তিকর।」একটি নারী কণ্ঠ অলসভাবে হাই তুলল।\n「তোমার শক্তি নিয়ে ক্লাবে যাও এবং লড়াইয়ে অংশ নাও।」"
  },
  Event_125757_Name = {
    Text = "ভাগ্যের তালা"
  },
  Event_125758_ChoiceDesc1 = {
    Text = "[ভাগ্যের জাল স্থিতিশীল করুন]3টি থেকে 1টি উন্নত মুদ্রাঙ্কন নির্বাচন করুন"
  },
  Event_125758_ChoiceDesc2 = {
    Text = "[বিপদ উপেক্ষা করুন]সোনালী সৃষ্টি রেলিক 「(RelicConfig.Arg1)「 অর্জন করুন, 「(Skill.Arg2)「 সংক্রমিত হন"
  },
  Event_125758_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_125758_Desc = {
    Text = "সে সৌন্দর্যের আদরের সন্তান। সে ভাগ্যের পরিত্যক্ত শিশু। সে অন্ধকারের মাঝে ক্ষীণ আলোর বিন্দু অনুসরণ করে অতল গহ্বর থেকে উঠে আসা এক প্রতিশোধকারী। সে এখানে এসেছে, সবকিছুকে মুক্তি দিতে।\nভাগ্যের জাল তোমাদের চারপাশে ভেঙে পড়ছে। তুমি থিয়েটারের মঞ্চে দাঁড়িয়ে আছ, নেফরিয়ার সাথে খুব বেশি দূরত্ব নেই।"
  },
  Event_125758_Name = {
    Text = "ভাগ্যের জালের পরিসমাপ্তি"
  },
  Event_125759_ChoiceDesc1 = {
    Text = "[বুঝতে না পেরে]সিলভার রেলিক「(RelicConfig.Arg1)」অর্জন করুন"
  },
  Event_125759_ChoiceDesc2 = {
    Text = "[সহানুভূতি]স্বর্ণ সৃষ্টি রেলিক「(RelicConfig.Arg1)」অর্জন করুন,「(Skill.Arg2)」সংক্রমিত হন"
  },
  Event_125759_Desc = {
    Text = "মঞ্চ থেকে ভেসে আসছে হৃদয়বিদারক কান্না ও আর্তনাদ, একমাত্র আলোর রশ্মি পড়েছে একটি নিঃসঙ্গ ছায়ামূর্তির উপর।\nসে তোমার জন্য তার সবচেয়ে আন্তরিক অভিনয় উৎসর্গ করছে——নিজের অন্তরাত্মা উন্মোচন করে প্রতিটি দর্শকের সামনে তুলে ধরছে।\nকী এমন যন্ত্রণা বহন করছে এই চরিত্রটি?"
  },
  Event_125759_Name = {
    Text = "অভিনেতার অন্তর্কথা"
  },
  Event_125760_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125760_Desc = {
    Text = "তোমার হাত ডানদিকে প্রসারিত হয়।\nসেটাই তোমার ভবিষ্যৎ, তোমার সবচেয়ে তীব্র আকাঙ্ক্ষা, তোমার গন্তব্য, যেখানে তুমি পৌঁছাবে।\nতোমার অস্তিত্ব, সামনের সূর্যকে তাড়া করার জন্যই।"
  },
  Event_125760_Name = {
    Text = "অতীত, ভবিষ্যৎ"
  },
  Event_125761_ChoiceDesc1 = {
    Text = "[Three Points]"
  },
  Event_125761_ChoiceDesc2 = {
    Text = "[Six Points]"
  },
  Event_125761_ChoiceDesc3 = {
    Text = "[One Point]"
  },
  Event_125761_Desc = {
    Text = "তুমি অবশ্যই সরাসরি চলে যেতে পারো, কিন্তু সেই নিপুণভাবে তৈরি পাশাটি তোমাকে সম্পূর্ণরূপে মুগ্ধ করেছে।\nতুমি পেছনের তাড়াকারীদের কথা ভুলে গিয়ে, শ্রদ্ধাভরে এটি তুলে নিলে এবং টুপির মধ্যে ছুড়ে দিলে——"
  },
  Event_125761_Name = {
    Text = "রাস্তার জুয়া"
  },
  Event_125762_ChoiceDesc1 = {
