  },
  Event_125762_Desc = {
    Text = "গড়গড়, পাশা পাশার পাত্রের ভেতরে উত্তেজিতভাবে নাচছে, ক্লান্ত না হওয়া পর্যন্ত নাচতেই থাকে।\n\n「কেন……কেন কেউ কখনো জিততে পারে না!……」"
  },
  Event_125762_Name = {
