  },
  Event_125763_ChoiceDesc2 = {
    Text = "[ভাগ্যের বিরুদ্ধে প্রতিরোধ]「(Skill.Arg1)「 সংক্রমিত হন, পুনরায় এলোমেলোভাবে খোদাই করুন"
  },
  Event_125763_Desc = {
    Text = "「আহ, দুষ্টু ছেলে। ভাগ্য সর্বদা দয়ালু……কিন্তু সকল বিদ্রোহের একটা মূল্য আছে। এখন, তুমি কি তা মেনে নিতে রাজি?」"
  },
  Event_125763_Name = {
    Text = "নিয়তির বন্দিশালা"
  },
  Event_125764_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125764_Desc = {
    Text = "তুমি সেই দৃষ্টিগুলোর দিকে তাকালে, তাদের উদ্দেশ্যে হাত নাড়লে।\nশীঘ্রই, তুমি তাদের গল্পের চরম মুহূর্তটি উপহার দেবে।"
  },
  Event_125764_Name = {
    Text = "দর্শক"
  },
  Event_125765_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125765_Desc = {
    Text = "「প্রিয় মিস আরাকনে, আজ আপনার জন্মদিন, আমি মালিক ও মালকিনের জন্য, এবং আপনার জন্যও আনন্দিত। এই সুন্দর পৃথিবীতে আপনাকে স্বাগতম। আমি এই কোমল ঘুমপাড়ানি গানটি আপনাকে উৎসর্গ করছি, আশা করি জন্মের এই দিন থেকে আপনি একটি উদ্বেগহীন জীবন কাটাবেন……」"
  },
  Event_125765_Name = {
    Text = "শুভরাত্রি, মিস্টার এডগার"
  },
  Event_125766_ChoiceDesc1 = {
    Text = "[ছবি তোলা]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে এনগ্রেভিং অর্জন করুন: 「(EnchantConfig.Arg1)」"
  },
  Event_125766_ChoiceDesc2 = {
    Text = "[পুনরায় পরিবর্তন]「(Skill.Arg1)」সংক্রমিত হন, বিকল্প 1-এ প্রাপ্ত মুদ্রাঙ্কন পরিবর্তন করুন, আরও একবার ব্যবহার করা যাবে"
  },
  Event_125766_Desc = {
    Text = "ক্যামেরার সামনে তুমি কিছুটা ভয় পাচ্ছ। হয়তো এই পোজে ছবি তুললে ভালো হবে? নাকি ওটা?"
  },
  Event_125766_Name = {
    Text = "দর্শক আসনের স্মৃতিচিত্র"
  },
  Event_125767_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125767_Desc = {
    Text = "আপনি এতে কী আছে দেখতে চাইলেন, কিন্তু পর্দায় কিছুই নেই, প্রেক্ষাগৃহে শুধু ফিল্ম ঘোরার শব্দ প্রতিধ্বনিত হচ্ছে।\nহয়তো অনেক পরে, আপনি ফিল্মের বিষয়বস্তু জানার সুযোগ পাবেন।"
  },
  Event_125767_Name = {
    Text = "স্মৃতি প্রেক্ষাগৃহ"
  },
  Event_125768_ChoiceDesc1 = {
    Text = "[Avoid Gaze] যেকোনো এক জন জাগরণকারীকে এলোমেলোভাবে জাগরণ ঘটাও"
  },
  Event_125768_ChoiceDesc2 = {
    Text = "[Stare] জাগরণ ঘটানোর জন্য একটি জাগরণকারী বেছে নাও, সেই কার্ডের অ্যারিথমেটিকা ব্যয় 2 কমাও, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_125768_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_125768_Desc = {
    Text = "মঞ্চে পা রাখতেই তুমি ফিসফিসানির শব্দ শুনতে পেলে। পেছনে ফিরে তাকালে—দশ হাজার দর্শকের চোখ মঞ্চের চারপাশে ভাসছে, তোমাকে একদৃষ্টে দেখছে।\nএসো! তারা বলল। এত চমৎকার নাটক, কি এখানেই থেমে যাবে?\nনাচো! তারা বলল। আমাদের জন্য এই নৃত্যের চরম মুহূর্তটি নিয়ে এসো!"
  },
  Event_125768_Name = {
    Text = "দর্শক"
  },
  Event_125769_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125769_Desc = {
    Text = "তুমি তার যন্ত্রণা বোঝো না, বোঝার প্রয়োজনও নেই।\nথিয়েটারে এত মঞ্চ, মঞ্চে এত পুতুল, তুমিও তাদের মধ্যে একজন মাত্র।\nতোমার আরও গুরুত্বপূর্ণ কাজ করার আছে।"
  },
  Event_125769_Name = {
    Text = "অভিনেতার অন্তর্কথা"
  },
  Event_125770_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125770_Desc = {
    Text = "মৃত্যু, বিলীন, ক্ষয়……শিল্প যন্ত্রণা দেওয়ার জন্য সৃষ্টি হয়নি। যদি সৌন্দর্য কেবল যন্ত্রণার মধ্যেই থাকে, তবে এমন সৌন্দর্যের প্রয়োজন নেই।\nতুমি প্রাণপণে তাদের তাড়িয়ে দিলে। প্রজাপতিরা ছড়িয়ে গেল, রেখে গেল একটি বিষাদময় মৃতদেহ।"
  },
  Event_125770_Name = {
    Text = "বিলীনের মাঝে প্রস্ফুটিত"
  },
  Event_125771_ChoiceDesc1 = {
    Text = "[Listen to the Singing] 40টি কালো চিহ্ন অর্জন করো, তবে 「(Skill.Arg2)」 উন্নয়ন করো, নির্বাচন চালিয়ে যাও"
  },
  Event_125771_ChoiceDesc2 = {
    Text = "[Ignore It] 25টি কালো চিহ্ন সংগ্রহ করে চলে যাও।"
  },
  Event_125771_Desc = {
    Text = "একসময় তোমার সাথে দেখা হওয়া কাকের ঝাঁক একত্রিত হয়ে একটি মাত্র কাকে পরিণত হয়েছে। সে তোমার সামনে দাঁড়িয়ে গান গাইছে, সেই গান বিষাদময়, যেন শেষ ভবিষ্যদ্বাণী।"
  },
  Event_125771_Name = {
    Text = "শেষ ভবিষ্যদ্বাণী"
  },
  Event_125772_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125772_Desc = {
    Text = "তোমার হাত বাম দিকে প্রসারিত হয়।\nসেটা তোমার অতীত, তোমার সবচেয়ে মূল্যবান স্মৃতি, যে পথে তুমি এসেছিলে, যেখানে তুমি ফিরে যাবে।\nঅতীতের সবকিছুই তোমার সমগ্র সত্তা গড়ে তুলেছে।"
  },
  Event_125772_Name = {
    Text = "অতীত, ভবিষ্যৎ"
  },
  Event_125773_ChoiceDesc1 = {
    Text = "[ছবি তোলা]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে এনগ্রেভিং অর্জন করুন: 「(EnchantConfig.Arg1)」"
  },
  Event_125773_Desc = {
    Text = "ক্যামেরার সামনে তুমি কিছুটা ভয় পাচ্ছ। হয়তো এই পোজে ছবি তুললে ভালো হবে? নাকি ওটা?\nতুমি এখনো দ্বিধায় আছ, কিন্তু তুমি বুঝতে পারছ, ক্যামেরা ইতিমধ্যেই বেশ অধৈর্য হয়ে উঠেছে।"
  },
  Event_125773_Name = {
    Text = "দর্শক আসনের স্মৃতিচিত্র"
  },
  Event_125774_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125774_Desc = {
    Text = "তুমি ভঙ্গি ঠিক করে ক্যামেরার সামনে দাঁড়ালে। সোজা, কৌতূহলী, মনোযোগী, যেন একজন সত্যিকারের দর্শক।\nগুড়গুড়——\nক্যামেরা শাটার চাপল, কালো আঠালো তরল যন্ত্রের ভেতর থেকে বিস্ফোরিত হয়ে পুরো মঞ্চে ছিটকে পড়ল।\nক্যামেরার মৃতদেহের মাঝখানে, ফিল্মে কিছুই নেই।"
  },
  Event_125774_Name = {
    Text = "দর্শক আসনের স্মৃতিচিত্র"
  },
  Event_125775_ChoiceDesc1 = {
    Text = "[গ্রহণ করুন]3টি থেকে 1টি সিলভার সৃষ্টি নির্বাচন করুন"
  },
  Event_125775_ChoiceDesc2 = {
    Text = "[পলায়ন]রৌপ্য সৃষ্টি রেলিক「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」 অর্জন করুন, দুইবার「(Skill.Arg3)」 সংক্রমিত হন"
  },
  Event_125775_Desc = {
    Text = "ঠক ঠক, ঠক ঠক…… জুতোর হিল কাঠের মেঝেতে ঠোকর খেয়ে আনন্দময় খটখট শব্দ তুলছে।\nস্কুলের ইউনিফর্ম পরা দুটি পুতুল মঞ্চের উপর নাচছে। হঠাৎ, তারা নাচ থামিয়ে ঘুরে দাঁড়াল এবং তোমার দিকে হাত বাড়িয়ে দিল।"
  },
  Event_125775_Name = {
    Text = "তিন জনের নৃত্য"
  },
  Event_125776_ChoiceDesc1 = {
    Text = "[যন্ত্রণা সহ্য করুন]সর্বোচ্চ জীবনী Arg1 পয়েন্ট বৃদ্ধি করুন"
  },
  Event_125776_ChoiceDesc2 = {
    Text = "[যন্ত্রণার প্রতিবাদ করো]এলোমেলোভাবে 1টি কমান্ড কার্ড অরিসন পায়：「(EnchantConfig.Arg1)」，1টি「(Skill.Arg2)」সংক্রমিত করো"
  },
  Event_125776_Desc = {
    Text = "「তুমি কখনো লিজের মৃত্যুর পরোয়া করোনি। তুমি কখনো কারো পরোয়া করোনি।」\n「তুমি শুধু নিজেকে নিয়েই ভাবো……তোমার চারপাশের সবাই শুধু তোমার স্বাধীনতা আর শান্তির পথে ব্যবহৃত হাতিয়ার মাত্র।」\n「তাই না……গোপনরক্ষক?」\nঘোষিকার ফিসফিস তোমার কানে ভেসে আসে। তোমার হৃদয় মুচড়ে ওঠে, সংকুচিত হয়, তীব্র যন্ত্রণা তার কথার সাথে সাথে তোমার সারা শরীরে ছড়িয়ে পড়ে……"
  },
  Event_125776_Name = {
    Text = "যন্ত্রণার বিস্তার"
  },
  Event_125777_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125777_Desc = {
    Text = "চেতনার পতনকে মুক্ত করো, সমুদ্রের জলে নিজস্ব প্লবতা আছে, নিয়তি তোমাদের সামনে সকল পথ নির্দেশ করবে।"
  },
  Event_125777_Name = {
    Text = "নির্বিকার"
  },
  Event_125778_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125778_Desc = {
    Text = "সেটা তুমি নিজেই। শক্তির উৎস, দায়িত্বের বাহক, একমাত্র আনুগত্যের পাত্র।\nতুমি সেই পথে হাঁটছ যা কেবল তোমারই।"
  },
  Event_125778_Name = {
    Text = "মদের প্রতিবিম্ব"
  },
  Event_125779_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125779_Desc = {
    Text = "「সত্যিই দুঃখজনক, আমার অতিথি। ভাগ্যের স্বাদ, তোমার আর কখনো চাখার সুযোগ হবে না……」"
  },
  Event_125779_Name = {
    Text = "ভাগ্যের স্বাদ"
  },
  Event_125780_ChoiceDesc1 = {
    Text = "[তার সাথে আলোচনা করুন]1টি কমান্ড কার্ড মুছুন, Arg1 কালো সীল অর্জন করুন"
  },
  Event_125780_ChoiceDesc2 = {
    Text = "[নীরব থাকুন]"
  },
  Event_125780_Desc = {
    Text = "「এটা সত্যিই একটা দুঃখজনক নাটক……সেই হতভাগ্য মেয়েটি, যাকে সে ভালোবাসত তার দ্বারাই কি পরিত্যক্ত হয়েছে, দিদি?」\nএই পরিচিত কণ্ঠস্বরে, তুমি কোনো উন্মাদনা বা ঘৃণা শুনতে পাওনি। সেই কণ্ঠ স্বচ্ছ, বিষাদময়, যেন বনভূমির মধ্য দিয়ে বয়ে চলা এক কোমল ঝর্ণাধারা।\n「সেই গায়িকা, অসহায়ভাবে ভেসে বেড়ানো একটি শুকনো পাতা, শুধু নিয়তির নির্মমতা সহ্য করা ছাড়া আর কিছুই করতে পারে না……কী করুণ মানুষ……」\n「বলো তো, আমি যদি সেই লেখক হতাম……তাহলে তার জন্য কেমন পরিণতি লিখতাম?」"
  },
  Event_125780_Name = {
    Text = "নাটকের সমাপ্তি"
  },
  Event_125781_ChoiceDesc1 = {
    Text = "[স্পর্শ করুন]50% সম্ভাবনায় 125 কালো সিল পাবেন, 50% সম্ভাবনায় 「(Skill.Arg2)「 সংক্রমিত হবেন"
  },
  Event_125781_ChoiceDesc2 = {
    Text = "[ব্যাখ্যা]75% সম্ভাবনায় 100 কালো সীল পাওয়া যাবে, 25% সম্ভাবনায় 「(Skill.Arg2)「 সংক্রমিত হবে"
  },
  Event_125781_ChoiceDesc3 = {
    Text = "[ভেদ করুন]50 কালো সীল অর্জন করুন"
  },
  Event_125781_Desc = {
    Text = "তুমি বারের পেছনের গলিতে তাড়া করতে গেলে, দানবের ছায়া অদৃশ্য হয়ে গেল, আর একদল কালো বিড়াল তোমার সামনে এসে পথ আটকাল।\n「 হেই, তুমি।」 একটি কালো বিড়াল নিজের থাবা চেটে তোমার দিকে তাকাল।\n「 তুমি আমাদের এলাকায় কী করতে এসেছ?」"
  },
  Event_125781_Name = {
    Text = "রূপান্তর পরিবর্তন"
  },
  Event_125782_ChoiceDesc1 = {
    Text = "[অতীতকে আলিঙ্গন করুন]সোনালি সৃষ্টি রেলিক 「(RelicConfig.Arg1)「 অর্জন করুন, 「(Skill.Arg2)「 সংক্রমিত হন"
  },
  Event_125782_ChoiceDesc2 = {
    Text = "[ভবিষ্যৎকে স্বাগত জানাও]3টি থেকে 1টি সোনালি সৃষ্টি লাভ করুন, সংক্রমিত হন「(Skill.Arg1)」"
  },
  Event_125782_ChoiceDesc3 = {
    Text = "[Leave] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_125782_Desc = {
    Text = "নেফরিয়ার আবির্ভাব সুতোগুলোকে বিঘ্নিত করেছে। বিশৃঙ্খল ভাগ্যের মাঝে, তুমি দুটি অস্পষ্ট মায়ামূর্তি দেখতে পাও।\nওটা তোমার অতীত, ওটা তোমার ভবিষ্যৎ। তুমি তাদের দিকে এগিয়ে যাও, হাত বাড়িয়ে দাও……"
  },
  Event_125782_Name = {
    Text = "অতীত, ভবিষ্যৎ"
  },
  Event_125855_ChoiceDesc1 = {
    Text = "[উপলব্ধি]1টি সৃষ্টি বেছে নিন এবং সোনালি সৃষ্টি 「(RelicConfig.Arg1)「-তে রূপান্তর করুন"
  },
  Event_125855_ChoiceDesc2 = {
    Text = "[Stare] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_125855_ChoiceDesc3 = {
    Text = "[Ignore] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_125855_Desc = {
    Text = "কাসালিমের রাস্তায়, একটি ক্রিস্টাল দোকানের চোখ ধাঁধানো আলো তোমার দৃষ্টি আকর্ষণ করল। তুমি দোকানের সামনে এসে একটি সিলভার কোর আকৃতির ক্রিস্টাল তুলে নিলে।"
  },
  Event_125855_Name = {
    Text = "স্ফটিকের রহস্য"
  },
  Event_125856_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125856_Desc = {
    Text = "তুমি চোখ বন্ধ করলে, মনোযোগ দিয়ে এটিকে অনুভব করতে লাগলে।\nএকটি ক্ষীণ আলো তোমার চেতনায় মিটমিট করে জ্বলে উঠল, এটি তোমাকে কিছু বলতে চাইছে……"
  },
  Event_125856_Name = {
    Text = "স্ফটিকের রহস্য"
  },
  Event_125857_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125857_Desc = {
    Text = "ভাগ্যের বিরুদ্ধে যেকোনো প্রতিরোধ বা উঁকি দেওয়া বৃথা। তুমি নীরবে চোখ বন্ধ করলে, ভাগ্যকে তোমাকে সেখানে নিয়ে যেতে দিলে যেখানে তোমার যাওয়ার কথা।"
  },
  Event_125857_Name = {
    Text = "নিয়তির জাল"
  },
  Event_125858_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125858_Desc = {
    Text = "「আবেগই টিকে থাকার অর্থ। আশা করি তুমি তোমার পছন্দের জন্য অনুতাপ করবে না।」"
  },
  Event_125858_Name = {
    Text = "পছন্দের মূল্য"
  },
  Event_125859_ChoiceDesc1 = {
    Text = "[আবেগ]Arg1 পয়েন্ট জীবনী পুনরুদ্ধার করুন"
  },
  Event_125859_ChoiceDesc2 = {
    Text = "[বিচক্ষণতা]এলোমেলো 1টি কমান্ড কার্ড এনগ্রেভিং অর্জন করে: 「(EnchantConfig.Arg1)「"
  },
  Event_125859_ChoiceDesc3 = {
    Text = "[Refuse to Choose] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_125859_Desc = {
    Text = "একটি দাঁড়িপাল্লা মঞ্চে আবির্ভূত হয়।\n「মস্তিষ্ক ও হৃদয়, যুক্তি ও আবেগ, ধূসর ও লাল... আমরা পছন্দ থেকে পালাতে পারি না, এটাই আমাদের নিয়তি।」\n「মঞ্চের সমাপ্তি ইতিমধ্যে নির্ধারিত। এখন, এই মঞ্চের জন্য সেই পথ বেছে নাও যা সে অতিক্রম করবে।」"
  },
  Event_125859_Name = {
    Text = "পছন্দের মূল্য"
  },
  Event_125860_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125860_Desc = {
    Text = "「মাথা তুলো না। এখান থেকে চলে যাও।」\nতুমি নিয়তির কণ্ঠস্বর শুনতে পেলে। তুমি প্রচণ্ডভাবে আকাশের দিকে তাকাতে চাইছিলে, কিন্তু তুমি জানো, সে ঠিকই বলেছে।"
  },
  Event_125860_Name = {
    Text = "ঊর্ধ্বে তাকানো"
  },
  Event_125861_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125861_Desc = {
    Text = "তুমি কখনো ভাগ্যকে মেনে নাও না। তুমি কখনো বন্দিত্ব মেনে নাও না।\nতুমি প্রাণপণ লড়াই করো, একটি মথের অঙ্গ উৎসর্গ করার পর, অবশেষে তুমি পালাতে সক্ষম হও……"
  },
  Event_125861_Name = {
    Text = "নিয়তির জাল"
  },
  Event_125862_ChoiceDesc1 = {
    Text = "[বন্ধুত্ব]50টি কালো সীল পান"
  },
  Event_125862_ChoiceDesc2 = {
    Text = "[সাহায্য]75 কালো মুদ্রা অর্জন করুন, সংক্রমিত হন「(Skill.Arg2)」"
  },
  Event_125862_Desc = {
    Text = "বারের পেছনের গলিতে, তুমি আবার সেই কালো বিড়ালগুলোর সাথে দেখা হলো।\n「আমি শুনেছি। সেই কালো আঠালো তরল আমাদের রূপ ধারণ করে তোমাকে বেশ ঝামেলায় ফেলেছে।」\n「ক্ষতিপূরণ হিসেবে, আমাকে বলো, তুমি কী চাও?」\nকালো বিড়ালটি তোমার পায়ের চারপাশে দুবার ঘুরে মাথা তুলে তোমার দিকে তাকাল।"
  },
  Event_125862_Name = {
    Text = "প্রথম সাক্ষাতের উপহার"
  },
  Event_125863_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125863_Desc = {
    Text = "পাশবিক শক্তি দিয়ে ভাগ্যকে ভাঙা যায় না, কিন্তু হয়তো বুদ্ধি দিয়ে সম্ভব?\nতুমি মনোযোগ দিয়ে এই জালটি পর্যবেক্ষণ করছ, এর মধ্য থেকে ভাগ্যের কিছু গতিপথ উদ্ঘাটন করার চেষ্টা করছ……"
  },
  Event_125863_Name = {
    Text = "নিয়তির জাল"
  },
  Event_125864_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125864_Desc = {
    Text = "আপনি কাছে গেলেন, মনোযোগ দিয়ে এটির দিকে তাকালেন।\nএকটি ক্ষীণ আলো আপনার চোখে ঝলসে উঠল, এটি আপনাকে কিছু বলতে চাইছে……"
