  },
  Event_125865_Desc = {
    Text = "একটি পরিচিত অনুভূতি তোমাকে গ্রাস করে, তবে এবার ভিন্ন — সেই আঠালো স্পর্শ, প্রতিরোধে অক্ষমতার সহজাত বোধ, আগের বারের চেয়ে আরও তীব্র, আরও মারাত্মক।\nমথ মাকড়সার জালে আটকে পড়ে, আর তুমিও ইতিমধ্যে মঞ্চে পা রেখেছ।"
  },
