  },
  Event_125867_ChoiceDesc1 = {Text = "[Leave]"},
  Event_125867_Desc = {
    Text = "কৌতূহল জেগে উঠল। তুমি জনতার মাঝে এসে দাঁড়ালে, তাদের মতোই মাথা তুলে তাকালে।\nসেখানে কিছুই নেই, কিন্তু কেন জানি না, তুমি চোখ নামাতে চাইছ না। তুমি শুধু এভাবেই তাকিয়ে থাকতে চাও, চিরকাল তাকিয়ে থাকতে চাও……"
