  Event_129178_ChoiceDesc2 = {
    Text = "[একসাথে প্রার্থনা]3টি থেকে 1টি বেছে অরিসন দুইবার পান"
  },
  Event_129178_Desc = {
    Text = "অন্ধকারাচ্ছন্ন বাতাসে পিয়ানো আর অর্গানের সুর একে অন্যের সঙ্গে জড়িয়ে যায়। যেন জাদুময় সুর ভেসে বেড়াচ্ছে জনশূন্য রাস্তায়।\nএক নামহীন সন্ন্যাসিনী সেই সঙ্গীতের মাঝখানে প্রার্থনা করে।\n「সরল প্রার্থনার জন্য কোনো জাঁকজমকপূর্ণ আচার লাগে না। পিতৃদেব আমাদের জন্য আশা বপন করবেন, যেমন একদিন তিনি আমাদের ওপর বর্ষণ করেছিলেন তাঁর ভক্তিময় উপদেশ।」"
  },
  Event_129178_Name = {
