  },
  Event_129180_Desc = {
    Text = "কয়েকটি মোমের ভাস্কর্য ব্লক তোমার পথ রুদ্ধ করে রেখেছে。\nওগুলো বেঁকে গেছে আর খসখসে, রজার্সের কাছ থেকে যে ধরনের কারুকাজ আশা করা যায়, তার সঙ্গে একেবারেই মেলে না。\n「আদেশ… প্রভুর আদেশ…」"
