  },
  Event_129181_ChoiceDesc2 = {
    Text = "[অনুপ্রেরণার পিছু নাও]এলোমেলো 1টি কমান্ড কার্ড অরিসন পাও：「(EnchantConfig.Arg1)」দুইবার"
  },
  Event_129181_Desc = {
    Text = "বন্দরটি আক্রমণের মুখে, এক রহস্যময় মালবাহী জাহাজ আসা-যাওয়া করছে আর পাখনাওয়ালা ‘নতুন বন্ধু’রা ঘোরাফেরা করছে... এটি কি নিখুঁতভাবে প্রস্তুত করা ফাঁদ? নাকি আরেকটি অপ্রত্যাশিত বিপদসংকুল যাত্রা?\nবাস্তবতা ও যুক্তি একে অন্যকে টেনে মুচড়ে ধরছে, মনের গভীর থেকে অসংখ্য অনুপ্রেরণা ও চিন্তা উথলে উঠছে।"
  },
  Event_129181_Name = {
    Text = "অনুপ্রেরণার বিস্ফোরণ"
  },
  Event_129182_ChoiceDesc1 = {
