  Event_129186_ChoiceDesc1 = {
    Text = "[প초상화 উদ্ধার]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」দুইবার, সংক্রমিত করুন「(Skill.Arg2)」দুইবার"
  },
  Event_129186_ChoiceDesc2 = {
    Text = "[শূন্যতা গ্রহণ]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」দুইবার, সংক্রমিত করুন「(Skill.Arg2)」দুইবার"
  },
  Event_129186_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129186_Desc = {
    Text = "তুমি দাঁড়িয়ে আছ পিকম্যানের উপহারের সামনে。\nএটি রক্তে আঁকা এক প্রতিকৃতি, যার গাঢ় কালো শিখা নীরবে জ্বলছে。\nচিত্রের মানুষের ফাঁপা চোখের গহ্বর দিয়ে তুমি দেখতে পাও—\nনিজের স্মৃতিগুলো উথলে উঠছে আর জ্বলছে, প্রসারিত হচ্ছে, বিকৃত হচ্ছে, দীপ্ত হচ্ছে, যেন কোনো আকারহীন আগুন তোমার মনের করিডরগুলো চেটে বেড়াচ্ছে। বিভোরতার মধ্যে তুমি একটি কণ্ঠস্বর শোনো。\n「রান্না শুরু করার সময় হয়েছে। আঁচ এখন একদম ঠিক।」\nএটাই তোমার নিজ হাতে নির্মিত স্মৃতির দৃশ্য—তুমি শিখার ভেতর পেঁচিয়ে ওঠো, মোচড়াও।"
  },
  Event_129186_Name = {
    Text = "জ্বলন্ত প্রতিকৃতি"
  },
  Event_129187_ChoiceDesc1 = {
    Text = "[আপনি কী মূল্য দিতে রাজি？]এলোমেলোভাবে 1টি কার্ডের অরিসন মান দুইবার উন্নত করুন"
  },
  Event_129187_ChoiceDesc2 = {
    Text = "[তাদের একটি মেয়াদোত্তীর্ণ ব্লাডি মেরি পান করতে দাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」দুইবার,「(Skill.Arg2)」দুইবার সংক্রমিত করো"
  },
  Event_129187_Desc = {
    Text = "\"স্বাগত জানাও, আমার অমূল্য অতিথি। নির্দ্বিধায় বেছে নাও; এই সব ঝলমলে আয়োজন কেবল তোমার প্রতীক্ষাতেই বিদ্যমান।\"\n\"আহ, বিরক্ত করলাম, একটু জানতে চাই... আপনি কি লেডি ড্যাফোডিলের যমজ বোন?\"\n\"আমি নিজেই লেডি ড্যাফোডিল। জানতে পারি, আজ কী কারণে এসেছ...?\"\n\"দুঃখিত, দুঃখিত, আপনি আগের চেয়েও অনেক বেশি মোহনীয় হয়ে উঠেছেন। আমি চিনতে পারিনি। মনে আছে? বিশ বছর আগে, আপনি আমার বারের এক বিকৃত অতিথিকে তাড়িয়ে দিয়েছিলেন... গতকাল, সেই দুঃস্বপ্ন ফিরে এসেছে। সে বারে দখল নিয়েছে, সঙ্গে এনেছে তার আপন জাতের অগণিত সঙ্গী...\""
  },
  Event_129187_Name = {
