  Event_129198_Desc = {
    Text = "\"সুরেলা, গীতিময়, আনন্দময়, শোকাবহ... সেই সুর প্রতিধ্বনিত হচ্ছে ডোমেইনের ভেতর, উৎস যার অস্পষ্ট।\nওটা কি ভূতুড়ে জাহাজের অডিও সিস্টেম থেকে ভেসে আসা সিম্ফনি, নাকি ডোমেইনের ভেতর বন্দী কোনো মধ্যরাত্রির র‍্যাপসোডি?\""
  },
