  },
  Event_129200_ChoiceDesc3 = {
    Text = "[Put it back] ৫০টি কালো মুদ্রা অর্জন করো"
  },
  Event_129200_Desc = {
    Text = "একটি অবহেলিত কোণে, একটি চিঠি পড়ে আছে।\nচিঠির বহু শব্দ আর পড়া যায় না, কিন্তু একটি শব্দ রয়ে গেছে। তা কাগজ ভেদ করে বেরিয়ে এসেছে।\nসেই শব্দটি হলো \"মা\"।"
  },
