  },
  Event_129202_ChoiceDesc2 = {
    Text = "[Cover Ears] প্রতিটি জাগরণকারী, যার অ্যালিমাস 50 বা তার বেশি, তার জন্য 15টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_129202_ChoiceDesc3 = {
    Text = "[দেখো]3টির মধ্যে 1টি বেছে নেওয়ার অরিসন দুইবার লাভ করে"
  },
  Event_129202_Desc = {
    Text = "তুমি অবশিষ্ট দেহের তলায় প্রবেশ করতেই, ফাঁকা পরিত্যক্ত কারখানার ভেতর হঠাৎ এক সুরেলা ঘণ্টাধ্বনি প্রতিধ্বনিত হয়। পিয়ানোর স্বচ্ছ সুর মরিচাধরা ইস্পাত ধ্বংসাবশেষের সঙ্গে তীব্র বৈপরীত্য গড়ে তোলে।"
  },
  Event_129202_Name = {
    Text = "ভুতুড়ে স্কেল"
  },
  Event_129203_ChoiceDesc1 = {
    Text = "[স্থানধারক]অস্থায়ী লেখা।"
  },
  Event_129203_Name = {
    Text = "বিস্মৃতি অধ্যায় 3@"
  },
  Event_129204_ChoiceDesc1 = {
    Text = "[স্থানধারক]অস্থায়ী লেখা।"
  },
  Event_129204_Name = {
    Text = "বিস্মৃতি অধ্যায় 6@"
  },
  Event_129205_ChoiceDesc1 = {
    Text = "[Spare Her] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_129205_ChoiceDesc2 = {
    Text = "[তাকে সাহায্য করুন]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」দুইবার"
  },
  Event_129205_ChoiceDesc3 = {
    Text = "[Walk My Own Path] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129205_Desc = {
    Text = "তিনটি অন্ধকার, ক্ষণস্থায়ী অবয়ব তোমার পথ ব্লক করে দাঁড়ায়।\n「তুমি তাকে যেতে দিতে পারো, 」 বলে যে জনের হাতে D-পঙ্কে ভেজা টেডি বিয়ার, 「সে শুধু ভীরু, দুষ্ট নয়। সে কাউকে আঘাত করতে চায় না।」\n「তুমি তাকে সাহায্য করতে পারো, 」 বলে যে জনের হাতে সুন্দর মোড়ানো ক্যান্ডির প্যাকেট, 「সে যা করতে পারে না, তুমি তা পারো। তুমি সবকিছুর ইতি টানতে পারো।」\n「তোমার আমাদের কথা শুনতেই হবে এমন নয়, 」 বলে যে জনের হাত ফাঁকা, 「তোমার নিজের পথ আছে।」"
  },
  Event_129205_Name = {
    Text = "বিভক্ত পথ"
  },
  Event_129206_ChoiceDesc1 = {
    Text = "[Feed the Rats] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 লাভ করুন, 1টি উপসর্গ বিকশিত করুন"
  },
  Event_129206_ChoiceDesc2 = {
    Text = "[ইঁদুর তাড়াও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」, 2 বার পুনরাবৃত্তি করো, সংক্রমণ করো「(Skill.Arg2)」, 2 বার পুনরাবৃত্তি করো"
  },
  Event_129206_ChoiceDesc3 = {
    Text = "[Ignore the Rats] 25টি কালো চিহ্ন অর্জন করো"
  },
  Event_129206_Desc = {
    Text = "এই জাহাজের সবকিছুই সময় চক্রের ফাঁদে বন্দি।\nএখানে বেঁচে থাকার জন্য লড়তে থাকা সেই ঘৃণ্য, লোমশ ছোট ছোট প্রাণীগুলোও তাদের নিয়তি থেকে পালাতে পারে না।\nচক্রের পর চক্র, তারা চোখের সামনে যা পায় তাই গ্রাস করে, তবু তাদের ক্ষুধা কোনোদিন মেটে না।\n「খুব... ক্ষুধা...」\nইঁদুরের ঝাঁক থেকে বেরোয় অসুস্থ, কানে বিঁধে যাওয়া চিৎকার।\nঅন্তহীন পুনরাবৃত্তি তাদের করেছে ক্ষুধার্ত আর উন্মাদ—তাদের কিছু একটা খেতেই হবে।\nএখনই। অবিলম্বে।"
  },
  Event_129206_Name = {
    Text = "ক্ষুধার্ত ইঁদুরের দল"
  },
  Event_129207_ChoiceDesc1 = {
    Text = "[স্থানধারক]অস্থায়ী লেখা।"
  },
  Event_129207_Name = {
    Text = "বিস্মৃতি অধ্যায় 8@"
  },
  Event_129208_ChoiceDesc1 = {
    Text = "[মস্তিষ্ক স্পর্শ]এলোমেলোভাবে 1টি কমান্ড কার্ড অরিসন পায়：「(EnchantConfig.Arg1)」দুইবার"
  },
  Event_129208_ChoiceDesc2 = {
    Text = "[Touch the Heart] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত হবে।"
  },
  Event_129208_Desc = {
    Text = "তুমি পা বাড়াও নীরব, ধূসর প্রাঙ্গণে, যেখানে কোনো হুইসপার ভেসে থাকে না; অন্ধকার কুয়াশা ভেদ করে আবছা ভেসে ওঠে একজোড়া দাঁড়িপাল্লা。\nবাঁদিকে, হ্রদের মতো শান্ত এক মস্তিষ্ক, যার রুপালি‑সাদা খাঁজে ক্ষীণ গ্লিমার; ডানদিকে, উষ্ণতায় ধোঁয়া ওঠা অগ্নি‑লাল এক হৃদয়。\nহঠাৎ, তোমার নাকে ভেসে আসে এক মোহময় সুগন্ধ। তোমার ভেতরে ফুলে ওঠে অতৃপ্ত কামনা, আর তোমার বিবেককে চেপে ধরে তার সীমাহীন অন্ধকার。\nতুমি হাত বাড়াও।"
  },
  Event_129208_Name = {
    Text = "ক্ষুধার খেলা"
  },
  Event_129209_ChoiceDesc1 = {
    Text = "[স্থানধারক]অস্থায়ী লেখা।"
  },
  Event_129209_Name = {
