  },
  Event_129210_ChoiceDesc1 = {
    Text = "[ছায়া হত্যা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」দুইবার, সংক্রমিত করো「(Skill.Arg2)」দুইবার"
  },
  Event_129210_ChoiceDesc2 = {
    Text = "[ভ্রূণ পিষে দাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「⟦P1⟧」দুইবার, সংক্রমিত করো「⟦P2⟧」দুইবার"
  },
  Event_129210_ChoiceDesc3 = {
    Text = "[Close Your Eyes] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129210_Desc = {
    Text = "অস্পষ্ট চেতনায় তুমি দেখতে পাও আরলান্ডে দেখা মানুষগুলো তোমার দিকে এগিয়ে আসছে।\nতারা হাসতে হাসতে তোমাকে মদ্যপান, নৃত্য ও সুস্বাদু খাবারের আমন্ত্রণ জানায়।\nতারপর তাদের মাংস স্তরে স্তরে খসে পড়ে, মাটিতে পড়ে আবার কিলবিল করতে করতে নতুন ভ্রূণ জন্ম নেয়।\nতারা তোমার দিকে হাত বাড়িয়ে দেয়, রক্তমাংস ও নবজন্মের এই উন্মত্ত উৎসবে যোগ দিতে আমন্ত্রণ জানায়।"
  },
  Event_129210_Name = {
    Text = "অতীতের ছায়া"
  },
  Event_129211_ChoiceDesc1 = {
    Text = "[Feed Them] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 3টি উপসর্গের মধ্যে 1টি বিকশিত করো।"
  },
  Event_129211_ChoiceDesc2 = {
    Text = "[উপেক্ষা করুন]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」দুইবার, 「(Skill.Arg2)」দুইবার সংক্রমিত করুন"
  },
  Event_129211_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129211_Desc = {
    Text = "বাসিন্দারা আসে আর যায়, অথচ ইঁদুরের ঝাঁকটি যেন অনন্ত পর্যন্ত প্রসারিত।\nমানুষের তুলনায়, এই দুর্গের প্রকৃত \"স্থানীয়\" তো তারাই।\nকিন্তু মানুষ এখানে এসে বাসা বাঁধলে তাদের কোনো আপত্তি নেই।\nকারণ ওই নরম আর সাদা কুৎসিত জিনিসগুলো তাদের খাওয়াবে ঠিক ততটাই নরম আর সাদা কুৎসিত জিনিস।\n\"আর তুমি, কুৎসিত জিনিস, তুমি কোন দলে পড়ো?\""
  },
  Event_129211_Name = {
    Text = "প্রাচীন দুর্গের রহস্য"
  },
  Event_129212_ChoiceDesc1 = {
