  },
  Event_129213_ChoiceDesc1 = {
    Text = "[Discern Man's Voice] তিনটি কমান্ড কার্ডের মধ্যে 1টি অনুলিপি করো"
  },
  Event_129213_ChoiceDesc2 = {
    Text = "[নারীর কণ্ঠস্বর চেনা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「⟦P1⟧」দুইবার, 「⟦P2⟧」দুইবার সংক্রমিত করুন"
  },
  Event_129213_ChoiceDesc3 = {
    Text = "[Discern the Elder's Voice] 25টি কালো চিহ্ন প্রাপ্ত হও।"
  },
  Event_129213_Desc = {
    Text = "তুমি একা একটি অন্ধকার জলাভূমিতে দাঁড়িয়ে আছ।\nঅস্পষ্টভাবে তুমি শুনতে পাচ্ছ বিশৃঙ্খল প্রলাপের ঢেউ তোমার দিকে ধেয়ে আসছে—কিছু আসছে অশীতিপর বৃদ্ধদের কাছ থেকে, কিছু আসছে সবে কথা বলতে শেখা শিশুদের কাছ থেকে, কিছু আসছে উদ্বিগ্ন নারীদের কাছ থেকে, আর কিছু আসছে অজানা ভয়ে ভীত পুরুষদের কাছ থেকে……"
  },
  Event_129213_Name = {
    Text = "অন্তিম বাণীর প্রলাপ"
  },
  Event_129214_ChoiceDesc1 = {
    Text = "[ভালো করে দেখুন]3টি থেকে 1টি বেছে অরিসন পান দুইবার"
  },
  Event_129214_ChoiceDesc2 = {
    Text = "[পোস্টার ছিঁড়ে ফেলুন]যেকোনো 1টি কমান্ড কার্ড এলোমেলোভাবে অরিসন পান：「(EnchantConfig.Arg1)」দুইবার, সংক্রমিত করুন「(Skill.Arg2)」দুইবার"
  },
  Event_129214_Desc = {
    Text = "মোম জাদুঘরে প্রায়ই দেখা যায় এমন এক ক্যান্ডেলাব্রাম।\nভৌতিক কমলা আভায় তুমি দেয়ালে টাঙানো হাতে আঁকা একটি পোস্টার দেখতে পাও।"
  },
  Event_129214_Name = {
