  Event_129216_Name = {
    Text = "বিস্মৃতি অধ্যায় 7@"
  },
  Event_129217_ChoiceDesc1 = {
    Text = "[Stare] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_129217_ChoiceDesc2 = {
    Text = "[উপেক্ষা করো]3টির মধ্যে 1টি বেছে নেওয়ার অরিসন দুইবার লাভ করে"
  },
  Event_129217_Desc = {
    Text = "আরাম গোষ্ঠী বালুঝড়ের মধ্যে হাঁটু গেড়ে বসে।\nঝড় তাদের দেহে চাবুকের মতো আঘাত হানে, আর বালি তাদের দৃঢ় বিশ্বাসকে গ্রাস করে।\nঘূর্ণায়মান ধুলোর ভেতর, অসংখ্য বিশাল চোখ যেন বিকৃত ভূমির উপর নেমে তাকিয়ে থাকে।"
  },
  Event_129217_Name = {
    Text = "ধূলির দানব"
  },
  Event_129218_ChoiceDesc1 = {
    Text = "[প্রজাপতি তাড়ানো]যেকোনো 1টি কমান্ড কার্ড এলোমেলোভাবে অরিসন পায়：「(EnchantConfig.Arg1)」দুইবার, সংক্রমিত হয়「(Skill.Arg2)」দুইবার"
  },
  Event_129218_ChoiceDesc2 = {
    Text = "[ইচ্ছা শোনা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পায়：「(EnchantConfig.Arg1)」, পুনরাবৃত্তি 2 বার"
  },
  Event_129218_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129218_Desc = {
    Text = "ছোট্ট প্রজাপতিটিরও অনেক স্বপ্ন আছে।\nএই স্বপ্নগুলো ছড়িয়ে আছে ফুলের সমুদ্রে, হাসপাতালের কক্ষে, আর রক্তমাংসে পরিপূর্ণ @2 বেদিতে।\nআর আজ, সে অবশেষে তার বন্ধনের মানুষটিকে পেয়েছে। জানি না তুমি তার ছোট্ট, ছোট্ট ইচ্ছাটি শুনতে রাজি কিনা।"
  },
  Event_129218_Name = {
    Text = "প্রজাপতির স্বপ্ন"
  },
  Event_129219_ChoiceDesc1 = {
    Text = "[নির্দেশনা অনুসরণ করো]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」, 2 বার পুনরাবৃত্তি করো, সংক্রমণ করো「(Skill.Arg2)」, 2 বার পুনরাবৃত্তি করো"
  },
  Event_129219_ChoiceDesc2 = {
    Text = "[নির্দেশনা উপেক্ষা করো]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」, 2 বার পুনরাবৃত্তি করো, সংক্রমণ করো「(Skill.Arg2)」, 2 বার পুনরাবৃত্তি করো"
  },
  Event_129219_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129219_Desc = {
    Text = "উৎসব শুরু হয়ে গেছে।\nআধ্যাত্মিক শিখা আর রক্তস্নাত আশীর্বাদের মাঝে, অগণিত বিশ্বাসী পরিণত হয়েছে জীবন্ত মশালে—\nঅলৌকিক আত্মারা জোনাকির মতো তোমার চারপাশে বিক্ষিপ্ত, জ্বলজ্বল করছে, অপেক্ষা করছে তোমার নির্বাচনের।"
  },
  Event_129219_Name = {
    Text = "আত্মার প্রদীপস্তম্ভ"
  },
  Event_129220_ChoiceDesc1 = {
    Text = "[ঘণ্টা উপেক্ষা]3টির মধ্যে 1টি উন্নত প্রার্থনালিপি দুইবার পান"
  },
  Event_129220_ChoiceDesc2 = {
    Text = "[Pick up the Receiver] 「(RelicConfig.Arg1)」 নামের সোনার রেলিক অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত হবে"
  },
  Event_129220_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129220_Desc = {
    Text = "ওটা বাজা উচিত ছিল না—ক্যানভাসের পেছনে গুটিয়ে থাকা টেলিফোনটা।\nতার তার মোটা যন্ত্রদেহের চারপাশে জংধরা নাভিরজ্জুর মতো পেঁচিয়ে আছে, যেন তোমার নিজের মস্তিষ্ক থেকে প্রসারিত হয়েছে।\nতুমি সাবধানে কম্পনের কম্পাঙ্ক নির্ণয় করো; সেই অদ্ভুত শব্দ তোমাকে পিকম্যানের অতিবাস্তব শিল্পের কথা মনে করিয়ে দেয়।"
  },
  Event_129220_Name = {
    Text = "মিসড কল"
  },
  Event_129221_ChoiceDesc1 = {
    Text = "[আমরা সবাই ভালো আছি]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」দুইবার, 「(Skill.Arg2)」দুইবার সংক্রমিত করো"
  },
  Event_129221_ChoiceDesc2 = {
    Text = "[তুমি কে？]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」দুইবার, 「(Skill.Arg2)」দুইবার সংক্রমিত করো"
  },
  Event_129221_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129221_Desc = {
    Text = "টাইপরাইটার হঠাৎ কালি উগরে দেয়, চোখে বিঁধে যাওয়ার মতো সংখ্যক বিস্ময়বোধক চিহ্নসহ.\n「ডল, তুমি ঠিক আছ তো??? রক্ষকও যখন গায়েব, তখন তুমিও কেন উধাও হয়ে গেলে??? প্লিজ, যদি নিরাপদে থাকো, একটা বার্তা পাঠাও!!! উইলিয়াম সিনিয়রের চুল আর অপেক্ষা সহ্য করতে পারবে না!!!」"
  },
