  Event_129234_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129234_Desc = {
    Text = "ওই প্রজাপতিটা উড়ে আসেনি, বরং ধীরে ধীরে গজিয়েছে তোমার হাতের তালু থেকে।\nশুরুতে তুমি ভেবেছিলে ওটা শুধু ঘাম, কিন্তু আঙুলের ফাঁকে দেখলে কালো তরল শিরার উল্টো স্রোতের মতো চুঁইয়ে বেরোচ্ছে, জমাট বেঁধে ঠান্ডা, স্পন্দিত ডানায় রূপ নিচ্ছে।\nপ্রতিবার সে ডানা ঝাপটায়, তোমার রক্তপ্রবাহ জুড়ে ঢেউ খেলে যায়।"
  },
