  },
  Event_129235_Desc = {
    Text = "ওজন মাপার এক পাল্লা।\nতার পেছনে অসংখ্য অঙ্গ লাল ফর্মালিনে ডুবে আছে।\nসেগুলো গুদামঘরের তাকজুড়ে পরিপাটি করে সাজানো।\nতুমি উদাসীন ভঙ্গিতে পাশের একখানা নোটবুক তুলে নিয়ে পাতা ওল্টাও:\n\"হৃদপিণ্ড: ৮ আউন্স, মস্তিষ্ক: ৫০ আউন্স...\""
  },
