  Event_129242_ChoiceDesc1 = {
    Text = "[তার জন্য বাজান]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」দুইবার, 「(Skill.Arg2)」দুইবার সংক্রমিত করুন"
  },
  Event_129242_ChoiceDesc2 = {
    Text = "[Listening to the Strings] প্রতিটি জাগরণকারী, যার অ্যালিমাস 50 বা তার বেশি, তার জন্য 15টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_129242_ChoiceDesc3 = {
    Text = "[চলে যাও]3টি থেকে 1টি বেছে অরিসন দুইবার পাও"
  },
  Event_129242_Desc = {
    Text = "「প্রিয় জন, \nহঠাৎ টের পেলাম, তুমি আমাদের জন্য পিয়ানো বাজাওনি বহু বছর হয়ে গেছে।\nএই বছর আমার বয়স 81, আর বয়স যত বাড়ছে, যৌবনের স্মৃতিগুলোকে ততই বেশি আঁকড়ে ধরছি।\nযদি তুমি এই চিঠি পাও, তবে পরেরবার লন্ডিনিয়াম দিয়ে যাওয়ার সময় আমার অ্যাপার্টমেন্টে একবার এসো, আর আমার জন্য একটা সুর বাজিয়ে যেও।」"
  },
  Event_129242_Name = {
    Text = "আক্ষেপের সোনাটা"
  },
  Event_129243_ChoiceDesc1 = {
    Text = "[স্থানধারক]অস্থায়ী লেখা।"
  },
  Event_129243_Name = {
    Text = "নক্ষত্র অধ্যায় 3@"
  },
  Event_129244_ChoiceDesc1 = {
    Text = "[বলুন যে মানিব্যাগ নেই]3টি থেকে 1টি অরিসন দুইবার অর্জন করুন"
  },
  Event_129244_ChoiceDesc2 = {
    Text = "[জাল ভেঙে ফেলুন]এলোমেলো 1টি কমান্ড কার্ডে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」দুইবার, সংক্রমিত করুন「(Skill.Arg2)」দুইবার"
  },
  Event_129244_Desc = {
    Text = "হলুদ-কমলা এক জাল নীরবে ভেসে আছে বাতাসে, তার ফাঁকাগুলো দেয়ালের গায়ে বাসা বাঁধা মাকড়সার সূক্ষ্ম বুননের তুলনায় অনেক কম জটিল।\nতুমি হাত বাড়িয়ে দিতে নিজেকে আটকাতে পারো না; ভঙ্গুর জালটি সঙ্গে সঙ্গে দ্রবীভূত হয়ে যায়, আর তোমার কানে ভেসে আসে বালকদের হাসি।\n「সোনা, সিলভার, হলুদ, লাল, সব মানিব্যাগই আমাদের!」"
  },
  Event_129244_Name = {
    Text = "ভেগাস নেটওয়ার্ক"
  },
  Event_129245_ChoiceDesc1 = {
    Text = "[Choose Emotion] Arg1 HP পুনরুদ্ধার করো"
  },
  Event_129245_ChoiceDesc2 = {
    Text = "[বিবেক বজায় রাখুন]এলোমেলো 1টি কমান্ড কার্ড অরিসন পায়：「(EnchantConfig.Arg1)」দুইবার"
  },
  Event_129245_ChoiceDesc3 = {
    Text = "[Refuse to Choose] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129245_Desc = {
    Text = "\"নির্বাচন করো, নির্বাচন করো।\"\nদৌড়ে চলা অন্ধকারের ভেতর, অসংখ্য হুইসপার প্রতিধ্বনিত হতে থাকে।\nভয়েসটি কোমল, সম্মোহনী, যেন অসীম জাদু বয়ে আনে, যা তোমার ভেতরে এক ধরনের উন্মত্ত মায়াভ্রম জাগিয়ে তোলে।\nতোমার মস্তিষ্ক উন্মাদনায় ডুবে যায়, দেহ থেকে কিলবিলিয়ে সরে যেতে থাকে, আর হৃদয় যেন নিজস্ব এক চেতনা অর্জন করেছে—চিৎকার করছে, তোমাকে ডাকছে।\n\"নির্বাচন করো, নির্বাচন করো।\"\n\"যুক্তিবোধ নাকি অনুভূতি; তোমাকে একটি নির্বাচন করতেই হবে।\""
  },
  Event_129245_Name = {
    Text = "মানবতার মূল্য"
  },
  Event_129246_ChoiceDesc1 = {
    Text = "[Destroy Offering] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_129246_ChoiceDesc2 = {
    Text = "[দড়ি খোলো]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」দুইবার"
  },
  Event_129246_ChoiceDesc3 = {
    Text = "[Keep Going] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129246_Desc = {
    Text = "উঁচু মঞ্চে তিনজন আরাম গোষ্ঠীর মানুষকে বেঁধে রাখা হয়েছে।\nতারা মন্ত্রোচ্চারণ করতে করতে, নবজাতকের গায়ে দেখা সেই অন্ধকার, বাকলসদৃশ নকশাগুলোই তাদের শরীরে ফুটে উঠল।"
  },
