  Event_129249_ChoiceDesc3 = {
    Text = "[নীরবে সহ্য করো]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」দুইবার"
  },
  Event_129249_Desc = {
    Text = "পুরো পথজুড়ে তুমি ঠেলে এগিয়ে যাচ্ছ, তোমার প্রতিটি সিদ্ধান্ত অদৃশ্য সুতোয় নিয়ন্ত্রিত।\nতুমি মরিয়া হয়ে আঁকড়ে ধরতে চাও তোমার সব প্রিয় জিনিস।\nবিশ্বের ভাগ্য ঝুলে আছে তোমার আঙুলের ডগার ঠিক সামনে।\nঅগণিত সুতো জড়িয়ে গেছে, বেঁধে ফেলেছে তোমার সমগ্র দেহ।"
  },
  Event_129249_Name = {
    Text = "পুতুল হাত"
  },
  Event_129250_ChoiceDesc1 = {
    Text = "[তাকে পথ জিজ্ঞেস করুন]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」দুইবার, সংক্রমিত করুন「(Skill.Arg2)」দুইবার"
  },
  Event_129250_ChoiceDesc2 = {
    Text = "[এটি ছেড়ে যাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_129250_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129250_Desc = {
    Text = "উঁচু রাস্তার বাতির নিচে ছায়াটা দাঁড়িয়ে আছে।\n\"একটু আগুন ধার পাব কি, স্যার?\"\nতোমার @2 করার অভ্যেস নেই, কিন্তু সামান্য একটু \"জাদু\" ব্যবহার করতে তোমার আপত্তি নেই।\nতোমার সহায়তায় ছায়াটি @2-তে আগুন ধরাবে এবং সেটাকে গভীরভাবে নিক্ষেপ করবে সেই অতল কালো ঘূর্ণাবর্তের ভেতর।\nঅল্পক্ষণের মধ্যেই তুমি দেখতে পাও সাদা ধোঁয়া কুণ্ডলী পাকিয়ে উঠছে।\n\"আহ—\"\nসন্তুষ্টির নিঃশ্বাস ফেলে ছায়াটি।"
  },
  Event_129250_Name = {
