  Event_129258_ChoiceDesc2 = {
    Text = "[Become a Butterfly] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_129258_ChoiceDesc3 = {
    Text = "[Swallow Back] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129258_Desc = {
    Text = "এই রাতে কত কিছুই না ঘটে গেছে।\nডকে আক্রমণ, ভূতুড়ে মালবাহী জাহাজ, সাগরচারী, তুলু, মার্ফি, রামোনা... সবকিছু ঘূর্ণাবর্তে ঘুরে মিশে গেছে মিথাগের রেস্তোরাঁর সকাল 7টার ওটমিলে।\nতুমি সামনে বসা Awakener-কে কিছু জিজ্ঞেস করতে চাও, কিন্তু কোথা থেকে শুরু করবে বুঝে উঠতে পারো না; গলায় যেন কিছু আটকে আছে—অথবা পেটে উড়ছে অদৃশ্য প্রজাপতির ঝাঁক।"
  },
  Event_129258_Name = {
    Text = "বাটারফ্লাই ইফেক্ট"
  },
  Event_129259_ChoiceDesc1 = {
    Text = "[স্থানধারক]অস্থায়ী লেখা।"
  },
  Event_129259_Name = {
    Text = "বিস্মৃতি অধ্যায় 8@"
  },
  Event_129260_ChoiceDesc1 = {
    Text = "[থাকতে দাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」দুইবার, 「(Skill.Arg2)」দুইবার সংক্রমিত করো"
  },
  Event_129260_ChoiceDesc2 = {
    Text = "[Wave Away] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_129260_ChoiceDesc3 = {
    Text = "[Welcome the Butterflies] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129260_Desc = {
    Text = "তুমি হিমশীতল স্যানাটোরিয়ামের ভেতর ঘুরে বেড়াও, যেখানে এই ঋতুতে থাকার কথা নয় এমন এক কালো প্রজাপতি উড়ে যায় তোমার পাশ দিয়ে।\nতার ডানা, কালো পিচ্ছিল কাদায় মোড়া, দুলতে দুলতে উড়ে চলে, আর উড়তে উড়তে স্তরে স্তরে কালো কাদামাটি ঝরিয়ে দেয়, যা বাতাসে কঠিনীকরণ হয়ে খসে পড়ে।\nশ্রান্ত হয়ে, সেটি এসে বসে তোমার আঙুলের ডগায়।"
  },
  Event_129260_Name = {
    Text = "যা থাকা উচিত নয়"
  },
  Event_129261_ChoiceDesc1 = {
    Text = "[অতীত পুনরুদ্ধার]3টি থেকে 1টি বেছে নেওয়া উন্নত প্রার্থনালিপি পাও, 2 বার পুনরাবৃত্তি করো"
  },
  Event_129261_ChoiceDesc2 = {
    Text = "[Gaze into the Future] সোনালি রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 উন্নয়ন করো"
  },
  Event_129261_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129261_Desc = {
    Text = "এই জগতে কিছুই অপরিবর্তিত থাকে না—\nদেবমাতার গড়া প্যারাডাইসও নয়।\nক্ষণিকের জন্য, তুমি সময়ের এক ফাটল দিয়ে কিছু এক ঝলক দেখতে পাও।\nঅতীত, বর্তমান ও ভবিষ্যৎ সেই ফাটলের ভেতর জড়িয়ে থাকে, অবিরাম রূপ বদলায়,\nপ্রতীক্ষা করে তোমার কৌতূহলী দৃষ্টির।"
  },
  Event_129261_Name = {
    Text = "সময়ের ফাটল"
  },
  Event_129262_ChoiceDesc1 = {
    Text = "[স্থানধারক]অস্থায়ী লেখা।"
  },
  Event_129262_Name = {
    Text = "বিস্মৃতি অধ্যায় 7@"
  },
  Event_129263_ChoiceDesc1 = {
    Text = "[উপেক্ষা করা]3টি থেকে 1টি বেছে নেওয়ার অরিসন পায়, পুনরাবৃত্তি 2 বার"
  },
  Event_129263_ChoiceDesc2 = {
    Text = "[স্পর্শ করা]যেকোনো 1টি কমান্ড কার্ড এলোমেলোভাবে অরিসন পায়：「(EnchantConfig.Arg1)」, পুনরাবৃত্তি 2 বার, সংক্রমিত হয়「(Skill.Arg2)」, পুনরাবৃত্তি 2 বার"
  },
  Event_129263_Desc = {
    Text = "স্পোরের মতো দেখতে এক অদ্ভুত বস্তু তোমার দৃষ্টি কেড়ে নেয়।\nওটা যেন মাংস আর রক্ত দিয়ে গড়া এক সূক্ষ্ম জেলিফিশ, আবার মস্তিষ্কের গভীরে সংকেত বহনকারী স্নায়ুতন্তুর মতোও লাগে।\n\"এসো, আমাকে ছুঁয়ে দেখো,\" নীরবে প্রলুব্ধ করে সে, \"আমি তোমাকে এক নিষ্ঠুর স্মৃতি দেখাব।\""
  },
  Event_129263_Name = {
    Text = "গভীর স্মৃতি"
  },
  Event_129264_ChoiceDesc1 = {
    Text = "[কল্পনায় মগ্ন]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「⟦P1⟧」দুইবার, সংক্রমিত করুন「⟦P2⟧」দুইবার"
  },
  Event_129264_ChoiceDesc2 = {
    Text = "[Maintain Sanity] প্রতি জাগরণকারীর জন্য, যার অ্যালিমাস 50 বা তার বেশি, 15টি করে কালো চিহ্ন লাভ করুন"
  },
  Event_129264_ChoiceDesc3 = {
    Text = "[জোর করে চলে যাও]3টি থেকে 1টি বেছে অরিসন পাও, 2 বার পুনরাবৃত্তি করো"
  },
  Event_129264_Desc = {
    Text = "হয়তো দীর্ঘ যুদ্ধ তোমাকে বিভ্রান্ত করে ফেলেছে, অথবা হয়তো তোমার মনই তোমার দেহকে বিশ্বাসঘাতকতা করেছে।\nএক ধরনের ভারশূন্যতা তোমার চিন্তাকে ভরে তোলে।\nএক মুহূর্তে, তোমার মন হয়ে ওঠে এক ক্যালেইডোস্কোপ—ঝলমলে, দীপ্তিময়, সব রঙের বিদ্যুৎচমকে ভরা।\nঅগণিত অন্তর্দৃষ্টি, ভাবনা আর কল্পনা ঢেউয়ের পর ঢেউয়ের মতো ভেসে আসে, তোমার মস্তিষ্কের প্রতিটি ফাঁক ভরে তোলে।\nএভাবে চলতে থাকলে, খুব শিগগিরই তোমার মস্তিষ্ক এই বিশৃঙ্খলায় ফেটে যাবে।"
  },
  Event_129264_Name = {
    Text = "চিন্তার ক্যালিডোস্কোপ"
  },
  Event_129265_ChoiceDesc1 = {
