  },
  Event_129267_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129267_Desc = {
    Text = "দুর্ঘটনার পর থেকে, তুমি আর তোমার সঙ্গীর কোনো খবর পাওনি।\nঅসংখ্য বার্তা পাঠিয়েছ, কিন্তু সবই যেন সমুদ্রে পাথর ফেলার মতো—কোনো উত্তর আসেনি।\nযখন তুমি ইতিমধ্যে সব আশা ছেড়ে দিয়েছিলে, হঠাৎ যোগাযোগ যন্ত্রটি বেজে উঠল।\nতুমি ব্রিফকেসটি খুললে এবং টেলিফোনের রিসিভারটি কানের কাছে ধরলে।\n\"রহস্যরক্ষক……\"\nঘোরের মধ্যে তুমি সেই বহু কাঙ্ক্ষিত কণ্ঠস্বরটি শুনতে পেলে, যেন স্তরে স্তরে শূন্যতার ওপার থেকে সুদূর প্রতিধ্বনি ভেসে আসছে।"
  },
