  },
  Event_129275_ChoiceDesc1 = {
    Text = "[যুদ্ধের প্রস্তুতি নাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」, 2 বার পুনরাবৃত্তি করো, সংক্রমণ করো「(Skill.Arg2)」, 2 বার পুনরাবৃত্তি করো"
  },
  Event_129275_ChoiceDesc2 = {
    Text = "[Try to Detour] 25টি কালো চিহ্ন অর্জন করো"
  },
  Event_129275_Desc = {
    Text = "তারাভরা গভীরে, সাগরচারীরা শতাব্দীর পর শতাব্দী তন্দ্রায় নিমগ্ন।\nঅসীম সাগর তাদের উন্মাদনা, তাদের সহনশীলতা, আর তাদের সর্বাধিক ভক্তিপূর্ণ বিশ্বাসের সাক্ষী।\nকেউই তাদের ঈশ্বরের মহা আগমনে বাধা দিতে পারবে না।\nযারা পথে দাঁড়াবে, সাগরচারীদের ক্রোধে তারা ছাইয়ে পরিণত হবে।"
  },
  Event_129275_Name = {
    Text = "নক্ষত্রের নিচে প্রতীক্ষা"
  },
  Event_129276_ChoiceDesc1 = {
    Text = "[Play a Few Notes] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_129276_ChoiceDesc2 = {
    Text = "[ঢাকনা বন্ধ করুন]3টি থেকে 1টি অরিসন দুইবার অর্জন করুন"
  },
  Event_129276_Desc = {
    Text = "দেয়ালের পাশে রাখা পিয়ানোর ঢাকনা খোলা। তার কী-গুলো হলদেটে, প্রান্তগুলো ফেটে কাঠের গায়ে পৌঁছে গেছে, তবু প্রতিটি কী যত্নে মুছে পরিষ্কার রাখা হয়েছে।\nএটি অগণিত মানুষের আনন্দের উৎস।"
  },
  Event_129276_Name = {
    Text = "শিশুদের ছড়া"
  },
  Event_129277_ChoiceDesc1 = {
    Text = "[মায়াভ্রম গ্রহণ করো]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」দুইবার, 「(Skill.Arg2)」দুইবার সংক্রমিত করো"
  },
  Event_129277_ChoiceDesc2 = {
    Text = "[Deny the Illusion] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_129277_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_129277_Desc = {
    Text = "ভারী, অন্ধকার লোহার সেতুর নীচে, নীরব, শাপলা-ঢাকা নদীতীর থেকে হঠাৎই এক ঝলমলে প্রজাপতি উড়ে আসে।\nপ্রজাপতিটি আলতো করে নেমে বসে তোমার তালুতে, ভয়াবহ আর্তনাদগুলোকে স্তব্ধ করে দেয়। তার বদলে তুমি শুনতে পাও ইস্পাত টেনে নেওয়া শ্রমিকদের ছন্দোময় মন্ত্রোচ্চারণ, হাতুড়ির গর্জন, আর রিভেটের টনটন শব্দ..."
  },
  Event_129277_Name = {
