  Event_129900_Name = {
    Text = "বিবর্ণ অস্থি"
  },
  Event_130337_ChoiceDesc1 = {
    Text = "[আসন গ্রহণ]'সুতোর পুতুল' ডেকে রাখুন।"
  },
  Event_130337_Desc = {
    Text = "আপনার পা যখন নাট্যশালার সিঁড়িতে পড়লো, দৃষ্টি আর এই মঞ্চ থেকে সরানো গেল না।\nভাগ্যের সুতো অগণিত কাহিনীকে টেনে এখানে প্রবাহিত করছে — অতীতের ধূলিকণা, বর্তমানের আলোছায়া, ভবিষ্যতের কুয়াশা, সবই মঞ্চের সামনে অবিরাম উত্তাল হচ্ছে।\nআপনি ভুলে গেলেন কোথা থেকে এসেছেন, কোথায় যেতে চান, 「আত্মপরিচয়」 এর চিহ্ন পর্দার ছায়ায় সম্পূর্ণ মিলিয়ে গেল। এই মুহূর্তে, আপনি আসনে বসা নীরব দর্শক, আবার মঞ্চে জ্বলন্ত অভিনেতাও।\nআপনার অস্তিত্বের সমগ্র অর্থ দুটি খোদাই চিহ্নে সংকুচিত হলো: দর্শন, এবং অভিনয়।"
  },
  Event_130337_Name = {
    Text = "নিয়তির মঞ্চ"
  },
  Event_131264_ChoiceDesc1 = {Text = "[Leave]"},
  Event_131264_Desc = {
    Text = "তোমরা শক্তি বেছে নিয়েছ, বেছে নিয়েছ অটল বিশ্বাস আর অদম্য সাহস।\nকিন্তু, মূল্য……মূল্যের অস্তিত্বের অর্থই তো হলো তা বহন করা, তাই না?"
  },
  Event_131264_Name = {
    Text = "পুরাতন দিনের দৃষ্টি"
  },
  Event_131265_ChoiceDesc1 = {Text = "[Leave]"},
  Event_131265_Desc = {
    Text = "তুমি মাথার ভেতরের যন্ত্রণা সহ্য করে, ছড়িয়ে পড়া ও ভেঙে যাওয়া স্মৃতিগুলোকে শক্ত করে আঁকড়ে ধরো। তোমার কঠিন সহনশীলতায়, সেই ফাটলগুলো জোড়া লাগতে শুরু করে।\nতুমি স্মৃতি ধরে রাখতেই এখান থেকে বেরিয়েছ, স্মৃতি ধরে রাখতেই যুদ্ধ করেছ। তুমি কোনো স্মৃতিকেই নিজের কাছ থেকে হারাতে দেবে না।"
  },
  Event_131265_Name = {
    Text = "ভগ্ন স্মৃতি"
  },
  Event_131266_ChoiceDesc1 = {
    Text = "[স্মৃতি রক্ষা করুন]3টি থেকে 1টি সিলমোহর অর্জন করুন"
  },
  Event_131266_ChoiceDesc2 = {
    Text = "[ফাটল প্রতিরোধ]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে এনগ্রেভিং অর্জন করুন: 「(EnchantConfig.Arg1)」, সংক্রমিত হন「(Skill.Arg2)」"
  },
  Event_131266_Desc = {
    Text = "তুমি কখনো নিজের স্মৃতিকে প্রশ্ন করোনি। সেগুলো উষ্ণ, দৃঢ়, তোমার সবচেয়ে নির্ভরযোগ্য আশ্রয় এবং সবচেয়ে মূল্যবান সম্পদ।\nকিন্তু এখন, অতল কারাগারের হস্তক্ষেপে, সেই স্মৃতিগুলোতে বিশৃঙ্খল ফাটল দেখা দিতে শুরু করেছে।"
  },
  Event_131266_Name = {
    Text = "ভগ্ন স্মৃতি"
  },
  Event_131267_ChoiceDesc1 = {Text = "[Leave]"},
  Event_131267_Desc = {
    Text = "মানসিক শক্তি মস্তিষ্কে প্রবাহিত হয়, সেই ভয়ংকর ফাটলগুলো মেরামত করে। তুমি সর্বশক্তি দিয়ে চেষ্টা করো, অবশেষে সেই ফাটলগুলো পুনরায় অক্ষত হয়ে ওঠে।\nতুমি স্মৃতি ধরে রাখতে এখান থেকে বেরিয়েছিলে, স্মৃতি ধরে রাখতেই লড়াই করেছিলে। তুমি কোনো স্মৃতিকে নিজের কাছ থেকে হারাতে দেবে না।"
  },
  Event_131267_Name = {
    Text = "ভগ্ন স্মৃতি"
  },
  Event_131268_ChoiceDesc1 = {Text = "[Leave]"},
  Event_131268_Desc = {
    Text = "「উউউউ……হাহাহাহা！！」\nকেউ তোমার প্রশ্ন বুঝতে পারেনি, তারা কান্না ও তীক্ষ্ণ হাসি দিয়ে সাড়া দিয়েছে।"
  },
  Event_131268_Name = {
    Text = "পরিত্যক্ত"
  },
  Event_131269_ChoiceDesc1 = {Text = "[Leave]"},
  Event_131269_Desc = {
    Text = "আপনারা তাদের দিকে ফিরে তাকান। সুতোর তার কাঁপে, কোমল দৃষ্টি স্মৃতিকে আলিঙ্গনে জড়িয়ে নেয়।\nআপনি নীরবে সেই ভাগ্য নিয়ন্ত্রণকারীর দিকে তাকান। যদি আরেকবার সুযোগ পেতেন, তিনি কী বেছে নিতেন?"
  },
  Event_131269_Name = {
    Text = "পুরাতন দিনের দৃষ্টি"
  },
  Event_131270_ChoiceDesc1 = {Text = "[Leave]"},
  Event_131270_Desc = {
    Text = "「উউউউ……হাহাহাহা！！」\nকান্না আর তীক্ষ্ণ হাসি তোমার সামনে ধীরে ধীরে মিলিয়ে যায়। কোনো আত্মা তোমাকে আঘাত করতে আসেনি——তারা অনেক আগেই উপেক্ষিত হতে অভ্যস্ত হয়ে গেছে।"
  },
