  Event_131271_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_131271_Desc = {
    Text = "মেয়েটির শরীরের ভেতর থেকে তুমি একটি পাত্র ভেঙে যাওয়ার শব্দ শুনতে পাও। স্মৃতিগুলো তাদের পাত্র ছেড়ে তোমাদের কাছে চলে আসে।\nশৈশবের খেলার সাথী, বাবা-মায়ের উপহার, সাদা মেঘ আর উড়ন্ত পাখিদের নিয়ে সবচেয়ে নিষ্পাপ কল্পনা, আকাশের মতো শুভ্র স্বপ্ন……সমস্ত স্মৃতি চোখ মেলে, নীরবে তোমাদের দিকে তাকিয়ে থাকে।\nতারা প্রশ্ন করে। তারা কাঁদে। তারা অপেক্ষা করে।"
  },
