  },
  Event_131272_Desc = {
    Text = "তীক্ষ্ণ আর্তনাদ তোমার কানে বেজে ওঠে, যন্ত্রণাকাতর আত্মারা তোমার সামনে নিজেদের মুখমণ্ডল ও দেহ ছিঁড়ে ফেলছে……\nতারা কে? অতল কারাগারের বন্দী? পরিত্যক্ত নিয়তি? সমাধিস্থ স্মৃতি?"
  },
