  },
  Event_133380_ChoiceDesc1 = {Text = "[Confirm]"},
  Event_133380_Desc = {
    Text = "আপনি আপনার জন্য নির্ধারিত মখমলের আসনে বসলেন, রক্তলাল পর্দা নীরবে সরে গেল।\nপ্রিয় দর্শক, মঞ্চ আপনার প্রত্যাশায় সাড়া দেবে।\nএই নাটকের প্রধান অভিনেতা ইতিমধ্যে মঞ্চে দাঁড়িয়েছেন।"
