  Event_141995_ChoiceDesc3 = {
    Text = "[বিপরীত চিন্তা？]সর্বাধিক দুটি জাগরণকারী বেছে নাও, তাদের সম্পূর্ণ মৌলিক কার্ডের একটি সেট তৈরি করে ডেকে রাখো"
  },
  Event_141995_Desc = {
    Text = "তুমি একটি চত্বরে এসে পৌঁছাও, অনেক মানুষ তাড়াহুড়ো করে চলছে, হয়তো এখানে কিছু মজার জিনিস খুঁজে পাওয়া যাবে।\nতুমি একটি ম্লান হলুদ আলো জ্বলা ঘরের দরজায় টোকা দাও, একজন গবেষক পোশাকের মানুষ ভেতর থেকে মাথা বের করে। তুমি অনেক অজানা বৈজ্ঞানিক যন্ত্রপাতি দেখতে পাও, সে তোমাকে টেনে বসায় এবং দাবি করে যে সে একজন 「বিবর্তনবিদ」। তার মুখে উন্মত্ততার ছাপ, সে তোমাকে তার 「বৈজ্ঞানিক পদ্ধতি」 জোরালোভাবে সুপারিশ করে।\n「মানুষের মধ্যে থাকা নিরর্থক অতিরিক্ত অংশ মুছে ফেলাই হলো সত্যিকারের বিবর্তনের পথ！」"
  },
  Event_141995_Name = {
    Text = "বিবর্তনবিদ"
  },
  Event_141996_ChoiceDesc1 = {
