  Event_141996_ChoiceDesc3 = {
    Text = "[সর্বশক্তি দিয়ে বিশেষ প্রশিক্ষণ]এলোমেলো 15টি কমান্ড কার্ডে এলোমেলো অরিসন যুক্ত করো, 5টি এলোমেলো উপসর্গ কার্ড অর্জন করো"
  },
  Event_141996_Desc = {
    Text = "তুমি একটি চত্বরে এসে পৌঁছাও, অনেক মানুষ ব্যস্তভাবে ছুটে চলেছে, হয়তো এখানে কিছু মজার জিনিস খুঁজে পাওয়া যাবে।\nখোলা জায়গায় ধাতুর ঠনঠন শব্দ প্রতিধ্বনিত হচ্ছে, কয়েকজন এখানে পরস্পরের সাথে লড়াই করে নিজেদের যুদ্ধ দক্ষতা বাড়াচ্ছে। পুরনো ধাঁচের বর্ম পরা একজন তরুণ তোমাকে লক্ষ্য করে একটি তলোয়ার ছুঁড়ে দেয় এবং তাদের সাথে অনুশীলনে যোগ দেওয়ার আমন্ত্রণ জানায়।"
  },
