  Event_141998_ChoiceDesc3 = {Text = "[Leave]"},
  Event_141998_Desc = {
    Text = "তুমি একটি অত্যন্ত賑賑রমরমা জায়গায় এসে পৌঁছাও, সবার মুখে সুখের হাসি, অবাধে মিটমিট করা রঙিন আলো রাতের অন্ধকারকে কোণঠাসা করে ফেলেছে। আর সর্বত্র দৃশ্যমান সাইনবোর্ডে লেখা রয়েছে：「কার্নিভালে স্বাগতম! এখানে স্বপ্নের কোনো সমাপ্তি নেই, এখানে আনন্দের কোনো সমাপ্তি নেই!」\nভিড়ের ঠেলায় তুমি একটি জমকালো ভবনে ঢুকে পড়ো, হলঘরটি সোনালি জৌলুসে ভরা, কোলাহলে মুখর, বাতাসে মিষ্টি মদের সুগন্ধ ভেসে বেড়াচ্ছে। একটি পাশার দান গড়িয়ে গড়িয়ে ঠিক তোমার পায়ের কাছে এসে থামে, ওয়েটার চাটুকারিতার হাসি ঝুলিয়ে বলে এটি সৌভাগ্যের প্রতীক। কৌতূহল মনে নিয়ে তুমি এক পা এগিয়ে যাও, হয়তো এই খেলায় নিজের দক্ষতা দেখানোর সুযোগ আসবে।"
  },
  Event_141998_Name = {
    Text = "কোলাহলময় ক্যাসিনো"
