  Event_141999_ChoiceDesc2 = {Text = "[Leave]"},
  Event_141999_Desc = {
    Text = "তুমি একটি অত্যন্ত賑賑热闹 জায়গায় এলে, সবার মুখে সুখের হাসি, অবাধে মিটমিট করা রঙিন আলো রাতের অন্ধকারকে কোণঠাসা করে ফেলেছে। আর সর্বত্র দেখা যাওয়া সাইনবোর্ডে লেখা：「কার্নিভালে স্বাগতম！এখানকার স্বপ্নের কোনো সমাপ্তি নেই, এখানকার আনন্দ কখনো সমাপ্তি পায় না！」\nজনতার মধ্যে, একজন জীর্ণ পোশাক পরা, কিন্তু অবিশ্বাস্য রকম বড় বোঝা বহনকারী বণিক তোমার দিকে হাত নাড়াল, সে পাশের বোঝাটায় চাপড় দিল, কাছে এসে গলা নামিয়ে তোমাকে বিনিময় প্রথার আমন্ত্রণ জানাল, সেই পুরনো কাপড়ের থলেটি তার কথার সাথে সাথে আলতোভাবে দুলতে লাগল, আর মাঝে মাঝে কটকট শব্দও করতে লাগল।"
  },
