  },
  Event_142000_Desc = {
    Text = "বায়ু বয়ে যায় প্রান্তরের উপর দিয়ে, চারদিক নিস্তব্ধ, শুধু গাছের পাতার মর্মর শব্দ।\nহঠাৎ, তুমি কোনো কিছুর কলকল প্রবাহের শব্দ শুনতে পেলে, শব্দ অনুসরণ করে এগিয়ে গেলে, তীব্র মিষ্টি-রক্তের গন্ধ আগেই এসে আঘাত করল, তুমি অবশেষে সেই জলের শব্দের উৎস স্পষ্ট দেখতে পেলে—— এটি একটি মানত-কূপ, লাল রঙে পরিপূর্ণ, অসংখ্য মানুষের রক্ত সেই কূপে উত্থান করছে, যেন তরলের নিচে কিছু একটা লাফিয়ে বেরিয়ে আসতে চাইছে।\nশব্দটি তোমার হৃদয়ের গভীরে অনুরণিত হলো：「তোমার রক্ত নৈবেদ্য দাও, আমি তোমাকে আশীর্বাদ করব।」"
  },
