  Event_142001_Desc = {
    Text = "বায়ু প্রবাহিত হয় প্রান্তরের উপর দিয়ে, চারদিকে নিস্তব্ধতা, শুধু গাছের পাতার মর্মর শব্দ ভেসে আসে।\nঅজান্তেই তুমি একটি প্রাচীন বেদির সামনে এসে পড়ো, বিশাল মূর্তি উঁচু থেকে তোমার দিকে দৃষ্টি নিক্ষেপ করে, যেন তোমার হাত থেকে কিছু নিয়ে নিতে চায়। তুমি বেদির ঠিক নিচে অস্পষ্ট লেখা দেখতে পাও——「得失相称」।"
