  Event_142002_Desc = {
    Text = "তুমি একটি চত্বরে এসে পৌঁছাও, অনেক মানুষ ব্যস্তভাবে ছুটে চলেছে, হয়তো এখানে কিছু মজাদার জিনিস খুঁজে পাওয়া যাবে।\nউষ্ণ আলোয় আলোকিত একটি ছোট ভবন চত্বরের এক কোণে নীরবে দাঁড়িয়ে আছে, মনে হচ্ছে এটি একটি উন্নত ক্লাব, কিন্তু দেয়ালে ঝোলানো গাঢ় রঙের ফলকে স্পষ্টভাবে লেখা আছে 「本店只为生物以外的存在服务。」"
  },
  Event_142002_Name = {
    Text = "বিশেষ ক্লাব"
  },
  Event_142003_ChoiceDesc1 = {
    Text = "[একবার টানুন]একটি উপসর্গ কার্ড পান"
  },
  Event_142003_ChoiceDesc2 = {
    Text = "[চলে যান]75 কালো মুদ্রা পান"
  },
  Event_142003_Desc = {
    Text = "তুমি একটি অত্যন্ত জমজমাট জায়গায় এসে পৌঁছাও, সকলের মুখে সুখের হাসি, এলোমেলোভাবে মিটমিট করা রঙিন আলো রাতের অন্ধকারকে কোণঠাসা করে ফেলেছে। আর সর্বত্র দৃশ্যমান সাইনবোর্ডে লেখা রয়েছে: 「কার্নিভালে স্বাগতম! এখানকার স্বপ্নের কোনো সমাপ্তি নেই, এখানকার আনন্দের কোনো সমাপ্তি নেই!」\nতুমি লক্ষ্য করো পথের পাশে একটি লটারির দোকান রয়েছে, চারদিকে মানুষের ভিড়, সকলের দৃষ্টি ভালোভাবে ঢেকে রাখা বড় পুরস্কারের দিকে নিবদ্ধ—দোকানদার জোরেশোরে এর বিরলতা প্রচার করছে, আর মানুষজন পরস্পর প্রতিযোগিতা করে এতে অংশ নিচ্ছে।"
  },
  Event_142003_Name = {
    Text = "লটারি চ্যালেঞ্জ"
  },
  Event_142004_ChoiceDesc1 = {
    Text = "[একটু ব্যবহার করি]"
  },
  Event_142004_ChoiceDesc2 = {Text = "[Leave]"},
  Event_142004_Desc = {
    Text = "বায়ু প্রান্তরের উপর দিয়ে বয়ে গেল, চারদিকে নিস্তব্ধতা, শুধু গাছের পাতার মর্মর শব্দ ভেসে আসছে।\nহঠাৎ, তুমি একটি জীর্ণ খড়ের ছাউনি দেখতে পেলে, যার মাঝখানে একটি নেহাই রাখা আছে, পাশে অনেক মরিচা ধরা ধাতব অস্ত্র পড়ে আছে — মনে হচ্ছে এটি বহুদিন ধরে পরিত্যক্ত একটি কামারশালা। নেহাইয়ের পাশে বিস্তারিত ব্যবহারবিধি রাখা আছে, যা তোমাকে জানাচ্ছে যে তুমি এখানে রেলিক রেখে রূপান্তরিত করতে পারবে।"
  },
  Event_142004_Name = {
