  },
  Event_142005_ChoiceDesc3 = {Text = "[Leave]"},
  Event_142005_Desc = {
    Text = "অন্যদের উল্লাস তোমার জয় ঘোষণা করল, কোলাহলপূর্ণ জনস্বরের মাঝে তুমিও অবশেষে তাদের মতোই, এই সর্বস্ব বাজি রাখা অদ্ভুত স্বপ্নে মগ্ন হয়ে গেলে। তুমি হাতের চিপগুলোর দিকে তাকালে, যেন সেগুলো তোমার জন্য গৌরব বয়ে আনা সবচেয়ে বিশ্বস্ত সঙ্গী, জুয়ার টেবিলের গভীর থেকে ফিসফিস ভেসে এল, কোনো এক অস্পষ্ট অনুরোধ নিয়ে：「আরেকবার, আরেকবার জিতে নাও।」"
  },
  Event_142005_Name = {
    Text = "কোলাহলময় ক্যাসিনো"
  },
  Event_142013_ChoiceDesc1 = {
    Text = "[বড় বাজি]50% সম্ভাবনায় এলোমেলো রৌপ্য সৃষ্টি পাবে এবং পুনরায় বাজি ধরবে, 50% সম্ভাবনায় 75 কালো মুদ্রা পাবে এবং এলিট যুদ্ধে প্রবেশ করবে"
  },
  Event_142013_ChoiceDesc2 = {
    Text = "[ছোটতে বাজি]50% সম্ভাবনায় এলোমেলো রূপালি সৃষ্টি পাবে এবং পুনরায় বাজি ধরবে, 50% সম্ভাবনায় 75 কালো মুদ্রা পাবে এবং এলিট যুদ্ধে প্রবেশ করবে"
  },
  Event_142013_Desc = {
    Text = "সার্ভিস স্টাফ অপরিবর্তিত হাসি বজায় রেখে ডাইস কাপ তুলল, স্পষ্ট শব্দ প্রতিধ্বনিত হল, অন্য খেলোয়াড়রা একে একে তাদের পছন্দ করে নিল। 「বাজি রাখা হলে সরে যান।」 সে বলল, 「দয়া করে বাজি ধরুন——」"
  },
  Event_142013_Name = {
    Text = "কোলাহলময় ক্যাসিনো"
  },
  Event_142073_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142073_Desc = {
    Text = "পরিচারক ডাইসের ঢাকনা তুলে ধরল, মাত্র কয়েক সেকেন্ডের জন্য, বাতাস যেন স্থবিরতায় আটকে গেল। উত্তর প্রকাশের মুহূর্তে, তুমি উল্লাস ও আর্তনাদ একসাথে মিশে যেতে শুনলে। ভাগ্য তোমাকে আশীর্বাদ করেনি, টেবিলে নিঃশব্দে পড়ে থাকা কয়েকটি ডাইস তোমার বিপরীত উত্তর দিল। তুমি শেষবারের মতো চারদিকে একবার চোখ বুলালে, সেই উন্মাদনায় মত্ত জুয়াড়িদের দিকে তাকালে। এবার যাওয়ার সময়।"
  },
  Event_142073_Name = {
    Text = "কোলাহলময় ক্যাসিনো"
  },
  Event_142074_ChoiceDesc1 = {
    Text = "[যুদ্ধে প্রবেশ করো]"
  },
  Event_142074_Desc = {
    Text = "যখন তুমি প্রত্যাশায় ভরা মনে জুয়ার টেবিলের দিকে একদৃষ্টিতে তাকিয়ে ছিলে, হঠাৎ তোমার হাত শক্ত করে আটকে গেল, মাথা তুলে দেখলে ক্যাসিনোর বস উপর থেকে তোমার দিকে তাকিয়ে আছে, নিয়ম না মানা সব অতিথিকে বের করে দিতে প্রস্তুত। মুহূর্তের মধ্যে, সমস্ত দৃষ্টি শুধু তোমার উপর কেন্দ্রীভূত হলো — বিস্মিত, শত্রুভাবাপন্ন, আর পরিস্থিতি উপভোগ করা......তুমি বুঝলে, একজন মানুষ হয়তো অনেকবার প্রতারণা করতে পারে, কিন্তু যতক্ষণ একবার আবিষ্কার হয়, সম্পূর্ণ সর্বনাশ অনিবার্য।"
  },
  Event_142074_Name = {
    Text = "কোলাহলময় ক্যাসিনো"
  },
  Event_142103_ChoiceDesc1 = {Text = "[Leave]"},
