  Event_142118_ChoiceDesc2 = {Text = "[Leave]"},
  Event_142118_Desc = {
    Text = "বণিক তোমার দেওয়া জিনিসটি হাতে নিয়ে চাঁদের আলোয় বারবার উল্টেপাল্টে দেখল, চোখ দুটো যেন বেরিয়ে আসার জোগাড়। তুমি অনেকক্ষণ অপেক্ষা করলে, তারপর সে মুখে হাসি ফুটিয়ে ব্যাগ থেকে একটা মরচে-ধরা লোহার বাক্স বের করল। 「এসো, খুলে দেখো — এটা এখনকার সবচেয়ে জনপ্রিয় ব্লাইন্ড বক্স।」\nতুমি সেটা খুললে, কিন্তু আবিষ্কার করলে ভেতরে শুধু কিছু হতাশাজনক কালো চিহ্ন। বণিক হাত ঘষতে ঘষতে অনুতাপভরা চোখে জানাল যে আরেকবার চেষ্টা করা যেতে পারে।"
  },
