  Event_142119_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142119_Desc = {
    Text = "বণিক তোমার দেওয়া জিনিসটি হাতে নিয়ে চাঁদের আলোয় বারবার উল্টেপাল্টে দেখল, চোখ দুটো যেন বেরিয়ে আসার জোগাড়। তুমি অনেকক্ষণ অপেক্ষা করলে, তারপর সে মুখে হাসি ফুটিয়ে ব্যাগ থেকে একটা মরচে-ধরা লোহার বাক্স বের করল। 「এসো, খুলে দেখো — এটা এখনকার সবচেয়ে জনপ্রিয় ব্লাইন্ড বক্স।」\nতুমি সেটা খুললে, আর ভেতরে কোনো একটা জিনিস পড়ে রইল।"
  },
  Event_142119_Name = {
    Text = "জীর্ণবেশী ভ্রাম্যমাণ বণিক"
  },
  Event_142120_ChoiceDesc1 = {
    Text = "[বিনিময় প্রথা]1টি সোনালী নিদর্শন সরাও, 50% সম্ভাবনায় 3টির মধ্যে 1টি ক্রোনো পেন্ডুলাম পাও, 50% সম্ভাবনায় 3টির মধ্যে 1টি আশীর্বাদপ্রাপ্ত রেলিক পাও"
  },
  Event_142120_ChoiceDesc2 = {Text = "[Leave]"},
  Event_142120_Desc = {
    Text = "তুমি আবার ব্লাইন্ড বক্সটি খুললে, কিন্তু আবিষ্কার করলে তোমার কাঙ্ক্ষিত জিনিস এবারও নেই। বণিক তাড়াতাড়ি ক্ষমাপ্রার্থী হাসি দিয়ে আরেকটি লোহার বাক্স বের করে দুই হাতে তোমার সামনে ধরল।\n「রাগ করো না, অতিথি! আমি কসম খাচ্ছি, এবার নিশ্চিত অসাধারণ কিছু আছে......」 মুখে এ কথা বলতে বলতে সে চুপিচুপি একটা হাত সরিয়ে তোমার দিকে বাড়িয়ে দিল, 「অবশ্যই, মূল্যবান জিনিসের বিনিময়ে মূল্যবান জিনিসই চাই।」"
  },
  Event_142120_Name = {
    Text = "জীর্ণবেশী ভ্রাম্যমাণ বণিক"
  },
  Event_142138_ChoiceDesc1 = {
