  Event_142167_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142167_Desc = {
    Text = "তিন দফা ব্যবহারের পর, নেহাইটি সম্পূর্ণরূপে দেবে গেছে এবং হাতুড়িটিও ঘষে ঘষে ক্ষয় হয়ে গেছে, মনে হচ্ছে আর ব্যবহার করা সম্ভব নয়।"
  },
  Event_142167_Name = {
    Text = "কামারশালা"
  },
  Event_142235_ChoiceDesc1 = {
    Text = "[আমি দৃঢ়ভাবে এগিয়ে যাব】「বিশুদ্ধতা」 অর্জন করো：সকল কমান্ড কার্ড ২০ স্তরের স্থায়ী শক্তিবৃদ্ধি লাভ করে"
  },
  Event_142235_ChoiceDesc2 = {
    Text = "[আমি পালাব না】 「উন্নীতকরণ」 অর্জন করুন：রূপালি চাবির সীমা、উন্মাদনার সীমা স্থায়ীভাবে 20% হ্রাস পাবে"
  },
  Event_142235_Desc = {
    Text = "তোমার চোখের সামনে হঠাৎ একটা কুয়াশা নেমে এলো, পৃথিবী ঝাপসা হতে শুরু করল, বিভ্রান্তির মাঝে তোমার মনের গভীর থেকে একটি কণ্ঠস্বর ভেসে উঠল：\n「তুমি কি এগিয়ে যেতে চাও？」"
  },
  Event_142235_Name = {
    Text = "শেষ স্টেশন আসন্ন"
  },
  Event_142925_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142925_Desc = {
    Text = "হলের কর্মীরা পারিশ্রমিক গ্রহণ করে তোমাকে মৌলিক সেবা প্রদান করল। তারা তোমার দেওয়া জিনিসগুলো একটি অন্ধকার কক্ষে নিয়ে গেল, প্রহরার সময়টা বেশি দীর্ঘ ছিল না, সে যখন আবার আবির্ভূত হল, জিনিসগুলো ট্রেতে ফিরিয়ে রাখা হয়েছিল, মনে হচ্ছিল আগের চেয়ে কিছুটা আলাদা।"
  },
  Event_142925_Name = {
    Text = "বিশেষ ক্লাব"
  },
  Event_142926_ChoiceDesc1 = {
    Text = "[একটি সোনালী নিদর্শন মুছুন]（সোনালী নিদর্শন থাকা আবশ্যক）"
  },
  Event_142926_ChoiceDesc2 = {
    Text = "[শক্তিবৃদ্ধি（Forged）রেলিক নির্বাচনযোগ্য]"
  },
  Event_142926_ChoiceDesc3 = {Text = "[Leave]"},
  Event_142926_Desc = {
    Text = "「রেলিকের সংখ্যা」「রেলিক তালিকা বেছে নিন」 পরীক্ষা করুন"
  },
  Event_142927_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142927_Desc = {
    Text = "হলের কর্মীরা পারিশ্রমিক গ্রহণ করে তোমাকে বিলাসবহুল সেবা প্রদান করল। তারা যত্নসহকারে তোমার জিনিসপত্র একটি বাক্সে রেখে একটি অন্ধকার কক্ষে নিয়ে গেল। তুমি দীর্ঘক্ষণ অপেক্ষা করলে, যতক্ষণ না সে আবার আবির্ভূত হয়ে দুই হাতে জিনিসপত্র তুলে ধরল, তার মুখের ভাব আগের মতোই শান্ত।"
  },
  Event_142927_Name = {
    Text = "বিশেষ ক্লাব"
  },
  Event_142928_ChoiceDesc1 = {
    Text = "[সর্বাধিক 2টি জাগরণকারী বেছে নিন অ্যালিমাস পূর্ণ করতে]"
  },
  Event_142928_ChoiceDesc2 = {
    Text = "[অবশ্যই 2টি জাগরণকারী বেছে নিতে হবে অ্যালিমাস পূর্ণ করতে]"
  },
  Event_142928_ChoiceDesc3 = {Text = "[Leave]"},
  Event_142928_Desc = {
    Text = "পরীক্ষা 「条件选择唤醒体」"
  },
  Event_142929_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142929_Desc = {
    Text = "গবেষক তোমাকে ঘিরে বারবার চক্কর দিলেন, দীর্ঘক্ষণ মনোযোগ দিয়ে পর্যবেক্ষণ করলেন, তারপর কাজ শুরু করলেন—তিনি তোমার মতামত জিজ্ঞেস করেননি। কিছুক্ষণ পরে, যখন তুমি এই অদ্ভুত গবেষণাগার ছেড়ে যাওয়ার প্রস্তুতি নিচ্ছিলে, তুমি স্পষ্ট বুঝতে পারলে যে তুমি অনেক কিছু হারিয়েছ, কিন্তু তিনি হাততালি দিয়ে তোমাকে অভিনন্দন জানালেন：「এটাই বিবর্তনের সত্যিকারের সারমর্ম！」"
  },
