  Event_142933_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142933_Desc = {
    Text = "তুমি পাহাড়সম নৈবেদ্যের স্তূপ থেকে একটু নিয়ে দ্রুত সরে পড়লে, যাওয়ার সময় মূর্তির চোখ যেন একটু নড়ে উঠল।"
  },
  Event_142933_Name = {
    Text = "লাভ-ক্ষতির বেদি"
  },
  Event_142934_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142934_Desc = {
    Text = "তুমি প্রতিরক্ষার দিকে মনোযোগ দিয়ে প্রশিক্ষণ নিয়েছ, প্রতিদ্বন্দ্বীর অতর্কিত আক্রমণের মুখে তুমি বারবার অস্ত্র দিয়ে রুখে দিয়েছ, তোমার প্রতিরক্ষা ক্ষমতা এবং প্রতিক্রিয়া উভয়ই উন্নত হয়েছে।"
  },
  Event_142934_Name = {
    Text = "বিশেষ প্রশিক্ষণের সময়"
  },
  Event_142935_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142935_Desc = {
    Text = "গবেষক হাতমোজা পরে, আলমারি থেকে কিছু অদ্ভুত আকৃতির যন্ত্রপাতি নিয়ে তোমার সামনে কিছুক্ষণ নাড়াচাড়া করলেন। তিনি ঠিক কী করলেন তুমি জানো না, কিন্তু মনে হলো সত্যিই একটু হালকা লাগছে।"
  },
  Event_142935_Name = {
    Text = "বিবর্তনবিদ"
  },
  Event_142936_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142936_Desc = {
    Text = "তুমি কোনো নির্দিষ্ট দিক বেছে নাওনি, বরং নিজের শারীরিক সীমা উপেক্ষা করে অন্যদের সাথে অনুশীলন করে গেছ, যতক্ষণ না সকলে ক্লান্তিতে ভেঙে পড়েছে। তুমি জানো যে তুমি অনেকটা উন্নতি করেছ, কিন্তু একইসাথে, তুমি এর মূল্যও চুকিয়েছ।"
  },
