    Text = "বিশেষ প্রশিক্ষণের সময়"
  },
  Event_142937_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142937_Desc = {
    Text = "তুমি ব্যাগ থেকে এলোমেলোভাবে কিছু জিনিস নিয়ে নৈবেদ্য দিলে এবং সমতুল্য পুরস্কার পেলে।"
  },
  Event_142937_Name = {
    Text = "লাভ-ক্ষতির বেদি"
  },
  Event_142938_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142938_Desc = {
    Text = "তুমি কিছু মূল্যবান নৈবেদ্য উৎসর্গ করলে এবং সমতুল্য পুরস্কার পেলে।"
  },
  Event_142938_Name = {
    Text = "লাভ-ক্ষতির বেদি"
  },
  Event_142939_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142939_Desc = {
    Text = "তুমি তার গবেষণা পদ্ধতি নিয়ে সন্দেহে পূর্ণ ছিলে, একটি বিতর্কের পর তিনি রাজি হলেন তোমাকে নিজে এই যন্ত্রপাতি ব্যবহার করতে দিতে, অন্য উপায়ে「বিবর্তন」অন্বেষণ করতে।\nএকই সরঞ্জাম, কিন্তু তুমি ভুলক্রমে যা「মুছে ফেলা」উচিত ছিল তা প্রচুর পরিমাণে「বৃদ্ধি」করে ফেললে, চলে যাওয়ার আগে তুমি গবেষকের আর্তনাদ শুনতে পেলে।"
  },
  Event_142939_Name = {
    Text = "বিবর্তনবিদ"
  },
  Event_142940_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142940_Desc = {
    Text = "হলের কর্মীরা তোমাকে বিনামূল্যে সেবা প্রদান করল। তারা তোমার দেওয়া জিনিসগুলো একটি অন্ধকার কক্ষে নিয়ে গেল, কিছুক্ষণ পরে সে ফিরে এল এবং জিনিসগুলো তোমার হাতে ফিরিয়ে দিল, একটি কথাও না বলে।"
  },
  Event_142940_Name = {
    Text = "বিশেষ ক্লাব"
  },
  Event_142941_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142941_Desc = {
    Text = "তুমি ইচ্ছা পূরণের পুকুরে প্রচুর রক্ত উৎসর্গ করলে, পুকুরে একটি মূল্যবান উপহার ভেসে উঠল।"
  },
  Event_142941_Name = {
    Text = "রক্তঝরনা"
  },
  Event_142942_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142942_Desc = {
    Text = "তুমি আক্রমণের দিকে মনোযোগ দিয়ে প্রশিক্ষণ নিয়েছ, ইস্পাতের সংঘর্ষে তোমার আঘাতের কৌশল এবং গতি উভয়ই উন্নত হয়েছে।"
  },
  Event_142942_Name = {
    Text = "বিশেষ প্রশিক্ষণের সময়"
  },
  Event_142943_ChoiceDesc1 = {Text = "[Leave]"},
  Event_142943_Desc = {
    Text = "তুমি ইচ্ছা পূরণের পুকুরে সামান্য রক্ত উৎসর্গ করলে, পুকুর থেকে একটি উপহার ভেসে উঠল।"
  },
  Event_142943_Name = {
    Text = "রক্তঝরনা"
  },
  Event_142944_ChoiceDesc1 = {
    Text = "[রেলিক আপগ্রেড বেছে নিন]"
  },
  Event_142944_ChoiceDesc2 = {
    Text = "[এলোমেলোভাবে রেলিক আপগ্রেড করুন]"
  },
  Event_142944_ChoiceDesc3 = {
    Text = "[চলে যান（পরীক্ষা）]"
  },
  Event_142944_Desc = {
    Text = "「আপগ্রেড রেলিক ফিচার」 পরীক্ষা করুন, রেলিক নিজেই যোগ করে"
  },
  Event_146258_ChoiceDesc1 = {
    Text = "[তাকে আহ্বান করো】অভিশপ্ত নিদর্শন「(RelicConfig.Arg1)」অর্জন করো, 「(Skill.Arg2)」দ্বারা সংক্রমিত হও"
  },
  Event_146258_ChoiceDesc2 = {
    Text = "[তাদের সাড়া দাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_146258_ChoiceDesc3 = {
    Text = "[Ignore Them] 50টি কালো চিহ্ন অর্জন করো"
  },
  Event_146258_Desc = {
    Text = "বেদির উপরে, জুলিয়েটের সাদা আলখাল্লা ঘন ধোঁয়ায় ডুবে ছিল, ধূপের ছাই মিশে ছিল এক ধরনের মিষ্টি-কাঁচা গন্ধের সাথে।\n「প্রদীপবাহক জগতের পাপীদের প্রতি করুণা করেন,」 তার কণ্ঠস্বর উচ্চ ছিল না, তবু স্পষ্টভাবে মন্দিরময় ফিসফিসানো প্রার্থনাকে ছাপিয়ে গেল, 「যেমন স্নেহময়ী মা কোলের শিশুর প্রতি করুণা করেন।」\nবেদির উপরের নৈবেদ্য মোমবাতির আলোয় তেলতেলে চকচক করছিল, সরু সরু নীলাভ ধোঁয়া তার রেখা বেয়ে বাঁকিয়ে উঠছিল, নিচে দাঁড়ানো মানুষগুলোর মুখ ঝাপসা করে দিচ্ছিল।\nক্যাস্টর সেই দুলতে থাকা ধোঁয়ার আড়াল থেকে পলাক্সের দিকে তাকাল, সে ভক্তদের মাঝে দাঁড়িয়ে ছিল, চোখ নামানো, মুখে প্রশিক্ষিত, যথার্থ ভক্তির ভাব।"
  },
  Event_146258_Name = {
    Text = "পুরনো স্বপ্ন Ⅲ"
  },
  Event_146259_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146259_Desc = {
    Text = "গায়ে মাখবেন না, এ শুধু তুষার-বাতাসের গর্জন, বরফ-হ্রদের দীর্ঘশ্বাস, অথবা পর্বতশ্রেণীর শোকগাথা।\nএ হলো শুকিয়ে যাওয়া মৃত ডালপালার, পরস্পরের গায়ে ঘষা খাওয়ার ফিসফিসানি।\nতারা চিরন্তন বিষাদে গুনগুন করে, বরফের ফাটলে সমাহিত প্রতিটি পথিকৃতের জন্য।"
  },
  Event_146259_Name = {
    Text = "বরফ হ্রদের আরিয়া"
  },
  Event_146260_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146260_Desc = {
    Text = "যদি পরম সমতা ন্যায্যতা হয়, তাহলে হেলট-ক্যাটেনা কি তোমাদের মতো সমানভাবে ইচ্ছা পূরণের সুযোগ পাওয়ার অধিকার রাখে?\nতাহলে, সে তোমাদের আগে এগিয়ে গিয়ে এমনকি প্রতিযোগীদের তাড়িয়ে দেওয়ার যে কাজ করেছে, সে বিষয়ে তোমার কি নির্বিকার থাকা উচিত?\n「অথবা আর আজেবাজে চিন্তা না করে, তাড়াতাড়ি চড়তে থাকো!」 কানের কাছে কারাবুর ডাক ভেসে এল।"
  },
  Event_146260_Name = {
    Text = "অদ্ভুত ন্যায্যতা"
  },
  Event_146261_ChoiceDesc1 = {
    Text = "[পর্বত ভয় পায় ক্ষুধাকে]"
  },
  Event_146261_ChoiceDesc2 = {
    Text = "[পর্বত ভয় পায় হারানোকে]"
  },
  Event_146261_ChoiceDesc3 = {
    Text = "[পর্বত ভয় পায় মৃত্যুকে]"
  },
  Event_146261_Desc = {
    Text = "তুমি পর্বতের দেহের উপর দিয়ে হেঁটে চলো।\nপর্বতের কম্পন তার গোপন রহস্য উন্মোচন করে।\nপর্বতের লোভ, পর্বতের ভয় নির্ধারণ করে।"
  },
  Event_146261_Name = {
    Text = "পর্বতের রহস্য"
  },
  Event_146262_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146262_Desc = {
    Text = "তুমি মসৃণ ও নরম পশমের আনন্দ উপভোগ করছ、তুমি নিজের আকাঙ্ক্ষার মধ্যে বন্দী হয়ে পড়েছ।\nতুমি এর স্পর্শে বেশ সন্তুষ্ট।\nবাহ্যিক রূপের নিচে আসলে কী আছে、সেটা কি সত্যিই গুরুত্বপূর্ণ?"
  },
  Event_146262_Name = {
    Text = "লুকিয়ে চলা কালো বিড়াল"
  },
  Event_146263_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146263_Desc = {
    Text = "তুমি চুপচাপ লাল সুতোর প্রান্তটা নিয়ে নিজের কব্জিতে বেঁধে নিলে।\nপলাক্সও একইভাবে করল, আর দুটো শিশুর হাত শীঘ্রই সেই সরু লাল সুতোয় একসাথে বাঁধা পড়ে গেল।\nএতে একই সময়ে খোঁজার এলাকা ছোট হয়ে গেল বটে, তবে তোমাদের একসাথে বাঁচতে ও মরতে হবে, তাই না?\nবাকিটা ভাগ্যের হাতেই ছেড়ে দাও।"
  },
  Event_146263_Name = {
    Text = "পুরনো স্বপ্ন Ⅰ"
  },
  Event_146264_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146264_Desc = {
    Text = "「আমি অবশ্যই জানি এটা কতটা কঠিন, প্রিয় শিশু।」\n「কিন্তু পৃথিবী কখনো কারো জন্যই সহজ ছিল না।」\n「একদিন না একদিন, সেই প্রজাপতিটি তোমার হাতের তালু থেকে উড়ে যাবে, তারপর চিরতরে অদৃশ্য হয়ে যাবে।」"
  },
  Event_146264_Name = {
    Text = "মায়া না বাস্তব"
  },
  Event_146265_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146265_Desc = {
    Text = "উইলিয়াম চোখ তুলল, দৃষ্টি দ্রুত তোমার উপর দিয়ে সরে গিয়ে দূরে তুষারে ঢাকা পর্বতশিরায় স্থির হলো।\n「তুমি এমন কিছু করোনি যার জন্য ক্ষমা চাইতে হবে,」 সে গম্ভীরভাবে বলল, 「কিছু প্রশ্ন আমার নিজের, এবং শুধু আমাকেই সেগুলোর উত্তর দিতে হবে।」\n「তবে তোমার তীক্ষ্ণতা ও অন্তর্দৃষ্টির জন্য ধন্যবাদ।」"
  },
  Event_146265_Name = {
    Text = "কোমল নিমজ্জন"
  },
  Event_146266_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146266_Desc = {
    Text = "উইলিয়ামের দৃষ্টি কাঁপছিল।\nতুমি মুখ খুললে, কিন্তু কিছুই বললে না। এই মুহূর্তে নীরবতাই সর্বোত্তম পছন্দ।\nতোমাদের মধ্যে যে মূল্যবান নিঃশব্দ বোঝাপড়া রয়েছে, তা নষ্ট করো না।"
  },
  Event_146266_Name = {
    Text = "কোমল নিমজ্জন"
  },
  Event_146267_ChoiceDesc1 = {
    Text = "[Leave] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_146267_Desc = {
    Text = "「ফিরিয়ে দাও, ফিরিয়ে দাও, ওটা আমার শক্তি!」\nপর্বত কাঁদছে, পর্বত আর্তনাদ করছে।\nপর্বত সহ্য করতে পারছে না, তার সব কিছু কেড়ে নেওয়া হয়েছে।"
  },
  Event_146267_Name = {
    Text = "পর্বতের রহস্য"
  },
  Event_146268_ChoiceDesc1 = {
    Text = "[পালানো চালিয়ে যান】৩টি কমান্ড কার্ড থেকে ১টি বেছে নিয়ে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」, সংক্রমিত করুন 「(Skill.Arg2)」"
  },
  Event_146268_ChoiceDesc2 = {
    Text = "[শান্তভাবে অপেক্ষা করুন】 ৩টি থেকে ১টি অরিসন বেছে নিন"
  },
  Event_146268_ChoiceDesc3 = {
    Text = "[ধীরে ধীরে চলে যান】"
  },
  Event_146268_Desc = {
    Text = "「দাদা、সাবধান、একটা কাক দেখছে।」\nকিশোর ক্যাস্টর পলাক্সকে পিঠে বহন করে দ্রুত এগিয়ে চলল、উদ্বিগ্ন দৃষ্টিতে প্রতিটি সন্দেহজনক কোণ স্ক্যান করল、কিন্তু কিছুই খুঁজে পেল না।\n「উপরে।」\nতুমি সারা শরীর কেঁপে উঠে মাথা তুলে তাকালে।\nছাদের কোণের ছায়ায় একটি কাক নিঃশব্দে বসে ছিল、তার চারদিকে ঘোরানো অদ্ভুত চোখগুলো সবই তোমার দিকে স্থির হয়ে গেল।"
  },
  Event_146268_Name = {
    Text = "পুরনো স্বপ্ন Ⅱ"
  },
  Event_146269_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146269_Desc = {
    Text = "প্রশিক্ষণের সতর্কবাণী মনে রেখেছিলে, নিরাপত্তা দড়ির উপর নির্ভর করা যাবে না।\nলাথি মেরে কোনোমতে নিজেকে স্থির রাখলে।\nকিন্তু ব্যাকপ্যাকের ভেতর থেকে কিছু একটা পাহাড়ের গা বেয়ে গড়িয়ে পড়ল, দেখতে না পাওয়া একটি ক্ষুদ্র বিন্দুতে পরিণত হলো।\nআর গুরুত্বপূর্ণ নয়, অন্তত তুমি এখনও বেঁচে আছ।"
  },
  Event_146269_Name = {
    Text = "নীরব পতন"
  },
  Event_146270_ChoiceDesc1 = {
    Text = "[Listen Closely] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_146270_ChoiceDesc2 = {
    Text = "[Plug Ears] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_146270_Desc = {
    Text = "ঝড়ো বাতাস পাথরের দেয়ালে আছড়ে পড়ছে, বরফের গভীর থেকে ভেসে আসা অস্পষ্ট ফাটলের শব্দের সাথে মিশে একটানা বিলাপে পরিণত হচ্ছে।\nজনমানবহীন উচ্চতায় দাঁড়িয়ে, হঠাৎ তুমি পাহাড়ের সুর স্পষ্ট শুনতে পেলে।\nএটি ছিল বিষণ্ণ ও গম্ভীর, মৃতদের জন্য নিবেদিত একটি গান গুনগুন করছিল।"
  },
  Event_146270_Name = {
    Text = "প্রকৃতির মায়া সুর"
  },
  Event_146271_ChoiceDesc1 = {
    Text = "[এটি ঘণ্টার শব্দ] 「(Skill.Arg1)」 সংক্রমিত হন, এলোমেলো ১টি কমান্ড কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg2)」"
  },
  Event_146271_ChoiceDesc2 = {
    Text = "[এটি খাবার] 「(Skill.Arg1)」 সংক্রমিত হন, এলোমেলো ১টি কমান্ড কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg2)」"
  },
  Event_146271_ChoiceDesc3 = {
    Text = "[এটি কুকুরের প্রত্যাশা] এলোমেলো ১টি কমান্ড কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg1)」"
  },
  Event_146271_Desc = {
    Text = "「পাভলভ ঘণ্টা বাজাতেন, তারপর কুকুরকে খাবার দিতেন। দীর্ঘদিন ধরে এভাবে চলতে থাকলে, শুধু ঘণ্টা বাজালেই কুকুর লালা ঝরাতে শুরু করে।」\n「তাহলে, কুকুরের লালা ঝরানোর আসল কারণটা কী?」"
  },
  Event_146271_Name = {
    Text = "পাভলভের প্রতিফলন"
  },
  Event_146272_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146272_Desc = {
    Text = "স্মৃতিতে ফিরে যেও না।\nউইলিয়াম তোমার হাতের নাগালের মধ্যেই আছে।\nযন্ত্রণাকে তোমাকে গ্রাস করতে দিও না।\nঅনেক কিছু মিস করেছ, কিন্তু এখনো দেরি হয়নি।"
  },
  Event_146272_Name = {
    Text = "পরপার থেকে আগত"
  },
  Event_146273_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146273_Desc = {
    Text = "「হাতের মুঠো বন্ধ করো।」\n「একসময় যা ছিল মনোরম, তোমার হাতের মুঠোয় তা কেবল একদলা কালো কাদায় পরিণত হবে।」"
  },
  Event_146273_Name = {
    Text = "মায়া না বাস্তব"
  },
  Event_146274_ChoiceDesc1 = {
    Text = "[আগের মতো ফিরে যাও] ৫০ কালো মুদ্রা অর্জন করুন"
  },
  Event_146274_ChoiceDesc2 = {
    Text = "[আদর করুন] ৭৫ কালো মুদ্রা অর্জন করুন，「(Skill.Arg2)」 সংক্রমিত করুন"
  },
  Event_146274_Desc = {
    Text = "「মিঁয়াও।」সবুজ চোখের একটি কালো বিড়াল নরম পায়ে হেঁটে তোমার পায়ের সাথে গা ঘষল।\nএকই সাথে、「N」 উধাও হয়ে গেল।"
  },
  Event_146274_Name = {
    Text = "লুকিয়ে চলা কালো বিড়াল"
  },
  Event_146275_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146275_Desc = {
    Text = "তুমি কথা বললে না, শুধু সেই দৃষ্টিটাকে ধোঁয়া পেরিয়ে পলাক্সের চোখে গিয়ে পড়তে দিলে, এক ইঞ্চিও সরাতে রাজি হলে না।\nসেও সরে গেল না, ছোট ভাই সবসময় এমনই, একগুঁয়েমি সবচেয়ে গভীরে লুকিয়ে রাখতে পছন্দ করে, আগে মাথা নোয়াতে নয়।\nমন্দিরের ভেতরের মন্ত্রোচ্চারণ, ধূপের ছাইয়ের গন্ধ, করুণা ও বলিদান নিয়ে জুলিয়েটের বাণী——হঠাৎ সব কিছু অনেক দূরের মনে হলো, যেন শুধু তোমরা দুজনই বাকি, এই মন্দিরময় মিথ্যা দয়ার আড়াল পেরিয়ে, দীর্ঘ সময়ের ব্যবধান পেরিয়ে, পরস্পরের দিকে তাকিয়ে।"
  },
  Event_146275_Name = {
    Text = "পুরনো স্বপ্ন Ⅲ"
  },
  Event_146276_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146276_Desc = {
    Text = "এই মুহূর্তে, তুমিই তোমার ফ্যাকাশে ও দীর্ঘ স্মৃতির একমাত্র প্রহরী।\nউইন্ডিগো শুকনো ডালের মতো হাত বাড়িয়ে দিল, আঙুলের ডগা সরাসরি তোমার বুক লক্ষ্য করে এগিয়ে এল, কিন্তু শেষ মুহূর্তে তুমি জোর করে তা ঠেকিয়ে দিলে।\nএটি হোঁচট খেতে খেতে কুয়াশার মধ্যে পিছিয়ে গেল, কেবল একটি ভাঙা গলার প্রলাপ রেখে গেল——\n「তুমি দেরিতে হলেও স্বেচ্ছায়, সবকিছু আমাকে দিয়ে দেবে……」"
  },
  Event_146276_Name = {
    Text = "লোভী ভক্ষক"
  },
  Event_146277_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146277_Desc = {
    Text = "এটি ছিল সুদূর এক স্বপ্ন, শৈশব নামের স্বপ্ন।\nএকটু সজাগ হও। তুমি সেখানে নেই।\nতুমি আছো তুষারঝড়ের মাঝে, স্তরে স্তরে প্রদীপবাহক ভক্তদের ঘেরাওয়ের মধ্যে, আর পলাক্সের ছুরির ফলা তোমার বুকের দিকে তাক করা।"
  },
  Event_146277_Name = {
    Text = "পুরনো স্বপ্ন Ⅰ"
  },
  Event_146278_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146278_Desc = {
    Text = "「আমি মৃত্যুর আগমনকে মেনে নিই।」\n「আমি কঠিন যাত্রায় সমাহিত হতে রাজি।」\n「খাড়া পাহাড়ের পাদদেশে, আকাশ-মাটি আমার জন্য স্মৃতিস্তম্ভ গড়ে দেবে।」"
  },
  Event_146278_Name = {
    Text = "মৃত্যুর পূর্বাভাস"
  },
  Event_146279_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146279_Desc = {
    Text = "প্রতিফলন কেবল আলোর প্রতিসরণ ঘটনা মাত্র।\nটিঙ্কট যা দেখেছে, তার বেশিরভাগই সম্ভবত তার নিজের ছায়া।\nতার মাতৃগ্রহ কোটি কোটি আলোকবর্ষ দূরে, সামান্যতম পথের বিচ্যুতিও তাদের ভিন্ন ভিন্ন ছায়াপথে নিক্ষেপ করতে পারে।\nএভাবে নিজেকে সান্ত্বনা দিতে দিতে, তুমি আর পায়ের নিচের প্রতিফলনে মনোযোগ দিলে না।"
  },
  Event_146279_Name = {
    Text = "হ্রদতলের প্রতিফলন"
  },
  Event_146280_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146280_Desc = {
    Text = "নক্ষত্রপুঞ্জ থেকে। আদিকাল থেকে। মানুষের এখনও অজানা, হয়তো চিরকালের অজানা থেকে।\nতাঁর কাছে উত্তর চেয়ো না।\nতুমি মূল্য জানো না।"
  },
  Event_146280_Name = {
    Text = "বরফ হ্রদের আরিয়া"
  },
  Event_146281_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146281_Desc = {
    Text = "তুমি পা থামালে, সেই বিষণ্ণ সুর কানে ভরে নিলে।\nবাতাসের শব্দ বেহালা, তুষারকণা ড্রামের বাদ্য, দূরে বরফের স্তর ভেঙে পড়ার গর্জন হলো দীর্ঘদিন চাপা পড়া কোনো গভীর সুরের মিলন।\nএর মূল সুর বুঝতে পারছিলে না, কিন্তু জানতে যে অতীতে হোক বা ভবিষ্যতে, এই পাহাড়ে সমাহিত অগণিত পথিকের জন্য এটি বারবার বাজতে থাকবে।"
  },
  Event_146281_Name = {
    Text = "প্রকৃতির মায়া সুর"
  },
  Event_146283_ChoiceDesc1 = {
    Text = "[ঊর্ধ্বদৃষ্টি আলো】সকল জাগরণকারী ⟦P1⟧ অ্যালিমাস নিরাময় করে"
  },
  Event_146283_ChoiceDesc2 = {
    Text = "[পর্বতশীর্ষে পদার্পণ】২ জন জাগরণকারীর জাগরণ বেছে নাও"
  },
  Event_146283_Desc = {
    Text = "চূড়া মেঘের মধ্যে নীরবে আলো ছড়ায়।\nউপত্যকা, পাথরের দেয়াল, ঝড় — এখানে যা বাস করে তা কখনও মানুষের জন্য ছিল না।\nএর মাঝে থেকে, তুমি কতটা ভঙ্গুর।"
  },
  Event_146283_Name = {
    Text = "শীর্ষ স্পর্শ"
  },
  Event_146284_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146284_Desc = {
    Text = "「না, এটা তোমার দোষ নয়।」\n「তুমি শুধু চাবি দেওয়া, ভাগ্যের একটা খেলনা মাত্র।」"
  },
  Event_146284_Name = {
    Text = "লোভী ইঁদুর"
  },
  Event_146285_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146285_Desc = {
    Text = "「বুঝতে পারলাম, তুমি বস্তুনিষ্ঠ অভিজ্ঞতা সংক্ষেপ করতে পারদর্শী। কিন্তু ভুলো না, কখনো কখনো একই রকম বাহ্যিক রূপের আড়ালে আসলে ভিন্ন ভিন্ন সম্ভাবনা লুকিয়ে থাকে।」 ঘণ্টার শব্দ হাসতে হাসতে দূরে মিলিয়ে গেল।"
  },
  Event_146285_Name = {
    Text = "পাভলভের প্রতিফলন"
  },
  Event_146286_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146286_Desc = {
    Text = "যদি পাপ-পুণ্যের প্রতিফল ন্যায্যতা হয়, তাহলে পাপ-পুণ্য বিচার করবে কে?\nআনুবিসের সেই দাঁড়িপাল্লা কি?\nযদি পরলোকের মাধ্যাকর্ষণ পদার্থবিজ্ঞানের নিয়ম মেনে চলে, তাহলে তোমার হৃদয় সেই পালকের চেয়ে হালকা হবে কিনা সে বিষয়ে তোমার তেমন আস্থা নেই।"
  },
  Event_146286_Name = {
    Text = "অদ্ভুত ন্যায্যতা"
  },
  Event_146287_ChoiceDesc1 = {
    Text = "[জিজ্ঞাসাবাদ] রৌপ্য সৃষ্টি「(RelicConfig.Arg1)」 অর্জন করে, 「(Skill.Arg2)」 সংক্রমিত করে"
  },
  Event_146287_ChoiceDesc2 = {
    Text = "[নীরবতা] রৌপ্য সৃষ্টি「(RelicConfig.Arg1)」 অর্জন করে, 「(Skill.Arg2)」 সংক্রমিত করে"
  },
  Event_146287_ChoiceDesc3 = {
    Text = "[ক্ষমাপ্রার্থনা] ২৫ কালো মুদ্রা অর্জন করে"
  },
  Event_146287_Desc = {
    Text = "「উইলিয়াম সিনিয়র, যখন সবাই ওয়েন্ডিগোর মোহে আচ্ছন্ন হয়ে পড়েছিল, আপনিই মনে হয় প্রথম জেগে উঠেছিলেন। এখন সরাসরি ওয়েন্ডিগোর দলের মুখোমুখি হতে হবে, কোনো কৌশল কি শেখাতে পারবেন?」\nউইলিয়ামের চোখের রঙ সামান্য নড়ে উঠল, তার দৃষ্টিতে তুমি অস্পষ্টভাবে দেখতে পেলে এক দুর্বোধ্য বিভ্রান্তি, বিষাদ এবং প্রশান্তি।\nযেন আলো-ভেদী সমুদ্রের জলে ডুবে, দুলতে দুলতে অন্ধকার সমুদ্রের তলদেশে ডুবে যাচ্ছে।\n「দুঃখিত, আমি সম্ভবত কোনো সাহায্য করতে পারব না।」"
  },
  Event_146287_Name = {
    Text = "কোমল নিমজ্জন"
  },
  Event_146288_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146288_Desc = {
    Text = "「মানবিকতাহীন、কতটাই না মানবিকতাহীন।」কালো ছায়ামূর্তি মাথা নাড়তে নাড়তে আবির্ভূত হলো、「সত্য হয়তো হাড়-কাঁপানো বিষ। কখনো কখনো মায়াকে মেনে নেওয়াই বর্তমানের সুখ টিকিয়ে রাখে、তাই না?」"
  },
  Event_146288_Name = {
    Text = "লুকিয়ে চলা কালো বিড়াল"
  },
  Event_146290_ChoiceDesc1 = {
    Text = "[হত্যাকারী কে] 「(Skill.Arg1)」 সংক্রমিত হন, এলোমেলো ১টি কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg2)」"
  },
  Event_146290_ChoiceDesc2 = {
    Text = "[এটা আমার ভুল] সংক্রমিত 「(Skill.Arg1)」，এলোমেলো ১টি কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg2)」"
  },
  Event_146290_ChoiceDesc3 = {
    Text = "[লোভের মূল্য] ৩টি কমান্ড কার্ড থেকে ১টি বেছে অরিসন অর্জন করে：「(EnchantConfig.Arg1)」"
  },
  Event_146290_Desc = {
    Text = "「ছোট্ট ইঁদুর, হামাগুড়ি দেয়, হামাগুড়ি দেয়। নর্দমা, কালো আর লম্বা। হঠাৎ পনিরের গন্ধ পেল।」\n「ছোট্ট ইঁদুর, পনির টেনে, বাড়ির দিকে ছোটে। মাথা ঝিমঝিম করে, মাথা ঝিমঝিম করে।」\n「দরজা ঠেলে খোলে, দরজা ঠেলে খোলে, ঘরে নিঃশব্দ নীরবতা।」\n「ভাই-বোনেরা মাটিতে শুয়ে, পেটে সবার একটা করে ছিদ্র, একটা ছিদ্র।」"
  },
  Event_146290_Name = {
    Text = "লোভী ইঁদুর"
  },
  Event_146291_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146291_Desc = {
    Text = "তুমি হাঁটু গেড়ে বসলে, তার গালের অশ্রুর দাগ মুছিয়ে দিলে, সেই অশ্রু সত্যি না মিথ্যা তা জিজ্ঞেস করলে না।\n「সত্যি হোক বা মিথ্যা，」তুমি বললে，「আর কাউকে প্রমাণ করে দেখানোর দরকার নেই。」\nকারাবু মুখ খুলল, সেই প্রস্তুত করা, এড়িয়ে যাওয়ার জন্য রাখা রসিকতাটা শেষ পর্যন্ত বেরিয়ে এল না।\nতার অশ্রু কোনো পূর্বসংকেত ছাড়াই বাঁধ ভেঙে পড়ল, তোমার হাতের পিঠে ঝরে পড়ল।"
  },
  Event_146291_Name = {
    Text = "কুকরোডাইলের অশ্রু"
  },
  Event_146292_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146292_Desc = {
    Text = "「না জিজ্ঞেস করাই ভালো। কিছু প্রশ্নের উত্তর জানার দরকার নেই।」"
  },
  Event_146292_Name = {
    Text = "লোভী ইঁদুর"
  },
  Event_146293_ChoiceDesc1 = {
    Text = "[সরবে সতর্ক করুন] রৌপ্য সৃষ্টি「(RelicConfig.Arg1)」অর্জন করুন, 「(Skill.Arg2)」সংক্রমিত হন"
  },
  Event_146293_ChoiceDesc2 = {
    Text = "[শুনতে থাকুন] সমস্ত জাগরণকারী ৫০ অ্যালিমাস নিরাময় করে, 「(Skill.Arg1)」সংক্রমিত হন"
  },
  Event_146293_ChoiceDesc3 = {
    Text = "[কাঁধ ঝাঁকিয়ে উপেক্ষা করুন] ৩টি থেকে ১টি অরিসন অর্জন করুন"
  },
  Event_146293_Desc = {
    Text = "নারাকার পতনস্থলে শুধু অন্ধকার।\nকাদার মধ্য থেকে ভেসে আসে আর্দ্র এক সুর, যেন বরফশীতল ফ্যাকাশে দুটি হাত, কোমলভাবে তোমার গালে বুলিয়ে যাচ্ছে।\nসে মৃদুস্বরে গেয়ে ওঠে, 「এসো, রাতের নীরবতায় আমার কাছে এসো。」"
  },
  Event_146293_Name = {
    Text = "আকাঙ্ক্ষার কণ্ঠস্বর"
  },
  Event_146294_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146294_Desc = {
    Text = "তুমি মাথা নামিয়ে নিলে, সেই ধোঁয়াকে পলাক্সের অবয়ব ঝাপসা করে দিতে দিলে, তার এই মুহূর্তের অভিব্যক্তিসহ সব কিছু ধূসর-সাদা কুয়াশায় লুকিয়ে গেল।\nএটাই সবচেয়ে নিরাপদ——তুমি নিজেকে বললে, দেখার দরকার নেই, ভাবার দরকার নেই।\nজুলিয়েটের বক্তৃতা এখনও কানের পাশে বয়ে চলল, তুমি নিজের একে অপরের উপর রাখা হাতের দিকে একদৃষ্টে তাকিয়ে রইলে, একটি কথাও বললে না।\nঅনুষ্ঠানের ঘণ্টা বাজার পরেই কেবল চোখ তুলতে সাহস পেলে।\nআর পলাক্স তার ভক্তির ভঙ্গি ধরে রেখেছিল।\nদীর্ঘ সময় ও কল্পনার আড়ালে, সেই মুহূর্তে কিছু একটা সরে গিয়েছিল কিনা তুমি বুঝতে পারলে না।"
  },
  Event_146294_Name = {
    Text = "পুরনো স্বপ্ন Ⅲ"
  },
  Event_146295_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146295_Desc = {
    Text = "「পলাক্স——」 তোমার কণ্ঠস্বর গলা থেকে বেরোতেই নিজেই তা গিলে নিলে, কেবল একটুখানি শ্বাসের মতো অবশিষ্ট রইল, ধূপের ধোঁয়ায় মিলিয়ে গেল।\nপাশের ভক্তদের মন্ত্রপাঠের ঢেউ থামল না, তবু কয়েকটি দৃষ্টি অলক্ষ্যে ভেসে এল।\nপলাক্স হঠাৎ শক্ত হয়ে গেল, চোখের গভীরে এক মুহূর্তের জন্য আতঙ্ক ঝলকে উঠল, তারপর দ্রুত সেই প্রশিক্ষিত বিনম্র ভাবটি দিয়ে ঢেকে গেল।\nসে সাড়া দিল না, কেবল চোখ নামিয়ে রইল, কিন্তু হাতের আঙুলগুলো হাতার ভেতরে চুপিচুপি মুঠো হয়ে গেল——তুমি জানো, সে শুনেছে।"
  },
  Event_146295_Name = {
    Text = "পুরনো স্বপ্ন Ⅲ"
  },
  Event_146297_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146297_Desc = {
    Text = "অন্তত সেই মুহূর্তে, তুমি চোখের সামনে তাকে একা দল থেকে বিতাড়িত হতে দেখতে পারোনি।\nএই মুহূর্তে যে সমস্যার সমাধান দরকার, তা এই মুহূর্তের নিজের উপরই ছেড়ে দাও।"
  },
  Event_146297_Name = {
    Text = "কৌশলের মধ্যে কৌশল"
  },
  Event_146298_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146298_Desc = {
    Text = "「পলাক্স, আমাদের ভিন্ন দিকে যাওয়াই ভালো। এভাবে, আমাদের বনের সীমানা খুঁজে পাওয়ার সম্ভাবনা বেশি থাকবে।」\n「তাহলে তুমি আমাকে কীভাবে খুঁজে পাবে, দাদা?」\nধূসর সময়ের আড়াল থেকে তুমি তার বিষণ্ণ মুখটি দেখতে পাও। যন্ত্রণার অনুভূতি তোমার হৃদয়কে মুচড়ে ধরে। তুমি গভীরভাবে শ্বাস নাও, ধীরে ধীরে ছেড়ে দাও।\n「আমরা যমজ। আমরা একে অপরের হৃদস্পন্দন পড়তে পারি।」\n「আমরা কখনো আলাদা হব না।」"
  },
  Event_146298_Name = {
    Text = "পুরনো স্বপ্ন Ⅰ"
  },
  Event_146299_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146299_Desc = {
    Text = "এটি বিচার করছে, এটি প্রশ্ন করছে। এটি সমস্ত প্রত্যাবর্তনহীন চ্যালেঞ্জারদের শীতল মৃত্যু দান করে।"
  },
  Event_146299_Name = {
    Text = "তুষাররেখার বিচার"
  },
  Event_146300_ChoiceDesc1 = {
    Text = "[পুনরায় শুরু】৩টি কমান্ড কার্ড থেকে ১টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，「(Skill.Arg2)」তে সংক্রমিত হন"
  },
  Event_146300_ChoiceDesc2 = {
    Text = "[এটি কঠিন】রৌপ্য সৃষ্টি「(RelicConfig.Arg1)」অর্জন করুন，「(Skill.Arg2)」তে সংক্রমিত হন"
  },
  Event_146300_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_146300_Desc = {
    Text = "কৃমি তাকে মিথ্যা শিখিয়েছিল।\nএর বাইরে, সে কখনো বেঁচে থাকতে শেখেনি।\nকিন্তু মিথ্যা শেষ পর্যন্ত মিথ্যাই, কোনো একদিন থেকে, তোমাকে তার সাহায্য ছাড়াই বেঁচে থাকতে হবে।"
  },
  Event_146300_Name = {
    Text = "মায়া না বাস্তব"
  },
  Event_146301_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146301_Desc = {
    Text = "「হ্যাঁ, কিন্তু এত ছোট্ট ইঁদুর, সে কীভাবে জানবে লোভের মূল্য কী?」"
  },
  Event_146301_Name = {
    Text = "লোভী ইঁদুর"
  },
  Event_146302_ChoiceDesc1 = {
    Text = "[লাল সুতো বাঁধুন】 ১টি কমান্ড কার্ড মুছুন, ⟦P1⟧ কালো মুদ্রা অর্জন করুন"
  },
  Event_146302_ChoiceDesc2 = {
    Text = "[লাল সুতো প্রত্যাখ্যান করুন】 ১টি কমান্ড কার্ড কপি করুন, 「(Skill.Arg1)」 সংক্রমিত হন"
  },
  Event_146302_ChoiceDesc3 = {
    Text = "[বাস্তবে ফিরে আসুন] ৩টি কমান্ড কার্ড থেকে ১টি বেছে নিয়ে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_146302_Desc = {
    Text = "প্রথম স্বপ্ন। বনের মধ্যে স্বপ্ন। দশ বছরেরও কম বয়সের দুটো শিশু, ধর্মগুরু তাদের গভীর অন্ধকার বনের মাঝে ফেলে গেছেন।\n「রাত নামলে, ঘুমন্ত বন্য জন্তুরা শিকারে বেরিয়ে পড়বে। তার আগেই পালিয়ে যাও। যে পালাতে পারবে, সেই আমার ভালো সন্তান।」\nছোট ভাই তার হাত ধরে একটুকরো লাল সুতো বের করল।\n「দাদা, চলো হাত বেঁধে নিই। তাহলে আমরা আর আলাদা হয়ে যাব না।」"
  },
  Event_146302_Name = {
    Text = "পুরনো স্বপ্ন Ⅰ"
  },
  Event_146304_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146304_Desc = {
    Text = "তুমি হাসির শব্দ শুনতে পাও।\nআনন্দের, উস্কানিমূলক, কৌতূহলে ভরপুর।\nমহাবিশ্বকে অন্বেষণ করতে মানুষ যে সর্বশক্তি ঢেলে দেয়, তা তাঁদের চোখে পিঁপড়ার আরোহণের চেয়ে বেশি কিছু নয়।"
  },
  Event_146304_Name = {
    Text = "উপেক্ষিত জন"
  },
  Event_146306_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146306_Desc = {
    Text = "এটি পবিত্র করবে। এটি গলিয়ে দেবে। এটি সমস্ত প্রত্যাবর্তনহীন আরোহীদের নিজের মধ্যে গ্রহণ করে নেবে।"
  },
  Event_146306_Name = {
    Text = "তুষাররেখার বিচার"
  },
  Event_146307_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146307_Desc = {
    Text = "তুমি আর কাকটা একটা অচলাবস্থায় আটকে গেলে।\nএটা স্পষ্ট যে এই মুখোমুখি লড়াইয়ে তুমি শেষ পর্যন্ত জয়ী হতে পারবে না।\nজুলিয়েটের বিরুদ্ধে লড়াইয়ে তোমরা যেন কখনোই জিততে পারবে না।"
  },
  Event_146307_Name = {
    Text = "পুরনো স্বপ্ন Ⅱ"
  },
  Event_146308_ChoiceDesc1 = {
    Text = "[কে আমাকে দেখছে？】এলোমেলোভাবে ১ জন জাগরণকারীকে জাগরণ করো, 「(Skill.Arg1)」দ্বারা সংক্রমিত হও"
  },
  Event_146308_ChoiceDesc2 = {
    Text = "[বর্তমানে মনোযোগ দাও】৩টি কমান্ড কার্ড থেকে ১টি বেছে নিয়ে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」"
  },
  Event_146308_Desc = {
    Text = "বরফ-ঢাকা ঝড়ো বাতাস মানুষের পদচিহ্নের সর্বোচ্চ স্থান ছাড়িয়ে হু হু করে বয়ে যায়।\nতুমি মাথা তুলে তাকাও, আরও উপরে কেবল অনন্তকাল ধরে জ্বলতে থাকা সূর্য।\nকিন্তু তুমি জানো, আরও উঁচুতে আরও দূরে কোথাও, অগণিত চোখের জোড়া রয়েছে — কেউ খোলা, কেউ বন্ধ।\nতার মধ্যে কয়েক জোড়া, নীরবে তোমার পায়ের নিচের সমগ্র পৃথিবীর দিকে দৃষ্টি নিবদ্ধ করে আছে।"
  },
  Event_146308_Name = {
    Text = "উপেক্ষিত জন"
  },
  Event_146309_ChoiceDesc1 = {
    Text = "[আমি এখনও ছাড়তে পারছি না】অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করুন, সংক্রমিত করুন 「(Skill.Arg2)」"
  },
  Event_146309_ChoiceDesc2 = {
    Text = "[আমি ইতিমধ্যে ভুলে গেছি】যেকোনো ১টি কার্ড এলোমেলোভাবে অরিসন অর্জন করে：「(EnchantConfig.Arg1)」"
  },
  Event_146309_Desc = {
    Text = "তুমি মস্তিষ্কের「স্মৃতি」সংরক্ষণকারী মডিউলটি বন্ধ করার চেষ্টা করলে।\nসেই গোপন বাক্সে লুকিয়ে আছে তোমার সমস্ত সত্তার উত্তর、তোমার সব লজ্জাজনক ভাবনা、তোমার সব অপ্রকাশিত কল্পনা।\nকিন্তু আকাঙ্ক্ষা হলো অবচেতনের এক মন্ত্র、এক মোহময় স্বপ্ন যাকে তুমি প্রতিরোধ করতে পারো না।"
  },
  Event_146309_Name = {
    Text = "অবচেতন অভিশাপ"
  },
  Event_146310_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146310_Desc = {
    Text = "উইলিয়াম তোমার দৃষ্টি এড়িয়ে গেল।\n「চেতনাই হলো মোহের বিরুদ্ধে অস্ত্র। আর প্রতিটি মানুষের জীবনের অভিজ্ঞতা তার চেতনা নির্ধারণ করে, যা প্রতিস্থাপন করা যায় না, শেখানোও যায় না।」\n「আমি শুধু তোমাকে এটুকুই বলতে পারি, নিজেকে দুর্বলতায় গ্রাস হতে দিও না।」"
  },
  Event_146310_Name = {
    Text = "কোমল নিমজ্জন"
  },
  Event_146311_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146311_Desc = {
    Text = "「বুঝতে পেরেছি, তুমি দার্শনিক হতে চাওয়া ধরনের মানুষ। কিন্তু ভুলো না, প্রত্যাশা না থাকা মানে যন্ত্রণা না থাকা নয়।」 ঘণ্টার শব্দ হাসতে হাসতে দূরে মিলিয়ে গেল।"
  },
  Event_146311_Name = {
    Text = "পাভলভের প্রতিফলন"
  },
  Event_146312_ChoiceDesc1 = {
    Text = "[Leave] 50টি কালো চিহ্ন অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গটি বিকাশ করো।"
  },
  Event_146312_Desc = {
    Text = "「ক্ষুধা, ক্ষুধা।」\nপর্বত কাঁদছে, পর্বত আর্তনাদ করছে।\nপর্বত সহ্য করতে পারছে না, তার উদর শূন্য।"
  },
  Event_146312_Name = {
    Text = "পর্বতের রহস্য"
  },
  Event_146313_ChoiceDesc1 = {
    Text = "[পাথরের দেয়ালে লাথি] ১টি কমান্ড কার্ড মুছে ফেলুন এবং Arg1 পয়েন্ট জীবন নিরাময় করুন"
  },
  Event_146313_ChoiceDesc2 = {
    Text = "[নিরাপত্তা দড়ি ধরো】সোনালী নিদর্শন「(RelicConfig.Arg1)」অর্জন করো, 「(Skill.Arg2)」দ্বারা সংক্রমিত হও"
  },
  Event_146313_Desc = {
    Text = "রঙিন মায়াবী দৃশ্য তোমার মনের মধ্যে ঘুরপাক খাচ্ছে।\n প্রথমে ছিল আলগা গুঁড়ো তুষার।\nতারপর ধসে পড়া তুষার-কার্নিশ।\nনিজেকে পিছলে পড়া থেকে আটকাতে পারছিলে না, নিরাপত্তা দড়ি ক্লিপের ঘর্ষণে চোখ ধাঁধানো স্ফুলিঙ্গ ছড়াচ্ছিল।\nকিন্তু পর্বতমালার সামনে, সেটি ছিল এতটাই ক্ষুদ্র ও ভঙ্গুর।"
  },
  Event_146313_Name = {
    Text = "নীরব পতন"
  },
  Event_146314_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146314_Desc = {
    Text = "「স্বপ্নে আমার কাছে এসো, আমাকে আবার আমার জীবন বাঁচতে দাও।」\nগ্রামোফোন একটি কান্নার শব্দ করে, তারপর শ্বাসের আওয়াজ ধীরে ধীরে অন্ধকারে মিলিয়ে যায়।\nকেবল প্রতিধ্বনি থাকে। শুধু প্রতিধ্বনি।"
  },
  Event_146314_Name = {
    Text = "আকাঙ্ক্ষার কণ্ঠস্বর"
  },
  Event_146315_ChoiceDesc1 = {
    Text = "[অনুতাপের উদয়] রৌপ্য সৃষ্টি「(RelicConfig.Arg1)」অর্জন করুন"
  },
  Event_146315_ChoiceDesc2 = {
    Text = "[সবই ভাগ্যের পরিকল্পনা] সোনালী নিদর্শন「(RelicConfig.Arg1)」অর্জন করুন, 「(Skill.Arg2)」দ্বারা সংক্রমিত হন"
  },
  Event_146315_Desc = {
    Text = "তুমি সবসময়ই জানতে যে এই যাত্রা কল্পনার মতো সহজ নয়, এই পর্বতারোহণ দলের অধিকাংশ আরোহীরই নিজস্ব গোপন উদ্দেশ্য রয়েছে।\nকিন্তু কারাবুর ক্রমশ উন্মাদ হয়ে ওঠা অহংকারী হাসির দিকে তাকাতে গিয়ে, তোমার বুকের ভেতর তবুও কাচ ভাঙার একটি শব্দ বিস্ফোরিত হলো।\nহয়তো যখন নারাকা তাকে দল থেকে বহিষ্কার করতে চেয়েছিল, তখন তোমার অন্য একটি সিদ্ধান্ত নেওয়া উচিত ছিল।"
  },
  Event_146315_Name = {
    Text = "কৌশলের মধ্যে কৌশল"
  },
  Event_146316_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146316_Desc = {
    Text = "কতজন মানুষ এখানে গ্রাস হয়ে গেছে?\nআঠালো গভীর জলাশয় কালো হাত বাড়িয়ে তোমাকে তাদের জগতে টেনে নিতে চায়।\nকিন্তু তুমি কেবল এগিয়ে চলো, আর তারাও যেন ধরে রাখতে আগ্রহী নয়, একে একে সরে যায়।\nসামনে এখনও শীর্ষচূড়া তোমার অপেক্ষায়।"
  },
  Event_146316_Name = {
    Text = "আকাঙ্ক্ষার কণ্ঠস্বর"
  },
  Event_146317_ChoiceDesc1 = {
    Text = "[ছেড়ে দিন] ২৫ কালো মুদ্রা অর্জন করুন"
  },
  Event_146317_ChoiceDesc2 = {
    Text = "[ঝুঁকে দেখুন] রৌপ্য সৃষ্টি「(RelicConfig.Arg1)」অর্জন করুন, 「(Skill.Arg2)」সংক্রমিত হন"
  },
  Event_146317_Desc = {
    Text = "টিঙ্কটের দৃষ্টি অনুসরণ করে তুমি অজান্তেই হ্রদের তলদেশে তাকিয়ে থাকো।\nসেই প্রতিফলনে এমন কী আছে যা তাকে আকর্ষণ করছে?\nকিন্তু তুমি স্পষ্ট দেখতে পাও না, বরফের উপরিভাগে ঝাপসা ছায়ায় কেবল তোমার নিজের প্রতিচ্ছবিই ভেসে ওঠে।"
  },
  Event_146317_Name = {
    Text = "হ্রদতলের প্রতিফলন"
  },
  Event_146318_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146318_Desc = {
    Text = "গ্রাস করার বিরুদ্ধে প্রতিরোধের একমাত্র উপায় হলো ত্যাগ করা।\nকেউই এমন কিছু হারাতে পারে না যা তার কখনো ছিল না।\nউইন্ডিগো দাঁত বের করে গলার গভীর থেকে অসন্তুষ্ট গর্জন করতে করতে কুয়াশার মধ্যে পিছু হটল।"
  },
  Event_146318_Name = {
    Text = "অবচেতন অভিশাপ"
  },
  Event_146319_ChoiceDesc1 = {
    Text = "[তুষার আমাকে শুদ্ধ করবে] এলোমেলোভাবে ১টি কার্ডের অরিসন মান উন্নত করুন"
  },
  Event_146319_ChoiceDesc2 = {
    Text = "[তুষার আমাকে বিচার করবে] ৩টি কমান্ড কার্ড থেকে ১টি বেছে নিন এবং অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」, 「(Skill.Arg2)」দ্বারা সংক্রমিত হন"
  },
  Event_146319_Desc = {
    Text = "সামনে রয়েছে শেষ আরোহণ, তুষাররেখা শীতল ও অন্তহীন।\nজমা বরফ এতটাই সাদা যে চোখ ধাঁধিয়ে যায়, এখানে মৃত্যুও যেন পরিষ্কার মনে হয়।"
  },
  Event_146319_Name = {
    Text = "তুষাররেখার বিচার"
  },
  Event_146320_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146320_Desc = {
    Text = "সেই দৃশ্যের কোনো বিবরণ মিস করো না।\nসেগুলো মস্তিষ্কে গেঁথে নাও।\nসেই মুহূর্তে উথলে ওঠা বিভ্রান্তি、শূন্যতা এবং তার সাথে আসা যন্ত্রণাও গেঁথে নাও।\nকখনো ভুলো না।"
  },
  Event_146320_Name = {
    Text = "পরপার থেকে আগত"
  },
  Event_146321_ChoiceDesc1 = {
    Text = "[একসাথে লড়াই】রৌপ্য সৃষ্টি「(RelicConfig.Arg1)」অর্জন করুন"
  },
  Event_146321_ChoiceDesc2 = {
    Text = "[শান্ত করুন】সোনালী নিদর্শন「(RelicConfig.Arg1)」অর্জন করুন，「(Skill.Arg2)」তে সংক্রমিত হন"
  },
  Event_146321_Desc = {
    Text = "পর্বতটি প্রচণ্ডভাবে কাঁপতে লাগল, যেন একটি মৃত্যুপথযাত্রী জীবন্ত প্রাণী।\nখণ্ড খণ্ড ফাটা পাথরের স্তর ভেদ করে ফ্যাকাশে মাংসের গিঁটযুক্ত অংশগুলো উথলে উঠল, একটির পর একটি উঁচু হয়ে পেঁচিয়ে গেল, আর কারাবুকে সজোরে আছড়ে ফেলল।\nআবার যখন সে তোমাদের সামনে এল, তার গালে তখন একটি অশ্রুর রেখা ঝুলছিল।\nএটা কি যন্ত্রণার অশ্রু?\nতুমি নিশ্চিত নও।\nঅগণিত মিথ্যা তার মুখ থেকে বেরিয়েছে, কুমিরের চোখের জলে আর কে বিশ্বাস করবে?"
  },
  Event_146321_Name = {
    Text = "কুকরোডাইলের অশ্রু"
  },
  Event_146322_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146322_Desc = {
    Text = "তুমি উত্তর খুঁজতে যাওনি, শুধু তার পাশে গিয়ে দাঁড়ালে।\n「উঠে পড়ো，」তুমি বললে，「নাটক অর্ধেক হয়েছে, মাঝপথে মঞ্চ ছেড়ে যেও না。」\nকারাবু একটু থমকে গেল, তারপর জোর করে মুখটা মুছে নিল।\nসে হোঁচট খেতে খেতে উঠে দাঁড়াল, আবার শক্ত করে অস্ত্র ধরল, কাঁধে কাঁধ মিলিয়ে সেই আবার বন্ধ হয়ে আসা বিশাল রক্তাক্ত মুখের দিকে এগিয়ে গেল।\nমিথ্যা এত বেশি বলা হয়েছে যে সে নিজেও আর বুঝতে পারছিল না কোন অশ্রুটা সত্যি আর কোনটা মিথ্যা।\nকিন্তু অন্তত এবার, কেউ সত্যি-মিথ্যা হিসাব করেনি।"
  },
  Event_146322_Name = {
    Text = "কুকরোডাইলের অশ্রু"
  },
  Event_146323_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146323_Desc = {
    Text = "「বুঝতে পারলাম, তুমি বাহ্যিক রূপ ভেদ করতে পারদর্শী। কিন্তু ভুলো না, সেই মুহূর্তের বাস্তবতায়, খাবার কেবল তোমার অভিজ্ঞতা আর কল্পনার মধ্যেই ছিল।」 ঘণ্টার শব্দ হাসতে হাসতে দূরে মিলিয়ে গেল।"
  },
  Event_146323_Name = {
    Text = "পাভলভের প্রতিফলন"
  },
  Event_146324_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146324_Desc = {
    Text = "তুমি পা ফেলার গতি কমিয়ে আনলে।\nআস্তে আস্তে, ধীরে ধীরে, নিঃশব্দে…\nএভাবেই তুমি পরের মোড়টা ঘুরে সরে পড়লে।\nসেই কাকটা কি শেষ পর্যন্ত তোমাকে ধরে ফেলেছিল?\nতুমি সেটা আর মনেই করতে পারছ না।"
  },
  Event_146324_Name = {
    Text = "পুরনো স্বপ্ন Ⅱ"
  },
  Event_146325_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146325_Desc = {
    Text = "সুর হঠাৎ থেমে যায়।\nকালো কাদার মধ্যে একজোড়া আকাঙ্ক্ষী চোখ মেলে ধরে।\nসেই চোখ দুটি ভেজা দৃষ্টিতে তোমার দিকে তাকিয়ে, এমন কথা ফিসফিস করে যা তুমি বুঝতে পারো না।\nতারপর ধীরে ধীরে, অতি ধীরে বন্ধ হয়ে যায়।"
  },
  Event_146325_Name = {
    Text = "আকাঙ্ক্ষার কণ্ঠস্বর"
  },
  Event_146326_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146326_Desc = {
    Text = "তুমি বেশিক্ষণ থামোনি, সেই সুরটাকে পেছনে ফেলে এগিয়ে গেলে, পায়ের তলায় জমা তুষার ভেঙে পড়ল, বাতাসের চেয়েও তীব্র শব্দ তুলে।\nকিন্তু যত দ্রুতই হাঁটো না কেন, সেই বিষণ্ণ সুর একগুঁয়ের মতো তোমার পিছু নিল, একটি পদক্ষেপও না ছেড়ে।\nতুমি পালাতে পারবে না——এটি এই তুষারাবৃত পর্বতের নিজস্ব শ্বাস, আর তুমি, কেবল ঘটনাক্রমে পথ পেরিয়ে যাওয়া এক ক্ষুদ্র শ্রোতা।"
  },
  Event_146326_Name = {
    Text = "প্রকৃতির মায়া সুর"
  },
  Event_146327_ChoiceDesc1 = {
    Text = "[তাহলে শুনুন] ৩টি কমান্ড কার্ড থেকে ১টি বেছে নিয়ে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，「(Skill.Arg2)」 সংক্রমিত করুন"
  },
  Event_146327_ChoiceDesc2 = {
    Text = "[পাত্তা দেওয়ার দরকার নেই] প্রতিটি জাগরণকারীর জন্য যাদের অ্যালিমাস মান ৫০ বা তার বেশি, ১৫ কালো মুদ্রা অর্জন করুন"
  },
  Event_146327_ChoiceDesc3 = {
    Text = "[Leave by Force] 3টি ওরিসনের মধ্যে 1টি অর্জন করো"
  },
  Event_146327_Desc = {
    Text = "বাতাসে মিশে আছে এক সুদূরের গানের সুর।\nসেই সুর যেন চারদিক থেকে আসছে, অথবা মাটির গভীর থেকে।\nতুমি যে দিকেই তার পিছু নাও না কেন, একই তীব্রতায় তা তোমার কানে প্রতিধ্বনিত হতে থাকে।"
  },
  Event_146327_Name = {
    Text = "বরফ হ্রদের আরিয়া"
  },
  Event_146328_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146328_Desc = {
    Text = "「হে মৃত্যুর তারা, এই মুহূর্ত তোমার জ্বলে ওঠার সময় নয়।」\n「আমার যাত্রায় এখনও এমন গন্তব্য আছে যেখানে পৌঁছাইনি।」\n「তুমি কিছুক্ষণের জন্য নিভে যাও, আজ রাতের আকাশকে আবার শান্ত করে দাও।」"
  },
  Event_146328_Name = {
    Text = "মৃত্যুর পূর্বাভাস"
  },
  Event_146329_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146329_Desc = {
    Text = "অর্থহীন অনুশোচনা ঢেউয়ের মতো উথলে ওঠে।\nমানুষকে সবসময় না চাইলেও অতীতের নিজের করা গণ্ডগোল সামলাতে হয়।"
  },
  Event_146329_Name = {
    Text = "কৌশলের মধ্যে কৌশল"
  },
  Event_146330_ChoiceDesc1 = {
    Text = "[চর্বণ]এলোমেলোভাবে 1টি জাগ্রত সত্তাকে জাগ্রত করুন, সংক্রমিত করুন「(Skill.Arg1)」"
  },
  Event_146330_ChoiceDesc2 = {
    Text = "[Refuse] 3টি প্রার্থনাগাথা থেকে 1টি খোদাই করো"
  },
  Event_146330_Desc = {
    Text = "তুষার-কুয়াশার গভীরে একটি হাড়-জিরজিরে দেহ লুকিয়ে আছে、পাঁজরের হাড় শুকনো চামড়ার থলিকে ঠেলে ধরে রেখেছে、মাথার উপর শুকনো ডালের মতো দুটি শিং কুয়াশা ভেদ করে বেরিয়ে আছে।\nতার পেট থেকে একটি ফাঁপা গুড়গুড় শব্দ ভেসে আসছে।\nতোমার দৃষ্টি তার সাথে মিলিত হওয়ার মুহূর্তে、সেই গভীর কোটরে ডুবে যাওয়া চোখে ভেঙে পড়া দৃশ্যের ঢেউ উঠল——সেগুলো তোমার স্মৃতি। সে ইতিমধ্যে স্বাদ পেয়ে গেছে।\n「এখনও যথেষ্ট নয়、এখনও যথেষ্ট নয়……」সে কর্কশ গলায় কাতরাতে কাতরাতে তোমার দিকে শুকনো হাত বাড়িয়ে দিল、তার ভঙ্গিতে কিছুটা মিনতির ছায়া।"
  },
  Event_146330_Name = {
    Text = "লোভী ভক্ষক"
  },
  Event_146332_ChoiceDesc1 = {
    Text = "[আকাশ সমাধি] রৌপ্য সৃষ্টি「(RelicConfig.Arg1)」অর্জন করুন"
  },
  Event_146332_ChoiceDesc2 = {
    Text = "[তাড়িয়ে দাও]75 কালো সিল অর্জন করুন, সংক্রমিত হন「(Skill.Arg2)」"
  },
  Event_146332_Desc = {
    Text = "দাড়িশকুন ঊর্ধ্বমুখী বায়ুপ্রবাহে ভর করে উঁচুতে চক্কর দেয়, নিজের এলাকা পাহারা দেয়।\nপর্বতারোহীদের মধ্যে এটি চিরকালই অশুভ লক্ষণ।\n「ওরা খাবার খুঁজছে। শকুন মৃত্যু আসন্নের গন্ধ পায়।」"
  },
  Event_146332_Name = {
    Text = "মৃত্যুর পূর্বাভাস"
  },
  Event_146333_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146333_Desc = {
    Text = "নিজের দুই পায়ের উপর বিশ্বাস রাখো।\nতুমি শীর্ষ জয় করবে।"
  },
  Event_146333_Name = {
    Text = "শীর্ষ স্পর্শ"
  },
  Event_146334_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146334_Desc = {
    Text = "বিচ্ছেদের ভাবনা মনে ভেসে ওঠার মুহূর্তেই তুমি বুঝলে যে তুমি আর প্রতিরোধ করতে অক্ষম、শুধু তাকে তোমার সেই দীর্ঘকাল ধুলোয় ঢাকা স্মৃতির ভান্ডারে অবাধে প্রবেশ করতে দিতে পারো।\nধবধবে সাদা কুকুরের দাঁত তোমার কানের পাশে বিঁধে গেল、একটার পর একটা দৃশ্য শিকড়সহ উপড়ে নেওয়া হলো।"
  },
  Event_146334_Name = {
    Text = "অবচেতন অভিশাপ"
  },
  Event_146335_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146335_Desc = {
    Text = "এটি তোমার দিকে ঝুঁকে পড়ল, নাকের ডগা প্রায় তোমার কপাল ছুঁয়ে গেল, এর গভীর আবেশ যেন একটুকরো মধুর ঘ্রাণ নিচ্ছে।\nসেই উথালপাতাল অস্থির অনুভূতিগুলো চেটেপুটে সাফ করে নিল।\nতৃপ্তিভরে গুনগুন করতে করতে সরে গেল, চোখের গভীরে ভেসে উঠল এক মোহময় আলো।\nতোমার বুকের মাঝে একটা শূন্যতা জন্ম নিল, তবু অদ্ভুতভাবে……অনেকটা হালকা লাগছে।"
  },
  Event_146335_Name = {
    Text = "লোভী ভক্ষক"
  },
  Event_146336_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146336_Desc = {
    Text = "「পায়ের নিচে খেয়াল রাখো, প্রতিটি পদক্ষেপ শক্ত করে ফেলো,」 নারাকার কণ্ঠস্বর তোমার কানের কাছে ভেসে ওঠে, 「সবসময় অন্যের উপর ভরসা করো না যে তারা তোমাকে সামলে নেবে।」"
  },
  Event_146336_Name = {
    Text = "উপেক্ষিত জন"
  },
  Event_146337_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146337_Desc = {
    Text = "মানুষের উচিত আকাশ স্পর্শ করা।\nলক্ষ্য মানুষকে বিপদ ভুলিয়ে দেয়।\nবিস্তৃত আকাশ-ভূমি তোমার জন্য মাথার উপরে অপেক্ষা করছে।"
  },
  Event_146337_Name = {
    Text = "শীর্ষ স্পর্শ"
  },
  Event_146338_ChoiceDesc1 = {
    Text = "[স্মৃতি দূর করুন】সোনালী নিদর্শন「(RelicConfig.Arg1)」অর্জন করুন，「(Skill.Arg2)」তে সংক্রমিত হন"
  },
  Event_146338_ChoiceDesc2 = {
    Text = "[ধরা স্বপ্ন】৩টি থেকে ১টি সোনালী নিদর্শন বেছে নিন, সংক্রমিত করুন 「(Skill.Arg1)」"
  },
  Event_146338_ChoiceDesc3 = {
    Text = "[Leave] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_146338_Desc = {
    Text = "উইলিয়ামকে হত্যাকারী ঘাতক এই মুহূর্তে তোমার চোখের সামনে।\nআলানের তাঁবুর ভেতরে, বমি-উদ্রেককারী বাতাসে, উইলিয়ামের ফ্যাকাশে মুখ, ভাসমান শরীর, আর টেবিলের উপর ব্যবচ্ছেদ করা সেই ছোট্ট লণ্ঠনটি আবার তোমার মনে ভেসে উঠল।"
  },
  Event_146338_Name = {
    Text = "পরপার থেকে আগত"
  },
  Event_146339_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146339_Desc = {
    Text = "নিরাপত্তা দড়ি ছিঁড়ে গেল।\nতুমি ধপ করে তুষারের স্তূপে পড়লে, পাঁজরের ভেতরে সব কিছু ভোঁতা ব্যথায় মারাত্মক সংকেত দিতে লাগল।\nমাথা ঘুরতে ঘুরতে চোখ খুলে দেখলে, একটি অজ্ঞাত কঙ্কাল তোমার দিকে তাকিয়ে আছে।\nতার শূন্য চোখের কোটরে, কিছু একটা ঝিকমিক করছে।"
  },
  Event_146339_Name = {
    Text = "নীরব পতন"
  },
  Event_146340_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146340_Desc = {
    Text = "পালানোর পথ নেই।\nদাঁত কামড়ে ধরে তুমি দ্রুত ছুটতে শুরু করলে, গতির জোরে নজরদারকে ফাঁকি দেওয়ার মরিয়া চেষ্টায়।\nকাকটা এক বিকট ডাক দিয়ে ডানা ঝাপটাল, তারপর অনায়াসে তোমাদের মাথার উপর দিয়ে উড়তে লাগল, এমনকি সহজেই একটা চক্কর কেটে নিল।\nবরফশীতল হতাশা তার দৃষ্টি বেয়ে শরীরের ভেতরে ঢুকে পড়ল।\nতোমরা পালাতে পারবে না।"
  },
  Event_146340_Name = {
    Text = "পুরনো স্বপ্ন Ⅱ"
  },
  Event_146341_ChoiceDesc1 = {
    Text = "[সৎকর্মের পুরস্কার] এলোমেলোভাবে ১টি কমান্ড কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg1)」"
  },
  Event_146341_ChoiceDesc2 = {
    Text = "[পরম সমতা] Arg1 পয়েন্ট সর্বোচ্চ জীবনী শক্তি বৃদ্ধি করে, 「(Skill.Arg2)」 সংক্রমিত করে"
  },
  Event_146341_Desc = {
    Text = "তুমি পাহাড়ের খাড়া দেয়ালে ঝুলে আছ, কিন্তু হঠাৎ মনে একটি অসংলগ্ন প্রশ্ন ভেসে উঠল: ন্যায্যতা কাকে বলে?"
  },
  Event_146341_Name = {
    Text = "অদ্ভুত ন্যায্যতা"
  },
  Event_146342_ChoiceDesc1 = {
    Text = "[Leave] 50টি কালো চিহ্ন অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গটি বিকাশ করো।"
  },
  Event_146342_Desc = {
    Text = "「আমি এখনও মরতে পারি না!」\nপর্বত কাঁদছে, পর্বত আর্তনাদ করছে।\nপর্বত সহ্য করতে পারছে না, লোভের কারণে সে আগামীকালের সম্ভাবনা হারিয়ে ফেলেছে।"
  },
  Event_146342_Name = {
    Text = "পর্বতের রহস্য"
  },
  Event_146343_ChoiceDesc1 = {Text = "[Leave]"},
  Event_146343_Desc = {
    Text = "তুমি নিচু হয়ে ঝুঁকলে, যতক্ষণ না তোমার গাল বরফের পৃষ্ঠ স্পর্শ করল।\nহাড় কাঁপানো শীতলতা ত্বক ভেদ করে মজ্জায় প্রবেশ করল, তুমি অনিচ্ছাকৃতভাবে কেঁপে উঠলে।\nজমাট বাঁধা বরফের স্তরের নিচে কোনো অস্পষ্ট অস্তিত্ব ধীরে ধীরে আবর্তিত হচ্ছে — জলস্রোত নাকি কোনো প্রাণী?\nযাই হোক না কেন, তোমার যাত্রার সাথে তার কোনো সম্পর্ক নেই।"
  },
  Event_146343_Name = {
    Text = "হ্রদতলের প্রতিফলন"
  },
  Event_148532_ChoiceDesc1 = {
    Text = "[আশীর্বাদ গ্রহণ】যুদ্ধ শুরু হওয়ার পর, ১টি এলোমেলো 「রূপান্তরের ফল」 তৈরি করে ডেকে রাখুন।"
  },
  Event_148532_Desc = {
    Text = "বিস্তীর্ণ তুষারভূমি দিগন্তহীন, হিমশীতল বাতাস এতটুকু শব্দও তুলতে পারছে না, কোথা থেকে এলো বলা যায় না এমন এক ছায়ামূর্তি নিঃশব্দে ভেসে উঠল, হাতে তুলে দিল একটি উষ্ণ ফল।\nমিষ্টি সুবাস কুয়াশার সাথে মিশে ঢুকে পড়ল পথিকের শীতে অসাড় হয়ে যাওয়া নাকে। \nএই তুষারভূমি বহু আগেই মৃত্যুতে ভিজে গেছে, বাতাসে ভাসছে পচন ও হিমের বমি-উদ্রেককারী গন্ধ, কেবল হাতের তালুতে এই ফলটিই রসে টলটলে ও পরিপূর্ণ, যেন কোনো তরুণীর মোহময় প্রতিশ্রুতি।"
  },
  Event_148532_Name = {
    Text = "উর্ধ্ব মরীচিকা"
  },
  Event_20778_ChoiceDesc1 = {
    Text = "[Leave It to Her] সকল জাগরণকারীরা Arg1 অ্যালিমাস লাভ করে"
  },
  Event_20778_ChoiceDesc2 = {
    Text = "[Require Support] 2 জন জাগরণকারীকে জাগরণ ঘটাও"
  },
  Event_20778_Desc = {
    Text = "「এটি মিথাগ থেকে প্রেরিত যোগাযোগ। Awakener-এর Gnosis Index-এ অস্বাভাবিক ওঠানামা সনাক্ত হয়েছে। আপনার কি সহায়তা প্রয়োজন?」"
  },
  Event_20778_Name = {
    Text = "সহায়তা যোগাযোগ"
  },
  Event_20779_ChoiceDesc1 = {Text = "[Leave]"},
  Event_20779_Desc = {
    Text = "\"জরুরি সহায়তা প্রদান করা হয়েছে। গ্রহণের পর নিশ্চিত করতে ব্রোচটি তিনবার স্পর্শ করুন।\""
  },
  Event_20779_Name = {
    Text = "সহায়তা যোগাযোগ"
  },
  Event_20780_ChoiceDesc1 = {Text = "[Leave]"},
  Event_20780_Desc = {
    Text = "দূর ভবিষ্যৎ থেকে আসা এক মায়াভ্রম, লুকিয়ে আছে এলওয়ার্থের গিরিখাতে।"
  },
  Event_20780_Name = {
    Text = "আগ্নেয়গিরির প্রেতছায়া"
  },
  Event_20781_ChoiceDesc1 = {
    Text = "[Gaze at Phantasm] সকল জাগরণকারী Arg1 অ্যালিমাস লাভ করে"
  },
  Event_20781_ChoiceDesc2 = {
    Text = "[Approach Phantasm] 2 জন জাগরণকারীকে জাগরণ ঘটাও"
  },
  Event_20781_Desc = {
    Text = "দূরে যেন কোনো আগ্নেয় শঙ্কু বিস্ফোরিত হয়েছে, আর ঝড়ো আকাশে মানুষের আকৃতির ধোঁয়া উঠছে।\nকিন্তু এটি এলওয়ার্থ, যেখানে আছে কেবল অন্তহীন সুউচ্চ তুষার পর্বত আর চুনাপাথরের কার্স্ট গুহা।\nনিরবচ্ছিন্ন এই অস্বাভাবিকতাগুলো কি তোমাকে আত্মিক বিভ্রান্তির দিকে ঠেলে দিয়েছে?"
  },
  Event_20781_Name = {
    Text = "আগ্নেয়গিরির প্রেতছায়া"
  },
  Event_20782_ChoiceDesc1 = {Text = "[Leave]"},
  Event_20782_Desc = {
    Text = "মায়াভ্রমটি মিলিয়ে যাওয়ার আগে তোমার দিকে হাত নাড়ে। কেবল ঠান্ডা তুষার আর আকাশছোঁয়া পর্বতমালা রয়ে যায়।"
  },
  Event_20782_Name = {
    Text = "আগ্নেয়গিরির প্রেতছায়া"
  },
  Event_20783_ChoiceDesc1 = {Text = "[Leave]"},
  Event_20783_Desc = {
    Text = "\"বুঝেছি। আমরা সাধারণ সম্পদ সরবরাহ করব। অনুগ্রহ করে পরীক্ষা করুন।\""
