  },
  Event_21398_Desc = {
    Text = "যন্ত্র ভেঙে গুঁড়ো, সত্য উন্মোচিত।\nকোলাহলময় জীবন শূন্যতায় মিলিয়ে যায়, আর তোমার হাতে রয়ে যায় সত্য উন্মোচনের তৃপ্তি।"
  },
  Event_21398_Name = {
    Text = "প্রত্যক্ষদর্শীর বিবরণ"
  },
  Event_21399_ChoiceDesc1 = {
    Text = "[Pick up the Photo] 3টি কমান্ড কার্ডের মধ্যে 1টিতে 「(EnchantConfig.Arg1)」 নামের প্রার্থনা খোদাই করো।"
  },
  Event_21399_ChoiceDesc2 = {
    Text = "[Check Film] 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো এবং যে প্রার্থনাগাথা খোদাই করা হবে তা বদলাও।(ব্যবহার: 1/2)"
  },
  Event_21399_Desc = {
    Text = "কৌতূহলে তাড়িত হয়ে তুমি ছায়া পুকুরের গভীরে তাকাও。\nচিত্রগুলো ডুবে আছে রক্তিম তরলের তলে, আর কালো ময়লায় আচ্ছাদিত পাপীটির মুখ তোমার মুখের সঙ্গেই হুবহু মিলে যায়।"
  },
  Event_21399_Name = {
    Text = "প্রত্যক্ষদর্শীর বিবরণ"
  },
  Event_21400_ChoiceDesc1 = {Text = "[Leave]"},
  Event_21400_Desc = {
    Text = "যন্ত্র ভেঙে গুঁড়ো, সত্য উন্মোচিত।\nকোলাহলময় জীবন শূন্যতায় মিলিয়ে যায়, আর তোমার হাতে রয়ে যায় সত্য উন্মোচনের তৃপ্তি।"
  },
  Event_21400_Name = {
    Text = "প্রত্যক্ষদর্শীর বিবরণ"
  },
  Event_21811_ChoiceDesc1 = {Text = "[Leave]"},
  Event_21811_Desc = {
    Text = "\n「পঁচিশ বছর... হ্যাঁ, সে আমাকে পঁচিশ বছর ঘুম পাড়িয়ে রেখেছিল।」\nমেয়েটি গুমোট, নিচু স্বরে তোমাকে জবাব দেয়।\nজেগে উঠে সে দেখে, যারা শৈশব থেকে তার যত্ন নিয়েছিল, এই ক」বছরে তারা সবাই পূর্ণাঙ্গ সাগরচারী হয়ে গেছে।\nএখন আর কেউ তার যন্ত্রণা বোঝে না, কেউ তার কষ্টের খোঁজ নেয় না, তাকে একা ফেলে রেখেছে সেই উপাসনালয়ে।\nসে বরং চাইত, তার ঘুমের আগের দিনটিই যেন হতো 「নক্ষত্র সমন্বয়ের দিন」।"
  },
  Event_21811_Name = {
    Text = "শৃঙ্খলিত জীবন"
  },
  Event_22058_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22058_Desc = {
    Text = "\n\"না, আমি ক্ষুধার্ত নই।\"\nতুমি ভোজের উষ্ণ আমন্ত্রণ ভদ্রভাবে প্রত্যাখ্যান করলে।\nওই কিছুর জন্য তুমি কখনোই নিজের আত্মা বন্ধক রাখতে রাজি নও।"
  },
  Event_22058_Name = {
    Text = "দেহের ভোজ"
  },
  Event_22059_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22059_Desc = {
    Text = "তুমি ক্ষুধার্তভাবে রক্তক্ষরণে ভেজা স্কোনে দাঁত বসাও, গোলমরিচ মেশানো হৃদয়ের বেক করা গন্ধ ময়দার সঙ্গে মিশে পরিচিত এক সুগন্ধে তোমার ইন্দ্রিয় ভরিয়ে তোলে।\n\"শক্তি অর্জনের সবসময়ই মূল্য আছে।\"\nতুমি শেষ রক্তবিন্দুটিও পান করে ফেলো।"
  },
  Event_22059_Name = {
    Text = "দেহের ভোজ"
  },
  Event_22060_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22060_Desc = {
    Text = "তুমি ঝটপট ঝোল আর মাংস গিলে ফেললে, হাতার সঙ্গে মুখ মুছে নিলে।\nমাংস ছিল নরম, ঝোল ছিল সুস্বাদু, কিন্তু একসময় তা কার ছিল?\nএ তো কেবলই তুমি যা হারিয়েছ তার হিমশৈলের চূড়া মাত্র।"
  },
  Event_22060_Name = {
    Text = "দেহের ভোজ"
  },
  Event_22061_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22061_Desc = {
    Text = "তুমি সতর্ক দৃষ্টিতে বাতাসঘণ্টায় খোদাই করা প্রাচীন প্রার্থনাগুলো পরীক্ষা করো।\nওগুলো এমনভাবে বিকৃত, যা কল্পনারও অতীত; যেন ইচ্ছাকৃতভাবে বোঝার অযোগ্য করে রাখা হয়েছে।\nযদি বোঝা না যায়, তবে বিরক্তও করা হবে না।"
  },
  Event_22061_Name = {
    Text = "মরিচা ধরা বায়ুঘণ্টা"
  },
  Event_22062_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22062_Desc = {
    Text = "\"মন্দ না, তুমি বেশ সতর্ক।\"\nহঠাৎ, বাতাসে দুলতে থাকা ঘণ্টাধ্বনি থেকে এক সুদূরের কণ্ঠস্বর ভেসে এল।\n\"সতর্কতা তোমাকে সামান্য পুরস্কার দেবে, কিন্তু তার বেশি কিছু নয়।\""
  },
  Event_22062_Name = {
    Text = "মরিচা ধরা বায়ুঘণ্টা"
  },
  Event_22063_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22063_Desc = {
    Text = "তুমি বাতাসি ঘণ্টায় খোদাই করা প্রাচীন Orison-এ হাত রাখো।\nওগুলো মানুষের বোধের বাইরে বিকৃত হয়ে ওঠে, বোঝা যাওয়াকে অস্বীকার করে।\nভুল বোঝা মানে অশান্তি থেকে মুক্ত থাকা।"
  },
  Event_22063_Name = {
    Text = "মরিচা ধরা বায়ুঘণ্টা"
  },
  Event_22064_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22064_Desc = {
    Text = "\"“আহ, কী দুঃখজনক... মনে হয় আমার একাকী পরিবেশনাই চলতে থাকবে।” তুমি জানো না কখন বীণা আর হাতদুটো অদৃশ্য হয়ে গেছে, কিন্তু সুরটি, বয়ে চলা জলের মতো, চিরদিনের জন্য থেকে গেল তোমার হৃদয়ে।\""
  },
  Event_22064_Name = {
    Text = "বীণার প্রেতাত্মা"
  },
  Event_22065_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22065_Desc = {
    Text = "“আহ, এমন এক বন্ধুকে পাওয়া কী বিরল সম্মান!” সেই হাতগুলো উত্তেজনায় কাঁপতে থাকে, আর তুমি তাদের গতির সঙ্গে তাল মেলাতে পারো না। বহুক্ষণ আগে পরিবেশনা শেষ হয়ে গেলেও, সেই উন্মত্ত সুর এখনও তোমার হৃদয়কে আলোড়িত করে যায়।"
  },
  Event_22065_Name = {
    Text = "বীণার প্রেতাত্মা"
  },
  Event_22175_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22175_Desc = {
    Text = "প্ল্যানচেটটি আত্মবিশ্বাসের সঙ্গে নড়ছে, আর তুমি তার প্রতিটি গতিবিধি অনুসরণ করছ。\nকিন্তু মাত্র দুটি অক্ষর ইঙ্গিত করেই তা এক করুণ চিৎকারের সঙ্গে গলে গিয়ে আঠালো কালো কাদায় পরিণত হয়।"
  },
  Event_22175_Name = {
    Text = "স্পিরিট বোর্ড"
  },
  Event_22176_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22176_Desc = {
    Text = "\n「গণিত! গণিত!!」\nমহিলা দাঁত চেপে ধরল, ওরাকল বোর্ডটি দ্রুত সংখ্যাগুলোর মাঝে সরে যেতে লাগল, কাঠের কর্কশ ঘর্ষণের শব্দ তুলতে তুলতে।\n「আমার সামনে থেকে তোমার গণিত সরাও!」"
  },
  Event_22176_Name = {
    Text = "স্পিরিট বোর্ড"
  },
  Event_22177_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22177_Desc = {
    Text = "\"দাঁড়াও, দাঁড়াও!!\"\n\"আমাকে জিজ্ঞেস করো! কেন তুমি জিজ্ঞেস করছ না!\""
  },
  Event_22177_Name = {
    Text = "স্পিরিট বোর্ড"
  },
  Event_22178_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22178_Desc = {
    Text = "এত তীব্রভাবে, এত জীবন্ত স্পন্দন আগে কখনো অনুভব করিনি; কিন্তু উল্টো দিকে, আমার হৃদয়ের শূন্যতা যেন ছিঁড়ে টুকরো টুকরো হয়ে যাচ্ছে..."
  },
  Event_22178_Name = {
    Text = "অভিশপ্ত আকাঙ্ক্ষা"
  },
  Event_22179_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22179_Desc = {
    Text = "আত্মা ও প্রাণশক্তি তোমার ফুসফুস ভরে দেয়, আর তুমি নীরবতায় ভেসে উঠতে থাকো।\nজগতের শব্দ ধীরে ধীরে উদ্ভাসিত হয়, গড়ে তোলে জীবনের এক সিম্ফনি।"
  },
  Event_22179_Name = {
    Text = "লিথির প্রবাহ"
  },
  Event_22180_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22180_Desc = {
    Text = "যেমন সবসময়, ধ্বংস প্রতিশ্রুতি অনুযায়ী উপস্থিত হয়। দাহ না হওয়া অবশিষ্টাংশের নিচে মূল্যবান বস্তুগুলি সমাধিস্থ থাকে, ছায়ার ভেতরেও তীব্র দীপ্তিতে ঝলমল করে।"
  },
  Event_22180_Name = {
    Text = "সূচাগ্রের ওপারে"
  },
  Event_22181_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22181_Desc = {
    Text = "সাক্ষাৎ, বিচ্ছেদ এবং পাশ কাটিয়ে যাওয়া।"
  },
  Event_22181_Name = {
    Text = "নাক্ষত্রিক সুরলহরী"
  },
  Event_22182_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22182_Desc = {
    Text = "হৃদস্পন্দন ধীরে ধীরে মন্থর হয়ে আসে, কিন্তু হয়তো \"বিবেক\" সামান্য হলেও কিছু সান্ত্বনা খুঁজে পেয়েছে..."
  },
  Event_22182_Name = {
    Text = "অভিশপ্ত আকাঙ্ক্ষা"
  },
  Event_22183_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22183_Desc = {
    Text = "তুমি চোখ বন্ধ করলে, এই বিরল মায়াস্বপ্ন আর স্বাধীনতার মুহূর্ত উপভোগ করতে লাগলে। ধীরে ধীরে, তুমি অনুভব করলে নীরবতা থেকে বিশ্ব উন্মোচিত হচ্ছে, জীবন নিঃশব্দে বিকশিত হচ্ছে।"
  },
  Event_22183_Name = {
    Text = "লিথির প্রবাহ"
  },
  Event_22184_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22184_Desc = {
    Text = "তুমি সূচ থামিয়ে দাও, সিলভার টুকরোগুলো ঝলসে ওঠে, যখন তারা তোমার নরম তালু চিরে যায়। ধ্বংস এখনো এসে পৌঁছায়নি, কিন্তু তোমার পায়ের নিচের ছায়া ইতিমধ্যেই কালি-কালো অন্ধকারে গ্রাসিত হচ্ছে।"
  },
  Event_22184_Name = {
    Text = "সূচাগ্রের ওপারে"
  },
  Event_22185_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22185_Desc = {
    Text = "\n“তুমি পালাতে পারবে না; অন্তর্গত অশুভকে কেউ প্রতিরোধ করতে পারে না।”\nদুরভিসন্ধিময় চিন্তাগুলো তোমার স্নায়ু ছিঁড়ে ফেলার মতো টানতে থাকে, তোমাকে টেনে নিয়ে যেতে চায় অতল গহ্বরে। কিন্তু সেই যন্ত্রণাই তোমার মস্তিষ্ককে দেয় এক অভূতপূর্ব স্বচ্ছতা।\nঅশুভ তোমাকে গ্রাস করতে পারে না; তুমি তুমি-ই থাকবে।"
  },
  Event_22185_Name = {
    Text = "অযাচিত চিন্তা"
  },
  Event_22186_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22186_Desc = {
    Text = "\"কেন নয়?\"\nএকবার তুমি সেই ভয়াবহ চিন্তাগুলোকে তোষামোদকারীর আলিঙ্গনে নিলে, সব জটিলতা সহজেই মিটে যাবে, আর এই বিশ্বে আর \"নৈতিকতা\" নামের কোনো প্যারাডক্স থাকবে না।"
  },
  Event_22186_Name = {
    Text = "অযাচিত চিন্তা"
  },
  Event_22187_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22187_Desc = {
    Text = "আমার চোখের সামনে এক ঝলক সিলভার আলো দপ করে উঠল, আর এক ম্লান হাওয়া সব শব্দকে ঝেঁটিয়ে নিয়ে গেল।"
  },
  Event_22187_Name = {
    Text = "অযাচিত চিন্তা"
  },
  Event_22188_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22188_Desc = {
    Text = "চঞ্চল, শীতল এবং দূরবর্তী।"
  },
  Event_22188_Name = {
    Text = "নাক্ষত্রিক সুরলহরী"
  },
  Event_22189_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22189_Desc = {
    Text = "প্রসারণ, সংকোচন, প্রান্তসীমায়।"
  },
  Event_22189_Name = {
    Text = "নাক্ষত্রিক সুরলহরী"
  },
  Event_22190_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22190_Desc = {
    Text = "কেন না একটু বেপরোয়া হওয়া যায়?\nসব প্রতিবন্ধক ভেঙে সমাপ্তি রেখার দিকে ঝাঁপিয়ে পড়ো।\nভাবনার হ্রদে ঝড় তুললেও, সূর্যকে ধাওয়া করা ইকারুস হয়ে গেলেও, অন্তত তুমি তো তোমার লক্ষ্য অর্জন করেছ, তাই না?"
  },
  Event_22190_Name = {
    Text = "মানসিক গোলকধাঁধা"
  },
  Event_22191_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22191_Desc = {
    Text = "তোমার মস্তিষ্ক এক গোলকধাঁধা, আর তুমি তারই আরিয়াদনে।\nএই মহাবিশ্বে, তোমার চেয়ে ভালো কেউ এই গোলকধাঁধা চেনে না।\nকেউ না।"
  },
  Event_22191_Name = {
    Text = "মানসিক গোলকধাঁধা"
  },
  Event_22192_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22192_Desc = {
    Text = "সঠিক সুর মেলায়, বেসুরো ব্যবধানগুলো কিছুটা নরম হয়ে এলো।\nকিন্তু হয়তো তুমি আরও কিছু করতে পারো।"
  },
  Event_22192_Name = {
    Text = "অসঙ্গতি"
  },
  Event_22193_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22193_Desc = {
    Text = "তুমি একই সঙ্গে এক সঙ্গীতগুরু এবং এক সাধারণ বেসুরো মানুষ।\nতোমার দিশানির্দেশে স্বরলিপিগুলো নিজ নিজ ভূমিকা পালন করে, আর ডোমেইনের ভেতর অবশেষে জীবনের অনুরণন জেগে ওঠে।"
  },
  Event_22193_Name = {
    Text = "অসঙ্গতি"
  },
  Event_22194_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22194_Desc = {
    Text = "তোমার কণ্ঠ নীরবতায় গ্রাসিত হয়। নীরবতা ক্রমে আরও উচ্চকণ্ঠ ও তীব্র হয়ে ওঠে, অবশেষে ভেঙে চুরমার হয়, রেখে যায় শুধু অবশিষ্টাংশ।"
  },
  Event_22194_Name = {
    Text = "লিথির প্রবাহ"
  },
  Event_22195_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22195_Desc = {
    Text = "তুমি ফাঁদে পড়োনি। দৃঢ়ভাবে ঘুরে দাঁড়িয়ে সেখান থেকে সরে গিয়েছিলে।"
  },
  Event_22195_Name = {
    Text = "বিচরণকারী ফাটল"
  },
  Event_22293_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22293_Desc = {
    Text = "তুমি কলমটি হাতে নেওয়ার মুহূর্তে, চিঠিটি ডোমেইনের ভেতর জ্বলে ওঠে, ভস্ম ঝরে পড়ে তোমার হাতে।\nহুঁশ ফিরলে তুমি বুঝতে পারো, চিঠির সঙ্গে আরও কিছু একসাথে বিলীন হয়ে গেছে।"
  },
  Event_22293_Name = {
    Text = "স্বগতোক্তি"
  },
  Event_22294_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22294_Desc = {
    Text = "চিঠিটি ডোমেইনের ভেতর বিলীন হয়ে গেলে, তুমি এক কোমল অথচ দুর্বল উদ্বেগের অভিব্যক্তি শুনতে পাও।\n\"এমন পরিস্থিতিতেও আমাকে স্মরণ করা, তোমার শিক্ষক হিসেবে, আমার জন্য এক গৌরবের বিষয়।\nতবে, ডোমেইনের ভেতর দিয়ে হেঁটে যাওয়ার পর থেকে অনেক বেশি সময় কেটে গেছে। এখন, আমি কেবল এতটুকুই তোমাকে সাহায্য করতে পারি...\""
  },
  Event_22294_Name = {
    Text = "স্বগতোক্তি"
  },
  Event_22295_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22295_Desc = {
    Text = "ডোমেইনের ভেতরে চিঠিটি গুঁড়িয়ে যেতে যেতে, তুমি এক তড়িঘড়ি করা বিস্মিত আহ্বান শুনলে।\n\"কিপার, যদি কোনো অস্বস্তি অনুভব করো, অবশ্যই আমাকে জানিও।\nতোমার সঙ্গী হিসেবে, তোমাকে সহায়তা করতে আমি সর্বশক্তি নিয়োগ করব।\""
  },
  Event_22295_Name = {
    Text = "স্বগতোক্তি"
  },
  Event_22296_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22296_Desc = {
    Text = "ডোমেইনের ভেতর চিঠিটি বিলীন হয়ে যেতে যেতে তুমি এক শীতল দীর্ঘশ্বাস শোনো।\n“যদি পরীক্ষায় ফেল করার সময় সাহায্য চাইতে তুমি এতটাই উদগ্রীব হতে, কতই না ভালো হতো।”"
  },
  Event_22296_Name = {
    Text = "স্বগতোক্তি"
  },
  Event_22397_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22397_Desc = {
    Text = "তোমার আগমন ছায়াগুলোকে কিংকর্তব্যবিমূঢ় করে দিল। তারার আলোয়ের এক কণা তোমার পায়ের আঙুল ছুঁয়ে চলে গেল, আর জনতা হঠাৎ ছত্রভঙ্গ হয়ে গেল, তোমার হাতে রেখে গেল কেবল সবচেয়ে ঘন ছায়াটুকু।"
  },
  Event_22397_Name = {
    Text = "নাক্ষত্রিক শপথ"
  },
  Event_22398_ChoiceDesc1 = {Text = "[Leave]"},
  Event_22398_Desc = {
    Text = "কোলাহলময় হুইসপার হঠাৎ করেই থেমে যায়। কালি-কালো ছায়ারা তোমার দিকে ঘুরে দাঁড়ায়, স্থির দৃষ্টিতে তাকিয়ে থাকে। তাদের বৈশিষ্ট্যহীন মুখগুলো থেকে তুমি বিদ্রূপের এক ক্ষীণ আভাস টের পাও..."
  },
  Event_22398_Name = {
    Text = "নাক্ষত্রিক শপথ"
  },
  Event_22399_ChoiceDesc1 = {
    Text = "[শান্তভাবে পর্যবেক্ষণ]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমিত করুন「(Skill.Arg2)」"
