  Event_22399_ChoiceDesc2 = {
    Text = "[Ask Aloud] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_22399_Desc = {
    Text = "তারকা আর চাঁদের জটিল বুননে, হুইসপার থামে না কখনো।\n「এই কি সেই জন? @4-এর মানুষ...」\n「মানবদেহ, শেষ পর্যন্ত এখনো @3...」"
