  },
  Event_22411_Name = {
    Text = "ফাঁদ তৈরি"
  },
  Event_24254_ChoiceDesc1 = {Text = "[Leave]"},
  Event_24254_Desc = {
    Text = "নসিসের ঝড় তুলুকে ঘিরে রেখেছে। তুমি তার সঙ্গে চোখাচোখি করে নাও, এবং একে একে অন্ধকারের ভেতর পা বাড়াও।"
  },
  Event_24254_Name = {
    Text = "সাগর থেকে আগত"
  },
  Event_24255_ChoiceDesc1 = {Text = "[Leave]"},
  Event_24255_Desc = {
    Text = "জ্ঞানপ্রলয়ের ঝড় তুলুকে ঘিরে রেখেছে, আর অবিনাশী শোক ও অপরাধবোধ স্থান জুড়ে ছড়িয়ে পড়ছে।"
  },
  Event_24255_Name = {
    Text = "অতলের মুখোমুখি"
  },
  Event_24256_ChoiceDesc1 = {
    Text = "[Hold the Tentacle] তুলুর সাহায্য গ্রহণ করুন"
  },
  Event_24256_Desc = {
    Text = "তার মহিমান্বিত উপস্থিতি ডোমেইনের ভেতর প্রতিধ্বনিত হয়, যেন এক মহাকায় বস্তু সাগরে আছড়ে পড়েছে।\nএই শক্তি প্রাচীন, কালাতীত, সব যুগকে অতিক্রম করে।\nসৌভাগ্য যে, অন্তত এখনো তুমি তার শত্রু নও।"
  },
  Event_24256_Name = {
    Text = "সাগর থেকে আগত"
  },
  Event_24257_ChoiceDesc1 = {
    Text = "[Hold the Tentacle] টুলুর সঙ্গে যাও"
  },
  Event_24257_Desc = {
    Text = "টুলু গভীর শ্বাস নিয়ে দূরে মিরিয়ামের দিকে তাকায়।\nযেন ইতিহাস, পুরাতন বন্ধু আর নিজের জীবনকে স্মরণ করছে...\nতার মুখের জটিল অভিব্যক্তি এক মুহূর্তের জন্য ভেসে থাকে, তারপর সে মিরিয়ামের দিক থেকে দৃষ্টি সরিয়ে নেয়।\n\"চলো, তাকে রেখে যাই।\""
  },
  Event_24257_Name = {
    Text = "অতলের মুখোমুখি"
  },
  Event_24277_ChoiceDesc1 = {
    Text = "[Close the Hatch]"
  },
  Event_24277_Desc = {
    Text = "রামোনা বাইরে থেকে হুড়মুড়িয়ে ঢুকে পড়া ছাত্রটিকে ধরে ফেলল।\nওই নির্ভীক আর দৃঢ় কিপার, এলোমেলো চেহারা সত্ত্বেও, তার চশমার আড়ালের নীল চোখে যেন কুয়াশার মতো ঝাপসা দেখাচ্ছিল।\nহাতটা ধরে রাখার সেই মুহূর্ত পর্যন্ত রামোনা নিশ্চিত হতে পারেনি: তোমরা আবার একত্রিত হয়েছ।"
  },
  Event_24277_Name = {
    Text = "আনন্দময় পুনর্মিলন"
  },
  Event_24278_ChoiceDesc1 = {Text = "[Leave]"},
  Event_24278_Desc = {
    Text = "রামোনা তোমাকে ব্যাখ্যা করার কোনো সুযোগই দিল না। সে তোমাকে টেনে নিল ম্লান আলোয় ঢাকা কেবিনে, আর সাবধানে দরজাটা বন্ধ করে দিল..."
  },
  Event_24278_Name = {
    Text = "আনন্দময় পুনর্মিলন"
  },
  Event_24540_ChoiceDesc1 = {Text = "[Leave]"},
  Event_24540_Desc = {
    Text = "\"সে তোমার অটল ঢাল, তোমার হাতে ধরা তলোয়ার।\nসে তোমার সঙ্গী, সহচর, বিশ্বস্ত বন্ধু—যেভাবেই সে বদলে যাক না কেন।\""
  },
  Event_24540_Name = {
    Text = "অপরিচিত অথচ পরিচিত অস্তিত্ব"
  },
  Event_24541_ChoiceDesc1 = {Text = "[Leave]"},
  Event_24541_Desc = {
    Text = "\n「তুমি... না, তা হতে পারে না। তোমার এই অবতার তো ইতিমধ্যেই... আর আমিও, আমিও তো ইতিমধ্যেই...」\nকণ্ঠস্বরটি অবয়বের সঙ্গে সঙ্গে মিলিয়ে গেল, কুয়াশায় ভেসে রইল শুধু বেদনার দীর্ঘশ্বাস।"
  },
  Event_24541_Name = {
    Text = "পরিচিত অথচ অপরিচিত অবয়ব"
  },
  Event_24542_ChoiceDesc1 = {Text = "[Leave]"},
  Event_24542_Desc = {
    Text = "“এই পৃথিবীর জন্য, মানবতার দীপ্তির জন্য, আমাদের সব প্রিয় কিছুর জন্য।\nঅবশ্যই, সবচেয়ে গুরুত্বপূর্ণ হলো—সে তোমার জন্য।”"
  },
  Event_24542_Name = {
    Text = "অপরিচিত অথচ পরিচিত অস্তিত্ব"
  },
  Event_24543_ChoiceDesc1 = {Text = "[Leave]"},
  Event_24543_Desc = {
    Text = "তুমি এখনো কাছে পৌঁছাওনি, তবু সে তোমাকে টের পায়। সে স্থির হয়ে যায়, যেন আকস্মিক ধাক্কায়, তারপর যেন গভীর শোকে ভেঙে পড়ে।\nতুমি কিছু বলার আগেই, সে কুয়াশার সঙ্গে সঙ্গে মিলিয়ে যায়।"
  },
  Event_24543_Name = {
    Text = "পরিচিত অথচ অপরিচিত অবয়ব"
  },
  Event_24544_ChoiceDesc1 = {
    Text = "[Who is She?] 3টি কমান্ড কার্ডের মধ্যে 1টি অনুলিপি করো"
  },
  Event_24544_ChoiceDesc2 = {
    Text = "[সে কেন এমন হয়ে গেল？]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_24544_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_24544_Desc = {
    Text = "আরেক কুয়াশা, আরেক ছায়া। আগেরবারের মতো নয়, এবার তুমি প্রতিপক্ষকে স্পষ্ট দেখতে পাচ্ছ।\nএকটি অবয়ব, হুবহু তোমার মতো, তোমার মতোই ইউনিফর্ম, তোমার মতোই মুখ।\n\"তুমি জানো কেন তুমি এখানে,\" সেই ব্যক্তি বলল, \"যেমন তুমি জানো কেন সে ওই রকম হয়ে গেছে।\""
  },
  Event_24544_Name = {
    Text = "অপরিচিত অথচ পরিচিত অস্তিত্ব"
  },
  Event_24545_ChoiceDesc1 = {
    Text = "[Console] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_24545_ChoiceDesc2 = {
    Text = "[Approach] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_24545_ChoiceDesc3 = {
    Text = "[Turn and Leave] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_24545_Desc = {
    Text = "কুয়াশা তোমার পথ ঢেকে রেখেছে。\nধোঁয়াটে ছায়ার ভেতর থেকে একটি অবয়ব উদ্ভাসন হয়; তুমি চোখ কুঁচকে তাকিয়েও তার মুখ দেখতে পাও না, কেবল টুকরো টুকরো হুইসপার শুনতে পাও。\n\"কেন… কেন আমি বাঁচাতে পারি না… নিয়তি কি সত্যিই অপরিবর্তনীয়…\""
  },
  Event_24545_Name = {
    Text = "পরিচিত অথচ অপরিচিত অবয়ব"
  },
  Event_35039_ChoiceDesc1 = {
    Text = "[সহযোগীর কাছে সাহায্য চাওয়া]3টি থেকে 1টি উন্নত প্রার্থনালিপি অর্জন করুন"
  },
  Event_35039_ChoiceDesc2 = {
    Text = "[Manage the set] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো।"
  },
  Event_35039_ChoiceDesc3 = {
    Text = "[Phenomenal Frenzy] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো।"
  },
  Event_35039_Desc = {
    Text = "\"‘মাস্টার হুডিনি'র চলচ্চিত্র নির্মাণের পথপ্রদর্শক’-এ স্পষ্ট করে লেখা আছে যে ক্যাসিয়া—অর্থাৎ আমি—প্রযোজক ও পরিচালক হিসেবে পুরো চলচ্চিত্রের তত্ত্বাবধান করার দায়িত্ব ও শক্তি রাখি। সুতরাং, ক্যাসিয়ার সাহসী কর্মীরা, তোমরা এখনই তোমাদের পরবর্তী কর্মসূচি বেছে নাও!\"\n\"কর্মসূচি? দাঁড়াও, আমি কবে থেকে তোমার কর্মচারী হলাম?!\"\n\"সুযোগ কেবল একবারই কড়া নাড়ে, দ্বিধা কোরো না!\""
  },
  Event_35039_Name = {
    Text = "প্রযোজকের মিথ"
  },
  Event_35103_ChoiceDesc1 = {
    Text = "[Connect] Arg2 HP পুনরুদ্ধার করুন। [ExDesc1] [ExDesc2]"
  },
  Event_35103_ChoiceDesc2 = {
    Text = "[Meditate] একজন Awakener-কে Rouse করো।"
  },
  Event_35103_ChoiceDesc3 = {
    Text = "[Expel] সর্বোচ্চ 3টি উপসর্গ কার্ড ধ্বংস করো, এবং Arg2 সংখ্যক কালো চিহ্ন লাভ করো।"
  },
  Event_35103_Desc = {
    Text = "কুয়াশা ভারী হয়ে ঝুলে থাকে, আর তোমার ব্যাজে মিটমিট করে ফ্যাকাশে সিলভার আভা। যোগাযোগকারীটা কড়কড় শব্দ তুলে জেগে ওঠে। কেউ একজন ডাকছে।"
  },
  Event_35103_Name = {
    Text = "সংযোগস্থল"
  },
  Event_35103_Tips3 = {
    Text = "আপনার বর্তমানে কোনো উপসর্গ প্রকাশ পাচ্ছে না।"
  },
  Event_35165_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35165_Desc = {
    Text = "দ্বিধার সেই মুহূর্তে, তুমি নিজেই যোগাযোগ করলে সেই রহস্যময় উপকারকের সঙ্গে।\n\"এখন আর ফেরার পথ নেই। অনুগ্রহ করে, সম্ভ্রান্তজন, একটু উদার হোন...\"\nসিলভার যোগাযোগকারী-র ওপার থেকে ভেসে এল টগবগে হাসি, আর শেষ পর্যন্ত তারা হাসিমুখেই তোমার অনুরোধে সম্মতি দিল।\n\"তা ছাড়া, বিষয়টা যেন রামোনা’র কানে না ওঠে, খেয়াল রেখো।\""
  },
  Event_35165_Name = {
    Text = "প্রযোজকের মিথ"
  },
  Event_35236_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35236_Desc = {
    Text = "একজন প্রোডাকশন কো-অর্ডিনেটর আসলে কী করে? তুমি নসিস ট্রান্সফারের ভেতর ক্যাসিয়া অজান্তে গুঁজে দেওয়া এক গাদা নথি বের করে মনোযোগ দিয়ে পড়তে শুরু করলে।\nতারপরই তোমার মাথা ধরতে শুরু করল।\nসেট সাজানোর সময় লোটানের করা খরচ, অরিটা আর ব্রাউনের খেয়ে ফেলা স্ন্যাকস, ক্যাসিয়ার কেনা জাদু গোলকের রিইমবার্সমেন্টের আবেদন... প্রতিটি জনবসতি এক এক করে তোমার সামনে বিছিয়ে গেল, তোমাকে বাধ্য করল যন্ত্রণায় কুঁকড়ে মাটিতে বসে গণনা করতে।\nতা ছাড়া, ক্যাসিয়ার এই জাদু গোলকগুলো আসলে কী?"
  },
  Event_35236_Name = {
    Text = "প্রযোজকের মিথ"
  },
  Event_35259_ChoiceDesc1 = {
    Text = "[Dispel the Illusion] উপসর্গ [ExDesc1][ExDesc2] বিকশিত করো।"
  },
  Event_35259_ChoiceDesc2 = {Text = "[Leave]"},
  Event_35259_Desc = {
    Text = "ঝাপসা মুখগুলো হঠাৎই আবির্ভূত হয়, তোমাকে ঘিরে ধরে আর অস্তিত্বহীন স্বরযন্ত্র দিয়ে মরিয়া আর্তনাদ তোলে।"
  },
  Event_35259_Name = {
    Text = "বিভ্রম"
  },
  Event_35497_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35497_Desc = {
    Text = "চরম উন্মত্ততার যে ঘটনাটি, তার আড়ালে অবশ্যই থাকে কোনো প্ররোচক, আর 「প্ররোচক「 শব্দটি উঠলেই মনে পড়ে এক সবুজ চুলের মেয়ের কথা।\n「মিথাগ বিশ্ববিদ্যালয়ের প্রথম দালাল, হান্না পিজলি, আপনার সেবায় হাজির!「\n「এটা যদি রক্ষকের প্রথম সেবা অনুরোধ হয়, তবে আপনাকে শুধু ক্যান্টিনের তিন প্লেট কারির দামের সমান মূল্যই দিতে হবে!「"
  },
  Event_35497_Name = {
    Text = "প্রযোজকের মিথ"
  },
  Event_35887_ChoiceDesc1 = {
    Text = "[Move Forward]"
  },
  Event_35887_Desc = {
    Text = "তুমি পাল তুলো, কিন্তু তার নিচে কিছুই পাও না। যখন হুঁশ ফিরে আসে, ততক্ষণে পালটি উধাও।\nশুভ্র পাল আর এক কিশোরীর ক্ষীণ মুখচ্ছবি মিলে এক বার্তা গড়ে তোলে, যা তোমাকে মনে করিয়ে দেয়—আগামী যাত্রা যতই কঠিন হোক, তুমি একা নও।"
  },
  Event_35887_Name = {
    Text = "পাণ্ডুর পাল"
  },
  Event_35888_ChoiceDesc1 = {
    Text = "[Raise the Sail]"
  },
  Event_35888_Desc = {
    Text = "এখানে কোনো হাওয়া নেই, তবু এক নির্মল সাদা পালতোলা নৌকা শান্ত নীল সমুদ্রে অ্যাঙ্কর ফেলে দাঁড়িয়ে আছে, তার পাল গর্বভরে উঁচু করে তোলা।\nতুমি অস্পষ্টভাবে এক কিশোরীর মুখ দেখতে পাও, তার মুখাবয়ব ঝাপসা, যেন পাতলা কুয়াশার আড়াল থেকে, বা ঢেউ খাওয়া জলের পৃষ্ঠের ভেতর দিয়ে দেখা। তার উপস্থিতি আশেপাশের সবকিছু থেকে বিচ্ছিন্ন মনে হলেও, এই দৃশ্যের কেন্দ্রবিন্দু সে-ই।\nতার অবয়ব কখনো স্পষ্ট, কখনো আবছা হয়ে ওঠে, তবু কোনো সন্দেহ নেই—তুমি জানো সে কে।"
  },
  Event_35888_Name = {
    Text = "পাণ্ডুর পাল"
  },
  Event_35894_ChoiceDesc1 = {
