  },
  Event_35894_Desc = {
    Text = "মেয়েটির কণ্ঠস্বর বাতাসে মিলিয়ে যায়, বুদবুদের মতো অস্পষ্ট ও দূরবর্তী।"
  },
  Event_35894_Name = {
