  },
  Event_35895_ChoiceDesc2 = {
    Text = "[Get Far Away]"
  },
  Event_35895_Desc = {
    Text = "অঙ্গপ্রত্যঙ্গ অস্বাভাবিকভাবে ভারী লাগে, কুয়াশা নাজুক দেহটিকে শক্ত করে জড়িয়ে ধরে।"
  },
  Event_35895_Name = {
    Text = "জীবন-মৃত্যুর প্রান্তে"
  },
  Event_35896_ChoiceDesc1 = {
    Text = "[পূর্বসূরীদের পথ পড়া]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，সংক্রমিত হও「(Skill.Arg2)」"
  },
  Event_35896_ChoiceDesc2 = {
    Text = "[Write Your Own Path] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_35896_ChoiceDesc3 = {
    Text = "[Stare into Darkness] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_35896_Desc = {
    Text = "তুমি যদি একা ডোমেইন অন্বেষণ করতে, তবে পথ নিয়ে এতটা নিশ্চিত থাকতে না।\nডোমেইনের ভেতরের পদচিহ্ন তিনটি পথে ভাগ হয়ে গেছে; প্রতিটি পদক্ষেপ অদেখা ভবিষ্যৎ লিখে চলে।"
  },
  Event_35896_Name = {
    Text = "বেরোনোর পথ"
  },
  Event_35897_ChoiceDesc1 = {
    Text = "[Support Her]"
  },
  Event_35897_ChoiceDesc2 = {
    Text = "[Look at her]"
  },
  Event_35897_Desc = {
    Text = "সে বিড়বিড় করতে করতে ঘুরে এসে আপনার সামনে থামে।\nকেউ তার তন্দ্রা ভেঙেছে; তার চেতনা বাস্তবতার সঙ্গে বাঁধা, অথচ তার আত্মা রয়ে গেছে এক বিস্মৃত জগতে।"
  },
  Event_35897_Name = {
    Text = "হারানো মায়াচিত্র"
  },
  Event_35898_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35898_Desc = {
    Text = "এই অবিভাজিত অন্ধকারে এক সারি ঝাপসা পায়ের ছাপ প্রসারিত হয়েছে, যেন অদৃশ্য মরুভূমিতে রাতের পথিকের ফেলে যাওয়া চিহ্ন।"
  },
  Event_35898_Name = {
    Text = "বেরোনোর পথ"
  },
  Event_35899_ChoiceDesc1 = {
    Text = "[চলে যাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_35899_Desc = {
    Text = "তোমার চোখে প্রতিফলিত হচ্ছে দূরের এক বাতিঘর, অন্ধকারের কিনারায় একাকী দাঁড়িয়ে, ক্ষীণ অথচ দৃঢ়চেতা আলো ছড়াচ্ছে, যেন রাতের সমুদ্রে এক পথপ্রদর্শক, হারিয়ে যাওয়া আত্মাদের তীরের নীরবতার দিকে আহ্বান জানাচ্ছে।\nতুমি নিজেকে সামলাতে না পেরে তার পিছু নাও, কিন্তু হঠাৎই টের পাও, পায়ের নিচের জমিন আর কঠিন নেই।\nতুমি পা বাড়াও এক গোপন জলের স্তরে। জলের পৃষ্ঠ রেশমের মতো মসৃণ, নীরবে গ্রাস করে নিচ্ছে তোমার পদধ্বনি।"
  },
  Event_35899_Name = {Text = "পলক"},
  Event_35900_ChoiceDesc1 = {
    Text = "[Listen to Her]"
  },
  Event_35900_ChoiceDesc2 = {
    Text = "[Ignore Her]"
  },
  Event_35900_Desc = {
    Text = "তুমি আলোয়ের উৎস দেখতে পাও—ওটা এক নারী অবয়বের চরিত্র।\nতার ভিনগ্রহী-মতো মাথা থেকে একধারা জ্যোতি ঝরে পড়ছে, অজানা জীবের দিকে এক পথ বিছিয়ে দিচ্ছে।\n「প্রত্যাবর্তন... লেমু@2া-য়...」"
  },
  Event_35900_Name = {
    Text = "চিরদীপ্তি"
  },
  Event_35901_ChoiceDesc1 = {
    Text = "[Approach the Lighthouse]"
  },
  Event_35901_ChoiceDesc2 = {
    Text = "[Stay away from the Lighthouse]"
  },
  Event_35901_Desc = {
    Text = "যেখানে বাস্তবতা আর স্বপ্ন একে অপরের সঙ্গে জড়িয়ে যায়, সেই মোড় ঘুরতেই ক্ষণিকের জন্য তোমার চোখের সামনে উন্মোচিত হয় এক ভয়াবহ ঝড়ের দৃশ্যপট। যেন অদৃশ্য এক দৈত্যাকার হাত সবকিছু তুলে নিয়েছে; হাওয়া হিংস্র জন্তুর মতো গর্জে ওঠে, ধুলো আর আশাকেও একসঙ্গে ঝেঁটিয়ে নিয়ে যায়। আকাশ ভারী, দমবন্ধ করা চাপের মতো।\n\nঝড়ের কেন্দ্রবিন্দুতে দাঁড়িয়ে আছে এক বাতিঘর, যার অস্তিত্বই থাকার কথা নয়—একই সঙ্গে যেন কল্পনার ফসল, আবার প্রাচীন কিংবদন্তির অবশেষ। তা ক্ষীণ আলো ছড়ায়, নিঃসঙ্গ অথচ অবিচল, প্রলয়ংকরী ঝড়ের মঞ্চের মাঝখানে।"
  },
  Event_35901_Name = {
    Text = "ঝড়ের চোখ"
  },
  Event_35902_ChoiceDesc1 = {
    Text = "[Leave] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_35902_Desc = {
    Text = "「ডোমেইনে, চিরদীপ্তি, শুঁড়ওয়ালা মায়াভ্রম...」\nতুলু চোখ বন্ধ করে, কিছুক্ষণ ভাবনায় ডুবে থাকে, তারপর এক গভীর দীর্ঘশ্বাস ফেলে.\n「লেমুরিয়ার অভিভাবক... আমার এক অনুচর। শেষ পর্যন্ত সে তার আবেশের শৃঙ্খল থেকে পালাতে পারে না।」"
  },
  Event_35902_Name = {
    Text = "সোনা-নিলের পতন"
  },
  Event_35903_ChoiceDesc1 = {
    Text = "[Touch the Silver Light] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_35903_ChoiceDesc2 = {
    Text = "[Talk to Silverlight] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_35903_Desc = {
    Text = "কঠোরভাবে সিল করা যোগাযোগকারীটি কষ্টে খোলা হলো, ভেতর থেকে ফিকে আলো চুঁইয়ে বেরিয়ে এলো—সিল হওয়ার পর থেকে রৌপ্য আর বাইরের বিশ্বের মধ্যে সম্ভাব্য প্রথম কথোপকথন।"
  },
  Event_35903_Name = {
    Text = "মিথ্রিল স্মৃতিস্তম্ভ"
  },
  Event_35904_ChoiceDesc1 = {
    Text = "[Leave] রেলিক 「(RelicConfig.Arg1)」 অধিকার করো"
  },
  Event_35904_Desc = {
    Text = "「জ্বলজ্বলে মাথাওয়ালা এক নারী?」 এল্টনের মুখে বিস্ময়ের ছাপ ফুটে ওঠে। স্পষ্টই বোঝা যায়, কার্গো জাহাজের ডোমেইনে মাঝে মাঝে দেখা দেওয়া সেই অবয়বের কথা সে শুনেছে—কেবল—\n「যে রাতে সোনা-নিল ডুবে গেল... যেই রাতে আমি সেলেস্টকে জাগিয়ে তুললাম, ঝড়ের মধ্যে আমি এমনই এক ছায়া দেখেছিলাম।」\n「হ্যাঁ, আমি নিশ্চিত, দেখেছিলাম।」"
  },
  Event_35904_Name = {
    Text = "সোনা-নিলের পতন"
  },
  Event_35905_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35905_Desc = {
    Text = "সামনের ডোমেইন বিপদে ভরা, গভীরতা যার তল নেই।\nতোমার দৃষ্টি স্থির অদেখা বিশৃঙ্খলার ওপর; কিন্তু তা তোমাকে গ্রাস করার আগেই, পিছু ধাওয়াকারীদের সামলে নেওয়া রামোনা তোমাকে ধরে টেনে অন্য দিকে নিয়ে যায়।"
  },
  Event_35905_Name = {
    Text = "বেরোনোর পথ"
  },
  Event_35906_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35906_Desc = {
    Text = "ওটা কি তোমার রহস্যময় আত্মার ফল? তুমি যা কিছু অনুভব করছ, তা কি স্ব-সত্তা আর অতিসত্তার সংঘর্ষ?\nতুমি যত ভাবো, মাথার ভেতরের শোরগোল ততই স্পষ্ট হয়। তোমার দৃষ্টিক্ষেত্র কুয়াশা ভেদ করে, কিন্তু ভেতরের অবয়বটিকে ঠিক দেখার আগমুহূর্তেই আত্মা তোমাকে প্রত্যাখ্যান করে।"
  },
  Event_35906_Name = {
    Text = "বিপরীত ভাগ্য"
  },
  Event_35907_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35907_Desc = {
    Text = "এটি ভেতরে উথলে উঠে, নির্ভীক শক্তিতে রূপান্তরিত হয়, তোমাকে কুয়াশা ভেদ করে ভয়কে ছিন্নভিন্ন করার সমর্থন জোগায়।"
  },
  Event_35907_Name = {
    Text = "আলোকসন্ধানী"
  },
  Event_35908_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35908_Desc = {
    Text = "মন যখন একাগ্র হয় এবং অন্তরের বিশৃঙ্খলা স্তিমিত হতে থাকে, তখন বিশৃঙ্খল মায়াস্বপ্ন ধীরে ধীরে দ্রবীভূত হতে শুরু করে, ভাটার জলের মতো সরে যায়।\nশেষমেশ, মস্তিষ্কের কোলাহল বিন্দুমাত্র চিহ্ন না রেখে মিলিয়ে যায়—কিন্তু তুমি কতটুকু হারালে? তা অজানাই থেকে যায়।"
  },
  Event_35908_Name = {
    Text = "ভবিষ্যৎ সতর্কতা"
  },
  Event_35909_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35909_Desc = {
    Text = "তোমার আত্মা সম্পূর্ণভাবে হারিয়ে গেছে সেই কানে বাজতে থাকা গুঞ্জনে, মরিয়া হয়ে মুক্তি পেতে আর এই যন্ত্রণার অর্থ উদ্ধার করতে চাইছে, অথচ তুমি কেবলই চেতনার কিনারায় ঝুলে থাকতে পারছ..."
  },
  Event_35909_Name = {
    Text = "জীবন-মৃত্যুর প্রান্তে"
  },
  Event_35910_ChoiceDesc1 = {
    Text = "[Leave] 3টি সোনার রেলিকের মধ্যে 1টি অর্জন করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_35910_Desc = {
    Text = "তুমি বাতিঘর থেকে ছুটে আসা প্রতিটি আলোকরশ্মি অনুভব করো, ঝড়ের মধ্যে জ্বলে ওঠা ও লাফিয়ে ওঠা—যেন আত্মার গভীরতা থেকে আসা কোনো আহ্বান, যা তীব্রতম ভয়ের মাঝেও ঘরে ফেরার পথ দেখানোর দায়িত্ব কখনোই ত্যাগ করে না।"
  },
  Event_35910_Name = {
    Text = "ঝড়ের চোখ"
  },
  Event_35911_ChoiceDesc1 = {
    Text = "[Leave] 3টি উন্নত প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_35911_Desc = {
    Text = "ওটা কি আশার প্রতীক, নাকি ধ্বংসের অগ্রদূত?\nতুমি আর তার দিকে তাকাও না, যেন তার অস্তিত্ব কেবল নিখুঁতভাবে নির্মিত এক মায়াস্বপ্ন।"
  },
  Event_35911_Name = {
    Text = "ঝড়ের চোখ"
  },
  Event_35912_ChoiceDesc1 = {
    Text = "[Sink into Oblivion] 20টি কালো চিহ্ন গ্রহণ করো, তবে 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_35912_ChoiceDesc2 = {
    Text = "[Get Far Away]"
  },
  Event_35912_Desc = {
    Text = "তারপর, এক অদ্ভুত ধূসর পর্দা তোমার চোখ ঢেকে ফেলে। কিছুক্ষণ পর তুমি বুঝতে পারো, সেটি তোমার আধা-স্বচ্ছ উপরের চোখের পাতা।"
  },
  Event_35912_Name = {
    Text = "জীবন-মৃত্যুর প্রান্তে"
  },
  Event_35913_ChoiceDesc1 = {
    Text = "[Leave] এলোমেলো এক জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_35913_Desc = {
    Text = "তুমি এক বর্ণনাতীত অনুরণন অনুভব করো।\nকিন্তু যুক্তি তোমাকে বলে: তাকে উপেক্ষা করো।"
  },
  Event_35913_Name = {
    Text = "চিরদীপ্তি"
  },
  Event_35914_ChoiceDesc1 = {
    Text = "[চলে যাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_35914_Desc = {
    Text = "তার কথা কোনো পরিচিত শিলালিপিতে খোদাই নেই, তবু সেগুলো বাতাসে কঠিনীকরণ হয়ে ঝুলে থাকে গভীরতম অনুতাপ ও আহ্বান হিসেবে। সেগুলো যেন অন্য এক সময় থেকে ভেসে এসেছে, বছরের অবক্ষেপণ ভেদ করে, দূরবর্তী শ্বেত পাখির দেশের জন্য গভীর আকুলতা বহন করে।"
  },
  Event_35914_Name = {
    Text = "চিরদীপ্তি"
  },
  Event_35915_ChoiceDesc1 = {
    Text = "[Hold Her Hand] একটি এলোমেলো রৌপ্য সৃষ্টি-কে উন্নয়ন অর্জন করে সোনার রেলিক 「(RelicConfig.Arg1)」 তে রূপান্তর করো"
  },
  Event_35915_ChoiceDesc2 = {
    Text = "[Express Concern] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_35915_ChoiceDesc3 = {
    Text = "[Gaze at Her] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_35915_Desc = {
    Text = "মার্ফি দলের সবার পেছনে হাঁটছিল, সেলেস্টের পাশাপাশি।\nতুমি বারবার পেছন ফিরে তার দিকে তাকাতে নিজেকে আটকাতে পারছিলে না, কিন্তু মার্ফি সবসময় মাথা নিচু করে নিজের জুতোর ডগার দিকে তাকিয়ে ছিল, তার অভিব্যক্তি অজানার আড়ালে লুকিয়ে রেখেছিল।"
  },
  Event_35915_Name = {
    Text = "যন্ত্রণা ব্যবস্থাপনা"
  },
  Event_35915_Tips1 = {
    Text = "রৌপ্য সৃষ্টি এখনও অর্জিত হয়নি"
  },
  Event_35916_ChoiceDesc1 = {
    Text = "[No Way Out] 40টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 দক্ষতা বিকশিত করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_35916_ChoiceDesc2 = {
    Text = "[Embrace Reality] 25টি কালো চিহ্ন গ্রহণ করো এবং সরে যাও।"
  },
  Event_35916_Desc = {
    Text = "@1@1পুনরুজ্জীবন লাভ করে, এক আত্মা @2-এর কিনারা বেয়ে চলে, তবু পুরোপুরি মাংসকে আলিঙ্গন করে না।\nমার্ফির উদ্বিগ্ন কথা তোমার চেতনা থেকে মিলিয়ে যায়, কাকের আর্তনাদের মতো, কানে লেগে থাকে, তবু সবসময় মনের প্রতিবন্ধকে আটকে যায়।"
  },
  Event_35916_Name = {
    Text = "জীবন-মৃত্যুর প্রান্তে"
  },
  Event_35917_ChoiceDesc1 = {
    Text = "[Leave] একটি কমান্ড কার্ড নকল করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_35917_Desc = {
    Text = "সে কেবল বাস্তবতায় ভেসে থাকা এক ভূত, এক প্রাচীন খণ্ডাংশ, যাকে স্পর্শ করা যায় না, তবু যে বিস্মৃত হতে অস্বীকার করে।"
  },
  Event_35917_Name = {
    Text = "হারানো মায়াচিত্র"
  },
  Event_35918_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_35918_Desc = {
    Text = "সেই মুহূর্তে, তুমি আত্মার গভীরে এক ক্ষীণ ভাঙনের শব্দ শোনো। মিলিয়ে যাওয়া ধোঁয়ার মতো তার অবয়ব ঝাপসা হয়ে কম বাস্তব হয়ে ওঠে。\nসে সত্যিই এখানে নেই; এ কেবল দলনেতা এল্টনের স্মৃতিচারণের প্রক্ষেপণ。\nতবু, বুকের ভেতর থেকে উঠে আসা হারানোর বেদনা আর বিভ্রান্তি ভীষণ বাস্তব মনে হয়।"
  },
  Event_35918_Name = {
    Text = "হারানো মায়াচিত্র"
  },
  Event_35919_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35919_Desc = {
    Text = "তোমার আঙুলের ডগা স্পর্শ করতেই এক জটিল অনুভূতি প্লাবিত হয়—একই সঙ্গে দগ্ধকারী ও হিমশীতল।\nজগৎ যে আত্মাগুলোকে ভুলে গেছে, তারা চিরন্তনতার খোঁজে হাহাকার তোলে।"
  },
  Event_35919_Name = {
    Text = "মিথ্রিল স্মৃতিস্তম্ভ"
  },
  Event_35920_ChoiceDesc1 = {
    Text = "[Grasp the Spark] সর্বোচ্চ HP Arg1 দ্বারা বৃদ্ধি করো"
  },
  Event_35920_ChoiceDesc2 = {
    Text = "[মনের মুখোমুখি হও]এলোমেলো 2টি কমান্ড কার্ড অরিসন পাবে：「(EnchantConfig.Arg1)」，2টি「(Skill.Arg2)」সংক্রমিত করো"
  },
  Event_35920_Desc = {
    Text = "এই মহা শিকারে, গোলিয়াথের অনুসন্ধান অন্ধকারের এক জন্তুর মতো, সর্বগ্রাসী ক্ষয়ের মতো সব আশা গ্রাস করতে উদ্যত। তবু এই নিরলস ধাওয়া তোমাকে হিমায়িত করে না; বরং তোমার অন্তরের গভীরে এক স্ফুলিঙ্গ প্রজ্বলিত করে, যা বুকে বিস্তার লাভ করে আরও তীব্রভাবে জ্বলে ওঠে।"
  },
  Event_35920_Name = {
    Text = "আলোকসন্ধানী"
  },
  Event_35921_ChoiceDesc1 = {
    Text = "[Decipher It] 3টি কমান্ড কার্ডের মধ্যে 1টি অনুলিপি করো"
  },
  Event_35921_ChoiceDesc2 = {
    Text = "[এটি হয়ে ওঠো]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，「(Skill.Arg2)」সংক্রমিত করো"
  },
  Event_35921_ChoiceDesc3 = {
    Text = "[Disregard It] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_35921_Desc = {
    Text = "তুমি এক পা বাড়াতেই, এক অদৃশ্য কম্পন তোমার মনকে আঁকড়ে ধরে, তোমার দৃষ্টি জোর করে ডোমেইনের বিশৃঙ্খল ও মায়াময় সীমানার দিকে ঘুরিয়ে দেয়।"
  },
  Event_35921_Name = {
    Text = "ভবিষ্যৎ সতর্কতা"
  },
  Event_35922_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35922_Desc = {
    Text = "চোখের সামনে ঝলমলে রঙ নেচে বেড়ায়, কানে ভরে ওঠে ফিসফিস, আর অস্পষ্ট মুখওয়ালা ক্ষণস্থায়ী দৃশ্যগুলো একে অন্যের সঙ্গে জড়িয়ে যায়, যেন অজানা সব গল্পের মিছিল বয়ে যাচ্ছে। এই মায়াস্বপ্নগুলো তোমাকে বাস্তবতা থেকে বিচ্ছিন্ন করে, টেনে নিয়ে যায় এক স্বপ্নদৃশ্যের ভেতর, যা একই সঙ্গে পরিচিত এবং অপরিচিত।"
  },
  Event_35922_Name = {
    Text = "ভবিষ্যৎ সতর্কতা"
  },
  Event_35923_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35923_Desc = {
    Text = "এই কম্পন কোনো বাহ্যিক শব্দ বা শারীরিক কম্পন থেকে আসে না, বরং এক অনির্বচনীয়, গভীর অন্তর্দৃষ্টি থেকে। যেন ভবিষ্যৎ থেকে আসা কোনো আহ্বান, যা তোমার চেতনার ভেতর স্পন্দিত হচ্ছে।"
  },
  Event_35923_Name = {
    Text = "ভবিষ্যৎ সতর্কতা"
  },
  Event_35924_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35924_Desc = {
    Text = "তার হাত স্বতঃস্ফূর্তভাবে বুকে চলে যায়, শ্বাসরুদ্ধকর অনুভূতিটাকে নিয়ন্ত্রণ করার চেষ্টা করে।\nভয় তাকে দাঁত চেপে ধরতে বাধ্য করে, বুকে বিঁধে ওঠা ব্যথাকে জোর করে উপেক্ষা করতে বাধ্য করে। মার্ফির মুখে সামান্যতম বিকৃতিও দ্রুত গোপন হয়ে যায়, কাঁচা এক মুখোশের আড়ালে লুকিয়ে ফেলে সেই যন্ত্রণা।\n—যতক্ষণ না তুমি তার হাত ধরো, আর বিস্ময়ের রঙ তার অভিব্যক্তিকে রাঙিয়ে তোলে।"
  },
  Event_35924_Name = {
    Text = "যন্ত্রণা ব্যবস্থাপনা"
  },
  Event_35925_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35925_Desc = {
    Text = "\n「মার্ফি? তুমি ঠিক আছো?」\n— সে তোমার কোনো জবাব দেয় না।\nস্পর্শযোগ্য সেই অস্বাভাবিকতা তার হৃদয় ক্ষয় করে, তাকে প্রায় শ্বাস নিতে না দেওয়ার মতো করে তোলে।"
  },
  Event_35925_Name = {
    Text = "যন্ত্রণা ব্যবস্থাপনা"
  },
  Event_35926_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35926_Desc = {
    Text = "তুমি আর দ্বিধা করো না এবং পা বাড়াও ঘন কালো অজানা জীবের দিকে। তুমি যেদিকেই যাও, সেদিকেই ক্ষীণ গ্লিমারের দিকে নিয়ে যাওয়া এক পথ উন্মোচিত হতে থাকে।"
  },
  Event_35926_Name = {
    Text = "বেরোনোর পথ"
  },
  Event_35927_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35927_Desc = {
    Text = "\nতোমার সামনে এক স্পন্দিত আগুন।\nএটি উষ্ণ, সজীব, এক মিটমিট করা শীতল শিখাকে জড়িয়ে ধরে, উজ্জ্বলভাবে সেই বেসুরো শব্দগুলোকে বিতাড়িত করছে।\nহুঁশ ফিরলে তুমি দেখো, মার্ফি বিস্ময়ে তোমার দিকে তাকিয়ে আছে—\n「তুমি কি সত্যিই ঠিক আছো?」"
  },
  Event_35927_Name = {
    Text = "জীবন-মৃত্যুর প্রান্তে"
  },
  Event_35928_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35928_Desc = {
    Text = "তুমি অনুভব করো তোমার চেতনা আলগা হয়ে যাচ্ছে, ধীরে ধীরে দেহ থেকে টেনে বের করে নেওয়া হচ্ছে।\nতুমি দেখো তোমার আত্মা নাচছে সিলভার-এর চেতনার অবশিষ্টাংশের সঙ্গে, তারপর ডুবে যাচ্ছে এক অদৃশ্য অতল গহ্বরে...\nসেখানে আছে নিখাদ মায়াস্বপ্ন।"
  },
  Event_35928_Name = {
    Text = "মিথ্রিল স্মৃতিস্তম্ভ"
  },
  Event_35929_ChoiceDesc1 = {
    Text = "[Leave] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_35929_Desc = {
    Text = "তুমি আলোটির উৎস আরও অনুসন্ধান করার আগেই, তা হঠাৎ কেঁপে ওঠে এবং বাতাসে ভেঙে চুরমার হয়ে যায়।\nআলোটি ডোমেইনের ভেতর ঢেউ তুলে বাইরে দিকে বিস্তার লাভ করে।\nতারপর, আর কিছুই অবশিষ্ট থাকে না।"
  },
  Event_35929_Name = {Text = "পলক"},
  Event_35930_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35930_Desc = {
    Text = "ওটা কীভাবে তুমি হতে পারো?\nযদি ওটা তুমি হও, তবে শোক নেমে এলে সেটি কেন তোমাকে রক্ষা করল না?\nযদি ওটা তুমি হও, তবে দুঃসময়ে সেটি কেন তোমাকে সাহায্য করল না?\nতাহলে, সবই মায়াস্বপ্ন।"
  },
  Event_35930_Name = {
    Text = "বিপরীত ভাগ্য"
  },
  Event_35931_ChoiceDesc1 = {
    Text = "[Ask the Captain]"
  },
  Event_35931_ChoiceDesc2 = {Text = "[Ask Tulu]"},
  Event_35931_Desc = {
    Text = "আবারও তুমি দেখো, সেই রহস্যময় অবয়বটি বাল্কহেডের ভেতরে মিলিয়ে যায়, বিন্দুমাত্র চিহ্ন না রেখে অদৃশ্য হয়ে যায়। জ্যোতির্ময় লম্বা চুল কয়েকটি শুঁড়ের মতো ঝরে মাটিতে ছুঁয়ে থাকে。\nতুমি স্পষ্টই জানো, সে সাগরচারী না হলেও, হারানো জাতির সঙ্গে তার গভীর বন্ধন থাকা চাই।"
  },
  Event_35931_Name = {
    Text = "সোনা-নিলের পতন"
  },
  Event_35932_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35932_Desc = {
    Text = "তুমি ভীত; সবই অ্যাড্রেনালিনের কাজ।\nতুমি আশঙ্কা করো, তোমার সিদ্ধান্তগুলো এই অন্ধকারে তোমার সঙ্গে ভাগ করা আত্মাগুলোর ক্ষতি ডেকে আনতে পারে।"
  },
  Event_35932_Name = {
    Text = "আলোকসন্ধানী"
  },
  Event_35933_ChoiceDesc1 = {
    Text = "[Nowhere to Run] 25টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 দক্ষতা বিকশিত করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_35933_ChoiceDesc2 = {
    Text = "[Get Far Away]"
  },
  Event_35933_Desc = {
    Text = "প্রতিটি স্নায়ু @2-এর জন্য তীব্র আকাঙ্ক্ষায় চিৎকার করছে।"
  },
  Event_35933_Name = {
    Text = "জীবন-মৃত্যুর প্রান্তে"
  },
  Event_35934_ChoiceDesc1 = {Text = "[Chase]"},
  Event_35934_ChoiceDesc2 = {
    Text = "[Ignore It]"
  },
  Event_35934_Desc = {
    Text = "ডোমেইনের দূর প্রান্তে এক ক্ষীণ, মোহময় আলো দেখা দেয়।\nজলের ওপর নাচতে থাকা সূর্যালোকের মতো, মিটমিট করা নক্ষত্রের মতো, কিংবা মোমবাতির শিখার মতো তা ঝিলমিল করে...\nতুমি কাছে যেতেই আলোটি হঠাৎ মিলিয়ে যায়।\nমনে হয়, তা তোমাকে টেনে নিচ্ছে, যেমন স্বভাববশত প্রজাপতি টেনে যায় আগুনের দিকে।"
  },
  Event_35934_Name = {Text = "পলক"},
  Event_35935_ChoiceDesc1 = {Text = "[Leave]"},
  Event_35935_Desc = {
    Text = "এসব নিয়ে ভেবে লাভ কী?\nতুমি যেন মাঝ আকাশে ঝুলে থাকা এক পাতা, ভাগ্যের হাওয়ায় ঠেলে চলেছ। শুধু তাই।"
  },
  Event_35935_Name = {
    Text = "বিপরীত ভাগ্য"
  },
  Event_35936_ChoiceDesc1 = {
    Text = "[Self-Deprecation] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_35936_ChoiceDesc2 = {
    Text = "[Pursue] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 এবং 「(Skill.Arg3)」 বিকশিত করো।"
  },
  Event_35936_ChoiceDesc3 = {
    Text = "[Stop Thinking] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_35936_Desc = {
    Text = "জীবনের হাওয়া তোমার আত্মাকে ছুঁয়ে যায়, বাস্তবতার ঘূর্ণাবর্তে তোমাকে আলোড়িত করে কুয়াশা-ঢাকা অজানা জীবের দিকে টেনে নিয়ে যায়।\nতুমি নিজেকে সামলাতে না পেরে মাথার ভেতরের কণ্ঠকে জিজ্ঞেস করো: \"ওটা কি আমি?\""
  },
  Event_35936_Name = {
    Text = "বিপরীত ভাগ্য"
  },
  Event_36146_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36146_Desc = {
    Text = "\nঅবশেষে মার্ফি তোমার দৃষ্টি টের পায়; হয়তো তা সত্যিই অতিরিক্ত তীব্র।\nসে কয়েকবার গভীর শ্বাস নেয়, নাক দিয়ে ক্ষীণ 「হুঁ」 শব্দ বের হয়। শেষমেশ, সে সেলেস্টকে টেনে নিয়ে তোমার পেছনে ঘনিষ্ঠভাবে অনুসরণ করে।"
  },
  Event_36146_Name = {
    Text = "যন্ত্রণা ব্যবস্থাপনা"
  },
  Event_36722_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36722_Desc = {
    Text = "তোমার আঙুলের ডগা স্পর্শ করতেই এক জটিল অনুভূতি প্লাবিত হয়—একই সঙ্গে দগ্ধকারী ও হিমশীতল।\nজগৎ যে আত্মাগুলোকে ভুলে গেছে, তারা চিরন্তনতার খোঁজে হাহাকার তোলে।"
  },
  Event_36722_Name = {
    Text = "নসিস স্মারকস্তম্ভ"
  },
  Event_36723_ChoiceDesc1 = {
    Text = "[Touch it] একটি এলোমেলো জাগরণকারীকে জাগরণ করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_36723_ChoiceDesc2 = {
    Text = "[Join the Spin] 3টি প্রার্থনাগাথা থেকে 1টি খোদাই করো"
  },
  Event_36723_Desc = {
    Text = "তুমি এক পা বাড়াতেই, তোমার আত্মার গভীরতম স্থানে নীরবে এক ফাটল গড়ে ওঠে। এক অবর্ণনীয় গাঢ় আভা সেখান থেকে চুঁইয়ে বেরিয়ে এসে তোমার চিন্তায় ঢেউ তোলে।\nতুমি অনুভব করো, তোমার ভেতরে এক সিলভার বিশৃঙ্খল গ্রহ নীরবে ঘুরছে ও বেড়ে উঠছে।"
  },
  Event_36723_Name = {
    Text = "নসিস স্মারকস্তম্ভ"
  },
  Event_36724_ChoiceDesc1 = {
    Text = "[Follow them] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_36724_ChoiceDesc2 = {
    Text = "[Pet Them] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 এবং 「(Skill.Arg3)」 বিকশিত করো।"
  },
  Event_36724_ChoiceDesc3 = {
    Text = "[Do Not Disturb] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_36724_Desc = {
    Text = "একটি অপ্রত্যাশিত বাঁক ঘোরার পর, একটি অদ্ভুত দৃশ্য তোমার চোখের সামনে ভেসে ওঠে।\nকয়েকটি বিড়ালের ছায়া, কখনো দেখা যায় কখনো মিলিয়ে যায়, ঠান্ডা দেয়ালের পাশে ভেসে বেড়াচ্ছে।"
  },
  Event_36724_Name = {
    Text = "জাহাজের বিড়াল"
  },
  Event_36725_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36725_Desc = {
    Text = "「স্মৃতিচারণ」 কোনো সাড়া দেয় না। তারা কেবিনের দেয়ালে লেগে থাকে, তোমার দিকে তাকিয়ে থাকে, যতক্ষণ না তুমি পরের মোড় ঘুরে অদৃশ্য হয়ে যাও।"
  },
  Event_36725_Name = {
    Text = "সোনা-নিলের মালিক"
  },
  Event_36726_ChoiceDesc1 = {
    Text = "[Detour] একটি কমান্ড কার্ড ধ্বংস করো এবং Arg1টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_36726_ChoiceDesc2 = {
    Text = "[Ask Why It Sank] একটি কমান্ড কার্ড নকল করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকাশ করো।"
  },
  Event_36726_ChoiceDesc3 = {
    Text = "[Greet the Crew] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_36726_Desc = {
    Text = "\nইঞ্জিন রুমের দিকে হাঁটতে হাঁটতে তুমি আবারও কিছু 「স্মৃতিচারণ」-এর মুখোমুখি হও, যা ডোমেইনে স্থির হয়ে আছে.\nওগুলো ভূত নয়, কেবল হারিয়ে যাওয়া নাবিকদের জন্য দলনেতা এল্টনের অবশিষ্ট চিন্তাধারা।"
  },
  Event_36726_Name = {
    Text = "সোনা-নিলের মালিক"
  },
  Event_36727_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36727_Desc = {
    Text = "\n「স্মৃতিচারণ」 বাল্কহেড থেকে খসে পড়ে, মুখ বিকৃত করে এক করুণ আর্তনাদ ছেড়ে দেয়.\n—আলোদ্বীপ.\n—সেই বিচ্ছিন্ন আলোদ্বীপই তাদের ঝড়ের ভেতরে টেনে নিয়েছিল।"
  },
  Event_36727_Name = {
    Text = "সোনা-নিলের মালিক"
  },
  Event_36728_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36728_Desc = {
    Text = "তুমি কোমল ও মুক্ত আত্মাদের আঁকা পথ অনুসরণ করেছ, যদিও সামনে অন্ধকারের ফাঁদ লুকিয়ে আছে।"
  },
  Event_36728_Name = {
    Text = "জাহাজের বিড়াল"
  },
  Event_36729_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36729_Desc = {
    Text = "মৃতদের অশান্ত কোরো না, তন্দ্রাচ্ছন্নদের স্মৃতিচারণও জাগিও না।"
  },
  Event_36729_Name = {
    Text = "সোনা-নিলের মালিক"
  },
  Event_36730_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36730_Desc = {
    Text = "তুমি অনুভব করো, তোমার চেতনা আলগা হতে শুরু করেছে, ধীরে ধীরে দেহ থেকে টেনে বের করে নেওয়া হচ্ছে।\nতুমি দেখো, তোমার আত্মা গ্রহের সঙ্গে নৃত্য করছে, তারপর এক অদৃশ্য অতল গহ্বরে ডুবে যাচ্ছে...\nসেখানে আছে নিখাদ শূন্যতা।"
  },
  Event_36730_Name = {
    Text = "নসিস স্মারকস্তম্ভ"
  },
  Event_36731_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36731_Desc = {
    Text = "নরম স্বভাবের প্রাণী হিসেবে, এই ডোমেইনে তারা নিষিদ্ধ বিলাসিতা, কেবল মায়াভ্রম মাত্র。\nতুমি তা জানো, তবু হৃদয়ের গভীরে একটুখানি উষ্ণতার ঢেউ গোপনে দোলা দিয়ে যায়।"
  },
  Event_36731_Name = {
    Text = "জাহাজের বিড়াল"
  },
  Event_36732_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36732_Desc = {
    Text = "তাদের অবয়ব ঝাপসা, যেন সময় আর স্থান-স্রোতে ধুয়ে যাওয়া কোনো চিত্রকর্ম। গভীর কালো দাগগুলো রাতের আকাশে ভেসে বেড়ানো মেঘের মতো, কিন্তু তাদের চোখ জ্বলে ওঠে দূর নক্ষত্রের গ্লিমারের মতো, ছড়িয়ে দেয় এক রহস্যময় ও অতল আলোকচ্ছটা।\nতুমি তাদের আকর্ষণ প্রতিহত করতে পারো না, হাত বাড়িয়ে দাও মায়াস্বপ্নের এক রাজ্যে।"
  },
  Event_36732_Name = {
    Text = "জাহাজের বিড়াল"
  },
  Event_36733_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36733_Desc = {
    Text = "তুমি জানো, তোমাকে এগিয়ে যেতেই হবে—হোঁচট খেলেও, পড়ে গেলেও।"
  },
  Event_36733_Name = {
