  Event_36735_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36735_Desc = {
    Text = "\"কিপার, যদি আর সহ্য করতে না পারো, দয়া করে একা একা এই যন্ত্রণা বয়ে নিও না।\"\nতুমি যন্ত্রণাকে এড়াবে না, কারণ তা ক্ষণস্থায়ী জীবনেরই অংশ।\nতুমি রাত্রির ছায়াকে ভয় করবে না, কারণ তুমি তার অন্ধকারে গিলে খাওয়া হওয়ার ভয় করো না।"
  },
  Event_36735_Name = {
    Text = "দৈহিক যন্ত্রণা"
  },
  Event_36736_ChoiceDesc1 = {
    Text = "[Keep Calling Him] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_36736_ChoiceDesc2 = {Text = "[Leave]"},
  Event_36736_Desc = {
    Text = "এই বিশ্ব সরল আঁকিবুঁকি দ্বারা গঠিত।"
  },
  Event_36736_Name = {
    Text = "বিবর্তনের রূপান্তর"
  },
  Event_36737_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36737_Desc = {
    Text = "সাগরচারীদের নীরব প্রার্থনা চারদিকে প্রতিধ্বনিত হয়, উন্মাদ করে তোলে, শ্বাসরুদ্ধ করে。\nকিন্তু তারা তোমার ইচ্ছাশক্তিকে প্রভাবিত করতে পারবে না, একেবারেই না।"
  },
  Event_36737_Name = {
    Text = "সাগর থেকে আগত"
  },
  Event_36738_ChoiceDesc1 = {
    Text = "[Pick up the Photo] 3টি কমান্ড কার্ডের মধ্যে 1টিতে 「(EnchantConfig.Arg1)」 নামের প্রার্থনা খোদাই করো।"
  },
  Event_36738_Desc = {
    Text = "তাদের দৃষ্টি গভীর ও স্বচ্ছ, যেন গভীর সাগরের আলো, উজ্জ্বল ও উষ্ণ।\nতারা কথা বলে না, সামনে আসে না, তবু তুমি তাদের উপস্থিতি অনুভব করো, যেন গ্রীষ্মের বাতাসের কোমল স্পর্শ।"
  },
  Event_36738_Name = {
    Text = "সদয় দৃষ্টি"
  },
  Event_36739_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36739_Desc = {
    Text = "তুমি নিজেকে জোর করে বর্তমান সংকটে মনোযোগী রাখো, কঠোরভাবে নিজেকে ব্যথা উপেক্ষা করতে আদেশ দাও।"
  },
  Event_36739_Name = {
    Text = "দৈহিক যন্ত্রণা"
  },
  Event_36740_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36740_Desc = {
    Text = "ওগুলোই জীবনের দাগ, অস্তিত্বের প্রমাণ। তারা গল্প বর্ণনা করে, কিন্তু ঝড়ের প্রলয়ের নিচে ধীরে ধীরে তাদের কণ্ঠ হারিয়ে ফেলে।"
  },
