  Event_36743_ChoiceDesc3 = {
    Text = "[Ignore Pain] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_36743_Desc = {
    Text = "ব্যথা তোমার মনে একগুঁয়ে পাথরের মতো গেঁথে আছে। ছড়িয়ে পড়া যন্ত্রণা প্রতিটি স্নায়ু জড়িয়ে ধরে, তোমার চেতনাকে বিকৃত করে।"
  },
  Event_36743_Name = {
    Text = "দৈহিক যন্ত্রণা"
  },
  Event_36744_ChoiceDesc1 = {
    Text = "[Firm Call] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 নামের উপসর্গ গড়ে ওঠে।"
  },
  Event_36744_ChoiceDesc2 = {Text = "[Leave]"},
  Event_36744_Desc = {
