  Event_36744_Name = {
    Text = "বিবর্তনের রূপান্তর"
  },
  Event_36745_ChoiceDesc1 = {
    Text = "[Watch Them] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_36745_ChoiceDesc2 = {
    Text = "[Seek Help] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো এবং খোদাই করার প্রার্থনাগাথা পরিবর্তন করো।(ব্যবহার: 2/2)"
  },
  Event_36745_Desc = {
    Text = "ডোমেইনের বয়ে চলা রঙের ভেতর তুমি এক রহস্যময় দৃষ্টির অনুভব পাও—রূপহীন চোখ, তার গোপন ভাঁজগুলোর মধ্যে গোপন。\nযেই মুহূর্তে তারা তোমার দিকে তাকায়, তোমার হৃদয়ে এক প্রবল আকাঙ্ক্ষা জেগে ওঠে।"
  },
  Event_36745_Name = {
    Text = "সদয় দৃষ্টি"
  },
  Event_36746_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36746_Desc = {
    Text = "তুমি যদি তাদের বুঝতে ব্যর্থ হও, তবে এই বিশৃঙ্খল অগ্নিকুণ্ড থেকে কখনোই পালাতে পারবে না।\nযখন তারারা জলের পৃষ্ঠে প্রতিফলিত হয়, তখন সেই স্পন্দিত আকাঙ্ক্ষা আর আর্তি, সেই প্রার্থনাগুলো বুদবুদের মতো সাগরের দিকে উঠে যায়, কেবলই নীরবে গ্রাসিত হতে অন্ধকারের দ্বারা।"
  },
  Event_36746_Name = {
    Text = "সাগর থেকে আগত"
  },
  Event_36747_ChoiceDesc1 = {
    Text = "[Eager Call] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_36747_ChoiceDesc2 = {Text = "[Leave]"},
  Event_36747_Desc = {
    Text = "কুৎসিত শব্দাবলী দ্বারা এই বিশ্ব গঠিত।"
  },
  Event_36747_Name = {
    Text = "বিবর্তনের রূপান্তর"
  },
  Event_36748_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36748_Desc = {
    Text = "তুমি তার সামনে দাঁড়িয়ে আছ, দেখছ তার আত্মা অদ্ভুত স্মৃতিচারণ দ্বারা গ্রাস হয়ে যাচ্ছে।"
  },
  Event_36748_Name = {
    Text = "বিবর্তনের রূপান্তর"
  },
  Event_36749_ChoiceDesc1 = {
    Text = "[Tears of Sorrow] একটি কার্ড ধ্বংস করো"
  },
  Event_36749_ChoiceDesc2 = {
    Text = "[That's Blood] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_36749_Desc = {
    Text = "কয়েক ফোঁটা তরল ডেকে ছড়িয়ে পড়ে, নিঃশব্দে ফাঁকফোকর দিয়ে গলে যায়。\nচিহ্নগুলো কোমল অথচ দৃঢ়চেতা, প্রতিটি ভেজা দাগে এক ধরনের চূড়ান্ততার সুর, গর্জনরত সমুদ্রের হাওয়া আর কড়মড়ে পালতোলার মাঝখানে জীবন-মৃত্যু, নীরবতা আর বিশৃঙ্খলার এক ছবি বুনে তোলে।"
  },
  Event_36749_Name = {
    Text = "বিদায়, ইকারাস"
  },
  Event_36750_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36750_Desc = {
    Text = "তুমি ধীরে ছড়িয়ে পড়া দাগগুলোর দিকে তাকিয়ে তাদের প্রকৃতি বোঝার চেষ্টা করো। যেখানে আকাশ আর মাটির সীমানা মিলিয়ে যায়, সেখানে বৃষ্টি আর রক্তের পার্থক্য ঝাপসা হয়ে ওঠে।\nওগুলো কি বৃষ্টির ফোঁটা? নাকি সাগরের চোখের জল?\nতুমি জানো না।"
  },
  Event_36750_Name = {
    Text = "বিদায়, ইকারাস"
  },
  Event_36751_ChoiceDesc1 = {
    Text = "[Reject the Synchrony] 3টি রৌপ্য সৃষ্টি থেকে 1টি অর্জন করো"
  },
  Event_36751_ChoiceDesc2 = {
    Text = "[Join the Synchrony] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 ও 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু 「(Skill.Arg3)」 দক্ষতাটি দুইবার বিকশিত করো।"
  },
  Event_36751_Desc = {
    Text = "সাগরচারীদের হুইসপার 「দিব্য ভ্রূণ」-এর হৃদস্পন্দনের সঙ্গে জড়িয়ে গোপন এক সিম্ফনি রচনা করে। প্রতিটি কম্পন সীমাহীন তরল মহাবিশ্বে এক গর্জন জাগিয়ে তোলে।"
  },
  Event_36751_Name = {
    Text = "সাগর থেকে আগত"
  },
  Event_36752_ChoiceDesc1 = {
    Text = "[Pick up the Photo] 3টি কমান্ড কার্ডের মধ্যে 1টিতে 「(EnchantConfig.Arg1)」 নামের প্রার্থনা খোদাই করো।"
  },
  Event_36752_ChoiceDesc2 = {
    Text = "[Check Film] 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো এবং যে প্রার্থনাগাথা খোদাই করা হবে তা বদলাও।(ব্যবহার: 1/2)"
  },
  Event_36752_Desc = {
    Text = "তাদের কোনো অশুভ উদ্দেশ্য নেই; এই অনুভূতিটা কেবল স্বভাবজাত, তোমার অস্থিমজ্জায় গভীরমূল প্রতিরক্ষা হয়ে গেঁথে আছে。\nতাই তুমি সতর্কতা নামিয়ে রেখে এই গোপন পর্যবেক্ষকদের কাছে সাহায্য চাইতে চেষ্টা করো: নিজের বিভ্রান্তি আর আকাঙ্ক্ষা সেই অস্পষ্ট সত্তার সঙ্গে ভাগ করে নাও, যেন কোনো পুরাতন বন্ধুর কাছে মনের কথা উজাড় করে দিচ্ছো, এতটাই আন্তরিকভাবে কথা বলো।"
  },
  Event_36752_Name = {
    Text = "সদয় দৃষ্টি"
  },
  Event_36874_ChoiceDesc1 = {
    Text = "[Narrate school stories] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_36874_ChoiceDesc2 = {
    Text = "[Uneducated] 75টি কালো চিহ্ন গ্রহণ করো, তবে 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_36874_Desc = {
    Text = "একটি ধ্বংসস্তূপের পাশ দিয়ে যেতে যেতে, অরিতার চোখ হঠাৎ জ্বলে উঠল।\n\"দিদা বলতেন, এটা নাকি একসময় স্কুল ছিল, কিন্তু ছাত্র না থাকায় অনেক আগেই পরিত্যক্ত হয়েছে!\"\n\"অরিতা কোনোদিন স্কুলে যায়নি। তুমি কী বলো, বন্ধু? তুমি কি কখনো স্কুলে গিয়েছ?\""
  },
  Event_36874_Name = {
    Text = "হারানো আনন্দ"
  },
  Event_36875_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36875_Desc = {
    Text = "তোমার নেতিবাচক উত্তর পেয়ে অরিটা ম্লান মুখে মাথা নাড়ল。\n\"তাহলে, বাইরের জগতে কোনো ছাত্রও নেই… তবে প্রথমে স্কুলগুলো প্রতিষ্ঠা করার মানেটাই বা কী ছিল?\""
  },
  Event_36875_Name = {
    Text = "হারানো আনন্দ"
  },
  Event_36876_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36876_Desc = {
    Text = "「দরিদ্রাশ্রম, ছোট্ট ইঁদুর, মোমের ভাস্কর্য... হুররে! অভিযান, এটা অভিযান!」\nঅরিটা বলল, তার মাথার ওপর যেন অদৃশ্য এক প্রশ্নবোধক চিহ্ন ভেসে উঠল।\n「তবে, দিদিমা বলেছিলেন, স্কুল নাকি এমন এক জায়গা, যা অরিটাকে আরও বুদ্ধিমান করে তুলবে, কিন্তু...」\nঅরিটা তার ভাবনা শেষ করার আগেই, তুমি তাকে ঠেলে আরেকটা মোড় ঘুরিয়ে দিলে।"
  },
  Event_36876_Name = {
    Text = "হারানো আনন্দ"
  },
  Event_36877_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36877_Desc = {
    Text = "\n“ক-কেন?”\nতুমি দেখে অরিটা আতঙ্কিত হয়ে উঠল, তবু কঠোর অভিব্যক্তি নিয়ে তোমাকে পথ দেখাতে থাকল।\n“এটা অরিটার বাড়ি। অরিটা জানে যে চত্বরটা—এই ভেতরেই আছে!”"
  },
  Event_36877_Name = {
    Text = "দৃষ্টিহীন অন্ধকার"
  },
  Event_36878_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36878_Desc = {
    Text = "\"আমি এই পথ দিয়ে যেতে চাই না। অরিটা কি চত্বরে যাওয়ার আর কোনো পথ জানে?\"\nঅরিটা ঠোঁট ফুলিয়ে বিভ্রান্ত দৃষ্টিতে তোমার দিকে তাকায়, কিন্তু শেষমেশ তোমার চাদর টেনে ধরে অন্য এক পথে তোমাকে নিয়ে চলে।"
  },
  Event_36878_Name = {
    Text = "দৃষ্টিহীন অন্ধকার"
  },
  Event_36879_ChoiceDesc1 = {Text = "[Leave]"},
  Event_36879_Desc = {
    Text = "এটা এক স্বপ্ন, শুধু এক স্বপ্ন।\nতুমি বারবার নিজেকে তিরস্কার করো, অথবা হয়তো সান্ত্বনা দাও, অরিটাকে নিয়ে অদেখা অন্ধকারের ভেতর পা বাড়াও।"
  },
  Event_36879_Name = {
    Text = "দৃষ্টিহীন অন্ধকার"
  },
  Event_36880_ChoiceDesc1 = {
    Text = "[Listen to Her] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_36880_ChoiceDesc2 = {
    Text = "[Oppose Her] এক জন জাগরণকারীকে জাগরণ করো, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত হবে।"
  },
  Event_36880_ChoiceDesc3 = {
    Text = "[Negotiate with Her] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_36880_Desc = {
    Text = "অরিটা তোমার চাদর আঁকড়ে ধরে, তোমার পায়ের ছাপের ভেতরেই এক এক করে পা ফেলে এগোচ্ছে।\n「এই... না! চত্বর তো ওইদিকে!」\nঅরিটা যে দিকে আঙুল তোলে, তুমি মাথা ঘুরিয়ে সেই দিকে তাকাও, আর ডোমেইনের পথঘাট সব পিচকালো অন্ধকার। D-পঙ্ক আর বিচ্যুতি গুলো কিলবিল করে একে অন্যে জড়িয়ে আছে, টেনে নিচ্ছে বাস্তব জগতকে অতল গহ্বরে।"
  },
  Event_36880_Name = {
    Text = "দৃষ্টিহীন অন্ধকার"
  },
  Event_37983_ChoiceDesc1 = {
    Text = "[Secure Funding] Arg1টি কালো চিহ্ন অর্জন করো"
  },
  Event_37983_ChoiceDesc2 = {
    Text = "[Secure Funding] Arg1টি কালো চিহ্ন অর্জন করুন [ExDesc1]"
  },
  Event_37983_Desc = {
    Text = "\"কোনো প্রভুই কোনো রহস্যময় অতিথিকে নজরদারি ছাড়া রাখে না, সন্ন্যাসী তো দূরের কথা।\"\nরানী উঁচু সিংহাসনে বসে, তার চোখে অত্যাচারের এক মিটমিট ঝিলিক।\n\"তোমার উপযোগিতা প্রমাণ করো, নইলে...\"\nউপযোগিতা? তুমি জানালার বাইরে অনুর্বর ভূমির দিকে তাকাও, হঠাৎ এক চিন্তা মাথায় আসে: হয়তো তোমার অর্থনৈতিক জ্ঞান ব্যবহার করে ওয়ান্ডাকে এস্টেট পরিচালনায় সাহায্য করা যায়?\nতুমি প্রাণপণে পড়াশোনার কথা মনে করার চেষ্টা করো—মিথাগ-এ অর্থনীতি ছিল শুধু এক তুচ্ছ ঐচ্ছিক বিষয়...\nধৈর্য ফুরিয়ে আসছে। রানী হাই তোলে।\n\"হতাশাজনক। মৃত্যুদণ্ড—\"\nযেই না গিলোটিন নেমে আসে, অ্যাডাম স্মিথ, ম্যালথাস, ডেভিড রিকার্ডো এবং অন্যান্য মহান পূর্বসূরিদের আত্মারা তোমার মস্তিষ্কে নেমে আসে।\nশ্রমবিভাজন! করব্যবস্থা! জনসংখ্যা, অভিশপ্ত জনসংখ্যা!\nতুমি হয়তো মনে করতে পারো..."
  },
  Event_37983_Name = {
    Text = "প্রতিনিধি কোড"
  },
  Event_37984_ChoiceDesc1 = {Text = "[Leave]"},
  Event_37984_Desc = {
    Text = "তুমি অনিচ্ছায় ফরমানটি পেশ করো।\nরানি একবার চোখ বুলিয়ে ঠান্ডা হাসি হেসে বলে:\n\"এটা যদি নিরর্থক প্রমাণিত হয়, কী হবে তুমি জানো।\""
  },
  Event_37984_Name = {
    Text = "প্রতিনিধি কোড"
  },
  Event_37985_ChoiceDesc1 = {
    Text = "[Propose Decree] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করুন"
  },
  Event_37985_ChoiceDesc2 = {
    Text = "[Propose Decree] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করুন"
  },
  Event_37985_ChoiceDesc3 = {
    Text = "[Propose Decree] সোনালি রেলিক 「(RelicConfig.Arg1)」 অর্জন করুন"
  },
  Event_37985_Desc = {
    Text = "\n「আমার টাকা নিয়েছ যখন, তখন তোমাকে আমাকে সেবা করতেই হবে।」\nরানি এক হাতের তালুতে থুতনি ভর দিয়ে, উদাসীন ভঙ্গিতে তোমার দিকে তাকিয়ে রইলেন।\nস্বীকার করুন আর না-ই করুন, বিষয়টি নিয়ে তিনি সত্যিই কৌতূহলী।\n「তো, বলো তবে তোমার পরিকল্পনা, মহা সংস্কারক।」"
  },
