  Event_40452_ChoiceDesc1 = {
    Text = "[পরিচয় জিজ্ঞেস করো]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」"
  },
  Event_40452_ChoiceDesc2 = {
    Text = "[Leave] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 এলোমেলো 3টি কমান্ড কার্ডে খোদাই করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_40452_Desc = {
    Text = "তিনটি ভূত পথ রোধ করে দাঁড়াল।\nতারা জুয়ার টেবিল ঘিরে ধরল, তাদের দৃষ্টি স্থির হয়ে রইল পাশার উপর।\n\"গলপ, গলপ।\"\nপাশা অসংখ্যবার ছোড়া হলো, পড়ল, আবার ছোড়া হলো।\nএ এক অন্তহীন জুয়া।"
  },
  Event_40452_Name = {
    Text = "অন্তহীন বাজি"
  },
  Event_40453_ChoiceDesc1 = {Text = "[Leave]"},
  Event_40453_Desc = {
    Text = "\n「হ্যালো, আমরা ওয়ান্ডার প্রথম, দ্বিতীয়, আর তৃতীয় স্বামী।」\n「কি? আপনি জানতে চাইছেন চতুর্থ স্বামী কোথায়?\nআচ্ছা... সত্যি বলতে, জনের রসবোধের বড় অভাব ছিল, তাই ভদ্রমহিলা তাকে অন্ধ পরিচারকে রূপান্তর করেছেন।」\n「ওকে হারিয়ে আমরা সবাই অনুতপ্ত। অবশ্যই, সামান্যই।」"
  },
  Event_40453_Name = {
    Text = "অন্তহীন বাজি"
  },
  Event_40454_ChoiceDesc1 = {
    Text = "[Shake Hands] এলোমেলো এক জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_40454_ChoiceDesc2 = {
    Text = "[Leave] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_40454_Desc = {
    Text = "তারা যখন এক খাঁচার পাশ দিয়ে যাচ্ছিল, ভেতর থেকে একটি হাত এগিয়ে এল।\n“আমাকে ফেলে যেও না, রেবেকা...”\nকণ্ঠস্বরটি ছিল বার্ধক্যে শুকিয়ে যাওয়া, পুরোনো ধোঁয়াটে ধমনীঘটিত ধোঁকনির মতো ক্লান্ত।"
  },
  Event_40454_Name = {
    Text = "বন্দী"
  },
  Event_40455_ChoiceDesc1 = {Text = "[Leave]"},
  Event_40455_Desc = {
    Text = "তোমার তালুটা আঠালো লাগছে—এটা D-পঙ্ক।\nকণ্ঠস্বরের মালিক উধাও, লুকিয়ে গেছে অন্ধকার কোণের ছায়ায়।"
  },
  Event_40455_Name = {
    Text = "বন্দী"
  },
  Event_40456_ChoiceDesc1 = {Text = "[Leave]"},
  Event_40456_Desc = {
    Text = "তুমি বিন্দুমাত্র তোয়াক্কা না করে চলে গেলে, চিঠির পেছনের নাটকীয় কাহিনিটা মিস করলে。\nকিন্তু তাতে কী আসে যায়?\nঅসীম সাগর, ভোর আর গোধূলি, বিষুবীয় মরুভূমি…\nতুমি আরও অনেক কিছুর মুখোমুখি হবে, আর আরও অনেক কিছুই হারিয়ে ফেলবে।"
  },
  Event_40456_Name = {
    Text = "শ্রদ্ধেয় মহিলাকে"
  },
  Event_40457_ChoiceDesc1 = {Text = "[Leave]"},
  Event_40457_Desc = {
    Text = "এক অর্থে, তুমি এই বন্দীর থেকে ভিন্ন নও।\nএখনই সতর্কতা জাগানোর সময় নয়।\nতুমি বন্দীর আর্তি উপেক্ষা করে সরে গেলে।"
  },
  Event_40457_Name = {
