  },
  Event_40458_ChoiceDesc3 = {
    Text = "[Reply] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_40458_Desc = {
    Text = "I. জন ক্যামব্রিয়ানের চিঠি ওয়ান্ডার উদ্দেশে (B.F. @2)\n\nএকজন স্বামীর তার স্ত্রীর ভাগ্য নির্ধারণের অধিকার আছে, অন্তত ক্যামব্রিয়ানে তো আছে।\nকিন্তু আমি স্পষ্টতই তোমার উন্মাদনাকে হালকাভাবে নিয়েছিলাম। এখন আমি প্রায় অন্ধ, আর আমার অঙ্গপ্রত্যঙ্গ কেটে ফেলার উপক্রম।\nঅশুভের কন্যা... না, তুমিই অশুভের মূর্ত প্রতীক।\nআমি তোমাকে অভিশাপ দিচ্ছি @1, তোমাকে অভিশাপ দিচ্ছি @2, তোমাকে অভিশাপ, অভিশাপ..."
  },
  Event_40458_Name = {
    Text = "শ্রদ্ধেয় মহিলাকে"
  },
  Event_40459_ChoiceDesc1 = {Text = "[Leave]"},
  Event_40459_Desc = {
    Text = "তুমি অভিশাপ ভাঙতে সবচেয়ে সরল পদ্ধতিটাই ব্যবহার করলে।\nকিছুই ঘটল না। কাগজটা নিস্তেজভাবে মাটিতে পড়ে গেল।\nতুমি কাঁধ ঝাঁকিয়ে সরে গেলে, তবু মনে হচ্ছিল কোথাও যেন কিছু ঠিক নেই।"
  },
  Event_40459_Name = {
    Text = "শ্রদ্ধেয় মহিলাকে"
  },
  Event_40460_ChoiceDesc1 = {Text = "[Leave]"},
  Event_40460_Desc = {
    Text = "তুমি একবারও পেছনে না তাকিয়ে জুয়ার টেবিলের পাশ দিয়ে হেঁটে চলে যাও।\nতোমার প্রস্থানকালে, ভূতেরা একসাথে বলে ওঠে:\n\"আমাদের সেই অভিন্ন প্রাক্তন স্ত্রী, মিসেস ওয়ান্ডাকে আমাদের সালাম দিও।\""
  },
  Event_40460_Name = {
    Text = "অন্তহীন বাজি"
  },
  Event_40461_ChoiceDesc1 = {Text = "[Leave]"},
  Event_40461_Desc = {
    Text = "তুমি চিঠির শেষে পরিপাটি করে নিজের উত্তর লিখে রাখো:\n“অভিশাপ গৃহীত। তোমার মঙ্গল কামনা করি।”\nশেষ আঁচড়টি পড়তেই, কাগজের গায়ে ক্রুদ্ধ নীল আগুন জ্বলে ওঠে。\nতুমি ছাইগুলো সংগ্রহ করো।"
  },
  Event_40461_Name = {
    Text = "শ্রদ্ধেয় মহিলাকে"
  },
  Event_44187_ChoiceDesc1 = {
    Text = "[Face the Darkness] [ExDesc1][ExDesc2]"
  },
  Event_44187_ChoiceDesc2 = {
    Text = "[Face the Darkness] [ExDesc1][ExDesc2]"
  },
  Event_44187_ChoiceDesc3 = {
    Text = "[Flee the Darkness] একটি দৈব সোনালি রেলিক অর্জন করো"
  },
  Event_44187_Desc = {
    Text = "তোমার সামনে যে আত্মাটি রয়েছে, তা অন্ধকারে কলুষিত—তার ভেতরে আলো আর অন্ধকার পাশাপাশি সহাবস্থান করছে। তারা আধিপত্যের জন্য লড়াই করছে, আর আত্মাটিকে বিভ্রান্তিতে ডুবিয়ে দিচ্ছে।\n\"আমি তাদের জন্য দুঃখ পাই, সেই করুণ আত্মাগুলোর জন্য যারা সবকিছু হারিয়েছে, কিন্তু এ-ই কি পৃথিবীর স্বাভাবিক নিয়ম নয়?\n\"কারও প্রাপ্তি মানেই তো কারও না-প্রাপ্তি।\n\"অন্যের আনন্দের জন্য কি আমাকে আমার সুখ উৎসর্গ করতেই হবে?\""
  },
  Event_44187_Name = {
    Text = "অন্তরের অন্ধকার"
  },
  Event_44188_ChoiceDesc1 = {Text = "[Leave]"},
  Event_44188_Desc = {
    Text = "এটাই আমার পাপ, আমার বোঝা। কীভাবে আমি তোমাকে রক্ষা করব, হে আমার স্ববিরোধী আত্মা?"
  },
  Event_44188_Name = {
    Text = "অন্তরের অন্ধকার"
  },
  Event_44299_ChoiceDesc1 = {
    Text = "[Plea to the Bishop] একটি পাপভারগ্রস্ত সৃষ্টি শুদ্ধিকরণ করুন। যদি আপনার কাছে না থাকে, একটি এলোমেলো সোনালি রেলিক অর্জন করুন।"
  },
  Event_44299_Desc = {
    Text = "「আমি প্রতারণা আর কৌশলে সেই জীবনটা কেড়ে নিয়েছি, যা আমি কামনা করতাম— টাকা হয়ে গেছে কেবল সংখ্যা, সুস্বাদু খাবার হয়ে উঠেছে প্রতিদিনের ভোজ, ব্যবসায় শেষ কথা আমার, আর রাজনীতিতে আমি শক্তিশালী প্রভাব চালিয়েছি। কিন্তু কেন, কেন আমি তাদের ভুলতে পারি না, যাদের কাছ থেকে সবকিছু কেড়ে নিয়েছি? কেন আমি তাদের মুখের সেই হতাশা ভুলতে পারি না?\n」মদ কেবল ক্ষণিকের পালানো দেয়; আমার আত্মা নিজেকেই ছিঁড়ে টুকরো করছে, আর পেইন প্রায় আমাকে ডুবিয়ে দিচ্ছে।\n「আমি কী করব?」"
  },
  Event_44299_Name = {
    Text = "অপরাধবোধ ও ক্ষমা"
  },
  Event_44301_ChoiceDesc1 = {Text = "[Leave]"},
  Event_44301_Desc = {
    Text = "「তুমি যন্ত্রণার পথে হেঁটে চলেছ, সর্বপিতার মহিমা থেকে বিচ্যুত হয়ে।\n」ফিরে এসো, পথহারা মেষশাবক। সর্বপিতার বাণী শোনো এবং সঠিক পথ খুঁজে নাও।「"
  },
  Event_44301_Name = {
    Text = "অপরাধবোধ ও ক্ষমা"
  },
  Event_44395_ChoiceDesc1 = {
    Text = "[Want for the Worldly] Arg1টি কালো চিহ্ন গ্রহণ করো। তোমার কাছে কোনো উপসর্গ থাকলে, বিশপ একটি উপসর্গ গ্রহণ করবে।"
  },
  Event_44395_ChoiceDesc2 = {
    Text = "[Want for Blood] বিশপ 2টি উপসর্গ গ্রহণ করবে। প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করুন।"
  },
  Event_44395_ChoiceDesc3 = {
    Text = "[Want for More] আপনার উপসর্গ 4 বা তার বেশি হলে বিশপ আরও বহন করতে পারবে।"
  },
  Event_44395_Desc = {
    Text = "\nমায়াময় আত্মা এক অস্পষ্ট অবয়ব ধারণ করল, ভাঙা দেহ আর কালো হয়ে যাওয়া হৃদয়ের অবশিষ্টাংশ প্রদর্শনের জন্য বিশপের সামনে হাঁটু গেড়ে বসল।\n“আপনি আমাকে দিশা দিয়েছেন, ক্ষমা করেছেন, মুক্তি দিয়েছেন, কিন্তু দয়ালু বিশপ, এ তো যথেষ্ট নয়।\n“আমি নিঃস্ব, আর প্লেগে জর্জরিত। আমার জীবন ঝুলে আছে সূক্ষ্ম এক সুতোয়, আর আপনি-ই আমার একমাত্র মুক্তি। অনুগ্রহ করে আমাকে রক্ষা করুন, বিশপ, যেন আর কষ্ট পেতে না হয়।”"
  },
  Event_44395_Name = {
    Text = "বিশপের 「আশীর্বাদ」"
  },
  Event_44396_ChoiceDesc1 = {
    Text = "[Bow and Leave]"
  },
  Event_44396_Desc = {
    Text = "বিশপ তার আংটি আর ব্রোচ খুলে ফেলল। সর্বপিতার প্রতীক নীল রত্নগুলো একে একে সেই আত্মার হাতে তুলে দিল। বিশপ ঝুঁকে পড়ে, দরিদ্র আত্মার হাত দুটো নিজের হাতে নিল। \n「আমার সোনা আর সিলভার নিয়ে নাও, আমার সব সম্পদ নিয়ে নাও—যদি সেটাই তোমার প্রয়োজন হয়। সর্বপিতার বাণীই আমার বেঁচে থাকার জন্য যথেষ্ট।」"
  },
  Event_44396_Name = {
    Text = "বিশপের 「আশীর্বাদ」"
  },
  Event_44400_ChoiceDesc1 = {
    Text = "[Indulge] একটি এলোমেলো জাগরণকারীকে জাগরণ করান, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত হবে।"
  },
  Event_44400_ChoiceDesc2 = {Text = "[Give Up]"},
  Event_44400_Desc = {
    Text = "হারিয়ে যাওয়া আত্মা অন্ধকার ত্যাগ করতে অস্বীকার করে।\nতুমি জানো তাকে কী অপেক্ষা করছে। এক অযৌক্তিক জীবন উন্মোচিত হতে চলেছে, আর তুমি তার একমাত্র দর্শক।"
  },
  Event_44400_Name = {
    Text = "অন্তরের অন্ধকার"
  },
  Event_44401_ChoiceDesc1 = {
    Text = "[Quick Reflexes] Arg1টি কালো চিহ্ন গ্রহণ করুন"
  },
  Event_44401_ChoiceDesc2 = {
    Text = "[Seize Freely] 3টি উন্নত প্রার্থনাগাথা থেকে 1টি উৎকীর্ণ করুন, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত হবে।"
  },
  Event_44401_Desc = {
    Text = "ডোমেইনে পাওয়া একটি কালো চিহ্নকে রেলিক বা অন্যান্য আধ্যাত্মিক প্রক্ষেপণের বিনিময়ে ডি-মার্কের কাছে উৎসর্গ করা যায়। বর্তমান এলাকা ত্যাগ করার পর অল্প সময়ের মধ্যেই এটি কালো কাদায় দ্রবীভূত হয়ে যাবে।"
  },
