  Event_44911_ChoiceDesc1 = {Text = "[Leave]"},
  Event_44911_Desc = {
    Text = "\n「সব, সব... হ্যাঁ, আমি সবই চাই...!」\nআত্মা হাত বাড়িয়ে দিল, শূন্য বাতাসকে বৃথাই আঁকড়ে ধরল।\nসে কিছু অর্জন করল, কিন্তু হারাল সবকিছু।"
  },
  Event_44911_Name = {
    Text = "তুমি কী পেয়েছ?"
  },
  Event_44913_ChoiceDesc1 = {Text = "[Leave]"},
  Event_44913_Desc = {
    Text = "「শুধু সবচেয়ে গুরুত্বপূর্ণটি... সবচেয়ে নির্ণায়কটি...「\nআত্মা নিচু হয়ে বসে পড়ল, মায়াস্বপ্নের মাটি থেকে এক উজ্জ্বল প্রার্থনা খুঁড়ে বের করল, আর তা দু」হাতে দোলনার মতো করে আগলে রাখল।"
  },
  Event_44913_Name = {
    Text = "তুমি কী পেয়েছ?"
  },
  Event_44916_ChoiceDesc1 = {
    Text = "[সবকিছু ধরে রাখো]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」"
  },
  Event_44916_ChoiceDesc2 = {
    Text = "[Learn to Let Go] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 এলোমেলো 3টি কমান্ড কার্ডে খোদাই করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_44916_Desc = {
    Text = "ম্লান আত্মা যন্ত্রণায় কাতর।\nসম্ভাব্য সব পছন্দ আর তাদের পরিণতিতে বিভ্রান্ত হয়ে সে ঘুরে বেড়ায়।\n“আমি কী বেছে নেব?” সে ফিসফিস করে, “আমি কী করব?”\n“কীভাবে আমি সবকিছুই পেতে পারি?”"
  },
  Event_44916_Name = {
    Text = "তুমি কী পেয়েছ?"
  },
  Event_44919_ChoiceDesc1 = {
    Text = "[Self-Reflection] এলোমেলো এক জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_44919_ChoiceDesc2 = {
    Text = "[Look Around] 3টি প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_44919_Desc = {
    Text = "ভেসে থাকা আত্মা এক দ্বিধায় বন্দী।\nসে থেমে যায়, আকাঙ্ক্ষার দোলাচলে দুলতে দুলতে।\n\"আমার কী বেছে নেওয়া উচিত?\" সে মৃদুস্বরে প্রলাপ বকে, \"আমার কী করা উচিত?\"\n\"এর মধ্যে কোনটি আমার সত্যিকারের আকাঙ্ক্ষা?\""
  },
  Event_44919_Name = {
    Text = "তোমার বাসনা কী?"
  },
  Event_44920_ChoiceDesc1 = {Text = "[Leave]"},
  Event_44920_Desc = {
    Text = "\n\"তুমি ঠিকই বলেছ, আমাকে দেখতে হবে, আমাকে দেখতে হবে...\"\nওটা মাথা নত করে, হাত বুকে গুঁজে দেয়, ফাঁপা বক্ষগহ্বরের ভেতর থেকে টেনে আনে এক মায়াভ্রম হৃদয়: এক অর্ধেক কালি-কালো, অন্য অর্ধেক নক্ষত্রের মতো দীপ্ত।"
  },
  Event_44920_Name = {
    Text = "তোমার বাসনা কী?"
  },
  Event_44921_ChoiceDesc1 = {Text = "[Leave]"},
  Event_44921_Desc = {
    Text = "\n\"হ্যাঁ, হ্যাঁ... মানুষ বলে, অন্য মানুষ নাকি একেকটা প্রতিবিম্ব হতে পারে... আমাকে দেখতে হবে...\"\nওটা আরও ঝুঁকে এলো, তার মুখহীন চেহারা নিয়ে তোমার দিকে তাকিয়ে।\n\"তুমি কেন বিচলিত নও? কত হিংসে হয়, কত হিংসে হয়...\""
  },
  Event_44921_Name = {
    Text = "তোমার বাসনা কী?"
  },
  Event_44998_ChoiceDesc1 = {Text = "[Leave]"},
  Event_44998_Desc = {
    Text = "「বলে, বর্তমান কষ্ট কেবল অস্থায়ী, আর মৃত্যুর পর আমরা সর্বপিতার বুকে চিরন্তন আনন্দে মগ্ন থাকব।\n」আমি মরার পর পর্যন্ত অপেক্ষা করতে চাই না।「\nছায়ারা লোভী হয়ে সবকিছু গিলে খায়; আত্মাগুলো ম্লান হয়ে যায়, প্রায় চারপাশের অন্ধকারের সঙ্গে একাকার হয়ে ওঠে।\nতুমি কিছু করতে চাও, কিন্তু নিজেকে অসহায় মনে হয়।"
  },
  Event_44998_Name = {
    Text = "অন্তরের অন্ধকার"
  },
  Event_45000_ChoiceDesc1 = {
    Text = "[Bow and Leave]"
  },
  Event_45000_Desc = {
    Text = "বিশপ ধারালো ব্লেড দিয়ে নিজের তালু চিরে ফেলল, আর ট্যাবলেটের উপর ঝরে পড়া রক্ত রূপ নিল নিরাময়ের নীল আলোয়, যা আত্মার অনুপস্থিত রক্ত পূরণ করে দিল।\n「আমার রক্ত নাও, তোমার জীবন পূর্ণ করো—যদি সেটাই তোমার প্রয়োজন হয়। এটাই সর্বপিতা আমাকে করতে বলেছেন।」"
  },
  Event_45000_Name = {
    Text = "বিশপের 「আশীর্বাদ」"
  },
  Event_45001_ChoiceDesc1 = {
    Text = "[Bow and Leave]"
  },
  Event_45001_Desc = {
    Text = "বিশপ নিজের বক্ষের গভীর থেকে আত্মা টেনে বের করল। কোমল আলো ফলকের ভেতর মিশে গিয়ে নিরাময়কারী নীল আভায় রূপ নিল, যা আত্মার প্রতিটি ফাটল ভরে তুলল।\n「এটি গ্রহণ করো; এটি সর্বপিতার দান, তাঁর ভালোবাসার সাক্ষ্য। তোমার দেহ হোক সুস্থ, তোমার আত্মা হোক পূর্ণ, আর তুমি যেন সব যন্ত্রণার ঊর্ধ্বে থাকতে পারো।」"
  },
  Event_45001_Name = {
    Text = "বিশপের 「আশীর্বাদ」"
  },
  Event_45002_ChoiceDesc1 = {Text = "[Leave]"},
  Event_45002_Desc = {
    Text = "তুমি সেই মুখগুলোর দিকে এগিয়ে যাও, আর যখন আবার চোখ খোলো, সবকিছু ডুবে আছে অন্ধকারে। চারপাশে কেবল অজানা জীব আদিম হাসির প্রতিধ্বনি ঘুরে বেড়ায়।"
  },
  Event_45002_Name = {
    Text = "বিভ্রম"
  },
  Event_45036_ChoiceDesc1 = {
    Text = "[Delete All Relics]"
  },
  Event_45036_Desc = {
    Text = "এটাই আমার পাপ, আমার বোঝা। কীভাবে আমি তোমাকে রক্ষা করব, হে আমার স্ববিরোধী আত্মা?"
  },
  Event_45036_Name = {
    Text = "অন্তরের অন্ধকার"
  },
  Event_45196_ChoiceDesc1 = {
    Text = "[Bow and Leave]"
  },
  Event_45196_Desc = {
    Text = "বিশপ ধারালো ব্লেড দিয়ে হাড় আর মাংস কেটে বের করল। ফ্যাকাসে হাড় আর রক্তিম মাংস ফলকের ভেতর মিশে গিয়ে নিরাময়কারী নীল আলোয় রূপ নিল, যা ভাঙা আত্মাকে জোড়া লাগাতে শুরু করল।\n「আমার হাড় আর মাংস নিয়ে তোমার অপূর্ণ দেহ পূর্ণ করো—যদি সেটাই তোমার প্রয়োজন হয়। এটাই সর্বপিতা আমার কাছে প্রত্যাশা করেছেন।」"
  },
  Event_45196_Name = {
    Text = "বিশপের 「আশীর্বাদ」"
  },
  Event_46144_ChoiceDesc1 = {
    Text = "[Leave] 3টির মধ্যে 1টি রৌপ্য সৃষ্টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_46144_Desc = {
    Text = "অস্পষ্ট অবয়বটি ধীরে ধীরে স্পষ্ট হয়, আর তা না কোনো অবক্ষয়িত সত্তা, না মহাবিপর্যয়ের কোনো লক্ষণ—বরং ডানা-বিহীন, স্বাভাবিক চেহারার এক ক্লেমেন্টাইন。\n「কি কাকতাল, তুমিও কি চাঁদের আলো উপভোগ করতে এসেছ?」 সে হাসিমুখে বলে, আর তোমার মাথায় এক ঢেউ ঘোর ঘুরে ওঠে। 「কুয়াশাচ্ছন্ন রাতে, সাবধানে থেকো。\nএখানকার ছোট্টগুলো কিন্তু খুব ভদ্র নয় বোধহয়।」"
  },
  Event_46144_Name = {
    Text = "কুয়াশাবৃত ছায়ামূর্তি"
  },
  Event_46145_ChoiceDesc1 = {
    Text = "[Leave] 3টি সোনার রেলিকের মধ্যে 1টি অর্জন করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_46145_Desc = {
    Text = "তুমি শান্ত ও স্থির রইলে। হঠাৎ এক অভিজাত নারী মঞ্চে ছুটে এলেন।\nতিনি উন্মত্তের মতো ছেলেটির মুখ চেপে খুলে তার ভেতর জোর করে একটি কাঠি গুঁজে দিলেন।\n\"বলো, আমার সঙ্গে কথা বলো।\"\nছেলেটির মুখ থেকে কালো রক্ত গড়িয়ে পড়ছিল। সে অস্পষ্ট স্বরে বকবক করছিল।\n\"মায়ের জন্য একটি গান...\""
  },
  Event_46145_Name = {
    Text = "অন্তিম III"
  },
  Event_47309_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47309_Desc = {
    Text = "সেই দিনে দেবতারা তাদের প্রবল ও শক্তিশালী তরবারি দিয়ে ফিলিস্তিনদের শাস্তি দেবে,\nকারণ তারা যে হত্যাযজ্ঞ 「সাধন」 করেছে তার জন্য。\nকি? তুমি বলছো এটা অন্যায়?\nনা, এ তো শিকারিরই নিয়তি।"
  },
  Event_47309_Name = {
    Text = "নাবিকদের শ্যান্টি"
  },
  Event_47310_ChoiceDesc1 = {
    Text = "[Keep Listening] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_47310_ChoiceDesc2 = {
    Text = "[চলে যাও]যেকোনো 1টি কমান্ড কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg1)」"
  },
  Event_47310_Desc = {
    Text = "ঈশ্বর বললেন: তার নাম হবে ফিলিস্তিন।\nতার কাঁধে চাপিয়ে দাও হত্যার দায়, তাকে অভিশাপ দাও লোভ দিয়ে।\nতার পথ আলোকিত করো, যেন অন্যেরা অতল গহ্বরকেও দেখে সাদা চুলের মতো।\nঅসীম সাগরে, তার চেয়ে বড় হাঙর আর নেই।\nতাকে ভয় করুক আর পূজা করুক সব প্রাণী,\nযতদিন না বিচারের দিন এসে যায়।"
  },
  Event_47310_Name = {
    Text = "নাবিকদের শ্যান্টি"
  },
  Event_47311_ChoiceDesc1 = {
    Text = "[Leave] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_47311_ChoiceDesc2 = {
    Text = "[Leave] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_47311_ChoiceDesc3 = {
    Text = "[Leave] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_47311_Desc = {
    Text = "ছেলেটি ছিল এক তুচ্ছ দাস।\nতার প্রভু তাকে ছেলের মতোই দেখত, অথচ সেই প্রভুই বিছানায় শুয়ে ছুরিকাঘাতে মারা গেল।\n「আমি আপনাকে ভালোবাসি, বাবা। আমি শুধু আর দাস থাকতে চাই না।」\nপরে, ছেলেটি তার 「বাবার」 কবরের সামনে দাঁড়িয়ে পুরোহিতের কথাগুলো স্মরণ করল:\n<Small:যে মাটি তোমাকে লালন করেছে, তাকে ছেড়ে যেয়ো না।\nসময় এলে তোমার হাত রক্তে রঞ্জিত হবে, আর তুমি মরবে অপমানজনক মৃত্যুতে।\nবন্য কুকুর, শকুন আর সাগরের মাছ তোমাকে তুচ্ছ করবে।>\nইগলেন নামের সেই ছেলেটি তবু চলে গেল।\nসে নিজের কুখ্যাত গল্প নিজেই লিখবে।"
  },
  Event_47311_Name = {
    Text = "ব্যারেলের ছেলে"
  },
  Event_47312_ChoiceDesc1 = {
    Text = "[Turn Page Forward] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 3টি উপসর্গের মধ্যে 1টি বিকশিত করো।"
  },
  Event_47312_ChoiceDesc2 = {
    Text = "[Turn Page Backward] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_47312_ChoiceDesc3 = {
    Text = "[Discard] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_47312_Desc = {
    Text = "তুমি প্যাপিরাসে বাঁধাই করা একটি বই খুঁজে পাও:\n..\nএকটি ছেলে একটি পিপের ভেতর লুকিয়ে, ভেসে যায় এক ফিলিস্তিন দ্বীপে।\nসে দুর্বল, ঘৃণ্য, আর উচ্চাভিলাষী।\nযখন অমর দৈত্যের গৌরব সকলে কে বিস্ময়ে স্তব্ধ করে দেয়,\nছেলেটি তখনও ছায়ায় লুকিয়ে থাকে, সেই আলোকে দূরে ঠেলে রাখে।\nপরে, গোলিয়াথ তাকে অর্পণ করে এক গুরুত্বপূর্ণ দায়িত্ব।\nকারণটা কী—"
  },
  Event_47312_Name = {
    Text = "ব্যারেলের ছেলে"
  },
  Event_47313_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47313_Desc = {
    Text = "তারপর দৈত্যটি বলল:\n「আমি তাকে পাশে রাখি, কারণ সে একই সঙ্গে বিষণ্ন ও প্রহসনময়।\nআর সে কোনোদিনই আমাকে হত্যা করতে পারবে না।」"
  },
  Event_47313_Name = {
    Text = "ব্যারেলের ছেলে"
  },
  Event_47314_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47314_Desc = {
    Text = "\nতুমি শেষ অংশটা শোনোনি, কিন্তু তার গানের কথা তোমাকে আরেকটি গানের কথা মনে করিয়ে দিল:\n「এই বিরল দৈত্য হাঙর, ঝড় আর বৃষ্টির বুকে, \nসমুদ্রই তার গৃহ, \nযেহেতু শক্তিই ন্যায়বিচার, সে শক্তিরই দৈত্য, \nসীমাহীন সাগরের রাজা সে।」"
  },
  Event_47314_Name = {
    Text = "নাবিকদের শ্যান্টি"
  },
  Event_47315_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47315_Desc = {
    Text = "এখন পড়ার সময় নয়。\nতুমি তাড়াতাড়ি বইটা ছুড়ে ফেলে দাও, শেষ কয়েকটি লাইন আর পড়া হয় না:\n..\nসে ছায়ায় লুকিয়ে থাকে, হিংসা থেকে নয়,\nশুধু নিখাদ ভয়ের কারণে。\nআলোয় এলেই তার তুচ্ছ আত্মা সম্পূর্ণ বিলুপ্ত হবে。\nভস্মও অবশিষ্ট থাকবে না।"
  },
  Event_47315_Name = {
    Text = "ব্যারেলের ছেলে"
  },
  Event_47463_ChoiceDesc1 = {
    Text = "[Enter Hypnosis] একজন জাগরণকারীকে বেছে নাও, যে আত্মিক বিভাজনের মধ্য দিয়ে যাবে এবং তার প্রাথমিক চারটি কমান্ড কার্ড হারাবে।"
  },
  Event_47463_Desc = {
    Text = "ডাক্তার বিশাল বইয়ের স্তূপ থেকে মুখ তুলে তাকালেন:\n“তুমি এক বিরল নমুনা, তাই তোমার কাছ থেকে আমি কোনো ফি নেব না।\nকিন্তু আমার আরেক ধরনের পারিশ্রমিক দরকার: এক হিপনোসিস।\nএটা এক নতুন ধরনের থেরাপি, যা নিয়ে আসে অনাবৃত, সম্পূর্ণ নগ্ন চেতনা।\nতাহলে, কী বলো? একবার চেষ্টা করে দেখতে চাও?”"
  },
  Event_47463_Name = {
    Text = "「হিপনোসিস স্নেক」"
  },
  Event_47464_ChoiceDesc1 = {
    Text = "[Shining Memory] [ExDesc1][ExDesc2]"
  },
  Event_47464_ChoiceDesc2 = {
    Text = "[Faded Memory] খোদাই করা সব সমবেত সুর প্রার্থনাগাথার গুণমান উন্নত করো।"
  },
  Event_47464_Desc = {
    Text = "সে ঘুরে বেড়ায় চেতনার সাগরের তীরে।\nতরঙ্গের আঁচল তার পা ছুঁয়ে যায়, বয়ে আনে বিক্ষিপ্ত স্মৃতিচারণ তটরেখার বালিতে।\nকিছু স্মৃতি উজ্জ্বল, কিছু ম্লান, আর কিছুতে লন্ডিনিয়ামের বর্ষাকালের গন্ধ লেগে আছে।\nকোন স্মৃতিটা তুমি কুড়িয়ে নেবে? সে ঘুরে বেড়ায় চেতনার সাগরের তীরে।"
  },
  Event_47464_Name = {
    Text = "「কোর ফিউশন」"
  },
  Event_47465_ChoiceDesc1 = {
    Text = "[চেষ্টা প্রত্যাখ্যান করুন]এলোমেলো 1টি কমান্ড কার্ডে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_47465_ChoiceDesc2 = {
    Text = "[Smash the Solvent] একটি পাপভারগ্রস্ত সৃষ্টি শুদ্ধিকরণ করো"
  },
  Event_47465_ChoiceDesc3 = {
    Text = "[Accept Experiment] 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_47465_Desc = {
    Text = "ডাক্তার উত্তেজিত হয়ে পান্না-সবুজ দ্রাবকটি ঝাঁকিয়ে তাকে বলল:\n\"এক চুমুক খেলেই তুমি প্রবেশ করবে এক সচেতন স্বপ্নে।\nএটি সমষ্টিগত অবচেতনের মানসিক প্রতিফলন।\nএখন তুমি অগণিত সত্তার সঙ্গে একই চেতনার সাগর ভাগ করে নেবে।\nতুমি কি এটি চেষ্টা করে দেখতে চাও?\""
  },
  Event_47465_Name = {
    Text = "\"সচেতন স্বপ্ন\""
  },
  Event_47466_ChoiceDesc1 = {
    Text = "[Answer Voice] আত্মিক বিভাজন জাগরণকারী থেকে ১টি কমান্ড কার্ড অর্জন করো।"
  },
  Event_47466_Desc = {
    Text = "দেহ এক খাঁচা, যেখানে খণ্ডাংশে ভাঙা ব্যক্তিত্বগুলো বন্দি।\n\"২৪\" নামের এই কারাগার এখন উপচে পড়ছে।\n\"ঘুমিয়ে পড়ো না, শান্ত হয়ো না।\"\nঅন্ধকারে, এক নরম কণ্ঠ হুইসপার করে।"
  },
  Event_47466_Name = {
    Text = "「আত্মজ্ঞান জাগরণ」"
  },
  Event_47848_ChoiceDesc1 = {
    Text = "[Close Your Eyes] 3টি সোনালি রেলিকের মধ্যে 1টি অর্জন করুন"
  },
  Event_47848_ChoiceDesc2 = {
    Text = "[Sneak a Peek] 2 জন জাগরণকারীকে জাগরণ করান। তাদের জাগরণ কার্ডের অ্যারিথমেটিকা ব্যয় 1 কমিয়ে দিন।"
  },
  Event_47848_ChoiceDesc3 = {
    Text = "[Open Your Eyes] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」, 「(RelicConfig.Arg2)」, এবং 「(RelicConfig.Arg3)」 অর্জন করুন।"
  },
  Event_47848_Desc = {
    Text = "হিপনোসিসে যাওয়ার আগে চিকিৎসক বলেছিলেন:\n「আমার অনুমতি ছাড়া চোখ খুলবে না।」\nতাই সে চোখ বন্ধই রাখল, শ্বাস নিল... ছাড়ল...\nঅর্ধনিদ্রিত অবস্থায়, সে যেন এক 「সসস」 শব্দ শুনতে পেল।\nতারপর সে অনুভব করল ঠান্ডা চোখের দৃষ্টি—\nকিছু একটা তাকে দেখছিল।\nতার কি চুপিচুপি একবার উঁকি মারা উচিত?"
  },
  Event_47848_Name = {
    Text = "「হিপনোসিস স্নেক」"
  },
  Event_47876_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47876_Desc = {
    Text = "সে ঝুঁকে পড়ে ঝলমলে স্মৃতিচারণ কুড়িয়ে নিল।\nএক, দুই... অগণিত আনন্দ তার ভেতরে প্লাবিত হলো।\nসে দুই হাত মেলে তাদের ঘিরে ঘুরতে লাগল।"
  },
  Event_47876_Name = {
    Text = "「কোর ফিউশন」"
  },
  Event_47877_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47877_Desc = {
    Text = "সে ঝুঁকে তুলে নেয় ম্লান স্মৃতিগুলো।\nএকটি、দুটি…অগণিত তুচ্ছ স্মৃতি একে একে ভিড় করে আসে،\nসে দুই বাহু মেলে দেয়، তাদের সবাইকে বুকে টেনে নেয়।"
  },
  Event_47877_Name = {
    Text = "「কোর ফিউশন」"
  },
  Event_47878_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47878_Desc = {
    Text = "তুমি এই অদ্ভুত দ্রাবকের শিকার হতে অস্বীকার করো।\nচিকিৎসক খানিকটা হতাশ হয়, কিন্তু তোমাকে জোর করে না।\n\"আমি মানবতার দীপ্তির কাপুরুষতা আর স্বল্পদৃষ্টিকে ক্ষমা করি।\""
  },
  Event_47878_Name = {
    Text = "\"সচেতন স্বপ্ন\""
  },
  Event_47879_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47879_Desc = {
    Text = "ধড়াম! তুমি বোতলটা আছাড় মেরে ভেঙে ফেলো。\nসবুজ দ্রবণ দ্রুত মেঝে ক্ষয় করতে থাকে。\n“হুঁ, এ তো ছিল নির্বোধ দুঃসাহস। তবে আশা করি, এর পুনরাবৃত্তি আর হবে না。\nনইলে হয়তো দুঃখে আমার চোখে জল এসে যাবে।”"
  },
  Event_47879_Name = {
    Text = "\"সচেতন স্বপ্ন\""
  },
  Event_47880_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47880_Desc = {
    Text = "তুমি এক ঢোঁকে সব গিলে ফেললে।\nগলপ, গলপ... তোমার মস্তিষ্ক আর গলায় বুদবুদ ফেটে উঠল।\nক্ষুদ্র টুকটুক করা আতশবাজির মতো।\n\"তোমাকে ধন্যবাদ, সাহসী মানব। তোমার সামনে অসীমতাকে স্পর্শ করার সুযোগ আসবে।\nআর আমি তার সাক্ষী হয়ে থাকব।\""
  },
  Event_47880_Name = {
    Text = "\"সচেতন স্বপ্ন\""
  },
  Event_47881_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47881_Desc = {
    Text = "সে চোখ খুলে বলল,\n「হ্যাঁ, সবই ভুল।\nঅশ্রু ঝরতেই হবে, আর মৃত্যু প্রতিরোধ করতেই হবে।」\nঅন্ধকারে সাঁই সাঁই শব্দ উঠল, যেন কোথাও থেকে এক স্নিগ্ধ সাড়া মিলল।"
  },
  Event_47881_Name = {
    Text = "「আত্মজ্ঞান জাগরণ」"
  },
  Event_47900_ChoiceDesc1 = {
    Text = "[I Saw a Snake] সোনালি রেলিক+ 「(RelicConfig.Arg1)」 অর্জন করুন"
  },
  Event_47900_ChoiceDesc2 = {
    Text = "[I Saw You] পাপভারগ্রস্ত সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করুন"
  },
  Event_47900_Desc = {
    Text = "টুপ。\nআঙুলের হালকা টুপ শব্দ তাকে বাস্তবে ফিরিয়ে আনল。\nডাক্তার কখন যে মুখটা কাছে এনেছে, টের পাওনি; তার কোবাল্ট-হলুদ চোখে উত্তেজনার ঝিলিক。\n「বল তো, একটু আগে তুমি কী দেখেছিলে?」"
  },
  Event_47900_Name = {
    Text = "「হিপনোসিস স্নেক」"
  },
  Event_47901_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47901_Desc = {
    Text = "সে চোখ খুলল।\nআলো-ছায়ার কুয়াশাচ্ছন্ন মিশ্রণে, সে যেন দেখল অন্ধকারে গুটিয়ে থাকা এক শান্ত সাদা সাপ, ধীরে ধীরে সরছে।\nও হ্যাঁ, আর তার চোখ—\nখাঁটি, নিষ্কলুষ সোনা।\nনা দুঃখ, না আনন্দ, না বিচার,\nযথেষ্ট, এক গ্রীষ্মরাত্রির দুঃস্বপ্ন থেকে ঘুমন্ত ডরমাউসকে জাগিয়ে তোলার জন্য।"
  },
  Event_47901_Name = {
    Text = "「হিপনোসিস স্নেক」"
  },
  Event_47909_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47909_Desc = {
    Text = "সে নিঃশব্দে এক চোখ মেলে দিল।\nযা সে দেখল, তা ছিল ঝাপসা সাদা আলো, অন্ধকারে ধীরে ধীরে কিলবিল করছে।\nআলোর ভেতরে ক্ষীণ সোনালি ঝলক টিমটিম করছিল, যেন তার অপরাধের জন্য তাকে সতর্ক করছে।\nসে আর তাকানোর সাহস পেল না।"
  },
  Event_47909_Name = {
    Text = "「হিপনোসিস স্নেক」"
  },
  Event_47910_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47910_Desc = {
    Text = "সে ডাক্তারের নির্দেশ মেনে চলে, কখনোই চোখ খোলে না।\nতার চারপাশের বাতাসে এক ঠান্ডা হাওয়া বয়ে যায়, মুখের গায়ে গিয়ে থামে।\nকিছুক্ষণ পর, সবকিছু আবার স্বাভাবিক হয়ে যায়।\nযেন কিছুই ঘটেনি।"
  },
  Event_47910_Name = {
    Text = "「হিপনোসিস স্নেক」"
  },
  Event_47911_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47911_Desc = {
    Text = "\n\"আমি দেখেছি... এক ভীষণ সুন্দর সাপ।\"\nচিকিৎসক এক মুহূর্তের জন্য থেমে গেলেন, কলমটি হাতে স্থির।\n\"কী ধরনের সাপ?\"\n\"ওটা ভীষণ সুন্দর! পুরোটা সাদা, তার গায়ে সোনালি নকশা...\"\nচিকিৎসক আর কিছু বললেন না, কেবল ঠোঁটের কোণে এক অতি ক্ষীণ হাসি ফুটে উঠল।\n\"ধন্যবাদ।\""
  },
  Event_47911_Name = {
    Text = "「হিপনোসিস স্নেক」"
  },
  Event_47912_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47912_Desc = {
    Text = "সে সোজা তাকিয়ে থাকে চিকিৎসকের কোবাল্ট-হলুদ চোখের দিকে.\n「আমি দেখি তুমি এক সাপে রূপান্তরিত হয়েছ।」\n「ওহ। তুমি এত নিশ্চিত কীভাবে যে এটা আমি?」\nকারণ সেটি রহস্যময়, স্থির, আর জটিল।\nআর...\nওটা ক্লান্ত দেখাচ্ছে, যেন সহস্রাব্দব্যাপী শীতনিদ্রা থেকে সদ্য জেগে উঠেছে।"
  },
  Event_47912_Name = {
    Text = "「হিপনোসিস স্নেক」"
  },
  Event_47992_ChoiceDesc1 = {
    Text = "[Connect] Arg2 HP পুনরুদ্ধার করো।"
  },
  Event_47992_ChoiceDesc2 = {
    Text = "[Meditate] একজন Awakener-কে Rouse করো।"
  },
  Event_47992_ChoiceDesc3 = {
    Text = "[Expel] সর্বোচ্চ 3টি উপসর্গ কার্ড ধ্বংস করো, এবং Arg2 সংখ্যক কালো চিহ্ন লাভ করো।"
  },
  Event_47992_Desc = {
    Text = "কুয়াশা ভারী হয়ে ঝুলে থাকে, আর তোমার ব্যাজে মিটমিট করে ফ্যাকাশে সিলভার আভা। যোগাযোগকারীটা কড়কড় শব্দ তুলে জেগে ওঠে। কেউ একজন ডাকছে।"
  },
  Event_47992_Name = {
    Text = "সংযোগস্থল"
  },
  Event_47992_Tips3 = {
    Text = "আপনার বর্তমানে কোনো উপসর্গ প্রকাশ পাচ্ছে না।"
  },
  Event_47993_ChoiceDesc1 = {Text = "[Leave]"},
  Event_47993_ChoiceDesc2 = {
    Text = "[Leave] একটি এলোমেলো কমান্ড কার্ডের প্রতিলিপি তৈরি করো, এবং অনুলিপিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_47993_Desc = {
    Text = "তুমি স্কুল থেকে আসা যোগাযোগ অনুরোধটি গ্রহণ করেছ। পরিচিত কণ্ঠস্বর তোমার মনকে শান্ত করে। তুমি মনোবল সঞ্চয় করে সামনে এগিয়ে যাও।"
  },
  Event_47993_Name = {
    Text = "সংযোগস্থল"
  },
  Event_48225_ChoiceDesc1 = {Text = "[Leave]"},
  Event_48225_Desc = {
    Text = "বিড়ালটি আনন্দে তোমার হাতের পিঠ চেটে দিল。\n“ধন্যবাদ। আমার জন্য চিন্তা কোরো না, মিঁয়াও。\nএখানে ব্যক্তিত্বেরা সবসময়ই মরে যায়, আবার জন্ম নেয়。\nআমি অবশ্যই ফিরে আসব!\nমিঁয়াও মিঁয়াও, মিঁয়াও মিঁয়াও মিঁয়াও!”"
  },
  Event_48225_Name = {
    Text = "শেষ কথা"
  },
  Event_48226_ChoiceDesc1 = {Text = "[Leave]"},
  Event_48226_Desc = {
    Text = "বিড়ালটা ভাবে তুমি তাকে বুঝতে পারোনি, তাই সে তোমার হাতে নাক ঘষে。\n「যদি তুমি রাজি হও, আমি তোমাকে আমার সব লুকানো খাবার দিয়ে দেব。\nওগুলো নিরাপদে রাখা আছে ক্যামব্রে জেলায় @2…」"
  },
  Event_48226_Name = {
    Text = "শেষ কথা"
  },
  Event_48227_ChoiceDesc1 = {Text = "[Leave]"},
  Event_48227_Desc = {
    Text = "তুমি আন্তরিকভাবে জর্জ-এর কাছে ক্ষমা প্রার্থনা করলে।\n\"হুঁ, অন্তত কিছু ভদ্রতা তো জানো।\nজর্জ অভিশাপের শক্তি ১০% কমানোর কথা বিবেচনা করবে,\nসর্বোচ্চ ১৫%—ওটাই জর্জ-এর সীমা।\""
  },
  Event_48227_Name = {
    Text = "জর্জের প্রেতাত্মা"
  },
  Event_48228_ChoiceDesc1 = {
    Text = "[Agree] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতাটি বিকশিত করো।"
  },
  Event_48228_ChoiceDesc2 = {
    Text = "[Reject It] 3টি সোনার রেলিক থেকে 1টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_48228_ChoiceDesc3 = {
    Text = "[Stay Silent] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_48228_Desc = {
    Text = "\n“ক্যাট ২৪ গুরুতরভাবে আহত, কষ্ট করে তোমাকে বলতে চেষ্টা করছে:\n“ম্যাঁও… আমার সময় ফুরিয়ে আসছে…\nআমার এক বন্ধু আছে, এক সিলভার কড ম্যাঁও。\nযদি কোনোদিন তাকে দেখো, তাকে বলো আমি অনেক দূরে চলে গেছি, ম্যাঁও。\nআমি খুব, খুব দীর্ঘ সময়ের জন্য চলে যাব, ম্যাঁও。\nআমি ফিরব অনেক অনেক ফ্রাই নিয়ে, কিন্তু ভাজা মাছ ছাড়া, ম্যাঁও。\nতোমাকে অবশ্যই তাকে বলতে হবে!”"
  },
  Event_48228_Name = {
    Text = "শেষ কথা"
  },
  Event_48229_ChoiceDesc1 = {Text = "[Leave]"},
  Event_48229_Desc = {
    Text = "বিড়ালটি সামান্য হতাশ হল।\nকিন্তু সে সবসময়ই ভদ্র ও অনুগত একটি বাচ্চা বিড়াল ছিল, কখনো কাউকে জোর করত না।\nশেষ পর্যন্ত, সে অনুতাপে চোখ বুজল।"
  },
  Event_48229_Name = {
    Text = "শেষ কথা"
  },
  Event_48230_ChoiceDesc1 = {
    Text = "[Apologize to It] 「(RelicConfig.Arg1)」 নামের রৌপ্য সৃষ্টি অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_48230_ChoiceDesc2 = {
    Text = "[Taunt It] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_48230_ChoiceDesc3 = {
    Text = "[Disregard It] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_48230_Desc = {
    Text = "একটি প্রেতাত্মা, জর্জের প্রেতাত্মা, তোমার মাথার ওপর ভেসে বেড়াচ্ছে。\n\"জর্জ মরেছে অপমানিত হয়ে。\nকিন্তু তাতে কী আসে যায়। জর্জ এই অপমান চিরকাল মনে রাখবে。\nরক্ষক, তুমি কিন্তু গভীর বিপদে পড়েছ, হেহ হেহ হেহ…\""
  },
  Event_48230_Name = {
    Text = "জর্জের প্রেতাত্মা"
  },
  Event_48231_ChoiceDesc1 = {Text = "[Leave]"},
  Event_48231_Desc = {
    Text = "\"হেহে, কী দুঃসাহস, তুমি জর্জকে উপহাস করো。\nচিন্তা কোরো না, তুমি খাও, ঘুমাও, কিংবা গান গাও…\nজর্জ সবসময় তোমার চারপাশে ভেসে বেড়াবে, মনে করিয়ে দেবে, যন্ত্রণা দেবে。\nযাতে তুমি চিরকাল তোমার পাপ মনে রাখো。\nতুমি কোনোদিনই প্রেতাত্মাকে ধরতে পারবে না, লা লা লা~\""
  },
  Event_48231_Name = {
    Text = "জর্জের প্রেতাত্মা"
  },
  Event_48232_ChoiceDesc1 = {Text = "[Leave]"},
  Event_48232_Desc = {
    Text = "তুমি এগিয়ে গেলে, জর্জের অভিশাপ পেছনে ফেলে।\nপেছন থেকে কান্নার শব্দ ভেসে এল; জর্জ হাউমাউ করে কাঁদছে।\n“উঁউ... আমার মতো এত সুন্দর কেউ কী করে হয়ে গেল—\nবীভৎস! বীভৎস!\nজর্জ বরং প্যান্ডিয়ার চাবুকের নিচে মরতে রাজি!”"
  },
  Event_48232_Name = {
    Text = "জর্জের প্রেতাত্মা"
  },
  Event_49055_ChoiceDesc1 = {
    Text = "[Summon Awakeners] সব জাগরণকারী 100 অ্যালিমাস হারাবে। একটি উপসর্গ কার্ড ধ্বংস করো।"
  },
  Event_49055_ChoiceDesc2 = {
    Text = "[Struggle] Arg1 পরিমাণ HP পুনরুদ্ধার করো, তবে 「(Skill.Arg2)」 উপসর্গটি দুইবার বিকশিত করো।"
  },
  Event_49055_ChoiceDesc3 = {
    Text = "[Harness Silver Key] সব Keyflare হারাও।"
  },
  Event_49055_Desc = {
    Text = "তুমি যখন মিটমিট করা রক্তছিটার পুকুরে পা রাখো, তার আসল রূপ উন্মোচিত হয়।\nরক্তিম-কালো রক্ত অসংখ্য বাহু বাড়িয়ে তোমার গোড়ালিতে আঁকড়ে ধরে, আর তোমাকে নির্দয়ভাবে টেনে নিয়ে যায় অতল গহ্বরের দিকে।"
  },
  Event_49055_Name = {
    Text = "রক্তাক্ত পুকুর"
  },
  Event_49097_ChoiceDesc1 = {
    Text = "[Move Forward]"
  },
  Event_49097_Desc = {
    Text = "তোমার পেটের ভেতর হিংস্রভাবে মোচড়াতে থাকে, কিন্তু কয়েক সেকেন্ড পর অলৌকিকভাবে শান্ত হয়ে যায়। অদ্ভুতভাবে, তুমি যেন নিজের ভেতরে আরেকটি হৃদস্পন্দন শুনতে পাও..."
  },
  Event_49097_Name = {
    Text = "পালনকারী মাতা"
  },
  Event_49098_ChoiceDesc1 = {
    Text = "[এক চুমুকে পান করো][ExDesc3][ExDesc4]টি কমান্ড কার্ড বেছে নিন, সেগুলো অরিসন অর্জন করুক：「(EnchantConfig.Arg1)」[ExDesc1][ExDesc2]"
  },
  Event_49098_Desc = {
    Text = "নিচু পাথুরে দেওয়ালের ফাঁক থেকে একটি জীর্ণ হাঁড়ি তোমার দিকে তাকিয়ে থাকে।\nমরুভূমিতে পানি সবচেয়ে মূল্যবান সামগ্রী; আর মদ হলো উন্মাদনা ও মায়াস্বপ্নের দ্বার।\nএই অনুর্বর ভূমিতে, কোনো সুস্থ মানুষের পক্ষেই তার প্রলোভন প্রতিরোধ করা কঠিন।"
  },
  Event_49098_Name = {
    Text = "পালনকারী মাতা"
  },
  Event_49312_ChoiceDesc1 = {Text = "[Leave]"},
  Event_49312_Desc = {
    Text = "রৌপ্য চাবি গ্লিমার ছড়ায়; বাহুগুলো যেন কোনো শক্তিতে ভীত হয়ে পুকুরের ভেতরে সরে গিয়ে মিলিয়ে যায়।"
  },
  Event_49312_Name = {
    Text = "রক্তাক্ত পুকুর"
  },
  Event_49313_ChoiceDesc1 = {Text = "[Leave]"},
  Event_49313_Desc = {
    Text = "তুমি মরিয়া হয়ে লড়াই করো, কিন্তু আরও গভীরে ডুবে যেতে থাকো, মনের ভেতর অভিশপ্ত হুইসপার তোমাকে যন্ত্রণা দেয়।\nহুঁশ ফিরলে দেখো, রক্তলাল শুঁড়গুলো সরে গেছে, তৃপ্ত। তুমি অদ্ভুতভাবে রিফ্রেশ অনুভব করছ, যদিও মনে হয় কিছু একটা চিরতরে হারিয়ে গেছে..."
  },
  Event_49313_Name = {
    Text = "রক্তাক্ত পুকুর"
  },
  Event_49314_ChoiceDesc1 = {Text = "[Leave]"},
  Event_49314_Desc = {
    Text = "উদীয়মান জাগ্রতকারী বিন্দুমাত্র দ্বিধা না করে তোমাকে রক্তের পুকুর থেকে টেনে তোলে। তোমাদের জোড়া বাহু ছিঁড়ে যাওয়ার মতো টানে, কাদামাখা জল ছিটকে ওঠে, আর অগণিত প্রায় অদৃশ্য প্রাণী জলের ভেতর কিলবিল করতে থাকে, যেন তারা কিছু কামনা করছে, কিছু গ্রাস করছে।"
  },
