  },
  Event_49907_Desc = {
    Text = "\"তুমি সব সময় কৌতূহলী চোখে আমার শিংয়ের দিকে তাকিয়ে থাকো কেন? কোনো জিজ্ঞাসা?\"\nথাইস হঠাৎ তোমার কাঁধের কাছে ঝুঁকে আসে, মধুরঙা দানাগুলো আলতো করে তোমার গালে গিয়ে ছুঁয়ে যায়।"
  },
  Event_49907_Name = {
    Text = "শৃঙ্গধারী"
  },
  Event_49908_ChoiceDesc1 = {Text = "[Look Up]"},
  Event_49908_ChoiceDesc2 = {
    Text = "[Approach Thais]"
  },
  Event_49908_Desc = {
    Text = "ধ্বংসস্তূপে ধুলো ও ধোঁয়া চারদিকে ছড়িয়ে পড়ল, এক কোণের ভাঙা জানালার বাইরে হঠাৎ থাইসের অবয়ব দেখা গেল। সে কোনো দ্বিধা ছাড়াই ধুলোয় ঢাকা জানালার কিনারায় ঝুঁকে পড়ল, রহস্যময়ভাবে ঘরের কড়িকাঠের দিকে ইশারা করল।"
  },
  Event_49908_Name = {
    Text = "গুপ্তজাত"
  },
  Event_49909_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_49909_Desc = {
    Text = "তুমি মাথা তুলে দেখো মরচেধরা তামার পাইপগুলো উপরে বিশাল মাকড়সার জালের মতো ছড়িয়ে আছে। একটি ছায়া দ্রুত সরে গেল—ওটা কি খাবারের খোঁজে বেরোনো কোনো বন্য বিড়াল, নাকি অন্ধকারে ওত পেতে থাকা কোনো দানব?\nতুমি ফিরে তাকাতেই দেখো, থাইস উধাও।"
  },
  Event_49909_Name = {
    Text = "গুপ্তজাত"
  },
  Event_49910_ChoiceDesc1 = {
    Text = "[Stare at Her]"
  },
  Event_49910_ChoiceDesc2 = {Text = "[Call Her]"},
  Event_49910_Desc = {
    Text = "তুমি আবার সেই 「মায়াভ্রম」টিকে দেখতে পাও।\nএইবার, তুমি ইতিমধ্যেই তার নাম জানো।\nথাইস দূরের মাতৃবৃক্ষের নিচে দাঁড়িয়ে, তাকে উদ্দেশ করে ভক্তিভরে প্রার্থনা করছে।\nতার অবয়ব ছিল অস্পষ্ট, মাতৃবৃক্ষের মায়াভ্রমের সঙ্গে মিশে গিয়েছিল।"
  },
  Event_49910_Name = {
    Text = "প্রার্থনাকারী"
  },
  Event_49911_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_49911_Desc = {
    Text = "তুমি থাইসের অবয়বের দিকে তাকিয়ে থাকো; মহাপ্রলয়ের ঝড়ের মাঝে তার ছায়া যেন এক পবিত্র ও মহিমান্বিত একাকী শৃঙ্গ, উন্মত্ত বালুঝড়েও যার মহিমা ম্লান হয় না।\nতার পদক্ষেপ ধীর অথচ অবিচল, তার ভঙ্গি মহৎ ও অম্লান, যা তোমাকে মুগ্ধ করে রাখে।"
  },
  Event_49911_Name = {
    Text = "মৃত্যুহীন সত্তা"
  },
  Event_49912_ChoiceDesc1 = {
    Text = "[Leave] একটি কমান্ড কার্ড অনুলিপি করো"
  },
  Event_49912_Desc = {
    Text = "\n\"তোমার অনুমান কী?\"\nসে হুইসপার করে \"শ্\", আরও কাছে ঝুঁকে আসে। তুমি অনুভব কর তার শিংয়ের ডগা তোমার গালে ছুঁয়ে যাচ্ছে, রেখে যাচ্ছে শীতল আর সুড়সুড়ি-ধরা এক অনুভূতি..."
  },
  Event_49912_Name = {
    Text = "শৃঙ্গধারী"
  },
  Event_49913_ChoiceDesc1 = {
    Text = "[চলে যাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_49913_Desc = {
    Text = "「ছুঁতে চাইলে সোজা বললেই তো হয়। আমি কি তোমাকে ফিরিয়ে দিতাম?」\nসে মৃদু হেসে তোমার হাত ধরে, তার আঙুলের ডগার উষ্ণতা আর মসৃণতা তোমাকে প্রায় মোহগ্রস্ত করে তোলে..."
  },
  Event_49913_Name = {
    Text = "শৃঙ্গধারী"
  },
  Event_49914_ChoiceDesc1 = {
    Text = "[Leave] এক জাগরণকারীকে জাগরণ ঘটাও, সেই কার্ডের অ্যারিথমেটিকা ব্যয় 1 কমাও, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_49914_Desc = {
    Text = "তুমি অন্যদের সঙ্গে হাঁটু গেড়ে বসে পড়ো।\n「আমি জানতাম, জানতাম! রানি, মহামান্যা সবসময় আমাদের রক্ষা করে এসেছেন!」\nআনন্দাশ্রু আর দীর্ঘ হাহাকারের শব্দ হু হু করে বয়ে যাওয়া বাতাসের সঙ্গে মিশে, অনুরণিত হয়ে তোমার করোটির ভেতর কাঁপন তোলে।\nঅস্পষ্টভাবে, এক গুরুত্বপূর্ণ চিন্তা ঝলক দিয়ে যায়, কিন্তু তুমি তাকে ধরতে পারো না।"
  },
  Event_49914_Name = {
    Text = "মৃত্যুহীন সত্তা"
  },
  Event_49915_ChoiceDesc1 = {
    Text = "[Leave] 3টির মধ্যে 1টি রৌপ্য সৃষ্টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_49915_Desc = {
    Text = "তুমি তাকে হাত নাড়ো.\n「তুমি কী করছো?」 র‍্যামোনা বিভ্রান্ত হয়ে তোমার দিকে তাকায়.\n「ওখানে...」\nতুমি বাক্য শেষ করার আগেই, দূরের সেই নারী ইতিমধ্যে অদৃশ্য হয়ে গেছে.\nতবে কি ওটা এক মায়াস্বপ্ন ছিল?"
  },
  Event_49915_Name = {
    Text = "জল-প্রণামকারী"
  },
  Event_49916_ChoiceDesc1 = {
    Text = "[Respond to Her]"
  },
  Event_49916_ChoiceDesc2 = {Text = "[Hesitate]"},
  Event_49916_Desc = {
    Text = "দূর থেকে তুমি দেখতে পাও, নদীর ঘাটে এক নারী জল তুলছে。\nমনে হয় তোমার দৃষ্টি টের পেয়ে সে ঘুরে দাঁড়ায় এবং তোমার দিকে হাত নাড়ে。\nতুমি লক্ষ্য করো, তার ঘুরে দাঁড়ানোর ভঙ্গিতে কিছু অস্বাভাবিকতা আছে।"
  },
  Event_49916_Name = {
    Text = "জল-প্রণামকারী"
  },
  Event_49917_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_49917_Desc = {
    Text = "তোমার দ্বিধার মাঝেই, সেই নারী ঘুরে দাঁড়ায় এবং ওয়েসিসে ঝাঁপ দেয়, দৃষ্টির আড়ালে মিলিয়ে যায়।\nতুমি নিজের চোখকেই বিশ্বাস করতে পারো না... তার কি ছাগলের খুর ছিল?"
  },
  Event_49917_Name = {
    Text = "জল-প্রণামকারী"
  },
  Event_49918_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_49918_Desc = {
    Text = "「হে বৃক্ষ, অনুগ্রহ করে @1 মানুষের প্রার্থনা শোনো, আমি তোমার দুধে স্নান করে পুনর্জন্ম নেব, তোমার প্রতিনিধি হব, তোমার হয়ে হলুদ বালির মধ্যে হেঁটে বেড়াব, তোমার শিকড়কে লেমওয়াহির প্রতিটি কোণে নাগাল পৌঁছে দেব……」\n\nএকের পর এক শিশুর কণ্ঠের প্রার্থনার শব্দ স্থানটিতে প্রতিধ্বনিত হচ্ছিল।"
  },
  Event_49918_Name = {
    Text = "প্রার্থনাকারী"
  },
  Event_49919_ChoiceDesc1 = {
    Text = "[Leave] একজন দৈবচয়নকৃত জাগরণকারীকে জাগিয়ে তুলুন"
  },
  Event_49919_Desc = {
    Text = "থাইসের দ্ব্যর্থক, দুর্বোধ্য দৃষ্টি তোমার মনোযোগ কেড়ে নেয়। এক অদ্ভুত, শিউরে ওঠা শক্তি তোমাকে মন্ত্রমুগ্ধ করে, যেন তুমি অদম্য টানে তার দিকে টেনে নেওয়া হচ্ছ।\n「নিশ্চয়ই, যা দেখা যায় না, তা-ও অস্তিত্বশীল।」\nসে তোমার কানে খুব আস্তে ফিসফিস করে। তোমার মনে হয় তুমি যেন কিছু ধরতে পেরেছ, কিন্তু তা সাদা গজের স্তূপে ঢাকা, অস্পষ্ট, অধরা।\nএ কি কোনো ভবিষ্যদ্বাণী? চোখের পলকে থাইস বিন্দুমাত্র চিহ্ন না রেখে মিলিয়ে যায়।"
  },
  Event_49919_Name = {
    Text = "গুপ্তজাত"
  },
  Event_49920_ChoiceDesc1 = {Text = "[Gaze]"},
  Event_49920_ChoiceDesc2 = {Text = "[Kneel]"},
  Event_49920_Desc = {
    Text = "ভেড়ার কালো খুর বালুকাময় ভূমির ওপর পা ফেলে।\nথাইস এক অজানা জীবের উদ্দেশে প্রার্থনা জপে, আর অগণিত আরাম গোষ্ঠী তার চলার দিকেই হাঁটু গেড়ে বসে।"
  },
  Event_49920_Name = {
    Text = "মৃত্যুহীন সত্তা"
  },
  Event_49921_ChoiceDesc1 = {
    Text = "[Leave] 3টি সোনার রেলিকের মধ্যে 1টি অর্জন করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_49921_Desc = {
    Text = "দৈত্যাকার গাছটি হাজার হাজার মোটা ডাল বাড়িয়ে দেয়, জড়িয়ে থাকা শুঁড়ের মতো, থাইসের কবজি আর গোড়ালি বেঁধে ফেলে, তার ছটফটানি উপেক্ষা করে, জোর করে তার দেহটাকে গাছের স্ফীত কাণ্ডের ভেতরে টেনে নেয়...\n\nদূরের এক মায়াস্বপ্ন হয়েও, ঢেউ খেলানো জলের মাধ্যমে তার যন্ত্রণা তোমার হৃদয়ের সঙ্গে অনুরণিত হয়।"
  },
  Event_49921_Name = {
    Text = "প্রার্থনাকারী"
  },
  Event_49922_ChoiceDesc1 = {
    Text = "[Leave] রেলিক 「(RelicConfig.Arg1)」 অধিকার করো"
  },
  Event_49922_Desc = {
    Text = "\nনিষ্প্রাণ অঙ্গপ্রত্যঙ্গ গাছের রসের মতো ডাল বেয়ে নেমে আসে; সে প্রাণপণে লড়াই করে, তবু তার দেহ আচরণ করে এক টলমল, বিকৃত কৃমির মতো, যা কোনোভাবেই কথা শোনে না।\n\"হাড়গুলো সম্পূর্ণ দ্রবীভূত হয়ে গেছে,\" থাইসের মুখে এক শোকভরা অভিব্যক্তি ভেসে ওঠে, \"সে গাছেরই এক অংশ হয়ে গেছে।\"\n\"আমাদের দরকার এই অবস্থাকে উল্টে দেওয়ার শক্তি... এমন এক শক্তি, যা সময়কেও অতিক্রম করে।\""
  },
  Event_49922_Name = {
    Text = "কলুষিত"
  },
  Event_49923_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_49923_Desc = {
    Text = "「আর ওই 「উল্টো, মণিহীন চোখ」... সেটা যেন আত্মার গভীর থেকে কিছু নাড়া দেয়...」\n「ওহ? আমার কথাই বলছ?」\n「তোমার গল্প বলার প্রতিভা নিয়ে মেডিনেট বকবক করছিল।」\n\nসেই রাতে, নীরবে জ্বলতে থাকা ক্যাম্পফায়ারের পাশে বসে, সে তোমার পানপাত্র আবার ভরে দিয়েছিল।"
  },
  Event_49923_Name = {
    Text = "কলুষিত"
  },
  Event_49924_ChoiceDesc1 = {
    Text = "[Cut the Tumor]"
  },
  Event_49924_ChoiceDesc2 = {Text = "[Recall]"},
  Event_49924_Desc = {
    Text = "একটি বৃক্ষ-টিউমার。\nএটি এক অশুভ, ফোলা ছন্দে স্পন্দিত হয়, আর তার ভঙ্গুর, স্বচ্ছ রক্তিম চামড়ার ভেতর দিয়ে এক বিকৃত, যন্ত্রণাময় মুখ দেখা যায়, যেন গুটিরূপ ভেদ করে বেরিয়ে আসার উপক্রম。\n「মেডিনাইট।」 থাইসের মুখে শোকের ছাপ ফুটে ওঠে, যখন সে মৃদু স্বরে সেই মুখটির নাম ধরে ডাকে।"
  },
  Event_49924_Name = {
    Text = "কলুষিত"
  },
  Event_49939_ChoiceDesc1 = {
    Text = "[Trust Ryker] সব জাগরণকারীর অ্যালিমাস Arg1 দ্বারা বৃদ্ধি করো"
  },
  Event_49939_ChoiceDesc2 = {
    Text = "[Worry About Ryker] 2 জন জাগরণকারীকে জাগরণ ঘটাও"
  },
  Event_49939_Desc = {
    Text = "\"আমার ভাগ্যের ওপর ভরসা রাখুন।\""
  },
  Event_49939_Name = {
    Text = "ভাগ্যবান গোয়েন্দা"
  },
  Event_49940_ChoiceDesc1 = {Text = "[Leave]"},
  Event_49940_Desc = {
    Text = "রাইকার তিনটি বিষয়ে পারদর্শী: গোপন অনুসন্ধান, শোনা, আর পাশা নিক্ষেপ।\nঅন্য কথায়, সে যুদ্ধের কৌশলে দক্ষ নয়।\nতোমার দুশ্চিন্তা নিয়ন্ত্রণের বাইরে বেড়ে ওঠে, আর উন্মাদনা ছড়িয়ে পড়ে।"
  },
  Event_49940_Name = {
    Text = "ভাগ্যবান গোয়েন্দা"
  },
  Event_49941_ChoiceDesc1 = {Text = "[Leave]"},
  Event_49941_Desc = {
    Text = "যে হৃদয় বিশ্বাস করে, সেটাই ম্যাজিক; তার সামনে থাকা সব বাধা সে নিশ্চয়ই অতিক্রম করবে।"
  },
  Event_49941_Name = {
    Text = "ভাগ্যবান গোয়েন্দা"
  },
  Event_49943_ChoiceDesc1 = {Text = "[Leave]"},
  Event_49943_Desc = {
    Text = "তুমি লজ্জিত বোধ করো, তবু আশাব্যঞ্জক দৃষ্টিতে অসুস্থ র‍্যামোনার দিকে তাকিয়ে থাকো।\n\"আমি করব।\"\nলজ্জায় লাল হয়ে সে তার অসীম-ধারণক্ষমতার হ্যান্ডব্যাগ থেকে একটি নতুন সংগ্রহের শিশি বের করে দ্রুত মাকড়সাটিকে ঢেকে দেয়।"
  },
  Event_49943_Name = {
    Text = "বিষমাকড়সা"
  },
  Event_49944_ChoiceDesc1 = {Text = "[Leave]"},
  Event_49944_Desc = {
    Text = "রাইকার আঙুলে টোকা দিয়ে, তার লোমশ তর্জনী বাড়িয়ে দেয় সামনের পা তোলা এক মাকড়সার দিকে。\nএ ধরনের রঙিন নকশাওয়ালা প্রজাতি প্রায়ই বিষাক্ত হয়। তুমি তাকে সাবধান করতে যাচ্ছিলে, কিন্তু যে মাকড়সা একটু আগেও শত্রুভাবাপন্ন ছিল, সেটাই হালকা লাফিয়ে তার আঙুলের ডগায় উঠে গিয়ে গুটিয়ে বসে。\nযা হোক, নিয়তি যেমন, তেমনই।"
  },
  Event_49944_Name = {
    Text = "বিষমাকড়সা"
  },
  Event_49945_ChoiceDesc1 = {
    Text = "[Look at Ramona] 3টি প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_49945_ChoiceDesc2 = {
    Text = "[Look at Ryker] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে যেকোনো একটিতে খোদাই করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_49945_Desc = {
    Text = "অসংখ্য যৌগিক চোখ তোমার দিকে স্থির হয়ে যায়।\nপ্রাণীটি এক পা পিছিয়ে যায়, দাঁত ও নখর বের করে তোমাকে ভয় দেখানোর চেষ্টা করে।\nতার উঁচু করা পা ও পেডিপ্যাল্প, আর দেহকে সমর্থন করা দুই জোড়া অঙ্গ দেখে স্পষ্ট বোঝা যায়, এটি এক বিরল আরাকনিড।\nচজর্টের বিদায়বেলায় বলা কথা তোমার মনে প্রতিধ্বনিত হয়: \"অতিরিক্ত কাজ: স্থানীয় প্রজাতির নমুনা সংগ্রহ করে স্থানীয় জরিপকেন্দ্রে সংরক্ষণ করো।\"\nতুমি ব্যাকপ্যাকে রাখা সংগ্রহের বোতলটা ঝাঁকাও; সপ্তাহের পর সপ্তাহ পদযাত্রার পর সেটি ইতোমধ্যেই পোকামাকড়ে ঠাসা।"
  },
  Event_49945_Name = {
    Text = "বিষমাকড়সা"
  },
  Event_49946_ChoiceDesc1 = {Text = "[Leave]"},
  Event_49946_Desc = {
    Text = "\"সময়ের তোয়াক্কা না করা লোভ এক প্রকার রোগ।\""
  },
  Event_49946_Name = {
    Text = "তোমার উত্তর"
  },
  Event_49947_ChoiceDesc1 = {Text = "[Leave]"},
  Event_49947_Desc = {
    Text = "\"স্ক্রিপ্ট মুখস্থ বললে স্নেহ জুটবে না, বাছা।\""
  },
  Event_49947_Name = {
    Text = "তোমার উত্তর"
  },
  Event_49948_ChoiceDesc1 = {
    Text = "[Golden Key] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতাটি বিকশিত করো।"
  },
  Event_49948_ChoiceDesc2 = {
    Text = "[Iron Key] 3টি সোনার রেলিক থেকে 1টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_49948_ChoiceDesc3 = {
    Text = "[Silver Key] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_49948_Desc = {
    Text = "দুপুরে, পবিত্র নদীর বাষ্প ঘনীভূত হয়ে শূন্যতার দুইটি মায়াভ্রমে রূপ নেয়。\nসেই মায়াভ্রমের ভেতর থেকে এক কুয়াশাচ্ছন্ন কণ্ঠ তোমাকে জিজ্ঞেস করে: এটা কি তুমি ফেলে দেওয়া সোনার চাবি, রৌপ্য চাবি, নাকি লোহার চাবি?"
  },
  Event_49948_Name = {
    Text = "তোমার উত্তর"
  },
  Event_49949_ChoiceDesc1 = {Text = "[Leave]"},
  Event_49949_Desc = {
    Text = "\"সততা প্রায়ই অধিক সুরক্ষিত পরিণতির দিকে নিয়ে যায়, কিন্তু একই সঙ্গে, তুমি হয়তো কিছু হারিয়ে ফেলতে পারো।\""
  },
  Event_49949_Name = {
    Text = "তোমার উত্তর"
  },
  Event_50013_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50013_Desc = {
    Text = "তুমি চেষ্টা করো মানুষের মুখটা বোঝার, কিন্তু জলের ঢেউয়ের সঙ্গে সঙ্গে তা কেঁপে ওঠে, অস্পষ্টই থেকে যায়。\n\nযতই মনোযোগ দাও, তোমার শ্বাসপ্রশ্বাস ততই দুর্বলতা গ্রস্ত হয়, অক্সিজেনের অভাবের মাথা ঘোরানো অনুভূতি তোমার চেতনাকে ঢেকে ফেলে। কেবল যখন তুমি রামোনার কণ্ঠে নিজের নাম শুনতে পাও, তখনই কষ্টেসৃষ্টে বাস্তবে ফিরে আসো。\nজলের ওপর সূর্যের প্রতিফলন চোখ-ধাঁধানো, তবু পৃষ্ঠের নিচে যেন কিছু একটার ঝিলিক লুকিয়ে আছে।"
  },
  Event_50013_Name = {
    Text = "মৃত্যুর মরীচিকা"
  },
  Event_50014_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50014_Desc = {
    Text = "মায়াভ্রমটি মুহূর্তেই তোমার হাত থেকে মিলিয়ে যায়, রেখে যায় কেবল কপালের ভেতর এক তীক্ষ্ণ যন্ত্রণা।\nজলে প্রতিফলিত সূর্য চোখ-ধাঁধানো, তবু মনে হয় পৃষ্ঠের নিচে কিছু একটার গ্লিমার জ্বলে উঠছে।"
  },
  Event_50014_Name = {
    Text = "মৃত্যুর মরীচিকা"
  },
  Event_50015_ChoiceDesc1 = {
    Text = "[Strive to Recognize] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_50015_ChoiceDesc2 = {
    Text = "[Reach out and Touch] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_50015_ChoiceDesc3 = {
    Text = "[Rub Your Eyes] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_50015_Desc = {
    Text = "নুবিয়া তোমাকে ধাক্কা দেয়, আর তোমার পায়ের অর্ধেক পবিত্র নদীর ভেতর ডুবে যায়।\nতুমি নিজেকে সামলাতে লড়াই করছ, কিন্তু ঢেউ খেলানো জলে এক অপ্রত্যাশিত প্রতিবিম্ব দেখতে পাও।\nওটা মিথাগের ইউনিফর্ম পরা এক লম্বা তরুণ পুরুষ, তার নিস্তেজ দেহ পবিত্র নদীর স্রোতে ডুবে আছে।"
  },
  Event_50015_Name = {
    Text = "মৃত্যুর মরীচিকা"
  },
  Event_50016_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50016_Desc = {
    Text = "আতঙ্ক তোমার মস্তিষ্ককে ক্ষয় করে, যন্ত্রণায় তোমার চেতনা ঝাপসা হয়ে যায়। তুমি মরিয়া হয়ে ছটফট করো, কিন্তু লতাগুলো আরও শক্ত করে জড়িয়ে ধরে; দুর্গন্ধময় শ্লেষ্মা তোমার নাসারন্ধ্রে ঢুকে পড়ে, প্রতিটি শ্বাস ভরে ওঠে আঠালো হতাশায়।\nরামোনা স্ট্রাইক করে। নুবিয়া কাটা পা নিয়ে পালিয়ে যায়। তুমি মুখে লেগে থাকা শেষ শুঁড়টিও ছিঁড়ে ফেলো, তোমার মুখ জুড়ে লেগে থাকে কাদামাখা মাংসের থকথকে স্তর।"
  },
  Event_50016_Name = {
    Text = "সম্মুখ আক্রমণ"
  },
  Event_50017_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50017_Desc = {
    Text = "রৌপ্য আলো নুবিয়ার দেহ ভেদ করে, আর মাংস ফেটে যাওয়ার অনুভূতি রৌপ্য চাবি বেয়ে পৌঁছে যায় তোমার আঙুলের ডগা আর কবজিতে।\nনুবিয়ার বিকৃত অঙ্গপ্রত্যঙ্গ আকাশের দিকে উঠে যায়, ভয়াবহ আর করুণ এক আর্তনাদ ছড়িয়ে দিয়ে, সম্পূর্ণ রূপান্তরিত হয় আঠালো এক অজানা তরলে।"
  },
  Event_50017_Name = {
    Text = "সম্মুখ আক্রমণ"
  },
  Event_50018_ChoiceDesc1 = {
    Text = "[Tear] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_50018_ChoiceDesc2 = {
    Text = "[বিদ্ধকরণ]এলোমেলোভাবে 1টি কমান্ড কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg1)」"
  },
  Event_50018_Desc = {
    Text = "নুবিয়ার লতাগুল্মের মতো শাখাগুলো পেঁচিয়ে উঠে নৃত্য করতে থাকে, সুযোগ বুঝে তোমার মুখের দিকে চাবুকের মতো ঝাঁপিয়ে পড়ে, হিংস্রভাবে তোমার মুখ ও নাসারন্ধ্রে অনুপ্রবেশ করে।"
  },
  Event_50018_Name = {
    Text = "সম্মুখ আক্রমণ"
  },
  Event_50019_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50019_Desc = {
    Text = "জলের পৃষ্ঠে ঢেউয়ের আলো ঝিলমিল করছে।\nতুমি ভেজা পা তুলো এবং জুতোর ভেতরের স্যাঁতসেঁতে বালি ঝেড়ে ফেলো।\nআগের সেই দৃশ্যটি এখনো মনের ভেতর ভাসছে, মুছে যেতে অস্বীকার করছে।"
  },
  Event_50019_Name = {
    Text = "মৃত্যুর মরীচিকা"
  },
  Event_50029_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50029_Desc = {
    Text = "\"সে কি ফিরে আসবে? নাকি এই সীমাহীন মরুভূমিতে সে তোমাকে চিরতরে ফেলে চলে যাবে?\"\n\"সে কি তোমাকে খুঁজে পাবে? নাকি বদলে যাওয়া হাওয়া আর বালিয়াড়ি তার কাছ থেকে তোমার অবস্থানই কেড়ে নেবে?\"\n\"অন্যের ওপর যে আশা তুমি ন্যস্ত করো, তা কি সত্যিই নির্ভরযোগ্য?\""
  },
  Event_50029_Name = {
    Text = "হারানো মগ্নচড়া"
  },
  Event_50030_ChoiceDesc1 = {
    Text = "[Seek Rescue] একটি এলোমেলো জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_50030_ChoiceDesc2 = {
    Text = "[Move Forward] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে যেকোনো একটিতে খোদাই করো।"
  },
  Event_50030_Desc = {
    Text = "এক প্রাচীন, সুদূরের কণ্ঠস্বর, বয়ে চলা জলের শব্দের সঙ্গে মিশে, তোমাকে একটি জিজ্ঞাসা ছুড়ে দেয়।\n「তুমি হারিয়ে গেছ অন্তহীন বালুর মাঝে।」\n「তোমার সামনে দুটি নির্বাচন। তোমার সঙ্গী চলতে পারে দ্রুততর; তাকে খাদ্য আর জল দিয়ে সাহায্য খুঁজতে পাঠিয়ে দাও, আর তুমি পেছনে থেকে ভোগ কমিয়ে দাও।」\n「অথবা তোমরা সবকিছু ভাগ করে নিয়ে একসঙ্গে সামনে এগিয়ে যেতে পারো।」"
  },
  Event_50030_Name = {
    Text = "হারানো মগ্নচড়া"
  },
  Event_50031_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50031_Desc = {
    Text = "「তুমি হয়তো আর এগোতে পারবে না, কিন্তু তোমার আত্মা আর দেহ শক্ত বন্ধনে বাঁধা, একে অন্যের কাছ থেকে শক্তি টেনে নিচ্ছে।」\n「এটাই তোমার পছন্দ।」\nএই শব্দগুলি উচ্চারিত হতেই, মাথার উপর দাউদাউ করা সূর্য তার চোখ বন্ধ করে।"
  },
  Event_50031_Name = {
    Text = "হারানো মগ্নচড়া"
  },
  Event_50064_ChoiceDesc1 = {
    Text = "[Cut the Red Ribbon] একটি কমান্ড কার্ড ধ্বংস করো এবং Arg1টি কালো চিহ্ন প্রাপ্ত হও।"
  },
  Event_50064_ChoiceDesc2 = {
    Text = "[Resist] একটি কমান্ড কার্ড নকল করো, কিন্তু উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_50064_ChoiceDesc3 = {
    Text = "[Call Ramona] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_50064_Desc = {
    Text = "ক্যাসিয়া একটি লাল রেশমি ফিতা ছুড়ে দেয়, যা মুহূর্তেই তোমার ব্রিফকেসকে জড়িয়ে ধরে।"
  },
  Event_50064_Name = {
    Text = "জড়ানো রেশম"
  },
  Event_50065_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50065_Desc = {
    Text = "ছেদ-বিছেদ হওয়া পাইপগুলোর জালের ওপর দিয়ে ভেসে আসে মাঝেমধ্যে শোনা যায় এমন টকটকে টোকা দেওয়ার শব্দ, যেন কোনো ভূত একা নাচছে, এই মৃত নীরব স্থানে দুর্বলভাবে তার বাহু নাড়ছে।\nএই কল্পনা তোমার ভেতরে সুপ্ত প্রাচীন, গভীর ক্ষয়ের ভয়কে আহ্বান করে।"
  },
  Event_50065_Name = {
    Text = "ভুতুড়ে স্কেল"
  },
  Event_50066_ChoiceDesc1 = {
    Text = "[Explore the Cave Entrance] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_50066_ChoiceDesc2 = {
    Text = "[Deep into the Cave] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো"
  },
  Event_50066_Desc = {
    Text = "「এখানে একটা গুহা আছে।」\nথাইস তোমাকে আমন্ত্রণ জানায়।\n「চলো, ভেতরে যাব?」\nসঙ্কীর্ণ গুহাটা অন্ধকার আর গভীর, যেন কোনো দৈত্যাকার দানবের হা করা মুখ, যা অনন্ত অন্ধকারের দিকে প্রসারিত। যে-ই এই নির্জন স্থানে পা রাখে, তার মেরুদণ্ড বেয়ে উঠে আসে এক অদৃশ্য প্রতাপের অনুভূতি, যেখান থেকে পালানোর উপায় নেই। মনে হয়, প্রতিটি কোণে সূর্যালোক-বিমুখ প্রাচীন জীবেরা ওত পেতে আছে, অনুপ্রবেশকারীদের জন্য প্রতীক্ষায়।"
  },
  Event_50066_Name = {
    Text = "আঁধার গহ্বর"
  },
  Event_50067_ChoiceDesc1 = {
    Text = "[Strike One by One] একটি এলোমেলো রৌপ্য সৃষ্টি-কে সোনালি সৃষ্টি 「(RelicConfig.Arg1)」-এ উন্নয়ন অর্জন করো।"
  },
  Event_50067_ChoiceDesc2 = {
    Text = "[Surround the Two] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_50067_ChoiceDesc3 = {
    Text = "[Eavesdrop] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_50067_Desc = {
    Text = "দুজন আরামাইট প্রহরী কারখানার ফটকে পাহারা দিচ্ছে।\nতাদের একজন অলস ভঙ্গিতে এদিক-ওদিক ঘোরে, আরেকজনের সঙ্গে গল্প জুড়ে দেয়।\n「শোনা যাচ্ছে লেডি জুলিয়েট আবার ঝড়ের প্রাচীর ভেদ করার চেষ্টা করা দলগুলোর সংখ্যা গুনছেন।」\n「আশা করি আমাকে যেন না বেছে নেয়।」"
  },
  Event_50067_Name = {
    Text = "অলস দ্বাররক্ষী"
  },
  Event_50067_Tips1 = {
    Text = "রৌপ্য সৃষ্টি এখনও অর্জিত হয়নি"
  },
  Event_50068_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50068_Desc = {
    Text = "দেখো না, শোনো না, ভাবো না।\nসেই অযথা শব্দটা কোথা থেকে আসছে তা না ভেবেই, তুমি সোজা মাতৃবৃক্ষের অবশেষের দিকে এগিয়ে যাও।"
  },
  Event_50068_Name = {
    Text = "ভুতুড়ে স্কেল"
  },
  Event_50069_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50069_Desc = {
    Text = "রামোনা তার তলোয়ারটি ক্যাসিয়ার দিকে বিদ্ধ আঘাত করে, আর ক্যাসিয়া লাল রেশম নাড়াতে নাড়াতে তাড়াহুড়ো করে সরে যায়। তার ফলে তোমাকে জড়িয়ে থাকা রেশম মুহূর্তেই ঢিলে হয়ে পড়ে।"
  },
  Event_50069_Name = {
    Text = "জড়ানো রেশম"
  },
  Event_50070_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50070_Desc = {
    Text = "তোমরা দুই দলে ভাগ হয়ে যাও। তুমি আর র‍্যামোনা বামে যাও, রাইকার ডানে, দু’দিক থেকে ঘিরে ধরো।\nতোমার ইশারায় র‍্যামোনা আর রাইকার একসঙ্গে আঘাত হানে। দুই আরাম প্রহরী নীরবে লুটিয়ে পড়ে।"
  },
  Event_50070_Name = {
    Text = "অলস দ্বাররক্ষী"
  },
  Event_50071_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50071_Desc = {
    Text = "এখন ফাঁদগুলোর গভীরে নামার সময় নয়। শুধু গুহার দ্বারপ্রান্তে দাঁড়িয়েই তুমি প্রায় অনুভব করো, শিলার শিরায় কাঁপতে থাকা অশুভ স্পন্দন।"
  },
  Event_50071_Name = {
    Text = "আঁধার গহ্বর"
  },
  Event_50072_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50072_Desc = {
    Text = "তোমার ইশারায়, রাইকার নীরব আরাম প্রহরীটিকে একটি পাশা দিয়ে অজ্ঞান করে, তারপর চুপিসারে এগিয়ে যায় আরেকজনের দিকে, যে এখনো বকবক করে চলেছে।\n「এই ভাই, যদি সেই লেডি জুলিয়েট আসলে ভণ্ড হয়?」\n「আমিও তো জানি না।」\nরাইকারের হাসি কান পর্যন্ত লেগে যায়, আর সেই হাসিতেই প্রহরীর গায়ে কাঁটা দেয়। সে ঠিক চিৎকার করতে যাবে, এমন সময় রাইকার তার মুখ আর নাক চেপে ধরে।"
  },
  Event_50072_Name = {
    Text = "অলস দ্বাররক্ষী"
  },
  Event_50073_ChoiceDesc1 = {
    Text = "[মনোযোগ দিয়ে শোনো]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_50073_ChoiceDesc2 = {
    Text = "[Cover Ears] প্রতিটি জাগরণকারী, যার অ্যালিমাস 50 বা তার বেশি, তার জন্য 15টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_50073_ChoiceDesc3 = {
    Text = "[Check] 3টি প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_50073_Desc = {
    Text = "তুমি অবশিষ্ট দেহের তলায় প্রবেশ করতেই, ফাঁকা পরিত্যক্ত কারখানার ভেতর হঠাৎ এক সুরেলা ঘণ্টাধ্বনি প্রতিধ্বনিত হয়। পিয়ানোর স্বচ্ছ সুর মরিচাধরা ইস্পাত ধ্বংসাবশেষের সঙ্গে তীব্র বৈপরীত্য গড়ে তোলে।"
  },
  Event_50073_Name = {
    Text = "ভুতুড়ে স্কেল"
  },
  Event_50074_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50074_Desc = {
    Text = "「শোনো ভাই, যদি ওই জুলিয়েটটা মিথ্যুক হয়? তোমার কি মনে হয়, আমাদের কী করা উচিত?「\n「অর্থহীন কথা বলো না। জুলিয়েট আসার পর থেকে সবকিছুই তো শৃঙ্খলার সঙ্গে চলছে। সে যদি মিথ্যুক হতো, তবে আরাম গোষ্ঠীর জন্য এত কিছু করত কেন?「\nতাদের কথোপকথনের ফাঁকে, রাইকার নিঃশব্দে তার অতর্কিত আক্রমণ–স্থানে গিয়ে বসে, আর এক বিকট শব্দে দুইটি পাশা উড়ে গিয়ে দু」জনকেই মাটিতে ফেলে দেয়।"
  },
  Event_50074_Name = {
    Text = "অলস দ্বাররক্ষী"
  },
  Event_50075_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50075_Desc = {
    Text = "তুমি সাহস সঞ্চয় করে তাকিয়ে প্রতিদৃষ্টি দাও।\nপর্দার আড়ালের বিশাল চোখটি বিকৃত হাসিতে পেঁচিয়ে ওঠে, আর তোমার অবিচল ইচ্ছাশক্তি কেঁপে উঠে প্রাচীর পতনের মতো ভেঙে পড়ে।"
  },
  Event_50075_Name = {
    Text = "মায়াবী চোখ"
  },
  Event_50076_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50076_Desc = {
    Text = "তুমি অটল মনোযোগে পর্দা ছিঁড়ে ফেলো।\nতোমার হাতে বিশাল চোখটি পরিণত হয় সমতল, ছিন্নবিচ্ছিন্ন কাপড়ের টুকরোয়।"
  },
  Event_50076_Name = {
    Text = "মায়াবী চোখ"
  },
  Event_50077_ChoiceDesc1 = {
    Text = "[Stare Back] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_50077_ChoiceDesc2 = {
    Text = "[Tear Curtain] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_50077_Desc = {
    Text = "পর্দা সরে গেলে অসংখ্য বিকৃত চোখ উন্মোচিত হয়。\nওদের আড়ালে লুকিয়ে থাকা বিশাল সত্তা তীব্র ক্ষুধা ছড়িয়ে দেয়, ঝাঁপিয়ে পড়ার জন্য উদগ্রীব।"
  },
  Event_50077_Name = {
    Text = "মায়াবী চোখ"
  },
  Event_50078_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50078_Desc = {
    Text = "শেষ পর্যন্ত দেখা যায়, সেটা এক ফেলে দেওয়া, লম্বাটে যন্ত্রাংশ, তোমার নড়াচড়ায় বিরক্ত হয়ে দুলছে আর লোহার পাইপে ঠকঠক করে আঘাত করছে।"
  },
  Event_50078_Name = {
    Text = "ভুতুড়ে স্কেল"
  },
  Event_50079_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50079_Desc = {
    Text = "থাইস শান্তভাবে গুহার ভেতর পা বাড়ায়, আর তুমি সতর্ক পায়ে তার পিছু পিছু অন্ধকারে ঢুকে পড়ো।\n「সাবধানে!」 হঠাৎই কেউ তোমাকে টেনে পেছনে নিয়ে আসে, আর তুমি পড়ে যাও এক নরম আলিঙ্গনের ভেতর। তোমার সামনে, এক পিচকালো দানবীয় দেহ গুহা থেকে ঝড়ের বেগে ছুটে বেরিয়ে আসে।\n「এদিকে দেখো, 」 তুমি এখনো স্তব্ধ হয়ে থাকতেই থাইস বলে, অন্ধকারে তার চোখে মৃদু আলো জ্বলে ওঠে, 「ওটা হয়তো তার গোপন সম্পদ।」"
  },
  Event_50079_Name = {
    Text = "আঁধার গহ্বর"
  },
  Event_50080_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50080_Desc = {
    Text = "তুমি মরিয়া হয়ে স্যুটকেসের হাতল আঁকড়ে ধরো, লাল রেশমের টানের বিরুদ্ধে লড়াই করো।\nকিন্তু লাল রেশমের শক্তি প্রবল, তোমার হাত থেকে স্যুটকেস ছিটকে যায়, আর ভেতরের জিনিসপত্র চারদিকে বিক্ষিপ্ত হয়ে পড়ে।"
  },
  Event_50080_Name = {
    Text = "জড়ানো রেশম"
  },
  Event_50081_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50081_Desc = {
    Text = "তুমি বাঁধা পড়ার অনুভূতিকে ঘৃণা করো।\nতুমি লাল রেশমটা আঁকড়ে ধরে ছিঁড়ে ফেললে, ছিঁড়ে যাওয়ার কর্কশ শব্দে।\nঅবশিষ্ট টুকরোটি লাল সাপের মতো সরসরিয়ে সরে যায়।"
  },
  Event_50081_Name = {
    Text = "জড়ানো রেশম"
  },
  Event_50276_ChoiceDesc1 = {
    Text = "[Destroy Offering] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_50276_ChoiceDesc2 = {
    Text = "[দড়ি খুলে দাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_50276_ChoiceDesc3 = {
    Text = "[Keep Going] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_50276_Desc = {
    Text = "উঁচু মঞ্চে তিনজন আরাম গোষ্ঠীর মানুষকে বেঁধে রাখা হয়েছে।\nতারা মন্ত্রোচ্চারণ করতে করতে, নবজাতকের গায়ে দেখা সেই অন্ধকার, বাকলসদৃশ নকশাগুলোই তাদের শরীরে ফুটে উঠল।"
  },
  Event_50276_Name = {
    Text = "তিনটি নৈবেদ্য"
  },
  Event_50277_ChoiceDesc1 = {
    Text = "[Stare] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_50277_ChoiceDesc2 = {
    Text = "[Ignore] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_50277_Desc = {
    Text = "আরাম গোষ্ঠী বালুঝড়ের মধ্যে হাঁটু গেড়ে বসে।\nঝড় তাদের দেহে চাবুকের মতো আঘাত হানে, আর বালি তাদের দৃঢ় বিশ্বাসকে গ্রাস করে।\nঘূর্ণায়মান ধুলোর ভেতর, অসংখ্য বিশাল চোখ যেন বিকৃত ভূমির উপর নেমে তাকিয়ে থাকে।"
  },
  Event_50277_Name = {
    Text = "ধূলির দানব"
  },
  Event_50278_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50278_Desc = {
    Text = "যে দৃশ্যগুলো তুমি কখনোই স্মরণ করতে চাও না, সেগুলো আবার চোখের সামনে ভেসে ওঠে。\nকিলবিল করতে থাকা শুঁড়, কাঁচের খণ্ডাংশে কাটা ক্ষত থেকে ঝরে পড়া রক্ত...\nতোমার বমি পেতে থাকে।"
  },
  Event_50278_Name = {
    Text = "একাকী যাত্রা II"
  },
  Event_50279_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50279_Desc = {
    Text = "সে এখানে নেই; সে নেই সবচেয়ে বিপজ্জনক স্রোতের মাঝখানে।\nএই সত্যটুকুই তোমার মনকে শান্ত করার কথা।"
  },
  Event_50279_Name = {
    Text = "একাকী যাত্রা I"
  },
  Event_50280_ChoiceDesc1 = {
    Text = "[অতর্কিত আক্রমণ]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_50280_ChoiceDesc2 = {
    Text = "[Attack] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 এলোমেলো 3টি কমান্ড কার্ডে খোদাই করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_50280_Desc = {
    Text = "একটি নুবিয়া প্রচণ্ড বালুঝড়ে লড়াই করছে।\nতার চার খুর হলুদ বালুর গভীরে গেঁথে আছে, ঘূর্ণাবর্তে ভেসে যাওয়া এড়াতে প্রাণপণে চেষ্টা করছে।"
  },
  Event_50280_Name = {
    Text = "প্রকৃতির বালিঝড়"
  },
  Event_50281_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50281_Desc = {
    Text = "তুমি ঝাঁপিয়ে পড়ে, আরাম গোষ্ঠীর চিৎকারের মাঝেই দড়িগুলো কেটে দাও।\nএকজন আরাম যোদ্ধা এগিয়ে আসে; তুমি তার বর্শা ছিনিয়ে নিয়ে অন্ধকার ভিড়ের দিকে তাক করো।"
  },
  Event_50281_Name = {
    Text = "তিনটি নৈবেদ্য"
  },
  Event_50282_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50282_Desc = {
    Text = "বুদ্ধি বলে, সে আর ফিরবে না।\nহ্যাঁ, কে-ই বা আশা করে একজন জুয়াড়ি তার প্রতিশ্রুতি রাখবে?\nতোমার কাছে রয়ে যায় শুধু নিঃসঙ্গতা। তোমার আছে কেবল নিঃসঙ্গতাই।"
  },
  Event_50282_Name = {
    Text = "একাকী যাত্রা III"
  },
  Event_50283_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50283_Desc = {
    Text = "মাতৃবৃক্ষের পুনরুত্থানের সঙ্গে সঙ্গে কি অস্বাভাবিক জ্বর আরও তীব্র হবে?\nঝড়ের প্রাচীরের বাইরে একা থেকে কি রামোনা নিজের খেয়াল রাখতে পারবে?\nএখন মনোযোগ হারানোর সময় নয়, তবু সঙ্গীকে নিয়ে দুশ্চিন্তা থামাতে পারছো না।"
  },
  Event_50283_Name = {
    Text = "একাকী যাত্রা I"
  },
  Event_50284_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50284_Desc = {
    Text = "তুমি সিদ্ধান্ত নাও সরাসরি চ্যালেঞ্জের মুখোমুখি দাঁড়ানোর, আর সেই সময় নুবিয়া যেন বিরল এক ভর পেয়ে লাফিয়ে উঠে তোমার মাথায় গিয়ে ঝুলে বসে।\nতুমি আটকে পড়ো বালুঝড় আর নুবিয়ার দ্বৈত জটিলতায়।\n「অন্ধ সাহস একা কখনোই বিজয়ের পথ নয়, 」 উইলিয়াম সিনিয়রের ঠান্ডা কণ্ঠস্বর তোমার বন্ধ হয়ে আসা কানে ফেরেশতার সুসমাচারের মতো বাজে। 「সুযোগ কেড়ে নিতে শিখো।」"
  },
  Event_50284_Name = {
    Text = "প্রকৃতির বালিঝড়"
  },
  Event_50285_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50285_Desc = {
    Text = "এখন আরাম করে খবরের কাগজ পড়ার সময় নয়।"
  },
  Event_50285_Name = {
    Text = "তার উপদেশ"
  },
  Event_50286_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50286_Desc = {
    Text = "তুমি ভাবো না, তুমি স্মরণ করো না。\nতুমি ভাবতে চাও না, তুমি স্মরণ করতেও চাও না。\nমিথ্যাগের কিংবদন্তি একদিন শেষ হবে, কিন্তু তার যাত্রা থেমে থাকবে না。\nতোমাকে এগিয়ে যেতে হবে। তোমাকে এগিয়ে যেতে হবে।"
  },
  Event_50286_Name = {
    Text = "একাকী যাত্রা II"
  },
  Event_50287_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50287_Desc = {
    Text = "\n「প্রিয় রক্ষক, \nআশা করি এই চিঠি তোমার কাছে সুস্থতার বার্তা নিয়ে পৌঁছবে।\nনিজ দেহের প্রতি অবহেলার কারণে এই রেমুয়াহে যাত্রায় তোমার পাশে থাকতে না পারায় আমি দুঃখিত।\nকিন্তু সংকটময় মুহূর্তে, অনুগ্রহ করে তোমার একমাত্র সহায়তার ওপর ভরসা রেখো।\nযখনই তুমি আমাকে প্রয়োজন মনে করবে, আমি সবসময় তোমার সঙ্গেই আছি।」\nসময়ের অভাবে তুমি আর এগোতে পারলে না।\nকিন্তু পরিচিত হাতের লেখা তোমার ভেতরে এক শান্ত, স্থির প্রশান্তি এনে দিল।"
  },
  Event_50287_Name = {
    Text = "তার উপদেশ"
  },
  Event_50288_ChoiceDesc1 = {
    Text = "[He'll Be Back] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_50288_ChoiceDesc2 = {
    Text = "[He Won't Come] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_50288_Desc = {
    Text = "শেষ যে ব্যক্তি চলে গেল, সে ছিল রাইকার।\nকাসিয়াহকে থামাতে, সে তাঁবুতেই থেকে যাওয়ার সিদ্ধান্ত নিল।\nসে তোমাকে প্রতিশ্রুতি দিয়েছিল, সে আচার ভেঙে দেবে, প্রাচুর্যের মাতৃবৃক্ষ জ্বালিয়ে দেবে, আর তোমার পাশেই থাকবে।\nকিন্তু এখনো, সে তোমার কাছে আসেনি।\nফেলে রেখে গেছে তোমাকে, সম্পূর্ণ একা।"
  },
  Event_50288_Name = {
    Text = "একাকী যাত্রা III"
  },
  Event_50289_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50289_Desc = {
    Text = "গড়গড় শব্দ তুলে, তিন টার্নের বিভীষিকারা আচারস্থলের চারপাশে গড়িয়ে বেড়ায়।\nতুমি নিজেকেই নিজের থেকে বিচ্ছিন্ন মনে কর; আচার-অনুষ্ঠানের অসুস্থ উন্মাদনা তোমাকে গ্রাস করে এক অবর্ণনীয় মায়াস্বপ্নের ভেতর টেনে নেয়।"
  },
  Event_50289_Name = {
    Text = "তিনটি নৈবেদ্য"
  },
  Event_50290_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50290_Desc = {
    Text = "আরাম গোষ্ঠীর বিশ্বাস এতটাই ভক্তিপূর্ণ যে তারা স্বেচ্ছায় নিজেদেরকে বারবার বালুর নিচে সমাধিস্থ হতে দেয়।\nকিন্তু তুমি যখন মাথা তুলে তাকাও, ঝড়ের ভেতর কোনো সূর্য নেই।"
  },
  Event_50290_Name = {
    Text = "ধূলির দানব"
  },
  Event_50291_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50291_Desc = {
    Text = "বালু সমুদ্র যেন তাদের ভক্তিতে সাড়া দেয়।"
  },
