  Event_50292_ChoiceDesc1 = {
    Text = "[Break Free from Memories] একটি এলোমেলো কার্ডের প্রার্থনাগাথা গুণমান উন্নত করো।"
  },
  Event_50292_ChoiceDesc2 = {
    Text = "[স্মৃতি ধারণ]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，「(Skill.Arg2)」সংক্রমিত করুন"
  },
  Event_50292_Desc = {
    Text = "চলে যাওয়া দ্বিতীয় ব্যক্তি ছিলেন উইলিয়াম সিনিয়র।"
