  },
  Event_50293_ChoiceDesc1 = {
    Text = "[Calm] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_50293_ChoiceDesc2 = {
    Text = "[Worry] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_50293_Desc = {
    Text = "হঠাৎই তোমার মনে পড়ে যায় সেই দিনটির কথা, যেদিন তুমি এই যাত্রায় পা বাড়িয়েছিলে।\nরামোনা তোমাকে ব্যাগ গুছিয়ে নিতে মনে করিয়ে দিয়েছিল, উইলিয়াম সিনিয়র তোমার জন্য একটি ডায়েরি প্রস্তুত করেছিল, আর রাইকার গোপনে তোমার ব্যাগে এক বোতল হুইস্কি গুঁজে দিয়েছিল।\nএখন তারা কেউই আর নেই।\n\nপ্রথমে চলে গিয়েছিল রামোনা। তাওইলের শক্তি ঝড়ের প্রাচীরের কর্তৃত্বের সঙ্গে দ্বন্দ্বে জড়িয়ে পড়ে, আর পথের মাঝেই সে উচ্চ জ্বরে নুয়ে পড়ে।"
  },
  Event_50293_Name = {
    Text = "একাকী যাত্রা I"
  },
  Event_50294_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50294_Desc = {
    Text = "তুমি নুবিয়ার পায়ে আঘাত করো, ফলে সে ভারসাম্য হারায়। তার লতাগুল্মের মতো অঙ্গগুলো বাতাসে উন্মত্তভাবে ছটফট করে, তারপর ধুলিঝড়ে ভেসে যায়।"
  },
  Event_50294_Name = {
    Text = "প্রকৃতির বালিঝড়"
  },
  Event_50295_ChoiceDesc1 = {
    Text = "[Read] একটি কার্ড ধ্বংস করো"
  },
  Event_50295_ChoiceDesc2 = {
    Text = "[Put Away] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_50295_Desc = {
    Text = "টিক-ট্যাক।\nএই পরলোকীয়, উন্মত্ত বেদির নিচে, ভারী ঢাকের শব্দ বালুঝড়ের সঙ্গে গড়িয়ে আসে। অবিরাম জপের মাঝখানে, তুমি ক্ষীণ এক টাইপরাইটারের শব্দ শুনতে পাও— মিথাগের ডাকে, যা তোমার অস্থির হৃদয়কে শান্ত করে।"
  },
  Event_50295_Name = {
    Text = "তার উপদেশ"
  },
  Event_50296_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50296_Desc = {
    Text = "রাইকারের ভাগ্য অসাধারণ।\nসে যদি তোমাকে কিছু প্রতিশ্রুতি দেয়, তা সে অবশ্যই পূরণ করবে।\nনিশ্চয়ই।"
  },
  Event_50296_Name = {
    Text = "একাকী যাত্রা III"
  },
  Event_50297_ChoiceDesc1 = {Text = "[Leave]"},
  Event_50297_Desc = {
    Text = "তোমার জানার বিষয় নয়।\nএখন তোমার যা করা দরকার, তা হলো দ্রুত এগিয়ে গিয়ে প্রাচুর্যের মাতৃবৃক্ষের অবশেষ ধ্বংস করা।"
  },
  Event_50297_Name = {
    Text = "তিনটি নৈবেদ্য"
  },
  Event_52373_ChoiceDesc1 = {Text = "[Leave]"},
  Event_52373_Desc = {
    Text = "তুমি বেঁচে গেছ। তুমি অসংখ্য টিলা আর দগ্ধ দেহ দেখতে পাও।\nমনে হয় তুমিও কিছু একটা পুড়িয়ে ফেলেছ, কিন্তু তার আর কোনো অর্থ নেই।\nতুমি দিব্য রিয়েল্মের ঘণ্টাধ্বনি শুনতে পাও।"
  },
  Event_52373_Name = {
    Text = "মহামারীর আক্রমণ"
  },
  Event_52374_ChoiceDesc1 = {Text = "[Leave]"},
  Event_52374_Desc = {
    Text = "তুমি বেঁচে গেছ। তুমি অসংখ্য টিলা আর দগ্ধ দেহ দেখতে পাও।\nযা তুমি লালন করেছিলে তা রক্ষা করতে তুমি প্রাণপণ লড়েছ, চুকিয়েছ ভয়াবহ মূল্য। কিন্তু তার আর কোনো অর্থ নেই।\nতুমি দিব্য রিয়েল্মের ঘণ্টাধ্বনি শুনতে পাও।"
  },
  Event_52374_Name = {
    Text = "মহামারীর আক্রমণ"
  },
  Event_52375_ChoiceDesc1 = {Text = "[Leave]"},
  Event_52375_Desc = {
    Text = "দানবের উন্মত্ততা সাময়িকভাবে স্তিমিত হয়েছে। মেঘ সরে গেছে, নেমে এসেছে প্রশান্তি। সাগর, যেন এক অনন্ত জননী, কোমল জোয়ারে স্নেহভরে হাত বুলিয়ে দিচ্ছে লেমুরিয়ার পিঠে। লেমুরিয়ায় যা অবশিষ্ট, তা শুধু লাশ আর ধ্বংসস্তূপ।\nতুমি প্রাণপণ লড়েছিলে তোমার প্রিয় সবকিছু রক্ষার জন্য, চুকিয়েছ ভয়াবহ মূল্য। কিন্তু এখন আর তার কোনো অর্থ নেই।\nসাগরের বুকে তুমি ক্ষণিকের জন্য দেখেছিলে দিব্য রাজ্যের অস্পষ্ট রেখাচিত্র।"
  },
  Event_52375_Name = {
    Text = "সাগরের গর্জন"
  },
  Event_52376_ChoiceDesc1 = {
    Text = "[Offer Additional Sacrifices] একটি কমান্ড কার্ড ধ্বংস করো এবং 3 ধরনের প্রতিটি 「দেবরাজ্যের মায়া」 কার্ডের 1টি করে লাভ করো।"
  },
  Event_52376_Desc = {
    Text = "ভেঙে পড়া লেমুরিয়ার সিংহাসনের সামনে দাঁড়িয়ে তুমি তোমার শেষ শ্রদ্ধাঞ্জলি অর্পণ করো।\nঅন্তহীন অতল তোমার সামনে উন্মোচিত হয়। তুমি হাঁটু গেড়ে বসো, মুখে হাসি, চোখ বেয়ে অশ্রুধারা।\n\"দেখো, বাবা, ডেবোরাহ। দেখো, আমার পরম রাজা—দিব্য রিয়েল্ম আমার সামনে অবতীর্ণ হয়েছে!\""
  },
  Event_52376_Name = {
    Text = "স্বাগত জানাও, দিব্যরাজ্য"
  },
  Event_52377_ChoiceDesc2 = {
    Text = "[Protect What You Cherish] Arg1 HP হারাও, এবং একটি এলোমেলো উপসর্গ বিকশিত করো।"
  },
  Event_52377_Desc = {
    Text = "পৃথিবী। নীরব, অবিচল ইচ্ছাশক্তি‑সম পৃথিবী। সে মানবতার দীপ্তিকে বয়ে নিয়ে চলে, অনন্তকাল ধরে সহ্য করে। কিন্তু এখন সে কাঁপছে, অতল গহ্বরে ফেটে যাচ্ছে, তার বুকে ধারণ করা সবকিছুকে ঝাঁকিয়ে দিচ্ছে。\nতুমি তোমার সব আশা রেখেছিলে পৃথিবীর ওপর, কিন্তু যখন সে নিজেই কেঁপে ওঠে, তুমি কোথায় যাবে?\nউৎসর্গ, লেমুরিয়ার মানুষ তোমাকে ডাকে। তোমার যা কিছু আছে সব উৎসর্গ করো, যাতে নিঃশঙ্কভাবে ডিভাইন রিয়ালম উদ্ভাসিত হতে পারে।"
  },
  Event_52377_Name = {
    Text = "ভূকম্পন"
  },
  Event_52378_ChoiceDesc2 = {
    Text = "[Protect What You Cherish] Arg1 HP হারাও, এবং একটি এলোমেলো উপসর্গ বিকশিত করো।"
  },
  Event_52378_Desc = {
    Text = "সমুদ্র। সমুদ্রই লেমুরিয়ার জননী, তোমার জীবন, তোমার বিশ্বাস। এখন সেই সমুদ্রই কিংবদন্তির ক্রুদ্ধ দৈব দানবের মতো উঠে দাঁড়িয়েছে। সে গর্জন করছে, কোমল জলের শরীরকে কঠিন শিলা আর ধারালো কাঁটায় রূপান্তর করে, তার সামনে যা কিছু আছে সবকিছুর ওপর ভেঙে পড়ছে। সে শীতল দৃষ্টিতে পায়ের তলায় কাঁপতে থাকা লেমুরিয়ার দিকে তাকিয়ে আছে, পোকামাকড়ের মতো ছুটোছুটি করা লেমুরিয়ানদের দিকে তাকিয়ে আছে। সে লেমুরিয়াকে ধ্বংস করবে, লেমুরিয়ার কর্মের তোয়াক্কা না করেই。\nউৎসর্গ, চিৎকার করে লেমুরিয়ার বালকেরা। সবকিছু উৎসর্গ করো, যাতে ডিভাইন রিয়ালম শান্তিতে আগমন করতে পারে।"
  },
  Event_52378_Name = {
    Text = "সাগরের গর্জন"
  },
  Event_52379_ChoiceDesc2 = {
    Text = "[Protect What You Cherish] Arg1 HP হারাও, এবং একটি এলোমেলো উপসর্গ বিকশিত করো।"
  },
  Event_52379_Desc = {
    Text = "মহামারী। সর্বত্র তার বিস্তার। দেবতাদের স্থল ও সমুদ্রের ওপর ক্রোধ স্তিমিত হওয়ার পর, এই মহামারীই হয়ে ওঠে তাদের সবচেয়ে নির্লজ্জ ভৃত্য, তাদের পক্ষ থেকে বয়ে আনে অকথ্য মৃত্যু। মৃতদের দেহ মাটিচাপা দাও, মৃতদের দেহ দগ্ধ করো, আর যারা তোমাকে রক্ষা করতে গিয়ে প্রাণ দিয়েছে, তাদের জন্য প্রার্থনা করো—তাদের রাখো যত দূরে সম্ভব। মহামারীর সামনে জীবন আর মানবতার দীপ্তি প্রাচীর পতনের মতো ভেঙে পড়ে।\nউৎসর্গ, আর্তচিৎকার করে নাগরিকবৃন্দ লেমুরিয়ার। উৎসর্গ করো সবকিছু, যেন জন্ম নেয় এক মহামারীমুক্ত দিব্য রাজ্য।"
  },
  Event_52379_Name = {
    Text = "মহামারীর আক্রমণ"
  },
  Event_52380_ChoiceDesc1 = {Text = "[Leave]"},
  Event_52380_Desc = {
    Text = "প্রচণ্ড কম্পন থেমে গেছে। রাস্তাগুলো রক্তিম রক্তে রঞ্জিত, আর অসংখ্য মানুষ ধসে পড়া ঘরের নিচে চাপা পড়ে আছে。\nতুমি তোমার প্রিয় জিনিসগুলো রক্ষা করতে প্রাণপণ লড়েছ, দিয়েছ ভয়াবহ মূল্য। কিন্তু তার আর কোনো অর্থ নেই。\nএকমাত্র অর্থপূর্ণ বিষয় হলো, তুমি ডিভাইন রিয়ালমের আরও এক ধাপ কাছাকাছি চলে এসেছ।"
  },
  Event_52380_Name = {
    Text = "ভূকম্পন"
  },
  Event_52381_ChoiceDesc1 = {Text = "[Leave]"},
  Event_52381_Desc = {
    Text = "ভেঙে পড়া লেমুরিয়ার সিংহাসনের সামনে দাঁড়িয়ে তুমি শেষ প্রার্থনা পাঠ করো।\nঅন্তহীন অতল তোমার সামনে উন্মোচিত হয়। তুমি হাঁটু গেড়ে বসো, মুখে হাসি, চোখ বেয়ে অশ্রুধারা।\n\"দেখো, বাবা, ডেবোরাহ। দেখো, আমার পরম রাজা—দিব্য রিয়েল্ম, আমার সামনে অবতীর্ণ হয়েছে!\""
  },
  Event_52381_Name = {
    Text = "স্বাগত জানাও, দিব্যরাজ্য"
  },
  Event_52382_ChoiceDesc1 = {Text = "[Leave]"},
  Event_52382_Desc = {
    Text = "প্রচণ্ড কম্পন থেমে গেছে। রাস্তাগুলো রক্তিম রক্তে রঞ্জিত, আর অসংখ্য মানুষ ধসে পড়া ঘরের নিচে চাপা পড়ে আছে。\nধ্বংসস্তূপের নিচে যেন তোমারও কিছু চাপা পড়ে গেছে, কিন্তু তার আর কোনো অর্থ নেই。\nএকমাত্র অর্থপূর্ণ বিষয় হলো, তুমি ডিভাইন রিয়ালমের আরও এক ধাপ কাছাকাছি চলে এসেছ।"
  },
  Event_52382_Name = {
    Text = "ভূকম্পন"
  },
  Event_52383_ChoiceDesc1 = {Text = "[Leave]"},
  Event_52383_Desc = {
    Text = "দৈত্যের ক্রোধ আপাতত স্তিমিত হয়েছে। মেঘ সরে গেছে, নেমে এসেছে প্রশান্তি। সমুদ্র, যেন এক অনন্ত জননী, কোমল জোয়ারে লেমুরিয়ার পিঠে স্নেহের পরশ বুলিয়ে দিচ্ছে। লেমুরিয়ায় যা অবশিষ্ট, তা শুধু লাশ আর ধ্বংসস্তূপ。\nমনে হয় সমুদ্রে তোমারও কিছু হারিয়ে গেছে, কিন্তু তার আর কোনো অর্থ নেই。\nসমুদ্রের বুকে তুমি ডিভাইন রিয়ালমের অস্পষ্ট অবয়বের ঝলক দেখেছ।"
  },
  Event_52383_Name = {
    Text = "সাগরের গর্জন"
  },
  Event_52384_ChoiceDesc1 = {
    Text = "[Devout Prayer] তোমার ডেকে থাকা সব বেসিক উপসর্গ কার্ড ধ্বংস করো। সেই সংখ্যার সমান, তার সঙ্গে আরও 2টি এলোমেলো 「দেবরাজ্যের মায়া」 কার্ড লাভ করো।"
  },
  Event_52384_ChoiceDesc2 = {
    Text = "[Devout Prayer] তোমার ডেকে থাকা সব বেসিক উপসর্গ কার্ড ধ্বংস করো। সেই সংখ্যার সমান, তার সঙ্গে আরও 2টি এলোমেলো 「দেবরাজ্যের মায়া」 কার্ড লাভ করো।"
  },
  Event_52384_Desc = {
    Text = "পৃথিবী আর কাঁপে না, সাগর আর গর্জে ওঠে না, মহামারী আর আক্রমণ চালায় না। মহাবিপর্যয় লেমুরিয়াকে ধ্বংস করেছে, রেখে গেছে শুধু তোমাকে। চারদিকে তাকাও, সর্বত্র ধ্বংসস্তূপ। তাকাও তোমার শূন্য হাতের দিকে।\nকিন্তু তাতে কী আসে যায়, সম্মানিত প্রধান পুরোহিত? লেমুরিয়ার ধ্বংসস্তূপ আর লাশের ওপর পা রেখে, হামাগুড়ি দিয়ে হলেও এগিয়ে চল।\nতুমি এখন দিব্য রাজ্য থেকে মাত্র এক পা দূরে।"
  },
  Event_52384_Name = {
    Text = "স্বাগত জানাও, দিব্যরাজ্য"
  },
  Event_53140_ChoiceDesc1 = {Text = "[Leave]"},
  Event_53140_Desc = {
    Text = "তুমি স্কুল থেকে আসা যোগাযোগ অনুরোধটি গ্রহণ করেছ। পরিচিত কণ্ঠস্বর তোমার মনকে শান্ত করে। তুমি মনোবল সঞ্চয় করে সামনে এগিয়ে যাও।"
  },
  Event_53140_Name = {
    Text = "সংযোগস্থল"
  },
  Event_53141_ChoiceDesc1 = {
    Text = "[Connect] Arg2 HP পুনরুদ্ধার করো।"
  },
  Event_53141_ChoiceDesc2 = {
    Text = "[Meditate] একজন Awakener-কে Rouse করো।"
  },
  Event_53141_ChoiceDesc3 = {
    Text = "[Expel] সর্বোচ্চ 3টি উপসর্গ কার্ড ধ্বংস করো, এবং Arg2 সংখ্যক কালো চিহ্ন লাভ করো।"
  },
  Event_53141_ChoiceDesc4 = {
    Text = "[Fall into Madness] 2টি এলোমেলো জাগরণকারীকে উদ্দীপ্ত করো, তবে একটি এলোমেলো উপসর্গ বিকশিত করো।"
  },
  Event_53141_ChoiceDesc5 = {
    Text = "[Hesitation] অন্যান্য"
  },
  Event_53141_Desc = {
    Text = "কুয়াশা ভারী হয়ে ঝুলে থাকে, আর তোমার ব্যাজে মিটমিট করে ফ্যাকাশে সিলভার আভা। যোগাযোগকারীটা কড়কড় শব্দ তুলে জেগে ওঠে। কেউ একজন ডাকছে।"
  },
  Event_53141_Name = {
    Text = "সংযোগস্থল"
  },
  Event_53141_Tips3 = {
