  Event_53148_ChoiceDesc1 = {Text = "[Leave]"},
  Event_53148_Desc = {
    Text = "তুমি সংযোগ স্থাপন করো। এক কণ্ঠ, যা একই সঙ্গে উন্মাদকর ও মাদকতাময়, যন্ত্রের ভেতর দিয়ে ভেসে আসে।\n\"এটি মনে রেখো: এটি দিব্য রিয়েল্মের আশীর্বাদ।\""
  },
  Event_53148_Name = {
