  },
  Event_55782_ChoiceDesc1 = {
    Text = "[Cut Through Thorns] Arg1টি ইমেজারি 「(Skill.Arg2)」 রচনা করো। পরের যুদ্ধ-এ শত্রুদের HP 30% বৃদ্ধি পাবে এবং তারা 15% বেশি ক্ষতি করবে।"
  },
  Event_55782_ChoiceDesc2 = {
    Text = "[Cut Through Thorns] Arg1টি ইমেজারি 「(Skill.Arg2)」 রচনা করো। পরের যুদ্ধ-এ শত্রুদের HP 30% বৃদ্ধি পাবে এবং তারা 15% বেশি ক্ষতি করবে।"
  },
  Event_55782_ChoiceDesc3 = {
    Text = "[Part the Thorns] Arg1টি ইমেজারি 「(Skill.Arg2)」 রচনা করো, তবে 「(Skill.Arg3)」 উপসর্গটি বিকশিত করো।"
  },
  Event_55782_ChoiceDesc4 = {
    Text = "[Part the Thorns] Arg1টি ইমেজারি 「(Skill.Arg2)」 রচনা করো, তবে 「(Skill.Arg3)」 উপসর্গটি বিকশিত করো।"
  },
  Event_55782_ChoiceDesc5 = {
    Text = "[Leave the Thorns] 「হর্লার কলম ও কালি」 「Ink」-এর Arg1 স্তর অর্জন করে।"
  },
  Event_55782_Desc = {
    Text = "কিছু একটার স্পর্শে তোমার হৃদয়ের তার কেঁপে উঠল। তুমি থেমে বাগানের কোণের দিকে তাকিয়ে রইলে। কণ্টকের স্তর সংখ্যার নিচে এক টুকরো আলো মিটমিট করছে, মুক্তি পেতে প্রাণপণ লড়ছে।\nওটা কী? প্রজাপতি? পাখি? তুমি তার দিকে আরও কাছে এগিয়ে গেলে।"
  },
  Event_55782_Name = {
    Text = "মিউজের আশীর্বাদ"
  },
  Event_55782_Tips1 = {
    Text = "পরবর্তী যুদ্ধের শত্রুরা শক্তিবর্ধিত হয়েছে এবং এই বিকল্পটি আর বেছে নেওয়া যাবে না।"
  },
  Event_55783_ChoiceDesc1 = {
    Text = "[Create Offering] 3টি ইমেজারি কার্ড বেছে নাও এবং হর্লাকে তোমার জন্য একটি 「নিবেদিত কবিতা」 রচনা করতে দাও।"
  },
  Event_55783_ChoiceDesc2 = {Text = "[Leave]"},
  Event_55783_Desc = {
    Text = "তুমি একটি সুন্দর গ্রীনহাউসের সামনে এসে জানালা দিয়ে ভেতরে তাকালে, কিন্তু কিছুই দেখতে পেলে না।\nএক ঝাপটা হাওয়া বইল, ভেতরের পাপড়ি আর পাতাগুলো কাঁপিয়ে দিল। ফুল আর পাতার ভিড়ের মাঝে তুমি এক কিশোরীর অবয়ব দেখতে পেলে।\n\"আহ! বাগানে এক অতিথি!\" মেয়েটি বিস্ময় আর স্নায়ুচাপ নিয়ে তোমার দিকে তাকাল। \"দুঃখিত, কোলেট এখন নেই... আমি এসব ফুলের দাম জানি না...\"\nহঠাৎ মেয়েটি থেমে গেল, তোমার দিকে এগিয়ে এসে গভীরভাবে তোমাকে পর্যবেক্ষণ করল। \"আহ, প্রিয় অতিথি, আমি তোমার ভেতরে কাব্যিক ইমেজারি অনুভব করছি... হয়তো আমরা একসাথে একটি কবিতা রচনা করতে পারি?\""
  },
  Event_55783_Name = {
    Text = "বসন্তের উপহার"
  },
  Event_55783_Tips1 = {
    Text = "ইমেজারি অপর্যাপ্ত। অন্তত 3টি প্রয়োজন।"
  },
  Event_55799_ChoiceDesc1 = {Text = "[Leave]"},
  Event_55799_Desc = {
    Text = "জীবন্ত কণ্টকগুলো অস্থির বলে মনে হচ্ছে, কিন্তু এই মূল্য তুচ্ছ—ওই আলোর স্ফুলিঙ্গে তুমি মিউজের আহ্বান শুনতে পাও।"
  },
  Event_55799_Name = {
    Text = "মিউজের আশীর্বাদ"
  },
  Event_55819_ChoiceDesc1 = {
    Text = "[Follow the Body's Memory] যুদ্ধ এড়িয়ে গিয়ে তাৎক্ষণিক জয় লাভ করো, তবে Arg1 HP হারাও।"
  },
  Event_55819_ChoiceDesc2 = {
    Text = "[Leave] যুদ্ধে প্রবেশ করুন"
  },
  Event_55819_Desc = {
    Text = "পরিচিত শত্রুর মুখোমুখি হয়ে, তুমি আসন্ন যুদ্ধকে ইতোমধ্যেই ভালোভাবে চিনে ফেলেছ।"
  },
  Event_55819_Name = {
    Text = "পেশি স্মৃতি"
  },
  Event_55997_ChoiceDesc1 = {Text = "[Leave]"},
  Event_55997_Desc = {
    Text = "তুমি জড়ো করা ছবিগুলোর মধ্য থেকে কয়েকটি বেছে নিয়ে মেয়েটির হাতে তুলে দিলে।\n\"কী অপূর্ব ইমেজারি! মাননীয় অতিথি, অনুগ্রহ করে একটু অপেক্ষা করুন... এই নিন। এটি বসন্তের জন্য অনন্য এক নিবেদন, শুধুই আপনার জন্য!\"\nতোমার হাতে একটি কবিতা রূপ নিল, যেন কেবল তোমার জন্যই একটি ফুল ফুঁটে উঠল।\nতুমি মেয়েটিকে ধন্যবাদ জানাতে চেয়েছিলে, কিন্তু মুখ তুলে তাকাতেই দেখলে, তার অবয়ব অনেক আগেই মিলিয়ে গেছে। নির্জন গ্রীনহাউসে কেবল শুকিয়ে যাওয়া ফুল আর পাতা পড়ে আছে।\n—বসন্তের দহন শেষে যে ছাই অবশিষ্ট থাকে।"
  },
  Event_55997_Name = {
    Text = "বসন্তের উপহার"
  },
  Event_55999_ChoiceDesc1 = {Text = "[Leave]"},
  Event_55999_Desc = {
    Text = "ঘন কণ্টক তোমাকে দ্বিধাগ্রস্ত করে তোলে। তুমি আলোর বিন্দুটি ছেড়ে চলে যাও, তবু ক্ষণিকের সেই দৃষ্টি তোমার হৃদয় ভরে দেয় নতুন অনুপ্রেরণায়—ওই স্থানেই তুমি মিউজের আহ্বান শুনতে পাও।"
  },
  Event_55999_Name = {
    Text = "মিউজের আশীর্বাদ"
  },
  Event_56000_ChoiceDesc1 = {Text = "[Leave]"},
  Event_56000_Desc = {
    Text = "তুমি হাতে কণ্টক সরিয়ে দিলে, সামান্য আঘাত পেলে, তবু এই মূল্য নগণ্য—ওই আলোর বিন্দুতে তুমি মিউজের আহ্বান শুনতে পাও।"
  },
  Event_56000_Name = {
    Text = "মিউজের আশীর্বাদ"
  },
  Event_56024_ChoiceDesc1 = {Text = "[Leave]"},
  Event_56024_Desc = {
    Text = "এখনও যথেষ্ট নয়... তুমি আলোর দিকে এগিয়ে যেতে থাকো। কণ্টক উত্তেজিত হয়ে তাদের ধারালো অগ্রভাগ উন্মোচন করে। তবু সবই সার্থক।\nতোমার তালু থেকে আলো ছড়িয়ে পড়ে, আর জ্বলজ্বলে পর্দার মাঝখানে তুমি স্পষ্ট অনুভব করো Muzus-এর আশীর্বাদ।"
  },
  Event_56024_Name = {
    Text = "মিউজের আশীর্বাদ"
  },
  Event_56025_ChoiceDesc1 = {
    Text = "[Approach Light Points] একটি ইমেজারি কার্ডের উন্নয়ন অর্জন করো। পরের যুদ্ধ-এ শত্রুদের HP 30% বৃদ্ধি পাবে এবং তারা 15% বেশি ক্ষতি করবে।"
  },
  Event_56025_ChoiceDesc2 = {Text = "[Leave]"},
  Event_56025_Desc = {
    Text = "তুমি তোমার সরঞ্জাম দিয়ে কণ্টক কেটে পথ বানালে। জীবন্ত কণ্টকগুলো অস্থির হয়ে উঠল, কিন্তু এই মূল্য নগণ্য—ওই উজ্জ্বল বিন্দুতে তুমি মিউজের আহ্বান শুনলে।"
  },
  Event_56025_Name = {
    Text = "মিউজের আশীর্বাদ"
  },
  Event_56146_ChoiceDesc1 = {Text = "[Leave]"},
  Event_56146_Desc = {
    Text = "এখনও যথেষ্ট নয়... তুমি আলোর আরও কাছে সরে যাও। ধারালো কণ্টক তোমার হাত ভেদ করে, রক্ত অবিরাম ঝরতে থাকে। তবু সবই সার্থক।\nতোমার তালু থেকে আলো ছড়িয়ে পড়ে, আর জ্বলজ্বলে পর্দার মাঝখানে তুমি স্পষ্ট অনুভব করো Muzus-এর আশীর্বাদ।"
  },
  Event_56146_Name = {
    Text = "মিউজের আশীর্বাদ"
  },
  Event_56147_ChoiceDesc1 = {
    Text = "[Creative Impulse] সব জাগরণকারী তাদের সমস্ত অ্যালিমাস হারায়। 3টি ইমেজারি কার্ড বেছে নাও এবং হর্লাকে তোমার জন্য একটি 「নিবেদিত কবিতা」 রচনা করতে দাও।"
  },
  Event_56147_ChoiceDesc2 = {Text = "[Leave]"},
  Event_56147_Desc = {
    Text = "তুমি স্কুল থেকে আসা যোগাযোগ অনুরোধটি গ্রহণ করেছ। পরিচিত কণ্ঠস্বর তোমার মনকে শান্ত করে। তুমি মনোবল সঞ্চয় করে সামনে এগিয়ে যাও।"
  },
  Event_56147_Name = {
    Text = "সংযোগস্থল"
  },
  Event_56147_Tips1 = {
    Text = "ইমেজারি অপর্যাপ্ত। অন্তত 3টি প্রয়োজন।"
  },
  Event_56148_ChoiceDesc1 = {Text = "[Leave]"},
  Event_56148_Desc = {
    Text = "প্রতীকের ওপর সিলভার আলো তোমার অনুভূতিকে আলোড়িত করে। হৃদয়ের নির্দেশনা মেনে, তুমি যা আছে সব কাঁটার ঝোপে নিক্ষেপ করো। নিচের আলো জ্বলে উঠতে শুরু করে— সেই আলোয় তুমি নতুন অনুপ্রেরণা লাভ করো।"
