  },
  Event_56149_ChoiceDesc2 = {Text = "[Leave]"},
  Event_56149_Desc = {
    Text = "তুমি হাতে কণ্টক সরিয়ে দিলে, সামান্য আঘাত পেলে, তবু এই মূল্য নগণ্য—ওই আলোর বিন্দুতে তুমি মিউজের আহ্বান শুনতে পাও।"
