  Event_57738_ChoiceDesc1 = {
    Text = "[Forceful Entry] সব জাগরণকারীর অ্যালিমাস 30 বাড়াও, কিন্তু ডেকে দুইটি 「(Skill.Arg1)」 কার্ড যোগ করো।"
  },
  Event_57738_ChoiceDesc2 = {
    Text = "[Disarm] পরের যুদ্ধে শত্রুদের HP 60% বেশি হবে এবং তারা 30% বেশি DMG দেবে।"
  },
  Event_57738_ChoiceDesc3 = {
    Text = "[Ambush] সব জাগরণকারী তাদের সব অ্যালিমাস হারাবে; 30টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_57738_Desc = {
    Text = "তুমি কোণের অদৃশ্য ফাঁক থেকে উঁকি দাও। কমিটি এজেন্টরা অন্য দিকে তাকিয়ে আছে, তোমার উপস্থিতি সম্পর্কে সম্পূর্ণ অজ্ঞ।\nঅতীতের প্রশিক্ষণের স্মৃতিচারণ তোমার মনে ঝলসে ওঠে, আর তুমি দ্রুতই বের করে ফেলো, কীভাবে তোমার পথ রুদ্ধ করে থাকা শত্রুদের সামলাবে।"
  },
  Event_57738_Name = {
    Text = "কমিটির এজেন্ট"
  },
  Event_57738_Tips3 = {
    Text = "কোনো জাগরণকারী অ্যালিমাস বহন করছে না।"
  },
  Event_57739_ChoiceDesc1 = {Text = "[Leave]"},
  Event_57739_Desc = {
    Text = "তুমি মনোযোগ দিয়ে পর্যবেক্ষণ করলে। কমিটির এজেন্টরা তোমার পথ রুদ্ধ করে দাঁড়িয়ে, নিষ্ঠার সঙ্গে এলাকা পর্যবেক্ষণ করছে।\nঅসংখ্য শত্রুর মুখোমুখি হয়ে, তুমি তাদের সঙ্গে লড়তে পারলে না।\nঅগ্রসর হবে, না পিছু হটবে?"
  },
  Event_57739_Name = {
    Text = "আটক বিন্দু"
  },
  Event_57776_ChoiceDesc1 = {Text = "[Leave]"},
  Event_57776_ChoiceDesc2 = {
    Text = "[Feign Surrender] এই এলাকা অনুসন্ধানের পর, আটক বিন্দুতে স্থানান্তরিত হও এবং দুইটি এলোমেলো উপসর্গ বিকাশ করো।"
  },
  Event_57776_ChoiceDesc3 = {
    Text = "[Intrude] এই এলাকা অনুসন্ধানের পর, আটক বিন্দুতে স্থানান্তরিত হও এবং Arg1 HP হারাও।"
  },
  Event_57776_Desc = {
    Text = "তুমি মনোযোগ দিয়ে পর্যবেক্ষণ করলে। কমিটির এজেন্টরা তোমার পথ রুদ্ধ করে দাঁড়িয়ে, নিষ্ঠার সঙ্গে এলাকা পর্যবেক্ষণ করছে।\nঅসংখ্য শত্রুর মুখোমুখি হয়ে, তুমি তাদের সঙ্গে লড়তে পারলে না।\nঅগ্রসর হবে, না পিছু হটবে?"
  },
  Event_57776_Name = {
    Text = "পর্যবেক্ষণ বিন্দু"
  },
  Event_57776_Tips3 = {
    Text = "তোমার যথেষ্ট এইচপি নেই।"
  },
  Event_59193_ChoiceDesc1 = {
    Text = "[Alistair's Blessing] আপনার ডেকে 1টি 「মেরু গোধূলি আলো」 যোগ করুন।"
  },
  Event_59193_Desc = {
    Text = "তোমার স্যুটকেসের একেবারে তলায় পড়ে ছিল সেই প্রবেশ সনদটি। তুমি আলতো করে ছুঁয়ে দিলে তার সূক্ষ্ম ফ্রেমটিকে, যার কিনারায় যেন তারার ম্লান আলো জড়িয়ে আছে, আর কাগজের গায়ে লেগে থাকা কালি‑গন্ধ গভীরভাবে টেনে নিলে ফুসফুসে। মিথাগ প্রতীকটি ভবিষ্যতের দীপ্তিময় দ্বারপথের মতো ঝলমল করছিল, মুগ্ধ করে রাখছিল তোমার উদগ্রীব চোখকে—যেমন করেছিল সেদিন, যেমন করছে আজও।"
  },
  Event_59193_Name = {
    Text = "ভর্তি উৎসব"
  },
  Event_59527_ChoiceDesc1 = {
    Text = "「লেক্স নউস」 প্রার্থনাগাথা উপলব্ধি করতে একটি কার্ড বেছে নাও। 「লেক্স নউস」: খেলবার পর, 2টি কার্ড ড্র করো; তাদের অ্যারিথমেটিকা ব্যয় প্রার্থনাগাথা কার্ডগুলোর প্রকৃত অ্যারিথমেটিকা ব্যয় হ্রাস করে, এবং এই প্রভাব প্রতি যুদ্ধের জন্য কেবল একবারই কার্যকর হয়।"
  },
  Event_59527_Desc = {
    Text = "জ্ঞানের প্রতীক চিহ্ন আপনার নথিপত্রে খোদিত হলো।\nতাওয়ির চিন্তাধারা আপনার মনে প্রবাহিত হলো। সেই অসীম সম্ভাবনার মধ্যে, আপনি একমাত্র সঠিক পথে এগিয়ে চলেছেন।"
  },
  Event_59527_Name = {
    Text = "ভর্তি উৎসব"
  },
  Event_59528_ChoiceDesc1 = {
    Text = "「লেক্স ভোলিস」 প্রার্থনাগাথা উপলব্ধি করতে একটি কার্ড বেছে নাও। 「লেক্স ভোলিস」: খেলবার পর, এই জাগরণকারী ছাড়া বাকি সব কার্ড ফেলে দাও, এবং 5টি এলোমেলো অ-জাগরণকারী কার্ড অর্জন করো। এই প্রভাব প্রতি যুদ্ধের জন্য কেবল একবারই সক্রিয় থাকে।"
  },
  Event_59528_Desc = {
    Text = "আনন্দের প্রতীক চিহ্ন আপনার নথিপত্রে খোদিত হলো।\nসিলমোহরের মধ্য দিয়ে, N আপনাকে পর্যবেক্ষণ করছেন। তিনি প্রত্যাশা করছেন, আপনি তাঁর জন্য এমন এক পরিণতি নিয়ে আসবেন যা কখনো মিথ্যা প্রতিশ্রুতি ছিল না।"
  },
  Event_59528_Name = {
    Text = "ভর্তি উৎসব"
  },
  Event_59529_ChoiceDesc1 = {
    Text = "「লেক্স জেনিস」 প্রার্থনাগাথা উপলব্ধি করতে একটি কার্ড নির্বাচন করো। 「লেক্স জেনিস」: খেললে, অতিরিক্ত 3টি বেস কপি পাও, যেগুলোর মধ্যে 「ধরে রাখো」 ও 「ক্ষয়」 থাকবে; এই প্রভাব প্রতি যুদ্ধের জন্য কেবল একবারই কার্যকর।"
  },
  Event_59529_Desc = {
    Text = "প্রজননের প্রতীক চিহ্ন আপনার নথিপত্রে খোদিত হলো।\nতাইইসি তাঁর আশা আপনার উপর ন্যস্ত করেছেন, তিনি সকল জগতে আপনার সাথে সহাবস্থান করবেন।"
  },
  Event_59529_Name = {
