  Event_59566_ChoiceDesc1 = {
    Text = "[রক্তাশ্রু মোছা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_59566_ChoiceDesc2 = {
    Text = "[Eyes Open] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 এলোমেলো 3টি কমান্ড কার্ডে খোদাই করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_59566_Desc = {
    Text = "অগণিত আকাঙ্ক্ষা একত্রে মিশে যায়। একসময় তোমাদের উৎস ছিল এক, আর এখন তোমাদের দেহও এক।\nঅগণিত চোখ একসঙ্গে খুলে যায়, মুখোমুখি হয় মহান চোখের।\nঅগণিত চোখ একসঙ্গে ভেঙে চুরমার হয়, ঝরে পড়ে শুকনো রক্তের অশ্রু।"
  },
  Event_59566_Name = {
    Text = "স্ব-সত্তার সংমিশ্রণ"
  },
  Event_59567_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59567_Desc = {
    Text = "আপনি সেই উন্মাদ কণ্ঠস্বরের সাথে তর্ক করার চেষ্টা করলেন, সেই শূন্যতার দর্শনকে খণ্ডন করলেন।\n\"সবকিছুই একদিন মৃত্যুর দিকে ধাবিত হয়, তাহলে কি জীবন নিজেই সম্পূর্ণ অর্থহীন?\"\nআপনি যুক্তি দিয়ে লড়লেন, কিন্তু সেই হাসি একটুও কমল না, যেন আপনার মূর্খতাকে উপহাস করছে।"
  },
  Event_59567_Name = {
    Text = "জবাইয়ের মেষশাবক"
  },
  Event_59568_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59568_Desc = {
    Text = "তুমি সেই দরজার দিকে তাকিয়ে আছ, অজ্ঞতার যন্ত্রণা আর সহ্য করতে চাও না।\nতুমি দরজার ওপারের দৃশ্য দেখতে চাও।\nভ্রান্তিময় দরজাটি মায়াবীভাবে দুলতে থাকে, তুমি অসংখ্য জগতের ছায়া ক্ষণিকের জন্য ভেসে উঠতে দেখো।\nস্পষ্ট করে দেখার আগেই, অসীম তথ্যের স্রোত তোমার মনকে ভাসিয়ে নিয়ে যায়, তোমার মস্তিষ্ক বিশৃঙ্খল গোলমালে ভরে ওঠে।"
  },
  Event_59568_Name = {
    Text = "বহু দ্বারের ওপারে"
  },
  Event_59569_ChoiceDesc1 = {
    Text = "[Firm Command] একটি এলোমেলো জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_59569_ChoiceDesc2 = {
    Text = "[Joint Discussion] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে যেকোনো একটিতে খোদাই করো।"
  },
  Event_59569_Desc = {
    Text = "সবকিছুই ঘটল এত হঠাৎ। কুয়াশা তোমাকে গ্রাস করে, আর চারপাশ দেখার চেষ্টা করেও তুমি কিছুই স্পষ্ট দেখতে পাও না।\nজাগ্রতেরা তোমার আদেশের অপেক্ষায়।\nএখন, বিচ্ছিন্ন তুমি, কেবল নিজের শক্তির ওপরই নির্ভর করতে বাধ্য।"
  },
  Event_59569_Name = {
    Text = "অজ্ঞানের দৃষ্টি"
  },
  Event_59570_ChoiceDesc1 = {
    Text = "[With Sacrifice] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_59570_ChoiceDesc2 = {
    Text = "[সাহসিকতার সাথে]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_59570_ChoiceDesc3 = {
    Text = "[With Direct Stare] 50টি কালো চিহ্ন গ্রহণ করুন"
  },
  Event_59570_Desc = {
    Text = "অগণিত জগতে অগণিত সংস্করণের তুমি দাঁড়িয়ে আছ, কাঁধে কাঁধ মিলিয়ে, হাতে হাত রেখে, আপন ভাইবোনের মতো।\nএখন তোমরা সবাই দাঁড়িয়ে আছ মহান ছায়ার নীচে, মাথা উঁচু, এক পা-ও পিছু না হটে।\nকি করা যায়?\nকীভাবে তুমি পরাজিত করবে নিজের সেই চূড়ান্ত সংস্করণটিকে?"
  },
  Event_59570_Name = {
    Text = "আত্ম-উত্তর"
  },
  Event_59571_ChoiceDesc1 = {
    Text = "[Seek Answers] Arg1টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_59571_ChoiceDesc2 = {
    Text = "[Give Up] 25টি কালো চিহ্ন গ্রহণ করে চলে যাও।"
  },
  Event_59571_Desc = {
    Text = "দ্বারের মায়াময় প্রতিচ্ছবি পার হওয়ার সাথে সাথে, তোমার অগণিত অভিজ্ঞতার স্মৃতি তোমার মনে ভেসে ওঠে।\nতাদের কেউ মৃত্যুবরণ করেছে, কেউ উন্মাদ হয়েছে, কেউ অটল থেকেছে, কেউ পতিত হয়েছে।\nঅসংখ্য পথ, অসংখ্য পছন্দ তোমার চোখের সামনে ভেসে ওঠে, যেন এক মুহূর্তে তুমি এক অন্তহীন দীর্ঘ জীবন যাপন করেছ।\nএখন অসংখ্য মস্তিষ্ক, অসংখ্য মুখ একসাথে সক্রিয়।\nতুমি কাল ও স্থানের সীমা অতিক্রম করে অসংখ্য নিজের সাথে কথা বলার চেষ্টা কর, অন্তহীন স্মৃতির গভীর থেকে উত্তর খুঁজে বের করতে।"
  },
  Event_59571_Name = {
    Text = "স্ব-প্রশ্ন"
  },
  Event_59572_ChoiceDesc1 = {
    Text = "[Exchange Power] একটি এলোমেলো কমান্ড কার্ডে 「(EnchantConfig.Arg1)」 প্রার্থনাগাথা খোদাই করো।"
  },
  Event_59572_ChoiceDesc2 = {
    Text = "[Exchange Fortune] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত হবে।"
  },
  Event_59572_Desc = {
    Text = "প্রতিটি নির্বাচনই এক মূল্য দাবি করে।\nজীবন, আত্মা, অনুভূতি, স্মৃতি...\nতুমি ভাগ্যের সঙ্গে কী বিনিময় করতে চাও, আর দাঁড়িপাল্লায় কী তুলে ধরবে?"
  },
  Event_59572_Name = {
    Text = "ভাগ্যের বাছাই"
  },
  Event_59573_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59573_Desc = {
    Text = "হৃদয় ছাড়া কেউ কীভাবে বাঁচে?\nতুমি উন্মত্তের মতো চারদিকে খুঁজতে থাকো, প্রতিটি মুহূর্তে শ্বাস আরও দ্রুত হয়ে ওঠে, মৃত্যুভয়ের কুয়াশা তোমার মন ঢেকে ফেলে।\n“শ্বাস নিতে পারছি না... আমার হৃদয় থেমে যাচ্ছে...”\nহঠাৎ তুমি বুঝতে পারো, তোমার আর হৃদস্পন্দনের প্রয়োজন নেই।\nঅবশেষে তুমি উপলব্ধি করো—আর আনন্দে হেসে ওঠো।"
  },
  Event_59573_Name = {
    Text = "ফাঁপা বক্ষ"
  },
  Event_59574_ChoiceDesc1 = {
    Text = "[Peer] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_59574_ChoiceDesc2 = {
    Text = "[Evade] 2 জন এলোমেলো জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)「 দু」বার বিকশিত করো।"
  },
  Event_59574_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_59574_Desc = {
    Text = "তুমি শুন্যতার ভেতর এক উপস্থিতি অনুভব করো, যে তোমাকে দেখছে।\nতুমি যেদিকেই যাও, সেই দৃষ্টি ছায়ার মতো তোমার পিছু নেয়।\nনিজেকে মনে হয় ক্ষুদ্র এক শিকার, যার ওপর নিশানা ধরা হয়েছে; আর তোমার পিঠে সূচ ফোটার মতো ব্যথা শুরু হয়।"
  },
  Event_59574_Name = {
    Text = "তার দৃষ্টি"
  },
  Event_59575_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59575_Desc = {
    Text = "অগোছালো পরিবেশনা তোমাকে বিচলিত করতে পারে না, তুমি অবিচল ইচ্ছাশক্তি দিয়ে নিজের তাল ঠিক রাখো।\nপ্রতিপক্ষের আক্রমণ আর প্রলোভন ব্যর্থ হয়। পিয়ানোয় একসঙ্গে দুইটি সুর বাজে, আর যে শেষ পর্যন্ত টিকে থাকবে, সে-ই সব নোটের ওপর কর্তৃত্ব পাবে।"
  },
  Event_59575_Name = {
    Text = "প্রলয়ের উন্মত্ত সুর"
  },
  Event_59576_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59576_Desc = {
    Text = "সমস্ত সাহস সঞ্চয় করে, যা-ই আসুক না কেন, তুমি তোমার সঙ্গীদের পাশে নিয়ে সামনে এগিয়ে যেতে থাকবে।"
  },
  Event_59576_Name = {
    Text = "হিমায়িত ভবিষ্যৎ"
  },
  Event_59577_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59577_Desc = {
    Text = "\"তুমি এখন কোথায়?\"\n\"শিক্ষকরা কী করার পরিকল্পনা করছেন?\"\n\"আমার এরপর কী করা উচিত?\"\nতুমি উদ্বিগ্নভাবে প্রশ্নের পর প্রশ্ন করে যাচ্ছিলে, যেমনটা সবসময় করতে — সেই নির্ভরযোগ্য অস্তিত্বের উপর ভরসা করতে চাইছিলে।\nযোগাযোগ যন্ত্রটি যেন হ্যাং হয়ে গেল, কোনো সাড়া নেই। তুমি যন্ত্রটি ঝাঁকালে, আর ঝাঁকানির মধ্যে উত্তরপত্রের অক্ষরগুলো বিকৃত হয়ে একঝাঁক প্রজাপতিতে রূপ নিল, ঝাপটা মেরে তোমার মুখে এসে পড়ল।\nতুমি চোখ কচলালে, আর দেখলে সবটাই ছিল তোমার বিভ্রম।\nউত্তরপত্রের কাগজটি সম্পূর্ণ ফাঁকা।"
  },
  Event_59577_Name = {
    Text = "বিভ্রমের প্রতিধ্বনি"
  },
  Event_59578_ChoiceDesc1 = {
    Text = "[Panic Search] সর্বোচ্চ HP Arg1 বৃদ্ধি পায়"
  },
  Event_59578_ChoiceDesc2 = {
    Text = "[পূরণের চেষ্টা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_59578_Desc = {
    Text = "তোমার বুকে এক শূন্যতা ও হালকাতা অনুভব করো। নিচের দিকে তাকিয়ে দেখো, তা যেন এক চাবির ছিদ্রের মতো খুলে গেছে।\nতোমার হৃদয় অনুপস্থিত।"
  },
  Event_59578_Name = {
    Text = "ফাঁপা বক্ষ"
  },
  Event_59579_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59579_Desc = {
    Text = "তুমি উচ্চস্বরে তার অভিপ্রায়কে জিজ্ঞাসা করো, কিন্তু বদলায় না তার হাসি।\n\nসে বহু আগেই এই বিশ্বকে ত্যাগ করেছে। বিচ্ছিন্ন এক সত্তা কোনো দায়িত্ব বহন করে না।\nতোমার মৃত্যু প্রতিরোধ অর্থহীন।"
  },
  Event_59579_Name = {
    Text = "পাগল ভদ্রলোক"
  },
  Event_59580_ChoiceDesc1 = {
    Text = "[Disrupt Rhythm] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_59580_ChoiceDesc2 = {
    Text = "[Self-Preservation] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_59580_Desc = {
    Text = "তুমি বাজাতে থাকো যেন এক উন্মাদ নারীর সঙ্গী হয়ে; সে তোমাকে চাবির সঙ্গে বেঁধে ফেলে, টেনে নিয়ে যায় তার উন্মত্ত সুরের ভেতরে।\nতুমি তার তালের সঙ্গে তাল মেলাতে লড়াই করো, হোঁচট খেতে খেতে এগিয়ে চল।\nতুমি প্রাণপণে চেষ্টা করো সুরের নিয়ন্ত্রণ নিজের হাতে নিতে।"
  },
  Event_59580_Name = {
    Text = "প্রলয়ের উন্মত্ত সুর"
  },
  Event_59581_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59581_Desc = {
    Text = "তুমি এমন এক অতুলনীয় শক্তি কামনা করো, যা সব শৃঙ্খল আর প্রতিবন্ধক চূর্ণ করে দেবে।\nকিন্তু মানবশক্তির সীমা আছে। নশ্বর দেহ নিয়ে দেবতাদের চ্যালেঞ্জ করলে, শেষ পর্যন্ত তোমার জীবন দেশলাই কাঠির মতো পুড়ে নিঃশেষ হয়ে যাবে।"
  },
  Event_59581_Name = {
    Text = "ভাগ্যের বাছাই"
  },
  Event_59582_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59582_Desc = {
    Text = "\"নেই আর……নেই আর……\"\nশূন্যতার অনুভূতি সহ্য করা কঠিন, তুমি পকেট ঘড়ি, আপেল আর স্কুল ইউনিফর্মের জ্যাকেটটা তুলে নিলে, বুকের ভেতরের শূন্যতা পূরণ করার চেষ্টায়।\nতোমার বুকের খাঁচা আবার পরিপূর্ণ হয়ে উঠল, তবে তোমার মনে হচ্ছে যেন একটু বেশিই ভরে গেছে।\nকিছু যায় আসে না, সবকিছু তো আর নিখুঁত হয় না।"
  },
  Event_59582_Name = {
    Text = "ফাঁপা বক্ষ"
  },
  Event_59583_ChoiceDesc1 = {
    Text = "[Persuade] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_59583_ChoiceDesc2 = {
    Text = "[Question] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_59583_Desc = {
    Text = "N-এর চামড়ার জুতো তোমার সামনে থামল, তুমি সেই কালো মুখে অতিরঞ্জিত হাসি দেখতে পেলে।\nসে সবসময় পরিপাটি পোশাক পরে, কিন্তু তুমি জানো সেই ভদ্রলোকের বাইরের আবরণের নিচে শুধু সবচেয়ে বিশুদ্ধ উন্মাদনা।\nতার কোনো বন্ধু নেই, শত্রুও বিরল।\nকারণ সেই মানুষগুলো সবচেয়ে নাটকীয় উপায়ে সম্পূর্ণরূপে অদৃশ্য হয়ে যায়।\n\nদুর্ভাগ্যবশত, এখন তুমি তার নাটকের পরবর্তী প্রধান চরিত্র হিসেবে বেছে নেওয়া হয়েছ।\nতোমার উদ্বোধনী বক্তব্য প্রস্তুত করো, এই সবচেয়ে까다রোজ দর্শককে কীভাবে সন্তুষ্ট করবে?"
  },
  Event_59583_Name = {
    Text = "পাগল ভদ্রলোক"
  },
  Event_59584_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59584_Desc = {
    Text = "জাগ্রতরা তোমার চেয়ে বেশি কিছু জানে না, তবে তারা ইতিমধ্যেই তোমার সবচেয়ে বিশ্বস্ত সঙ্গী, যুদ্ধসাথী ও অবলম্বন।\nতুমি জাগ্রতদের সাথে পরিকল্পনা নিয়ে আলোচনা করো। যদিও তোমাদের হৃদয়ে এখনও দ্বিধা রয়েছে, তবুও তোমরা নতুন করে শুরু করার সাহস অর্জন করেছো।"
  },
  Event_59584_Name = {
    Text = "অজ্ঞানের দৃষ্টি"
  },
  Event_59585_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59585_Desc = {
    Text = "যেন নিজেকে দৃঢ়প্রতিজ্ঞ করছ, তুমি দৃঢ়ভাবে উচ্চস্বরে উত্তর দিলে।\nতোমার কণ্ঠস্বর অসংখ্য বুদবুদের মাঝে প্রতিধ্বনিত হলো, যেন অসংখ্য তুমি একসাথে শপথ নিচ্ছ।\nতুমি সবকিছুর মুখোমুখি হতে প্রস্তুত।"
  },
  Event_59585_Name = {
    Text = "তাঁর জিজ্ঞাসা"
  },
  Event_59586_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59586_Desc = {
    Text = "তুমি স্থির দাঁড়িয়ে থাকো, জবাবের কাগজের শব্দগুলোর দিকে একদৃষ্টে তাকিয়ে।\nতোমার দৃষ্টির নিচে শব্দগুলো ধীরে ধীরে ঝাপসা হয়ে বেঁকে যায়, আর প্রজাপতিতে রূপান্তরিত হয়ে তোমার মুখের দিকে উড়ে আসে।\nতুমি হাত নেড়ে তাদের তাড়াতে গিয়ে দেখো, জবাবের কাগজটি এখন সম্পূর্ণ ফাঁকা।\nঅবশ্যই, অতিরিক্ত সুন্দর স্বপ্নগুলো সবসময়ই মিথ্যা।"
  },
  Event_59586_Name = {
    Text = "বিভ্রমের প্রতিধ্বনি"
  },
  Event_59587_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59587_Desc = {
    Text = "আপনি এই ঘৃণ্য সুতোদের ঘৃণা করেন।\nআপনি সর্বশক্তি দিয়ে টানেন; কিছু ছিঁড়ে যায়, অথচ অগণিত সুতো আবার জট বেঁধে ফিরে আসে।\nতাদের সঙ্গে লড়াই করতে করতে আপনি আপনার সমস্ত শক্তি ক্ষয় করে ফেলেন।"
  },
  Event_59587_Name = {
