  },
  Event_59590_ChoiceDesc3 = {
    Text = "[Store] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_59590_Desc = {
    Text = "দেহের অভ্যন্তরে তিনটি প্লাস্টিডের শক্তি মিশে যাচ্ছে, তুমি কষ্টে এই বিশাল শক্তিকে নিয়ন্ত্রণ করছ।\nমানসিক জগৎ ক্রমাগত প্রসারিত হচ্ছে, একটি ছায়াপথ এখানে জন্ম নিচ্ছে ও ছড়িয়ে পড়ছে।\nঅবিরাম ধেয়ে আসা শত্রুদের মোকাবেলায়, তুমি আন্তরিকভাবে এই তারাভরা আকাশের কাছে প্রার্থনা করছ, এই শক্তির সাহায্য কামনা করছ।\nএকটি তারা ছায়াপথ থেকে খসে তোমার হাতের তালুতে এসে পড়ল, মোহনীয় আলো বিকিরণ করছে।"
  },
  Event_59590_Name = {
    Text = "ইচ্ছাতারা"
