  Event_59591_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59591_Desc = {
    Text = "তুমিও নীরবতায় সাড়া দাও, তোমাদের মধ্যে কোনো কথা হয় না, নীরবতাই সব প্রশ্নের উত্তর।\nতুমি সবকিছু মোকাবেলা করতে প্রস্তুত।"
  },
  Event_59591_Name = {
    Text = "তাঁর জিজ্ঞাসা"
  },
  Event_59592_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59592_Desc = {
    Text = "ওই বিড়ালটা কি মিথ্যুক?\nচারপাশে প্রতিধ্বনিত হাসির সঙ্গে সঙ্গে তুমি সেই পুকুরের মতো নীল চোখ দুটো নিয়ে সন্দেহ করতে শুরু করো।\n“মিথ্যুক, মিথ্যুক, তুমি তো ঠকেছ!”\nএক ধরনের অজানা দুশ্চিন্তা তোমার ভেতরে ফুঁসে ওঠে।"
  },
  Event_59592_Name = {
    Text = "গোপন ফিসফিস"
  },
  Event_59593_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59593_Desc = {
    Text = "তুমি যেন একজন দর্শক, নীরবে তাকিয়ে দেখছ ক্রমশ অপরিচিত হয়ে যাওয়া আবেগগুলোকে।\nতুমি সমস্ত মোহ ও আকুলতাকে দমন করলে, অনুভব করলে তোমার আত্মা ধীরে ধীরে বরফশীতল হয়ে যাচ্ছে।\nএটাই তোমার নিয়তি, এটাই তোমার অবশ্যম্ভাবী পথ।"
