  Event_59594_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59594_Desc = {
    Text = "ওই হাসিমাখা মুখটি অচঞ্চল; তোমার যুক্তি কিংবা আবেগের আর্তি—কিছুই তাকে টলাতে পারে না।\nমানুষের কামনা তার কাছে তুচ্ছ।\nতোমার শব্দ কি মানব কল্পনার সীমানা অতিক্রম করতে পারবে?"
