  },
  Event_59595_ChoiceDesc2 = {
    Text = "[Remain Silent] এলোমেলো 2 জন জাগরণকারীকে জাগাও, তবে 「(Skill.Arg1)「 দু」বার বিকশিত করো।"
  },
  Event_59595_Desc = {
    Text = "অসংখ্য বুদবুদ যেন অসংখ্য গোলাকার চোখ, তিনি নীরবে তোমার দিকে তাকিয়ে আছেন, যেন নিঃশব্দ প্রশ্ন করছেন।\nতুমি কি প্রস্তুত?\nসবকিছু ত্যাগ করতে প্রস্তুত?\nসবকিছুর দায়ভার বহন করতে প্রস্তুত?"
  },
