  Event_59596_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59596_Desc = {
    Text = "প্রতিপক্ষ আক্রমণ শুরু করার মুহূর্তেই তুমি পাল্টা আঘাত হানলে।\nতুমি বুদ্ধিমানের মতো তাদের আসল রূপ চিনে নিয়েছিলে—এরা আসলে দাঁত বের করা হিংস্র পশু ছাড়া আর কিছুই নয়।\nসৌভাগ্যক্রমে তুমি জয়ী হয়েছ।\nএখন প্রাণপণে পালাও, কিছুতেই তাদের হাতে ধরা পড়ো না।"
  },
