  },
  Event_59597_ChoiceDesc2 = {
    Text = "[Give Up] প্রস্থান"
  },
  Event_59597_Desc = {
    Text = "তুমি কী করবে?\nতুমি অসংখ্য নিজের দিকে তাকাও, অসংখ্য তোমার মতো মুখ তোমাকে দেখছে, তাদের ঠোঁট নড়ছে।\nযেন আশার শেষ খড়কুটো আঁকড়ে ধরেছ, তুমি মরিয়া হয়ে খুঁজে চলেছ, কান পেতে শুনছ, চূড়ান্ত উত্তর পাওয়ার আশায়।"
  },
