  Event_59598_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59598_Desc = {
    Text = "এখনও না। তোমাকে সহ্য করে অপেক্ষা করতে হবে।\nতুমি নিজের বিদ্বেষ আর ঘৃণা গিলে ফেলো, প্রতীক্ষা করো নির্ণায়ক মুহূর্তের।"
  },
  Event_59598_Name = {
    Text = "পুতুল হাত"
  },
  Event_59599_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59599_Desc = {
    Text = "তুমি এক অজানা টান অনুভব করো, যেন অদৃশ্য দৃষ্টির উৎসের দিকে টেনে নেওয়া হচ্ছ।\nতুমি শূন্যতার দিকে তাকাও, মনে হয় যেন কিছু একটার আভাস পেয়েছ।\nতোমার দৃষ্টিক্ষেত্র মুহূর্তের জন্য তুষারের মতো ঝাপসা দাগে ঢেকে যায়, আর চোখের সামনে থাকা পৃথিবী যেন রূপ বদলে ফেলে।\nচোখ মুছতে গিয়ে তুমি টের পাও, তোমার মুখ বেয়ে দুই ধারা রক্তমিশ্রিত অশ্রু গড়িয়ে পড়ছে।"
  },
  Event_59599_Name = {
    Text = "তার দৃষ্টি"
  },
  Event_59600_ChoiceDesc1 = {
    Text = "[চেষ্টা করে মনে করা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_59600_ChoiceDesc2 = {
    Text = "[দুঃখ উপভোগ করা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_59600_ChoiceDesc3 = {
    Text = "[Accept Silently] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_59600_Desc = {
    Text = "যেন সবচেয়ে সূক্ষ্ম মস্তিষ্ক-অস্ত্রোপচার চলছে, তুমি স্পষ্ট টের পাও—অতি প্রিয় স্মৃতিচারণগুলো তোমার মস্তিষ্ক থেকে টেনে বের করে নেওয়া হচ্ছে, আর তোমার চিন্তাগুলো ঝাপসা হয়ে যাচ্ছে, যেন মস্তিষ্ক গলে যাচ্ছে।\nতুমি যন্ত্রণায় কাঁপতে কাঁপতে, প্রতিরোধী হাতটিকে জোরে চেপে ধরো।\nস্ফটিকস্বচ্ছ অশ্রু গড়িয়ে পড়ছে, কিন্তু কেন পড়ছে?\nমনে হয় তুমি ভুলে গেছো।\nএক অকারণ, ব্যাখ্যাতীত বিষণ্ণতা তোমাকে গ্রাস করে।"
  },
  Event_59600_Name = {
    Text = "স্মৃতি বিয়োজন"
  },
  Event_59601_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59601_Desc = {
    Text = "বিড়ালের সঙ্গে তোমার বন্ধন নিয়ে কোনো সন্দেহ নেই। তুমি হাত নেড়ে, পেছনে না তাকিয়ে এগিয়ে যাও।\n\"বোকা! বোকা!\"\nপেছন থেকে কণ্ঠস্বরটি ক্ষোভে চিৎকার করে ওঠে।"
  },
  Event_59601_Name = {
    Text = "গোপন ফিসফিস"
  },
  Event_59602_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59602_Desc = {
    Text = "অটল সংকল্পে তুমি লড়াই চালিয়ে যাওয়ার সিদ্ধান্ত নাও, যেকোনো মূল্যে, সকলে’র আকাঙ্ক্ষা বয়ে নিয়ে।"
  },
  Event_59602_Name = {
    Text = "হিমায়িত ভবিষ্যৎ"
  },
  Event_59603_ChoiceDesc1 = {
    Text = "[Restrain] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_59603_ChoiceDesc2 = {
    Text = "[Gaze] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো"
  },
  Event_59603_Desc = {
    Text = "তাভি যে দরজা পাহারা দেয়, তার পেছনে রয়েছে অসীম জগৎ আর অসীম সত্য।\nসে দরজার ওপারে কী দেখেছে তুমি জানো না, তবে তুমি জানো সে সবকিছু জানে।\nএখন এই দরজা তোমার সামনে উন্মুক্ত, সকল সত্য দরজার ওপার থেকে নীরব আমন্ত্রণ জানাচ্ছে।"
  },
  Event_59603_Name = {
    Text = "বহু দ্বারের ওপারে"
  },
  Event_59604_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59604_Desc = {
    Text = "অজানা সত্তার প্রতি শ্রদ্ধা রাখা উচিত, তাদের তীক্ষ্ণতা এড়িয়ে চলাই বিচক্ষণ সিদ্ধান্ত।\nতুমি মাথা নিচু করলে, বুকের কাছে রুপোর চাবিটা শক্ত করে ধরলে, সামান্য সান্ত্বনা অনুভব করলে।\nঅন্তত তোমার কাছে এখনও শক্তি আছে, এখনও জাগরণকারীরা আছে।\nতুমি সেই দৃষ্টিগুলো উপেক্ষা করার চেষ্টা করলে, সামনের পথে মনোযোগ দিলে।\nকিন্তু সেই দৃষ্টিগুলো কি সত্যিই অদৃশ্য হয়েছে? তুমি মনে মনে জানো।"
  },
  Event_59604_Name = {
    Text = "তার দৃষ্টি"
  },
  Event_59605_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59605_Desc = {
    Text = "যদি দেবতাদের বিরোধিতা করার সব উপায়ই গাছ নাড়াতে চাওয়া পিঁপড়ের মতো নিষ্ফল হয়, তবে একমাত্র যে জিনিসটি আঁকড়ে ধরা যায়, তা হলো অটল সাহস।\nযখন অন্তহীন ধ্বংস মাথার ওপর ঝুলে থাকবে, তখন সামনের সারিতে দাঁড়িয়ে থাকবে তুমি।"
  },
  Event_59605_Name = {
    Text = "আত্ম-উত্তর"
  },
  Event_59606_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59606_Desc = {
    Text = "তুমি ঝরে পড়া অশ্রু স্পর্শ করো, আরেকবার অনুভব করো এক অতলান্তিক শোক।\nমনে হয় যেন তুমি কোনো অমূল্য জিনিস হারিয়েছ, অথচ কী ছিল তা আর মনে করতে পারো না।\nকি দুঃখজনক।\nতুমি দুর্বল হাতে অশ্রু মুছে ফেলো, ঠোঁটে জোর করে এক তিক্ত হাসি টেনে আনো।"
  },
  Event_59606_Name = {
    Text = "স্মৃতি বিয়োজন"
  },
  Event_59607_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59607_Desc = {
    Text = "তুমি তাদের কণ্ঠস্বর উপেক্ষা করলে।\nবিড়ালটি প্রতারক কিনা তা তুমি পরোয়া করো না, তুমি কেবল নিজের শক্তিতে বিশ্বাস করো।\nকানের কাছে সেই কণ্ঠস্বর দীর্ঘশ্বাস ফেলতে শুরু করল।"
  },
  Event_59607_Name = {
    Text = "গোপন ফিসফিস"
  },
  Event_59608_ChoiceDesc1 = {
    Text = "[Seek Answers] Arg1টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_59608_ChoiceDesc2 = {
    Text = "[Give Up] প্রস্থান"
  },
  Event_59608_Desc = {
    Text = "কেউ উন্মাদের মতো হাসছে।\nতোমার সেই সত্তা নিশ্চিত যে সবকিছুই নিরর্থক সংগ্রাম, তাই যত তাড়াতাড়ি সম্ভব হাল ছেড়ে দেওয়াই ভালো।\nতুমি ভ্রু কুঁচকালে, সেই সত্তা হঠাৎ মুচকি হেসে ঘুরে দাঁড়ায়। সে বলে—মানুষকে কষ্ট সহ্য করতে দেওয়ার চেয়ে নিজ হাতে তাদের জীবনের অবসান ঘটানোই শ্রেয়।\nতুমি হাত নেড়ে সেই কণ্ঠস্বরকে তাড়িয়ে দিলে, নিজের বিশ্বাসে অটল রইলে।"
  },
  Event_59608_Name = {
    Text = "স্ব-প্রশ্ন"
  },
  Event_59609_ChoiceDesc1 = {
    Text = "[Interrogate] যেকোনো 2টি কার্ড ধ্বংস করো"
  },
  Event_59609_ChoiceDesc2 = {
    Text = "[Pierce] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_59609_ChoiceDesc3 = {
    Text = "[Leave] Arg1টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_59609_Desc = {
    Text = "দীর্ঘ প্রতীক্ষার মাঝে তুমি আবার যোগাযোগকারী খুলে বসো। হয়তো তোমার আকুলতা আর নীরব প্রার্থনা ফল দিয়েছে; তুমি দেখো পরিচিত, স্নেহময় প্রতিক্রিয়াগুলো চিঠির ওপর ভেসে উঠছে।\nসে এখন ভীষণ নিরাপদ, তার পরামর্শদাতারা সবকিছু গুছিয়ে দিয়েছে, আর মিথাগও নির্বিঘ্নে চলছে...\nতুষারকণার মতো ঝরে পড়া এই সব সুসংবাদ দেখে, তোমার হৃদয় অনিচ্ছাসত্ত্বেও আলোড়িত হয়ে ওঠে।"
  },
  Event_59609_Name = {
    Text = "বিভ্রমের প্রতিধ্বনি"
  },
  Event_59610_ChoiceDesc1 = {
    Text = "[Catch the Stars] একটি রৌপ্য সৃষ্টি-কে উন্নয়ন অর্জন করে সোনার রেলিক 「(RelicConfig.Arg1)」-এ রূপান্তর করো"
  },
  Event_59610_ChoiceDesc2 = {
    Text = "[Crush the Stars] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 এবং 「(Skill.Arg3)」 দক্ষতা বিকশিত করো।"
  },
  Event_59610_ChoiceDesc3 = {
    Text = "[Watch Silently] 25টি কালো চিহ্ন গ্রহণ করুন"
  },
  Event_59610_Desc = {
    Text = "তোমার আবেগ স্মৃতির সাথে একসাথে ছিনিয়ে নেওয়া হচ্ছে, তুমি অনুভব করছ যে তুমি কোনো এক বিশাল সত্তায় পরিণত হচ্ছ, যেন কোনো দানব তার সুপ্রাচীন, উষ্ণ নীড়ে ফিরে এসেছে।\nঅগণিত সুখ-দুঃখ, হাসি-কান্না ঘনীভূত হয়ে একেকটি উজ্জ্বল তারায় রূপ নিচ্ছে, তোমার মানসিক মাত্রায় ঝলমলে বৃষ্টি হয়ে ঝরে পড়ছে।\nতোমার বেঁচে থাকার চিহ্নগুলো উল্কার মতো মিলিয়ে যাচ্ছে।\nতুমি নীরবে তাকিয়ে আছ, সামনে পড়ে থাকা একটি তারা তুলে নিলে, তার ভেতর থেকে ভেসে আসছে তোমার প্রাণখোলা হাসির শব্দ।\nতাই তুমিও একসাথে হেসে উঠলে, মধুর তৃপ্তিতে।"
  },
  Event_59610_Name = {
    Text = "আবেগের স্ফটিক"
  },
  Event_59611_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59611_Desc = {
    Text = "তুমি জানো এরা কেবল অতীতের ছায়া; তুমি নির্দয়ভাবে কেটে ফেলো তাদের, যারা একসময় তোমার সঙ্গে কথা বলত, বিন্দুমাত্র অনুভূতি ছাড়াই।\nতাদের হাসি আর কান্না তোমার মুঠোয় ভেঙে চুরমার হয়ে যায়, দ্বিধার কোনো অবকাশ না রেখে।\nযদি এ-ই হয় প্রয়োজনীয় পরীক্ষা, তবে তুমি-ই হবে সবচেয়ে নির্মম জল্লাদ।"
  },
  Event_59611_Name = {
    Text = "অতীতের ছায়া"
  },
  Event_59612_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59612_Desc = {
    Text = "এর নরম পশম আর স্বচ্ছ চোখ স্বাভাবিকভাবেই তোমার মনে বিশ্বাস জাগায়।\nতুমি বিড়ালের কাছে এগিয়ে গেলে, বিড়ালও তোমার কাছে এগিয়ে এলো।\nতোমাদের মধ্যে কোনো কথা হলো না, কিন্তু তার লেজ উঁচু করে খাড়া হয়ে আছে।"
  },
  Event_59612_Name = {
    Text = "বিড়ালের প্রলোভন"
  },
  Event_59613_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59613_Desc = {
    Text = "তুমি কৌতূহলের তাড়না সংবরণ করলে, তুমি জানো এই দরজা খোলা উচিত নয়।\nঅত্যধিক সত্য কখনো কখনো এক অভিশাপ।\nতুমি বুকের কাছে রুপোর চাবি শক্ত করে ধরলে, এই দরজা চিরতরে বন্ধ রাখার সংকল্প নিলে।"
  },
  Event_59613_Name = {
    Text = "বহু দ্বারের ওপারে"
  },
  Event_59614_ChoiceDesc1 = {
    Text = "[Courage] 2টি এলোমেলো কার্ডের প্রার্থনাগাথা গুণমান উন্নত করো।"
  },
  Event_59614_ChoiceDesc2 = {
    Text = "[Resolve] 3টি কমান্ড কার্ডের মধ্যে 1টির উপর প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_59614_Desc = {
    Text = "তাভির কথাগুলো তোমার মনে প্রতিধ্বনিত হচ্ছে।\nঅসংখ্য পরিণতির মধ্যে কেবল একটিই সঠিক পথ।\nঝাপসা দৃষ্টিতে তুমি দেখতে পাচ্ছ অসংখ্য জগতের ছায়ামূর্তি তোমার চোখের সামনে ফিল্মের ফ্রেমের মতো ভেসে যাচ্ছে, বোতাম টিপে একটি মুহূর্তকে স্থির করার অপেক্ষায়।\nএই এক সেকেন্ডের পর, পৃথিবী আসলে কোন পরিণতির মুখোমুখি হবে?"
  },
  Event_59614_Name = {
    Text = "হিমায়িত ভবিষ্যৎ"
  },
  Event_59615_ChoiceDesc1 = {
    Text = "[Ignore Suspicion] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_59615_ChoiceDesc2 = {
    Text = "[Arbitrary] 75টি কালো চিহ্ন গ্রহণ করো, কিন্তু 「(Skill.Arg2)」 নামের উপসর্গটি বিকশিত হবে"
  },
  Event_59615_Desc = {
    Text = "N-এর বিদ্রূপে, তুমি তোমার দেখা প্রতিটি মানুষকে নিয়ে সন্দেহ করতে শুরু করো।\nকারা তার অবতার, আর কারা তোমার সত্যিকারের গুরু ও বন্ধু?\nতার ছায়ারা ক্রমাগত বদলায়, অসংখ্য মুখ প্রকাশ পায়, সবকটিই তোমার দিকে তাকিয়ে হাসছে।"
  },
  Event_59615_Name = {
    Text = "ছায়ার শতমুখ"
  },
  Event_59616_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59616_Desc = {
    Text = "যদি সকলে বিশ্বাসঘাতকতার ক্ষমতা রাখে, তবে কারও ওপর ভরসা কোরো না।\nঅন্ধকারে তুমি কেবল একটি সত্যই নিশ্চিত করতে পারো।\nঅন্তত তুমি এখনো নিজেকে পেয়েছ—নিজের সেই সবচেয়ে অনুগত সংস্করণকে, যাকে তুমি বিশ্বাস করতে পারো।"
  },
  Event_59616_Name = {
    Text = "ছায়ার শতমুখ"
  },
  Event_59617_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59617_Desc = {
    Text = "তুমি জ্বলজ্বলে স্ফটিকটিকে চেপে গুঁড়ো করে ফেলো।\nতুমি লোভীভাবে অতীতের আবেগগুলো শ্বাসের সঙ্গে টেনে নাও।\nপ্রচণ্ড আনন্দের ঢেউ মস্তিষ্ক ভাসিয়ে দেয়, তারপর মায়াভ্রমের মতো মিলিয়ে যায়।\nতোমার ঠোঁট উঁচু হয়ে বাঁকায়, ধীরে ধীরে আবার নেমে আসে।\nতোমার মুখ ধীরে ধীরে শান্ত ও অভিব্যক্তিহীন হয়ে ওঠে।"
  },
  Event_59617_Name = {
    Text = "আবেগের স্ফটিক"
  },
  Event_59618_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59618_Desc = {
    Text = "তুমি জানো সব কিছুরই মূল্য আছে, আর যদি মুক্তির মূল্য হয় উৎসর্গ, তবে তুমি তা সম্পূর্ণভাবে পরিশোধ করতে প্রস্তুত।\nতুমি যে কোনো মুহূর্তে নিজেকে সম্পূর্ণ বিলিয়ে দিতে প্রস্তুত।"
  },
  Event_59618_Name = {
    Text = "আত্ম-উত্তর"
  },
  Event_59619_ChoiceDesc1 = {
    Text = "[Seek Answers] Arg1টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_59619_ChoiceDesc2 = {
    Text = "[Give Up] প্রস্থান"
  },
  Event_59619_Desc = {
    Text = "কেউ চিৎকার করছে।\nসে মরিয়া হয়ে পালাতে চাইছে, সে বলছে প্রতিরোধ মানেই পরাজয়।\nকেবল অন্তহীন পলায়নই চূড়ান্ত ধ্বংসকে বিলম্বিত করতে পারে।\nতুমি অর্ধবিশ্বাসে দ্বিধাগ্রস্ত।"
  },
  Event_59619_Name = {
    Text = "স্ব-প্রশ্ন"
  },
  Event_59620_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59620_Desc = {
    Text = "তুমি জানো সেই ভ্রূণগুলোর বংশবৃদ্ধির হার কতটা ভয়ংকর, এখানে নবজাতক পঙ্গপালের মতো এক অভিশাপ।\nতুমি সেই নবজাতকদের কান্না করার আগেই তাদের পিষে ফেলো।\nরক্তমাংসে গড়া মানুষেরা বিষাক্ত দৃষ্টিতে তোমার দিকে তাকায়, প্রশ্ন করে কেন তুমি পবিত্র জীবনকে অপবিত্র করছো।\nতুমি অন্তহীন হত্যাযজ্ঞ দিয়ে উত্তর দাও।"
  },
  Event_59620_Name = {
    Text = "অতীতের ছায়া"
  },
  Event_59621_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59621_Desc = {
    Text = "এই মুহূর্তে তুমি আশা করো তুমি-ই হবে সবচেয়ে ভাগ্যবান, অর্জন করবে সবচেয়ে নিখুঁত সমাপ্তি।\nকিন্তু সৌভাগ্যের মূল্য কখনও কখনও আরও নির্মম হয়। ভাগ্য আর দুর্ভাগ্য প্রায়ই পাশাপাশি হাঁটে। তুমি যখন কিছু অর্জন করো, ভুলে যেয়ো না, কী হারিয়েছ তা যাচাই করতে।"
  },
  Event_59621_Name = {
    Text = "ভাগ্যের বাছাই"
  },
  Event_59622_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59622_Desc = {
    Text = "এটা যেন গাড়ির স্টিয়ারিং হুইল নিয়ে লড়াই—তোমার হাত সবদিকে ছুটে বেড়াচ্ছে, সুরের ছন্দের ওপর নিয়ন্ত্রণ কেড়ে নেওয়ার চেষ্টা করছে।\nহুড়োহুড়ির উত্তাপে, হঠাৎই তুমি এক সারি কী-এর ওপর জোরে চাপ দাও।\nঅগোছালো পরিবেশনা ছিন্নভিন্ন হয়ে যায়; তুমি দাঁত বের করে হাসো, আর আরও গভীর উন্মাদনার অতলে নেমে যাও।"
  },
  Event_59622_Name = {
    Text = "প্রলয়ের উন্মত্ত সুর"
  },
  Event_59623_ChoiceDesc1 = {
    Text = "[Approach] 25টি কালো চিহ্ন পাওয়ার 100% সম্ভাবনা"
  },
  Event_59623_ChoiceDesc2 = {
    Text = "[Gaze] 50% সম্ভাবনায় 50টি কালো চিহ্ন পাবে, 50% সম্ভাবনায় কিছুই পাবে না।"
  },
  Event_59623_Desc = {
    Text = "একটি বিড়াল তোমার পিছু নেয়, তার লোম মসৃণ ও পরিষ্কার, সামনের পা দুটো তুষারের মতো সাদা।\nবিড়ালটি ধাপে ধাপে তোমার পাশে থাকে, যেন তোমার সবচেয়ে অনুগত ভৃত্য।\nতোমার সব বিভ্রান্তি, অসহায়তা, যন্ত্রণা ও উদ্বেগ শান্ত হয়ে আসে।"
  },
  Event_59623_Name = {
    Text = "বিড়ালের প্রলোভন"
  },
  Event_59624_ChoiceDesc1 = {
    Text = "[Deny] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg2)」 অর্জন করো, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_59624_ChoiceDesc2 = {
    Text = "[Retort] রৌপ্য সৃষ্টি 「(RelicConfig.Arg2)「 এবং 「(RelicConfig.Arg3)「 অর্জন করো, তবে 「(Skill.Arg1)「 দু」বার বিকশিত করো।"
  },
  Event_59624_ChoiceDesc3 = {
    Text = "[Remain Silent] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_59624_Desc = {
    Text = "তুমি এক ধরনের শূন্য মায়াজালে আটকে পড়েছ।\nতুমি দেখতে পাচ্ছ অগণিত মানুষ মহাপ্রলয়ের ছায়ায় নীরব, ধূলিকণার মতো ক্ষুদ্র।\nতারা হতবুদ্ধি, বিবর্ণ, আশাহীন।\nতুমি কারো তীক্ষ্ণ হাসি শুনতে পাচ্ছ।\n\"দেখো, এটাই তোমাদের জেদের পরিণতি।\"\n\"পৃথিবীর কখনো কোনো সমাপ্তি ছিল না, সবকিছুর কোনো অর্থই নেই।\""
  },
  Event_59624_Name = {
    Text = "জবাইয়ের মেষশাবক"
  },
  Event_59625_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59625_Desc = {
    Text = "না, এটা ভুল, এটা বাস্তব নয়।\nতুমি উন্মাদ কণ্ঠগুলোকে বারবার অস্বীকার করো, কিন্তু ধূসর ছায়ারা নড়ে না, যেন এক ভ্রান্ত সমাপ্তিকে নিশ্চিত করছে।\nহাসির শব্দ আরও জোরে ওঠে, তোমার অসহায়তাকে উপহাস করে।"
  },
  Event_59625_Name = {
    Text = "জবাইয়ের মেষশাবক"
  },
  Event_59626_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59626_Desc = {
    Text = "এক গভীর অনুশোচনা আর অনিচ্ছার ঢেউ তোমাকে গ্রাস করে; তুমি স্বতঃস্ফূর্তভাবে অতীত স্মরণ করতে লড়াই করো, স্মৃতির খণ্ডাংশের ভেতর তার চিহ্ন খুঁজে বেড়াও।\nঅস্পষ্ট প্রতিফলনগুলো দ্রুত দূরে সরে যায়, আর তুমি মরিয়া হয়ে তাদের আঁকড়ে ধরতে চাইলেও, তারা আঙুল ফাঁক গলে পিছলে যায়।\nতুমি হঠাৎ টের পাও, তুমি সবকিছু হারাতে চলেছ।"
  },
  Event_59626_Name = {
    Text = "স্মৃতি বিয়োজন"
  },
  Event_59627_ChoiceDesc1 = {
