  Event_59627_Desc = {
    Text = "একটি বিড়াল তোমার পিছু নেয়, তার লোম মসৃণ ও পরিষ্কার, সামনের পা দুটো তুষারের মতো সাদা।\nবিড়ালটি ধাপে ধাপে তোমার পাশে থাকে, যেন তোমার সবচেয়ে অনুগত ভৃত্য।\nতোমার সব বিভ্রান্তি, অসহায়তা, যন্ত্রণা ও উদ্বেগ শান্ত হয়ে আসে।"
  },
  Event_59627_Name = {
    Text = "বিড়ালের প্রলোভন"
  },
  Event_59628_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59628_Desc = {
    Text = "তুমি এখানে চূড়ান্ত তোমার সাথে সাক্ষাৎ করলে, সমগ্র বিশ্বকে ধ্বংস করার যুদ্ধ আসলে কেবল তোমাদের দৃষ্টির মুখোমুখি।\nযখন তিনি তোমার দিকে তাকান, তোমাকে অবশ্যই দৃঢ়ভাবে তাঁর দিকে সরাসরি তাকাতে হবে, যতক্ষণ না একটি দৃষ্টি বিলীন হয়ে যায় সেই মুহূর্ত পর্যন্ত।"
  },
  Event_59628_Name = {
    Text = "আত্ম-উত্তর"
  },
  Event_59629_ChoiceDesc1 = {
    Text = "[Breath] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_59629_ChoiceDesc2 = {
    Text = "[Counterattack] সোনালি সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 ও 「(Skill.Arg3)」 উপসর্গ বিকশিত করো।"
  },
  Event_59629_ChoiceDesc3 = {
    Text = "[Struggle] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_59629_Desc = {
    Text = "ঘন পায়ের শব্দ শোনা গেল, পরিদর্শন কমিটির একদল এজেন্ট তোমার পথ আটকে দাঁড়াল।\n\"আমাদের তদন্তে সহযোগিতা করুন।\"\nঠান্ডা কণ্ঠে লুকিয়ে আছে বিদ্বেষ।\nছপাৎ শব্দে শান্ত জলের পৃষ্ঠ ভেঙে গেল, তারা তোমাকে গভীর জলাশয়ে ছুড়ে ফেলল।"
  },
  Event_59629_Name = {
    Text = "অতলগামী"
  },
  Event_59630_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59630_Desc = {
    Text = "তুমি মরিয়া হয়ে লড়াই করছো।\nআরও সামনে, আরেকটু মাত্র।\nযে কোনো মূল্যেই হোক, তোমাকে সবকিছু রক্ষা করতেই হবে।\nতুমি হাত বাড়াও, সুতো তোমার মাংসে কেটে বসে, তবু তুমি কিছুই অনুভব করো না।"
  },
  Event_59630_Name = {
    Text = "পুতুল হাত"
  },
  Event_59631_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59631_Desc = {
    Text = "তুমি জোরে মাথা ঝাঁকালে, বিশৃঙ্খল স্মৃতিগুলোকে মস্তিষ্ক থেকে ঝেড়ে ফেললে।\nশীঘ্রই কোলাহলপূর্ণ শব্দগুলো ধীরে ধীরে মিলিয়ে গেল, তোমার চেতনা অবশেষে স্বাধীনতা ফিরে পেল।\nব্যর্থ অতীত থেকে তুমি কোনো সাহায্য পাবে না, কেবল বর্তমানে মনোনিবেশ করলেই আশার সন্ধান মিলবে।"
  },
  Event_59631_Name = {
    Text = "স্ব-প্রশ্ন"
  },
  Event_59632_ChoiceDesc1 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_59632_Desc = {
    Text = "হাত বাড়ানোর আগে, তুমি হঠাৎ মনে করলে, তুমি কখনো এমন একটা বিড়াল পোষোনি।\nতুমি আর বিড়ালটি বাতাসের ওপার থেকে একে অপরের দিকে তাকিয়ে রইলে, বিড়ালটি তোমার দিকে চোখ পিটপিট করল।\nবিড়ালটি তোমার ঔদাসীন্যে কিছু মনে করল না, দেখে মনে হচ্ছে সে আগের মতোই তোমাকে ভালোবাসে।"
  },
  Event_59632_Name = {
    Text = "বিড়ালের প্রলোভন"
  },
  Event_59633_ChoiceDesc1 = {
    Text = "[Seek Answers] Arg1টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_59633_ChoiceDesc2 = {
    Text = "[Give Up] প্রস্থান"
  },
  Event_59633_Desc = {
    Text = "কেউ একজন কাঁদছে।\nবেদনা ভরা হৃদয়ে, তারা প্রিয়জনকে তোষামোদকারীর আলিঙ্গনে জড়িয়ে ধরতে চায়।\nতাদের সবচেয়ে বড় আক্ষেপ—ধ্বংসের মুহূর্তে প্রিয়জনদের পাশে থাকতে না পারা।\nতাদের শোকে অংশ নিয়ে তোমার বুকেও হাহাকার জাগে।"
  },
  Event_59633_Name = {
    Text = "স্ব-প্রশ্ন"
  },
  Event_59634_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59634_Desc = {
    Text = "তুমি অসংখ্য ধূসর ছায়ামূর্তির দিকে তাকিয়ে আছ, সেই বিদ্রূপাত্মক হাসিকে উপেক্ষা করে।\nকীভাবে এই ধ্বংসপ্রাপ্ত পৃথিবীকে রক্ষা করা যায়?\nতুমি নীরব ধ্বংসের মাঝে অবিরাম ভাবতে থাক।"
  },
  Event_59634_Name = {
    Text = "জবাইয়ের মেষশাবক"
  },
  Event_59635_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59635_Desc = {
    Text = "ফুসফুসের বায়ুকোষ থেকে বাতাস ধীরে ধীরে মিলিয়ে যাচ্ছে, তুমি পানির নিচে শ্বাস নেওয়ার চেষ্টা করলে।\nকী বোকামি! কিন্তু তুমি সফল হলে।\nতোমার বায়ুকোষগুলো আবার পূর্ণ হয়ে উঠল, তুমি অবাধে নিঃশ্বাস ছাড়তে পারছ।\nকিন্তু তুমি আসলে কী শ্বাসের সাথে টেনে নিচ্ছ?"
  },
  Event_59635_Name = {
    Text = "অতলগামী"
  },
  Event_59636_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59636_Desc = {
    Text = "তুমি আঠালো তরলের ভেতর ডুবে যাচ্ছ।\nযতই ছটফট করো, ততই গভীরে তলিয়ে যাও।\nএই কাদামাটি থেকে তুমি একা পালাতে পারবে না।"
  },
  Event_59636_Name = {
    Text = "অতলগামী"
  },
  Event_59637_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59637_Desc = {
    Text = "তুমি জোর করে এই সংশয়গুলো ভুলে যাও।\nএই মুহূর্তে সংশয় যে নিষ্ফল, তা তুমি জানো; তোমার পক্ষে কেবল বিশ্বাস করাই সম্ভব।\nসিল করা বাক্সটি খোলার আগে তার সত্য তোমার কাছে অজানা জীবই থেকে যায়।\nকখনও কখনও, বিভ্রান্ত বোকা সেজে থাকা-ই শান্তি এনে দেয়।"
  },
  Event_59637_Name = {
    Text = "ছায়ার শতমুখ"
  },
  Event_59638_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59638_Desc = {
    Text = "সবার দৃষ্টি তোমার উপর নিবদ্ধ, তোমাকে সকলের নেতা হিসেবে দাঁড়াতে হবে, কোনো দুর্বলতা প্রকাশ করা চলবে না।\n\"কালো জলাভূমির দিকে এগিয়ে যাও, সব ঠিক হয়ে যাবে।\"\nতুমি স্থিরভাবে নির্দেশ দিলে, এমন এক প্রতিশ্রুতি দিলে যা তুমি নিজেও হয়তো বিশ্বাস করো না।"
  },
  Event_59638_Name = {
    Text = "অজ্ঞানের দৃষ্টি"
  },
  Event_59639_ChoiceDesc1 = {
    Text = "[Suspect] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg2)」 অর্জন করো, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_59639_ChoiceDesc2 = {
    Text = "[Disdain] রৌপ্য সৃষ্টি 「(RelicConfig.Arg2)「 এবং 「(RelicConfig.Arg3)「 অর্জন করো, তবে 「(Skill.Arg1)「 দু」বার বিকশিত করো।"
  },
  Event_59639_ChoiceDesc3 = {
    Text = "[Ignore] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_59639_Desc = {
    Text = "তোমার সামনে তিনটি দ্বিধাগ্রস্ত অবয়ব অস্পষ্ট কিছু বকবক করছে।\nতুমি ঝুঁকে শোনার চেষ্টা করো; তাদের শব্দ শ্বাসের সঙ্গে মিশে ধীরে ধীরে স্পষ্ট হয়ে ওঠে।\n\"ও বিড়ালটার ওপর ভরসা কোরো না; ও মিথ্যুক।\"\nতুমি হঠাৎ ঘুরে দাঁড়াও, কেবল দেখতে পাও তোমার পাশে কেউ নেই।"
  },
  Event_59639_Name = {
    Text = "গোপন ফিসফিস"
  },
  Event_59640_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59640_Desc = {
    Text = "তারাগুলো এত সুস্বাদু দেখায় যে তুমি তাদের শক্তির লোভে একটি তারা গিলে ফেলো।\nগলপ।\nতোমার আত্মা কখনো না হওয়ার মতো পরিপূর্ণ লাগে, আর চোখের কোণে এক আলো জ্বলে ওঠে।\nতুমি নিচের দিকে তাকিয়ে দেখো, তোমার পেটে সেই তারাটি এখনো জ্বলজ্বল করছে।"
  },
  Event_59640_Name = {
    Text = "ইচ্ছাতারা"
  },
  Event_59641_ChoiceDesc1 = {
    Text = "[Struggle Forward] একটি কমান্ড কার্ড ধ্বংস করো এবং Arg1টি কালো চিহ্ন প্রাপ্ত হও।"
  },
  Event_59641_ChoiceDesc2 = {
    Text = "[Snap the Thread] একটি কমান্ড কার্ড নকল করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকাশ করো।"
  },
  Event_59641_ChoiceDesc3 = {
    Text = "[Endure] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_59641_Desc = {
    Text = "পুরো পথজুড়ে তুমি ঠেলে এগিয়ে যাচ্ছ, তোমার প্রতিটি সিদ্ধান্ত অদৃশ্য সুতোয় নিয়ন্ত্রিত।\nতুমি মরিয়া হয়ে আঁকড়ে ধরতে চাও তোমার সব প্রিয় জিনিস।\nবিশ্বের ভাগ্য ঝুলে আছে তোমার আঙুলের ডগার ঠিক সামনে।\nঅগণিত সুতো জড়িয়ে গেছে, বেঁধে ফেলেছে তোমার সমগ্র দেহ।"
  },
  Event_59641_Name = {
    Text = "পুতুল হাত"
  },
  Event_59642_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59642_Desc = {
    Text = "তুমি রক্তমাখা অশ্রু মুছে ফেলো, কিন্তু আরও রক্ত গড়িয়ে পড়তেই থাকে।\nলাল রঙে ঢেকে যায় দৃষ্টি, যেন রক্তাক্ত কোনো উৎসর্গের পূর্বাভাস।\nতুমি কাঁপতে কাঁপতে, যন্ত্রণায় ছটফট করতে করতে মুছতে থাকো, কিন্তু ভয়ের লেশমাত্র নেই।"
  },
  Event_59642_Name = {
    Text = "স্ব-সত্তার সংমিশ্রণ"
  },
  Event_59643_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59643_Desc = {
    Text = "তুমি এই জাদুকরী রত্নটি আলতো করে স্পর্শ করলে এবং এটিকে রূপার চাবিতে বসিয়ে দিলে।\nতারার আলো তোমার উপর ঝলমল করে উঠল।\nতুমি মুগ্ধ ও বিমোহিত হয়ে গেলে।"
  },
  Event_59643_Name = {
    Text = "ইচ্ছাতারা"
  },
  Event_59644_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59644_Desc = {
    Text = "তবু তুমি চোখ বড় করে খোলা রেখেছিলে, নিখাদ ইচ্ছাশক্তিকে বিদ্রোহী গর্জনে রূপান্তরিত করেছিলে।\nভেঙে গুঁড়িয়ে মুছে গেলেও, তুমি এক পা-ও পিছু হটবে না।"
  },
  Event_59644_Name = {
    Text = "স্ব-সত্তার সংমিশ্রণ"
  },
  Event_59645_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59645_Desc = {
    Text = "কেউ নীরবে দাঁড়িয়ে আছে।\nসেই হতাশ, নিশ্চুপ মুখগুলোর দিকে তাকিয়ে তুমি বুঝতে পারো—তাদের কেউই শেষ পর্যন্ত পৌঁছাতে পারেনি।\nতুমিই সকল সত্তার মধ্যে সবচেয়ে দূর পর্যন্ত এগিয়ে এসেছ, কেবল তোমার নিজের উত্তরই শেষ আশা।"
  },
  Event_59645_Name = {
    Text = "স্ব-প্রশ্ন"
  },
  Event_59646_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59646_Desc = {
    Text = "তুমি হাত বাড়িয়ে অসংখ্য উল্কাপিণ্ড আঁকড়ে ধরতে চাও, জ্বলজ্বলে স্ফটিকগুলো তোমার আঙুলের ডগা ছুঁয়ে যায়。\nআনন্দ, শোক, ক্রোধ, ভয়…\nতুমি লোভী হয়ে প্রতিটি অনুভূতিকে কুক্ষিগত করো, আবার দেখো সেগুলো আঙুল ফাঁক গলে সরে যাচ্ছে。\nদীপ্তিমান আলো তোমার মুখ আলোকিত করে, তোমার চোখ ধীরে ধীরে গভীর ও অন্ধকার হয়ে ওঠে।"
  },
  Event_59646_Name = {
    Text = "আবেগের স্ফটিক"
  },
  Event_59657_ChoiceDesc1 = {
    Text = "[Call Out] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_59657_ChoiceDesc2 = {
    Text = "[Touch] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_59657_Desc = {
    Text = "তুমি পুতুলটিকে ভেঙে পড়তে দেখলে।\nসে ছিল সবচেয়ে যুক্তিবাদী সত্তা, সবচেয়ে বিশ্বস্ত সহকারী, যে তোমাদের অর্জিত সমস্ত তথ্য যত্নসহকারে সংরক্ষণ করত।\nকিন্তু এখন সে তোমাদের একসাথে কাটানো সব স্মৃতি ভুলে গেছে বলে মনে হচ্ছে।\nতুমি দেখলে পুতুলটির চোখের কোণ থেকে স্বচ্ছ তরল ফোঁটা ফোঁটা করে ঝরে পড়ছে।"
  },
  Event_59657_Name = {
    Text = "যন্ত্রমানবের অশ্রু"
  },
  Event_59658_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59658_Desc = {
    Text = "তুমি হাল ছাড়োনি, তার এনার্জি কোরের সাথে যোগাযোগ করার চেষ্টা করলে।\nযন্ত্র হলে তো রিস্টার্ট করলেই ঠিক হয়ে যাওয়ার কথা, তাই না?\nদুর্ভাগ্যবশত, নির্মম পুতুলটি তোমাকে এই সরল সুযোগ দিল না।\nতোমার সংযম পুতুলের কাছ থেকে কোনো দয়া বয়ে আনেনি, তাই তোমাকে পূর্ণ শক্তিতে লড়াই করতে হলো।"
  },
  Event_59658_Name = {
    Text = "যন্ত্রমানবের অশ্রু"
  },
  Event_59659_ChoiceDesc1 = {Text = "[Leave]"},
  Event_59659_Desc = {
    Text = "তুমি তোমার পুরনো সঙ্গীকে ধ্বংস করতে চাও না।\nতুমি মরিয়া হয়ে তার নাম ধরে ডাকো, সমস্ত নির্দেশ দাও, কিন্তু কিছুই কাজ করে না।\nপুতুলটি তোমাদের সাথে বিশ্বাসঘাতকতা করেছে, ফিরে গেছে জড় পদার্থের শীতল নিস্তব্ধতায়।"
  },
  Event_59659_Name = {
    Text = "যন্ত্রমানবের অশ্রু"
  },
  Event_60944_ChoiceDesc1 = {Text = "[Leave]"},
  Event_60944_Desc = {
    Text = "সময় ফুরিয়ে আসছে, তাই তুমি সবচেয়ে সরাসরি পথ বেছে নিয়ে অবরোধ ভেদ করো। জাগরণকারীরা উদ্দীপনা পেয়ে উচ্ছ্বসিত হয়ে ওঠে।\nশত্রুদের বাড়তি সতর্কতার কথা বলতে গেলে, তা কোনো উদ্বেগের বিষয় নয়।"
  },
  Event_60944_Name = {
    Text = "কমিটির এজেন্ট"
  },
  Event_60945_ChoiceDesc1 = {Text = "[Leave]"},
  Event_60945_Desc = {
    Text = "এজেন্ট প্রতিক্রিয়া জানানোর আগেই তুমি পেছন ঘুরে তার অস্ত্র ছিনিয়ে নাও। জোরদার বাহিনী পৌঁছানোর আগে তুমি সফলভাবে পালিয়ে যাও।\nদুঃখজনকভাবে, খবর ছড়িয়ে পড়েছে, আর পরের শত্রুরা হবে আরও প্রস্তুত। প্রস্তুত থেকো।"
  },
  Event_60945_Name = {
    Text = "কমিটির এজেন্ট"
  },
  Event_60946_ChoiceDesc1 = {Text = "[Leave]"},
  Event_60946_Desc = {
    Text = "একটি শিসের টানে এজেন্ট তোমার লুকোনো জায়গার দিকে এগিয়ে আসে। সে কাছে আসতেই, প্রতীক্ষায় থাকা জাগরণকারীরা ঝাঁপিয়ে পড়ে আক্রমণ চালায়।\nএকটি নিখুঁত ওত পেতে থাকা হামলা। এখানে থাকা হুমকি স্থায়ীভাবে নির্মূল হয়েছে।"
  },
  Event_60946_Name = {
    Text = "কমিটির এজেন্ট"
  },
  Event_60947_ChoiceDesc1 = {Text = "[Leave]"},
  Event_60947_Desc = {
    Text = "অসংখ্য শত্রুর মুখোমুখি হয়ে তুমি আর পাল্টা লড়াই করতে পারো না। তুমি ইচ্ছে করেই কোনো প্রতিরোধ না করে তাদের দৃষ্টিসীমার ভেতর পা বাড়াও।\nতুমি জানো, খুব শিগগিরই তোমাকে একটি আটক বিন্দুতে নিয়ে যাওয়া হবে, আর সেটাই পরিকল্পনার অংশ।\nসেখান থেকে তুমি পালিয়ে যাবে এবং খুঁজে নেবে এক নতুন পথ।"
  },
  Event_60947_Name = {
    Text = "পর্যবেক্ষণ বিন্দু"
  },
  Event_60948_ChoiceDesc1 = {Text = "[Leave]"},
  Event_60948_Desc = {
    Text = "অসংখ্য শত্রুর মুখোমুখি হয়ে, তুমি তাদের সঙ্গে পেরে ওঠো না। সংক্ষিপ্ত লড়াইয়ের পর তুমি প্রতিরোধ ত্যাগ করো।\nতুমি জানো, তোমাকে এখন একটি আটক কেন্দ্রে নিয়ে যাওয়া হবে, আর সেটাই পরিকল্পনার অংশ।\nসেখান থেকে তুমি পালাবে, আর খুঁজে নেবে এক নতুন পথ।"
  },
  Event_60948_Name = {
    Text = "পর্যবেক্ষণ বিন্দু"
  },
  Event_60949_ChoiceDesc1 = {Text = "[Leave]"},
  Event_60949_Desc = {
    Text = "অসংখ্য শত্রুর মুখোমুখি হয়ে তুমি তাদের সঙ্গে পেরে ওঠো না。\nতুমি সাময়িক সরে গিয়ে নতুন পথ খোঁজার সিদ্ধান্ত নাও।"
  },
  Event_60949_Name = {
    Text = "পর্যবেক্ষণ বিন্দু"
  },
  Event_61058_ChoiceDesc1 = {Text = "[Leave]"},
  Event_61058_Desc = {
    Text = "তুমি নিজের দুই হাতের দিকে তাকালে, নিজের সমগ্র শরীরের দিকে, হৃদয় আশা ও দৃঢ় সংকল্পে পরিপূর্ণ।\nযদি এই সবকিছু নিয়তির পরিকল্পনা হয়ে থাকে, তুমি সবকিছুর মুখোমুখি হতে প্রস্তুত।\nচূড়ান্ত মুহূর্তে যদি সত্যিই স্বর্গ বা নরকের দ্বার থেকে থাকে, তাহলে তুমিই নিজ হাতে এই পৃথিবীর জন্য সেই দ্বার উন্মোচন করবে।"
  },
  Event_61058_Name = {
    Text = "আড়চোখে তাকাও"
  },
  Event_61059_ChoiceDesc1 = {
    Text = "[Ready for Battle] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_61059_ChoiceDesc2 = {
    Text = "[Continue Observing] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো এবং প্রার্থনাগাথাকে খোদাই-রূপে পরিবর্তন করো।(ব্যবহার: 1/2)"
  },
  Event_61059_Desc = {
    Text = "তুমি তাড়াহুড়ো করে যুদ্ধে ঝাঁপিয়ে পড়ো না, বরং শান্তভাবে পরিস্থিতি বোঝার চেষ্টা করো। এই হঠাৎ আবির্ভূত কন্ডাক্টর যেন একই সঙ্গে বন্ধু ও শত্রু; তার অভিপ্রায় সম্পর্কে তুমি নিশ্চিত নও। তবু তুমি স্থির করো সম্পূর্ণ প্রস্তুতি নিতে, তার চ্যালেঞ্জের মুখোমুখি হতে, তারপরই তার প্রকৃত উদ্দেশ্য পর্যবেক্ষণ করবে।"
  },
  Event_61059_Name = {
    Text = "দানব কন্ডাক্টর"
  },
  Event_61060_ChoiceDesc1 = {
    Text = "[Listen] 3টি উন্নত প্রার্থনাগাথা থেকে 1টি খোদাই করো"
  },
  Event_61060_ChoiceDesc2 = {
    Text = "[Call Out] সোনালি সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_61060_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_61060_Desc = {
    Text = "দুর্ঘটনার পর থেকে, তুমি আর তোমার সঙ্গীর কোনো খবর পাওনি।\nঅসংখ্য বার্তা পাঠিয়েছ, কিন্তু সবই যেন সমুদ্রে পাথর ফেলার মতো—কোনো উত্তর আসেনি।\nযখন তুমি ইতিমধ্যে সব আশা ছেড়ে দিয়েছিলে, হঠাৎ যোগাযোগ যন্ত্রটি বেজে উঠল।\nতুমি ব্রিফকেসটি খুললে এবং টেলিফোনের রিসিভারটি কানের কাছে ধরলে।\n\"রহস্যরক্ষক……\"\nঘোরের মধ্যে তুমি সেই বহু কাঙ্ক্ষিত কণ্ঠস্বরটি শুনতে পেলে, যেন স্তরে স্তরে শূন্যতার ওপার থেকে সুদূর প্রতিধ্বনি ভেসে আসছে।"
  },
  Event_61060_Name = {
    Text = "স্মৃতিকাতরতার প্রতিধ্বনি"
  },
  Event_61061_ChoiceDesc1 = {
    Text = "[Embrace the Darkness] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_61061_ChoiceDesc2 = {
    Text = "[Attempt to Swim] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_61061_ChoiceDesc3 = {
    Text = "[Call to the Ghosts] 25টি কালো চিহ্ন গ্রহণ করুন"
  },
  Event_61061_Desc = {
    Text = "তুমি ঝাঁপিয়ে এগিয়ে গেলে, আর মাটি হঠাৎই অতিক্রম-অযোগ্য সাগরে রূপ নিল।\nতুমি মাটির ভেতর ডুবে যেতে থাকো।\nকবরস্থানের ভূতের মতো ঘন আর আঠালো অন্ধকার তোমাকে ঘিরে ধরে, লোভীভাবে তোমার মুখ আর নাকে ঢুকে পড়ে।"
  },
  Event_61061_Name = {
    Text = "ভূগর্ভে নিমজ্জন"
  },
  Event_61062_ChoiceDesc1 = {Text = "[Leave]"},
  Event_61062_Desc = {
    Text = "তুমি চোখ বড় বড় করে খুলে সব ধরনের সূক্ষ্ম সূত্র খুঁজতে শুরু করলে।\nএকশোটি চোখ একসাথে ঘুরতে লাগল, তুমি দেখলে সামনে মানবমুখী কুকুরের দৌড়ানো থাবা, তুমি দেখলে পেছনে হ্যামলিনের পরিচালনার দণ্ডের দোলানোর গতিপথ।\nতুমি লোভীর মতো সবকিছু পর্যবেক্ষণ করতে লাগলে।\nহঠাৎ, তুমি দেখলে মাটিতে একটি পরিচিত চোখের গোলা গড়িয়ে পড়েছে।\nসেটা যেন তোমার নিজেরই চোখ।"
  },
  Event_61062_Name = {
    Text = "জ্ঞানের লোভ"
  },
  Event_61063_ChoiceDesc1 = {Text = "[Leave]"},
  Event_61063_Desc = {
    Text = "না, তুমি এত কিছু দেখতে পারো না।\nতোমার চোখ কতগুলো আছে আবার? মাত্র... কয়েকটা?\nতাড়াহুড়ো করে তুমি চোখ বন্ধ করো আর হাতড়াতে থাকো নিজের মুখ।\nএক, দুই...\nআবার চোখ খুলতেই তোমার দৃষ্টিক্ষেত্র হয়ে যায় সঙ্কীর্ণ আর অজ্ঞ।\nআহা, তোমার তো মাত্র দুটো চোখ। কী দুঃখজনক।"
  },
  Event_61063_Name = {
    Text = "জ্ঞানের লোভ"
  },
  Event_61064_ChoiceDesc1 = {
    Text = "[Search] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_61064_ChoiceDesc2 = {
    Text = "[চোখ বন্ধ করো]এলোমেলোভাবে 1টি কমান্ড কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg1)」"
  },
  Event_61064_Desc = {
    Text = "ক্রমবর্ধমান সূত্রগুলো সুতোর মতো জট পাকিয়ে একটা গোলকধাঁধা তৈরি করেছে। তুমি উদ্বিগ্ন, বিভ্রান্ত, ক্রুদ্ধ — নিজেকে ঘৃণা করছ কেন তুমি কিছুই জানো না।\nপ্রচণ্ড চাপে তোমার মানসিক অবস্থা একটা সূক্ষ্ম সুতোর মতো টানটান হয়ে গেছে।\nঝন্ করে একটা শব্দ হলো, তুমি অনুভব করলে মাথার চামড়া হঠাৎ শিথিল হয়ে গেছে। তুমি হঠাৎই চারপাশের সমস্ত দৃশ্য দেখতে পাচ্ছ, শূন্যতার মাঝে দোলায়মান ছায়াগুলো দেখতে পাচ্ছ।\nআরও বেশি, তোমাকে আরও বেশি দেখতে হবে……"
  },
  Event_61064_Name = {
    Text = "জ্ঞানের লোভ"
  },
  Event_61065_ChoiceDesc1 = {Text = "[Leave]"},
  Event_61065_Desc = {
    Text = "তুমি মাটির ভেতর দিয়ে সাঁতার কাটছ, নিজেকে কল্পনা করছ সবচেয়ে চটপটে মাছ হিসেবে।\nমাছ হতে চাইলে, তোমাকে ত্যাগ করতে হবে তোমার মানবীয় পা দুটো।\nএটাই সেই চুক্তির মূল্য।\nঅল্প পরেই তুমি অনুভব করলে এক অভূতপূর্ব মুক্তি, যেন ভূগর্ভের সবচেয়ে স্বাধীন সত্তা তুমি নিজেই।\nতুমি ফিরে আসো পৃষ্ঠে, কিন্তু হাঁটতে শেখার স্মৃতিটুকুও তোমার আর নেই।"
  },
  Event_61065_Name = {
    Text = "ভূগর্ভে নিমজ্জন"
  },
  Event_61066_ChoiceDesc1 = {Text = "[Leave]"},
  Event_61066_Desc = {
    Text = "তোমার আঙুলের ডগায় রুপালি চাবির সেই পরিচিত স্পর্শ অনুভূত হলো, যা সকল আলোর কেন্দ্রবিন্দু।\nএটি তোমার জীবনের সারাংশ, এটি তোমার নিয়তির মূর্ত রূপ।\nঅতীতের অভিজ্ঞতাগুলো একে একে চোখের সামনে ভেসে উঠল।\nতোমার পছন্দ ইতিমধ্যেই এই জগতের পছন্দের সাথে অবিচ্ছেদ্যভাবে জড়িয়ে গেছে।\nতোমার নিয়তি ইতিমধ্যেই অসংখ্য মানুষের সাথে গভীরভাবে সংযুক্ত হয়ে গেছে।"
  },
  Event_61066_Name = {
    Text = "আড়চোখে তাকাও"
  },
  Event_61067_ChoiceDesc1 = {Text = "[Leave]"},
  Event_61067_Desc = {
    Text = "তুমি অনুভব কর, অসংখ্য পরিচিত উপস্থিতি তোমাকে ঘিরে আছে।\nঅস্তিত্বহীন হতে পারে এমন ভূতদের তুমি ডেকে ওঠার চেষ্টা করো।\nএকটি অলৌকিক ঘটনা ঘটে, আর তুমি নিজেকে আবার মাটির বুকে আবিষ্কার করো।\nঅগণিত সমাধিফলক নীরবে দাঁড়িয়ে আছে।"
  },
  Event_61067_Name = {
    Text = "ভূগর্ভে নিমজ্জন"
  },
  Event_61068_ChoiceDesc1 = {Text = "[Leave]"},
  Event_61068_Desc = {
    Text = "অনুভূতিতে ডুবে থাকার সময় তোমার নেই; তোমার একমাত্র লক্ষ্য এই ভেঙে পড়া পৃথিবীকে রক্ষা করা。\nযদি তোমাকে নক্ষত্র হতেই হয়, তবে হও এক উল্কাপিণ্ড。\nতুমি পতিত হলেও, যতক্ষণ তুমি রাত্রির আকাশকে আলোকিত করো।"
  },
  Event_61068_Name = {
    Text = "আড়চোখে তাকাও"
  },
  Event_61069_ChoiceDesc1 = {Text = "[Leave]"},
  Event_61069_Desc = {
    Text = "তুমি কানটা আরও কাছে ঠেকালে, প্রতিটি ক্ষুদ্র শব্দ ধরার চেষ্টা করলে।\n“আমি...”\n“তোমাকে অবশ্যই...”\nতুমি কেবল ভাঙা ভাঙা বাক্যাংশ শুনতে পাও, কোনো অর্থ উদ্ধার করতে পারো না।\nকিন্তু তুমি সাহস করো না কোনো শব্দ করতে, ভয়ে যে একটি শব্দও যেন মিস না হয়ে যায়।\nতবু, নিয়তি কোনো দয়া দেখায় না।\nশেষ ক্ষীণ শব্দটুকুও মিলিয়ে যায়, রেখে যায় শুধু নীরবতা।"
  },
  Event_61069_Name = {
    Text = "স্মৃতিকাতরতার প্রতিধ্বনি"
  },
  Event_61070_ChoiceDesc1 = {Text = "[Leave]"},
  Event_61070_Desc = {
    Text = "তুমি আর ভাবনা বাড়াও না, এবং জাগরণকারীদের আদেশ দাও সার বেঁধে তার চ্যালেঞ্জের মুখোমুখি হতে।"
  },
  Event_61070_Name = {
    Text = "দানব কন্ডাক্টর"
  },
  Event_61071_ChoiceDesc1 = {Text = "[Leave]"},
  Event_61071_Desc = {
    Text = "তুমি বারবার তার নাম ধরে ডাকছ, চেষ্টা করছ অন্তত অনুভূতির একটুখানি সুরও যেন পৌঁছে যায় তার কাছে।\nতুমি জানো না, সে আদৌ শুনছে কি না। তুমি কান পেতে থাকো মাইক্রোফোনের ওপার থেকে ভেসে আসা ক্ষীণ শব্দগুলোর দিকে।\nওটা হয়তো তারই জবাব, অথবা হয়তো অতীতের খণ্ডাংশ, যা অনন্ত লুপে ঘুরে চলেছে।\nআবারও বাঁচিয়ে তুলছে সেই সব আনন্দ আর শোক, যা একদিন তোমরা একসঙ্গে ভাগ করে নিয়েছিলে।"
  },
  Event_61071_Name = {
    Text = "স্মৃতিকাতরতার প্রতিধ্বনি"
  },
  Event_61072_ChoiceDesc1 = {Text = "[Leave]"},
  Event_61072_Desc = {
    Text = "হয়তো এই অন্ধকারটাই আসল জগৎ। এর সঙ্গে মিশে যেতে দোষ কোথায়?\nতুমি সম্পূর্ণভাবে অন্ধকারকে আলিঙ্গন করো, আর সে আর তোমাকে প্রত্যাখ্যান করে না। তুমি স্বচ্ছন্দে শ্বাস নিতে পারো।\nপরের মুহূর্তেই তুমি আবার পৃষ্ঠে ফিরে আসো। হয়তো কিছু একটা নীচে রয়ে গেছে, কিন্তু তার আর কোনো গুরুত্ব নেই।"
  },
  Event_61072_Name = {
    Text = "ভূগর্ভে নিমজ্জন"
  },
  Event_61073_ChoiceDesc1 = {
    Text = "[Gaze at Light] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_61073_ChoiceDesc2 = {
    Text = "[Touch Chest] এক জাগরণকারীকে জাগরণ ঘটাও, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত হবে।"
  },
  Event_61073_ChoiceDesc3 = {
    Text = "[Keep Running] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_61073_Desc = {
    Text = "তুমি পথ হারিয়ে ফেলেছ, আর কেবল উন্মত্তের মতো দৌড়াচ্ছ, ভাবারও সময় নেই।\nহঠাৎ, তোমার বুকে এক শূন্যতা অনুভব করো।\nনিচে তাকিয়ে দেখো, যেখানে হৃদয় থাকার কথা, সেখানে চাবির আকারের এক আলোকরেখা জ্বলছে।\nআলো ক্রমে উজ্জ্বলতর হয়ে তোমার সমগ্র দেহে বিস্তার লাভ করে।\nতুমি নিজেকে এক নক্ষত্রে রূপান্তরিত হতে দেখো।\nহঠাৎ তোমার বোধ হয়—সম্ভবত এ-ই ছিল তোমার নিয়তি, সবসময়।"
  },
  Event_61073_Name = {
    Text = "আড়চোখে তাকাও"
  },
  Event_61074_ChoiceDesc1 = {
    Text = "[Ready for Battle] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_61074_ChoiceDesc2 = {
    Text = "[Observe Carefully] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো এবং প্রার্থনাগাথাকে খোদাই-রূপে পরিবর্তন করো।(ব্যবহার: 2/2)"
  },
  Event_61074_Desc = {
    Text = "\"এই... দাঁড়াও! কী হচ্ছে...\"\n\"মহড়া।\"\nপুরুষটি নিরাভিব্যক্ত মুখে তোমার দিকে তাকায়।\n\"সঙ্গীত ব্যবহার করে জাগরণকারীর সংযোগ বজায় রাখা এক নতুন পরীক্ষা। অর্কেস্ট্রার মান নিশ্চিত করলেই নিখুঁত পরিবেশনা নিশ্চিত হয়।\"\nসে সুনিপুণ ভঙ্গিতে তার ব্যাটন তোলে, চিহ্নিত করে শুরু।\n\"বাজাও, রক্ষক। আমাকে দেখাও তুমি কী করতে পারো।\""
  },
  Event_61074_Name = {
    Text = "দানব কন্ডাক্টর"
  },
  Event_61075_ChoiceDesc1 = {
    Text = "[Ready for Battle] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_61075_Desc = {
    Text = "তার অভিপ্রায় যাই হোক, সে তোমাকে কমিটির প্রয়োগকারীদের হাত থেকে বাঁচিয়েছে। যদি তোমার ক্ষতি করার ইচ্ছে থাকত, তবে সে সাহায্য করত না। নিজেকে শক্ত করে, তুমি সবচেয়ে খারাপের জন্য প্রস্তুতি নাও।"
  },
  Event_61075_Name = {
    Text = "দানব কন্ডাক্টর"
  },
  Event_65400_ChoiceDesc1 = {Text = "[Leave]"},
  Event_65400_Desc = {
    Text = "একজন মধ্যস্থতাকারী বাইরের দিক থেকে উদ্ধারের প্রতিশ্রুতি পৌঁছে দিল, আরোহী উদ্ধারদল পাহাড়ে পৌঁছানোর চেষ্টা করতে করতে নিভে যাওয়া আশাকে আবার দপদপিয়ে তুলল।"
  },
  Event_65400_Name = {
    Text = "সংযোগস্থল"
  },
  Event_65401_ChoiceDesc1 = {Text = "[Leave]"},
  Event_65401_Desc = {
    Text = "অভিযানদলের কেউই তুষার পর্বত থেকে জীবিত ফিরতে পারেনি। বিপদের মুখে তুমি বারবার নিজেকেই বেছে নিয়েছো, সাধারণ মানুষের জীবন তোমার কাছে কোনো মূল্যই রাখেনি। তুমি মানবতার দীপ্তি ত্যাগ করে নিরাপদে শেষ প্রান্তে পৌঁছেছো।\nউদ্ধারকারীরা জটিল দৃষ্টিতে তোমার দিকে তাকাল, কিন্তু তুমি নির্বিকার থেকে তুষারঝড়ের ভেতর হাঁটতে থাকলে। হয়তো গভীর রাতে, তোমার উদাসীনতায় যারা প্রাণ হারিয়েছে, তাদের আত্মারা তোমার শয্যার চারপাশে জড়ো হবে, নীরবে তোমার দিকে তাকিয়ে থাকবে।"
  },
  Event_65401_Name = {
    Text = "নিরাপদ নিষ্কাশন বিন্দু"
  },
  Event_65402_ChoiceDesc1 = {
    Text = "[Crowd Evacuation] অবশিষ্ট বস্তু \"অভিযান দল\" সরিয়ে ফেলো এবং অভিযান দলের সদস্যসংখ্যার ভিত্তিতে ভিন্ন স্তরের \"Rescue Medal\" অর্জন করো।"
  },
  Event_65402_Desc = {
    Text = "তুমি নিরাপদে অভিযান দলকে সরিয়ে নেওয়ার স্থানে পৌঁছে দিয়েছ। উদ্ধারকারী দল দায়িত্ব নেয়, আর উদ্ধার হওয়া মানুষগুলো অন্য এক জগতে নিক্ষিপ্তদের মতো মাটিতে লুটিয়ে পড়ে।\nকিন্তু তুমি জানো, প্রকৃত সংকটের সমাধান এখনো বহু দূরে। সেই দৈত্যাকার জন্তুটি এখনো পর্বতমালায় ওত পেতে আছে, ক্ষুধার্ত প্রতীক্ষায় তার পরবর্তী পদক্ষেপের জন্য।"
  },
  Event_65402_Name = {
    Text = "নিরাপদ নিষ্কাশন বিন্দু"
  },
  Event_65403_ChoiceDesc1 = {
    Text = "[Supply Trade] 25টি কালো চিহ্ন গ্রহণ করো, এবং প্রতিটি অভিযাত্রী সদস্যের (Arg1) জন্য অতিরিক্ত 1টি করে।"
  },
  Event_65403_ChoiceDesc2 = {
    Text = "[Rescue Promise] 3টির মধ্যে 1টি প্রার্থনাগাথা উৎকীর্ণ করো। 2 জন অভিযাত্রী সদস্য লাভ করো।"
  },
  Event_65403_ChoiceDesc3 = {
    Text = "[Profit First] একটি গোল্ডেন+ রেলিক অর্জন করো, তবে 10 জন অভিযাত্রী সদস্য হারাও।"
  },
  Event_65403_Desc = {
    Text = "তুমি তুষারঝড় ভেদ করে এগিয়ে চলেছ, দূরের জরুরি যোগাযোগ কেন্দ্রের মিটমিট আলো অনুসরণ করে।\n○ অবশেষে, অগণিত প্রার্থনার পর, তুমি দেখতে পাও সেই ছোট কুটিরটিকে, যার ভেতরে আশ্রয় নিয়ে আছে আশা।"
  },
  Event_65403_Name = {
    Text = "সংযোগস্থল"
  },
  Event_65403_Tips3 = {
    Text = "অভিযাত্রী সদস্যের সংখ্যা খুব কম"
  },
  Event_65404_ChoiceDesc1 = {Text = "[Leave]"},
  Event_65404_Desc = {
    Text = "তুমি সংযোগকারীর কাছ থেকে গুদামের কোড পেলে এবং সকলের জন্য দুই দিনের সামগ্রী মজুত খুঁজে পেলে। অন্তত তুষার পর্বতে তোমরা না খেয়ে বা হিমায়িত হয়ে মরবে না।"
  },
  Event_65404_Name = {
    Text = "সংযোগস্থল"
  },
  Event_65415_ChoiceDesc1 = {Text = "[Confirm]"},
  Event_65415_Desc = {
    Text = "তুষার পর্বত মুহূর্তেই তার \"ভোজ\" সম্পন্ন করল; দুই জন মানুষ চিরতরে হারিয়ে গেল তলহীন গিরিখাতে, তোমাদের কারও নজরেই না পড়ে।"
  },
  Event_65415_Name = {
    Text = "বিভ্রম"
  },
  Event_65416_ChoiceDesc1 = {
    Text = "[Leave] সার্চলাইট খুঁজুন"
  },
  Event_65416_ChoiceDesc2 = {
    Text = "[Snow Intrusion] 2 জন অভিযাত্রী সদস্য হারাও"
  },
  Event_65416_Desc = {
    Text = "হঠাৎ এক ঝোড়ো হাওয়া তুষার পর্বত জুড়ে বয়ে যায়, বাতাসের হুঙ্কার যেন কোনো জন্তুর আর্তচিৎকার, তুষারকুয়াশায় তোমার দৃষ্টি অন্ধ হয়ে আসে। অনন্ত সাদার ভেতরে যেন কিছু একটা নড়ে ওঠে।\nতুমি বাধ্য হয়ে থেমে যাও, ঢাল বেয়ে গড়িয়ে পড়া এড়াতে বরফে পা গেঁথে দাঁড়িয়ে থাকো।"
  },
  Event_65416_Name = {Text = "???"},
  Event_65417_ChoiceDesc1 = {
    Text = "[Silent Evaporation] 2 জন অভিযাত্রী সদস্য হারান"
  },
  Event_65417_ChoiceDesc2 = {Text = "[Leave]"},
  Event_65417_Desc = {
    Text = "তুষার পর্বতের অন্তঃস্থল থেকে গর্জন উঠে আসে, যেন ক্ষুধার্ত জন্তুর গরগর শব্দ। মাটি কেঁপে ওঠে, তুষারের নিচের বরফ নীরবে ফেটে যায়, যেন তুষার পর্বত তার চোয়াল মেলে ধরেছে。\nকম্পন অবশেষে থেমে গেলে, মানুষ চারদিকে বিভ্রান্ত দৃষ্টিতে তাকায়, আর তুমি ফিরে দাঁড়িয়ে সঙ্গীদের অবস্থা যাচাই করো।"
  },
  Event_65417_Name = {
    Text = "বিভ্রম"
  },
  Event_65468_ChoiceDesc1 = {Text = "[Leave]"},
  Event_65468_Desc = {
    Text = "দলের গতিশীলতা নিশ্চিত করতে, তুমি সংগ্রামরতদের পরিত্যাগ করলে, তাদের রেখে এলে এক বিচ্ছিন্ন কেবিনে। এতে হয়তো বাকিদের বেঁচে থাকার সম্ভাবনা বাড়বে, কিন্তু তাদের ক্ষোভে ভরা দৃষ্টির মুখোমুখি হয়ে তুমি কি সত্যিই কিছুই অনুভব করো না?"
  },
  Event_65468_Name = {
    Text = "সংযোগস্থল"
  },
  Event_65483_ChoiceDesc1 = {Text = "[Leave]"},
  Event_65483_Desc = {
    Text = "তুমি কয়েকজনকে বাঁচিয়েছ, কিন্তু আরও অনেকে রয়ে গেছে তুষার পর্বতে। অন্তত তুমি সর্বোচ্চ চেষ্টা করেছ।\nউদ্ধারকারীরা বলল, তোমার প্রচেষ্টা পরে স্বীকৃতি পাবে। তুমি হাত নেড়ে তাদের বিদায় জানিয়ে আবার তুষারঝড়ের ভেতর ফিরে গেলে।"
  },
  Event_65483_Name = {
    Text = "নিরাপদ নিষ্কাশন বিন্দু"
  },
  Event_65484_ChoiceDesc1 = {Text = "[Leave]"},
  Event_65484_Desc = {
    Text = "তুমি কেবল তুষার পর্বত থেকে পালানোর দিকেই মনোযোগ দিয়েছিলে, বেছে নিয়েছিলে সবচেয়ে কার্যকর পথ। শেষ জীবিত প্রত্যাবর্তনকারীর চোখে তুমি হয়তো এক দানবের মতোই দেখিয়েছ।\nউদ্ধারকারীরা বলেছিল, তোমার অবদান শিগগিরই সম্মানিত হবে। তুমি হাত নেড়ে তাদের থামিয়ে দিলে, আর তুষারঝড়ের ভেতর হেঁটে চলে গেলে।"
  },
  Event_65484_Name = {
    Text = "নিরাপদ নিষ্কাশন বিন্দু"
  },
  Event_65485_ChoiceDesc1 = {Text = "[Leave]"},
  Event_65485_Desc = {
    Text = "আপনার সর্বাত্মক সুরক্ষায় বৈজ্ঞানিক অভিযান দলের সকল সদস্য সম্পূর্ণ অক্ষত রইলো। আপনার সাথে দেখা হওয়া তাদের দুর্ভাগ্যের মধ্যে সবচেয়ে বড় সৌভাগ্য, আপনি তাদের প্রকৃত ত্রাণকর্তা।\nআপনি বিপর্যয়ের মধ্যে এক অলৌকিক ঘটনা সৃষ্টি করেছেন, তুষার পর্বতের বীরের কাহিনী হয়তো শীঘ্রই চারদিকে ছড়িয়ে পড়বে। উদ্ধারকর্মীরা গম্ভীরভাবে জানালো আপনার অনন্য অবদানের জন্য পরে সম্মাননা দেওয়া হবে, আপনি হেসে হাত নেড়ে ঘুরে তুষারঝড়ের মধ্যে হেঁটে গেলেন।"
  },
  Event_65485_Name = {
    Text = "নিরাপদ নিষ্কাশন বিন্দু"
  },
  Event_65486_ChoiceDesc1 = {Text = "[Leave]"},
  Event_65486_Desc = {
    Text = "তুমি সত্যিই মানুষের জীবনের প্রতি যত্নশীল। তাদের অধিকাংশই তোমার হাতে রক্ষা পেয়েছে, আর তারা তোমার সুরক্ষার জন্য অশ্রুসিক্ত কণ্ঠে অবিরাম কৃতজ্ঞতা জানিয়েছে।\nউদ্ধারকারীরা গম্ভীরভাবে প্রতিশ্রুতি দিয়েছে, তোমার অসাধারণ অবদান শিগগিরই স্বীকৃতি পাবে। তুমি হাসলে, হাত নাড়লে, আর তুষারঝড়ের ভেতর হেঁটে চলে গেলে।"
  },
  Event_65486_Name = {
    Text = "নিরাপদ নিষ্কাশন বিন্দু"
  },
  Event_65487_ChoiceDesc1 = {Text = "[Leave]"},
  Event_65487_Desc = {
    Text = "তুমি রূপ বদলানো বিপর্যয়ের বিরুদ্ধে লড়েছ, মানুষকে টেনে এনেছ জীবন-মৃত্যুর প্রান্তে থেকে। তোমার প্রচেষ্টায়, মর্মান্তিক সমাপ্তি সামান্য হলেও সরে গেছে。\nউদ্ধারদল গম্ভীরভাবে তোমার অমূল্য অবদান স্বীকার করল এবং ঘোষণা করল যে তোমাকে সম্মানিত করা হবে। তুমি মৃদু হেসে হাত নাড়লে, তারপর আবার হেঁটে ঢুকে গেলে তুষারঝড়ের ভেতর।"
  },
  Event_65487_Name = {
    Text = "নিরাপদ নিষ্কাশন বিন্দু"
  },
