  },
  Event_6817_Desc = {
    Text = "কাঠের বুকশেলফের শীর্ষে, সোনালি মলাটের একটি বই রাখা আছে। মেঝে থেকে তাকালে তার নাম অস্পষ্ট, পড়া যায় না।\nকোনো এক অজ্ঞাত কারণে, বইটি পড়ার এক প্রবল আকাঙ্ক্ষা তোমার ভেতর ফুঁসে ওঠে... মুহূর্তেই সেই আকাঙ্ক্ষা নিয়ন্ত্রণের বাইরে চলে যায়। ধরা পড়ার ঝুঁকি উপেক্ষা করে তুমি বুকশেলফের পাশের কাঠের সিঁড়িতে চড়ে ওঠো, বইটি হাতে তুলে নাও, আর উন্মুখ হয়ে পড়তে শুরু করো...\nতোমার মনের সাগরে অস্পষ্ট সব ছাপ ভেসে ওঠে। তুমি মায়াস্বপ্নের সাগরে ডুবে যেতে থাকো..."
  },
  Event_6817_Name = {
    Text = "হলুদ গ্রন্থ"
  },
  Event_6818_ChoiceDesc1 = {
    Text = "[শোনা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_6818_ChoiceDesc2 = {
    Text = "[Ensemble] প্রতিটি জাগরণকারী, যার অ্যালিমাস 50 বা তার বেশি, তার জন্য 15টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_6818_ChoiceDesc3 = {
    Text = "[Leave] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_6818_Desc = {
    Text = "হঠাৎ পিয়ানোর শব্দ তোমার কানে এসে লাগে। অলৌকিক সবুজ আঙুলগুলো কী-বোর্ডের উপর নাচে, স্রোতস্বিনীর মতো সুশোভন এক সুর বুনে চলে।\n“প্রিয় বন্ধু, তুমি কি আমার সঙ্গে দ্বৈত সঙ্গীতে যোগ দেবে?”\nহাতগুলো কথা বলে না; তারা সুরের ভেতর দিয়েই তোমাকে প্রশ্ন করে।"
  },
  Event_6818_Name = {
    Text = "বীণার প্রেতাত্মা"
  },
  Event_6819_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6819_Desc = {
    Text = "রামোনা শব্দের উৎসের দিকে তাকাল, কিন্তু কেবল এক মিলিয়ে যাওয়া মায়াভ্রমকে ধরতে পারল, যেন একটি গ্রামোফোন দেয়ালের ভেতর গলে যাচ্ছে।"
  },
  Event_6819_Name = {
    Text = "অপরের কান"
  },
  Event_6820_ChoiceDesc1 = {
    Text = "[Clean the Typewriter] একটি কমান্ড কার্ড ধ্বংস করো, এবং 25টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_6820_ChoiceDesc2 = {
    Text = "[Try to Identify Text] একটি কার্ড অনুলিপি করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_6820_Desc = {
    Text = "সুটকেসের ভেতরের টাইপরাইটারটি হঠাৎ ঘন কালি উগরে দিল, ট্রেনের দুলুনিতে তা সরল রেখার মতো ছিটকে ছড়িয়ে পড়ল।"
  },
  Event_6820_Name = {
    Text = "টাইপরাইটারের মৃদুস্বর"
  },
  Event_6821_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6821_Desc = {
    Text = "তোমার মুষ্টি মায়াভ্রমকে ছিন্নভিন্ন করে দিলে, স্মৃতিচারণ ঢেউয়ের মতো মস্তিষ্কে আছড়ে পড়ে, যন্ত্রণার কাঁটা হয়ে আত্মাকে বিদ্ধ করে।"
  },
  Event_6821_Name = {
    Text = "মরীচিকা"
  },
  Event_6822_ChoiceDesc1 = {
    Text = "[Discard the Letter] একটি কার্ড ধ্বংস করো"
  },
  Event_6822_ChoiceDesc2 = {
    Text = "[Keep Close] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_6822_Desc = {
    Text = "\nতুমি টাইপরাইটার থেকে কয়েকটি কাগজ টেনে বের করো। ঝাপসা কালি থেকে তীব্র গন্ধ বেরোচ্ছে। তুমি দ্রুত চোখ বুলিয়ে নাও, আর অজান্তেই কপাল কুঁচকে ওঠে।\nচিঠির বেশিরভাগ অংশই কালি দিয়ে মুছে ফেলা, কেবল কিছু খণ্ডাংশ টিকে আছে যা কষ্টেসৃষ্টে বাক্য গঠন করে, ফলে প্রায় পড়াই যায় না।"
  },
  Event_6822_Name = {
    Text = "দাগলাগা চিঠি"
  },
  Event_6823_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6823_Desc = {
    Text = "তুমি কাগজের ঝাপসা লেখা পড়ার জন্য চোখ কুঁচকে তাকাও। শব্দগুলো মোচড়াতে মোচড়াতে একেবারে ভিন্ন কিছু প্রকাশ করে।\n“@2আমি ধরে নিচ্ছি তুমি পত্রিকায় খবরটা দেখেছ।\nহ্যাঁ, তোমার বাবা তোমাকে উত্তরাধিকারীর সারি থেকে সরিয়ে দিয়েছেন… আমরা চাইনি @2\nশয়তান, শয়তান…\nমিস্টার হার্বার্টের সঙ্গে অবিলম্বে সব সম্পর্ক ছিন্ন করো, নইলে আমি তোমার আর্থিক সহায়তা কেটে দেব…”"
  },
  Event_6823_Name = {
    Text = "লিখিত উপস্থিতি"
  },
  Event_6824_ChoiceDesc1 = {
    Text = "[Hold Silver Key] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_6824_ChoiceDesc2 = {
    Text = "[Close Your Eyes] এক জাগরণকারীকে জাগরণ ঘটাও, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত হবে।"
  },
  Event_6824_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6824_Desc = {
    Text = "\nঅযৌক্তিকতার এক উন্মত্ত ঢেউয়ে তুমি ছিন্নভিন্ন হয়ে গেলে, অঙ্গপ্রত্যঙ্গ বিকৃত হয়ে মাটিতে গড়াতে লাগলে, যেন মাত্রা @2-এর পরলোক থেকে আগত কোনো কিছুর ইশারায় নড়াচড়া করছ।\n「না... না...」\nতোমার সুস্থতা টুকরো টুকরো হয়ে প্রাচীর পতনের মতো ভেঙে পড়তে লাগল, প্রলাপের হাসি আর আর্তচিৎকার জড়িয়ে গেল এক বিশাল জালের মতো, যা তোমার চেতনাকে বেঁধে ফেলল, আর তোমার ঠোঁট থেকে ঝরে পড়তে লাগল শুধু অস্পষ্ট গোঙানি।"
  },
  Event_6824_Name = {
    Text = "পর্যবেক্ষকের দৃষ্টি"
  },
  Event_6825_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6825_Desc = {
    Text = "এটা রক্ষকের হাতে তুলে দাও, সে সামলাক; কে জানে, এটা কেমন সত্তাকে জাগিয়ে তুলতে পারে।"
  },
  Event_6825_Name = {
    Text = "নিঃসঙ্গ সিলভার কোর"
  },
  Event_6826_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6826_Desc = {
    Text = "একটি শোকভরা সুর কানের পাশ দিয়ে বয়ে যায়, মন ও আত্মা ভরে ওঠে যন্ত্রণা আর বেদনার ঢেউয়ে। টের পাওয়ার আগেই কারও চোখে অশ্রু জমে উঠেছে।"
  },
  Event_6826_Name = {
    Text = "নামহীন প্রতিধ্বনি"
  },
  Event_6827_ChoiceDesc1 = {
    Text = "[Open the Left Door] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_6827_ChoiceDesc2 = {
    Text = "[Open the Right Door] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো"
  },
  Event_6827_Desc = {
    Text = "দরজা। দরজা। অসংখ্য দরজা।\nতুমি আর রামোনা শেষবার পরিদর্শন করার পর থেকে যেন দরজার সংখ্যা বেড়েছে।\nতুমি করিডরে দাঁড়িয়ে, পরের দরজাটি ঠেলে খোলার জন্য প্রস্তুত।\nবাম দিকের দরজার ওপারে সবকিছু নীরব, নিঃশব্দে তোমার আগমনের প্রতীক্ষা করছে।\nডান দিকের দরজার ওপার থেকে অস্পষ্ট কণ্ঠস্বর শোনা যাচ্ছে।"
  },
  Event_6827_Name = {
    Text = "অসীমের দ্বার"
  },
  Event_6828_ChoiceDesc1 = {
    Text = "[Listen Closely] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_6828_ChoiceDesc2 = {
    Text = "[Plug Ears] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_6828_Desc = {
    Text = "তুমি শুধু উন্মত্ত কীবোর্ড চাপার শব্দই শুনতে পাও, ঝড়ের মতো আছড়ে পড়ছে, যেন উল্কাপিণ্ড মাটিতে গিয়ে লাগছে, আর পুরো পিয়ানো কেঁপে উঠছে।\nহ্যামারগুলো কড়মড় শব্দ করে, আর পেডালগুলো থেকে বেরোয় এক শোকাতুর আর্তনাদ।\nভূতুড়ে সুরের ভেতর পরিচিত সুরগুলো টেনে হিঁচড়ে নিয়ে যাওয়া হয়, তোমার কানের পর্দায় ঘষে ঘষে ক্ষত তৈরি করে।"
  },
  Event_6828_Name = {
    Text = "নিষিদ্ধ সুর"
  },
  Event_6829_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6829_Desc = {
    Text = "\"অনুসন্ধান কর্মকর্তা উইলিয়াম সিনিয়র জরুরি সামগ্রী সরবরাহ করেছেন; গ্রহণের পর নিশ্চিতকরণের জন্য তোমার ব্রোচ তিনবার ট্যাপ করো।\""
  },
  Event_6829_Name = {
    Text = "সহায়তা যোগাযোগ"
  },
  Event_6830_ChoiceDesc1 = {
    Text = "[Push Left Door] 3টি প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_6830_ChoiceDesc2 = {
    Text = "[Push the Right Door] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে যেকোনো একটিতে খোদাই করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_6830_Desc = {
    Text = "দরজা। দরজা। অসংখ্য দরজা।\nতুমি আর রামোনা শেষবার পরিদর্শন করার পর থেকে যেন দরজার সংখ্যা বেড়েছে।\nতুমি করিডরে দাঁড়িয়ে, পরের দরজাটি ঠেলে খোলার জন্য প্রস্তুত।\nবাম দিকের দরজার ওপারে সবকিছু নীরব, নিঃশব্দে তোমার আগমনের প্রতীক্ষা করছে।\nডান দিকের দরজার ওপার থেকে অস্পষ্ট কণ্ঠস্বর শোনা যাচ্ছে।"
  },
  Event_6830_Name = {
    Text = "অন্তহীন দ্বারসমূহ"
  },
  Event_6831_ChoiceDesc1 = {
    Text = "[Read the Letter] একটি কমান্ড কার্ড ধ্বংস করো, এবং Arg1টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_6831_ChoiceDesc2 = {
    Text = "[Close the Box]"
  },
  Event_6831_Desc = {
    Text = "সুটকেসটি অবিরাম কাঁপছে, যেন কোনো জীবন্ত সত্তা ডিমের খোলস ভেদ করে বেরিয়ে আসার দ্বারপ্রান্তে।\nতুমি অজান্তেই সুটকেস খুলে ফেলো, আর অক্ষরগুলো মুক্ত প্রজাপতির মতো বিক্ষিপ্ত হয়ে উড়ে যায়।"
  },
  Event_6831_Name = {
    Text = "অনাকাঙ্ক্ষিত পত্র"
  },
  Event_6832_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6832_Desc = {
    Text = "অবিরাম রিংটোন তোমার হৃদস্পন্দন বাড়িয়ে দেয়। তুমি রিসিভার তুলে টেবিলের ওপর রাখো। রিংটোন হঠাৎ থেমে যায়, যেন কেউ তার গলা চেপে ধরেছে, কেবল একটুখানি প্রতিধ্বনি থেকে যায় তোমার মনের ভেতর।"
  },
  Event_6832_Name = {
    Text = "ট্রেন কল"
  },
  Event_6833_ChoiceDesc1 = {
    Text = "[Pick up the Photo] 3টি কমান্ড কার্ডের মধ্যে 1টিতে 「(EnchantConfig.Arg1)」 নামের প্রার্থনা খোদাই করো।"
  },
  Event_6833_ChoiceDesc2 = {
    Text = "[Check Film] 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো এবং যে প্রার্থনাগাথা খোদাই করা হবে তা বদলাও।(ব্যবহার: 2/2)"
  },
  Event_6833_Desc = {
    Text = "স্টুডিওর এক কোণে পড়ে আছে একটি পুরোনো ক্যামেরা, কয়েক রোল ফিল্ম, আর বিক্ষিপ্ত কিছু ছবি। এগুলো বিশ্বস্তভাবে নথিবদ্ধ করেছে মোমের ভাস্করের কাজ আর নান্দনিকতা।"
  },
  Event_6833_Name = {
    Text = "হুবহু নথি"
  },
  Event_6834_ChoiceDesc1 = {
    Text = "[Continue Questioning] সর্বোচ্চ HP Arg1 বৃদ্ধি পায়"
  },
  Event_6834_ChoiceDesc2 = {
    Text = "[ছায়া ধরা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_6834_Desc = {
    Text = "ছায়াটি সোনালি ধুলোর মাঝে মন্ত্রোচ্চারণ করে:\n「যারা সত্যকে জানে...\nচাবিকেই যাদের কর্তৃত্ব, তারাই পথ দেখাবে।」\nএক প্রাচীন বাণী।\nতোমার অন্তর্দৃষ্টি বলে, এটা তোমার খোঁজা সত্যের খুব কাছাকাছি।\nআর তোমার অন্তর্দৃষ্টি কখনোই ভুল হয় না।"
  },
  Event_6834_Name = {
    Text = "রৌপ্য চাবির বাহক"
  },
  Event_6835_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6835_Desc = {
    Text = "তুমি উন্মাদ প্রলাপের সঙ্গে প্রকাশ্যে সহমত জানাও, আর সেই উন্মাদ সত্তার প্রলোভনে পড়ে প্রায় তার ভোজের টেবিলেই গিয়ে শেষ করতে বসেছিলে।"
  },
  Event_6835_Name = {
    Text = "জলীয় আচার"
  },
  Event_6836_ChoiceDesc1 = {
    Text = "[Call the Crow] 30টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 দক্ষতা বিকশিত করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_6836_ChoiceDesc2 = {
    Text = "[Get Far Away]"
  },
  Event_6836_Desc = {
    Text = "তুমি যদি না যাও, তারাও যাবে না।\nএক অদ্ভুত দড়ি তোমাদের আত্মাকে বেঁধে রেখেছে; মনে হয় তাদের তোমার কাছে বলার কিছু আছে।"
  },
  Event_6836_Name = {
    Text = "নির্বাসিত কাক"
  },
  Event_6837_ChoiceDesc1 = {
    Text = "[Give Up Resistance] একটি কমান্ড কার্ড ধ্বংস করো, এবং Arg1 কালো চিহ্ন গ্রহণ করো।"
  },
  Event_6837_ChoiceDesc2 = {
    Text = "[Pull Back Hands]"
  },
  Event_6837_Desc = {
    Text = "এক, দুই, তিন...\nমুখে, আঙুলে, ঝাঁকে ঝাঁকে প্রজাপতি আকাশের আতশবাজির মতো ঝলমল করে, তাদের রত্নের মতো আভা অন্ধকার ভেদ করে যায়।\nএই টাইপরাইটারের কোনো বাস্তব প্রয়োগ নেই, কিন্তু সৌন্দর্য সৃষ্টি করার ক্ষেত্রে এটি এক ওস্তাদ।"
  },
  Event_6837_Name = {
    Text = "অনুপ্রেরণার বিস্ফোরণ"
  },
  Event_6838_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6838_Desc = {
    Text = "এখন দেখভাল করার মতো আরও জরুরি বিষয় আছে। তুমি বাক্সটি বন্ধ করো, তাকে উপেক্ষা করার সংকল্প নাও, আর টাইপরাইটার ধীরে ধীরে স্তব্ধ হয়ে যায়।"
  },
  Event_6838_Name = {
    Text = "অনাহূত সতর্কবার্তা"
  },
  Event_6839_ChoiceDesc1 = {
    Text = "[Listen to the Moon] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_6839_ChoiceDesc2 = {
    Text = "[Listen to the Dwarf Star] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_6839_ChoiceDesc3 = {
    Text = "[Listen to the Meteor] 25টি কালো চিহ্ন হারান"
  },
  Event_6839_Desc = {
    Text = "প্রবল, উজ্জ্বল, অন্তহীন।"
  },
  Event_6839_Name = {
    Text = "নাক্ষত্রিক সুরলহরী"
  },
  Event_6840_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6840_Desc = {
    Text = "জ্যোতির কেন্দ্রে রয়েছে জমাট বাঁধা সিলভারের এক ফোঁটা, অথচ তোমার বোধ বলে—ওটা আদৌ জ্বলছে না।\nতোমার দৃষ্টি আলোর উৎস অনুসরণ করে, আর শেষে গিয়ে মুখোমুখি হয় শুধু অন্ধকার আর অজানা ফাঁদের..."
  },
  Event_6840_Name = {
    Text = "নিশাদ্যুতি"
