  },
  Event_6847_Desc = {
    Text = "ডান দিকের দরজাটি খোলা, মেঝের ওপর রক্ত পূর্বনির্ধারিত পথ এঁকে এগিয়ে গেছে।"
  },
  Event_6847_Name = {
    Text = "নিস্তব্ধ প্রকোষ্ঠ"
  },
  Event_6848_ChoiceDesc1 = {
    Text = "[Leave] এখানে তোমার জন্য আর কিছুই অবশিষ্ট নেই।"
  },
  Event_6848_Desc = {
    Text = "কে বলেছে সব সময়ই সামনে ঝাঁপিয়ে পড়তে হবে? এক পা পিছিয়ে আসাই হয়তো উন্মোচন করবে এক বিস্তীর্ণ নতুন জগৎ।"
  },
  Event_6848_Name = {
    Text = "নিস্তব্ধ প্রকোষ্ঠ"
  },
  Event_6849_ChoiceDesc1 = {
    Text = "[Repair Wax Sculpture] একটি কার্ড বেছে নাও এবং তার অ্যারিথমেটিকা ব্যয় 1 কমাও"
  },
  Event_6849_Desc = {
    Text = "মোমের ভাস্কর্যটির পুনরুদ্ধার কাজ চলছে।\nতুমি কোনো পেশাদার মোমের ভাস্কর নও, আনুষ্ঠানিক নান্দনিক শিক্ষাও পাওনি।\nতবু, তুমি দক্ষ হাতে গড়া, আকার দেওয়া আর রঙ করা শুরু করো...\nযেন জন্ম থেকেই তোমার হাতে ছিল এক টুকরো ছেনি।\nযেন এই ভাস্কর্যটি আদতেই অসম্পূর্ণ থাকার কথা ছিল, তোমার স্পর্শের প্রতীক্ষায়।"
  },
  Event_6849_Name = {
    Text = "অসমাপ্ত মোমের ভাস্কর্য"
  },
  Event_6850_ChoiceDesc1 = {
    Text = "[Repair Wax Sculpture] একটি কার্ড বেছে নাও এবং তার অ্যারিথমেটিকা ব্যয় 1 কমাও"
  },
  Event_6850_Desc = {
    Text = "গ্যালাটিয়া, গ্যালাটিয়া...\nডাকের অনুসরণে আবারও তুমি আবিষ্কার করেছ অসমাপ্ত মোমের ভাস্কর্যটিকে।\nসে ছিল নিখুঁত, এমনকি অস্বস্তিকরভাবে নিখুঁত।\n「কুৎসিততা হলো পরিপূর্ণতার গায়ে ফেটে যাওয়া এক ফাঁটল।」\nশেষ মুহূর্তে, তুমি কিছু একটা করার সিদ্ধান্ত নাও।"
  },
  Event_6850_Name = {
    Text = "অসমাপ্ত মোমের ভাস্কর্য"
  },
  Event_6851_ChoiceDesc1 = {
    Text = "[মায়াভ্রম গ্রহণ করুন]এলোমেলো 1টি কমান্ড কার্ড অরিসন লাভ করে：「(EnchantConfig.Arg1)」，সংক্রমিত হয়「(Skill.Arg2)」"
  },
  Event_6851_ChoiceDesc2 = {
    Text = "[Deny the Illusion] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_6851_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6851_Desc = {
    Text = "ভারী, অন্ধকার লোহার সেতুটির নীচে, নলখাগড়ায় ঢেকে যাওয়া নীরব নদীতীরে হঠাৎই এক জ্বলজ্বলে প্রজাপতি উড়ে উঠল।\nপ্রজাপতিটি আলতো করে এসে নামল তোমার তালুতে। ভয়াবহ হাহাকার থেমে গেল, তার জায়গায় শোনা গেল মরচে ধরা রেলে গড়িয়ে চলা ট্রেনের গর্জন, জ্বলতে থাকা কয়লার খসখস শব্দ, আর ঘুরতে থাকা অক্ষের ধাতব কড়মড়ানি..."
  },
  Event_6851_Name = {
    Text = "আয়রনওয়ে মরীচিকা"
  },
  Event_6852_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6852_Desc = {
    Text = "হ্যাঁ, তুমি পালাচ্ছ, কোনো এক সত্তা তোমাকে তাড়া করছে। তোমার বেঁচে থাকার প্রবৃত্তি তোমাকে মরিয়া দৌড় করিয়ে নিয়ে যায়, যতক্ষণ না সামনে আর কোনো পথ থাকে না। থামো, তা হলে কি হওয়ার কথা ছিল না... নরককুকুরদেরই, যারা পালানোর পথ নেই রেখে যায়?"
  },
