  },
  Event_6853_Desc = {
    Text = "মাটির ওপরের আয়নাগুলোর ফ্রেমগুলো ভীষণ জটিল, ফ্রেমের ভেতর ফ্রেম, ফ্রেমের ভেতর আবার ফ্রেম...\nঅ্যালিস লাফিয়ে নিচে পড়ে, আর পড়তেই থাকে অন্তহীন খরগোশের গর্তে, একের পর এক আয়না, একের পর এক আত্মা বন্দি, কিন্তু নিজেকে দেখতে অক্ষম।"
  },
  Event_6853_Name = {
    Text = "আয়নার ভেতর আয়না"
  },
  Event_6854_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6854_Desc = {
    Text = "তুমি তুষারে ঢাকা জানালা দিয়ে তুষার পর্বতের দিকে তাকিয়ে আছো, অসংখ্য কালো পিঁপড়ে একটি মাত্র কালো পিঁপড়েকে তাড়া করছে...\nতোমার চিন্তার স্রোত হঠাৎ থেমে যায়।"
  },
  Event_6854_Name = {
    Text = "আগ্নেয়গিরির স্মৃতি"
  },
  Event_6855_ChoiceDesc1 = {
    Text = "[Step Forward and Grip] 100% সম্ভাবনায় 25টি কালো চিহ্ন পাবে"
  },
  Event_6855_ChoiceDesc2 = {
    Text = "[Friendly Response] 50% সম্ভাবনায় 50টি কালো চিহ্ন পাবে, 50% সম্ভাবনায় কিছুই পাবে না।"
  },
  Event_6855_Desc = {
    Text = "অজানা জীবের এক বিড়াল D-পঙ্কের ভিড়ে বসে থাকে, তার ঝাপসা দেহ যেন ইঙ্গিত দেয় যে সে আত্মিক মাত্রার বাসিন্দা।\nএই অস্পষ্ট প্রক্ষেপণটি প্রজ্ঞাময় চোখে র‍্যামোনার দিকে চেয়ে থাকে, তার সাদা থাবা তোলে, আর তাকে আহ্বান জানায়।"
  },
  Event_6855_Name = {
    Text = "বিচরণকারী বাসিন্দা"
  },
  Event_6856_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6856_Desc = {
    Text = "একটি প্রাণবন্ত দলীয় প্রতিকৃতি।\nমোমের ভাস্কর্যগুলি সাজগোজ করে পরিপাটি হয়ে বসে আছে, সবার মুখে একই অতিরঞ্জিত হাসি।\nতারা দেখতে ঠিক ততটাই সুশৃঙ্খল, যতটা তুমি কোনো উন্মাদাগারে দেখতে পেতে।\n\nতারিখ: এ.এফ. 305, @2 রজার্স"
  },
  Event_6856_Name = {
    Text = "প্রতিকৃতি গ্যালারি"
  },
  Event_6857_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6857_Desc = {
    Text = "\nতুমি সাবধানে খণ্ডাংশগুলো তুলে নিয়ে গভীরভাবে পরীক্ষা করো। ও আবার নিশ্চল হয়ে যায়.\n「তোমার গাফিলতি হাত সামলে রাখো, নড়াচড়া কোরো না, 」 ডল তোমার মাথার পেছনে হালকা টোকা দেয়, 「এ রকম আরেকটা টুকরো আমি এত তাড়াতাড়ি বানিয়ে দিতে পারব না।」"
  },
  Event_6857_Name = {
    Text = "অস্থির ব্রোচ"
  },
  Event_6858_ChoiceDesc1 = {Text = "[Use Key]"},
  Event_6858_ChoiceDesc2 = {Text = "[Leave]"},
  Event_6858_Desc = {
    Text = "একটি দরজা তোমার পথ রুদ্ধ করে। তুমি সম্ভাব্য সব উপায়ই চেষ্টা করেছ, তবু সেটি অনড় থেকে গেছে।"
  },
  Event_6858_Name = {
    Text = "মরিচা ধরা দ্বার"
  },
  Event_6858_Tips1 = {
    Text = "আপনাকে 「মরিচা ধরা চাবি」 খুঁজে বের করতে হবে।"
  },
  Event_6859_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6859_Desc = {
    Text = "তোমার তাড়াহুড়ো নিয়ে তুমি লজ্জিত বোধ করলে।\nএকজন যোগ্য রক্ষককে হতে হয় কঠোর; তুমি হঠাৎ করেই এ রায় দিতে পারো না যে এগুলো 「উচ্চমানের পণ্যসামগ্রী」 নয়।\nতাই তুমি স্থির করলে, ভালো করে পর্যবেক্ষণ করবে। পাঁচ মিনিট কেটে গেল, দশ মিনিট কেটে গেল...\nআচ্ছা, এখন তুমি একটি বিচার করতে পারো—\nএগুলো সত্যিই আবর্জনা।"
  },
  Event_6859_Name = {
    Text = "বন্দী আত্মা"
  },
  Event_6860_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6860_Desc = {
    Text = "তুমি আর তোমার সঙ্গীরা অস্ত্র মাটিতে নামিয়ে রাখলে।\nএটা দয়া থেকে নয়; তুমি জানো, তাদের ভঙ্গুর দেহ বেশিক্ষণ টিকবে না।\nশেষ পর্যন্ত, তোমার ধারণাই সত্যি প্রমাণিত হয়।"
  },
