  Event_6861_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6861_Desc = {
    Text = "\n「এসো, আমাকে ধরো!」\n「এসো না, বোকা!」\n「যদি পারো, আমাদের ধরে দেখাও!」\nবালকেরা গর্বে ভরা কণ্ঠে চিৎকার করছিল।\n「ধুর! ওখানেই থামো!」\nবয়স্ক মানুষের কণ্ঠ হাঁপিয়ে উঠেছে।"
  },
  Event_6861_Name = {
    Text = "আমাদের স্মৃতি"
  },
  Event_6862_ChoiceDesc1 = {
    Text = "[Enter] কুয়াশা চিরে এগিয়ে গিয়ে অন্য প্রান্তে নাগাল পান।"
  },
  Event_6862_ChoiceDesc2 = {Text = "[Leave]"},
  Event_6862_Desc = {
    Text = "এখানেই সেই ব্যক্তি যাকে আপনি খুঁজছিলেন। আপনি গোপনরক্ষকের হ্যান্ডবুক সম্পন্ন করেছেন।"
  },
  Event_6862_Name = {
    Text = "একমুখী গোপন পথ 26"
  },
  Event_6863_ChoiceDesc1 = {
    Text = "[Leave] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_6863_Desc = {
    Text = "আহ! অল্পের জন্য মিস! থামো, তিনটা পাশা গড়িয়ে দশ এল কীভাবে?\nপাশাগুলো তোমার সামনে নিশ্চুপ শুয়ে আছে, দেখতে নির্দোষ আর অনুগত।"
  },
  Event_6863_Name = {
    Text = "অনন্ত জুয়া"
  },
  Event_6864_ChoiceDesc1 = {
    Text = "[Leave] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_6864_Desc = {
    Text = "ধুর! এখনো ছ’টা বাজেনি, তবু কিছুটা লাভ তোলা যায় বোধহয়।\nতাহলে, আসলে এখন ক’টা বাজে?"
  },
  Event_6864_Name = {
    Text = "অনন্ত জুয়া"
  },
  Event_6865_ChoiceDesc1 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6865_Desc = {
    Text = "যদিও আমি ঠিকমতো অনুমান করতে পারিনি, তবু মেনে নিতে পারি।\nহা-হুতাশ, তারা কখন ভোট দিল?"
  },
  Event_6865_Name = {
    Text = "অনন্ত জুয়া"
  },
  Event_6866_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6866_Desc = {
    Text = "তুমি মাথা নত করে প্লাস্টারের খণ্ডাংশ কুড়িয়ে নাও, একে একে জোড়া লাগিয়ে তাকে আবার গড়ে তুলতে থাকো। তোমার হাতের নিচে ধীরে ধীরে তার দেহের একাংশ আকার পেতে শুরু করে।"
  },
  Event_6866_Name = {
    Text = "জোড়াতালির দেহাবশেষ"
  },
  Event_6867_ChoiceDesc1 = {
    Text = "[Pick Up Key]"
  },
  Event_6867_Desc = {
    Text = "জং ধরা চাবির একগুচ্ছ। দরজা খুলতে ব্যবহার করা যেতে পারে।"
  },
  Event_6867_Name = {
    Text = "মরিচা ধরা চাবি"
  },
  Event_6868_ChoiceDesc1 = {
    Text = "[Silver Chip] 50% সম্ভাবনায় সোনার রেলিক 「(RelicConfig.Arg2)」 অর্জন করো, 50% সম্ভাবনায় 「(Skill.Arg3)」 বিকাশ করো।"
  },
  Event_6868_ChoiceDesc2 = {
    Text = "[Red Chip] 50% সম্ভাবনায় 75টি কালো চিহ্ন প্রাপ্ত হও, 50% সম্ভাবনায় 「(Skill.Arg3)」 উপসর্গ বিকশিত করো।"
  },
  Event_6868_ChoiceDesc3 = {
    Text = "[Let Them Choose] 50% সম্ভাবনায় অভিশপ্ত নিদর্শন 「(RelicConfig.Arg2)」 অর্জন করো, 50% সম্ভাবনায় 「(Skill.Arg3)」 বিকাশ করো।"
  },
  Event_6868_Desc = {
    Text = "এটা শুধু এক বাজি। তুমি হারবে না।\nজটিল নকশা খোদাই করা মুদ্রাটি আকাশে উঁচুতে ছুড়ে দেওয়া হয়, দ্রুত নেমে এসে তোমার তালুতে গরম হয়ে ওঠে।"
  },
  Event_6868_Name = {
    Text = "কুখ্যাত জুয়াড়ি"
  },
  Event_6869_ChoiceDesc1 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6869_Desc = {
    Text = "\"যারা ভাগ্যের অনুগ্রহে আস্থা রাখে, তারাই শেষে তার দ্বারাই উল্টে যায়।\"\nতুমি চলে যাওয়ার সিদ্ধান্ত নাও।"
  },
  Event_6869_Name = {
    Text = "কুখ্যাত জুয়াড়ি"
  },
  Event_6870_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6870_Desc = {
    Text = "\"কিপার।\"\nরামোনার কণ্ঠস্বর তোমাকে চেতনায় ফিরিয়ে আনে, কিন্তু পতনের অনুভূতিটি কিছুতেই মিলিয়ে যায় না।"
  },
  Event_6870_Name = {
    Text = "আয়নার ভেতর আয়না"
  },
  Event_6871_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6871_Desc = {
    Text = "শোনা যায়, সেরেনেড হলো প্রেম থেকে জন্ম নেওয়া গান।\nগ্রীষ্মের রাতে, প্রেয়সীর জানালার বাইরে, মানুষ একসঙ্গে এই কোমল সুর বাজায়।\nএগুলো হালকা আর উপরিতলীয়, রজার্সের রুচির সঙ্গে মেলে না, তবু সেগুলো তার রেপার্টরিতে রয়ে গেছে।\nকেন, তা হয়তো একমাত্র সেও জানে।"
  },
  Event_6871_Name = {
    Text = "বাজে রুচি"
  },
  Event_6872_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6872_Desc = {
    Text = "\nতুমি তাদের হুইসপার-এর প্রলোভনে পা দিতে অস্বীকার করো।\nতুমি বললে, \"মিথ্যাবাদী! তুমি তো পিচকালো মায়ারাত্রি অনন্ত প্রলয়ে বন্দি। তুমি কেমন করে সমগ্র মহাবিশ্ব পাড়ি দেবে?\"\nচোখগুলো হেসে উঠল। অসংখ্য হাসি মিলেমিশে এক বিশাল গর্জনে রূপ নিল, তোমার হৃদয় কেঁপে উঠল সেই শব্দে।\nচোখগুলো বলল, \"অন্য চোখ লুট করে। প্রতিটি চোখই এক একটি মহাবিশ্ব। যখন তোমার কাছে হাজারটি চোখ থাকবে, তখনই তুমি সত্যিকারের সময় ও মহাশূন্য ভ্রমণে পা বাড়াবে।\""
  },
  Event_6872_Name = {Text = "চোখ"},
  Event_6873_ChoiceDesc1 = {
    Text = "[Receive] 3টি সোনালি রেলিক থেকে 1টি অর্জন করো"
  },
  Event_6873_Desc = {
    Text = "হ্যাঁ, ওই ঘৃণ্য প্রতিবিম্বটিই তুমি।\nউথলে ওঠা বিদ্বেষ তোমার পায়ের কাছে কালো কাদার সঙ্গে মিশে গিয়ে পেঁচিয়ে ওঠে, নাচতে থাকে। তুমি আপত্তি না করলে, সেটি তোমার কাঁধেও চড়ে বসতে চায়।"
  },
  Event_6873_Name = {
    Text = "আয়নাতলে"
  },
  Event_6874_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6874_Desc = {
    Text = "অল্পক্ষণ পরেই, বন্ধনগুলো হঠাৎ ঢিলে হয়ে গেল, তুমি হোঁচট খেলো।\nতুমি ফিরে তাকালে নীরব সুতোদের দিকে—\"চলমান বালুকণা বিরক্ত কোরো না\", এই প্রবাদটি হয়তো ডোমেইনেও প্রযোজ্য।"
  },
  Event_6874_Name = {
    Text = "গভীরে আটকানো"
  },
  Event_6875_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6875_Desc = {
    Text = "নসিসের আগুন প্রজ্বলিত হয়, সব শৃঙ্খল পুড়িয়ে ছাই করে দেয়—\nঅন্তত, তুমি তাই বিশ্বাস করো।"
  },
  Event_6875_Name = {
    Text = "গভীরে আটকানো"
  },
  Event_6876_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6876_Desc = {
    Text = "সমস্ত শক্তি দিয়ে নিজেকে ছাড়িয়ে নাও। সুতো তোমার পোশাক ছিঁড়ে ফেলে, ত্বকে সূক্ষ্ম আঁচড় কেটে যায়।\nজাল তার মূল্য আদায় করেছে, তবু তুমি স্বস্তি অনুভব কর— তুমি মুক্ত।"
  },
  Event_6876_Name = {
    Text = "গভীরে আটকানো"
  },
  Event_6877_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6877_Desc = {
    Text = "ডিজলিউশন থেকে উৎপন্ন বিকৃত পত্রের বেশিরভাগ তথ্যই সাধারণত মুছে যায়。\nতুমি এর থেকে কোনো মূল্যবান তথ্য আহরণ করতে পারোনি, তাই চিঠিটিকে ছিঁড়ে টুকরো টুকরো করে বাতাসে বিক্ষিপ্ত করে দিলে।"
  },
  Event_6877_Name = {
    Text = "প্রজাপতি অধ্যায়"
  },
  Event_6878_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6878_Desc = {
    Text = "যদিও শব্দগুলো ইচ্ছে করে মুছে ফেলা হয়েছে, তবু তুমি স্পষ্টভাবেই সেই চিঠির মূল্য অনুভব করতে পারো।"
  },
  Event_6878_Name = {
    Text = "প্রজাপতি অধ্যায়"
  },
  Event_6879_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6879_Desc = {
    Text = "অতিরিক্ত সতর্কতাই নিরাপত্তা।\nরামোনা ঝুঁকে বসল, করিডরে ফিরে এল, এবং গোপনে পরের ঘরে ঢুকে পড়ল।"
  },
  Event_6879_Name = {
    Text = "জানালার প্রতিবিম্ব"
  },
  Event_6880_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6880_Desc = {
    Text = "তুমি এক মরিয়া চিৎকার ছেড়ে দাও।\nতোমার কণ্ঠে আকৃষ্ট হয়ে আসা কাকের ঝাঁক হঠাৎই মিলিয়ে যায়, রেখে যায় অন্ধকার দাগ।"
  },
  Event_6880_Name = {
    Text = "কাকদের গান"
  },
  Event_6881_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6881_Desc = {
    Text = "তুমি শরীর গুটিয়ে নাও, নিজেকে এক ক্ষুদ্র কালো বিন্দুতে সঙ্কুচিত করার চেষ্টা করো।\nহয়তো তারা তোমায় খেয়াল করবে না।\nকিছুক্ষণ পর, তুমি চোখ খোল।\nতুমি আলো দেখো।"
  },
  Event_6881_Name = {
    Text = "কাকদের গান"
  },
  Event_6882_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6882_Desc = {
    Text = "ছায়াটি আলতো করে আমার আঙুলের ফাঁক গলে সরে যায়, পেছনে রেখে যায় সোনালি ধুলোর এক সরু রেখা।"
  },
  Event_6882_Name = {
    Text = "রৌপ্য চাবির বাহক"
  },
  Event_6883_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6883_Desc = {
    Text = "তুমি অগোছালোভাবে চুল এলোমেলো করো, যখন উন্মত্ত কল্পনা আর বিভ্রান্তি মস্তিষ্কে ছুটে বেড়ায়, গভীরে লুকিয়ে থাকে কালো, পিচ্ছিল দলা।\nতুমি যদি সেটাকে চিরে দেখো, কী ধরনের উপহার পাবে?"
  },
  Event_6883_Name = {
    Text = "মস্তিষ্ক আলোড়ন"
  },
  Event_6884_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6884_Desc = {
    Text = "বর্ণিল তেলের দাগ ধীরে ধীরে তোমার দৃষ্টিক্ষেত্র ভরিয়ে তোলে, আবেগকে ঠেলে দেয় এক বিশৃঙ্খল উল্লাসে।"
  },
  Event_6884_Name = {
    Text = "মস্তিষ্ক আলোড়ন"
  },
  Event_6885_ChoiceDesc1 = {Text = "[Take It]"},
  Event_6885_Desc = {
    Text = "প্রায় পারদের মতো এক সিলভার পদার্থ, D-পঙ্ক থেকে পরিশোধিত, তীব্র মানসিক শক্তিতে পরিপূর্ণ, আচার অনুষ্ঠানে আরও অধিক জাগরণকারীকে সংযুক্ত করতে ব্যবহৃত হয় প্রায় পারদের মতো এক সিলভার পদার্থ, D-পঙ্ক থেকে পরিশোধিত, তীব্র মানসিক শক্তিতে পরিপূর্ণ, আচার অনুষ্ঠানে আরও অধিক জাগরণকারীকে সংযুক্ত করতে ব্যবহৃত হয়।"
  },
  Event_6885_Name = {
    Text = "সিলভার"
  },
  Event_6886_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6886_Desc = {
    Text = "হাসির ধারা বাক্স থেকে উথলে ওঠে, আর উষ্ণ আলোকচ্ছটা মিলিয়ে গেলে তুমি দেখতে পাও তিনটি কাঠি-মানুষ আঁকা একটি কার্ড: তুমি, রূপালি-কেশী র‍্যামোনা, আর সোনালি-কেশী ওজিয়ে। পাশে লেখা এক পঙ্‌ক্তি:\n「তোমাদের সবাইকে ধন্যবাদ!」"
  },
  Event_6886_Name = {
    Text = "সদিচ্ছার উপহার"
  },
  Event_6887_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6887_Desc = {
    Text = "তোমার দেহ প্রজাপতির ঝাঁক এড়িয়ে যায়, কিন্তু তারা তাদের লক্ষ্য হারায় না। তারা নিঃশব্দে তোমার স্যুটকেসে ঢুকে পড়ে, তোমার টাইপরাইটারের কালি লোভাতুরভাবে শুষে নেয়।"
  },
  Event_6887_Name = {
    Text = "বিভ্রান্তির উদ্গীরণ"
  },
  Event_6888_ChoiceDesc1 = {
    Text = "[ভুল নির্দেশ করো]1টি কমান্ড কার্ড বেছে অরিসন পান：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_6888_ChoiceDesc2 = {
    Text = "[Listen to the Performance] প্রতিটি জাগরণকারী, যার অ্যালিমাস 50 বা তার বেশি, তার জন্য 15টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_6888_ChoiceDesc3 = {
    Text = "[Leave] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_6888_Desc = {
    Text = "মোম ভাস্কর্য বালক পিয়ানোর সামনে বসে অনুশীলন করছে।\nতার শিক্ষক—সেও এক মোমের ভাস্কর্য—কাছে দাঁড়িয়ে তাকে দিকনির্দেশ দিচ্ছে।\n১৩৩, ৩৫৫, ২৪৪...\nভুল, প্রতিটি সুরই ভুল।"
  },
  Event_6888_Name = {
    Text = "পিয়ানো পাঠ"
  },
  Event_6889_ChoiceDesc1 = {
    Text = "[Give Up Resistance] একটি কমান্ড কার্ড ধ্বংস করো, এবং Arg1 কালো চিহ্ন গ্রহণ করো।"
  },
  Event_6889_ChoiceDesc2 = {
    Text = "[Pull Back Hands]"
  },
  Event_6889_Desc = {
    Text = "তুমি ভেতরের তাগিদকে আর প্রতিহত করতে পারো না।\nতোমার আঙুলগুলো অরণ্যে পথহারা বালকের মতো কীবোর্ডের ওপর ঘুরে বেড়ায়, বাজতে থাকে...\nধীরে ধীরে, টাইপরাইটার থেকে প্রজাপতির উদ্ভাসন ঘটে।\nএকটি, দুটি, তিনটি...\nতোমার মুখে, তোমার আঙুলে, প্রজাপতির ঝাঁক আতশবাজির মতো ঝলসে ওঠে, অন্ধকারে রত্নের মতো দীপ্তি ছড়ায়।\nএই টাইপরাইটারের কোনো বাস্তব প্রয়োগ নেই, কিন্তু সৌন্দর্য সৃষ্টি করার ক্ষেত্রে সে এক অতুলনীয় শিল্পী।"
  },
  Event_6889_Name = {
    Text = "অনুপ্রেরণার বিস্ফোরণ"
  },
  Event_6890_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6890_Desc = {
    Text = "\nতুমি কাগজটাকে গাঢ় লাল আলোয় তুলে ধরেছিলে, ভয়ে ভয়ে, যেন কোনো খুঁটিনাটি চোখ এড়িয়ে না যায়।\nএটা ছিল একটি স্বাস্থ্য প্রতিবেদন, আর পরীক্ষিত ব্যক্তি ছিল ম্যাসন।\n\"ওজন ৪০ কেজি, রক্তের অক্সিজেন মাত্রা স্বাভাবিক, সমসংস্থান হার ৩০%, অনুরণন মান...\"\nতুমি পড়তে থাকতে চেয়েছিলে, কিন্তু লেখা ধীরে ধীরে মিলিয়ে যেতে লাগল।\nএতটাই পরিষ্কার, যেন কিছুই কোনোদিন ঘটেনি।"
  },
  Event_6890_Name = {
    Text = "টাইপরাইটার"
  },
  Event_6891_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6891_Desc = {
    Text = "হ্যাঁ, তুমি পালাচ্ছ না; তুমি তাড়া করছ এক নির্দিষ্ট লক্ষ্যকে—ভেজা, সরু, বরফে ঢাকা গলিপথে ছুটে চলা সেই 「নরককুকুর」-কে। তুমি এটা ভুলবে না, যেমন ভুলবে না সেই মুখটাও, যে তোমাকে টেনে তুলেছিল টুংগুস্কার ধ্বংসস্তূপ থেকে সেদিন… কে ছিল সে আবার?"
  },
  Event_6891_Name = {
    Text = "দৌড়াও"
  },
  Event_6892_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6892_Desc = {
    Text = "এই সম্পূর্ণ বিচ্ছিন্ন স্থানে, তুমি কেবল নিজের ওপরই নির্ভর করতে পারো।"
  },
  Event_6892_Name = {
    Text = "দুঃস্বপ্ন পথিক"
  },
  Event_6893_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6893_Desc = {
    Text = "সঙ্কট আর ঝুঁকি পাশাপাশি সহাবস্থান করে। তুমি ভারী তালায় হাত দিতেই ক্ষয়কারী পিচ্ছিল পদার্থ তোমার তালু পুড়িয়ে দেয়। আশা করি দরজার ওপারের অবশেষটি এই যন্ত্রণার যোগ্য।"
  },
  Event_6893_Name = {
    Text = "লৌহ দ্বারের পশ্চাতে"
  },
  Event_6894_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6894_Desc = {
    Text = "অজানা জগৎগুলোতে বেপরোয়া ঘুরে বেড়াতে বেড়াতে, তোমার ভঙ্গুর মানসিক স্থিতি এখনো এমন পর্যায়ে অবনতি পায়নি যে বোধবুদ্ধি হারাবে।\nঅজানার বিভীষিকা এমন এক বিষয়, যা তুমি গভীরভাবে বোঝো।"
  },
  Event_6894_Name = {
    Text = "দুঃস্বপ্ন পথিক"
  },
  Event_6895_ChoiceDesc1 = {
    Text = "[Loud Shout] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_6895_ChoiceDesc2 = {
    Text = "[Embrace Silence] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 এবং 「(Skill.Arg3)」 বিকশিত করো।"
  },
  Event_6895_ChoiceDesc3 = {
    Text = "[Surface] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6895_Desc = {
    Text = "তুমি নীরবতা শোনো।\nবর্ধিত এক নীরবতা, ঢেউয়ের শব্দের মতো, সমগ্র স্থান ভরে তোলে।\n\nতুমি মাথা তুলে তাকাও, নক্ষত্রের দিকে চেয়ে থাকা এক ক্ষুদ্র বিন্দুর মতো।"
  },
  Event_6895_Name = {
    Text = "লিথির প্রবাহ"
  },
  Event_6896_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6896_Desc = {
    Text = "তুমি কান খাড়া করো, শব্দের উৎস খুঁজতে থাকো, দুষ্টুমিকারীটাকে ধরার চেষ্টা করো。\nকিন্তু সবকিছুই যেন ইচ্ছাকৃত এক প্রহসন। ঠিক যখন ভাবো, তাকে কোণঠাসা করেছ, বুঝতে পারো তুমি আবার সেই শুরুর জায়গাতেই ফিরে এসেছ。\nহতাশ হয়ে তুমি ইটের দেয়ালে লাথি মারো; একটি ইট সরে গিয়ে ভেতরে লুকিয়ে থাকা ঝকঝকে এক রহস্য উন্মোচন করে।"
  },
  Event_6896_Name = {
    Text = "হারানো প্রতিধ্বনি"
  },
  Event_6897_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6897_Desc = {
    Text = "এটা নিশ্চয়ই প্লেব্যাকের সমস্যা, নিশ্চয়ই তাই।\nসন্দেহ নিয়ে তুমি সূচটা আবার পেছনে ঘুরিয়ে দাও, সহ্য করো সেই ভয়াবহ প্রথম অংশ, কিন্তু পরিচিত টোকা দেওয়ার শব্দ আর শোনা যায় না।\nতোমার পেছনে, শূন্যতার ভেতর, মাটিতে পড়ে থাকা এক ছোট্ট ছায়া নিঃশব্দে সরে গিয়ে মিলিয়ে যায়।"
  },
  Event_6897_Name = {
    Text = "হারানো প্রতিধ্বনি"
  },
  Event_6898_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6898_Desc = {
    Text = "তোমার চারপাশে কেউ নেই। টোকা দেওয়ার সেই রহস্য নিশ্চয়ই লুকিয়ে আছে ফোনোগ্রাফের ভেতরের কোনো যান্ত্রিক ব্যবস্থায়।\nনিজের বিচার-বুদ্ধিতে ভরসা রেখে, তুমি পুরোনো ফোনোগ্রাফটি খুলে ফেলো।\nক্ষয়ধরা ধাতব অংশ আর মোটা ধুলোর স্তর ছাড়া তুমি আর কিছুই পাও না।\nশুধু একটুখানি ক্ষীণ খিলখিল হাসি কুয়াশার ভেতর গলে যায়, স্বপ্নলোকের মতোই হালকা।"
  },
  Event_6898_Name = {
    Text = "হারানো প্রতিধ্বনি"
  },
  Event_6899_ChoiceDesc1 = {
    Text = "[Fool's White Matter] Arg1 HP পুনরুদ্ধার করো"
  },
  Event_6899_ChoiceDesc2 = {
    Text = "[Madman's Heart] একটি এলোমেলো কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_6899_ChoiceDesc3 = {
    Text = "[Refuse to Eat] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6899_Desc = {
    Text = "「দ্য ফুল-এর সাদা মস্তিষ্কদ্রব্য ফুটন্ত মাছের স্যুপের মতোই সুস্বাদু, আর উন্মাদ মানুষের হৃদয় বেক হয়ে উঠেছে গরম, রক্তাক্ত স্কোনে।」\nছায়া বিদ্বেষী হাসি হাসল, তোমার সামনে অজানা জীব দিয়ে তৈরি এক পদ এগিয়ে ধরল।\nতুমি গভীর শ্বাস নিলে; প্রলয়ংকরী সুগন্ধ জোর করে তোমার নাসারন্ধ্রে ঢুকে পড়ল। সম্পূর্ণ অপমানিত তোমার লালাগ্রন্থি সবার আগে আত্মসমর্পণ করল, আর তোমার পাকস্থলী যন্ত্রণায় মোচড়াতে মোচড়াতে কামনার এক গোঙানিময় আর্তনাদ ছেড়ে দিল।"
  },
  Event_6899_Name = {
    Text = "দেহের ভোজ"
  },
  Event_6900_ChoiceDesc1 = {
    Text = "[Touch Wind Chime] একটি এলোমেলো কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg2)」 উৎকীর্ণ করো, কিন্তু 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_6900_ChoiceDesc2 = {
    Text = "[Observe Wind Chime] একটি এলোমেলো কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg2)」 উৎকীর্ণ করো, কিন্তু 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_6900_ChoiceDesc3 = {
    Text = "[Do Nothing] একটি এলোমেলো কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_6900_Desc = {
    Text = "টিং টিং, টিং টিং...\nএটি একটি মরিচাধরা বাতাসি ঘণ্টা, যার কদর্য সুরগুলো ফাঁকফোকর পেরিয়ে হোঁচট খেতে খেতে ভেসে বেড়ায়।"
  },
  Event_6900_Name = {
    Text = "মরিচা ধরা বায়ুঘণ্টা"
  },
  Event_6901_ChoiceDesc1 = {
    Text = "[Wait and See] বেঁচে থাকার চেষ্টা করো"
  },
  Event_6901_ChoiceDesc2 = {
    Text = "[Swing Weapon] ভেদ করে যাওয়ার চেষ্টা"
  },
  Event_6901_ChoiceDesc3 = {
    Text = "[Hold a Hand] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6901_Desc = {
    Text = "হঠাৎ তোমার পায়ের নিচে এক কালো জলাভূমি গড়ে ওঠে, সেখান থেকে অসংখ্য হাত বেরিয়ে আসে।\nতাদের রং, গঠন আর উপাদান নানান রকম—ময়ূরনীল, আঁশে ঢাকা, এমনকি চোখ-ওয়ালা—যেন অগণিত মাত্রা আর শূন্যতা পেরিয়ে এসে, পরের দুর্ভাগা আত্মাটিকে তাদের পরিবারে টেনে নিতে উদ্যত।\nতুমি সিদ্ধান্ত নাও—"
  },
  Event_6901_Name = {
    Text = "বিষণ্ণ জলাভূমি"
  },
  Event_6902_ChoiceDesc1 = {
    Text = "[Hold it] 3টি কমান্ড কার্ডের মধ্যে 1টি অনুলিপি করো"
  },
  Event_6902_ChoiceDesc2 = {
    Text = "[একটু নাড়াও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
