  Event_6902_Desc = {
    Text = "টিং টিং, টিং টিং...\nএটি একটি মরিচাধরা বাতাসি ঘণ্টা, যার কদর্য সুরগুলো ফাঁকফোকর পেরিয়ে হোঁচট খেতে খেতে ভেসে বেড়ায়।"
  },
  Event_6902_Name = {
    Text = "ছোট্ট বায়ুঘণ্টা"
  },
  Event_6903_ChoiceDesc1 = {
    Text = "[Counter Them] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 3টি উপসর্গের মধ্যে 1টি বিকশিত করো।"
  },
  Event_6903_ChoiceDesc2 = {
    Text = "[Follow Them] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_6903_ChoiceDesc3 = {
    Text = "[Suggest New Idea] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6903_Desc = {
    Text = "\n「দয়া করে আমাদের থেকে দূরত্ব বজায় রাখুন।」\nএক ঝাঁক ইঁদুর তোমাকে ঘিরে ধরল, কিন্তু অন্তত পাঁচ ফুট দূরত্ব বজায় রেখে।\n「আমরা বংশবৃদ্ধির জন্য লড়ি, আমরা বেঁচে থাকি; আমরা খাবারে খুঁতখুঁতে নই—এই কারণেই আমরা নিয়ে আসি রোগ, উদ্বেগ আর মানবতার দীপ্তির ওপর নেমে আসা যন্ত্রণা।」\n「আমাদের মানুষের খুব কাছে যাওয়া উচিত নয়; এটি তোমাদের থাকার জায়গা নয়।」\nইঁদুরগুলোর প্রহরা ঢিলেঢালা করতে, তুমি সিদ্ধান্ত নিলে—"
  },
  Event_6903_Name = {
    Text = "প্লেগ"
  },
  Event_6904_ChoiceDesc1 = {
    Text = "[Descend Further] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_6904_ChoiceDesc2 = {
    Text = "[Pull Away] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6904_Desc = {
    Text = "「তুমি」 তোমাকে আমন্ত্রণ জানাচ্ছে।\nসর্পিলের গভীরে, অতীত ও ভবিষ্যতের 「তুমি」 তোমাকে ভিন্ন মাত্রা থেকে একটি 「উপহার」 পাঠিয়েছে।"
  },
  Event_6904_Name = {
    Text = "অতল গহ্বর"
  },
  Event_6905_ChoiceDesc1 = {
    Text = "[Pin Down the Crow] 40টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_6905_ChoiceDesc2 = {
    Text = "[Ignore It] 25টি কালো চিহ্ন সংগ্রহ করে চলে যাও।"
  },
  Event_6905_Desc = {
    Text = "একাকী কাকটি কর্কশ স্বরে ডাকে, একে একে নিজের কালো পালক ছিঁড়ে ফেলে।\nব্যথায় কাঁপতে কাঁপতে, তীক্ষ্ণ চিৎকার তোলে, তবু ক্রমশ উন্মত্ত হয়ে ওঠা হাত থামাতে পারে না।\n\"কা—কা—\"\nতার চোখ থেকে নীল অশ্রু ও কালো পিচ্ছিল তরল মিশে গড়িয়ে পড়ে, যার সাক্ষী কেবল তুমি।"
  },
  Event_6905_Name = {
    Text = "গলিত অশ্রু"
  },
  Event_6906_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6906_Desc = {
    Text = "লাল, উন্মত্ত, সজীব, আর দৃষ্টিনন্দন। এমন এক সৌন্দর্যকে আমি চিনি, আর সময় হলে তুমি তার সাথেও দেখা পাবে।\nতাহলে, তোমার পরের পছন্দটি কী?"
  },
  Event_6906_Name = {
    Text = "প্রদর্শনীর সময়"
  },
  Event_6907_ChoiceDesc1 = {
    Text = "[Loud Cheer]"
  },
  Event_6907_ChoiceDesc2 = {Text = "[Drowsy]"},
  Event_6907_Desc = {
    Text = "তুমি এক দীর্ঘ স্বপ্ন দেখেছিলে।\nস্বপ্নে, তুমি ছিলে দর্শকাসনে, মঞ্চে এক ছেলেকে গান গাইতে দেখছিলে।\n「বৃদ্ধ চার্লির ছিল এক অতি স্নেহের ট্যাবি বিড়াল।\nসে যখন হারিয়ে গেল, সে খুঁজল সর্বত্র।」\n.....\nফাঁপা, শুষ্ক কণ্ঠস্বরটি যান্ত্রিকভাবে, অনন্তকাল ধরে পুনরাবৃত্তি হতে থাকল।"
  },
  Event_6907_Name = {
    Text = "অন্তিম IV"
  },
  Event_6908_ChoiceDesc1 = {
    Text = "[Unravel the Upper Branch]"
  },
  Event_6908_ChoiceDesc2 = {
    Text = "[Unravel the Lower Branch]"
  },
  Event_6908_Desc = {
    Text = "ডোমেইনে অবশিষ্ট জ্ঞান একে অপরের সাথে জড়িয়ে, গিঁট বেঁধে এক অস্থির বলক্ষেত্র গঠন করেছে।\nহয়তো, তুমি এই জ্ঞানকে খুলে আলগা করে নিজের জন্য সামনে এগোনোর এক পথ গড়ে নিতে পারো।"
  },
  Event_6908_Name = {
    Text = "জটিল পথ"
  },
  Event_6909_ChoiceDesc1 = {
    Text = "[Leave] 2 জন জাগরণকারীকে জাগরণ ঘটাও"
  },
  Event_6909_Desc = {
    Text = "\nতুমি উঠে দাঁড়ালে এবং দরজার দিকে ছুটে গেলে।\n「তুমি কাপড়ের আচ্ছাদনটা সরিয়ে নিলে...\nএকটা গোপন, তুমি একটা গোপন আবিষ্কার করলে...」\nগর্জন সঞ্চিত হয়ে এক বেসুরো সাগরে পরিণত হলো, আর ভয়াবহ অনুরণনে মেঝে প্রচণ্ড কেঁপে উঠল।\nতুমি পেছনে তাকাতে সাহস করলে না, যত দ্রুত পারলে সেখান থেকে পালিয়ে গেলে।"
  },
  Event_6909_Name = {
    Text = "অন্তিম V"
  },
  Event_6910_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6910_Desc = {
    Text = "আপনি প্রতিরোধ করেন না, তবে প্রশ্রয়ও দেন না।"
  },
  Event_6910_Name = {
    Text = "করোটির ক্ষত"
  },
  Event_6911_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6911_Desc = {
    Text = "তুমি প্রতিরোধ থামিয়ে দিলে, ময়লাকে তোমার দেহ আর আত্মা গ্রাস করতে দিলে। দীর্ঘ তন্দ্রার পর, সিলভার আলো এসে পড়ল তোমার জোড়া করা হাতের ভাঁজে।"
  },
  Event_6911_Name = {
    Text = "করোটির ক্ষত"
  },
  Event_6912_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6912_Desc = {
    Text = "তুমি যত বেশি ছটফট করো, কলুষ তত গভীরে তোমার মস্তিষ্কে ডুবে যায়। পাপের ভারে নুয়ে পড়া মস্তিষ্কের অতল গহ্বরে লুকিয়ে আছে এক দুর্বোধ্য উপহার।"
  },
  Event_6912_Name = {
    Text = "করোটির ক্ষত"
  },
  Event_6913_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6913_Desc = {
    Text = "জালটি ভেঙে পড়তেই, তোমার মস্তিষ্কে কিছু ঝলসে ওঠে—মনে হয় যেন কয়েকজন বালকেরা হাসিমুখে তাকিয়ে আছে।"
  },
  Event_6913_Name = {
    Text = "ভেগাস নেটওয়ার্ক"
  },
  Event_6914_ChoiceDesc1 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6914_Desc = {
    Text = "বিড়ালটি তৃপ্তির ভঙ্গিতে মাথা নাড়ল, তারপর ছায়ার ভেতর মিলিয়ে গেল, পেছনে রেখে গেল কয়েকটি কালো বৃত্তাকার বস্তু।"
  },
  Event_6914_Name = {
    Text = "বিচরণকারী বাসিন্দা"
  },
  Event_6915_ChoiceDesc1 = {
    Text = "[Read the Letter] একটি কমান্ড কার্ড ধ্বংস করো, এবং Arg1টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_6915_ChoiceDesc2 = {
    Text = "[Close the Box]"
  },
  Event_6915_Desc = {
    Text = "ডানা ঝাপটানো অক্ষর আকাশ ভরে তোলে, নীরব তাগিদের মতো।"
  },
  Event_6915_Name = {
    Text = "অনাকাঙ্ক্ষিত পত্র"
  },
  Event_6916_ChoiceDesc1 = {
    Text = "[Enter] কুয়াশা চিরে এগিয়ে গিয়ে অন্য প্রান্তে নাগাল পান।"
  },
  Event_6916_ChoiceDesc2 = {Text = "[Leave]"},
  Event_6916_Desc = {
    Text = "সামনের পথে একটি লুকানো সুড়ঙ্গ দেখা দেয়, কালো কুয়াশায় ভরা। তার গন্তব্য অজানা জীব।"
  },
  Event_6916_Name = {
    Text = "সুড়ঙ্গ"
  },
  Event_6917_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6917_Desc = {
    Text = "তুমি তার যন্ত্রণা শেষ করার সিদ্ধান্ত নাও, হাত বাড়িয়ে তার নরম দেহটাকে আঁকড়ে ধরো, চেপে ধরো... আরও চেপে ধরো...\nতোমার তালুর ভেতর সে মরিয়া হয়ে ছটফট করে, শেষে উষ্ণ তরলের এক ছিটায় ফেটে যায়।"
  },
  Event_6917_Name = {
    Text = "গলিত অশ্রু"
  },
  Event_6918_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6918_Desc = {
    Text = "চিন্তা কোরো না, এগুলো কেবল মাত্রার ভেতরে অন্যদের স্মৃতিচারণের খণ্ডাংশ। তোমার একটি ছায়া আছে। কিন্তু, ছায়ার ভেতরের সেই মানুষটি কি সত্যিই এখনো তুমি নিজেই?"
  },
  Event_6918_Name = {
    Text = "স্মৃতি খণ্ডাংশ: বিয়ার"
  },
  Event_6919_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6919_Desc = {
    Text = "তুমি জোর করে কাকের ঠোঁটকে নিজের পালক উপড়ে ফেলা থেকে সরিয়ে দাও, কিন্তু তা নির্দয়ভাবে আবার মোচড় খেয়ে ফিরে আসে, তার শক্তিতে তোমার হাড়ে কড়মড় শব্দ ওঠে।\nনিজের সমস্ত শক্তি ঢেলে তুমি কাকের দেহকে চেপে ধরো, তার উন্মত্ত আত্ম-ক্ষতিকে থামিয়ে দাও, আর মুখ লাল হয়ে ওঠে প্রচেষ্টায়।\nঠিক যখন তুমি স্বস্তির নিঃশ্বাস ফেলছ, অর্ধেক টাক হয়ে যাওয়া কাকের গলা হঠাৎ তীব্রভাবে পেছনে বেঁকে যায়, তার দেহ ঢিলে হয়ে তোমার হাতের কার্ডের মধ্যে কালো কাদার পুকুরে রূপান্তরিত হয়।"
  },
  Event_6919_Name = {
    Text = "গলিত অশ্রু"
  },
  Event_6920_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6920_Desc = {
    Text = "তুমি নির্দয়ভাবে সেই মরিয়া রিংগুলো উপেক্ষা করলে।\nপরের মুহূর্তেই যদি তোমাকে আদিম জগতে ছিটকে ফেলা হয়, যদি তুমি আর তোমার মহা-মিশন একসাথে সমাধিস্থও হয়ে যাও—তবু।\nযে আহ্বানে সাড়া দেওয়া উচিত নয়, তাকে কখনোই সাড়া দেওয়া যায় না।\nএই সরল সত্য তুমি খুব ভালো করেই জানো।"
  },
  Event_6920_Name = {
    Text = "কল গৃহীত"
  },
  Event_6921_ChoiceDesc1 = {
    Text = "[Lower Gaze] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6921_ChoiceDesc2 = {
    Text = "[I Must Find It] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_6921_Desc = {
    Text = "\nতুমি ছায়াটিকে তাড়া করতে করতে হঠাৎই পা রাখলে অগভীর এক জলাশয়ে। বর্ণহীন তরলটি তোমার জুতো ভিজিয়ে হাড় পর্যন্ত শীতলতা নামিয়ে আনল।\nজলের ভেতর থেকে একটি কণ্ঠ ভেসে এল, “তুমি সত্যিই জানতে চাইবে না।”"
  },
  Event_6921_Name = {
    Text = "যা তোমার খোঁজা উচিত নয়"
  },
  Event_6922_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6922_Desc = {
    Text = "একটি নিরাপদ নির্বাচন।"
  },
  Event_6922_Name = {
    Text = "খড়ের গাদার আড়ালে"
  },
  Event_6923_ChoiceDesc1 = {
    Text = "[Chase the Crows] Arg1টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_6923_ChoiceDesc2 = {
    Text = "[Disregard] 25টি কালো চিহ্ন গ্রহণ করে চলে যাও।"
  },
  Event_6923_Desc = {
    Text = "আশ্রয়স্থলের ঘরে কাক থাকবে কী করে?\nতবু তুমি স্পষ্টই তাদের কাকলি শুনতে পাও। অদৃশ্য এক শক্তি ফাঁপা পাখির চোখ দিয়ে ছায়া থেকে তোমাকে পর্যবেক্ষণ করছে। এই কালো প্রাণীগুলো রাস্তার বাতির মাথায় বসে গলা পেঁচিয়ে, বিদ্বেষভরা দৃষ্টিতে তোমার দিকে চেয়ে থাকে। তাদের গাদাগাদি মাথাগুলো যেন একটিমাত্র দেহ ভাগ করে নিয়েছে, যা D-পঙ্কের ভেতর ডুবে আছে।"
  },
  Event_6923_Name = {
    Text = "ল্যান্টার্ন-ক্রো"
  },
  Event_6924_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6924_Desc = {
    Text = "অপবিত্রতাকে ভয় কোরো না; এর থেকে তুমি যত হারাও, তার চেয়ে বেশি অর্জন করো।"
  },
  Event_6924_Name = {
    Text = "খড়ের গাদার আড়ালে"
  },
  Event_6925_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6925_Desc = {
    Text = "নসিসের ঝড় তুলুকে ঘিরে রেখেছে। তুমি তার সঙ্গে চোখাচোখি করে নাও, এবং একে একে অন্ধকারের ভেতর পা বাড়াও।"
  },
  Event_6925_Name = {
    Text = "দূতের অঙ্গীকার"
  },
  Event_6926_ChoiceDesc1 = {
    Text = "[Enter] কুয়াশা চিরে এগিয়ে গিয়ে অন্য প্রান্তে নাগাল পান।"
  },
  Event_6926_ChoiceDesc2 = {Text = "[Leave]"},
  Event_6926_Desc = {
    Text = "তুমি অন্ধকারে তলিয়ে যাও。\nদৃষ্টির কিনারায়, চাবির ছিদ্রের মতো এক ফাঁক দিয়ে এক টুকরো আলো ভেতরে ঢোকে。\nরৌপ্য চাবি ক্ষীণ আলো ছড়ায়, তোমাকে গোপন প্যাসেজের দিকে পথ দেখায়।"
  },
  Event_6926_Name = {
    Text = "একমুখী গোপন পথ"
  },
  Event_6927_ChoiceDesc1 = {
    Text = "[Infect \"(Skill.Arg1)\", acquire Relic: \"(RelicConfig.Arg2)\"]"
  },
  Event_6927_ChoiceDesc2 = {
    Text = "[Choose 1 out of 3 Command Cards to gain the Orison: \"(EnchantConfig.Arg1)\"]"
  },
  Event_6927_Desc = {
    Text = "ইভেন্ট 203 (উন্নয়নাধীন), চূড়ান্ত প্রভাব নয়"
  },
  Event_6927_Name = {
    Text = "ইভেন্ট 203 (উন্নয়নাধীন)"
  },
  Event_6928_ChoiceDesc1 = {
    Text = "[Patch Her Up] একটি কমান্ড কার্ড ধ্বংস করো, এবং রেলিক 「(RelicConfig.Arg1)」 অর্জন করো।"
  },
  Event_6928_ChoiceDesc2 = {
    Text = "[Touch] একটি স্ট্রাইক বা ডিফেন্স কার্ড ধ্বংস করো, এবং 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_6928_ChoiceDesc3 = {
    Text = "[Disgust] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6928_Desc = {
    Text = "“আমার অবশিষ্টাংশ কি তোমার পছন্দ হয়েছে? সম্ভব হলে, তুমি কি আমার দেহটা আবার জোড়া লাগিয়ে দিতে পারবে?”\nঅর্ধেক দেহওয়ালা প্লাস্টারের মূর্তিটির ঠোঁট নড়ল, আর তার শক্ত ও শীতল হওয়ার কথা যে ঠোঁটের, সেখান থেকেই রেশমের মতো কোমল এক কণ্ঠস্বর ভেসে এল।"
  },
  Event_6928_Name = {
    Text = "জোড়াতালির দেহাবশেষ"
  },
  Event_6929_ChoiceDesc1 = {
    Text = "[Discard Envelope] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_6929_ChoiceDesc2 = {
    Text = "[Tucked in the Chest] রেলিক 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_6929_Desc = {
    Text = "এটি একটি সাহায্যের চিঠি। লেখক শান্ত থাকার চেষ্টা করেছে, কিন্তু মাঝেমধ্যে কাঁপা হাতের লেখা তার গহিন ভয়ের পরিচয় দেয়।\n“এটা আমার কল্পনার সম্পূর্ণ বাইরে। কেউ যদি আমাকে বলে আমি গভীরভাবে অভিশপ্ত, আমি শপথ করে বলব, আমি তা বিশ্বাস করি।”\n“কেউ কেউ বলে আমি পাগল। তারা অর্ধেক ঠিক। আমি পাগলামির কিনারায় দুলছি।”\n“কিন্তু আমি সত্যিই ওটাকে দেখেছি! ওটা রূপ বদলাচ্ছে আর মিলিয়ে যাচ্ছে, বিস্তারমান কালো পিচ্ছিল বস্তুটা আমাকে পুরো ঢেকে ফেলতে চাইছে!”\n“আমি দৌড়েছি! যত জোরে পারি দৌড়েছি, তবু দৃষ্টি এক মুহূর্তের জন্যও আমাকে ছাড়েনি। আমার মনে হচ্ছে ওটা আমাকে খুঁজে নেবে! সেই ঘৃণ্য কালো কাদামাটি আবার আমার করোটিতে ঢুকে পড়বে। যে-ই এই চিঠি পাবে, অনুগ্রহ করে, আমাকে বাঁচান—”"
  },
  Event_6929_Name = {
    Text = "একটি সাহায্যের চিঠি"
  },
  Event_6930_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6930_Desc = {
    Text = "\"শান্ত হও,\" রামোনা আপনার মাথায় টোকা দেয়, \"এগুলো শুধু অতীতের খণ্ডাংশ। কে যে এগুলো এই মাত্রিক পথের ভেতর ফেলে গেছে, জানি না।\"\nনিশ্চয়ই, বাতাসে এক নস্টালজিক গন্ধ ভাসছে।"
  },
  Event_6930_Name = {
    Text = "জরুরি বার্তা"
  },
  Event_6931_ChoiceDesc1 = {
