    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6932_Desc = {
    Text = "ইভেন্ট 204 (উন্নয়নাধীন), চূড়ান্ত প্রভাব নয়"
  },
  Event_6932_Name = {
    Text = "ইভেন্ট 204 (উন্নয়নাধীন)"
  },
  Event_6933_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6933_Desc = {
    Text = "একাকী চাঁদ ঝুলে আছে আকাশের অনেক উঁচুতে, তবু তুমি স্পষ্ট শুনতে পাও তার প্রার্থনা—এক অদ্ভুত মন্ত্রোচ্চারণ, যা পচনের হুইসপারের মতো শোনায়।\nপ্রার্থনা থেমে যায়, আর তুমি যখন সরে যেতে উদ্যত, তখনই তোমার পেছনে আবির্ভূত হয় এক সাদা প্রেতছায়া।\n“যারা ভাগ্য আর প্রার্থনার সীমা লঙ্ঘন করে, তাদের কাছে আশীর্বাদ ও প্রতিশোধ—দু’টিই প্রতিশ্রুতির মতোই এসে পৌঁছায়।”"
  },
  Event_6933_Name = {
    Text = "মুন সিলভার শার্ড"
  },
  Event_6934_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6934_Desc = {
    Text = "পেছন থেকে ভাঙচুরের খাস্তা শব্দ ভেসে আসে। তুমি এক মুহূর্ত থেমে, চিন্তায় ডুবে যাও, তারপর মুখ ফিরিয়ে নাও।"
  },
  Event_6934_Name = {
    Text = "মুন সিলভার শার্ড"
  },
  Event_6935_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6935_Desc = {
    Text = "এক মুঠো চাঁদের আলো, তালুতে জড়ো করে পাথরের ফলকের ওপর ছিটিয়ে দেওয়া হলো।\nকারও দেহ ঘন কাদার নিচে পুঁতে রাখা হয়েছিল, আর দর্শকেরা বলেছিল, ওটা স্বাভাবিক মৃত্যু, তারা নাকি মাটির নিচে শান্তিতে বিশ্রাম নেবে।\nকিন্তু পোঁতা কাদা ফুঁসে উঠল, আর চিৎকারের মাঝখানে, এক অবশ চাঁদ হামাগুড়ি দিয়ে বেরিয়ে এলো।"
  },
  Event_6935_Name = {
    Text = "মুন সিলভার শার্ড"
  },
  Event_6936_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6936_Desc = {
    Text = "শুধু এক জীবন্ত সত্তা, বাঁচার জন্য লড়ছে, বিশ্রামের জন্য ভাসমান কাঠের টুকরো খুঁজছে...\nতুমি দীর্ঘশ্বাস ফেলো, প্রজাপতির লেজ থেকে কালো পিচ্ছিল তরলটিকে গড়িয়ে পড়তে দাও।"
  },
  Event_6936_Name = {
    Text = "যা থাকা উচিত নয়"
  },
  Event_6937_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6937_Desc = {
    Text = "এটা এক পূর্বপরিকল্পিত ফাঁদ, আর তুমি তার বিপদের কথা ভালো করেই জানো।\nগয়নার তুলনায়, তুমি নিজেই— স্পষ্টতই আরও মূল্যবান রত্ন।"
  },
  Event_6937_Name = {
    Text = "উলটপালট দানবীয় থাবা"
  },
  Event_6938_ChoiceDesc1 = {
    Text = "[Insert your Silver Key]"
  },
  Event_6938_Desc = {
    Text = "অতিরিক্ত স্যাচুরেটেড D-পঙ্কের ভেতরে যেন কিছু আছে... রৌপ্য চাবি ব্যবহার করে সেটিকে তোমার নিজস্ব শক্তিতে রূপান্তর করো।"
  },
  Event_6938_Name = {
    Text = "নিষ্কাশন বিন্দু"
  },
  Event_6939_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6939_Desc = {
    Text = "তুমি অনুরোধটি গ্রহণ করেছিলে, কিন্তু একটুখানি সমস্যায় পড়লে।\n\"ওই মোমের ভাস্কর্যটা দেখতে কেমন?\"\n\"ওটা আমার বক্ষভাস্কর্য, অবশ্যই আমার মতোই দেখতে।\"\n\"কিন্তু...\"\n\"তোমার মুখ তো বহু আগেই সম্পূর্ণ পচে গিয়েছে। তুমি কি তা জানো না?\""
  },
  Event_6939_Name = {
    Text = "আমার অপর অর্ধেক"
  },
  Event_6940_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6940_Desc = {
    Text = "তুমি সঙ্গীর হাতের কার্ড শক্ত করে চেপে ধরো। রামোনা বিস্মিত দৃষ্টিতে একবার তাকায়, কিন্তু শেষ পর্যন্ত তোমার এই অশিষ্টতাকেও মেনে নেয়।"
  },
  Event_6940_Name = {
    Text = "স্বপ্নলোক প্রার্থনা"
  },
  Event_6941_ChoiceDesc1 = {
    Text = "[Ask Who It Is] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_6941_ChoiceDesc2 = {
    Text = "[Stare Back] এক জাগরণকারীকে জাগরণ ঘটাও, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত হবে।"
  },
  Event_6941_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6941_Desc = {
    Text = "তীব্র নজরে পড়ে থাকার অনুভূতিতে তুমি হঠাৎই গতিপথের নিয়ম থামিয়ে দাও।\n「কে ওখানে?」 ঘন কুয়াশার ভেতর তুমি চারপাশে তাকাও, 「জেনকিন, তুমি কি?」\nকুয়াশা ঘন, আর আঙিনার গভীর থেকে ভেসে আসে(ক্ষয়িত)দের ফেইন্ট আর্তনাদ। তুমি কিছুই খুঁজে পাও না, আর ঘুরে দাঁড়াতেই প্রায় ধাক্কা খেতে বসো— বাতাসে ঝুলে থাকা এক বিশাল চোখের সঙ্গে।"
  },
  Event_6941_Name = {
    Text = "অন্ধ দৃষ্টি"
  },
  Event_6942_ChoiceDesc1 = {
    Text = "[Avoid Coin] একটি এলোমেলো কমান্ড কার্ডে 「(EnchantConfig.Arg1)」 প্রার্থনাগাথা খোদাই করো।"
  },
  Event_6942_ChoiceDesc2 = {
    Text = "[Touch the Coin] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত হবে।"
  },
  Event_6942_Desc = {
    Text = "তুমি কালো কাদার ভেতর গেঁথে থাকা একটি প্রাচীন মুদ্রা খুঁজে পেলে।\nএক পাশে নীল আর লাল শিরার সূক্ষ্ম খোদাই, আর অন্য পাশে নিখুঁত সাদা এক প্রতিকৃতির সূক্ষ্ম উঁচু খোদাই—নিষ্কলুষ এক ডাচেস মৃদু হাসছেন, তার দৃষ্টি এক মুহূর্তের জন্য তোমার ফ্যাকাসে চোখের সঙ্গে মেলে, তারপরই অস্থিরভাবে চারদিকে ছুটে বেড়াতে শুরু করে।"
  },
  Event_6942_Name = {
    Text = "দ্বিমুখী প্রাচীন মুদ্রা"
  },
  Event_6943_ChoiceDesc1 = {
    Text = "[Turn Around] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6943_ChoiceDesc2 = {
    Text = "[Keep Going] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_6943_Desc = {
    Text = "আবারও শোনা গেল, সেই অদ্ভুত পায়ের শব্দ।\nওটা তোমাকে অনুসরণ করে স্টুডিও থেকে কিউরেটরের কক্ষে, তারপর কিউরেটরের কক্ষ থেকে বেসমেন্টে নেমে আসে।\nতুমি জানো, ওটা সতর্ক স্বভাবের।\nওটা সাবধানে তোমাদের মধ্যকার দূরত্ব বজায় রাখে—না অত দূরে, না এত কাছে যে অপমানিত হতে হয়।\nতবু, তুমি এই গভীর অস্বস্তির অনুভূতিটা কিছুতেই ঝেড়ে ফেলতে পারো না।"
  },
  Event_6943_Name = {
    Text = "পদধ্বনি"
  },
  Event_6944_ChoiceDesc1 = {
    Text = "[Observe It] 25টি কালো চিহ্ন পাওয়ার 100% সম্ভাবনা"
  },
  Event_6944_ChoiceDesc2 = {
    Text = "[Pet It] 50% সম্ভাবনায় 50টি কালো চিহ্ন পাবে, 50% সম্ভাবনায় কিছুই পাবে না।"
  },
  Event_6944_Desc = {
    Text = "একটি কালো বিড়াল হঠাৎ পাশের গলির অন্ধকার থেকে লাফিয়ে বেরিয়ে এসে স্নেহভরে তোমার পায়ের সঙ্গে জড়িয়ে গেল। তার ভৌতিক সবুজ উল্লম্ব মণি শীতল আলোয় ঝলসে উঠল, যেন বলছে, \"আমাকে তাড়া কোরো না, এসো, একটু আমার সঙ্গে খেলো।\"\n\"তুমি ইতিমধ্যেই তাঁকে দেখেছ। তিনি ঠিক তোমার পাশেই—যারা উন্মাদনায় দূষিত, সেই উন্মত্ত ছায়ারা... তাঁর অবয়বের দিকে সরাসরি তাকিও না।\""
  },
  Event_6944_Name = {
    Text = "নিশিযামিনীর পরী"
  },
  Event_6945_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6945_Desc = {
    Text = "জাগরণকারীরা তোমার আদেশের অপেক্ষায়; অন্য কিছুর জন্য তোমার কাছে আর কোনো সময় নেই।"
  },
  Event_6945_Name = {
    Text = "দৃষ্টিকোণ থেকে"
