  },
  Event_6946_ChoiceDesc2 = {
    Text = "[Check Camera] 50টি কালো চিহ্ন গ্রহণ করুন"
  },
  Event_6946_Desc = {
    Text = "যেন ভেতরের নাড়িভুঁড়ি টেনে বের করে নেওয়া, ক্যামেরার ভেতরের ফিল্মটি ছিন্নভিন্ন হয়ে গেল, অন্তঃসারশূন্য দেহের মতো ফেলে রাখা ও উপেক্ষিত।\nএক ঝলক অন্ধকার-চেরা সাদা আলো, রাস্তার মোড়ে ফেলে রাখা ক্যামেরাটি কাত হয়ে উঠল, অদৃশ্য এক শক্তি তার শাটার টিপে দিল।\n\"ক্লিক—\"\nতোমার শক-গ্রস্ত, স্তব্ধ অভিব্যক্তি বিশ্বস্তভাবে বন্দী হয়ে রইল সেই ফিল্মে"
  },
  Event_6946_Name = {
    Text = "নির্দোষতার নথি"
  },
  Event_6947_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6947_Desc = {
    Text = "ওটা শুধু বাতাসে দুলে ওঠা ভারী তালার শব্দ, উদ্বিগ্ন হওয়ার কিছু নেই। একে উপেক্ষা করো।"
  },
  Event_6947_Name = {
