  Event_6948_Desc = {
    Text = "\"আমি\" অনন্য, কোটি কোটি মহাবিশ্ব জুড়ে যার কোনো বিকল্প নেই।"
  },
  Event_6948_Name = {
    Text = "আত্মা অনুরণন"
  },
  Event_6949_ChoiceDesc1 = {
    Text = "[Claim] একটি রৌপ্য সৃষ্টি বেছে নাও"
  },
  Event_6949_Desc = {
    Text = "\nওটা হয়তো “আমি”।\nসময়ের ছায়া ভেদ করে, মাত্রিক প্রতিরক্ষা প্রাচীর অতিক্রম করে, এক চিরে যাওয়া ফাঁক দিয়ে, আমি মুখোমুখি হলাম “নিজের” সঙ্গে।"
  },
  Event_6949_Name = {
    Text = "আত্মা অনুরণন"
  },
  Event_6950_ChoiceDesc1 = {
    Text = "[Point Out the Issue] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_6950_ChoiceDesc2 = {
    Text = "[Swallow Doubt] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো এবং খোদাই করার প্রার্থনাগাথা বদলাও।(ব্যবহার: 1/2)"
  },
  Event_6950_Desc = {
    Text = "মেয়েটির জন্যও, সেটি ছিল এক অনুচ্চারিত বেদনা।\nসে যখন বুকে হাত রেখে পঁচিশ বছরের দীর্ঘ স্বপ্নের কাহিনি, আর জেগে ওঠার পরের একাকিত্বের অনুভূতি বলতে শুরু করে, তুমি তোমার জিজ্ঞাসা গিলে ফেলো।"
  },
  Event_6950_Name = {
    Text = "শৃঙ্খলিত জীবন"
  },
  Event_6951_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6951_Desc = {
    Text = "তুমি কাগজ আর কাঠের টুকরোগুলো আগুনে নিক্ষেপ করো। আগুন লোভীভাবে সেগুলো গিলে ফেলে, আর তৃপ্তির ঢেঁকুর তোলে। ধ্বংসের জন্য সে প্রস্তুত, তবে তার আগে তোমাকে একটি আশীর্বাদ দেবে।"
  },
  Event_6951_Name = {
    Text = "বিবর্ণ অগ্নি"
  },
  Event_6952_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6952_Desc = {
    Text = "তুমি নির্মমভাবে ঘৃণার শেষ অঙ্গারটুকু নিভিয়ে দিয়েছ, আর চারপাশে ভেসে থাকা বিদ্বেষ ও অনিচ্ছা যেন কিছুটা প্রশমিত হয়েছে।"
  },
  Event_6952_Name = {
    Text = "বিবর্ণ অগ্নি"
  },
  Event_6953_ChoiceDesc1 = {
    Text = "[Chase the Crows] Arg1টি কালো চিহ্ন গ্রহণ করো, তবে 「(Skill.Arg2)」 বিকাশ করো।"
  },
  Event_6953_ChoiceDesc2 = {
    Text = "[Ignore] প্রস্থান"
  },
  Event_6953_Desc = {
    Text = "তুমি কাকটিকে ধরার চেষ্টা করো, কিন্তু সে কেবল শোবার ঘরের এক প্রান্ত থেকে অন্য প্রান্তে উড়ে যায়, তার ভৌতিক ডাক অব্যাহত রাখে। যেখানে সে বসে, সেখান থেকে কালো আঠালো তরল ঝরে পড়ে, গাঢ় দাগের জন্ম দেয়।"
  },
  Event_6953_Name = {
    Text = "ল্যান্টার্ন-ক্রো"
  },
  Event_6954_ChoiceDesc1 = {
    Text = "[Leave] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_6954_Desc = {
    Text = "\n「তুমি সারবস্তুটাকে ধরতে পারো,」 লোকটি উজ্জ্বল হাসি হেসে বলে। 「ওটাই পৃথিবীর সবচেয়ে সুস্বাদু খাদ্য, প্রতিটি পেটুকের সূক্ষ্ম প্রস্তুতি ও আস্বাদের যোগ্য।」\n「দুঃখের বিষয়, এবার তোমাকে সেটা চেখে দেখতে দিতে পারছি না। ক্ষতিপূরণ হিসেবে, আমার কাছে কিছু অন্য রকম সুস্বাদু জিনিস আছে, সেগুলোই তোমাকে দেব।」\nএ কথা বলে লোকটি কোমল লাল মাংসের একটি টুকরো ছুড়ে দেয়। নরম মাংসের টুকরোটি সেতুর ওপর পড়ে, তার আঠালো অঙ্গপ্রত্যঙ্গগুলো গ্রোটেস্ক ভঙ্গিতে কিলবিল করতে থাকে। তুমি আবার মাথা তুলে তাকাতেই দেখো, জটিল ইস্পাত কাঠামোর আড়ালে লোকটির অবয়ব উধাও, কোনো চিহ্ন নেই।"
  },
  Event_6954_Name = {
    Text = "অদ্ভুত সঙ্গী VI"
  },
  Event_6955_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6955_Desc = {
    Text = "স্তর সংখ্যা একে একে, ধাপে ধাপে খুলে ফেলা—এটাই তোমার পারদর্শিতা।\nএক ঝলক অনুপ্রেরণা তোমার মন পরিষ্কার করে দেয়, সামনে থাকা বাস্তবতাকে স্পষ্ট করে তোলে—\nযেই সুতোই টানুক না কেন, পালিয়ে বেঁচে থাকাই তোমার একমাত্র পথ।"
  },
  Event_6955_Name = {
    Text = "অনুপ্রেরণার বিস্ফোরণ"
  },
  Event_6956_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6956_Desc = {
    Text = "তোমার তালুর ভেতর এক প্রজাপতি ভেঙে চুরমার হয়ে যায়, যেন হঠাৎ ভেঙে যাওয়া কাঁচের সিলিং—খণ্ডাংশগুলো পড়ছে, পড়ছে, পড়ছে মাটির দিকে—"
  },
  Event_6956_Name = {
    Text = "আয়রনওয়ে মরীচিকা"
  },
  Event_6957_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6957_Desc = {
    Text = "রামোনা এগিয়ে আসতে অনিচ্ছুক দেখে, বিড়ালটি মাথা নাড়ল এবং ছায়ায় মিলিয়ে গেল।"
  },
  Event_6957_Name = {
