  Event_6958_ChoiceDesc1 = {
    Text = "[Make a promise] 「(RelicConfig.Arg1)」 নামের রৌপ্য সৃষ্টি অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_6958_ChoiceDesc2 = {
    Text = "[Refuse] 「(RelicConfig.Arg1)」 নামের রৌপ্য সৃষ্টি অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_6958_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6958_Desc = {
    Text = "「ওটা সত্যিই এক ভোলার নয় এমন স্মৃতি ছিল।\nআমার মাথা আর অঙ্গপ্রত্যঙ্গ জোর করে প্লাস্টারের ভেতর চেপে ধরা হয়েছিল।\nশ্বাসরোধ আর মৃত্যু-সন্নিকট মায়াভ্রম আমাকে গভীরভাবে আচ্ছন্ন করেছিল, তারপর আমাকে টেনে তুলে ছুড়ে ফেলেছিল এক অন্ধকার তীরে।\nআমি তার দিকে তাকালাম, অনুভব করলাম আমারও একটা অংশ যেন কেড়ে নেওয়া হয়েছে।\nআমার আত্মার সেই হারিয়ে যাওয়া অর্ধেক তখন থেকেই বাস করছে সেই ছোট, প্রাথমিক মোমের ভাস্কর্যে।\nতাই... তুমি কি আমাকে আমার অপর অর্ধেক খুঁজে পেতে সাহায্য করবে?」"
  },
