  },
  Event_6959_Desc = {
    Text = "তুমি স্মৃতিচারণের এক দর্শক, অসহায়ভাবে দেখছ মেয়েটি আলোহীন সাগরে ডুবে যাচ্ছে।\nস্রোত তার স্কার্টকে উপরের দিকে তুলে ধরে, অথচ সে ডুবে যায়, এক অম্লান, অখোলা ফুলের মতো।"
  },
  Event_6959_Name = {
    Text = "ডুবন্ত সাগর"
  },
  Event_6960_ChoiceDesc1 = {
    Text = "[Insert your Silver Key]"
  },
  Event_6960_Desc = {
    Text = "অতিরিক্ত স্যাচুরেটেড D-পঙ্কের ভেতরে যেন কিছু আছে... রৌপ্য চাবি ব্যবহার করে সেটিকে তোমার নিজস্ব শক্তিতে রূপান্তর করো।"
  },
  Event_6960_Name = {
    Text = "নিষ্কাশন বিন্দু"
  },
  Event_6961_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6961_Desc = {
    Text = "শত্রুর প্রলোভনে পা দিও না; ওটা হয়তো এক ফাঁদ।"
  },
  Event_6961_Name = {
    Text = "অভিশপ্ত দুর্কাক"
  },
  Event_6962_ChoiceDesc1 = {Text = "[Help Him]"},
  Event_6962_ChoiceDesc2 = {
    Text = "[Observe Coldly]"
  },
  Event_6962_Desc = {
    Text = "মঞ্চের ওপর দাঁড়িয়ে আছে বালক, ফ্যাকাশে আলো তার মুখে পড়েছে।\n\"উ-উৎসর্গ করা হলো...\"\nবালকের মুখ লাল হয়ে উঠল। সে মুখ খুলল, কিন্তু কোনো শব্দই বেরোল না।\nতার ফাঁক হয়ে থাকা মুখ ক্রমেই বড় থেকে বড়তর হতে লাগল..."
  },
  Event_6962_Name = {
    Text = "অন্তিম III"
  },
  Event_6963_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6963_Desc = {
    Text = "“ধুর, ধুর!” যেন কোনো সুইচ টিপে দিলে, কালো বিড়ালটি হঠাৎ হিংস্র হয়ে ওঠে, তোমার হাতে ঝাঁপিয়ে কামড় বসাতে চায়। সৌভাগ্যবশত তুমি ঠিক সময়ে সরে যাও, কেবল জামার এক টুকরো ছিঁড়ে যায়। কালো বিড়ালটি রাস্তার মোড় ঘুরে নর্দমার ভেতর মিলিয়ে যায়।"
  },
  Event_6963_Name = {
    Text = "নিশিযামিনীর পরী"
  },
  Event_6964_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6964_Desc = {
    Text = "মস্তিষ্কে উথলে ওঠা চিন্তাধারার ঢেউয়ে আচ্ছন্ন হয়ে তুমি দরজা ঠেলে খোলো, আর পা বাড়াও এক অপ্রত্যাবর্তনীয় পথে।\nদরজার বাইরে দাউদাউ করে জ্বলা সাদা আলো কি মুক্তি, না ধ্বংস?"
  },
  Event_6964_Name = {
    Text = "বহু দ্বারের ওপারে"
  },
  Event_6965_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6965_Desc = {
    Text = "তুমি সতর্কভাবে এগিয়ে গিয়ে পরীক্ষা করো, আর টেবিল ঢেকে থাকা পিচ্ছিল স্তর হঠাৎ ফেটে গিয়ে নিচে লুকিয়ে থাকা জিনিসটি প্রকাশ করে।"
  },
  Event_6965_Name = {
    Text = "বহু দ্বারের ওপারে"
  },
  Event_6966_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6966_Desc = {
    Text = "তোমার সংশয় গিলে ফেলো, শত্রুর ওপর মনোযোগ দাও।\nপ্রজাপতিগুলোকে তোমার দেহের ভেতরেই ভেসে বেড়াতে দাও, যদিও তাদের ডানা তোমার অঙ্গপ্রত্যঙ্গ ছিঁড়ে ফেলে।"
  },
  Event_6966_Name = {
    Text = "বাটারফ্লাই ইফেক্ট"
  },
  Event_6967_ChoiceDesc1 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6967_Desc = {
    Text = "বিড়ালটি তৃপ্তির ভঙ্গিতে মাথা নাড়ল, তারপর ছায়ার ভেতর মিলিয়ে গেল, পেছনে রেখে গেল কয়েকটি কালো বৃত্তাকার বস্তু।"
  },
  Event_6967_Name = {
    Text = "বিচরণকারী বাসিন্দা"
  },
  Event_6968_ChoiceDesc1 = {
    Text = "[Insert your Silver Key]"
  },
  Event_6968_Desc = {
    Text = "অতিরিক্ত স্যাচুরেটেড D-পঙ্কের ভেতরে যেন কিছু আছে... রৌপ্য চাবি ব্যবহার করে সেটিকে তোমার নিজস্ব শক্তিতে রূপান্তর করো।"
  },
  Event_6968_Name = {
    Text = "নিষ্কাশন বিন্দু"
  },
  Event_6969_ChoiceDesc1 = {
    Text = "[Leave] একটি এলোমেলো সোনার রেলিক অর্জন করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_6969_Desc = {
    Text = "তোমাকে এখনও দ্বিধায় দেখে, কৌম মাটির ঢিবির ওপর ঝাঁপিয়ে পড়ল, সামনের থাবা দিয়ে দ্রুত খুঁড়ে কিছু একটা তোমার সামনে ঠেলে দিল।"
  },
  Event_6969_Name = {
    Text = "গভীরে সমাহিত"
  },
  Event_6970_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6970_Desc = {
    Text = "কাগজের শীর্ষে পরিপাটি করে ছাপা আছে \"মেরিমে\", সেখানে কখনো কোনো ম্যাসন ছিল না।\nঅতিরিক্ত সংশয় ভালো লক্ষণ নয়, রক্ষক।"
  },
  Event_6970_Name = {
    Text = "টাইপরাইটার"
  },
  Event_6971_ChoiceDesc1 = {
    Text = "[Leave] 3টি সোনার রেলিকের মধ্যে 1টি অর্জন করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_6971_Desc = {
    Text = "এই টিলার নিচে চাপা পড়ে আছে ভাস্করদের সমিতির অগণিত নৃশংস অপরাধ।"
  },
  Event_6971_Name = {
    Text = "গভীরে সমাহিত"
  },
  Event_6972_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6972_Desc = {
    Text = "পাখিদের নিজস্ব নিয়ম আছে। তারা তোমার ইচ্ছা অনুযায়ী চলে না, আর তুমি প্রকৃতির বিধিতে হস্তক্ষেপ করার অধিকারও রাখো না।"
  },
  Event_6972_Name = {
    Text = "নির্বাসিত কাক"
  },
  Event_6973_ChoiceDesc1 = {
    Text = "[Leave] 3টি সোনার রেলিকের মধ্যে 1টি অর্জন করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_6973_Desc = {
    Text = "কেন? কেন তা ডুবে গেল?\nসেদিন কোনো বজ্রঝড় ছিল না, ছিল না কোনো তুফান। রাতের আকাশ ছিল নির্মল, একটি তারাও নেই, দিগন্তের নিচুতে ঝুলে ছিল পূর্ণ চাঁদ—একটি শীতল সূর্যের মতো।"
  },
  Event_6973_Name = {
    Text = "ডুবন্ত সাগর"
  },
  Event_6974_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6974_Desc = {
    Text = "「কনডাক্টর! আমরা আক্রমণের শিকার!...ব্জ্জ...」\nমনে হচ্ছে এটা চালকের কাছ থেকে আসা কল। তুমি কল কেটে দেওয়ার উপক্রম করেছিলে।\n「পুনরায় বলছি, এখানে মিথাগ ফিল্ড টিম 4। আমরা উদ্ধারকৃত জিম্মিদের নিয়ে উত্তরমুখী রাতের এক্সপ্রেসে প্রহরী হিসেবে ছিলাম, তখনই আমরা... আহ!」\nফোনের ওপারের কণ্ঠস্বর কর্কশ হুইসপার-এ পরিণত হয়, তার সঙ্গে মিশে যায় অদ্ভুত আর্তনাদ।\n「অনুষ্ঠান সম্পন্ন। পথহারা মেষশাবক, এই পবিত্র স্নান যেন তোমার আত্মাকে শুদ্ধ করে...」"
  },
  Event_6974_Name = {
    Text = "ট্রেন কল"
  },
  Event_6975_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6975_Desc = {
    Text = "সিলভার সংগ্রহ করাও রক্ষকদের কাজের একটি অংশ।\nশুভ্র স্ফটিকের ভেতর ভেসে থাকা আত্মাগুলো ভবিষ্যতে একেবারে নতুন রূপে আবার এই জগতে প্রত্যাবর্তন করবে।"
  },
  Event_6975_Name = {
    Text = "বন্দী আত্মা"
  },
  Event_6976_ChoiceDesc1 = {
    Text = "[Descend Further] একটি এলোমেলো কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_6976_ChoiceDesc2 = {
    Text = "[Pull Away] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6976_Desc = {
    Text = "「তুমি」 তোমাকে আমন্ত্রণ জানাচ্ছে।\nসর্পিলের গভীরে, অতীত ও ভবিষ্যতের 「তুমি」 তোমাকে ভিন্ন মাত্রা থেকে একটি 「উপহার」 পাঠিয়েছে।"
  },
  Event_6976_Name = {
    Text = "অতল গহ্বর"
  },
  Event_6977_ChoiceDesc1 = {
    Text = "[Lean Out] সোনার রেলিক 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_6977_ChoiceDesc2 = {
    Text = "[Give Up Checking] 50টি কালো চিহ্ন গ্রহণ করুন"
  },
  Event_6977_Desc = {
    Text = "অপারেশন টেবিলের নিচে যেন কোনো ফিল্মের রোল আটকে আছে।"
  },
  Event_6977_Name = {
    Text = "স্মৃতির ছায়ামূর্তি"
  },
  Event_6978_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6978_Desc = {
    Text = "বিক্ষেপ উপেক্ষা করো এবং বর্তমানের ওপর মনোযোগ দাও।\nতোমার করার আছে আরও গুরুত্বপূর্ণ কাজ।"
  },
  Event_6978_Name = {
    Text = "আমার অপর অর্ধেক"
  },
  Event_6979_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6979_Desc = {
    Text = "একটি হারিয়ে যাওয়া অবশেষ, অমূল্য উত্তরাধিকার, ইচ্ছাপূরণকারী এক যন্ত্র...\nহয়তো কেবল গোপন সম্পদই এতটা মোহময় হতে পারে।"
  },
  Event_6979_Name = {
    Text = "প্রহেলিকা ইনপুট"
  },
  Event_6980_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6980_Desc = {
    Text = "「তুমি লিলির 「মা」, অথচ তাকে শুধু গবেষণা আর যুদ্ধের হাতিয়ার হিসেবে ব্যবহার করো,「 তুমি জবাব দাও। 「একটি সন্তান তার মায়ের কথা মানতে পারে, কিন্তু তোমার লিলির 「মা」 হওয়া উচিত নয়।「"
  },
  Event_6980_Name = {
    Text = "তার পছন্দ"
  },
  Event_69813_ChoiceDesc1 = {Text = "[Leave]"},
  Event_69813_Desc = {
    Text = "রৌপ্য চাবি গ্লিমার ছড়ায়; বাহুগুলো যেন কোনো শক্তিতে ভীত হয়ে পুকুরের ভেতরে সরে গিয়ে মিলিয়ে যায়।"
  },
  Event_69813_Name = {
    Text = "রক্তাক্ত পুকুর"
  },
  Event_69814_ChoiceDesc1 = {Text = "[Leave]"},
  Event_69814_Desc = {
    Text = "যত গভীরে ডুবে যাও, ততই তোমার মস্তিষ্কে পরম ইচ্ছাশক্তির বিশৃঙ্খল হুইসপার স্পষ্ট হয়ে ওঠে। তুমি চোখ বন্ধ করো, নিজের ভেতরে সুপ্ত কর্তৃত্বকে আহ্বান জানাও।\nহঠাৎ, সব শব্দ আর অদ্ভুত অনুভূতি মিলিয়ে যায়। তুমি দাঁড়িয়ে আছো দরজার ওপারে, তোমার পাশে থাকা রক্ত-লাল শুঁড়গুলো যেন কখনো ছিলই না, বিন্দুমাত্র চিহ্ন না রেখে উধাও হয়ে গেছে।\nতুমি নিজেকে পুনরুজ্জীবিত অনুভব করো। তুমি জানো, যে মূল্য তুমি দিয়েছ, তা তুচ্ছ— তুমি আরও শক্তিশালী রূপে সেই সর্বোচ্চ সত্তার মুখোমুখি হবে।"
  },
  Event_69814_Name = {
    Text = "রক্তাক্ত পুকুর"
  },
  Event_69815_ChoiceDesc1 = {Text = "[Leave]"},
  Event_69815_Desc = {
    Text = "তোমার স্মৃতি দিয়ে গড়া জাগরণকারী এক মুহূর্ত দেরি না করে রক্তে ভেজা পুকুর থেকে তোমাকে টেনে তোলে। কাদামাখা জল ছিটকে পড়তে পড়তে তোমার ছেঁড়া হাতটি আবার জোড়া লাগে, জলের ভেতর অগণিত অস্পষ্ট প্রাণী কিলবিল করতে থাকে। আসল রেলিক আর ধ্বংসকারী উন্মত্ত আকাঙ্ক্ষায় গিলে খেতে চাইছিল।"
  },
  Event_69815_Name = {
    Text = "রক্তাক্ত পুকুর"
  },
  Event_69816_ChoiceDesc1 = {
    Text = "[Summon Awakeners] সব জাগরণকারী 100 অ্যালিমাস হারাবে। একটি উপসর্গ কার্ড ধ্বংস করো।"
  },
  Event_69816_ChoiceDesc2 = {
    Text = "[Drink the Blood] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি দুইবার বিকশিত করো।"
  },
  Event_69816_ChoiceDesc3 = {
    Text = "[Harness Silver Key] সব Keyflare হারাও।"
  },
  Event_69816_Desc = {
    Text = "আদিম সত্তার চোখে জীবনের কর্তৃত্ব মৃত্যুর রূপেই প্রকাশ পায়। তুমি যখন এই ছায়াময় ডোমেইনে পা রাখো, দুর্গন্ধময় রক্তের পুকুরটি সঙ্গে সঙ্গে তার আসল রূপ উন্মোচন করে।\nরক্তিম-কালো সেই রক্ত অসংখ্য বাহু প্রসারিত করে, তোমার গোড়ালিতে আঁকড়ে ধরে নিরন্তর উপরের দিকে টেনে চলে, তোমাকে টেনে নিয়ে যেতে চায় অতলের অতল গভীরে।"
  },
  Event_69816_Name = {
    Text = "রক্তাক্ত পুকুর"
  },
  Event_6981_ChoiceDesc1 = {
    Text = "[Pick Up Key]"
  },
  Event_6981_Desc = {
    Text = "জং ধরা চাবির একগুচ্ছ। দরজা খুলতে ব্যবহার করা যেতে পারে।"
  },
  Event_6981_Name = {
    Text = "মরিচা ধরা চাবি"
  },
  Event_6982_ChoiceDesc1 = {
    Text = "[Leave] একটি কমান্ড কার্ড নকল করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_6982_Desc = {
    Text = "শ্যান্তি আর সেলেস্টের দিশা মেনে তুমি তাকাও কেবিনের অতল কালো গভীরে—তোমার বেঁচে থাকার ক্ষীণ সম্ভাবনাটা কি তবে লুকিয়ে আছে সেই সীমাহীন অন্ধকারের ভেতরেই?"
  },
  Event_6982_Name = {
    Text = "নাবিকদের গান"
  },
  Event_6983_ChoiceDesc1 = {
    Text = "[Leave Together] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_6983_ChoiceDesc2 = {
    Text = "[Refuse to Leave] 75টি কালো চিহ্ন গ্রহণ করো, তবে 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_6983_Desc = {
    Text = "এটা কি মায়াভ্রম? তুমি দেখো কাকেরা মাথার ওপর চক্কর দিচ্ছে, গুনগুনিয়ে গাইছে এক পরিচিত সুর:\n\"তবে চলো, একসাথে চলে যাই, তুমি আর আমি,\nরাত যখন নামে,\nরাস্তার ধারে লুটিয়ে পড়া মরণাপন্ন মাতালের মতো।\""
  },
  Event_6983_Name = {
    Text = "কাকদের কোরাস"
  },
  Event_6984_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6984_Desc = {
    Text = "পশ্চাদ্দৃষ্টির শক্তি স্বল্প সময়ে তোমার জন্য আরেকটি সংযোগস্থল খুঁজে পায় না, কিন্তু অন্তত তুমি কিছুটা সাময়িক মুক্তি অনুভব করো।"
  },
  Event_6984_Name = {
    Text = "অস্বাভাবিক যোগাযোগ"
  },
  Event_6985_ChoiceDesc1 = {
    Text = "[Gaze into the Abyss]"
  },
  Event_6985_ChoiceDesc2 = {
    Text = "[Pull Away] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6985_Desc = {
    Text = "পোর্টহোল থেকে সমুদ্রের পৃষ্ঠ উধাও হয়ে গেছে।\nকাঁচে প্রতিফলিত হচ্ছে তোমার ফ্যাকাসে মুখ, আর তোমার চোখের মণিতে, \"তুমি\" আবার পোর্টহোলের দিকে তাকিয়ে আছো।\nবাস্তবতা আর ডোমেইন একে অন্যের ওপর চেপে বসে জড়িয়ে যায়, শেষে বিকৃত হয়ে সূক্ষ্ম এক সর্পিল ঘূর্ণিতে পরিণত হয়।"
  },
  Event_6985_Name = {
    Text = "অতল গহ্বর"
  },
  Event_6986_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6986_Desc = {
    Text = "তুমি স্কুল থেকে আসা যোগাযোগ অনুরোধটি গ্রহণ করেছ। পরিচিত কণ্ঠস্বর তোমার মনকে শান্ত করে। তুমি মনোবল সঞ্চয় করে সামনে এগিয়ে যাও।"
  },
  Event_6986_Name = {
    Text = "সংযোগস্থল"
  },
  Event_6987_ChoiceDesc1 = {Text = "[Agree]"},
  Event_6987_ChoiceDesc2 = {Text = "[Disagree]"},
  Event_6987_ChoiceDesc3 = {
    Text = "[No Comment]"
  },
  Event_6987_Desc = {
    Text = "「অনেক দিন পর দেখা, বন্ধুরা।」 আলোবাহকের ভক্তদের সঙ্গে যুদ্ধ থেকে পালিয়ে শ্বাস ঠিক করার পর তুমি হঠাৎ লক্ষ্য করো, লম্বা চুলের মানুষটি আবারও রাস্তার ধারে উপস্থিত হয়েছে, এমনভাবে হাসছে যেন লড়াইটা কখনো ঘটেইনি।\n「গতবারের তুলনায়, তোমার গায়ে সার্বেরাসের গন্ধ অনেক বেশি তীব্র। এই সময়ে তুমি নিশ্চয়ই অনেক দূর ভ্রমণ করেছ, তাই না?」\n"
  },
  Event_6987_Name = {
    Text = "অদ্ভুত সঙ্গী V"
  },
  Event_6988_ChoiceDesc1 = {
    Text = "[তাকে পথ জিজ্ঞেস করা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_6988_ChoiceDesc2 = {
    Text = "[এটি ছেড়ে যাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_6988_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6988_Desc = {
    Text = "উঁচু রাস্তার বাতির নিচে ছায়াটা দাঁড়িয়ে আছে।\n\"একটু আগুন ধার পাব কি, স্যার?\"\nতোমার @2 করার অভ্যেস নেই, কিন্তু সামান্য একটু \"জাদু\" ব্যবহার করতে তোমার আপত্তি নেই।\nতোমার সহায়তায় ছায়াটি @2-তে আগুন ধরাবে এবং সেটাকে গভীরভাবে নিক্ষেপ করবে সেই অতল কালো ঘূর্ণাবর্তের ভেতর।\nঅল্পক্ষণের মধ্যেই তুমি দেখতে পাও সাদা ধোঁয়া কুণ্ডলী পাকিয়ে উঠছে।\n\"আহ—\"\nসন্তুষ্টির নিঃশ্বাস ফেলে ছায়াটি।"
  },
  Event_6988_Name = {
    Text = "পথের আলোয় ছায়ামূর্তি"
  },
  Event_6989_ChoiceDesc1 = {Text = "[Confirm]"},
  Event_6989_Desc = {
    Text = "দাবার বোর্ডে, যা তুমি দেখছো তা বাস্তব নয়।\n\nযা তোমার পথ রোধ করে আছে, তা হয়তো দেয়াল নয়, বরং তোমার ক্ষয়িষ্ণু কৌতূহল।"
  },
  Event_6989_Name = {
    Text = "প্রেতচ্ছায়া মহাকাশ"
  },
  Event_6990_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6990_Desc = {
    Text = "「আমি ভীষণ কষ্টে আছি... সাশা দিদি...「\nতুমি সারার দিকে তাকাও। সে—উদ্বিগ্ন ভঙ্গিতে—দু」জন বালককে আড়াল করে দাঁড়িয়ে আছে, ভান করছে যেন কিছুই শোনেনি।\nকণ্ঠস্বরটি ধীরে ধীরে মিলিয়ে যায়।"
  },
  Event_6990_Name = {
    Text = "\"সাশা দিদি\""
  },
  Event_6991_ChoiceDesc1 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6991_Desc = {
    Text = "তুমি উঠে দাঁড়িয়ে ছেলেটির জন্য হাততালি দিলে।\nমনে হলো তোমার উৎসাহ সে অনুভব করেছে, সে তার ছোট বুকটা ফুলিয়ে দাঁড়াল।\nতার মুখ থেকে কালো রক্ত ঝরতেই থাকল, তবু আর কিছুই তার গান থামাতে পারল না।"
  },
  Event_6991_Name = {
    Text = "অন্তিম IV"
  },
  Event_6992_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6992_Desc = {
    Text = "দুঃখের একাংশ বাষ্পীভূত হচ্ছে, তবু অশ্রু অবিরাম প্রবাহিত হচ্ছে সেই রহস্যময় পূর্বজন্মের দিকে।"
  },
  Event_6992_Name = {
    Text = "স্টিক্সের বিলাপ"
  },
  Event_6993_ChoiceDesc1 = {
    Text = "[Choke the Singer] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg2)」 অর্জন করো, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_6993_ChoiceDesc2 = {
    Text = "[Stumbling Dancer's Steps] রৌপ্য সৃষ্টি 「(RelicConfig.Arg2)」 এবং 「(RelicConfig.Arg3)」 অর্জন করো, তবে 「(Skill.Arg1)」 উপসর্গটি দুইবার বিকশিত করো।"
  },
  Event_6993_ChoiceDesc3 = {
    Text = "[Take a Detour] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো।"
  },
  Event_6993_Desc = {
    Text = "তুমি তিনটি আঠালো অবয়বের দ্বারা পথরুদ্ধ হও।\nএকটি অবয়ব কর্কশ কণ্ঠে ভৌতিক গানের কথা গাইছে। তুমি কান ঢেকে তাকে এড়িয়ে পাশ কাটিয়ে যাও।\nআরেকটি অবয়ব কাঠের পুতুলের মতো কড়া নড়াচড়ায় দ্বিধাগ্রস্ত পায়ে নৃত্য করছে। তুমি চোখ বন্ধ করে তাকে ফাঁকি দিয়ে সরে যাও।\nশেষ অবয়বটি ভাঙাচোরা বাক্যে খণ্ডিত কবিতা আবৃত্তি করছে। আর সহ্য করতে না পেরে, তুমি—"
  },
  Event_6993_Name = {
    Text = "সংকীর্ণ পথের দুর্বৃত্ত"
  },
  Event_6994_ChoiceDesc1 = {Text = "[Leave]"},
  Event_6994_Desc = {
    Text = "ক্রোধের এক অংশ ফুটতে থাকে, অথচ অশ্রু গড়িয়ে চলে এক অজানা অতীতের দিকে।"
  },
  Event_6994_Name = {
    Text = "স্টিক্সের বিলাপ"
  },
  Event_6995_ChoiceDesc1 = {
    Text = "[Ignore It] একটি রেলিক অর্জন করো, তবে 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_6995_ChoiceDesc2 = {
    Text = "[Turn Away] একজন র‍্যান্ডম জাগরণকারীকে জাগ্রত করো"
  },
  Event_6995_Desc = {
    Text = "নিষ্ঠুর নিয়তি ভ্রমণকারীর পায়ের নিচে সরীসৃপের মতো গড়িয়ে চলে। পথটি আয়নার মতো স্বচ্ছ, পেছনে ক্ষীণ ভাঙনের শব্দ।\nকার পায়ের তলায় চূর্ণ হলো সেই নিয়তি? এ কি মায়াস্বপ্ন, ফাঁদ, নাকি শুধু প্রলাপ, প্রতারণা...\nতোমার চোখের সামনে ধীরে ধীরে এগিয়ে আসে এক সরু ফাটল।\n<Italic:যেন তা ডুবে যাবে জাগরণ নসিসের ভারে।>"
  },
  Event_6995_Name = {
    Text = "বিচরণকারী ফাটল"
  },
  Event_6996_ChoiceDesc1 = {
    Text = "[Initiate Trial] 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো; বিজয়ী হলে একটি সোনার রেলিক জিতে নাও, আর ব্যর্থ হলে 50টি কালো চিহ্ন লাভ করো।"
  },
  Event_6996_ChoiceDesc2 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6996_Desc = {
    Text = "তোমার পায়ের নিচের আয়নার মতো কালো কাদামাটি থেকে তুমি কিছু গোপন সত্যের আভাস পেয়েছ।\nতার প্রতিফলন ঝাপসা, এক অনমনীয় অন্ধকার কুয়াশায় মোড়া। অদ্ভুতভাবে পরিচিত মনে হয়, তবু তুমি ঠিক বুঝে উঠতে পারো না, সেটি আসলে কী।"
  },
  Event_6996_Name = {
    Text = "আয়নাতলে"
  },
  Event_6997_ChoiceDesc1 = {
    Text = "[Imitate Cat's Call] 50% সম্ভাবনায় 125টি কালো চিহ্ন প্রাপ্ত হও, 50% সম্ভাবনায় 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_6997_ChoiceDesc2 = {
    Text = "[Feed] 75% সম্ভাবনায় 100টি কালো চিহ্ন প্রাপ্ত হও, 25% সম্ভাবনায় 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_6997_ChoiceDesc3 = {
    Text = "[Run Away] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6997_Desc = {
    Text = "\"তুমি অসাবধানে কালো বিড়ালের ডোমেইনে ঢুকে পড়েছ।\nঅন্ধকারে অসংখ্য চোখ খুলে গেল, ভরা কৌতূহল, অনুসন্ধান আর সতর্কতায়... কিন্তু বিন্দুমাত্র মমতা নেই।\nপান্না সবুজ, অ্যাম্বার হলুদ, ময়ূর নীল...\nতোমার মনে হলো, যেন তুমি ঝলমলে রত্নের সাগরে নিমজ্জিত হয়ে আছো।\nপালানোর জন্য, তুমি—\""
  },
  Event_6997_Name = {
    Text = "বিড়ালের শহর"
  },
  Event_6998_ChoiceDesc1 = {
