  Event_6999_ChoiceDesc1 = {
    Text = "[Let Pointer] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_6999_ChoiceDesc2 = {
    Text = "[Hold Pointer] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_6999_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_6999_Desc = {
    Text = "কড়মড়, খচখচ, কড়মড়—\nভাগ্যের হাতগুলো ইঞ্চি ইঞ্চি করে এগিয়ে চলে, ঠান্ডা দাঁতাল গিয়ারের টিকটিক শব্দ নির্দয়ভাবে এগিয়ে যায় সেই দিকেই, যেটিকে তুমি সবচেয়ে বেশি ভয় পাও।"
  },
  Event_6999_Name = {
    Text = "সূচাগ্রের ওপারে"
  },
  Event_7000_ChoiceDesc1 = {
    Text = "[Turn a Deaf Ear] 3টি কমান্ড কার্ডের মধ্যে 1টি ধ্বংস করো, এবং 75টি কালো চিহ্ন প্রাপ্ত হও।"
  },
  Event_7000_ChoiceDesc2 = {
    Text = "[Carefully Inspect] 3টি কমান্ড কার্ডের মধ্যে 1টি অনুলিপি করো, এবং 25টি কালো চিহ্ন প্রাপ্ত হও।"
  },
  Event_7000_ChoiceDesc3 = {
    Text = "[Turn and Leave] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7000_Desc = {
    Text = "নিষ্ঠুর নিয়তি ধীরে ধীরে সরীসৃপের মতো এগোয় পথিকের পায়ের তলায়, সলতের পথ আয়নার মতো ঝকঝক করে, পেছনে ক্ষীণ ভাঙনের শব্দ।\nকার হাতে ভেঙে গিয়েছে পায়ের তলার সেই নিয়তি? এটি কি বিভ্রান্তি, ফাঁদ, নাকি কেবল প্রলাপ আর প্রতারণা...\nতোমার চোখের সামনে ধীরে ধীরে এগিয়ে আসে এক সরু, সরণশীল ফাটল।"
  },
  Event_7000_Name = {
    Text = "বিচরণকারী ফাটল"
  },
  Event_7001_ChoiceDesc1 = {
    Text = "[Call the Crow] 25টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 দক্ষতা বিকশিত করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_7001_ChoiceDesc2 = {
    Text = "[Get Far Away]"
  },
  Event_7001_Desc = {
    Text = "নখরটি চাদর ছিঁড়ে কাঁধের গভীরে গিয়ে গেঁথে বসে।"
  },
  Event_7001_Name = {
    Text = "নির্বাসিত কাক"
  },
  Event_7002_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7002_Desc = {
    Text = "ভয় কখনও কখনও কোনো দৃশ্যমান বস্তু থেকে জন্মায় না।\n“নরককুকুর” যেখানে যায়, সেখানেই লাল ফোঁটা রেখে যায়, যাতে প্রতিফলিত হয় তোমার ছায়ামূর্তি।"
  },
  Event_7002_Name = {
    Text = "নিরাকার প্রতিবিম্ব"
  },
  Event_7003_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7003_Desc = {
    Text = "মৃদু গুঞ্জনের সঙ্গে তুমি নারীর হুইসপার শুনতে পাও。\nঅশ্রুভেজা কণ্ঠে সে অবিরাম তার গল্প শোনাতে থাকে。\nএক ঘণ্টা কেটে যায়, তারপর এক দিন… অবশেষে তুমি বহু আগেই ভুলে যাও, কেন সে দুঃখিত ছিল。\nশেষমেশ, সে প্রফুল্ল কণ্ঠে ফোন রাখে এবং তোমাকে একটি উপহার পাঠানোর প্রতিশ্রুতি দেয়。\nতুমি তা গ্রহণ করো। শেষ পর্যন্ত, উপহার তো সবসময়ই মনোরম।"
  },
  Event_7003_Name = {
    Text = "কল গৃহীত"
  },
  Event_7004_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7004_Desc = {
    Text = "সহচরদের বিস্মিত দৃষ্টির সামনে তুমি মাথা নোয়াও, এক হাঁটু মাটিতে ঠেকাও, আর ডান মুঠোটা কপালে ঠেকিয়ে ধরো।\nঅসাধারণ, এতে তোমার মুখ পুরোপুরি আড়াল হয়ে যাবে।"
  },
  Event_7004_Name = {
    Text = "নিখুঁত ছদ্মবেশ"
  },
  Event_7005_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7005_Desc = {
    Text = "\n「তুমি আমার ওপর পর্দা মুড়ে দিয়েছ।」\nমোমের ভাস্কর্যটি শান্ত হাসি হেসে তোমার দিকে তাকায়।\n「তোমার পরিশ্রমের পুরস্কার হিসেবে আমি তোমাকে সত্য দিচ্ছি।」\nতার উদর থেকে অবিরাম কালো তরল বেরিয়ে এসে তোমাকে শক্ত করে জড়িয়ে ধরে।\nবিশ্ব ঘন কালো, অথচ অসীম উষ্ণ।\nতুমি গুটিয়ে বসে হাই তুলো, আর @1‑তম বারের মতো স্বপ্নলোকে পা রাখো…"
  },
  Event_7005_Name = {
    Text = "অসমাপ্ত মোমের ভাস্কর্য"
  },
  Event_7006_ChoiceDesc1 = {Text = "[Confirm]"},
  Event_7006_Desc = {
    Text = "কুয়াশার মাঝে আপনি কিছুই খুঁজে পেলেন না।"
  },
  Event_7006_Name = {
    Text = "বিশৃঙ্খলার কুয়াশা"
  },
  Event_7007_ChoiceDesc1 = {
    Text = "[Answer the Phone] 3টি উন্নত প্রার্থনাগাথা থেকে 1টি উৎকীর্ণ করো"
  },
  Event_7007_ChoiceDesc2 = {
    Text = "[Ignore Bell] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7007_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7007_Desc = {
    Text = "\"ডিং ডিং ডিং...\"\nকোণ থেকে ভেসে এলো এক কানে-বিদ্ধ করা ফোনের রিং, তাড়াহুড়ো আর কোলাহলে ভরা, প্রতিটি রিং আগের চেয়ে আরও জোরে, যেন তোমার মনে এক মায়াস্বপ্ন ঢুকিয়ে দিচ্ছে—যদি তুমি না তোলো, তবে সে সঙ্গে সঙ্গে পাগল হয়ে বিস্ফোরিত হবে, আর সেইসঙ্গে ধ্বংস করবে সমগ্র বিশ্বকে।\""
  },
  Event_7007_Name = {
    Text = "কল গৃহীত"
  },
  Event_7008_ChoiceDesc1 = {
    Text = "[Approach Phantasm] 3টি রৌপ্য সৃষ্টি থেকে 1টি অর্জন করো"
  },
  Event_7008_ChoiceDesc2 = {
    Text = "[Break Phantasm] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)「 ও 「(RelicConfig.Arg2)「 অর্জন করো, তবে 「(Skill.Arg3)「 দু」বার বিকশিত করো।"
  },
  Event_7008_Desc = {
    Text = "এটা কি ডোমেইনের কোনো মরীচিকা? নাকি আরেকটি অনিবার্য স্মৃতি?\nতুমি চোখ মুছে নাও। এক মায়াভ্রম এগিয়ে আসে—ওটা কি কোলাহলমুখর বাজার, ডিজলিউশনে হারিয়ে যাওয়া মোম জাদুঘর, তুষারাবৃত গ্রামের আশ্রয়কেন্দ্র, নাকি ঝাপসা ইয়াকুতস্ক?"
  },
  Event_7008_Name = {
    Text = "মরীচিকা"
  },
  Event_7009_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7009_Desc = {
    Text = "সিদ্ধ জলের আঁচে পুড়ে যাওয়ার মতো, তুমি স্বতঃস্ফূর্তভাবে কান চেপে ধরো, সেই বিদ্বেষপূর্ণ সুরকে বাইরে রেখে।"
  },
  Event_7009_Name = {
    Text = "নিষিদ্ধ সুর"
  },
  Event_7010_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7010_Desc = {
    Text = "একটি উজ্জ্বল মেজর কর্ড টানটান স্নায়ু আর ভয়কে দূর করে দেয়। তুমি উচ্ছ্বসিত, প্রস্ফুটিত, উচ্ছল। তুমি লম্বা পা ফেলে এগিয়ে চল, রামোনাকে অনেক পেছনে ফেলে—「রক্ষক?! এত তাড়াতাড়ি হাঁটো না!」"
  },
  Event_7010_Name = {
    Text = "নামহীন প্রতিধ্বনি"
  },
  Event_7011_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7011_Desc = {
    Text = "\n「ওখানেই থামো!!! পেট ঘেঁষে হেঁটে চলা গলতে থাকা দানবও তার নিজের অঙ্গপ্রত্যঙ্গ তোমার চেয়ে ভালো চেনে!」\nদর্শকদের ছেড়ে দাও…\nতুমি মনে মনে এই প্রার্থনা করো"
  },
  Event_7011_Name = {
    Text = "সংকীর্ণ পথের দুর্বৃত্ত"
  },
  Event_7012_ChoiceDesc1 = {Text = "[Withdraw]"},
  Event_7012_Desc = {
    Text = "এটি কেবল একটি ডোমেইন।\nযা তুমি রক্ষা করতে চাও এবং যেখান থেকে পালাতে চাও, সেটিই একক ও অনন্য বাস্তবতা।"
  },
  Event_7012_Name = {
    Text = "অতল গহ্বর"
  },
  Event_7013_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7013_Desc = {
    Text = "\n「সবচেয়ে ঘৃণ্য তুমি।」\nতুমি পাণ্ডুলিপিটা টুকরো টুকরো করে ছিঁড়ে ফেলো, খণ্ডাংশগুলোকে বাতাসে বিক্ষিপ্ত করে দাও, যেন উড়ন্ত পাপড়ির কয়েকটি গুচ্ছে ভেঙে যাচ্ছে।\nকবিতার মানুষ বাতাসে ঘুরপাক খাওয়া অক্ষরগুলোর দিকে তাকিয়ে থাকে, তার ঠোঁটের কোণে আবেশের এক রেখা কুঁকড়ে ওঠে।\n「অসাধারণ...」"
  },
  Event_7013_Name = {
    Text = "সংকীর্ণ পথের দুর্বৃত্ত"
  },
  Event_7014_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7014_Desc = {
    Text = "\nতুমি পোস্টারটা ছিঁড়ে নামিয়ে পেছনে মোম জাদুঘরের তাড়াহুড়ো করে লেখা খরচের হিসাব পেলে।\nলেখার হাত দেখে বোঝা যায়, যার তা সে অঙ্কে না ধৈর্যশীল, না প্রতিভাবান; এই হিসাব কোনোভাবেই গুছিয়ে তোলা সম্ভব নয়।\nতুমি চোখ বুলিয়ে গেলে, আর সবচেয়ে বড় খরচের খাতটি চোখে পড়ল— 「মোমের ভাস্কর্য রক্ষণাবেক্ষণ ও পরিষ্কার-পরিচ্ছন্নতা」।\nকর্মচারীদের খরচ ছিল করুণ রকমের কম; সর্বশেষ খরচের আইটেমে লেখা— ঘোড়ার লোমের 12টি চাবুক, প্রতিটির দাম প্রায় 20 ফ্যাং।\nআরও একটি বিশেষ খরচের খাত ছিল— 「তাদের খাবার」।\n「তারা」 কারা?"
  },
  Event_7014_Name = {
    Text = "অন্ধকারে হাসি"
  },
  Event_7015_ChoiceDesc1 = {
    Text = "[Leave] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7015_Desc = {
    Text = "\"চতুর... এবং একটি সংশোধন উত্তর।\"\nস্বরটি উত্তরের প্রতি আগ্রহী হয়ে উঠল, জলের ভেতর থেকে একটি সিলভার বস্তু উদ্ভাসন হলো।\n\"মনে রেখো, সব কিছুরই মূল্য আছে।\""
  },
  Event_7015_Name = {
    Text = "সীমানার ওপারের কণ্ঠস্বর"
  },
  Event_7016_ChoiceDesc1 = {
    Text = "[Catch the Second Butterfly] একটি কমান্ড কার্ড ধ্বংস করো, এবং Arg1 কালো চিহ্ন গ্রহণ করো।"
  },
  Event_7016_ChoiceDesc2 = {
    Text = "[Linger No Longer]"
  },
  Event_7016_Desc = {
    Text = "ওরা কি আত্মিক মাত্রার বাসিন্দা? নাকি ডিজলিউশন থেকে জন্ম নেওয়া জীবন?\nএই জিজ্ঞাসা বুকে নিয়ে তুমি প্রজাপতির ঝড়ের ভেতর পা বাড়াও।"
  },
  Event_7016_Name = {
    Text = "নসিস টেম্পেস্ট"
  },
  Event_7017_ChoiceDesc1 = {
    Text = "[Observe the Third Butterfly] একটি কমান্ড কার্ড ধ্বংস করো, এবং Arg1 কালো চিহ্ন গ্রহণ করো।"
  },
  Event_7017_ChoiceDesc2 = {
    Text = "[Linger No Longer]"
  },
  Event_7017_Desc = {
    Text = "আঙুলের পেইন অসহনীয় হয়ে ওঠে, আর আপনি তাড়াতাড়ি হাত ছেড়ে দেন।"
  },
  Event_7017_Name = {
    Text = "নসিস টেম্পেস্ট"
  },
  Event_7018_ChoiceDesc1 = {
    Text = "[Leave] 25টি কালো চিহ্ন প্রাপ্ত হও, তবে 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_7018_Desc = {
    Text = "\"তোমরা মানুষদের আর কোনো উত্তর নেই?\"\nকণ্ঠস্বরের মালিক বিরক্ত গর্জন ছাড়ল, পুরো স্থান কেঁপে উঠল তাতে।\n\"লোভী আর অজ্ঞ... এই কারণেই আমি তোমাদের প্রতি ক্লান্ত।\""
  },
  Event_7018_Name = {
    Text = "সীমানার ওপারের কণ্ঠস্বর"
  },
  Event_7019_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7019_Desc = {
    Text = "“চিন্তা কোরো না, আমি শুধু লোভী অতিথিটাকে সামান্য শাস্তি দিয়েছি। কিছু করার নেই—আমি বিয়ার পছন্দ করি না~”"
  },
  Event_7019_Name = {
    Text = "স্মৃতি খণ্ডাংশ: বিয়ার"
  },
  Event_7020_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7020_Desc = {
    Text = "\"গান বন্ধ করো—\"\nতুমি সুরহীন গায়ককে সতর্ক করো, আর তোমার কানকে আর নির্যাতিত হতে দিতে অস্বীকার করো।"
  },
  Event_7020_Name = {
    Text = "সংকীর্ণ পথের দুর্বৃত্ত"
  },
  Event_7021_ChoiceDesc1 = {
    Text = "[Leave] 2 জন জাগরণকারীকে জাগরণ ঘটাও"
  },
  Event_7021_Desc = {
    Text = "তুমি মুখ ফিরিয়ে নিলে, আর দেখলে নিজেকে হারিয়ে ফেলেছ সেই দীর্ঘ করিডোরে।\nঅন্তহীন সেই হলওয়ে ধীরে ধীরে শুষে নেয় তোমার সব ধৈর্য, যতক্ষণ না তুমি খেয়াল করো এক ছোট, জীর্ণ মঞ্চকে।\nতুমি চোখের পাতা ফেলো, আর মঞ্চটি মিলিয়ে যায়।"
  },
  Event_7021_Name = {
    Text = "অন্তিম II"
  },
  Event_7022_ChoiceDesc1 = {
    Text = "[Raise the Goblet] 「মধু মিড」 অর্জন করো"
  },
  Event_7022_Desc = {
    Text = "এক পেয়ালা সোনালি তরল — সন্ধ্যার শেষ আলোর মতো স্বচ্ছ, শরতের শেষে গমক্ষেতের ঢেউয়ের মতো দোদুল্যমান — মধুর মতো মিষ্টি ও মোহনীয় সুগন্ধ ছড়াচ্ছে। এর উপাদান কী? কে এটি এখানে রেখেছে? কেন কেউ এর দেখাশোনা করছে না?\nএই প্রশ্নগুলোর উত্তর পাওয়ার আগেই, একটি রহস্যময় চিন্তা তোমার মনে হামাগুড়ি দিয়ে ওঠে: তোমাকে এখনই, এই মুহূর্তে এটি পান করতে হবে।\nএই মুহূর্তে, তুমি হঠাৎ আগুনে মোহিত পতঙ্গে পরিণত হও, কলসী উদ্ভিদের ফাঁদে পড়া পোকায় রূপান্তরিত হও, নিজেকে সামলাতে না পেরে সেই মিষ্টি মদের পেয়ালাটি তুলে নাও——"
  },
  Event_7022_Name = {
    Text = "মধু মিড"
  },
  Event_7023_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7023_Desc = {
    Text = "তুমি এই দরজাটি পরীক্ষা করার চেষ্টা করলে। তুমি স্পর্শ করতেই দরজাটি মিলিয়ে গেল, আর দূরে কোথাও কিছু একটার খুলে যাওয়ার শব্দ কানে এলো।"
  },
  Event_7023_Name = {
    Text = "অদ্ভুত দরজা"
  },
  Event_7024_ChoiceDesc1 = {
    Text = "[No Action]"
  },
  Event_7024_ChoiceDesc2 = {
    Text = "[Wipe Palm Print]"
  },
  Event_7024_Desc = {
    Text = "ফ্রান্সিসের অফিস শীতল ও কলঙ্কহীন, তার সূক্ষ্ম স্বভাবেরই প্রতিফলন।\nএক কোণে, একটি বাক্সের ওপর তুমি পাঁচ ইঞ্চি বর্গাকার ধুলোর ছাপ খুঁজে পাও।\nছাপটি অদ্ভুত—একটি জন্তুর থাবার রেখা, যার কেন্দ্রে গাঁথা একটি ছোট মানব কন্যার হাতের ছাপ। মনে হয় যেন প্রথমে মেয়েটির হাতের ছাপ পড়েছে, তারপর তার ওপর নেমে এসেছে জন্তুর বিশাল থাবা।\nতুমি হয়তো কল্পনা করতে পারো এক কোমল দৃশ্য—শান্ত জন্তুটি সান্ত্বনার ভঙ্গিতে মেয়েটির হাতের ওপর আলতো করে থাবা রেখে আছে।\nকিন্তু তুমি সত্য জানো—এটি এক নিষ্ঠুর পরীক্ষায় সৃষ্ট সংকর দানবের রেখে যাওয়া চিহ্ন।"
  },
  Event_7024_Name = {
    Text = "দৈত্যপশুর পদচিহ্ন"
  },
  Event_7025_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7025_Desc = {
    Text = "Psyche Deepdive পরীক্ষার বিষয়বস্তুগুলো তোমাকে সম্পূর্ণ ক্লান্ত করে ফেলেছে, আর ক্ষণিকের বিশ্রামও যেন মরুভূমিতে বৃষ্টির মতো মনে হয়।"
  },
  Event_7025_Name = {
    Text = "অসীমের দ্বার"
  },
  Event_7026_ChoiceDesc1 = {
    Text = "[Master] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7026_ChoiceDesc2 = {
    Text = "[এটি নিয়ে যাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_7026_ChoiceDesc3 = {
    Text = "[Disassemble It] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7026_Desc = {
    Text = "তুমি হাঁটছিলে, হঠাৎ পায়ে কিছু লেগে লাথি খেয়ে গড়িয়ে গেল।\nওটা একটি কম্পাস, কাচ ভাঙা আর D-স্লাইমে ঢাকা। সাবধানে উল্টে ধরতেই, তুমি অস্পষ্টভাবে দেখতে পাও পিছনে খোদাই করা মিথাগ বিশ্ববিদ্যালয়ের প্রতীক।"
  },
  Event_7026_Name = {
    Text = "তার পছন্দ"
  },
  Event_7027_ChoiceDesc1 = {
    Text = "[Read the Letter] একটি কমান্ড কার্ড ধ্বংস করো, এবং Arg1টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_7027_ChoiceDesc2 = {
    Text = "[Close the Box]"
  },
  Event_7027_Desc = {
    Text = "একটি চিঠি, আরেকটি চিঠি, তারপর আরও একটি।\nকাগজজুড়ে লেখা তোমার অতীত, আর আঁকা তোমার ভবিষ্যৎ। এক অদ্ভুত মোহবিভ্রমের প্রভাবে তুমি না চেয়েও কাগজ ছিঁড়ে গিলে ফেলতে থাকো।\n「এই? আবার কী পাগলামি শুরু করলে? হাওয়া খাচ্ছ?」\nমার্ফি লাথি মেরে তোমাকে মায়াভ্রম থেকে জাগিয়ে তোলে। বাস্তবে ফিরে এসে তুমি দেখো, তোমার সামনে কিছুই নেই।"
  },
  Event_7027_Name = {
    Text = "অনাকাঙ্ক্ষিত পত্র"
  },
  Event_7028_ChoiceDesc1 = {
    Text = "[Leave] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_7028_Desc = {
    Text = "তোমার কণ্ঠস্বর শুনে মানুষের ছায়াটি থামল, ক্লেমেন্টাইনের কণ্ঠ জলীয় কুয়াশা ভেদ করে এলো।\n「তুমি তো,」 তার কণ্ঠ অস্পষ্ট, ঝাপসা, যেন জলে গলে যাওয়া চাঁদের আলো, 「চিন্তা করো না, তোমার কিছু হবে না, সে চায়, কিন্তু সে পারবে না।」\n「এখানে শেষ হলে, আমরা আবার দেখা করব।」"
  },
  Event_7028_Name = {
    Text = "কুয়াশাবৃত ছায়ামূর্তি"
  },
  Event_7029_ChoiceDesc1 = {
    Text = "[Recipient: Academic Office] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো।"
  },
  Event_7029_ChoiceDesc2 = {
    Text = "[Recipient: My Partner] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো।"
  },
  Event_7029_Desc = {
    Text = "তুমি যখন প্রাপকের নাম লিখে চলেছ, চিঠি থেকে ধোঁয়া উঠতে থাকে। এক অদৃশ্য হাত হঠাৎই তা তোমার মুঠো থেকে ছিনিয়ে নেয়—\nচিবোনোর শব্দের সঙ্গে সঙ্গে, হঠাৎই তোমার দেহ ভারী হয়ে আসে।\nকিন্তু তোমার হাতে ধরা অবশেষটি জানিয়ে দেয়, এই যাত্রা সম্পূর্ণ নিষ্ফল ছিল না।"
  },
  Event_7029_Name = {
    Text = "স্বগতোক্তি"
  },
  Event_7030_ChoiceDesc1 = {
    Text = "[Insert your Silver Key]"
  },
  Event_7030_Desc = {
    Text = "অতিরিক্ত স্যাচুরেটেড D-পঙ্কের ভেতরে যেন কিছু আছে... রৌপ্য চাবি ব্যবহার করে সেটিকে তোমার নিজস্ব শক্তিতে রূপান্তর করো।"
  },
  Event_7030_Name = {
    Text = "নিষ্কাশন বিন্দু"
  },
  Event_7031_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7031_Desc = {
    Text = "তাদের ছায়া থেকে উদ্ভাসিত হওয়ার অপেক্ষায় থাকা যাক।"
  },
  Event_7031_Name = {
    Text = "ল্যান্টার্ন-ক্রো"
  },
  Event_7032_ChoiceDesc1 = {
    Text = "[Call the Crow] 35টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 দক্ষতা বিকশিত করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_7032_ChoiceDesc2 = {
    Text = "[Get Far Away]"
  },
  Event_7032_Desc = {
    Text = "অন্ধকার পাখিগুলো উদ্দীপনায় ফুলে ওঠে, আর তোমার হাতে কিছু উগরে দেয়।\nতারা আবার মাস্তুলে ফিরে গিয়ে তীক্ষ্ণ দৃষ্টিতে তোমার দিকে তাকিয়ে থাকে।"
  },
  Event_7032_Name = {
    Text = "নির্বাসিত কাক"
  },
  Event_7033_ChoiceDesc1 = {
    Text = "[Enter Cave]"
  },
  Event_7033_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7033_Desc = {
    Text = "\"কাঁশ, কাঁশ, কাঁশ...\"\nকী ভয়ংকর পরিচিত কণ্ঠস্বর... আমি মনে করতে পারছি, স্কুইক!\nমানুষেরা এই শব্দ করে যখন তারা অসুস্থ থাকে, অথবা মৃত্যুর দ্বারপ্রান্তে!\nতাড়াতাড়ি গিয়ে দেখে আসো, স্কুইক!"
  },
  Event_7033_Name = {
    Text = "গুহার গভীরে"
  },
  Event_7034_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7034_Desc = {
    Text = "তুমি সিলভারদের সম্পর্কে সবকিছুই অধ্যয়ন করেছ, তাদের গ্রেড কীভাবে নির্ণয় করতে হয় তাও।\nস্পষ্টই বোঝা যায়, এই সিলভারগুলো পরিশোধনের ন্যূনতম শর্তও পূরণ করে না।\nতোমাকে এগুলো ত্যাগ করতেই হবে, সঙ্গে সম্ভবত বন্দী হয়ে থাকা খণ্ডিত আত্মাগুলোকেও।\nত্যাগ করতে শেখা একজন কিপারের জন্য অপরিহার্য পাঠ।"
  },
  Event_7034_Name = {
    Text = "বন্দী আত্মা"
  },
  Event_7035_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7035_Desc = {
    Text = "এটি একটি একমুখী প্যাসেজ; এর মাধ্যমে তুমি প্রবেশদ্বারে ফিরে যেতে পারবে না।"
  },
  Event_7035_Name = {
    Text = "প্যাসেজ"
  },
  Event_7036_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7036_Desc = {
    Text = "যত তাড়াতাড়ি সব শেষ হবে, তত তাড়াতাড়ি আমরা বিশ্রাম পাব। মিথাগ অনুসন্ধান কর্মকর্তারা কখনো বিপদকে ভয় পায় না।"
  },
  Event_7036_Name = {
    Text = "অসীমের দ্বার"
  },
  Event_7037_ChoiceDesc1 = {
    Text = "[দয়া করে সরুন, আমার জরুরি কাজ আছে।]"
  },
  Event_7037_ChoiceDesc2 = {
    Text = "[Would Love to Hear More]"
  },
  Event_7037_Desc = {
    Text = "\"মাফ করবেন, অনুগ্রহ করে একটু থামুন। আপনাকে খুব গম্ভীর আর তাড়াহুড়োতে মনে হচ্ছে; হয়তো আপনি কোনো জটিল দ্বিধার ফাঁদে পড়েছেন।\nকিন্তু বর্তমান বিপদের কারণে কারও উচিত নয় সামগ্রিক দৃষ্টিভঙ্গি কিংবা শান্ত মস্তিষ্ক হারিয়ে ফেলা।\nযেমন ধরুন, গত কয়েক দিন ধরে আমি খুব মনোযোগ দিয়ে সার্বেরাসের কিংবদন্তি আর বর্তমান পরিস্থিতির মধ্যে থাকা বহু অসঙ্গতি নিয়ে ভাবছি।\""
  },
  Event_7037_Name = {
    Text = "অদ্ভুত সঙ্গী II"
  },
  Event_7038_ChoiceDesc1 = {
    Text = "[Receive the Gift]"
  },
  Event_7038_ChoiceDesc2 = {
    Text = "[Decline Kindly]"
  },
  Event_7038_Desc = {
    Text = "ছেলেটি জানালার কার্নিশে বসে, তোমার দিকে তাকিয়ে আছে। সে অনেকক্ষণ ধরে তোমার প্রতীক্ষা করছিল।\n“নাটকটা সাফল্যমণ্ডিত হয়েছে, ধ–ধন্যবাদ।”\n“আমি শিগগিরই চলে যাব... এটা তোমার জন্য একটা উপহার।”\nছেলেটি তার হাত তোমার দিকে বাড়িয়ে দেয়।\nতুমি দেখো, সুন্দর করে মোড়ানো একটি উপহারের বাক্স, যার ভেতর থেকে রক্ত চুঁইয়ে বেরিয়ে এসে ছেলেটির হাত রাঙিয়ে দিচ্ছে।"
  },
  Event_7038_Name = {
    Text = "অন্তিম VI"
  },
  Event_7039_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7039_Desc = {
    Text = "তোমার মধ্যে যেন সবসময় এই ধরনের আত্মবিশ্বাস থাকে—এই কামনা করি।"
  },
  Event_7039_Name = {
    Text = "নিরাকার প্রতিবিম্ব"
  },
  Event_7040_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7040_Desc = {
    Text = "তুমি তুলে নাও এই ছোট, নরম কানটি।\nআঠালো মোমে মোড়া, তা নীরবে শুয়ে থাকে তোমার তালুর কেন্দ্রে।\nতোমার ভেতর জেগে ওঠে প্রবল দায়িত্ববোধ।\nপ্রথমত, বার একেবারেই চলবে না; ওখানকার সঙ্গীত অতিরিক্ত কোলাহলপূর্ণ।\nদ্বিতীয়ত, ওয়েলিংটন গার্ডেন থিয়েটারও বাতিল; তাদের অর্কেস্ট্রা বহু আগেই সেকেলে হয়ে গেছে।\nতারপর...\nতুমি আর তোমার সঙ্গীরা অনায়াসে মেনে নাও যে এখন তোমাদের একটি নতুন ছোট্ট পোষা প্রাণী হয়েছে।"
  },
  Event_7040_Name = {
    Text = "কান পেতে শোনো"
  },
  Event_7041_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7041_Desc = {
    Text = "\"প্রফেসর অ্যালিস্টেয়ারই মিথ্যাগের ভিত্তিস্তম্ভ। তাকে ছাড়া সবকিছুই অচল হয়ে যাবে।\"\nতুমি আবছাভাবে মনে করতে পারো, তন্দ্রাচ্ছন্ন এক ক্লাসে চজোর্ট এই কথাগুলো বলছিল, কঠোর অভিব্যক্তি নিয়ে ব্ল্যাকবোর্ডে টোকা দিচ্ছিল।\nযদি এই ভিত্তিস্তম্ভই প্রাচীর পতন ঘটায়, তুমি কীভাবে তা সামলাবে? এক গভীর আতঙ্ক তোমাকে গ্রাস করে।\n\"কোথায় যাচ্ছ?\" র‍্যামোনার কণ্ঠ তোমাকে বাস্তবে ফিরিয়ে আনে।\nওটা কি অতীত ছিল, না ভবিষ্যৎ, বাস্তব না কল্পিত, নাকি অন্য কোনো মাত্রার স্বপ্ন? তুমি বুঝতে পারো না।\nতোমার হাতে এক \"উপহার\" উদ্ভাসিত হয়।"
  },
  Event_7041_Name = {
    Text = "বিশৃঙ্খলার আর্তনাদ"
  },
  Event_7042_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7042_Desc = {
    Text = "「এই হুইলচেয়ারটাই আমার দ্বিতীয় জোড়া পা; এই জীবনে সম্ভবত আর কখনোই এটা ছাড়া থাকতে পারব না, 」 অ্যালিস্টেয়ার অধ্যাপক তিক্ত হাসি হেসে বললেন, 「কিন্তু দুর্ভাগ্য এই যে, এটা আমাকে অনেক খাটো বানিয়ে দিয়েছে।」\n\nসুতরাং, এ আসল অ্যালিস্টেয়ার অধ্যাপক হতে পারে না।"
  },
  Event_7042_Name = {
    Text = "বিশৃঙ্খলার আর্তনাদ"
  },
  Event_7043_ChoiceDesc1 = {
    Text = "[কে কথা বলছে？]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_7043_ChoiceDesc2 = {
    Text = "[কী হুইস্কি, আমাকেও চেখে দেখো]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_7043_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7043_Desc = {
    Text = "\n「তুমি সত্যিই এক চুমুকও নেবে না? এটা কিন্তু প্রিমিয়াম হুইস্কি। বার-মালিক যদি আমাকে পুরো বোতলটা দান না করত, তোমার সঙ্গে এক ফোঁটাও ভাগ করে খাওয়ার সাহস পেতাম না।」\n「তাহলে, তুমি তাকে সাহায্য করেছ সেই কান্ত, রাবারের চামড়ার লোকটাকে সরাতে, যে শুধু ব্লাডি মেরি খায়? ওই তদন্তের পুরস্কার হিসেবে মালিক তোমাকে এটুকুই দিয়েছে। তুমি এক মাস সময় দিয়েছ, ত্রিশটা বাড়িতে গিয়েছ, এগারোটা বন্ধ দরজার মুখোমুখি হয়েছ, আর সতেরোটা রিভলভার বুলেট ক্ষয় করেছ। এক বোতল হুইস্কি, আর তাতেও তোমার খরচ ওঠে না।」\n「আচ্ছা, আচ্ছা, এত কৃপণ হয়ো না। অন্তত এখন আমাদের কাছে এই বোতল হুইস্কি তো আছে, তাই না?」"
  },
  Event_7043_Name = {
    Text = "স্মৃতির খণ্ডাংশ: হুইস্কি"
  },
  Event_7044_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7044_Desc = {
    Text = "তুমি জাগরণকারীর শুঁড়গুলো আঁকড়ে ধরো; সে ঘুরে তোমার দিকে তাকায়, চোখে এক দুর্বোধ্য আলো ঝলসে ওঠে।\nসে কিছু বলে না, তবু তুমি গোপন বার্তাটি বুঝে ফেলো—\n「সীমা লঙ্ঘন।」"
  },
  Event_7044_Name = {
    Text = "বাটারফ্লাই ইফেক্ট"
  },
  Event_7045_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7045_Desc = {
    Text = "\"টেলিগ্রাফ মেশিনটি সম্পূর্ণ ভেঙে গেছে। তুমি কল্পনা করতে পারো, ঝড়ের রাতে তার মালিকের হতাশা কেমন ছিল... ঠিক যেমনটা তুমি এখন অনুভব করছ।\""
  },
  Event_7045_Name = {
    Text = "প্রাচীন উত্তরাধিকার"
  },
  Event_7046_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7046_Desc = {
    Text = "নাম: লেই\nবয়স: 20\nজটিলতা: তীব্র হিস্টিরিয়াসহ রক্তপিপাসা\nহাইপারপ্লাসিয়া: গাঢ় লাল শুঁড় @2 মুখাঙ্গ\nগ্রাফট: সরাসরি রক্তের আত্মীয়দের অঙ্গপ্রত্যঙ্গ ও টিস্যু @3\nস্থানান্তরের কারণ: বিশেষ কোনো কারণ নেই। আমি শুধু ওকে পছন্দ করি না।\n(বাকি অংশ কেটে ফেলা হয়েছে)"
  },
  Event_7046_Name = {
    Text = "অঙ্গ নিবন্ধন"
  },
  Event_7047_ChoiceDesc1 = {
    Text = "[Receive Blessing] সব কালো চিহ্ন হারাও। একটি সোনার রেলিক অর্জন করো।"
  },
  Event_7047_Desc = {
    Text = "তোমার সামনে এক দলা কালো আঠালো বস্তু উদ্ভাসিত হয়, কাঁপতে কাঁপতে একটি নথি এগিয়ে দেয়।\n「আমি এখন বাইরে আসতে পারছি না... তবে তুমি আমাদের কাস্টম পরিষেবাগুলো দেখে নিতে পারো...」\nওই আঠালো দেহের বুকের ভেতর থেকে এক নারীর কণ্ঠ ভেসে আসে, সামান্য আতঙ্কিত, যেন কোনো কিছুর আড়ালে লুকিয়ে আছে।\n「ফেয়ারি আশীর্বাদ সদস্যপদ স্তরের ভিত্তিতে সক্রিয় হয়, সবার জন্য ন্যায্যতা নিশ্চিত।」\n「সই করো, তাড়াতাড়ি!」"
  },
  Event_7047_Name = {
    Text = "পরীর আশীর্বাদ"
  },
  Event_7048_ChoiceDesc1 = {
    Text = "[Listen Closely] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_7048_ChoiceDesc2 = {
    Text = "[Inspect] সকল জাগরণকারী 50 অ্যালিমাস পাবে, কিন্তু তুমি 「(Skill.Arg1)」 দক্ষতা বিকশিত করবে।"
  },
  Event_7048_ChoiceDesc3 = {
    Text = "[Leave Directly] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_7048_Desc = {
    Text = "「জানো কি?」 রহস্যময় সেই অবয়বটিকে খুঁজতে খুঁজতে রামোনা যখন অগ্রসর হচ্ছিল, হঠাৎই এক কণ্ঠ হুইসপার করে উঠল, 「তুমি কি সেই ব্যাপারটা জানো? সেই ভয়াবহভাবে গুরুত্বপূর্ণ ব্যাপারটা?」"
  },
  Event_7048_Name = {
    Text = "অপরের কান"
  },
  Event_7049_ChoiceDesc1 = {
    Text = "[Focus] সর্বোচ্চ 2টি উপসর্গ কার্ড Destroy করো।"
  },
  Event_7049_ChoiceDesc2 = {
    Text = "[Meditate] একজন Awakener-কে Rouse করো।"
  },
  Event_7049_ChoiceDesc3 = {
    Text = "[Connect] Arg2 HP পুনরুদ্ধার করো।"
  },
  Event_7049_Desc = {
    Text = "কুয়াশা ভারী হয়ে ঝুলে থাকে, আর তোমার ব্যাজে মিটমিট করে ফ্যাকাশে সিলভার আভা। যোগাযোগকারীটা কড়কড় শব্দ তুলে জেগে ওঠে। কেউ একজন ডাকছে।"
  },
  Event_7049_Name = {
    Text = "সংযোগস্থল"
  },
  Event_7050_ChoiceDesc1 = {
    Text = "[Handle Carefully] সর্বোচ্চ HP Arg1 বৃদ্ধি পায়"
  },
  Event_7050_ChoiceDesc2 = {
    Text = "[সামনে এগিয়ে যাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」, সংক্রমিত করুন「(Skill.Arg2)」"
  },
  Event_7050_Desc = {
    Text = "ডোমেইন ডেকে আনা এক ছায়া তোমার দিকে হাত বাড়ায়, তার অবয়ব অস্পষ্ট।\nতুমি মনে করো, একসময় এক মিথাগ অনুসন্ধান কর্মকর্তা এই জাহাজে পা রেখেছিল। তবে কি সে-ই?\nনাকি এ কেবল ডোমেইনের শৃঙ্খলে বাঁধা আরেকটি করুণ স্মৃতি?"
  },
  Event_7050_Name = {
