  },
  Event_7051_Desc = {
    Text = "「দেখো, আমার একখানা হালকা মন্তব্যের কারণে আমি সবচেয়ে জরুরি পরিস্থিতিটাই চোখ এড়িয়ে গিয়েছিলাম, যা মোটেই ভালো হয়নি।\nআর দেরি করলে তোমার শিকার অনেক দূরে পালিয়ে যাবে।\nক্ষমা চাওয়ার নিদর্শন হিসেবে, এগুলো তোমার জন্য।」\n\nলোকটি অন্য প্রসঙ্গে বকবক করতে করতে তোমার হাতে একটি বস্তু তুলে দেয়।"
  },
  Event_7051_Name = {
    Text = "অদ্ভুত সঙ্গী II"
  },
  Event_7052_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7052_Desc = {
    Text = "\"তোমার কামনা যেন পূর্ণ হয়।\"\nলোকটি কাঁধ ঝাঁকাল এবং সরে দাঁড়াল, সামনে পথ খুলে দিল।"
  },
  Event_7052_Name = {
    Text = "অদ্ভুত সঙ্গী II"
  },
  Event_7053_ChoiceDesc1 = {Text = "[Take It]"},
  Event_7053_Desc = {
    Text = "প্রায় পারদের মতো এক সিলভার পদার্থ, D-পঙ্ক থেকে পরিশোধিত, তীব্র মানসিক শক্তিতে পরিপূর্ণ, আচার অনুষ্ঠানে আরও অধিক জাগরণকারীকে সংযুক্ত করতে ব্যবহৃত হয় প্রায় পারদের মতো এক সিলভার পদার্থ, D-পঙ্ক থেকে পরিশোধিত, তীব্র মানসিক শক্তিতে পরিপূর্ণ, আচার অনুষ্ঠানে আরও অধিক জাগরণকারীকে সংযুক্ত করতে ব্যবহৃত হয়।"
  },
  Event_7053_Name = {
    Text = "সিলভার"
  },
  Event_7054_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7054_Desc = {
    Text = "তুমি পথের এক নতুন দ্বিখণ্ডনে পা বাড়াও।\nসূর্য প্রতিদিনের মতোই ওঠে, মানুষ প্রতিদিনের মতোই মরে, আর তুমি প্রতিদিনের মতোই পথ হারাও।\nকিছুই আর নতুন লাগে না।"
  },
  Event_7054_Name = {
    Text = "চোখের গোলকধাঁধা"
  },
  Event_7055_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7055_Desc = {
    Text = "এটি যেন আলোয় প্রতিফলিত এক বিকৃত ছায়া।"
  },
  Event_7055_Name = {
    Text = "পিপার ভাসমান বস্তু"
  },
  Event_7056_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7056_Desc = {
    Text = "তুমি ঘুরে দাঁড়িয়ে দেখো এক জোড়া একাকী চামড়ার জুতো।\n\"মাফ করবেন, আমার কোনো খারাপ উদ্দেশ্য নেই।\"\n\"আপনি যদি আমার শরীরটা খুঁজে পান, তাকে বলবেন তার সবচেয়ে বিশ্বস্ত হাঁটার সঙ্গী অপেক্ষা করছে প্রদর্শনী কক্ষ ১-এর, প্রদর্শনী কেস ৪৫-এ।\"\n\"—মনে রাখবেন, গরুর চামড়ারটা, ছাগলের চামড়ারটা নয়।\""
  },
  Event_7056_Name = {
    Text = "অক্সফোর্ডস"
  },
  Event_7057_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7057_Desc = {
    Text = "এটা নিশ্চয়ই সেই প্রাক্তন ছাত্র—তুমি তাকে বুকে টেনে নিতে বাহু মেলো, কিন্তু পরক্ষণেই অস্থিমজ্জা ভেদ করে ঢুকে পড়া এক শীতল যন্ত্রণা তোমাকে গ্রাস করে।\nযন্ত্রণা স্তিমিত হলে, তোমার অঙ্গপ্রত্যঙ্গ অস্বাভাবিকভাবে শক্তিশালী হয়ে ওঠে—আগের যেকোনো সময়ের চেয়ে বেশি।"
  },
  Event_7057_Name = {
    Text = "রৌপ্য চাবির বাহক"
  },
  Event_7058_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7058_Desc = {
    Text = "তোমার সামনে কুয়াশা যেন পাতলা হয়ে আসে।\n\nপরের চালের জন্য তুমি অনুভব করো, তোমার দৃষ্টিক্ষেত্র আরও তীক্ষ্ণ হয়ে উঠছে।"
  },
  Event_7058_Name = {
    Text = "অসুরীয় বিচার"
  },
  Event_7059_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7059_Desc = {
    Text = "মায়াভ্রম ঘনিয়ে আসে, স্মৃতিচারণ প্লাবিত হয়, আর হঠাৎই স্পষ্টতা আঘাত হানে।"
  },
  Event_7059_Name = {
    Text = "মরীচিকা"
  },
  Event_7060_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7060_Desc = {
    Text = "তার অবচেতন মনে অদৃশ্যের আড়ালে কিছু একটাকে বদলে যেতে থাকে।"
  },
  Event_7060_Name = {
    Text = "ঐশ্বরিক দৃষ্টি"
  },
  Event_7061_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7061_Desc = {
    Text = "সংকটের মুহূর্তে, সিলভার কোর সংগ্রহের সময় এখন নয়।"
  },
  Event_7061_Name = {
    Text = "অস্তিত্বের প্রমাণ"
  },
  Event_7062_ChoiceDesc1 = {
    Text = "[Leave] 3টির মধ্যে 1টি রৌপ্য সৃষ্টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_7062_Desc = {
    Text = "অস্পষ্ট অবয়বটি ধীরে ধীরে স্পষ্ট হয়, আর তা না কোনো অবক্ষয়িত সত্তা, না মহাবিপর্যয়ের কোনো লক্ষণ—বরং ডানা-বিহীন, স্বাভাবিক চেহারার এক ক্লেমেন্টাইন。\n「কি কাকতাল, তুমিও কি চাঁদের আলো উপভোগ করতে এসেছ?」 সে হাসিমুখে বলে, আর তোমার মাথায় এক ঢেউ ঘোর ঘুরে ওঠে। 「কুয়াশাচ্ছন্ন রাতে, সাবধানে থেকো。\nএখানকার ছোট্টগুলো কিন্তু খুব ভদ্র নয় বোধহয়।」"
  },
  Event_7062_Name = {
    Text = "কুয়াশাবৃত ছায়ামূর্তি"
  },
  Event_7063_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7063_Desc = {
    Text = "প্লাস্টারের খণ্ড মাটিতে ভেঙে পড়তেই, তার দেহটাও টুকরো টুকরো হয়ে গেল। অনিচ্ছুক হাহাকার তোমার মস্তিষ্ক ভরে দিল, কিন্তু সৌভাগ্যবশত তুমি সময়মতো নিজেকে সরিয়ে নিতে পেরেছিলে।"
  },
  Event_7063_Name = {
    Text = "দেহ পুনর্গঠন"
  },
  Event_7064_ChoiceDesc1 = {
    Text = "[দুঃখ শোনো]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_7064_ChoiceDesc2 = {
    Text = "[Hear Joy] প্রতিটি জাগরণকারী, যার অ্যালিমাস 50 বা তার বেশি, তার জন্য 15টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_7064_ChoiceDesc3 = {
    Text = "[Leave] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_7064_Desc = {
    Text = "\"সুরেলা, গীতিময়, আনন্দময়, শোকাবহ... সেই সুর প্রতিধ্বনিত হচ্ছে ডোমেইনের ভেতর, উৎস যার অস্পষ্ট।\nওটা কি ভূতুড়ে জাহাজের অডিও সিস্টেম থেকে ভেসে আসা সিম্ফনি, নাকি ডোমেইনের ভেতর বন্দী কোনো মধ্যরাত্রির র‍্যাপসোডি?\""
  },
  Event_7064_Name = {
    Text = "নামহীন প্রতিধ্বনি"
  },
  Event_7065_ChoiceDesc1 = {
    Text = "[They're Searching for Someone] একটি কমান্ড কার্ড ধ্বংস করো, এবং 25টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_7065_ChoiceDesc2 = {
    Text = "[They're Searching for Something] একটি কার্ড অনুলিপি করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7065_Desc = {
    Text = "কেন আলোবাহক ভক্তরা রাই-এ উপস্থিত হলো? এখানে রহস্যের শেষ নেই।\nনরককুকুর সের্বেরাস, ফ্রান্সিস, রাই স্যানাটোরিয়ামের পরিচালক, ভাস্কর সমিতি, আলোবাহকদের গির্জা...\nঅবশ্যই এমন কোনো উৎস আছে, যা তাদের সবাইকে এই জনশূন্য শহরে টেনে এনেছে।\nটাইপরাইটার হঠাৎ কালো কালি উগরে দেয়, যেন তোমাকে কিছু লিখতে তাগাদা দিচ্ছে।"
  },
  Event_7065_Name = {
    Text = "প্রহেলিকা ইনপুট"
  },
  Event_7066_ChoiceDesc1 = {
    Text = "[Tightly Close Your Eyes]"
  },
  Event_7066_ChoiceDesc2 = {
    Text = "[Escape Scene]"
  },
  Event_7066_Desc = {
    Text = "অভিনয় হঠাৎ করেই থেমে যায়। তুমি চারদিকে তাকিয়ে দেখো, দর্শকরা চারপাশ ঘিরে বসে আছে।\nতাদের সবার মুখ সেই ছেলেটির মতোই, একসাথে তোমার দিকে চেয়ে আছে।\nআহ—\nতারা নিঃশব্দে তাদের পিচকালো মুখগুলো তোমার দিকে হা করে খুলে দেয়।"
  },
  Event_7066_Name = {
    Text = "অন্তিম V"
  },
  Event_7067_ChoiceDesc1 = {
    Text = "[Pick up the Photo] 3টি কমান্ড কার্ডের মধ্যে 1টিতে 「(EnchantConfig.Arg1)」 নামের প্রার্থনা খোদাই করো।"
  },
  Event_7067_ChoiceDesc2 = {
    Text = "[Check Film] 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো এবং যে প্রার্থনাগাথা খোদাই করা হবে তা বদলাও।(ব্যবহার: 1/2)"
  },
  Event_7067_Desc = {
    Text = "তুমি ফিল্মটাকে ম্লান লাল আলোয় রাখো, আধা-স্বচ্ছ ভিত্তির ভেতর দিয়ে ক্ষীণ সব ছবি ভেসে ওঠে。\nহাত, পা, চোখের বল, অঙ্গপ্রত্যঙ্গ… কল্পনাযোগ্য ও অকল্পনীয় প্রতিটি মানব অঙ্গ ফিল্মে বিশ্বস্তভাবে লিপিবদ্ধ。\nসেগুলো নিখুঁতভাবে পরিষ্কার ও সাজানো, তোমার প্রথম ছন্দবদ্ধ কবিতার মতোই শৃঙ্খলাবদ্ধ।"
  },
  Event_7067_Name = {
    Text = "হুবহু নথি"
  },
  Event_7068_ChoiceDesc1 = {
    Text = "[Princess's Guard] একটি এলোমেলো জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7068_ChoiceDesc2 = {
    Text = "[Thinker] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে যেকোনো একটিতে খোদাই করো।"
  },
  Event_7068_Desc = {
    Text = "\"টক, টক, টক...\"\nদূর থেকে পদধ্বনি এগিয়ে এল, আর তুমি দেখলে কেউ একজন স্টুডিওর বড় দরজাটা ঠেলে খুলতে যাচ্ছে।\nআর পিছু হটার কোনো জায়গা না থাকায়, তুমি কেবলই ম্লান আলোয় মোমের ভাস্কর্য সেজে দাঁড়িয়ে রইলে, সেই অনুসন্ধিৎসু দৃষ্টি থেকে বাঁচার মরিয়া চেষ্টা করে।"
  },
  Event_7068_Name = {
    Text = "নিখুঁত ছদ্মবেশ"
  },
  Event_7069_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7069_Desc = {
    Text = "\"দারুণ, দারুণ!\" কণ্ঠস্বরটি আনন্দে টইটম্বুর। \"তুমি অবশেষে আমার মতোই হয়ে গেছ, সাশা দিদি!\""
  },
  Event_7069_Name = {
    Text = "\"সাশা দিদি\""
  },
  Event_7070_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7070_Desc = {
    Text = "হয়তো কেউ তাদের এখানে নিয়ে এসেছে।\nতুমি অনুসন্ধান চালিয়ে গেলে, একসময় সেই ব্যক্তির পরিচয় অন্ধকার ভেদ করে প্রকাশ পাবে।"
  },
  Event_7070_Name = {
    Text = "প্রহেলিকা ইনপুট"
  },
  Event_7071_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7071_Desc = {
    Text = "যত তাড়াতাড়ি সব শেষ হবে, তত তাড়াতাড়ি আমরা বিশ্রাম পাব। মিথাগ অনুসন্ধান কর্মকর্তারা কখনো বিপদকে ভয় পায় না।"
  },
  Event_7071_Name = {
    Text = "অন্তহীন দ্বারসমূহ"
  },
  Event_7072_ChoiceDesc1 = {
    Text = "[Choose Morality] Arg1 HP পুনরুদ্ধার করো"
  },
  Event_7072_ChoiceDesc2 = {
    Text = "[Choose HP] সব HP পুনরুদ্ধার করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7072_Desc = {
    Text = "কখনও হয়তো তোমার ছিল সোনার হৃদয়।\nদিনরাত নিরলসভাবে তা ধুকপুক করত, তোমার জীবন আর স্বপ্নের জন্য লড়ে যেত... উষ্ণ, উন্মত্ত, আর আশায় পূর্ণ।\nকিন্তু কোনো এক সময়ে, তার গতি ধীর হয়ে গেল। যেন জীবন আর নৈতিকতার মাঝখানে আটকে, সে কেবল একটাকেই বহন করতে পারল।"
  },
  Event_7072_Name = {
    Text = "অভিশপ্ত আকাঙ্ক্ষা"
  },
  Event_7073_ChoiceDesc1 = {
    Text = "[Pick up the Photo] 3টি কমান্ড কার্ডের মধ্যে 1টিতে 「(EnchantConfig.Arg1)」 নামের প্রার্থনা খোদাই করো।"
  },
  Event_7073_ChoiceDesc2 = {
    Text = "[Check Film] 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো এবং যে প্রার্থনাগাথা খোদাই করা হবে তা বদলাও।(ব্যবহার: 2/2)"
  },
  Event_7073_Desc = {
    Text = "\n「তাহলে, তুমি সবকিছু সত্যনিষ্ঠভাবে লিপিবদ্ধ করেছ।」\n「হ্যাঁ, সত্য লুকিয়ে আছে এই ফিল্মের ভেতরেই।」\nআলাপ হঠাৎ থেমে যায়, আর অগণিত অদৃশ্য চোখ তোমার দিকে ঘুরে আসে, যেন তোমার চূড়ান্ত রায়ের অপেক্ষায়।"
  },
  Event_7073_Name = {
    Text = "প্রত্যক্ষদর্শীর বিবরণ"
  },
  Event_7074_ChoiceDesc1 = {
    Text = "[Leave] সর্বোচ্চ HP Arg1 দ্বারা বৃদ্ধি করো এবং 25টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_7074_Desc = {
    Text = "তোমার কণ্ঠ হু হু করে বয়ে যাওয়া বাতাসে গ্রাসিত হয়।\n\"তোমার আমাকে জানার প্রয়োজন নেই,\" হিসহিস শব্দটা আরও স্পষ্ট হয়, \"হার্বার্ট, হার্বার্ট-ই সেইজন, যাকে তুমি খুঁজছ। তাকে মিথ্যা স্বপ্ন থেকে ছিঁড়ে এনে নির্মম, শীতল বাস্তবতায় ফেলে দাও।\"\n\"আমি তোমার ওপর আমার আশীর্বাদ বর্ষণ করব, তোমাকে দেব সবচেয়ে সুস্বাদু...\""
  },
  Event_7074_Name = {
    Text = "অদ্ভুত সঙ্গী VI"
  },
  Event_7075_ChoiceDesc1 = {
    Text = "[Leave] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_7075_Desc = {
    Text = "\n「হ্যাঁ, সেই করুণ পথহারা আত্মা, যার হাতে শক্তি আছে, অথচ নিজেকেই চিনতে অক্ষম।\nতুমি কি সাহায্যের হাত বাড়াবে? নাকি তাঁর বিরুদ্ধেই অস্ত্র তুলবে?」\nলোকটি স্রোতস্বিনী জলে ঝাঁপ দিল। তার দেহ যখন ঠিক পড়ে যেতে চলেছে, ঠিক সেই মুহূর্তে তোমার দৃষ্টি তার সঙ্গে মিলল। সেটি ছিল সোনালি, মধুরঙা, সরু ফাঁকওয়ালা—এক সর্পের তারারন্ধ্রের জোড়া।\nআর যেখানে সে একটু আগে দাঁড়িয়ে ছিল, সেখানে রয়ে গেল বেগুনি ধোঁয়া ছড়ানো একটি ছোট প্রদীপ।"
  },
  Event_7075_Name = {
    Text = "অদ্ভুত সঙ্গী VI"
  },
  Event_7076_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7076_Desc = {
    Text = "\"সতর্কতা এক ধরনের গুণ, কিন্তু অতিরিক্ত সতর্কতা আসলে এক ধরনের অকালপক্বতা,\" একঘেয়ে, অসন্তোষমিশ্রিত কণ্ঠে মন্তব্য ভেসে এল, \"নক্ষত্রপুঞ্জের গতি জাগরণের নিদ্রার জেনেসিসকে ব্যাহত করবে, আর সঠিক সময় নির্বাচন করলে তাদের অ্যালিমাস দ্রুত স্ফীত হবে, যেন ফোলানো বেলুন। সংক্ষেপে বললে, এখনো ধূমকেতুর লেজ ধরার সময় আছে; পরের বার তোমার প্রতিক্রিয়ার গতি—যা এখন কচ্ছপের চেয়েও ভালো নয়—সেটা উন্নত করতে ভুলো না।\""
  },
  Event_7076_Name = {
    Text = "উত্তরণ"
  },
  Event_7077_ChoiceDesc1 = {
    Text = "[Restore] বর্তমান চাপ অর্ধেক কমিয়ে ফেলুন।"
  },
  Event_7077_Desc = {
    Text = "তুমি স্থিতিকরণ চেম্বার স্পর্শ করো, আর তোমার বর্তমান চাপের মাত্রা পুনরুদ্ধার হয়।"
  },
  Event_7077_Name = {
    Text = "ভারসাম্য বিন্দু"
  },
  Event_7078_ChoiceDesc1 = {
    Text = "[তাকে সান্ত্বনা দাও]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」"
  },
  Event_7078_ChoiceDesc2 = {
    Text = "[Blame Her] 3টি এলোমেলো কমান্ড কার্ডের উপর প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7078_Desc = {
    Text = "「আমি মৃত অনুসন্ধান কর্মকর্তার ছায়া, আর খুনি হল ওই রৌপ্য চাবি।」\nমহিলা যন্ত্রণায় মাথা চেপে ধরল। তার ঘন চুলে অসংখ্য ঝলমলে চোখ শোভা পাচ্ছে, টুকটুক করে পলক ফেলছে…\n「ওরা সব সময়ই বলত: না, শার্লট! হায়, শার্লট!\nতাই আমি ভেবেছিলাম, যদি একসাথে অনেক জাগরণকারীকে সংযুক্ত করতে পারি, তবে সকলে চুপ করে যাবে।」\n「তারপর… কী হল আমি জানি না, আর যখন জেগে উঠলাম, আমি এমন হয়ে গেছি। হায়!」"
  },
  Event_7078_Name = {
    Text = "অনুসন্ধানকারীর ছায়া"
  },
  Event_7079_ChoiceDesc1 = {
    Text = "[Climb the Wall] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7079_ChoiceDesc2 = {
    Text = "[গোলকধাঁধায় প্রবেশ করো]যেকোনো 1টি কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg1)」"
  },
  Event_7079_Desc = {
    Text = "তোমার মস্তিষ্ক একটি গোলকধাঁধা।\nঅনেক বেশি চিন্তা সেখানে জড়িয়ে আছে, বের হওয়ার পথ দৃষ্টির নাগালেই, কিন্তু চিন্তার উঁচু দেয়াল তোমাদের মাঝে দাঁড়িয়ে আছে।"
  },
  Event_7079_Name = {
    Text = "মানসিক গোলকধাঁধা"
  },
  Event_7080_ChoiceDesc1 = {
    Text = "[Gaze at Phantasm] 3টি রৌপ্য সৃষ্টি থেকে 1টি অর্জন করো"
  },
  Event_7080_ChoiceDesc2 = {
    Text = "[Near Phantasm] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)「 ও 「(RelicConfig.Arg2)「 অর্জন করো, তবে 「(Skill.Arg3)「 দু」বার বিকশিত করো।"
  },
  Event_7080_Desc = {
    Text = "দূরে যেন কোনো আগ্নেয় শঙ্কু বিস্ফোরিত হয়েছে, আর ঝড়ো আকাশে মানুষের আকৃতির ধোঁয়া উঠছে।\nকিন্তু এটি এলওয়ার্থ, যেখানে আছে কেবল অন্তহীন সুউচ্চ তুষার পর্বত আর চুনাপাথরের কার্স্ট গুহা।\nনিরবচ্ছিন্ন এই অস্বাভাবিকতাগুলো কি তোমাকে আত্মিক বিভ্রান্তির দিকে ঠেলে দিয়েছে?"
  },
  Event_7080_Name = {
    Text = "আগ্নেয়গিরির প্রেতছায়া"
  },
  Event_7081_ChoiceDesc1 = {
    Text = "[What Did I See] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_7081_ChoiceDesc2 = {
    Text = "[I Saw Nothing] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7081_Desc = {
    Text = "তোমার চোখের কোণ থেকে তরল গড়িয়ে পড়ছে, তার আঠালো অনুভূতি অস্বস্তিকর।\nশেষ পর্যন্ত, এর উদ্রেক ঘটিয়েছে তুমি যা দেখেছিলে—নাকি সত্যিই তুমি কিছুই দেখোনি?"
  },
  Event_7081_Name = {
    Text = "অদৃশ্য"
  },
  Event_7082_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7082_Desc = {
    Text = "তুমি আনন্দ অনুভব করেছ। তুমি দুঃখও অনুভব করেছ। এখন তুমি বুঝতে পারো, এগুলো তোমার নিজের অনুভূতি নয়, অন্য কিছুর ঢেউ তোমাকে ভাসিয়ে দিচ্ছিল।\nচোখ বন্ধ করে, কান ঢেকে নিলে রৌপ্য চাবি ঝলসে ওঠে অন্ধকার-চেরা আলোয়।\nসব ঠিক হয়ে যাবে। অবশেষে তুমি গভীর শ্বাস নিতে পারো।"
  },
  Event_7082_Name = {
    Text = "আসক্তি"
  },
  Event_7083_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7083_Desc = {
    Text = "ছোরা-ধারণকারী মধ্যরাতের কবরস্থানের মৃত্যু-পাখির মতো এক আর্তনাদ ছাড়ে।\nশব্দটি মুহূর্তেই মিলিয়ে যায়, আর বাকি দুই সাগরচারীও অদৃশ্য হয়ে যায়... আসলে সবই ছিল ডোমেইনে প্রতিফলিত এক মায়াস্বপ্ন।"
  },
  Event_7083_Name = {
    Text = "নিরলস তাড়া"
  },
  Event_7084_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7084_Desc = {
    Text = "ওটা নীরবে বাতাসে ভেসে থাকে, পলকহীন, তাঁর দৃষ্টি নিবিড়—যেন তোমাকে কিছু বলতে চাইছে।\nচোখে হয়তো আত্মা বাস করে, কিন্তু শব্দহীনতায় তুমি কেবল একটুখানি তাড়াহুড়ো আর সামান্য বিষণ্ণতা অনুভব করতে পারো।\nওটা হাওয়ায় মিলিয়ে যায়।"
  },
  Event_7084_Name = {
    Text = "অন্ধ দৃষ্টি"
  },
  Event_7085_ChoiceDesc1 = {
    Text = "[Agree] 「(RelicConfig.Arg1)」 নামের রৌপ্য সৃষ্টি অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_7085_ChoiceDesc2 = {
    Text = "[Gift] 「(RelicConfig.Arg1)」 নামের রৌপ্য সৃষ্টি অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_7085_ChoiceDesc3 = {
    Text = "[Turn and Leave] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7085_Desc = {
    Text = "\n「যদি কোনো একদিন আমার পতন অবধারিত হয়, তবে আমি চাই জলে ডুবে পড়তে।\nনাসারন্ধ্র ঢেকে রাখা প্রবাহমান জল যেন এক কোমল পুরোনো স্বপ্নের মতো লাগে।\nযে তরলে আমি ডুবে যাই\nসেটাই সেই বাটি, যা @2 সবচেয়ে বেশি কামনা করে।」"
  },
