  },
  Event_7086_ChoiceDesc2 = {
    Text = "[Extract Aliemus] 2 জন এলোমেলো জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)「 দু」বার বিকশিত করো।"
  },
  Event_7086_Desc = {
    Text = "খণ্ডিত মাত্রাটি ধীরে ধীরে ভেঙে পড়ে, আর অন্য মাত্রা থেকে আসা মায়াভ্রমগুলো উন্মত্ত কক্ষে প্লাবিত হয়।"
  },
  Event_7086_Name = {
