  },
  Event_7087_Desc = {
    Text = "মেয়েটি থেমে যায়, আঙুল দিয়ে তার স্কার্ট ঝাড়ে।\n「আমি তোমার জন্য যা করতে পারি... তার সীমা এতটুকুই।」"
  },
  Event_7087_Name = {
    Text = "সাদা পোশাকের কিশোরী"
  },
  Event_7088_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7088_Desc = {
    Text = "কে কথা বলছে?\nতুমি মাথা নিচু করলে, শুধু একটি ঝাপসা প্রতিফলন দেখতে পেলে——সে তোমার মতোই পোশাক পরে আছে, কিন্তু হাতে একটি ছুরি ধরে তোমার দিকে হাসছে।"
  },
  Event_7088_Name = {
    Text = "যা তোমার খোঁজা উচিত নয়"
  },
  Event_70892_ChoiceDesc1 = {
    Text = "[Follow the Body's Memory] যুদ্ধ এড়িয়ে গিয়ে তাৎক্ষণিক জয় লাভ করো, তবে Arg1 HP হারাও।"
  },
  Event_70892_ChoiceDesc2 = {
    Text = "[Leave] যুদ্ধে প্রবেশ করুন"
  },
  Event_70892_Desc = {
    Text = "শত্রু অসাধারণ শক্তিশালী হলেও, তাদের পরাস্ত করার কৌশলে তুমি ইতোমধ্যেই সিদ্ধহস্ত।"
  },
  Event_70892_Name = {
    Text = "পেশি স্মৃতি"
  },
  Event_7089_ChoiceDesc1 = {
    Text = "[Rake Koum]"
  },
  Event_7089_ChoiceDesc2 = {
    Text = "[Attack the Test Subject]"
  },
  Event_7089_Desc = {
    Text = "কৌম পরীক্ষামূলক বিষয়টির ঘাড়ের পেছনে কামড় বসিয়ে তাকে ছুড়ে ফেলার প্রস্তুতি নিচ্ছিল। হঠাৎ, বিষয়টি পেঁচার মতো মাথা 180° ঘুরিয়ে কৌমের মুখে ঠোকর মারল।"
  },
  Event_7089_Name = {
    Text = "অ্যারেনা"
  },
  Event_7090_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7090_Desc = {
    Text = "তুমি রৌপ্য চাবি শক্ত করে ধরে, মাত্রার আলোড়নের ভেতর দিয়ে জেনেসিসের আহ্বান অনুভব করো।\nঅজানা দুষ্ট নরককুকুরের সঙ্গে লড়তে হলে, তোমাকে সম্ভাব্য সব শক্তিই ব্যবহার করতে হবে।"
  },
  Event_7090_Name = {
    Text = "মাত্রিক মায়াচিত্র"
  },
  Event_7091_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7091_Desc = {
    Text = "\n「ওই অনুসন্ধান কর্মকর্তার ব্যাপারে, কিউরেটর নিজেই তাকে জেরা করার ইচ্ছা পোষণ করেছেন...\nজীবিত ধরে আনো...」\nকণ্ঠস্বরটি ধীরে ধীরে ক্ষীণ হয়ে এলো, শেষমেশ অন্ধকারে মিলিয়ে গেল।"
  },
  Event_7091_Name = {
    Text = "গোপন শ্রোতা"
  },
  Event_7092_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7092_Desc = {
    Text = "হঠাৎ ভরশূন্যতার অনুভূতি তোমাকে ঝাঁকুনি দিয়ে জাগিয়ে তোলে। পায়ের নিচের মাটি দৃঢ় ও নির্ভরযোগ্য লাগে, আর তোমার পায়ের কাছে পড়ে আছে এক অপূর্ব বর্গাকার আয়না।"
  },
  Event_7092_Name = {
    Text = "আয়নার ভেতর আয়না"
  },
  Event_7093_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7093_Desc = {
    Text = "তুমি কখনো উন্মাদনায় ডুবে যাওয়া, নিরাময়ের অতীত মানুষের সাথে তর্ক করো না, এটা মধ্যরাতের জিজ্ঞাসায় তোমার আত্মাকে সম্পূর্ণরূপে গ্রাস করবে — নিজেকে রক্ষা করো!"
  },
  Event_7093_Name = {
    Text = "জলীয় আচার"
  },
  Event_7094_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7094_Desc = {
    Text = "মোমের ভাস্কর্যের মুখটা কেমন হওয়া উচিত?\nতুমি চোখ বুজতেই অসংখ্য ঝাপসা মুখ ভেসে ওঠে মনে।\nওগুলো যেন ফ্যাকাসে শিখাওয়ালা মোমবাতি, অন্ধকার নদীতে ভেসে ওঠে, আবার মিলিয়ে যায়...\nতুমি নদীর স্রোত ধরে এগিয়ে যেতে যেতে তার শেষ প্রান্তে পৌঁছাও, যেখানে একমাত্র, চূড়ান্ত মোমের ভাস্কর্যটি দাঁড়িয়ে আছে।\nতুমি যখন তার কাছে এগিয়ে যাও, তখন দেখো...@2।"
  },
  Event_7094_Name = {
    Text = "অসমাপ্ত মোমের ভাস্কর্য"
  },
  Event_7095_ChoiceDesc1 = {
    Text = "[Attack the Dagger-Wielder] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু বিকশিত করো 「(Skill.Arg1)」।"
  },
  Event_7095_ChoiceDesc2 = {
    Text = "[Ambush the Blade-Wielder] রৌপ্য সৃষ্টি 「(RelicConfig.Arg2)「 এবং 「(RelicConfig.Arg3)「 অর্জন করো, তবে 「(Skill.Arg1)「 দু」বার বিকাশ করো।"
  },
  Event_7095_ChoiceDesc3 = {
    Text = "[Trip the Spear-Wielder] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_7095_Desc = {
    Text = "তিনজন সাগরচারী তোমাকে শক্ত করে জাপটে ধরে আছে, তাদের উন্মত্ত, দাউদাউ দৃষ্টি প্রায় তোমার চাদরটাকেই আগুন ধরিয়ে দিচ্ছে।\nএকবার পেছনে তাকিয়ে তুমি বুঝতে পারো, তিনজনই আলাদা—\nবৃহৎ ধারালো অস্ত্রধারী সাগরচারীটি সবচেয়ে হিংস্রভাবে চিৎকার করছে, অথচ তার আচরণে এক ধরনের অসাবধানতা লেগে আছে।\nবর্শাধারী সাগরচারীটি একসঙ্গে, তাল মিলিয়ে নড়ছে, যেন কথা শেখা কোনো শিশু।\nআর ছোরা আঁকড়ে ধরা সাগরচারীটি সবসময় একটু পিছিয়ে থাকে, তার মুখের নীরব প্রার্থনার বকবকানি তার উন্মত্ততাকেই প্রমাণ করে।"
  },
  Event_7095_Name = {
    Text = "নিরলস তাড়া"
  },
  Event_7096_ChoiceDesc1 = {
    Text = "[Leave] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_7096_Desc = {
    Text = "তুমি সাবধানে উপহারের মোড়ক খুললে।\nএক জোড়া চোখ শান্তভাবে শুয়ে আছে বাক্সের ভেতর।\n「আমি তোমাকে আমার চোখ দিচ্ছি।」\n「যেমন সে একদিন আমায় দিয়েছিল।」"
  },
  Event_7096_Name = {
    Text = "অন্তিম VI"
  },
  Event_7097_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7097_Desc = {
    Text = "আলোর কেন্দ্র ভেদ করে তুমি হাত বাড়িয়ে এক কঠিন হয়ে যাওয়া রূপা তুলে নাও। স্মৃতি আর আত্মার এই মূল্যবান পাত্রটি দগদগে উত্তাপে জ্বলছে, অদ্ভুত রঙের প্রতিফলন ছড়িয়ে।\nসমস্ত আলো বিকৃত হয়ে যাওয়ার আগেই, দহনময় যন্ত্রণা তোমাকে বাধ্য করে সেটিকে আবার অন্ধকারে নিক্ষেপ করতে।"
  },
  Event_7097_Name = {
    Text = "নিশাদ্যুতি"
  },
  Event_7098_ChoiceDesc1 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7098_Desc = {
    Text = "তুমি ছেলেটির উপহার প্রত্যাখ্যান করেছো।\nছেলেটি ফাঁপা চোখে তোমার দিকে তাকিয়ে রইল। সে আস্তে নিঃশ্বাস ফেলল।\n「তাহলে, বিদায়।」\nএই কথাগুলো বলেই ছেলেটি মাথা নত করার ভঙ্গি করে জানালা দিয়ে নিচে পড়ে গেল।\nসে মিলিয়ে গেল, যেন নাচতে থাকা কোনো প্রজাপতি, কিংবা বয়ে যাওয়া হাওয়ার ঝাপটা।"
  },
  Event_7098_Name = {
    Text = "অন্তিম VI"
  },
  Event_7099_ChoiceDesc1 = {
    Text = "একটি সাধারণ প্রার্থনাগাথা বেছে নিন"
  },
  Event_7100_ChoiceDesc1 = {
    Text = "[Accept Ear] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7100_ChoiceDesc2 = {
    Text = "[Reject Request] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_7100_Desc = {
    Text = "আঙুলের ডগা থেকে ঝরে পড়ে সুশোভিত সুরের ধারা।\nবিষণ্ণ মোমের পিয়ানোবাদক একা বসে আছে জানালার ধারে।\nচেতনা লাভের পর থেকে মোম জাদুঘরই তার সমগ্র জগৎ।\nসে শুনতে চায় কিছু ভিন্ন, বিশেষ করে... জ্যাজ নামের এক ধরনের সঙ্গীত।\nশেষ পর্যন্ত, সে নিজের এক কান ছিঁড়ে আপনাকে দেয়, সঙ্গে নিতে অনুরোধ করে।\n“বাইরের সঙ্গীতটা আমাকে শুনতে দিও... শুধু পকেটে করে নিয়ে যেয়ো।”"
  },
  Event_7100_Name = {
    Text = "কান পেতে শোনো"
  },
  Event_7101_ChoiceDesc1 = {
    Text = "[Connect] Arg2 HP পুনরুদ্ধার করুন। [ExDesc1]"
  },
  Event_7101_ChoiceDesc2 = {
    Text = "[Meditate] এক জন জাগরণকারীকে জাগরণ করুন। [ExDesc1]"
  },
  Event_7101_ChoiceDesc3 = {
    Text = "[Expel] সর্বোচ্চ 3টি উপসর্গ কার্ড ধ্বংস করো, এবং Arg2 সংখ্যক কালো চিহ্ন লাভ করো।"
  },
  Event_7101_Desc = {
    Text = "কুয়াশা ভারী হয়ে ঝুলে থাকে, আর তোমার ব্যাজে মিটমিট করে ফ্যাকাশে সিলভার আভা। যোগাযোগকারীটা কড়কড় শব্দ তুলে জেগে ওঠে। কেউ একজন ডাকছে।"
  },
  Event_7101_Name = {
    Text = "সংযোগস্থল"
  },
  Event_7101_Tips3 = {
    Text = "আপনার বর্তমানে কোনো উপসর্গ প্রকাশ পাচ্ছে না।"
  },
  Event_7102_ChoiceDesc1 = {
    Text = "[Accept Challenge]"
  },
  Event_7102_ChoiceDesc2 = {
    Text = "[Punch It] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7102_Desc = {
    Text = "ছায়া থেকে এক কৃশকায় অবয়ব বেরিয়ে এসে তোমার পথ রোধ করে।\nচিরতরে বাঁধা এক স্মৃতি এই ডোমেইনে অনধিকার প্রবেশ করে, নিজেকে ঘোষণা করে 「N」 নামে। আবির্ভাবটি হাতে ধরা চিপগুলো ছুড়ে খেলায়, স্তব্ধ গুঞ্জনে তোমাকে আহ্বান জানায় তাঁর খেলায় যোগ দিতে।\nত্রিবর্ণ চিপগুলো তোমার সামনে বিছিয়ে পড়ে; তুমি তাঁর সঙ্গে কোনো 「খেলা」 না খেললে, তিনি যেন তোমাকে ছাড়তে মোটেই রাজি নন।"
  },
  Event_7102_Name = {
    Text = "প্রদর্শনীর সময়"
  },
  Event_7103_ChoiceDesc1 = {
    Text = "[Insert your Silver Key]"
  },
  Event_7103_Desc = {
    Text = "অতিরিক্ত স্যাচুরেটেড D-পঙ্কের ভেতরে যেন কিছু আছে... রৌপ্য চাবি ব্যবহার করে সেটিকে তোমার নিজস্ব শক্তিতে রূপান্তর করো।"
  },
  Event_7103_Name = {
    Text = "নিষ্কাশন বিন্দু"
  },
  Event_7104_ChoiceDesc1 = {
    Text = "[Struggle Awake] সর্বোচ্চ HP Arg1 দ্বারা বৃদ্ধি করুন"
  },
  Event_7104_ChoiceDesc2 = {
    Text = "[নিজেকে গভীর নিদ্রায় ছেড়ে দাও]এলোমেলো 2টি কমান্ড কার্ড অরিসন পাবে：「(EnchantConfig.Arg1)」，2টি「(Skill.Arg2)」সংক্রমিত করো"
  },
  Event_7104_Desc = {
    Text = "তুমি বুকে জড়িয়ে ধরেছ এক ঝলমলে রত্ন।\nতা তোমার বক্ষ থেকে বিস্তার লাভ করে, দেহময় ভরে তোলে মোমবাতির আলোয় উষ্ণ স্মৃতিচারণ, শেষে প্লাবিত হয়ে ঢুকে পড়ে তোমার মস্তিষ্কে।\nটুকটুক করে জ্বলা অঙ্গার, অগ্নিকুণ্ডের পাশে আরামদায়ক আরামকেদারা, গাঢ় গরম চা, আর পায়ের কাছে গুটিসুটি মেরে শুয়ে থাকা এক বিড়াল...\nএই সান্ত্বনাময় তন্দ্রায় তোমার চিন্তা কুয়াশাচ্ছন্ন হয়ে আসে, আর তুমি ধীরে ধীরে নরম তন্দ্রায় ডুবে যাও।"
  },
  Event_7104_Name = {
    Text = "অতীতের আলিঙ্গন"
  },
  Event_7105_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7105_Desc = {
    Text = "তুমি নির্মমভাবে ক্যামেরার ভেতরে লুকিয়ে থাকা আরেকটি ফিল্ম স্ট্রিপ টেনে বের করলে, আর তাতে ফুটে ওঠা ছবিগুলো তোমার বাকরুদ্ধ কণ্ঠকে আরও ভারী করে তুলল।\nঅপ্রসেস করা সেই ফিল্ম বিশ্বস্তভাবে ধারণ করে রেখেছে— তুমি নিজে, কালো কাদার পাঁকে লুটিয়ে আছ।"
  },
  Event_7105_Name = {
    Text = "নির্দোষতার নথি"
  },
  Event_7106_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7106_Desc = {
    Text = "তুমি ক্যামেরাটি মনোযোগ দিয়ে পরীক্ষা করো; তার চামড়া আর কালো-সোনালি ইনলে থেকে মসৃণ এক দীপ্তি ঝরে。\nলেন্সটি তোমার দিকে তাক করা, যেন নীরবে চেয়ে আছে, গোপনে অনুসন্ধান করছে…"
  },
  Event_7106_Name = {
    Text = "নির্দোষতার নথি"
  },
  Event_7107_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7107_Desc = {
    Text = "এক মুঠো চাঁদের আলো, তালুতে জড়ো করে পাথরের ফলকের ওপর ছিটিয়ে দেওয়া হলো।\nকারও দেহ ঘন কাদার নিচে পুঁতে রাখা হয়েছিল, আর দর্শকেরা বলেছিল, ওটা স্বাভাবিক মৃত্যু, তারা নাকি মাটির নিচে শান্তিতে বিশ্রাম নেবে।\nকিন্তু পোঁতা কাদা ফুঁসে উঠল, আর চিৎকারের মাঝখানে, এক অবশ চাঁদ হামাগুড়ি দিয়ে বেরিয়ে এলো।"
  },
  Event_7107_Name = {
    Text = "মুন সিলভার শার্ড"
  },
  Event_7108_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7108_Desc = {
    Text = "তুমি আলতো করে প্রজাপতির কোমল কালো ডানায় স্পর্শ করো। সে মৃদু কাঁপে, তারপর পিচকালো ফোঁটায় রূপান্তরিত হয়ে তোমার তালুতে ঝরে পড়ে।"
  },
  Event_7108_Name = {
    Text = "যা থাকা উচিত নয়"
  },
  Event_7109_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7109_Desc = {
    Text = "একাকী চাঁদ ঝুলে আছে আকাশের অনেক উঁচুতে, তবু তুমি স্পষ্ট শুনতে পাও তার প্রার্থনা—এক অদ্ভুত মন্ত্রোচ্চারণ, যা পচনের হুইসপারের মতো শোনায়।\nপ্রার্থনা থেমে যায়, আর তুমি যখন সরে যেতে উদ্যত, তখনই তোমার পেছনে আবির্ভূত হয় এক সাদা প্রেতছায়া।\n“যারা ভাগ্য আর প্রার্থনার সীমা লঙ্ঘন করে, তাদের কাছে আশীর্বাদ ও প্রতিশোধ—দু’টিই প্রতিশ্রুতির মতোই এসে পৌঁছায়।”"
  },
  Event_7109_Name = {
    Text = "মুন সিলভার শার্ড"
  },
  Event_7110_ChoiceDesc1 = {
    Text = "[Three Points]"
  },
  Event_7110_ChoiceDesc2 = {
    Text = "[Six Points]"
  },
  Event_7110_ChoiceDesc3 = {
    Text = "[One Point]"
  },
  Event_7110_Desc = {
    Text = "দেখে মনে হচ্ছে আজ তোমার ভাগ্য বেশ ভালো।\nপাশা কেঁপে ওঠে এবং উত্তেজিত গুঞ্জন তোলে।\nতুমি একটি সংখ্যা অনুমান করার সিদ্ধান্ত নাও।"
  },
  Event_7110_Name = {
    Text = "অনন্ত জুয়া"
  },
  Event_7111_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7111_Desc = {
    Text = "এই জুয়াটা এক বিশাল প্রতারণা!\nতুমি 「ট্সেং」 শব্দ তুলে লাফিয়ে উঠে দাঁড়াও, আর সঙ্গে সঙ্গে মাথা ঘোরার ঢেউ এসে ভর করে.\nপাশা থেকে কানে-ফাটা গুঞ্জন বেরোতে থাকে, আর এক প্রলোভনসঙ্কুল কণ্ঠ অবিরত তোমার মনের ভেতর ঘুরপাক খায়:\n「একমাত্র… শেষজন…」"
  },
