  },
  Event_7112_ChoiceDesc3 = {
    Text = "[Put Back in Drawer] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7112_Desc = {
    Text = "তোমার ডেস্কের ডান দিকের দ্বিতীয় ড্রয়ারে একটি একাকী সিলভার কোর পড়ে আছে। তুমি ছুঁতেই, ঝড়ের হুংকার, তুষারকণার ভাঙার শব্দ, আর বাঁশির বিলাপ তোমার কানে ভেসে আসে..."
  },
  Event_7112_Name = {
