  },
  Event_7113_ChoiceDesc1 = {
    Text = "[Listen Closely] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg2)」 অর্জন করো, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7113_ChoiceDesc2 = {
    Text = "[Make a Change] একটি রেলিক ধ্বংস করো এবং একটি পুরস্কার লাভ করো।"
  },
  Event_7113_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7113_Desc = {
    Text = "সব সুরই হৃদয় ছোঁয় না।\nখাঁটি অসঙ্গতি গড়ে তোলে এক বিলাপ।"
  },
  Event_7113_Name = {
    Text = "অসঙ্গতি"
  },
  Event_7114_ChoiceDesc1 = {
    Text = "[Pick It Up] রৌপ্য রেলিক 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7114_ChoiceDesc2 = {
    Text = "[Abandon It] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7114_Desc = {
    Text = "খড়ের গাদার গোপন, পচনধরা কোণে, ফেটে যাওয়া D-চিহ্নের ভেতরে, কিছু একটার নীরব উপস্থিতি লুকিয়ে আছে।"
  },
  Event_7114_Name = {
    Text = "খড়ের গাদার আড়ালে"
  },
  Event_7115_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7115_Desc = {
    Text = "আকৃতিটি আর কাছে আসে না। কিছুক্ষণ তোমার দিকে তাকিয়ে থাকে, তারপর এক মুঠো রৌপ্য বালিতে রূপান্তরিত হয়।"
  },
  Event_7115_Name = {
    Text = "রৌপ্য চাবির বাহক"
  },
  Event_7116_ChoiceDesc1 = {
    Text = "[Hold the Tentacle] তুলুর সাহায্য গ্রহণ করুন"
  },
  Event_7116_Desc = {
    Text = "একটা দীর্ঘশ্বাস ফেলে তুলু এসে তোমার পাশে দাঁড়ায়।\nভারী, বরফশীতল অঙ্গপ্রত্যঙ্গ তোমাকে জড়িয়ে ধরে, শত্রুর মাঝখানে ঝাঁপিয়ে পড়ার তাড়নাকে স্তব্ধ করে দেয়।\n「আমি তোমার সহায় হব, তবে শুধু এই মুহূর্ত পর্যন্ত।」"
  },
  Event_7116_Name = {
    Text = "দূতের অঙ্গীকার"
  },
  Event_7117_ChoiceDesc1 = {
    Text = "[Get the Key]"
  },
  Event_7117_Desc = {
    Text = "\"১, ২, ৩...\nজেনকিন টেবিল থেকে ১০ ফুট দূরে।\nদূরত্বটা খুব বেশি নয়, তবু তার কাছে যেন এক আজীবন পথ।\nতার মনে পড়ে নরম ফিতা, সোনালি প্রজাপতি ক্যান্ডির মোড়ক, আর মায়ের অশ্রু।\nসে অনেক, অনেক কিছুই ভাবল...\nতার দুর্বল দেহ কালো নদী বেয়ে এগোতে লাগল, ইঞ্চি ইঞ্চি করে টেবিলের দিকে।\nচাবিটা ড্রয়ারের ভেতর, আর তা পাওয়ার মূল্য খুবই সহজ: সাহস, দক্ষতা, আর সামান্য ভাগ্য।\nজেনকিনের কাছে সবই আছে, শুধু ভাগ্য ছাড়া।\""
  },
  Event_7117_Name = {
    Text = "চূড়ান্ত চাবি"
  },
  Event_7118_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7118_Desc = {
    Text = "এটা শুধু এক বাজি। তুমি হারবে না।\nজটিল নকশা খোদাই করা মুদ্রাটি আকাশে উঁচুতে ছুড়ে দেওয়া হয়, দ্রুত নেমে এসে তোমার তালুতে গরম হয়ে ওঠে।"
  },
  Event_7118_Name = {
    Text = "কুখ্যাত জুয়াড়ি"
  },
  Event_7119_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7119_Desc = {
    Text = "এটা শুধু এক বাজি। তুমি হারবে না।\nজটিল নকশা খোদাই করা মুদ্রাটি আকাশে উঁচুতে ছুড়ে দেওয়া হয়, দ্রুত নেমে এসে তোমার তালুতে গরম হয়ে ওঠে।"
  },
