  },
  Event_7120_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7120_Desc = {
    Text = "এটা শুধু এক বাজি। তুমি হারবে না।\nজটিল নকশা খোদাই করা মুদ্রাটি আকাশে উঁচুতে ছুড়ে দেওয়া হয়, দ্রুত নেমে এসে তোমার তালুতে গরম হয়ে ওঠে।"
  },
  Event_7120_Name = {
    Text = "কুখ্যাত জুয়াড়ি"
  },
  Event_7121_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7121_Desc = {
    Text = "এই গম্ভীর পিয়ানো পাঠে যোগ দেওয়ার কোনো অভিপ্রায় তোমার নেই।\nপ্রতিটি মাত্রার শেষে, ছাত্ররা গলা মোচড় দিয়ে কষ্ট করে মাথা ঘোরায়, যেন মনোযোগ দিয়ে শুনছে এমন ভান করে।\nশিক্ষক সামান্য ঝুঁকে দাঁড়িয়ে, ঠোঁট নড়ছে, চোখ ঘুরিয়ে তাকিয়ে আছে এক অস্তিত্বহীন সুরলিপির দিকে।\nতারা স্পষ্টই জানে না তারা কী করছে, আর কোনোদিনও বুঝবে না কেন মানুষ বছরের পর বছর ধরে এই যান্ত্রিক অনুশীলনে জীবন ব্যয় করে।\nতারা শুধু নকল করছে।"
  },
  Event_7121_Name = {
    Text = "পিয়ানো পাঠ"
