  Event_7123_Desc = {
    Text = "প্রাচীন সমুদ্রগীতি ডোমেইনে প্রতিধ্বনিত হয়।\nবন্দী স্মৃতিচারণ অশ্রুত এক ভাষায় ঢেউ, আকাশ আর তীব্র মদের গান গায়।"
