  Event_7124_ChoiceDesc1 = {
    Text = "[Call the Crow] 20টি কালো চিহ্ন গ্রহণ করো, তবে 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_7124_ChoiceDesc2 = {
    Text = "[Get Far Away]"
  },
  Event_7124_Desc = {
    Text = "কালো পিচের মতো অন্ধকার পাখিগুলো তাদের দৃষ্টি তোমার ওপর স্থির করে। অনেকক্ষণ পর, তাদের পালক থেকে কিছু একটা ঝরে পড়ে..."
  },
  Event_7124_Name = {
    Text = "নির্বাসিত কাক"
  },
  Event_7125_ChoiceDesc1 = {
    Text = "[Step Forward and Grip] 100% সম্ভাবনায় 25টি কালো চিহ্ন পাবে"
  },
  Event_7125_ChoiceDesc2 = {
    Text = "[Friendly Response] 50% সম্ভাবনায় 50টি কালো চিহ্ন পাবে, 50% সম্ভাবনায় কিছুই পাবে না।"
  },
  Event_7125_Desc = {
    Text = "অজানা জীবের এক বিড়াল D-পঙ্কের ভিড়ে বসে থাকে, তার ঝাপসা দেহ যেন ইঙ্গিত দেয় যে সে আত্মিক মাত্রার বাসিন্দা।\nএই অস্পষ্ট প্রক্ষেপণটি প্রজ্ঞাময় চোখে র‍্যামোনার দিকে চেয়ে থাকে, তার সাদা থাবা তোলে, আর তাকে আহ্বান জানায়।"
  },
  Event_7125_Name = {
    Text = "বিচরণকারী বাসিন্দা"
  },
  Event_7126_ChoiceDesc1 = {
    Text = "[Running North]"
  },
  Event_7126_ChoiceDesc2 = {
    Text = "[Ignore the Sound]"
  },
  Event_7126_Desc = {
    Text = "শত্রুর আক্রমণ পেছন থেকে বৃষ্টির মাঝে ঝরে পড়ে, তাদের ব্লেড তোমার চাদর ছুঁয়ে যায়, আর ঘাটে বসে থাকা সীগালদের ঝাঁককে চমকে উড়িয়ে দেয়।\n「উত্তরের দিকে... নাকি জাহাজে উঠব...」\nসবচেয়ে মূর্খ মানুষটিও অনুভব করতে পারত, কোনো অদৃশ্য শক্তি তোমাদের পক্ষে হাত বাড়িয়ে আছে।"
  },
  Event_7126_Name = {
    Text = "উত্তরমুখী"
  },
  Event_7127_ChoiceDesc1 = {
    Text = "[Listen to the Sun] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_7127_ChoiceDesc2 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7127_Desc = {
    Text = "বাস্তবতা ও বিভ্রমের পারস্পরিক জড়াজড়িতে, মহাজাগতিক বস্তুগুলো চিরকাল তাদের পূর্বনির্ধারিত কক্ষপথে ঘুরতে থাকে।\nঅসংখ্য ছুঁয়ে যাওয়া মুহূর্ত একটি অদ্ভুত ও রহস্যময় সিম্ফনি রচনা করেছে..."
  },
  Event_7127_Name = {
    Text = "নাক্ষত্রিক সুরলহরী"
  },
  Event_7128_ChoiceDesc1 = {
    Text = "[Leave with Sorrow] একটি কার্ড অনুলিপি করো। যদি একটি উপসর্গ কার্ড অনুলিপি করা হয়, তবে 75টি কালো চিহ্ন প্রাপ্ত হও।"
  },
  Event_7128_ChoiceDesc2 = {
    Text = "[ক্রোধের সাথে চলে যাও]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」"
  },
  Event_7128_Desc = {
    Text = "তারারন্ধ্র থেকে তরল উছলে উঠল, শীতল ও উত্তাল, আত্মার এক অংশ ছিনিয়ে নিয়ে গেল।"
  },
  Event_7128_Name = {
    Text = "স্টিক্সের বিলাপ"
  },
  Event_7129_ChoiceDesc1 = {
    Text = "[Into the Corridor]"
  },
  Event_7129_ChoiceDesc2 = {
    Text = "[Go Against the Flow] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7129_Desc = {
    Text = "ফ্যাকাশে চাঁদের আলো সময়ের প্রবাহকে উপেক্ষা করে, নীরব করিডোর জুড়ে গড়িয়ে পড়ে।\nদরজার ফাঁক থেকে চাঁদের রশ্মিতে এক অস্বস্তিকর আভা বিচ্ছুরিত হয়।"
  },
  Event_7129_Name = {
    Text = "নিস্তব্ধ প্রকোষ্ঠ"
  },
  Event_7130_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7130_Desc = {
    Text = "আপনি মোমের ভাস্কর্যটি মেরামত করার সিদ্ধান্ত নেন।\nচারপাশে ছড়িয়ে থাকা কিছু যন্ত্রের মধ্যে থেকে আপনি \"প্রুশিয়ান ব্লু\" নামের একটি রং তুলে নেন।\nএটি নীল, এক রোগের মতো।"
  },
  Event_7130_Name = {
    Text = "অসমাপ্ত মোমের ভাস্কর্য"
  },
  Event_7131_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7131_Desc = {
    Text = "পুঁজফোড়াটি এক তীক্ষ্ণ, অশুভ চিৎকার ছাড়ল, যার সঙ্গে কানে বেজে উঠল অস্বাভাবিক শিসধ্বনি, মায়াভ্রমের বাঁশির সুর, আর ঝরতে থাকা তরলের নিষিদ্ধ অনুরণন।\nপুঁজফোড়াটি এক মুহূর্তের জন্য অদ্ভুতভাবে কেঁপে উঠে তারপর হঠাৎ শক্ত হয়ে নীরবতায় ডুবে গেল। এটি দেখে তোমার পাশের জাগরণকারী যেন কোনো এক আহ্বান গ্রহণ করল।"
  },
  Event_7131_Name = {
    Text = "অদ্ভুত পুঁজফোড়া"
  },
  Event_7132_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7132_Desc = {
    Text = "তোমার আঙুলের ডগা মূর্তিটিকে স্পর্শ করে, অপ্রত্যাশিতভাবে নরম খাঁজ অনুভব করো। তুমি সবসময় ভেবেছিলে ওটা কেবল মায়াস্বপ্ন।"
  },
  Event_7132_Name = {
    Text = "জোড়াতালির দেহাবশেষ"
  },
  Event_7133_ChoiceDesc1 = {
    Text = "[Tear For Her]"
  },
  Event_7133_ChoiceDesc2 = {
    Text = "[Pray to Her]"
  },
  Event_7133_Desc = {
    Text = "তুমি যখন জাহাজের রেলিং স্পর্শ করো, তখনই তোমার নয় এমন স্মৃতিগুলো ঢেউয়ের মতো ভেসে আসে মনে।\nমানুষেরা তাকে পরিয়ে দিয়েছিল এক নির্মল সাদা গাউন, শোভা বাড়িয়েছিল সুশোভিত গয়নায়, আর তাকে বসিয়েছিল উঁচু এক বেদির ওপর। শহরবাসী তার পায়ের কাছে নতজানু হয়ে প্রণাম করেছিল।\nতাদের চোখ ভরা ছিল আশায়: নাবিকেরা চেয়েছিল যাত্রাপথে তার সুরক্ষা, মাছ ধরা লোকেরা আশা করেছিল শান্তিপূর্ণ মাছ ধরা মৌসুম, আর অন্য শহরবাসী কামনা করেছিল সারা বছরের মসৃণ পথচলা।\nনতজানু জনতার ভিড়ের মধ্যে ছিল তার শৈশবের বন্ধু আর আপনজনেরা।\nসে কিছুই চাইত না; সে জানতই না সে কী চাইত।\nপ্রার্থনার জবাবে নিঃশব্দে সাড়া দেওয়াই যেন ছিল তার জীবনের একমাত্র উদ্দেশ্য।"
  },
  Event_7133_Name = {
    Text = "যাত্রা-পূর্ব আচার"
  },
  Event_7134_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7134_Desc = {
    Text = "ও বিকৃতদেহের ফ্যাকাশে মণিদ্বয় ধীরে ধীরে ঘুরে তোমার সরে যাওয়া অবয়বের দিকে চেয়ে রইল, আর তার ঠোঁটে ফুটে উঠল এক ক্ষীণ হাসি।"
  },
  Event_7134_Name = {
    Text = "জোড়াতালির দেহাবশেষ"
  },
  Event_7135_ChoiceDesc1 = {
    Text = "[Face It] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7135_ChoiceDesc2 = {
    Text = "[প্রতিরোধ ছেড়ে দাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_7135_ChoiceDesc3 = {
    Text = "[Run Away] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7135_Desc = {
    Text = "কয়েকটি মোমের ভাস্কর্য ব্লক তোমার পথ রুদ্ধ করে রেখেছে。\nওগুলো বেঁকে গেছে আর খসখসে, রজার্সের কাছ থেকে যে ধরনের কারুকাজ আশা করা যায়, তার সঙ্গে একেবারেই মেলে না。\n「আদেশ… প্রভুর আদেশ…」"
  },
  Event_7135_Name = {
    Text = "খসড়া"
  },
  Event_7136_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7136_Desc = {
    Text = "\nতুমি সাহস করে সেই চোখগুলোর দিকে সরাসরি তাকাতে বেছে নাও।\nওগুলো উজ্জ্বল তারকারাজি, অন্ধকারে ঝিলমিল করছে।\nতারপর তারা হেসে ওঠে, আর অসংখ্য অর্ধচন্দ্রাকৃতির চাঁদে রূপান্তরিত হয়।\n\"তুমি দৃষ্টিকে ভয় পাও না। তোমার ভয় পাওয়া উচিত নয়...\nঅনেক দিন পর দেখা, @2\"\nঅদৃশ্য হওয়ার আগে, তারা তোমাকে একটি ছোট উপহার দিয়ে যায়, \"পুনর্মিলনের স্মারক\" হিসেবে।"
  },
  Event_7136_Name = {Text = "চোখ"},
  Event_7137_ChoiceDesc1 = {
    Text = "[Switch On] বর্তমান দৃষ্টিক্ষেত্র প্রসারিত করুন[ExDesc1]।"
  },
  Event_7137_Desc = {
    Text = "একটি প্রাচীন আলোকযন্ত্র তার চারপাশের কালো কুয়াশা তাড়িয়ে দেয়।\nতার চারপাশের কুয়াশা ছন্দময়ভাবে দুলতে থাকে, যেন তার নিশ্বাসে বিঘ্নিত হয়েছে।"
  },
  Event_7137_Name = {
    Text = "সার্চলাইট"
  },
  Event_7138_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7138_Desc = {
    Text = "তোমার পিঠে স্বচ্ছ ডানা মেলে যায়, কাকদের সঙ্গে ঘূর্ণি তুলে নীরব সাগরতলের দিকে নেমে যায়।"
  },
  Event_7138_Name = {
    Text = "কাকদের কোরাস"
  },
  Event_7139_ChoiceDesc1 = {
    Text = "[Destroy It] একটি 「মিউটেশনের হৃদয়」 অর্জন করো"
  },
  Event_7139_Desc = {
    Text = "রাস্তার ধারে অজানা জীবেরা ফেলে যাওয়া বিকৃত পুঁজফোড়াগুলো নোংরা, তৈলাক্ত সবুজ আভায় চকচক করছে, অস্থিরভাবে কিলবিল করছে আর রূপ বদলাচ্ছে।\nদানবের চেয়ে বরং এগুলো দেখতে অনেকটা প্রখর রোদের তাপে গলতে থাকা আইসক্রিমের মতো, যা অচিরেই আঠালো কাদায় পরিণত হয়ে বাতাসে মিলিয়ে যায়।"
  },
  Event_7139_Name = {
    Text = "অদ্ভুত পুঁজফোড়া"
  },
  Event_7140_ChoiceDesc1 = {
    Text = "[Lower Your Hands] 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো, এবং একটি পুরস্কার বেছে নাও।"
  },
  Event_7140_ChoiceDesc2 = {
    Text = "[Catch a Crow] 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো, এবং একটি পুরস্কার বেছে নাও।"
  },
  Event_7140_ChoiceDesc3 = {
    Text = "[Close Your Eyes] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7140_Desc = {
    Text = "কর্কশ চিৎকার, অন্তহীন কর্কশ চিৎকার—\nক্রো গায়ক চকচকে কালো পালকে মোড়া, তার ধারালো ঠোঁটে ঠান্ডা আলো ঝলসে ওঠে, প্রতিটি বিলাপময় ডাক তোমার কানের পর্দা বিদীর্ণ করে।\nকান ঢেকে রেখো না!\nরাত্রির কাকেরা নিজেদের চিৎকারে উল্লসিত, তোমার সঙ্কুচিত দেহের ভেতরের অপ্রশমিত কম্পন থেকে পান করতে উদগ্রীব।\n"
  },
  Event_7140_Name = {
