    Text = "[Leave] কিছুই পাওয়া যায়নি"
  },
  Event_7141_Desc = {
    Text = "ইনি সেই ব্যক্তি নন যাকে আপনি খুঁজছেন"
  },
  Event_7141_Name = {
    Text = "2_6অস্থায়ী"
  },
  Event_7142_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7142_Desc = {
    Text = "তুমি এগিয়ে যাওয়ার সিদ্ধান্ত নিলে。\nওই ভয়াবহ মোম শিল্পগুলোর মানসিক ও শারীরিক আঘাতের তুলনায়, এই সামান্য অসুবিধা কিছুই নয়。\nতোমার সামনে আরও বৃহত্তর দায়িত্ব অপেক্ষা করছে।"
  },
  Event_7142_Name = {
    Text = "পদধ্বনি"
  },
  Event_7143_ChoiceDesc1 = {
    Text = "[Point Out the Issue] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7143_Desc = {
    Text = "“কী হয়েছে! তুমি কি ইচ্ছে করেই অন্যের ক্ষতগুলোতে আঙুল ঢুকিয়ে খোঁচাতে ভালোবাসো?”\n“হ্যাঁ! আমি হঠাৎ করেই কোনো কারণ ছাড়াই পঁচিশ বছর বয়স্ক হয়ে গেছি! এখন থেকে তোমাকে আমাকে ‘মারফি আপা’ বলে ডাকতে হবে!”"
  },
  Event_7143_Name = {
    Text = "শৃঙ্খলিত জীবন"
  },
  Event_7144_ChoiceDesc1 = {
    Text = "[Leave] 3টির মধ্যে 1টি রৌপ্য সৃষ্টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_7144_Desc = {
    Text = "মেয়েটির মুখ আজ রাতের চাঁদের আলোয়ের মতোই শান্ত। সে তোমার ডাকে সাড়া দেয় না, শুধু হাতে ধরা কম্পাসটি উঁচু করে তুলে ধরে—সে কাঁপছে, যেন এই ছোট্ট কম্পাসটুকু তুলতেই তার সমস্ত শক্তি নিঃশেষ হয়ে গেছে।"
  },
  Event_7144_Name = {
    Text = "সাদা পোশাকের কিশোরী"
  },
  Event_7145_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7145_Desc = {
    Text = "\"মজা! মজা!\" কাকটি খিকখিক করে হেসে উঠল, আর তার ডানা মেলতেই পচনের দুর্গন্ধ তোমার নাকে এসে লাগল।"
  },
  Event_7145_Name = {
    Text = "অভিশপ্ত দুর্কাক"
  },
  Event_7146_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7146_Desc = {
    Text = "আমার মতে, শব্দই নতুন যুগের আদর্শ।\nএটি অনিয়মিত ছন্দ আর উন্মাদ সুর নিয়ে নির্দয়ভাবে সারা দুনিয়া জুড়ে অগ্রসর হয়।\nনা দয়া, না দ্বিধা, না আপস।\nশৃঙ্খলা ঘৃণা করে, বিষয়বস্তু ছুঁড়ে ফেলে দেয়, শব্দ কখনোই তুষ্ট করতে চায় না—\nতার মধ্যে আমাদের মোম ভাস্করও আছে।"
  },
  Event_7146_Name = {
    Text = "বাজে রুচি"
  },
  Event_7147_ChoiceDesc1 = {Text = "[Guide]"},
  Event_7147_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7147_Desc = {
    Text = "কেউ একজন আলতো করে তোমার জামার হাতা টানছে।\nএটা সেই ছেলেটা, যাকে তুমি একটু আগে দেখেছিলে। সে কোণে বসে, দুঃখমাখা অভিব্যক্তি নিয়ে তোমার দিকে তাকিয়ে আছে।\n\"আ-আমি একাডেমির অনুষ্ঠানে অংশ নিতে চাই।\nকিন্তু আমি মঞ্চের পথ খুঁজে পাচ্ছি না।\""
  },
  Event_7147_Name = {
    Text = "অন্তিম II"
  },
  Event_7148_ChoiceDesc1 = {
    Text = "[Keep Searching] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7148_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7148_Desc = {
    Text = "নাকের ডগায় ধরা পড়ে এক পরিচিত গন্ধ, ঘরোয়া ও তৃপ্তিকর। ক্যাফেটেরিয়ার সেই সুবাস আরেকবার টেনে নিতে যেই তুমি ঝুঁকে পড়ো, তা সম্পূর্ণভাবে মিলিয়ে যায়।"
  },
  Event_7148_Name = {
    Text = "অস্বাভাবিক যোগাযোগ"
  },
  Event_7149_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7149_Desc = {
    Text = "ওগুলো উষ্ণ রঙ।\nউত্তেজিত, কোমল, আর স্নেহময় রঙ।\nওরা মেয়েটিকে এক নস্টালজিক আলিঙ্গন দিল, তারপর হাওয়ার মতো মিলিয়ে গেল।"
  },
  Event_7149_Name = {
    Text = "স্মৃতির রঙ"
  },
  Event_7150_ChoiceDesc1 = {
    Text = "[Who are you, really?]"
  },
  Event_7150_ChoiceDesc2 = {
    Text = "[How to Change Your Mindset?]"
  },
  Event_7150_Desc = {
    Text = "লম্বা চুলের এক ব্যক্তি আবারও তোমার পথ ব্লক করে দাঁড়াল। আগের অভিজ্ঞতার পর, রামোনার অভিব্যক্তি অনুকূল নয়।\n“শান্ত হও, বন্ধু আমার,” ধীরে ধীরে বলে উঠল লোকটি। তার কণ্ঠস্বর চৌম্বক আর প্রলুব্ধকর, যেন সরু এক বায়ুপথ বেয়ে বয়ে যাওয়া শব্দ, যার সঙ্গে মিশে আছে হিসহিসে ঘর্ষণের সুর।\n“আমি অনেকক্ষণ ধরে পর্যবেক্ষণ করছি; কেবল তোমার মানসিকতা বদলালেই তুমি তোমার লক্ষ্যটির কাছে পৌঁছতে পারবে।”"
  },
  Event_7150_Name = {
    Text = "অদ্ভুত সঙ্গী III"
  },
  Event_7151_ChoiceDesc1 = {
    Text = "[I Am Searching] সর্বোচ্চ HP Arg1 বৃদ্ধি পায়"
  },
  Event_7151_ChoiceDesc2 = {
    Text = "[আমি এড়িয়ে চলছি]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_7151_Desc = {
    Text = "আমি দেখি কেউ খুঁজছে, অধরা, সেই বেদনাময় আত্মীয়সদৃশ বস্তুটিকে, যাকে সত্য বলা হয়, তার সন্ধানে।\nআমি দেখি কেউ এড়িয়ে যাচ্ছে, অনিবার্য, সেই নিষ্ঠুর গোপন বস্তুটিকে, যাকে সত্য বলা হয়, তার কাছ থেকে।\nতুমি—কোনটি?"
  },
  Event_7151_Name = {
    Text = "অন্বেষিত"
  },
  Event_7152_ChoiceDesc1 = {
    Text = "[Examine Closely] একটি রৌপ্য রেলিককে সোনার রেলিক 「(RelicConfig.Arg1)」-এ উন্নীত করো।"
  },
  Event_7152_ChoiceDesc2 = {
    Text = "[Attempt to Listen] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 এবং 「(Skill.Arg3)」 বিকশিত হবে।"
  },
  Event_7152_ChoiceDesc3 = {
    Text = "[Store Carefully] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7152_Desc = {
    Text = "সামনের কুয়াশা আলোকিত করছিল এক ক্ষুদ্র বস্তু, কাঁচ বা স্ফটিকের ভগ্নাংশের মতো, যার ভেতরে অসংখ্য রং—উজ্জ্বল ও ম্লান—ঘূর্ণায়মান ছিল।"
  },
  Event_7152_Name = {
    Text = "আমাদের স্মৃতি"
  },
  Event_7153_ChoiceDesc1 = {
    Text = "[Accept Challenge] জিতলে একটি রৌপ্য সৃষ্টি অর্জন করবে, হারলে একটি উপসর্গ বিকাশ করবে। ফলাফল পরবর্তী তদন্তে প্রভাব ফেলবে না।"
  },
  Event_7153_ChoiceDesc2 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7153_Desc = {
    Text = "প্রতিফলনে থাকা মানুষটি কে?\nসে তোমার সঙ্গে শ্বাস নেয়, তোমার হৃদস্পন্দন ভাগ করে, আর একই ভৌতিক ভাবনা লালন করে।\nএ কি ডোমেইনের কোনো নিষ্ঠুর প্রহসন, নাকি মাত্রা ভেদ করা কোনো ছায়া?\nএ যেন এক মরীচিকার চ্যালেঞ্জের আমন্ত্রণ।"
  },
  Event_7153_Name = {
    Text = "আত্মা অনুরণন"
  },
  Event_7154_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7154_Desc = {
    Text = "দৃষ্টি ইতিহাস ও সময়কে অতিক্রম করে। তা হয়তো সরলরেখায় বাঁধা নয়, গ্রহের জন্মের আগের বিশৃঙ্খলা থেকে তোমার দিকে তাকিয়ে আছে।\nঅথবা, হয়তো তা অপেক্ষা করছে ভবিষ্যতের কোনো দূর দিনের প্রান্তে।"
  },
  Event_7154_Name = {
    Text = "আড়চোখে তাকাও"
  },
  Event_7155_ChoiceDesc1 = {
    Text = "[Claim] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7155_Desc = {
    Text = "এলাকাটি ফাঁকা, মাটির ওপর দিয়ে বয়ে যাচ্ছে কালো তরল, যা কিছুই প্রতিফলিত করছে না।\nএটা কি মায়াস্বপ্ন? তুমি অনুভব করো, কিছু একটা তোমার আঙুলের ফাঁক গলে সরে যাচ্ছে।"
  },
  Event_7155_Name = {
    Text = "আয়নাতলে"
  },
  Event_7156_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7156_Desc = {
    Text = "「তুমি তো ভীষণ উদার মানুষ। আজ, কাল, পরশু—তোমার সব মনোবাঞ্ছা পূর্ণ হোক।」\n「যাই হোক, এটা কিন্তু একবারের চুক্তি...」\nপরীটি তৃপ্তির সাথে ঠোঁট চেটে নিল এবং অনিচ্ছাসত্ত্বেও তোমাকে বিদায় জানাল।"
  },
  Event_7156_Name = {
    Text = "পরীর আশীর্বাদ"
  },
  Event_7157_ChoiceDesc1 = {
    Text = "[Give Me My Wallet Back!] 3টি প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_7157_ChoiceDesc2 = {
    Text = "[দ্বিধা করো]এলোমেলো 1টি কমান্ড কার্ড অরিসন লাভ করে：「(EnchantConfig.Arg1)」，সংক্রমিত হয়「(Skill.Arg2)」"
  },
  Event_7157_Desc = {
    Text = "\n「এসো, এসো, তোমার মানিব্যাগটা ফিরে নাও!」 দূরে এক শিশু হাত নেড়ে ডাকল।\nতুমি দৌড়ে এগিয়ে গেলে, আর হাত বাড়াতেই হঠাৎ এক কর্কশ, বিশৃঙ্খল শব্দমালা তোমার মস্তিষ্কে বাজতে লাগল।\n「এই নোংরা ছেলেটা এলো কোথা থেকে?」\n「ও তো একেবারে রাস্তার ইঁদুর! ডাচেসের গাউনে হাত দিতে তার সাহস হয় কী করে!」\n「ওকে এখান থেকে বের করে দাও!」\n「তোমার কাছে কি কোনো মুদ্রা আছে? মুদ্রা না থাকলে, এক টুকরো কালো রুটিও পাওয়ার কথা ভাববে না!」"
  },
  Event_7157_Name = {
    Text = "শূন্যের গ্রন্থ"
  },
  Event_7158_ChoiceDesc1 = {
    Text = "[Chase the Song] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7158_ChoiceDesc2 = {
    Text = "[Sing Along] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো এবং খোদাই করার প্রার্থনাগাথা পরিবর্তন করো।(ব্যবহার: 2/2)"
  },
  Event_7158_Desc = {
    Text = "দূরবর্তী গানটি ভেঙে গিয়ে তারাধূলিতে পরিণত হলো:\n“আমি অভিশাপ দিই রাতের গলির নোংরা জলাবদ্ধতাকে, পচা ফুলগুলো আঁকড়ে ধরে থাকে ভেঙে পড়া দেয়াল, শিকল টেনে নিয়ে যায় মনকে কাদার অতলে। কুয়াশা আমার অস্তিত্ব মুছে ফেলার আগে, গোধূলি ডুবে যাবে গভীরতম @2-এ।”"
  },
  Event_7158_Name = {
    Text = "বিবর্ণ অভিশাপ"
  },
  Event_7159_ChoiceDesc1 = {
    Text = "[নৈবেদ্য রেখে যাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_7159_ChoiceDesc2 = {
    Text = "[তাঁকে নিয়ে চলে যাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_7159_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7159_Desc = {
    Text = "তুমি এগিয়ে যেতেই, হঠাৎই কাদামাখা অতল থেকে বিশৃঙ্খল আত্মারা বেরিয়ে আসে।\nকালো অঙ্গপ্রত্যঙ্গ তোমাকে শক্ত করে জড়িয়ে ধরে, কাঁদতে কাঁদতে মিনতি করতে থাকে—\nএকটি নিবেদিত কবিতা অর্পণ করো, অথবা তাদের সরিয়ে দাও।"
  },
