    Text = "ডানায় লেগে থাকা কালো আঠালো কাদায় ভেজা এক প্রজাপতি টলতে টলতে উড়ে চলে, তার পেছনে রেখে যায় কালো পিচ্ছিল দাগ, যা বাতাসে কঠিনীকরণ হয়ে ঝরে পড়ে।\nসে ক্লান্ত হয়ে তোমার নাকের ডগায় গিয়ে বিশ্রাম নেয়।"
