  Event_7162_Name = {
    Text = "অবসিডিয়ান প্রজাপতি"
  },
  Event_7163_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7163_Desc = {
    Text = "আমি সাহস, ইচ্ছাশক্তি, আর নক্ষত্রের মতো দীপ্তিমান এক আত্মা দেখতে পাচ্ছি। সেই মোমে-সিলমোহর করা স্মৃতির দিকে এগিয়ে যাও, আর তোমার মনোবাঞ্ছা পূর্ণ হবে।"
  },
  Event_7163_Name = {
    Text = "অন্বেষিত"
  },
  Event_7164_ChoiceDesc1 = {
    Text = "[থাকতে দাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，সংক্রমিত হও「(Skill.Arg2)」"
  },
  Event_7164_ChoiceDesc2 = {
    Text = "[Wave Away] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7164_ChoiceDesc3 = {
    Text = "[Welcome the Butterflies] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7164_Desc = {
    Text = "তুমি হিমশীতল স্যানাটোরিয়ামের ভেতর ঘুরে বেড়াও, যেখানে এই ঋতুতে থাকার কথা নয় এমন এক কালো প্রজাপতি উড়ে যায় তোমার পাশ দিয়ে।\nতার ডানা, কালো পিচ্ছিল কাদায় মোড়া, দুলতে দুলতে উড়ে চলে, আর উড়তে উড়তে স্তরে স্তরে কালো কাদামাটি ঝরিয়ে দেয়, যা বাতাসে কঠিনীকরণ হয়ে খসে পড়ে।\nশ্রান্ত হয়ে, সেটি এসে বসে তোমার আঙুলের ডগায়।"
  },
  Event_7164_Name = {
    Text = "যা থাকা উচিত নয়"
  },
  Event_7165_ChoiceDesc1 = {
    Text = "[Leave] 3টির মধ্যে 1টি রৌপ্য সৃষ্টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_7165_Desc = {
    Text = "তুমি ক্লান্তি অনুভব করতে শুরু করলে।\nতোমার চেতনা তোমাকে টেনে নিয়ে যায় পুকুর আর পর্বতমালা পেরিয়ে,\nসূর্যের ওপারে, আলোকবর্ষেরও ওপারে,\nএক এবং অদ্বিতীয়... মহাজাগতিক দোলনার দিকে।"
  },
  Event_7165_Name = {
    Text = "অন্তিম IV"
  },
  Event_7166_ChoiceDesc1 = {
    Text = "[Look More]"
  },
  Event_7166_Desc = {
    Text = "এক বিশাল ছায়া তোমাকে সম্পূর্ণ গ্রাস করে ফেলে, আর দুর্গন্ধময় লালা তোমাকে ভেজা ইদুরের মতো ভিজিয়ে দেয়।\n\"ছোট ইঁদুর, এদিকে আয়। একটু মাত্র...\"\n\"আমি শপথ করে বলছি, তোমাকে খাওয়ার কোনো অভিপ্রায় আমার নেই...\"\n\"তোমার মোটা, রসালো পেটের দিকেও আমি একবার তাকাব না!\""
  },
  Event_7166_Name = {
    Text = "উপকরণ ১২"
  },
  Event_7167_ChoiceDesc1 = {
    Text = "[Look More]"
  },
  Event_7167_Desc = {
    Text = "শুকিয়ে যাওয়া মোমের ভাস্কর্য দার্শনিক ধোঁয়া টানে, সাদা কুয়াশায় আচ্ছন্ন।\n\"ওপারের তীর আছে, কিন্তু অজ্ঞেয়; তাই তা অজানা জীব রয়ে যায়।\"\n\"ভাবো, এই বিশ্বটাই যেন এক খেলা...\nতুমি যা খুঁজছ, তা হয়তো মানচিত্রের অন্য প্রান্তে লুকিয়ে আছে।\""
  },
  Event_7167_Name = {
    Text = "উপকরণ ৪৫"
  },
  Event_7168_ChoiceDesc1 = {
    Text = "[Look More]"
  },
  Event_7168_Desc = {
    Text = "「আমি দুঃখিত, অপমান করার ইচ্ছে ছিল না...」\n「আমি ইঁদুর পছন্দ করি না। ইঁদুরের সমস্যা হলো, তারা কোনোদিনই মানুষের ভয় পায় না...」\nএক অগোছালো বৃদ্ধ কোণে শুয়ে ছিল, তার বিষণ্ণ চোখ তোমার ওপর স্থির।\n「অবশ্যই, তুমি ভীষণ উচ্চাভিলাষী।\nএটা ভালো, কিন্তু এইটুকু দিয়ে তোমাকে আসন্ন বিপর্যয় থেকে পালাতে সাহায্য করা যাবে না...」"
  },
  Event_7168_Name = {
    Text = "উপকরণ ৪"
  },
  Event_7169_ChoiceDesc1 = {
    Text = "[অভিশাপ দেখাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_7169_ChoiceDesc2 = {
    Text = "[Reject the Crow] 3টি প্রার্থনাগাথা থেকে 1টি খোদাই করো"
  },
  Event_7169_ChoiceDesc3 = {Text = "[Ignore]"},
  Event_7169_Desc = {
    Text = "আলোবাহকের এক ভক্তের কালো চাদর থেকে এক পিচকালো, অসুস্থ বহু-মাথাওয়ালা কাক উড়ে এসে তোমার কাঁধে বসে.\n「আমার মাথাটা দেখছ? অভিশাপের স্বাদ পেলেই আমার নতুন মাথা গজায়। দেখি তো, তোমার অভিশাপটা!」"
  },
  Event_7169_Name = {
    Text = "অভিশপ্ত দুর্কাক"
  },
  Event_7170_ChoiceDesc1 = {
    Text = "[Answer the Call] একটি কমান্ড কার্ড ধ্বংস করো এবং Arg1 HP পুনরুদ্ধার করো"
  },
  Event_7170_ChoiceDesc2 = {
    Text = "[I'm Not Fleeing] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো"
  },
  Event_7170_Desc = {
    Text = "তুমি গলিপথ ধরে দৌড়াও। অ্যাড্রেনালিন ছুটে ওঠে, ল্যাকটিক অ্যাসিড জমে, গ্লুকোজ ফুরিয়ে আসে... বিশৃঙ্খলা তোমার মস্তিষ্কে ঢুকে পড়ে, সাইকেডেলিক কুয়াশার ভেতর থেকে তোমাকে পালাতে তাড়িত করে।\nহ্যাঁ, পালাও। তুমি যদি পালিয়ে না যাও, তবে কেন বিশৃঙ্খলা আর মায়াস্বপ্ন, ব্যর্থতা আর শূন্যতা তোমার জন্য অপেক্ষা করছে?"
  },
  Event_7170_Name = {
    Text = "দৌড়াও"
  },
  Event_7171_ChoiceDesc1 = {
    Text = "[Trace Sound Source]"
  },
  Event_7171_ChoiceDesc2 = {
    Text = "[Summon Lily and Koum]"
  },
  Event_7171_Desc = {
    Text = "দূর থেকে, মাত্রার প্যাসেজের গভীরে, আমরা গম্ভীর, গরগর শব্দ শুনি—তার সঙ্গে মিশে আছে ভয়, প্রত্যাশা ও উদ্বেগ—যেন তোমাকেই ডেকে চলেছে। তারপর, এক কিশোরীর দমবন্ধ প্রলাপ ধীরে ধীরে মিলিয়ে যায়।"
  },
  Event_7171_Name = {
    Text = "পথপ্রদর্শক কণ্ঠ"
  },
  Event_7172_ChoiceDesc1 = {Text = "[Take It]"},
  Event_7172_Desc = {
    Text = "প্রায় পারদের মতো এক সিলভার পদার্থ, D-পঙ্ক থেকে পরিশোধিত, তীব্র মানসিক শক্তিতে পরিপূর্ণ, আচার অনুষ্ঠানে আরও অধিক জাগরণকারীকে সংযুক্ত করতে ব্যবহৃত হয় প্রায় পারদের মতো এক সিলভার পদার্থ, D-পঙ্ক থেকে পরিশোধিত, তীব্র মানসিক শক্তিতে পরিপূর্ণ, আচার অনুষ্ঠানে আরও অধিক জাগরণকারীকে সংযুক্ত করতে ব্যবহৃত হয়।"
  },
  Event_7172_Name = {
    Text = "সিলভার"
  },
  Event_7173_ChoiceDesc1 = {
    Text = "[Ask to Clear the Path]"
  },
  Event_7173_ChoiceDesc2 = {
    Text = "[Ask Who He Is]"
  },
  Event_7173_Desc = {
    Text = "তুমি পা বাড়াও এক ম্লান আলোয় ভরা কামরায়, ভেতর থেকে ধীরে ধীরে উঠে আসে এক অস্বস্তিকর অনুভূতি।\nকামরাটি ফাঁকা; যাত্রীরা বহু আগেই পালিয়ে গেছে, ফেলে রেখে গেছে বিক্ষিপ্ত দানবের অবশিষ্ট দেহ, যা ধীরে ধীরে বিলীন হয়ে যাচ্ছে।\nকামরার মাঝখানে দাঁড়িয়ে আছে এক ব্যক্তি।\n\"আমি ভাগ্যে বিশ্বাস করি, আর সেই ভাগ্যই আমাদেরকে একই সাবওয়েতে এনে দাঁড় করিয়েছে।\""
  },
  Event_7173_Name = {
    Text = "অদ্ভুত সঙ্গী IV"
  },
  Event_7174_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7174_Desc = {
    Text = "\"তোমার চোখ খুব সুন্দর, তারার মতো।\"\nশার্লট খিলখিল করে হেসে উঠল, তার উন্মত্তভাবে ঘুরে বেড়ানো চুল ধীরে ধীরে শান্ত হয়ে এল।\n\"তুমি নিশ্চয়ই স্কুলে খুব জনপ্রিয়। আমিও তোমাকে পছন্দ করি।\"\nবিদায় নেওয়ার আগে, সে তোমার কপালে চুমু খেল।\nতুমি অনুভব করলে শরীর উষ্ণ হয়ে উঠেছে, আর যেন কিছু একটা বদলে গেছে।"
  },
  Event_7174_Name = {
    Text = "অনুসন্ধানকারীর ছায়া"
  },
  Event_7175_ChoiceDesc1 = {
    Text = "[Read] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_7175_ChoiceDesc2 = {
    Text = "[Store in Suitcase] রেলিক 「(RelicConfig.Arg2)」 অর্জন করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7175_Desc = {
    Text = "আলোবাহক ভক্তের পোশাক থেকে একটি হলদেটে পৃষ্ঠা ঝরে পড়ল।\nএটি অদ্ভুত সব লেখায় ভরা; কিছু হায়ারোগ্লিফের মতো, কিছু অস্বাভাবিকভাবে কাত হয়ে আছে, কিছু আবার একে অন্যের ওপর চেপে বসেছে। কেবল অল্প কিছু শব্দ কষ্টেসৃষ্টে পড়া যায়।"
  },
  Event_7175_Name = {
    Text = "সাইফার-এডিক্ট·পর্ব I"
  },
  Event_7176_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7176_Desc = {
    Text = "আপনি বলেন: 「ওহ, শার্লট! কখনোই না!」\nশার্লটের চুল উন্মত্তভাবে পেঁচিয়ে ওঠে, আর সে প্রচণ্ড ক্রুদ্ধ হয়।\n「আমি তোমাকে দেখাব! আমার দক্ষতা দেখো!」"
  },
  Event_7176_Name = {
    Text = "অনুসন্ধানকারীর ছায়া"
  },
  Event_7177_ChoiceDesc1 = {
    Text = "[Infect with \"(Skill.Arg1)\" and obtain the Silver Relic \"(RelicConfig.Arg2)\"]"
  },
  Event_7177_ChoiceDesc2 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7177_Desc = {
    Text = "ইভেন্ট 302 (উন্নয়নাধীন), চূড়ান্ত প্রভাব নয়"
  },
  Event_7177_Name = {
    Text = "ইভেন্ট 302 (উন্নয়নাধীন)"
  },
  Event_7178_ChoiceDesc1 = {
    Text = "[Accept Request] রৌপ্য রেলিক 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7178_ChoiceDesc2 = {
    Text = "[Refuse Request] 25টি কালো চিহ্ন গ্রহণ করুন"
  },
  Event_7178_Desc = {
    Text = "চোয়ালটা ছন্দ মিলিয়ে ফাটছে, এক নিয়মিত তালযুক্ত শব্দে, আর কাকতালীয়ভাবে তোমার সঙ্গী ক্রিপ্টোগ্রাফি সম্পর্কে কিছুটা জানে।\nডিকোড করা লেখাটি নিম্নরূপ:\n“হ্যালো, আমাকে ডাকা যাবে ড.@2 বলে। আমি একসময় সংগ্রাহক ছিলাম, আর প্রকৃতিবিদও...\n(এই অংশে পেশা ও উপাধি নিয়ে দীর্ঘ, ক্লান্তিকর আত্মপরিচয় রয়েছে।)\nসংক্ষেপে বললে, তুমি কি আমাকে আমার অপর অর্ধেক খুঁজে পেতে সাহায্য করবে? এটা উপরের চোয়ালের হাড়ের ছোট্ট একটা অংশ।\nওটা একবার পেলে, আমার ব্যক্তিগত ভাণ্ডারের দরজা তোমার জন্য খুলে যাবে।”"
  },
  Event_7178_Name = {
    Text = "কড়মড় শব্দ"
  },
  Event_7179_ChoiceDesc1 = {
    Text = "[Invest 100 Florins] রৌপ্য রেলিক 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7179_ChoiceDesc2 = {
    Text = "[Invest Five Pence] 25টি কালো চিহ্ন গ্রহণ করুন"
  },
  Event_7179_Desc = {
    Text = "কারুকাজ করা থলেটি কিলবিল করে ওঠে, তোমার দিকে একদম কালো এক চোয়াল খুলে দেয়।\nধনী গৃহকর্ত্রীর কাছ থেকে বিচ্ছিন্ন হওয়ার পর থেকে, এটি দশকের পর দশক অনাহারে কাতর, আহারের জন্য ব্যাকুল।\nতুমি ভেতরে উঁকি দাও; তা ফাঁকা, ভরা কেবল এক অভেদ্য অন্ধকারে।"
  },
  Event_7179_Name = {
    Text = "পেটুক থলি"
  },
  Event_7180_ChoiceDesc1 = {
    Text = "[Steadfast Determination] একটি কমান্ড কার্ড ধ্বংস করো এবং Arg1 HP পুনরুদ্ধার করো"
  },
  Event_7180_ChoiceDesc2 = {
    Text = "[Desire to Succeed] সোনালি রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7180_Desc = {
    Text = "「দু」জন একগুঁয়ে মানুষ? দরিদ্রাশ্রম তো আগেই বিপজ্জনক—「 পুতুলের কণ্ঠ হঠাৎ যোগাযোগকারী দিয়ে ভেসে এল, 「এখানে তোমার পরিকল্পনা কী? ওর মাথাটা আবার সেলাই করে লাগাবে?「\n「এখন ব্যঙ্গ করার সময় নয়, পুতুল!「\n「জানি, বুঝতে পারছি।「 পুতুল বলল, 「শান্ত হও। জানো সাফল্যের চাবিকাঠি কী?「"
  },
