  Event_7183_ChoiceDesc2 = {
    Text = "[Answer the Phone] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7183_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7183_Desc = {
    Text = "তুমি কন্ডাক্টরের বিশ্রামস্থলের পাশ দিয়ে যাওয়ার সময়, লুকোনো এক কোণ থেকে তীক্ষ্ণ শব্দে ফোন বেজে ওঠে।"
  },
  Event_7183_Name = {
    Text = "ট্রেন কল"
  },
  Event_7184_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7184_Desc = {
    Text = "ম্লান, তবু অস্বীকার করা যায় না এমন বাস্তব।\nএত ক্ষীণ সিলভার কোর কোনো জাগরণকারীকে আহ্বান করতে পারে না, কিন্তু শক্তিবৃদ্ধির জন্য একেবারে উপযুক্ত—এই তো সিলভার চিপ প্রযুক্তির সারমর্ম।"
  },
  Event_7184_Name = {
    Text = "অস্তিত্বের প্রমাণ"
  },
  Event_7185_ChoiceDesc1 = {
    Text = "[Lady's Portrait] একটি এলোমেলো কার্ডের প্রার্থনাগাথা গুণমান উন্নত করো।"
  },
  Event_7185_ChoiceDesc2 = {
    Text = "[মোমের ভাস্কর্যের পারিবারিক ছবি]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমিত করুন「(Skill.Arg2)」"
  },
  Event_7185_Desc = {
    Text = "মোম জাদুঘরে অনেক চিত্রকর্মও আছে।\nপ্রতিকৃতি, প্রাকৃতিক দৃশ্য, স্থির জীবন, বাস্তবধর্মী, বিমূর্ত...\nওগুলো নিরস দেয়ালগুলোকে সাজিয়ে তোলে, একঘেয়েমি কিছুটা কমিয়ে দেয়।\nওগুলোর একটিতে তোমার চোখ আটকে যায়। সেটি একটি —"
  },
  Event_7185_Name = {
    Text = "প্রতিকৃতি গ্যালারি"
  },
  Event_7186_ChoiceDesc1 = {
    Text = "[Keep Reading] একটি এলোমেলো কমান্ড কার্ডে 「(EnchantConfig.Arg1)」 প্রার্থনাগাথা খোদাই করো।"
  },
  Event_7186_ChoiceDesc2 = {
    Text = "[Leave] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত হবে।"
  },
  Event_7186_Desc = {
    Text = "ওজন মাপার এক পাল্লা।\nতার পেছনে অসংখ্য অঙ্গ লাল ফর্মালিনে ডুবে আছে।\nসেগুলো গুদামঘরের তাকজুড়ে পরিপাটি করে সাজানো।\nতুমি উদাসীন ভঙ্গিতে পাশের একখানা নোটবুক তুলে নিয়ে পাতা ওল্টাও:\n\"হৃদপিণ্ড: ৮ আউন্স, মস্তিষ্ক: ৫০ আউন্স...\""
  },
  Event_7186_Name = {
    Text = "অঙ্গ নিবন্ধন"
  },
  Event_7187_ChoiceDesc1 = {
    Text = "[Open Gift] একটি 「নির্দোষ প্রত্যাবর্তন উপহার」 গ্রহণ করো"
  },
  Event_7187_Desc = {
    Text = "একটি শিশুর ছায়া তোমার পাশ দিয়ে মিটমিট করে চলে যায়; তুমি বুঝতে পারো না সেটা সত্যিকারের শিশু, নাকি ডোমেইনের কোনো আত্মার প্রক্ষেপণ। কিন্তু—তুমি মাটিতে পড়ে থাকা বাক্সটির দিকে তাকাও, যার গায়ে শিশুসুলভ হাতের লেখায় লেখা আছে “উপহার”।"
  },
  Event_7187_Name = {
    Text = "সদিচ্ছার উপহার"
  },
  Event_7188_ChoiceDesc1 = {
    Text = "[Call the Crow] 40টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 দক্ষতা বিকশিত করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_7188_ChoiceDesc2 = {
    Text = "[Stay Far Away] 25টি কালো চিহ্ন গ্রহণ করো এবং সরে যাও।"
  },
  Event_7188_Desc = {
    Text = "সাদা গাঙচিলেরা তুষারঢাকা মাস্তুলে বিশ্রাম নিচ্ছে।\nতাদের প্রতিধ্বনিত ডাক তাড়িয়ে দিচ্ছে অন্ধকারকে, আর সেই কালো পাখিদের, যারা মুক্ত সমুদ্রের নয়।"
  },
  Event_7188_Name = {
    Text = "নির্বাসিত কাক"
  },
  Event_7189_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7189_Desc = {
    Text = "তুমি বুঝতে পেরেছিলে গানটি একটি প্রেমের গান থেকে রূপান্তরিত।\nসেই প্রেমের গানের শেষে কবি বলেছিল:\n\"যতক্ষণ না মানবতার দীপ্তি আমাদের জাগিয়ে তোলে, আমরা ডুবে থাকব।\"\nএখনই নয়, তুমি ভাবলে।\nতুমি এখনও অপেক্ষা করছ, মানবতা যেন তোমাকে জাগিয়ে তোলে।"
  },
  Event_7189_Name = {
    Text = "কাকদের কোরাস"
  },
  Event_7190_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7190_Desc = {
    Text = "ধুলোমাখা এক টেপের রিল। কিন্তু এই ঘরে কোনো প্রজেক্টর নেই, আর এখন প্রাসাদ, সিনেমা আর বিকেলের চা উপভোগ করার সময়ও নয়।\nহয়তো অনেক দিন পরই তুমি সুযোগ পাবে জানতে, এই রিলে আসলে কী লুকিয়ে আছে।"
  },
  Event_7190_Name = {
    Text = "স্মৃতির ছায়ামূর্তি"
  },
  Event_7191_ChoiceDesc1 = {
    Text = "[Leave] 3টি উন্নত প্রার্থনাগাথার মধ্যে 1টি খোদাই করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7191_Desc = {
    Text = "তুমি ছেলেটির পিছু নিলে, না খুব কাছে, না খুব দূরে।\nটাপ। টাপ। টাপ... ছেলেটি গিয়ে থামল মোড়ের মাথায়।\nতুমি তার পেছনে এক টুকরো মিটমিট করা লাল আলো দেখতে পেলে, আর তোমার প্রবৃত্তি জানিয়ে দিল সামনে আছে মোম জাদুঘর।\nছেলেটি ঘুরে দাঁড়াল। তার কোনো চোখ নেই, শুধু অন্ধকার ফাঁপা গহ্বর।\nসে তোমার দিকে তাকিয়ে হাসল।"
  },
  Event_7191_Name = {
    Text = "অন্তিম I"
  },
  Event_7192_ChoiceDesc1 = {
    Text = "[Leave] 50টি কালো চিহ্ন গ্রহণ করো, কিন্তু 「(Skill.Arg1)」 নামের উপসর্গটি বিকশিত হবে"
  },
  Event_7192_Desc = {
    Text = "\nতুমি তার কাঁধে হাত রাখলে।\nছেলেটি ঘুরে দাঁড়াল। তার চোখ নেই, কেবল গভীর কালো গহ্বর।\n\"শুভ সন্ধ্যা। আমি মোম জাদুঘরের পথ খুঁজছি।\"\nছেলেটি সামনে আঙুল তুলল। তুমি দেখলে, তার পেছনে টলমল করে দুলছে লাল আভা।\nতোমার প্রবৃত্তি জানিয়ে দিল, মোম জাদুঘর ঠিক সেখানেই।\nযখন তুমি হুঁশে ফিরলে, ছেলেটি ইতিমধ্যেই চলে গেছে, রেখে গেছে শুধু রাস্তার বাতির ফেলে যাওয়া ছায়া।"
  },
  Event_7192_Name = {
    Text = "অন্তিম I"
  },
  Event_7193_ChoiceDesc1 = {
    Text = "[Pin Down the Crow] 35টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_7193_ChoiceDesc2 = {
    Text = "[Ignore It] ত্যাগ করুন"
  },
  Event_7193_Desc = {
    Text = "একাকী কাকটি কর্কশ স্বরে ডাকে, একে একে নিজের কালো পালক ছিঁড়ে ফেলে।\nব্যথায় কাঁপতে কাঁপতে, তীক্ষ্ণ চিৎকার তোলে, তবু ক্রমশ উন্মত্ত হয়ে ওঠা হাত থামাতে পারে না।\n\"কা—কা—\"\nতার চোখ থেকে নীল অশ্রু ও কালো পিচ্ছিল তরল মিশে গড়িয়ে পড়ে, যার সাক্ষী কেবল তুমি।"
  },
  Event_7193_Name = {
    Text = "গলিত অশ্রু"
  },
  Event_7194_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7194_Desc = {
    Text = "অমূল্য জ্ঞান প্লাবনের মতো তোমার মস্তিষ্কে ঢুকে পড়ে, তারপর কুয়াশায় রূপ নেয়... যখন তুমি হুঁশে ফিরে আসো, অদ্ভুত হলুদ-মলাটের বইটি উধাও..."
  },
  Event_7194_Name = {
    Text = "হলুদ গ্রন্থ"
  },
  Event_7195_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7195_Desc = {
    Text = "তুমি অনায়াসে মোমের ভাস্কর্যগুলিকে পরাস্ত করলে। তারা তোমার সামনে গলে পড়ে।\nভিত্তির গায়ে যেন কয়েকটি লাইন খোদাই করা আছে।\n「A. F. @2, November\nMade by Rogers at @2 College」\nতোমার মনে পড়ে, রজার্স এক আর্ট স্কুলে ভাস্কর্য শিখেছিল। এই কদর্য মোমের ভাস্কর্যগুলো নিশ্চয়ই তার ছাত্রজীবনের কাজ।"
  },
  Event_7195_Name = {
    Text = "খসড়া"
  },
  Event_7196_ChoiceDesc1 = {Text = "[Why?]"},
  Event_7196_ChoiceDesc2 = {
    Text = "[Descend into the Deep Sea]"
  },
  Event_7196_Desc = {
    Text = "\n「প্রতারক! আমার ছেলেকে ফিরিয়ে দাও!」\n「তুমি কি আরকের শুভ্র দেবকন্যা নও? আরককে রক্ষা করা কি তোমার দায়িত্ব নয়? তবে কেন শুধু একটি জাহাজ ফিরে এলো? বলো, বলো!」\n「ওকে ডুবিয়ে মারো! আমার বাবার মৃত্যুর আগে যে যন্ত্রণা তিনি সয়েছেন, ওকেও সেই একই যন্ত্রণা সহ্য করতে হবে!」\n「ডুবিয়ে মারো, ডুবিয়ে মারো!」\n「এই প্রতারককে ডুবিয়ে মারো! পাথরে বেঁধে ডুবিয়ে দাও!」\nসমুদ্রের জল তার মুখ আর নাকে হুড়মুড়িয়ে ঢুকে পড়ে, ফুসফুসের প্রতিটি কোণ থেকে জোর করে বাতাস বের করে দিচ্ছে, তবু তার গায়ে তখনো সেই বিলাসবহুল, কলঙ্কহীন সাদা পোশাক।\nআশীর্বাদপ্রাপ্ত দেবকন্যা হওয়ার পর যে চিন্তাটি প্রথমে আসার কথা ছিল, তা বরং তার মনের সবচেয়ে অন্ধকার কোণ থেকে দেরিতে উঠে এলো।\n「হ্যাঁ, কেন সেই জাহাজগুলো ডুবে গেল?」"
  },
  Event_7196_Name = {
    Text = "ডুবন্ত সাগর"
  },
  Event_7197_ChoiceDesc1 = {
    Text = "[Pin Down the Crow] 30টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
