  Event_7198_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7198_Desc = {
    Text = "মনে হয় যেন এক জোড়া শক্ত, স্থির হাত তোমার কাঁধে এসে থেমেছে; কিন্তু তুমি ঘুরে তাকাতেই, একদা স্পর্শযোগ্য সেই স্পর্শ অধরা হয়ে যায়।"
  },
  Event_7198_Name = {
    Text = "অস্বাভাবিক যোগাযোগ"
  },
  Event_7199_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7199_Desc = {
    Text = "রেলওয়ে সেতু, লন্ডিনিয়ামের শিরা ও স্নায়ু, শহরের হৃদয় ও অঙ্গ-প্রত্যঙ্গকে সংযুক্ত করে। লাই পাগলাগারদ ঠিক সেই অঙ্গ-প্রত্যঙ্গের প্রান্তে অবস্থিত, নীরবে রক্ত ও সংকেত প্রবাহের অপেক্ষায়।"
  },
  Event_7199_Name = {
    Text = "আয়রনওয়ে মরীচিকা"
  },
  Event_7200_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7200_Desc = {
    Text = "তুমি মাটিতে পড়ে থাকা স্যুটকেসটাকে পা দিয়ে পিষে পিষে থামিয়ে দাও, তারপর আবার তুলে নাও।\nধুলো ঝেড়ে ফেলে, মার্ফির বিস্মিত দৃষ্টির সামনে দিয়ে তুমি আবার এগিয়ে চল।"
  },
  Event_7200_Name = {
    Text = "অনাকাঙ্ক্ষিত পত্র"
  },
  Event_7201_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7201_Desc = {
    Text = "একটি কাঠের দরজার আড়ালে বিপদ ওত পেতে আছে; ওটা থেমে থাকার জায়গা নয়। সেটাকে তোমার স্যুটকেসে গুছিয়ে নাও।"
  },
  Event_7201_Name = {
