  },
  Event_7202_ChoiceDesc1 = {
    Text = "[Chase the Crows] Arg1টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_7202_ChoiceDesc2 = {
    Text = "[Ignore] প্রস্থান"
  },
  Event_7202_Desc = {
    Text = "ওটা—বা বলা ভালো, ওগুলো—শোবার ঘরে ভেসে থাকে, ঝনঝন শব্দ তুলে ল্যাম্পশেডে গিয়ে ধাক্কা খায়।"
  },
  Event_7202_Name = {
    Text = "ল্যান্টার্ন-ক্রো"
  },
  Event_7203_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7203_Desc = {
    Text = "এটি আত্মার মাত্রা, জ্ঞানের জগৎ।\nতারা তোমার মন নিয়ে খেলা করা ছাড়া আর কিছুই করতে পারে না।"
  },
  Event_7203_Name = {
    Text = "নসিস টেম্পেস্ট"
  },
  Event_7204_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7204_Desc = {
    Text = "খুলি: হ্যাঙ্ক টিলিংহাস্ট A.F.186-A.F.203 ক্রিওল দ্বীপ\nমেরুদণ্ড: অ্যান্ডি ক্রফোর্ড A.F.177-A.F.203 ন্যারাগানসেট\n..এ নিয়ে বেশি ভাবা যাবে না।"
  },
  Event_7204_Name = {
    Text = "নেমপ্লেট"
  },
  Event_7205_ChoiceDesc1 = {
