  },
  Event_7205_ChoiceDesc2 = {
    Text = "[Ask Doll] 3টি কমান্ড কার্ডের মধ্যে 1টি অনুলিপি করো, এবং 25টি কালো চিহ্ন প্রাপ্ত হও।"
  },
  Event_7205_ChoiceDesc3 = {
    Text = "[Disregard] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7205_Desc = {
    Text = "ডল তোমাকে যে ধাতব খণ্ডাংশটি দিয়েছিল, তা তোমার বুকে অস্থিরভাবে কেঁপে ওঠে, যেন বিরক্ত করা কোনো প্রজাপতি।"
  },
  Event_7205_Name = {
    Text = "অস্থির ব্রোচ"
  },
  Event_7206_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7206_Desc = {
    Text = "\"সে নীরবে অপেক্ষা করে সমাপ্তির রেখায়, তুমি শেষ বিন্দু যেখানেই স্থির করো না কেন—ওই তরুণী প্রহরীকে দেখো; তার এড়িয়ে চলাই শেষমেশ তাকে উন্মাদনায় ঠেলে দেয়।\""
  },
  Event_7206_Name = {
