  },
  Event_7207_Desc = {
    Text = "নির্মাণাধীন, বিশেষ ইভেন্ট"
  },
  Event_7207_Name = {
    Text = "2_16অস্থায়ী"
  },
  Event_7208_ChoiceDesc1 = {
    Text = "[Comfort It] সর্বোচ্চ HP Arg1 বৃদ্ধি পায়"
  },
  Event_7208_ChoiceDesc2 = {
    Text = "[এটিকে অগ্রাহ্য করো]এলোমেলো 2টি কমান্ড কার্ড অরিসন পাবে：「(EnchantConfig.Arg1)」，2টি「(Skill.Arg2)」সংক্রমিত করো"
  },
  Event_7208_Desc = {
    Text = "লিঙ্ক উষ্ণতা ঢেলে দেয় সেই হৃদয়ে, যেখানে এখনো মানুষের স্বভাবের শেষ অংশটুকু ধরে রাখো।\nহৃদয় অন্য প্রান্তের শ্বাস-প্রশ্বাসের ছন্দ অনুকরণ করে, যেন এভাবে সে পরিত্যক্ত হওয়া থেকে বাঁচতে পারে, আর লিঙ্কের সঙ্গে চিরসঙ্গের অধিকার অর্জন করতে পারে।"
  },
  Event_7208_Name = {
    Text = "বাম অলিন্দ"
  },
  Event_7209_ChoiceDesc1 = {
    Text = "দৈবচয়নকৃত উন্নত প্রার্থনাগাথা"
  },
  Event_7210_ChoiceDesc1 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7210_Desc = {
    Text = "তোমার শীতলতা সেই কণ্ঠের মালিককে অনুতপ্ত করে তোলে, আর জল অলস ভঙ্গিতে ঢেউ তুলে আবার স্থিরতায় ফিরে যায়।"
