  },
  Event_7212_Desc = {
    Text = "তুমি আলতো করে ছেলেটির মাথায় হাত বুলিয়ে তাকে তোমার সঙ্গে সঙ্গে আবৃত্তি করতে শেখালে।\n「মায়ের জন্য একটি গান—」\nকণ্ঠগুলো, রাতের আঁধারে উড়ে বেড়ানো পোকামাকড়ের মতো, ফাঁকা মঞ্চ থেকে পাশাপাশি ভেসে উঠল, \nনরমভাবে গিয়ে বসলো পিচকালো দর্শকসারিতে।"
  },
  Event_7212_Name = {
    Text = "অন্তিম III"
  },
  Event_7213_ChoiceDesc1 = {
    Text = "[Leave] 3টি সোনার রেলিকের মধ্যে 1টি অর্জন করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7213_Desc = {
    Text = "তুমি শান্ত ও স্থির রইলে। হঠাৎ এক অভিজাত নারী মঞ্চে ছুটে এলেন।\nতিনি উন্মত্তের মতো ছেলেটির মুখ চেপে খুলে তার ভেতর জোর করে একটি কাঠি গুঁজে দিলেন।\n\"বলো, আমার সঙ্গে কথা বলো।\"\nছেলেটির মুখ থেকে কালো রক্ত গড়িয়ে পড়ছিল। সে অস্পষ্ট স্বরে বকবক করছিল।\n\"মায়ের জন্য একটি গান...\""
  },
  Event_7213_Name = {
    Text = "অন্তিম III"
  },
  Event_7215_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7215_Desc = {
    Text = "ওটা জানালা নয়, ওটা একটি আয়না। র‍্যামোনার টানটান মুখ সেখানে প্রতিফলিত হচ্ছে।\nএই ঘরে কেন কোনো জানালা নেই, কেবল দেয়ালে ঝোলানো এক বিশাল আয়না?"
  },
  Event_7215_Name = {
    Text = "জানালার প্রতিবিম্ব"
  },
  Event_7216_ChoiceDesc1 = {
    Text = "[Hold Silver Key] একটি এলোমেলো জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7216_ChoiceDesc2 = {
    Text = "[Close Your Eyes] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে যেকোনো একটিতে খোদাই করো।"
  },
  Event_7216_Desc = {
    Text = "\nঅযৌক্তিকতার এক উন্মত্ত ঢেউয়ে তুমি ছিন্নভিন্ন হয়ে গেলে, অঙ্গপ্রত্যঙ্গ বিকৃত হয়ে মাটিতে গড়াতে লাগলে, যেন মাত্রা @2-এর পরলোক থেকে আগত কোনো কিছুর ইশারায় নড়াচড়া করছ।\n「না... না...」\nতোমার সুস্থতা টুকরো টুকরো হয়ে প্রাচীর পতনের মতো ভেঙে পড়তে লাগল, প্রলাপের হাসি আর আর্তচিৎকার জড়িয়ে গেল এক বিশাল জালের মতো, যা তোমার চেতনাকে বেঁধে ফেলল, আর তোমার ঠোঁট থেকে ঝরে পড়তে লাগল শুধু অস্পষ্ট গোঙানি।"
  },
  Event_7216_Name = {
    Text = "পর্যবেক্ষকের দৃষ্টি"
  },
  Event_7217_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7217_Desc = {
    Text = "আকাশগঙ্গার মূল বর্ণ বদলে গিয়ে তোমার পায়ের কাছে বর্ণনাতীত নকশা গড়ে তোলে। সেগুলো রুবির মতো সুন্দর, আবার জেলিফিশের মতো স্ফীত। স্যুটকেস থেকে লাল আভা বেরিয়ে আসছে…"
  },
  Event_7217_Name = {
    Text = "নক্ষত্রের চৌরাস্তা"
  },
  Event_7218_ChoiceDesc1 = {
    Text = "[Dispel the Illusion] চাপ 10 বৃদ্ধি করো।"
  },
  Event_7218_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7218_Desc = {
    Text = "ঝাপসা মুখগুলো হঠাৎই আবির্ভূত হয়, তোমাকে ঘিরে ধরে আর অস্তিত্বহীন স্বরযন্ত্র দিয়ে মরিয়া আর্তনাদ তোলে।"
  },
  Event_7218_Name = {
    Text = "বিভ্রম"
  },
  Event_7221_ChoiceDesc1 = {
    Text = "[Catch] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_7221_ChoiceDesc2 = {
    Text = "[Look Down] 75টি কালো চিহ্ন গ্রহণ করো, তবে 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_7221_Desc = {
    Text = "কাকেরা আকাশে ভাসছিল, গলিগুলো যেন তাদের টুকরো টুকরো করে বিল্ডিং ব্লকের মতো ভাগ করে রেখেছে, তাদের কর্কশ ডাক অস্বস্তিকর।\nহঠাৎই ঝাঁকটা অস্থির হয়ে উঠল, যেন কোনো রোগাক্রান্ত প্রবৃত্তি মোচড় খেয়ে জেগে উঠেছে। তারা হিংস্রভাবে একে অপরকে আক্রমণ ও তাড়া করতে লাগল, বিশৃঙ্খলার মাঝে কিছু একটা নিচে পড়ে গেল।"
  },
  Event_7221_Name = {
    Text = "উন্মত্ত কাকের ঝাঁক"
  },
  Event_7222_ChoiceDesc1 = {
    Text = "[Follow the Instructions] সর্বোচ্চ HP Arg1 দ্বারা বৃদ্ধি করো"
  },
  Event_7222_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7222_Desc = {
    Text = "তুমি রৌপ্য চাবির অনুসন্ধানী শক্তি ব্যবহার করে নিকটতম সংযোগস্থল খুঁজতে চেষ্টা করো, কিন্তু যে তথ্য তুমি পাও, তাতে সূক্ষ্ম অস্বাভাবিকতা লুকিয়ে থাকে, যেন তা কোনো এক হস্তক্ষেপে বিকৃত হয়েছে।"
  },
  Event_7222_Name = {
    Text = "অস্বাভাবিক যোগাযোগ"
  },
  Event_7223_ChoiceDesc1 = {
    Text = "[Give It to Doll] একটি এলোমেলো কমান্ড কার্ডে 「(EnchantConfig.Arg1)」 প্রার্থনাগাথা খোদাই করো।"
  },
  Event_7223_ChoiceDesc2 = {
    Text = "[Read the Nameplate] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7223_Desc = {
    Text = "ভাস্করদের সমিতির ব্যর্থ পরীক্ষার দেহ থেকে একটি ধাতব ফ্রেমের নেমপ্লেট পড়ে গেল। রৌপ্য চাবি সেটি অনুভব করে হালকা আলো ছড়াল।"
  },
  Event_7223_Name = {
    Text = "নেমপ্লেট"
  },
  Event_7224_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7224_Desc = {
    Text = "ধারালো ব্লেডের ধারণকারী এক দীর্ঘ হুঙ্কার ছাড়ল, যেন সেই শব্দ পর্বতমালা আর সমুদ্র চিরে ফেলতে পারে।\nশব্দটি মুহূর্তেই মিলিয়ে গেল, আর বাকি দুই সাগরচারীও অদৃশ্য হয়ে গেল... আসলে তা ছিল কেবল ডোমেইনে প্রতিফলিত এক মায়াস্বপ্ন।"
  },
  Event_7224_Name = {
    Text = "নিরলস তাড়া"
  },
  Event_7225_ChoiceDesc1 = {
    Text = "[Repair Wax Sculpture] একটি কার্ড বেছে নাও এবং তার অ্যারিথমেটিকা ব্যয় 1 কমাও"
  },
  Event_7225_Desc = {
    Text = "হাতে মোমবাতি নিয়ে তুমি কুয়াশাচ্ছন্ন ধোঁয়ার ভেতর দিয়ে তার কাছে এগিয়ে যাও।\nসে এক অসমাপ্ত মোমের ভাস্কর্য।\nতার কোমল মুখখানি দু’ভাগে বিভক্ত, এক ভাগে হাসি, অন্য ভাগে @1।\nতার ঈশ্বর হয়ে ওঠো।\nতাকে দাও সৌন্দর্য, তাকে দাও অশ্রু।\nতাকে গড়ো, অথবা তাকে ধ্বংস করো।"
  },
  Event_7225_Name = {
    Text = "অসমাপ্ত মোমের ভাস্কর্য"
  },
  Event_7226_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7226_Desc = {
    Text = "\"অবশ্যই, আমি নিজ চোখে বিলুপ্তি প্রত্যক্ষ করেছি।\" তুমি জবাব দিলে।\nহ্যাঁ, তা ছিল কেবল এক ছোট ইঁদুরের হিংস্র মৃত্যু, এক হৃদয়ের পচন, আর রাতের অন্ত্যেষ্টিতে নিমজ্জিত এক পুষ্পগুচ্ছ আইরিস।"
  },
  Event_7226_Name = {
    Text = "বিলুপ্ত দেবলোক"
  },
  Event_7227_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7227_Desc = {
    Text = "「দিব্য রিয়েল্ম... অবসান... মায়াবী বিষয়... আমি জানি না ঠিক কীকে অবসান বলা যায়।」\nদুজন অবয়ব নরম হাসিতে ফেটে পড়ে, চারদিকে সাদা ঝিলমিল করা আলোর খণ্ডাংশ ভেসে বেড়ায়।\n「তাহলে এখন, তুমি সত্যিকারের অবসান প্রত্যক্ষ করবে।」"
  },
  Event_7227_Name = {
    Text = "বিলুপ্ত দেবলোক"
  },
  Event_7228_ChoiceDesc1 = {
    Text = "[Combine Pages] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7228_ChoiceDesc2 = {
    Text = "[Read] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_7228_ChoiceDesc3 = {
    Text = "[Discard It] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7228_Desc = {
    Text = "আলোবাহকের ভক্তের চাদর থেকে একটি হলদে পৃষ্ঠা ঝরে পড়ল.\nঅদ্ভুত লেখায় ভরা, কিছু হায়ারোগ্লিফের মতো, কিছু অস্বাভাবিকভাবে কাত হয়ে আছে, কিছু আবার একটির উপর আরেকটি চেপে বসেছে। কেবল কয়েকটি শব্দই কষ্টেসৃষ্টে বোঝা যায়.\nশিরোনাম: 「@2 দিবুসের জন্ম」"
  },
  Event_7228_Name = {
    Text = "সাইফার-এডিক্ট·পর্ব II"
  },
  Event_7229_ChoiceDesc1 = {
    Text = "[Struggle] 「(RelicConfig.Arg1)」 নামের রৌপ্য সৃষ্টি অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_7229_ChoiceDesc2 = {
    Text = "[Wallow] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_7229_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7229_Desc = {
    Text = "「আমি ভীষণ কষ্টে আছি, অসহ্য যন্ত্রণা...」\n「কেন আমি? কেন আমাকে এই সব সইতে হবে?」\n「দয়াময় পিতা, আমি কী ভুল করেছি?」\nশোক, যন্ত্রণা, ক্রোধ, হতাশা... সহমর্মিতার স্রোতে ডুবে গিয়ে, এই সব 「রোগী」-দের অনুভূতি তোমার ওপর ভারি হয়ে চেপে বসে। বুকে হাত চেপে ধরে তুমি বুঝতে পারো, শ্বাস নিতে কষ্ট হচ্ছে।"
  },
  Event_7229_Name = {
    Text = "আসক্তি"
  },
  Event_7230_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7230_Desc = {
    Text = "দৃষ্টি মাংস ভেদ করে, পথপ্রদর্শকের রেটিনায় দাগ কেটে দেয়।\nকেউ পালাতে পারে না, যেমন কেউই@2"
  },
  Event_7230_Name = {
    Text = "আড়চোখে তাকাও"
  },
  Event_7231_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7231_Desc = {
    Text = "মনকে কেন্দ্রীভূত করো, গানের কথাগুলো শনাক্ত করো, তারপর অনুভব করো কীভাবে বিশৃঙ্খল শব্দগুলো তোমার মাথার পেছনে আছড়ে পড়ছে।\nএগুলো মানবীয় বোধের অতীত শব্দ।"
  },
  Event_7231_Name = {
    Text = "নাবিক গীতি"
  },
  Event_7232_ChoiceDesc1 = {
    Text = "[Initiate Trial] 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো; বিজয়ী হলে একটি সোনার রেলিক জিতে নাও, আর ব্যর্থ হলে 50টি কালো চিহ্ন লাভ করো।"
  },
  Event_7232_ChoiceDesc2 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7232_Desc = {
    Text = "তোমার পায়ের নিচের আয়নার মতো কালো কাদামাটি থেকে তুমি কিছু গোপন সত্যের আভাস পেয়েছ।\nতার প্রতিফলন ঝাপসা, এক অনমনীয় অন্ধকার কুয়াশায় মোড়া। অদ্ভুতভাবে পরিচিত মনে হয়, তবু তুমি ঠিক বুঝে উঠতে পারো না, সেটি আসলে কী।"
  },
  Event_7232_Name = {
    Text = "আয়নাতলে"
  },
  Event_7233_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7233_Desc = {
    Text = "তুমি রহস্যময় বেনামি চিঠিটিকে উপেক্ষা করো এবং অনায়াসে আগুনে পুড়িয়ে ভস্ম করে দাও।"
  },
  Event_7233_Name = {
    Text = "আরেকটি সাহায্যের চিঠি"
  },
  Event_7234_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7234_Desc = {
    Text = "তুমি চিঠিটা নিজেই পরীক্ষা করো। সিলের গায়ে লেগে আছে আঠালো এক তরল, যেন রক্ত আর কালো পঙ্কের মিশ্রণ, তাতে আটকে আছে কয়েকটি চুলের গোছা।"
  },
  Event_7234_Name = {
    Text = "আরেকটি সাহায্যের চিঠি"
  },
  Event_7235_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7235_Desc = {
    Text = "চিঠিটি যে দিকে ভেসে গিয়েছিল, সেই দিক অনুসরণ করো। দেয়ালের কোণে তুমি ক্ষীণভাবে কিছু ঝকঝকে জিনিসের আভাস পাও।"
  },
  Event_7235_Name = {
    Text = "আরেকটি সাহায্যের চিঠি"
  },
  Event_7236_ChoiceDesc1 = {
    Text = "[Keep Searching] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7236_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7236_Desc = {
    Text = "একটি ক্ষীণ আলো উদিত হয়, উজ্জ্বল ও উষ্ণ। কিন্তু তুমি তাকে অনুসরণ করতে যেতেই, হঠাৎই তা মিলিয়ে যায়।"
  },
  Event_7236_Name = {
    Text = "অস্বাভাবিক যোগাযোগ"
  },
  Event_7237_ChoiceDesc1 = {
    Text = "[Leave] সব জাগরণকারীর অ্যালিমাস Arg1 বৃদ্ধি করো"
  },
  Event_7237_Desc = {
    Text = "তুমি ভয়ে চোখ শক্ত করে বন্ধ করে নিলে।\n\"তুমি ঢাকনাটা তুলে দিলে...\nরহস্য, তুমি রহস্য উন্মোচন করেছো...\"\nশব্দের ঢেউ গর্জন করা সমুদ্রে রূপ নেয়, আর মেঝে ভয়াবহ অনুরণনে প্রচণ্ড কাঁপতে থাকে।\nআর সহ্য করতে না পেরে তুমি হঠাৎ চোখ খুলে ফেলো, অথচ চারপাশে কিছুই দেখতে পাও না।"
  },
  Event_7237_Name = {
    Text = "অন্তিম V"
  },
  Event_7238_ChoiceDesc1 = {
    Text = "[Keep Searching] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7238_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7238_Desc = {
    Text = "নাকের ডগায় ধরা পড়ে এক পরিচিত গন্ধ, ঘরোয়া ও তৃপ্তিকর। ক্যাফেটেরিয়ার সেই সুবাস আরেকবার টেনে নিতে যেই তুমি ঝুঁকে পড়ো, তা সম্পূর্ণভাবে মিলিয়ে যায়।"
  },
  Event_7238_Name = {
    Text = "অস্বাভাবিক যোগাযোগ"
  },
  Event_7239_ChoiceDesc1 = {
    Text = "[Keep Searching] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7239_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7239_Desc = {
    Text = "একটি পরিচিত কণ্ঠস্বর আমার কানে হুইসপার করল, উষ্ণ আর সান্ত্বনাদায়ক। কিন্তু আমি যখন তাকে অনুসরণ করতে চাইলাম, শব্দটি হঠাৎ করেই থেমে গেল।"
  },
  Event_7239_Name = {
    Text = "অস্বাভাবিক যোগাযোগ"
  },
  Event_7240_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7240_Desc = {
    Text = "পশ্চাদ্দৃষ্টির শক্তি স্বল্প সময়ে তোমার জন্য আরেকটি সংযোগস্থল খুঁজে পায় না, কিন্তু অন্তত তুমি কিছুটা সাময়িক মুক্তি অনুভব করো।"
  },
  Event_7240_Name = {
    Text = "অস্বাভাবিক যোগাযোগ"
  },
  Event_7241_ChoiceDesc1 = {
    Text = "[Keep Searching] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7241_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7241_Desc = {
    Text = "মনে হয় যেন এক জোড়া শক্ত, স্থির হাত তোমার কাঁধে এসে থেমেছে; কিন্তু তুমি ঘুরে তাকাতেই, একদা স্পর্শযোগ্য সেই স্পর্শ অধরা হয়ে যায়।"
  },
  Event_7241_Name = {
    Text = "অস্বাভাবিক যোগাযোগ"
  },
  Event_7242_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7242_Desc = {
    Text = "「এন」-এর ছায়া ঘুষির আঘাতে ছিটকে যায়, কালো কণাগুলো ডোমেইনের কুয়াশার সঙ্গে মিশে গিয়ে অধরা হয়ে ওঠে।\n「মজার নয়, তবু আকর্ষণীয়। আমাদের সত্যিকারের সাক্ষাতের জন্য আমি অধীর আগ্রহে অপেক্ষা করব...」"
  },
  Event_7242_Name = {
    Text = "প্রদর্শনীর সময়"
  },
  Event_7243_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7243_Desc = {
    Text = "\n\"ভালো বাচ্চা। কিন্তু তবু, তোমাকে একটু শাস্তি তো দিতেই হবে।\"\nমাত্রিক ফাটলের ভেতর মিলিয়ে গেল ড্যাফোডিলের হালকা হাসি।"
  },
  Event_7243_Name = {
    Text = "ইঙ্গিতের সময়"
  },
  Event_7244_ChoiceDesc1 = {
    Text = "[Silver Chip] 50% সম্ভাবনায় সোনার রেলিক 「(RelicConfig.Arg2)」 অর্জন করো, 50% সম্ভাবনায় 「(Skill.Arg3)」 বিকাশ করো।"
  },
  Event_7244_ChoiceDesc2 = {
    Text = "[Red Chip] 50% সম্ভাবনায় 75টি কালো চিহ্ন প্রাপ্ত হও, 50% সম্ভাবনায় 「(Skill.Arg3)」 উপসর্গ বিকশিত করো।"
  },
  Event_7244_ChoiceDesc3 = {
    Text = "[Black Chip] 50% সম্ভাবনায় অভিশপ্ত নিদর্শন 「(RelicConfig.Arg2)」 অর্জন করো, 50% সম্ভাবনায় 「(Skill.Arg3)」 বিকাশ করো।"
  },
  Event_7244_Desc = {
    Text = "ভালো... ভালো...\nএখন, তোমার কামনার চিপটি বেছে নাও।"
  },
  Event_7244_Name = {
    Text = "প্রদর্শনীর সময়"
  },
  Event_7245_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7245_Desc = {
    Text = "\"আচ্ছা, আচ্ছা। লোকটা সবসময়ই আন্তঃমাত্রিক প্রাণীদের প্রতি দুর্বল ছিল। এই মাত্রিক ফাটলগুলো দিয়ে অবাধে চলাফেরা করতে আমার বেশ কষ্টই হয়েছে। আহ, সেটা বোধহয় তিন হাজার বছর আগের কথা।\""
  },
  Event_7245_Name = {
    Text = "ইঙ্গিতের সময়"
  },
  Event_7246_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7246_Desc = {
    Text = "প্রার্থনা করো যেন গবেষণা পরিচালক তোমার বুকে কোনো বোমা বসিয়ে না দেন।"
  },
  Event_7246_Name = {
    Text = "অস্থির ব্রোচ"
  },
  Event_7247_ChoiceDesc1 = {
    Text = "[Leave] একটি কমান্ড কার্ড ধ্বংস করো এবং 25টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_7247_Desc = {
    Text = "\"একজন দয়ালু অচেনা, পথহারা মানুষকে দিশা দিচ্ছে,\" ঠোঁট বাঁকিয়ে সে বলল, \"হালকা হয়ে ভ্রমণ করো। সার্বেরাস অপেক্ষা করছে।\"\nতার হাতে ধরা যন্ত্রটা হঠাৎ কেঁপে উঠল।"
  },
  Event_7247_Name = {
    Text = "অদ্ভুত সঙ্গী III"
  },
  Event_7248_ChoiceDesc1 = {
    Text = "[Move Slowly] তিনটি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_7248_ChoiceDesc2 = {
    Text = "[Lie Down] তিনটি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_7248_Desc = {
    Text = "\"জলাভূমিতে পড়লে, কখনোই লড়াই করবে না।\"\nতুমি এই বেঁচে থাকার নিয়মটি মনে রাখো, ইস্টার দ্বীপের মূর্তির মতো একদম স্থির হয়ে দাঁড়িয়ে থাকো।\nপাঁচ মিনিট, দশ মিনিট, এক ঘণ্টা... শেষমেশ কালো কাদা ধৈর্য হারিয়ে তোমার পায়ের নিচ থেকে সরে যায়।"
  },
  Event_7248_Name = {
    Text = "বিষণ্ণ জলাভূমি"
  },
  Event_7249_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7249_Desc = {
    Text = "তুমি এক অস্বাভাবিক হাত খেয়াল করো। এটি কোমল, ফ্যাকাশে, আর শুরু থেকে শেষ পর্যন্ত শান্ত।\nআরও গুরুত্বপূর্ণ—তুমি বুঝতে পারো, এ তোমারই হাত।\nতুমি ধীরে ধীরে সেটিকে ধরো।\nহাতটি পাল্টা তোমার হাত চেপে ধরে। তুমি অস্থিমজ্জা-শীতল এক ঠান্ডা আর এক মায়াস্বপ্ন অনুভব করো, তারপরই জলাভূমি মিলিয়ে যায়।"
  },
  Event_7249_Name = {
    Text = "বিষণ্ণ জলাভূমি"
  },
  Event_7250_ChoiceDesc1 = {
    Text = "[Cut Off Hand] তিনটি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_7250_ChoiceDesc2 = {
    Text = "[Soothe Them] তিনটি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_7250_Desc = {
    Text = "তুমি তলোয়ার ঘুরিয়ে, তাদের একে একে কেটে ফেলো।\nরক্ত ছিটকে পড়ে তোমার দেহে, মুখে, চুলে, তবু তুমি যেন কিছুই টের পাও না।\nঅগণিত হাত যন্ত্রণায় চিৎকার করে ওঠে, আর জলাভূমি মিলিয়ে যায়।\nওই আর্তনাদগুলোকে দুঃস্বপ্ন থেকে সরে যেতে এক সপ্তাহ সময় লাগে।"
  },
  Event_7250_Name = {
    Text = "বিষণ্ণ জলাভূমি"
  },
  Event_7251_ChoiceDesc1 = {
    Text = "[Pick up the Silver Core] একটি রৌপ্য সৃষ্টি-কে উন্নয়ন অর্জন করে সোনালি সৃষ্টি 「(RelicConfig.Arg1)」-এ রূপান্তর করো"
  },
  Event_7251_ChoiceDesc2 = {
    Text = "[Attempt Awakening] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 এবং 「(Skill.Arg3)」 বিকশিত হবে।"
  },
  Event_7251_ChoiceDesc3 = {
    Text = "[Ignore] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7251_Desc = {
    Text = "ঢিলা ডেকের তক্তার নিচ থেকে নোংরা কালো কাদা গলিয়ে বেরিয়ে আসে।\nসেই কাদার ভেতরেই, 「সিলভার কোর」-এর পরিচিত ঝিলিক তোমার চোখে ধরা পড়ে।"
  },
  Event_7251_Name = {
    Text = "অস্তিত্বের প্রমাণ"
  },
  Event_7252_ChoiceDesc1 = {
    Text = "[The Rat] এলোমেলো একটি কমান্ড কার্ড-এর ওপর প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_7252_ChoiceDesc2 = {
    Text = "[The Candle] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, কিন্তু 「(Skill.Arg2)」 উপসর্গটি বিকশিত হবে।"
  },
  Event_7252_Desc = {
    Text = "ডিসলুট তোমার সামনে গলে বিলীন হয়ে যায়। তার ভেতর থেকে কালো ছাই কুয়াশায় জমাট বেঁধে এক অদ্ভুত দাঁড়িপাল্লা রূপ নেয়। এক পাশে ঘুমিয়ে আছে এক ইঁদুর। অন্য পাশে বসে আছে মোমের ছোট্ট একটি মোমবাতি, যার গড়ন এক ছোট বালকের মতো।\nতুমি স্বতঃসিদ্ধ জানো, তোমাকে একটি নির্বাচন করতেই হবে।"
  },
  Event_7252_Name = {
    Text = "যুক্তি ও আবেগ"
  },
  Event_7253_ChoiceDesc1 = {Text = "[Call Out]"},
  Event_7253_ChoiceDesc2 = {
    Text = "[Check Carefully]"
  },
  Event_7253_Desc = {
    Text = "তুমি মোড় ঘোরাতেই চারপাশ ক্রমে ঝাপসা হয়ে আসে, অথচ ভয়াল গর্জনগুলো তীক্ষ্ণই থাকে।\nপদধ্বনি প্রতিধ্বনিত হয়, আর তুমি ঘুরে তাকাতেই কুয়াশার ভেতর অস্পষ্ট এক অদ্ভুত অবয়ব চোখে পড়ে; মানবাকৃতি সেই দেহটি মানুষের মতোই দাঁড়িয়ে, কিন্তু তার পেছনে রয়েছে দুটি ছায়া, যেন কোনো বিশাল প্রজাপতির ডানা।\n「সাবধানে, 」 রামোনা হুইসপার করে, 「ডোমেইনের ভেতরে যা দেখো, তা সবসময় সত্যি নাও হতে পারে। সাবধান না থাকলে, নিজেকেই বিপদে ফেলবে।」"
  },
  Event_7253_Name = {
    Text = "কুয়াশাবৃত ছায়ামূর্তি"
  },
  Event_7254_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7254_Desc = {
    Text = "তুমি রৌপ্য চাবি বের করো, শোক ও শ্রদ্ধায় তাকে আঁকড়ে ধরো। এক মৃদু, কুয়াশার মতো আভা তোমাকে আচ্ছন্ন করে।\nনীরবতার মাঝে কেবল একটি দীর্ঘশ্বাস ভেসে থাকে।"
  },
  Event_7254_Name = {
    Text = "পর্যবেক্ষকের দৃষ্টি"
  },
  Event_7255_ChoiceDesc1 = {
    Text = "[Choose Silver River] একটি এলোমেলো কমান্ড কার্ডে 「(EnchantConfig.Arg1)」 প্রার্থনাগাথা খোদাই করো।"
  },
  Event_7255_ChoiceDesc2 = {
    Text = "[Choose Rainbow Path] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত হবে।"
  },
  Event_7255_Desc = {
    Text = "ধুপ, ধুপ, ধুপ।\nতোমার হৃদয় ঢাকের মতো বাজছে, মুখ শুকিয়ে গেছে, আর ওপর থেকে নেমে আসা এক দৃষ্টি মেরুদণ্ড ভেদ করে বুকে গেঁথে যাচ্ছে।\nতোমার সামনে দেখা দেয় এক দ্বিখণ্ডিত পথ: একদিকে বয়ে চলেছে নক্ষত্রখচিত নদী, অন্যদিকে ঝিলমিল করছে রঙধনুর আভা।"
  },
  Event_7255_Name = {
    Text = "নক্ষত্রের চৌরাস্তা"
  },
  Event_7256_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7256_Desc = {
    Text = "লেগে থাকা দৃষ্টিগুলো অবিরত তোমাকে পর্যবেক্ষণ করে, আর তোমার চামড়ার নিচের কোষগুলো চিৎকার করে পালাতে থাকে, শিরাগুলো কিলবিল করতে থাকে কৃমির মতো।\nতুমি অনুভব করো শক্তির এক স্রোত, যা উথলে উঠে বিস্ফোরিত হচ্ছে তোমার অঙ্গপ্রত্যঙ্গের গ্রোটেস্ক বিকৃতির ভেতর দিয়ে।"
  },
  Event_7256_Name = {
    Text = "পর্যবেক্ষকের দৃষ্টি"
  },
  Event_7257_ChoiceDesc1 = {
    Text = "[Leave] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_7257_ChoiceDesc2 = {
    Text = "[Leave] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_7257_ChoiceDesc3 = {
    Text = "[Leave] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_7257_Desc = {
    Text = "\n“না, তা ঠিক নয়। আরশোলার সঙ্গে তুলনা করলে, অন্তত তোমাদের গায়ে নরম লোম আছে।\nকেউই নরম লোমের আকর্ষণ এড়াতে পারে না।”\nইঁদুরগুলো নিজেদের মধ্যে ফিসফিস করে কথা বলল, আর শেষমেশ তোমার কথার সঙ্গে একমত হলো।\n“যদিও, খুব বেশি লোম তো আর নেই।”\nপ্রশংসা পাওয়া সবসময়ই মনোরম। বিদায় নেওয়ার আগে, ইঁদুরগুলো তোমাকে একটি ছোট উপহার দিয়ে গেল।"
  },
  Event_7257_Name = {
    Text = "প্লেগ"
  },
  Event_7258_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7258_Desc = {
    Text = "「আমি একমত! মানুষ আর ইঁদুর একসাথে থাকতে পারে না!」\nইঁদুরগুলো কিছুটা রেগে গেল, সাদা দাঁত বের করে।\n「তাহলে তুমি এখনো এখানে কেন? তোমার জিনিসপত্র নিয়ে চলে যাও, আর কখনো ফিরে এসো না।」"
  },
  Event_7258_Name = {
    Text = "প্লেগ"
  },
  Event_7259_ChoiceDesc1 = {
    Text = "[Leave] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_7259_Desc = {
    Text = "এক অদ্ভুত ডানা ঝাপটানোর শব্দ তোমার চারপাশে ভেসে থাকে। ঘোরের মধ্যে তুমি দেখো, রজার্স চিকিৎসা শয্যায় শুয়ে আছে, হাতে রক্তছিটা, বুকে জড়িয়ে আছে পুতুল জর্জ।\nতুমি চোখ খুলে দেখো, ক্লেমেন্টাইন কোথাও নেই।\nযখন তুমি জেগে উঠো, ক্লেমেন্টাইন অনেক আগেই চলে গেছে।"
  },
  Event_7259_Name = {
    Text = "সম্মোহন চিকিৎসা"
  },
  Event_7260_ChoiceDesc1 = {
    Text = "[Unlock] চাবি ব্যবহার করুন।"
  },
  Event_7260_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7260_Desc = {
    Text = "একটি দরজা তোমার পথ রুদ্ধ করে। তুমি সম্ভাব্য সব উপায়ই চেষ্টা করেছ, তবু সেটি অনড় থেকে গেছে।"
  },
  Event_7260_Name = {
    Text = "মরিচা ধরা দ্বার"
  },
  Event_7260_Tips1 = {
    Text = "আপনাকে 「মরিচা ধরা চাবি」 খুঁজে বের করতে হবে।"
  },
  Event_7261_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7261_Desc = {
    Text = "তুমি তাকাও সেই দিকে, যেটিকে তুমি দৃষ্টির উৎস বলে বিশ্বাস করো। কর্মশালার ছাদ হঠাৎই দূরে সরে যেতে থাকে, আর বিশাল এক মণির স্তূপীকৃত ছায়া মাথার ওপর ঝুলে ওঠে। তোমার দৃষ্টির সঙ্গে তার মাত্র আংশিক মিলন হলেও, তুমি অনুভব কর এক অপরিমেয় চাপ।"
  },
  Event_7261_Name = {
    Text = "কার দৃষ্টি?"
  },
  Event_7262_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7262_Desc = {
    Text = "কালো বিড়ালটি সাবধানে এগিয়ে আসে এবং তোমার তালুর ওপর এক অন্ধকার পিণ্ড উগরে দেয়।"
  },
  Event_7262_Name = {
    Text = "রাতের বিড়ালের অভিশাপ"
  },
  Event_7263_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7263_Desc = {
    Text = "\"বুদ্ধিদীপ্ত নির্বাচন। ভয়ংকর প্রতিপক্ষের মুখোমুখি হলে নিজেকে আর শত্রুকে জানা জরুরি, তাই না? কিন্তু সাবধান—মাত্রাগুলোর রহস্য সম্পর্কে অতিরিক্ত জানলে তোমার মন বিচলিত হয়ে যেতে পারে।\"\n\"ও লোকটা মাত্রার সীমানা-ছাড়া সত্তাদের নিয়ে ভাবা বন্ধই করতে পারে না। এই মাত্রিক ফাটলগুলোর ভেতর দিয়ে অবাধে চলাচল করতে শিখতে আমার যুগ লেগে গেছে। আহ, ওটা ছিল তিন হাজার বছর আগে।\""
  },
  Event_7263_Name = {
    Text = "ইঙ্গিতের সময়"
  },
  Event_7264_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7264_Desc = {
    Text = "“ম্যাঁও, ম্যাঁও ম্যাঁও, ম্যাঁও ম্যাঁও ম্যাঁও...”\nতুমি গলা চেপে ধরলে, প্রাণপণে দুর্বল আর নিরীহ শোনানোর চেষ্টা করলে।\n“ম্যাঁও! ম্যাঁও ম্যাঁও! ম্যাঁও ম্যাঁও ম্যাঁও!”\nবিড়ালগুলোর দল যেন তোমার শুভেচ্ছা মেনে নিল, উচ্ছ্বসিত ডাকে সাড়া দিল। তোমার আর তাদের আর্তনাদ প্রতিধ্বনিত হতে থাকল এপার-ওপার, দিনরাত একটানা, এমনকি চাঁদটাকেও ভয় দেখিয়ে মেঘের আড়ালে লুকিয়ে ফেলল।"
  },
  Event_7264_Name = {
    Text = "বিড়ালের শহর"
  },
  Event_7265_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7265_Desc = {
    Text = "তুমি জোর করে কাকের ঠোঁটকে নিজের পালক উপড়ে ফেলা থেকে সরিয়ে দাও, কিন্তু তা নির্দয়ভাবে আবার মোচড় খেয়ে ফিরে আসে, তার শক্তিতে তোমার হাড়ে কড়মড় শব্দ ওঠে।\nনিজের সমস্ত শক্তি ঢেলে তুমি কাকের দেহকে চেপে ধরো, তার উন্মত্ত আত্ম-ক্ষতিকে থামিয়ে দাও, আর মুখ লাল হয়ে ওঠে প্রচেষ্টায়।\nঠিক যখন তুমি স্বস্তির নিঃশ্বাস ফেলছ, অর্ধেক টাক হয়ে যাওয়া কাকের গলা হঠাৎ তীব্রভাবে পেছনে বেঁকে যায়, তার দেহ ঢিলে হয়ে তোমার হাতের কার্ডের মধ্যে কালো কাদার পুকুরে রূপান্তরিত হয়।"
  },
  Event_7265_Name = {
    Text = "গলিত অশ্রু"
  },
  Event_7266_ChoiceDesc1 = {
    Text = "[Pin Down the Crow] 20টি কালো চিহ্ন গ্রহণ করো, তবে 「(Skill.Arg2)」 বিকাশ করো।"
  },
  Event_7266_ChoiceDesc2 = {
    Text = "[Ignore It] ত্যাগ করুন"
  },
  Event_7266_Desc = {
    Text = "একাকী কাকটি কর্কশ স্বরে ডাকে, একে একে নিজের কালো পালক ছিঁড়ে ফেলে।\nব্যথায় কাঁপতে কাঁপতে, তীক্ষ্ণ চিৎকার তোলে, তবু ক্রমশ উন্মত্ত হয়ে ওঠা হাত থামাতে পারে না।\n\"কা—কা—\"\nতার চোখ থেকে নীল অশ্রু ও কালো পিচ্ছিল তরল মিশে গড়িয়ে পড়ে, যার সাক্ষী কেবল তুমি।"
  },
  Event_7266_Name = {
    Text = "গলিত অশ্রু"
  },
  Event_7267_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7267_Desc = {
    Text = "কাকটি নিজের পালক ছিঁড়ে খায়, যেমন মানুষ নিজের শরীরকেই কুরে কুরে খায়।\nভয়ের এই জগতে এমন দৃশ্য নিত্যনৈমিত্তিক। তুমি সব জীবকে রক্ষা করতে পারবে না।"
  },
  Event_7267_Name = {
    Text = "গলিত অশ্রু"
  },
  Event_7268_ChoiceDesc1 = {
    Text = "[Leave] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_7268_Desc = {
    Text = "\"আমি ছাত্রদের নিয়ে ফিরে আসব।\" মেয়েটি জাগরণকারীর স্কার্ট টেনে ধরে দৃঢ়চেতা কণ্ঠে বলল, \"খেয়াল রেখো... সমুদ্রে পড়ে যেয়ো না।\""
  },
  Event_7268_Name = {
    Text = "জাহাজের পবিত্র কন্যার আশীর্বাদ"
  },
  Event_7269_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7269_Desc = {
    Text = "হা হা, কালো—আমার প্রিয়। বিশৃঙ্খলা, বিভ্রান্তি, যন্ত্রণা... এ পর্যন্ত তোমার বোঝা হয়ে যাওয়ার কথা—কালো কখনোই শুভ লক্ষণ নয়।\nতাহলে, তোমার পরবর্তী নির্বাচন কী?"
  },
  Event_7269_Name = {
    Text = "প্রদর্শনীর সময়"
  },
  Event_7270_ChoiceDesc1 = {
    Text = "[Pin Down the Crow] 25টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_7270_ChoiceDesc2 = {
    Text = "[Ignore It] ত্যাগ করুন"
  },
  Event_7270_Desc = {
    Text = "একাকী কাকটি কর্কশ স্বরে ডাকে, একে একে নিজের কালো পালক ছিঁড়ে ফেলে।\nব্যথায় কাঁপতে কাঁপতে, তীক্ষ্ণ চিৎকার তোলে, তবু ক্রমশ উন্মত্ত হয়ে ওঠা হাত থামাতে পারে না।\n\"কা—কা—\"\nতার চোখ থেকে নীল অশ্রু ও কালো পিচ্ছিল তরল মিশে গড়িয়ে পড়ে, যার সাক্ষী কেবল তুমি।"
  },
  Event_7270_Name = {
    Text = "গলিত অশ্রু"
  },
  Event_7271_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7271_Desc = {
    Text = "ওটা ছিল কেবিনের গভীর অংশ, বহুদিনের অবহেলায় ডুবে থাকা, অল্প আলোয় ঢাকা, পথনির্দেশহীন।\nমেয়েটি জাহাজের সন্তের আশীর্বাদ নিয়ে, তাদের চুক্তি অনুযায়ী যাত্রা শুরু করবে।"
  },
  Event_7271_Name = {
    Text = "জাহাজের পবিত্র কন্যার আশীর্বাদ"
  },
  Event_7272_ChoiceDesc1 = {
    Text = "[Chase the Song] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7272_ChoiceDesc2 = {
    Text = "[Sing Along] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো এবং খোদাই করার প্রার্থনাগাথা পরিবর্তন করো।(ব্যবহার: 1/2)"
  },
  Event_7272_Desc = {
    Text = "দূরবর্তী গানটি ভেঙে গিয়ে তারাধূলিতে পরিণত হলো:\n“আমি অভিশাপ দিই রাতের গলির নোংরা জলাবদ্ধতাকে, ভেঙে পড়া দেয়ালে আঁকড়ে ধরা পচা ফুলগুলোকে, শিকল জড়িয়ে ধরে কাদায় ডুবে যাওয়া মস্তিষ্ককে। কুয়াশা আমার অস্তিত্ব মুছে ফেলার আগে, গোধূলি নেমে যাবে গভীরতম @3-এ।”"
  },
  Event_7272_Name = {
    Text = "বিবর্ণ অভিশাপ"
  },
  Event_7273_ChoiceDesc1 = {
    Text = "[Chase the Song] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7273_Desc = {
    Text = "দূরবর্তী গানটি ভেঙে গিয়ে তারাধূলিতে পরিণত হলো:\n“আমি অভিশাপ দিই রাতের গলির নোংরা জলাবদ্ধতাকে, পচা ফুলগুলো আঁকড়ে ধরে থাকে ভেঙে পড়া দেয়াল, শিকল জড়িয়ে ধরে কাদায় ডুবে যাওয়া মস্তিষ্ককে। কুয়াশা আমার অস্তিত্ব মুছে ফেলার আগে, গোধূলি ডুবে যাবে গভীরতম @4-এ।”"
  },
  Event_7273_Name = {
    Text = "বিবর্ণ অভিশাপ"
  },
  Event_7274_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7274_Desc = {
    Text = "সিলভার কোর তোমার জাগরণে সাড়া দেয়নি, বরং এক উষ্ণ আভা ছড়িয়ে দিয়েছে।"
  },
  Event_7274_Name = {
    Text = "নিঃসঙ্গ সিলভার কোর"
  },
  Event_7275_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7275_Desc = {
    Text = "ঘূর্ণায়মান কালো কুয়াশা মেরুদণ্ড বেয়ে ধীরে ধীরে উঠে আসে, যতক্ষণ না তুমি মাটিতে লুটিয়ে পড়ো, আর এই বাক্যটি বারবার পুনরাবৃত্তি করতে থাকো।"
  },
  Event_7275_Name = {
    Text = "অদৃশ্য"
  },
  Event_7276_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7276_Desc = {
    Text = "হ্যাঁ, তোমার মণি থেকে ধীরে ধীরে গড়িয়ে পড়া কাচের মতো তরলই তোমার নিষিদ্ধতার কলুষের প্রমাণ।\nএই মুহূর্তে সততা নিজেই নৈতিকতার বিপরীতে দাঁড়িয়ে।"
  },
  Event_7276_Name = {
    Text = "অদৃশ্য"
  },
  Event_7277_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7277_Desc = {
    Text = "প্রাচীন মুদ্রাটি আঠালো ও স্যাঁতসেঁতে, যেন নোংরা আবর্জনায় মোড়া, আর তার গা থেকে দৃশ্যমান কালো ধোঁয়া বেরোচ্ছে।"
  },
  Event_7277_Name = {
    Text = "দ্বিমুখী প্রাচীন মুদ্রা"
  },
  Event_7278_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7278_Desc = {
    Text = "তোমার তীক্ষ্ণ স্নায়ুপ্রান্ত মারাত্মক সতর্কবার্তা পাঠায়। তুমি হঠাৎ সরে গিয়ে, অনিচ্ছায় হাত গুটিয়ে নাও。\nআরও একবার, অল্পের জন্য পালানো…\nএ কি অভিশাপ? নাকি মৃত্তিকা বিদীর্ণ পুনর্জন্ম?"
  },
  Event_7278_Name = {
    Text = "দ্বিমুখী প্রাচীন মুদ্রা"
  },
  Event_7279_ChoiceDesc1 = {
    Text = "[প্রজাপতি মুক্তি]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，সংক্রমিত হও「(Skill.Arg2)」"
  },
  Event_7279_ChoiceDesc2 = {
    Text = "[Become a Butterfly] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7279_ChoiceDesc3 = {
    Text = "[Swallow Back] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7279_Desc = {
    Text = "এই রাতে কত কিছুই না ঘটে গেছে।\nডকে আক্রমণ, ভূতুড়ে মালবাহী জাহাজ, সাগরচারী, তুলু, মার্ফি, রামোনা... সবকিছু ঘূর্ণাবর্তে ঘুরে মিশে গেছে মিথাগের রেস্তোরাঁর সকাল 7টার ওটমিলে।\nতুমি সামনে বসা Awakener-কে কিছু জিজ্ঞেস করতে চাও, কিন্তু কোথা থেকে শুরু করবে বুঝে উঠতে পারো না; গলায় যেন কিছু আটকে আছে—অথবা পেটে উড়ছে অদৃশ্য প্রজাপতির ঝাঁক।"
  },
  Event_7279_Name = {
    Text = "বাটারফ্লাই ইফেক্ট"
  },
  Event_7280_ChoiceDesc1 = {
    Text = "[Dispel the Illusion] Arg3 HP হারাও"
  },
  Event_7280_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7280_Desc = {
    Text = "ঝাপসা মুখগুলো হঠাৎই আবির্ভূত হয়, তোমাকে ঘিরে ধরে আর অস্তিত্বহীন স্বরযন্ত্র দিয়ে মরিয়া আর্তনাদ তোলে।"
  },
  Event_7280_Name = {
    Text = "বিভ্রম"
  },
  Event_7281_ChoiceDesc1 = {
    Text = "[Join the Prayer] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7281_ChoiceDesc2 = {
    Text = "[Sink into Ocean] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 এবং 「(Skill.Arg3)」 বিকশিত করো।"
  },
  Event_7281_ChoiceDesc3 = {
    Text = "[Surface] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7281_Desc = {
    Text = "\"স্নিগ্ধ ঈশ্বর, সর্বশক্তিমান ঈশ্বর।\nদয়া করে প্রচণ্ড ঝড়কে শান্ত করো, উন্মত্ত স্রোতকে রুখে দাও।\nসমুদ্রকে আমাদের গভীর নিবাসে পরিণত করো, আমাদের রাজ্যকে ঢেকে রাখো এক চিরন্তন পর্দায়...\"\nভক্তদের ফিসফিসানি অবশেষে এমন শব্দে রূপ নেয়, যা তুমি বুঝতে পারো; কিন্তু সেই শব্দের সঙ্গেই আসে এক অনিবার্য শ্বাসরোধ।"
  },
  Event_7281_Name = {
    Text = "স্বপ্নলোক প্রার্থনা"
  },
  Event_7282_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7282_Desc = {
    Text = "তুমি বাকি থাকা মাংসের টুকরোগুলো বিড়ালের ঝাঁকের দিকে ছুড়ে দাও।\nবিড়ালগুলো কালো জোয়ারের মতো ঝাঁপিয়ে পড়ে, উন্মত্তভাবে মাংস ছিঁড়ে খেতে থাকে, তারপর দ্রুত ছত্রভঙ্গ হয়ে যায়।\nদুর্ভাগ্যবশত, মাংসটি পচা। তা তাদের খালি পেট ভরায়, কিন্তু তৃপ্তি এনে দিতে পারে না।"
  },
  Event_7282_Name = {
    Text = "বিড়ালের শহর"
  },
  Event_7283_ChoiceDesc1 = {Text = "[Take It]"},
  Event_7283_Desc = {
    Text = "প্রায় পারদের মতো এক সিলভার পদার্থ, D-পঙ্ক থেকে পরিশোধিত, তীব্র মানসিক শক্তিতে পরিপূর্ণ, আচার অনুষ্ঠানে আরও অধিক জাগরণকারীকে সংযুক্ত করতে ব্যবহৃত হয় প্রায় পারদের মতো এক সিলভার পদার্থ, D-পঙ্ক থেকে পরিশোধিত, তীব্র মানসিক শক্তিতে পরিপূর্ণ, আচার অনুষ্ঠানে আরও অধিক জাগরণকারীকে সংযুক্ত করতে ব্যবহৃত হয়।"
  },
  Event_7283_Name = {
    Text = "সিলভার"
  },
  Event_7284_ChoiceDesc1 = {
    Text = "[Leave] এক জাগরণকারীকে জাগরণ ঘটাও, সেই কার্ডের অ্যারিথমেটিকা ব্যয় 2 কমাও, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7284_ChoiceDesc2 = {Text = "[Leave]"},
