  },
  Event_7290_Desc = {
    Text = "তুমি পা রাখলে এক অস্বস্তিকর নীরবতার ভেতর, আর একের ওপর এক চেপে থাকা দরজাগুলো নিয়ন্ত্রণহীনভাবে ঘুরতে ঘুরতে তোমার দেহকে টেনে নিল ঘূর্ণাবর্তের কেন্দ্রে।\nমাথা ঘুরে যায়, দিশেহারা হয়ে তুমি উল্টে থাকা দরজাগুলোর মাঝে লড়াই করো, কষ্টে চোখে পড়ে বেরোনোর পথ, তবু বারবার অনিবার্যভাবে আরেকটি দরজার ভেতর পড়ে যেতে থাকো।\nএইবার, তুমি এক দরজার সামনে থেমে যাও; তার ওপারের অজানা জীব প্রাণঘাতী আকর্ষণ ছড়িয়ে দেয়, তোমার সুস্থতার তারগুলোকে টেনে ধরে টানটান করে তোলে।\nহ্যাঁ, এটা সত্যিই মরণঘাতী।"
  },
  Event_7290_Name = {
    Text = "বহু দ্বারের ওপারে"
  },
  Event_7291_ChoiceDesc1 = {
    Text = "[Ecstasy] একটি কমান্ড কার্ড ধ্বংস করো এবং Arg1 HP পুনরুদ্ধার করো"
  },
  Event_7291_ChoiceDesc2 = {
    Text = "[Stop] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7291_Desc = {
    Text = "মনে হয় যেন অনায়াসে তোমার করোটিটি চিড় ধরে খুলে গেছে, আর বমি উদ্রেককারী মাথা ঘোরা ঢেউয়ের মতো তোমার মস্তিষ্কে প্লাবিত হচ্ছে। এক অদৃশ্য হাত তোমার মনকে নাড়ে আর ঘূর্ণায়মান করে, আগেই তরল হয়ে যাওয়া পদার্থকে পচা মণ্ডে পরিণত করে।\nহজম না হওয়া, পায়েসের মতো পাকস্থলীর উপাদানের মতো, তা মাধ্যাকর্ষণকে অমান্য করে তোমার ফাঁপা, বন্ধ্যা সেরিব্রাল কর্টেক্সে ঢেলে পড়ে।\nতা মথে, মেশায়, আঁচড়ায়, আনন্দের খণ্ডাংশ ছিটিয়ে দেয়, আর সূর্যাস্তের অবশিষ্টাংশ তোমার মাংসে মিশিয়ে দেয়।"
  },
  Event_7291_Name = {
    Text = "মস্তিষ্ক আলোড়ন"
  },
  Event_7292_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7292_Desc = {
    Text = "হঠাৎ আবির্ভূত নরককুকুরদের তুলনায় সাধারণ তুষারপাত তোমার মনোযোগের যোগ্য নয়। ধীরে ধীরে ঝরে পড়া তুষফুল উপেক্ষা করে তুমি রাতের অন্ধকারে ছুটে যাও।"
  },
  Event_7292_Name = {
    Text = "তুষার"
  },
  Event_7293_ChoiceDesc1 = {
    Text = "[Connect] Arg2 HP পুনরুদ্ধার করো।"
  },
  Event_7293_Desc = {
    Text = "কুয়াশা ভারী হয়ে ঝুলে থাকে, আর তোমার ব্যাজে মিটমিট করে ফ্যাকাশে সিলভার আভা। যোগাযোগকারীটা কড়কড় শব্দ তুলে জেগে ওঠে। কেউ একজন ডাকছে।"
  },
  Event_7293_Name = {
    Text = "সংযোগস্থল"
