  Event_7294_ChoiceDesc1 = {
    Text = "[Feel Fear] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7294_ChoiceDesc2 = {
    Text = "[Steadfast Will] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7294_Desc = {
    Text = "ভৌতিক আর্তনাদ প্রতিধ্বনিত হয়, অথচ লন্ডিনিয়াম নীরব, যেন মৃত কিংবা নিদ্রিত।\nতুমি রেলসেতুর নিচে ঘুরে বেড়াও, মনে পড়ে অ্যালিস্টেয়ারের উপদেশ।\nসে ভদ্রভাবে এগিয়ে আসে, কথা বলতে চায়, কিন্তু তার বাক্য জড়িয়ে যায়।\nতুমি মুখ তুলে তাকাও—তার মুখ থেকে ঝরে পড়ছে কালো আঠালো তরল, তার উচ্চারণকে শ্বাসরোধ করে—"
  },
  Event_7294_Name = {
    Text = "বিশৃঙ্খলার আর্তনাদ"
  },
  Event_7295_ChoiceDesc1 = {
    Text = "[Leave] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_7295_Desc = {
    Text = "\"অবশ্যই, অবশ্যই। যদি আপত্তি না থাকে, আমি তোমাকে একটু সাহায্য করতে পারি।\"\nসে তোমার হাতে একটি প্রাচীন হাতআয়না তুলে দেয়।\n\"নাইট ইতিমধ্যেই বোর্ডে পা রেখেছে, আর রাজাও খুব দূরে নয়। তুমি খুব শিগগিরই তার মুখোমুখি হবে। সত্যিই রোমাঞ্চকর, তাই না?\""
  },
  Event_7295_Name = {
