  },
  Event_7296_ChoiceDesc3 = {
    Text = "[Leave] Arg1টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7296_Desc = {
    Text = "তোমার চোখের সামনে কালো প্রজাপতির এক ঝাঁক বিস্ফোরণের মতো বেরিয়ে আসে, অবিরাম উড়ে বেরোয়, ডানা ঝাপটায়, আর ডেস্কের ওপর ঝরে পড়ে।\nখোলা সাদা চিঠির কাগজে কালি ছিটকে লেগে আছে, আহত প্রজাপতিগুলো তার গায়ে পড়ে আছে, কেবলমাত্র জীবিত।\nতাদের ডানায় লেগে থাকা কালো আঠালো তরল পৃষ্ঠ জুড়ে লেপটে গিয়ে নিষিদ্ধ শব্দের আকার নেয়।\nতুমি এই পাতাটি টাইপরাইটার থেকে টেনে বের করো।"
  },
  Event_7296_Name = {
    Text = "প্রজাপতি অধ্যায়"
  },
  Event_7297_ChoiceDesc1 = {
    Text = "[Go to the Butterflies] একটি কমান্ড কার্ড ধ্বংস করো, এবং Arg1 কালো চিহ্ন গ্রহণ করো।"
  },
  Event_7297_ChoiceDesc2 = {
    Text = "[Linger No Longer]"
  },
  Event_7297_Desc = {
    Text = "লন্ডিনিয়ামে সাম্প্রতিক এক প্রবাদ চালু হয়েছে: 「ইয়াকুতস্কে এক প্রজাপতির ডানার ঝাপটায় লিওনিয়া রাজ্যে ঝড় বয়ে যেতে পারে।」\nযখন তুমি প্রজাপতিদের ঢেউয়ের মতো ছুটে আসতে দেখ, এই কথাটা মনে না করে পারো না।\nএই প্রজাপতিগুলোই হয়তো এমন এক বিপর্যয়ের সূচনা করবে, যা পুরো গ্রহটাকে গ্রাস করে নিতে পারে।"
  },
  Event_7297_Name = {
    Text = "নসিস টেম্পেস্ট"
  },
  Event_7298_ChoiceDesc1 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7298_Desc = {
    Text = "তুমি ঠোঁটে আঙুল চেপে নীরবতার ইশারা করো。\nকালো বিড়ালটি মায়াভ্রমের মতো ঝলকে চলে যায়, পায়ের কাছে ফেলে যায় এক অন্ধকার উপহার।"
  },
  Event_7298_Name = {
    Text = "রাতের বিড়ালের অভিশাপ"
  },
  Event_7299_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7299_Desc = {
    Text = "এটা যেন রেশমের টুকরোর মতো তোমার ব্যাগে গলে ঢুকে গেল, ওজনের সামান্য বৃদ্ধি প্রায় টেরই পাওয়া যায় না, যেন নরম স্বরে একটি ধন্যবাদ ফিসফিস করে গেল।\nতারপর সবকিছু নিস্তব্ধ হয়ে গেল।"
  },
  Event_7299_Name = {
    Text = "কেওসের আত্মা"
  },
  Event_7300_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7300_Desc = {
    Text = "কেওসের আত্মার আর্তনাদ ক্রমে আরও ধারালো হয়ে উঠল, শেষে তা চারদিক জুড়ে প্রতিধ্বনিত এক বিদারক চিৎকারে রূপ নিল।\nতোমার নিবেদিত কবিতা আর অনিবার্য শোকের ভারে, তা আবার কাদার অতলে ডুবে গেল।"
  },
  Event_7300_Name = {
    Text = "কেওসের আত্মা"
  },
  Event_7301_ChoiceDesc1 = {
    Text = "[Answer Honestly]"
  },
  Event_7301_ChoiceDesc2 = {
    Text = "[Doodle Randomly]"
  },
  Event_7301_Desc = {
    Text = "পূর্ব জেলার রাস্তাগুলো জটিল ও গোলকধাঁধার মতো, আর তুমি খুব শিগগিরই বালকদের দৃষ্টির আড়ালে হারিয়ে ফেলো।\nযখন প্রায় আশা ছেড়ে দিতে যাচ্ছ, তখনই এক রহস্যময়ী নারী তোমার সামনে এসে দাঁড়ায়।\n「আমি জানি বালকেরা কোথায় গেছে, কিন্তু বলার আগে তুমি কি আমাকে একটা ছোট অনুগ্রহ করবে?」\nসে একটি কাগজ বের করে কোমল হাসি হেসে তোমার দিকে বাড়িয়ে দেয়।\n「আমার নাম ক্লেমেন্টাইন। আমি লন্ডিনিয়ামের বাসিন্দাদের ওপর একটি মনস্তাত্ত্বিক তদন্ত চালানো একজন মনোবিজ্ঞানী। তুমি যদি শুধু এই প্রশ্নপত্রটি পূরণ করে দাও,\nতাহলে আমি আনন্দের সঙ্গে তোমাকে এবং তোমার সঙ্গীদের কিছু সহায়তা করতে পারি।」"
  },
  Event_7301_Name = {
    Text = "মানসিক মূল্যায়ন"
  },
  Event_7302_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7302_Desc = {
    Text = "「「এটাও ছিল আমারই সিদ্ধান্ত,」 মিষ্টি ধরে থাকা অবয়বটি বলে। 「কিন্তু সে হয়ে যাবে তার গুটি, আর শেষ পর্যন্ত তোমাকেই একদিন একটি নির্বাচন করতে বাধ্য হতে হবে।\nএই জগতে নিখুঁত সমাপ্তি বলে কিছু নেই।」\nগভীর শোক তোমাকে গ্রাস করে। ছায়ামূর্তিগুলো মিলিয়ে যায়, তোমাকে বুকে হাত চেপে ধরে রেখে যায়, তুমি নিশ্চিত নও, এটা কি ছিল কোনো প্রক্ষেপণ, নাকি মানসিক চাপে উদ্ভূত কোনো মায়াভ্রম।「"
  },
  Event_7302_Name = {
    Text = "বিভক্ত পথ"
  },
  Event_7303_ChoiceDesc1 = {
