  },
  Event_7303_Desc = {
    Text = "\"হে মাত্রা অতিক্রমের অগ্রদূত।\"\nপ্রাচীন কণ্ঠস্বর তোমার কানে প্রতিধ্বনিত হয়, যেন প্রাগৈতিহাসিক যুগ থেকে উঠে এসে যুগযুগান্তর অতিক্রম করেছে।\nচূড়ান্ত টানটান উত্তেজনার মধ্যে তুমি সেই কণ্ঠকে এক অদ্ভুত পরিচিত প্রশ্ন করতে শোনো।\n\"এটা কি সেই সোনার কুঠার, যা তুমি ফেলেছিলে, নাকি এই রুপোরটা?\""
  },
