  },
  Event_7304_Desc = {
    Text = "「ওহ, এটা...」 সে কিছুটা বিহ্বল অভিব্যক্তি নিয়ে প্রশ্নপত্রটা ফিরিয়ে নেয়। 「আচ্ছা থাক, তুমি তো তাড়ায় আছো। বালকেরা ওই দিকেই গেছে, খুব দূরে যাওয়ার কথা নয়।」\nতুমি দ্রুত ঘুরে দৌড় দাও, প্রায়ই পেছনের হুইসপারটা কানে না এসে থেকে যায়।\n「কিছু যায় আসে না, আমরা আবার মিলিত হব।」"
  },
  Event_7304_Name = {
    Text = "মানসিক মূল্যায়ন"
  },
  Event_7305_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7305_Desc = {
    Text = "\n「তুমি কে?」\n「আমি সেই রৌপ্য চাবির বাহকের ছায়া, যাকে করুণভাবে খুন করা হয়েছে। খুনি হল এক ধূর্ত অ্যালবিনো সাপ।」\n「অ্যালবিনো সাপ? ওটা আবার কী?」\n「একটি ত্রুটি। মানুষ আর সাপের মিশ্রণে জন্ম নেওয়া এক নিন্দিত বিকৃতি...」\nতুমি আরও জিজ্ঞেস করতে চাও, কিন্তু ছায়াটা হঠাৎ মিলিয়ে যায়, রেখে যায় সোনালি ধুলায় ঢাকা এক মাটি।"
  },
  Event_7305_Name = {
    Text = "রৌপ্য চাবির বাহক"
  },
  Event_7306_ChoiceDesc1 = {
    Text = "[Infection\"(Skill.Arg1)\", Gain Golden Relic \"(RelicConfig.Arg2)\"]"
  },
  Event_7306_ChoiceDesc2 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7306_Desc = {
    Text = "ইভেন্ট 355 (উন্নয়নাধীন), চূড়ান্ত প্রভাব নয়"
  },
  Event_7306_Name = {
    Text = "ইভেন্ট 355 (উন্নয়নাধীন)"
  },
  Event_7307_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7307_Desc = {
    Text = "পেটের গভীরে ডুবে যাও, প্রজাপতির সঙ্গে নাচতে নাচতে।\nপ্রজাপতির সঙ্গে জড়িয়ে থাকা চিন্তার আঁশগুলো ভেতরে নরম তুষারের মতো ঝরে পড়ে।\nতুমি ধীরে ধীরে সবকিছু জোড়া লাগাতে থাকো, আর পরের সুযোগ আসলে কথা বলার জন্য প্রস্তুত হয়ে ওঠো।"
  },
  Event_7307_Name = {
    Text = "বাটারফ্লাই ইফেক্ট"
  },
  Event_7308_ChoiceDesc1 = {
    Text = "[Refute Them] এলোমেলো একটি কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg2)」 খোদাই করো, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7308_ChoiceDesc2 = {
    Text = "[Follow them] এলোমেলো একটি কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg2)」 খোদাই করো, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7308_ChoiceDesc3 = {
    Text = "[Propose New Idea] এলোমেলো একটি কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_7308_Desc = {
    Text = "\n「দয়া করে আমাদের থেকে দূরত্ব বজায় রাখুন।」\nএক ঝাঁক ইঁদুর তোমাকে ঘিরে ধরল, কিন্তু অন্তত পাঁচ ফুট দূরত্ব বজায় রেখে।\n「আমরা বংশবৃদ্ধির জন্য লড়ি, আমরা বেঁচে থাকি; আমরা খাবারে খুঁতখুঁতে নই—এই কারণেই আমরা নিয়ে আসি রোগ, উদ্বেগ আর মানবতার দীপ্তির ওপর নেমে আসা যন্ত্রণা।」\n「আমাদের মানুষের খুব কাছে যাওয়া উচিত নয়; এটি তোমাদের থাকার জায়গা নয়।」\nইঁদুরগুলোর প্রহরা ঢিলেঢালা করতে, তুমি সিদ্ধান্ত নিলে—"
  },
  Event_7308_Name = {
    Text = "প্লেগ"
  },
  Event_7309_ChoiceDesc1 = {
    Text = "[Open Iron Door] সোনার রেলিক 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7309_ChoiceDesc2 = {
    Text = "[Ignore] 50টি কালো চিহ্ন গ্রহণ করুন"
  },
  Event_7309_Desc = {
    Text = "এটি একটি আদর্শ আন্ডার-ডেক আর্চ সেতু। রেললাইনের পাশে সিঁড়ি গিয়ে মিশেছে একটি লোহার দরজায়। তার ওপাশ থেকে ভেসে আসছে ছন্দময়, অস্বাভাবিক ধাতব ঠকঠক শব্দ।\nতুমি থেমে দরজাটি লক্ষ্য করো, দেখতে পাও তাতে ঝুলছে ভারী এক তালা, কিন্তু সেটি লক করা নয়।"
  },
  Event_7309_Name = {
    Text = "লৌহ দ্বারের পশ্চাতে"
  },
  Event_7310_ChoiceDesc1 = {
    Text = "[Leave] 50টি কালো চিহ্ন অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গটি বিকাশ করো।"
  },
  Event_7310_Desc = {
    Text = "প্রলোভনের মুখে তুমি অবিচল রইলে।\nকণ্ঠস্বরের মালিক বেশ হতাশ হলো, জলের উপরিভাগে ক্লান্তভাবে কয়েকটি তরঙ্গ ছড়িয়ে পড়ল, তারপর আর কোনো আলোড়ন রইল না।"
  },
  Event_7310_Name = {
    Text = "সীমানার ওপারের কণ্ঠস্বর"
  },
  Event_7311_ChoiceDesc1 = {
    Text = "[Infection\"(Skill.Arg1)\", Gain Golden Relic \"(RelicConfig.Arg2)\"]"
  },
  Event_7311_ChoiceDesc2 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7311_Desc = {
    Text = "ইভেন্ট 353 (উন্নয়নাধীন), চূড়ান্ত প্রভাব নয়"
  },
  Event_7311_Name = {
    Text = "ইভেন্ট 353 (উন্নয়নাধীন)"
  },
  Event_7312_ChoiceDesc1 = {
    Text = "[Leave] 50টি কালো চিহ্ন অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গটি বিকাশ করো।"
  },
  Event_7312_Desc = {
    Text = "\"তোমরা মানুষদের আর কোনো উত্তর নেই?\"\nকণ্ঠস্বরের মালিক বিরক্ত গর্জন ছাড়ল, পুরো স্থান কেঁপে উঠল তাতে।\n\"লোভী আর অজ্ঞ... এই কারণেই আমি তোমাদের প্রতি ক্লান্ত।\""
  },
  Event_7312_Name = {
    Text = "সীমানার ওপারের কণ্ঠস্বর"
  },
  Event_7313_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7313_Desc = {
    Text = "ডোমেইনের ব্যবস্থাপনাকে মেনে নাও, হারানোর মধ্যেই প্রাপ্তি খুঁজে নাও, আর অভিশপ্ত উপহারের তোষামোদকারীর আলিঙ্গন গ্রহণ করো।"
  },
  Event_7313_Name = {
    Text = "বিভ্রান্তির উদ্গীরণ"
  },
  Event_7314_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7314_Desc = {
    Text = "চোখগুলো ধীরে ধীরে পলক ফেলে, যেন তোমার জিজ্ঞাসা ঠিকমতো বুঝতে পেরেছে কি না, সে নিয়েই অনিশ্চিত।\nচোখের কোণা থেকে সোনালি-লাল এক ফোঁটা অশ্রু ঝরে পড়ে, ক্ষুদ্র এক নক্ষত্রের মতো উষ্ণ সূর্যালোক ছড়িয়ে। তার পতনে বয়ে আনে বেদনা আর করুণা, যতক্ষণ না ইটের গায়ে গিয়ে গুঁড়ো হয়ে মিলিয়ে যায়।\nতুমি হঠাৎ বাস্তবে ফিরে আসো—চোখগুলো আর নেই।"
  },
  Event_7314_Name = {
    Text = "অন্ধ দৃষ্টি"
  },
  Event_7315_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7315_Desc = {
    Text = "কয়েকজন সাদামাটা, এমনকি কিছুটা ময়লা-মাখা বালক রাস্তা ধরে দৌড়াচ্ছে, তাদের পেছনে ধাওয়া করছে পুলিশ ইউনিফর্ম পরা এক প্রাপ্তবয়স্ক। বালকদের একজনের মাথায় বাদামি রঙের হুড, যা কেমন যেন পরিচিত মনে হয়।"
  },
  Event_7315_Name = {
    Text = "আমাদের স্মৃতি"
  },
  Event_7316_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7316_Desc = {
    Text = "\"গান বন্ধ করো—\"\nতুমি সুরহীন গায়ককে সতর্ক করো, আর তোমার কানকে আর নির্যাতিত হতে দিতে অস্বীকার করো।"
  },
  Event_7316_Name = {
    Text = "সংকীর্ণ পথের দুর্বৃত্ত"
  },
  Event_7317_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7317_Desc = {
    Text = "\n「ওখানেই থামো!!! পেট ঘেঁষে হেঁটে চলা গলতে থাকা দানবও তার নিজের অঙ্গপ্রত্যঙ্গ তোমার চেয়ে ভালো চেনে!」\nদর্শকদের ছেড়ে দাও…\nতুমি মনে মনে এই প্রার্থনা করো"
  },
  Event_7317_Name = {
    Text = "সংকীর্ণ পথের দুর্বৃত্ত"
  },
  Event_7318_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7318_Desc = {
    Text = "কালো কাদা টুপটাপ করে তোমার মুখে পড়ে, ত্বকে ঝিনঝিনে চুলকানি ধরায়।\nসহ্য করতে না পেরে তুমি প্রজাপতিটাকে ঝেড়ে ফেলতে যাও।\nপ্রজাপতিটি তোমার বৈরী আচরণ এড়িয়ে নীরবে দূরের অন্ধকারে মিলিয়ে যায়।"
  },
  Event_7318_Name = {
    Text = "যা থাকা উচিত নয়"
  },
  Event_7319_ChoiceDesc1 = {
    Text = "[Praise It] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7319_Desc = {
    Text = "জেনকিন বলল: \"জেগে ওঠো, জনি! কবিতা লিখে তোমার ঋণ শোধ হবে না, আর চুইয়ে পড়া মেঝেটাও ঠিক হবে না।\"\nতুমি বললে: \"দুঃখজনক, তোমার সত্য-অন্বেষী কোষগুলো প্রতিদিন দশ লক্ষ হারে মারা যাচ্ছে। খুব শিগগিরই তুমি কেবল একটা ব্রেইন স্টেম ছাড়া আর কিছুই থাকবে না।\"\nমস্তিষ্ক উদাসীন ভঙ্গিতে কাঁধ ঝাঁকাল—যদি সে পারত।\nমস্তিষ্ক বলল: \"আমি চিন্তা করি, তাই আমি আছি। একবার তুমি আমার চিন্তার স্তরে পৌঁছালে, তখন আর ব্রেইন স্টেম নিয়ে মাথা ঘামাবে না।\""
  },
  Event_7319_Name = {
    Text = "দার্শনিকের মস্তিষ্ক"
  },
  Event_7320_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7320_Desc = {
    Text = "পিয়ানোটি এক নরম দীর্ঘশ্বাস ফেলে, দীর্ঘস্থায়ী অথচ সান্ত্বনাদায়ক, যেন কারও সুরের শেষে ফুটে ওঠা হাসি।\n「যতক্ষণ বালকেরা... যতক্ষণ...」\nতুমি শব্দগুলো স্পষ্ট বোঝার আগেই, পিয়ানোর মায়াভ্রম হাওয়ার সঙ্গে মিলিয়ে যায়।"
  },
  Event_7320_Name = {
    Text = "শিশুদের ছড়া"
  },
  Event_7321_ChoiceDesc1 = {
    Text = "[Leave] 3টির মধ্যে 1টি রৌপ্য সৃষ্টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_7321_Desc = {
    Text = "\nতুমি মোটা মেডিকেল রেকর্ডটি হাতে তুলে নিয়ে খুলে দেখো, শিরোনাম পাতায় লেখা 「G. R.」।\n「ওহ হায়, ওহ হায়, এটা তো তোমার রেকর্ড নয়, তাই না?」 একেবারেই বিচলিত না হয়ে বলে ক্লেমেন্টাইন। 「কোনো অসুবিধা নেই, অন্যের মনস্তত্ত্ব নিয়ে গবেষণা করা শেষ পর্যন্ত নিজের মনকেও উপকার করে।」\nতুমি কিছু জিজ্ঞাসা করার আগেই, তার অবয়ব অনেক দূরে মিলিয়ে গেছে।"
  },
  Event_7321_Name = {
    Text = "চিকিৎসার নথিপত্র"
  },
  Event_7322_ChoiceDesc1 = {
    Text = "[Leave] এক জাগরণকারীকে জাগরণ দাও, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_7322_Desc = {
    Text = "তুমি পাতলা মেডিকেল রেকর্ডটা হাতে নিয়ে খোল, ভেতরে এক টুকরো কাগজ মাত্র, তাতে লেখা একটাই বাক্য।\n「অন্তহীন বিশৃঙ্খলার সাগরে, এক ফ্যাকাশে, মণিহীন চোখ নিরন্তর চেয়ে থাকে।」\nতুমি জিজ্ঞাসা করার আগেই, ক্লেমেন্টাইনের অবয়ব অনেক দূরে মিলিয়ে গেছে।"
  },
  Event_7322_Name = {
    Text = "চিকিৎসার নথিপত্র"
  },
  Event_7323_ChoiceDesc1 = {
    Text = "[Connect] সব HP পুনরুদ্ধার করো।"
  },
  Event_7323_ChoiceDesc2 = {
    Text = "[Meditate] একজন Awakener-কে Rouse করো।"
  },
  Event_7323_Desc = {
    Text = "কুয়াশা ভারী হয়ে ঝুলে থাকে, আর তোমার ব্যাজে মিটমিট করে ফ্যাকাশে সিলভার আভা। যোগাযোগকারীটা কড়কড় শব্দ তুলে জেগে ওঠে। কেউ একজন ডাকছে।"
  },
  Event_7323_Name = {
    Text = "সংযোগস্থল"
  },
  Event_7324_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7324_Desc = {
    Text = "গুরুত্বপূর্ণ ভৌত প্রমাণ সতর্কতার সঙ্গে সংরক্ষণ করে ইতিহাস বিভাগে গবেষণা ও বিশ্লেষণের জন্য হস্তান্তর করা উচিত।"
  },
  Event_7324_Name = {
    Text = "সাইফার-এডিক্ট·পর্ব I"
  },
  Event_7325_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7325_Desc = {
    Text = "দগ্ধ সূর্য উচ্চ আকাশ থেকে নেমে আসে, কুয়াশা ভেদ করে, ক্লান্ত আত্মাদের জাগিয়ে তোলে।"
  },
  Event_7325_Name = {
    Text = "উত্তরণ"
  },
  Event_7326_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7326_Desc = {
    Text = "তুমি এক ধরনের পরিপূর্ণতার অনুভূতি টের পাও। তোমার মাথার উপর রাতের আকাশে তাদের দৃষ্টি মিটমিট করে, সরে গিয়ে আরেকজনের উপর স্থির হয়।"
  },
  Event_7326_Name = {
    Text = "গম্বুজের চোখ"
  },
  Event_7327_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7327_Desc = {
    Text = "তুমি সেই অস্বস্তিকর দৃষ্টিকে এড়াতে পারবে না, দেবতাদের দানও প্রতিহত করতে পারবে না।"
  },
  Event_7327_Name = {
    Text = "গম্বুজের চোখ"
  },
  Event_7328_ChoiceDesc1 = {
    Text = "[Leave] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_7328_Desc = {
    Text = "\n「তুমি আসলে কী?」 আতঙ্কে তুমি জিজ্ঞেস করো。\n「ওটা নিয়ে তোমার মাথা ঘামানোর দরকার নেই। আমার শত্রুর শত্রুই তো আমার বন্ধু, তাই না?」 মানুষটি হাসে。\n「উপহারটা চেয়ারের ওপর রেখে এসেছি। তোমার জন্য শুভকামনা রইল।」"
  },
  Event_7328_Name = {
    Text = "অদ্ভুত সঙ্গী IV"
  },
  Event_7329_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7329_Desc = {
    Text = "রামোনা ঝুঁকে এল, “সাদা কোট”-এর আরও গল্প শোনার আশায়। “কেউ আড়ি পাতছে!” ফোনোগ্রাফের কণ্ঠ হঠাৎ আরও জোরে হয়ে উঠল: “আড়ি পাতছে, আড়ি পাতছে, আড়ি পাতছে!”"
  },
  Event_7329_Name = {
    Text = "অপরের কান"
  },
  Event_7330_ChoiceDesc1 = {
    Text = "[Leave] সব জাগরণকারীর অ্যালিমাস Arg1 বৃদ্ধি করো"
  },
  Event_7330_Desc = {
    Text = "তুমি ছেলেটির নরম হাত ধরে একের পর এক দরজা পেরিয়ে অবশেষে পৌঁছালে একটি ছোট, জীর্ণ মঞ্চে।\nছেলেটি কৃতজ্ঞতা জানাতে তোমার হাত চেপে ধরল।\n「ধন্যবাদ, বিদায়।」"
  },
  Event_7330_Name = {
    Text = "অন্তিম II"
  },
  Event_7331_ChoiceDesc1 = {
    Text = "[Descend Further] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_7331_ChoiceDesc2 = {
    Text = "[Pull Away] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7331_Desc = {
    Text = "「তুমি」 তোমাকে ডেকে নিয়ে যায় আরও গভীরে.\nসর্পিলের অন্তঃস্থলে, অতীত আর ভবিষ্যতের 「তুমি」 ভিন্ন ভিন্ন মাত্রা থেকে তোমার কাছে পাঠায় 「উপহার」।"
  },
  Event_7331_Name = {
    Text = "অতল গহ্বর"
  },
  Event_7332_ChoiceDesc1 = {
    Text = "[Keep Silent] 25টি কালো চিহ্ন পাওয়ার 100% সম্ভাবনা"
  },
  Event_7332_ChoiceDesc2 = {
    Text = "[Reach Out and Touch] 50% সম্ভাবনায় 50টি কালো চিহ্ন পাবে, 50% সম্ভাবনায় কিছুই পাবে না।"
  },
  Event_7332_Desc = {
    Text = "\"আমি শুধু একটা নীতি বলব—কেউই একটা বিড়ালকে মেরে ফেলতে পারে না!\"\n\"ওই অভিশপ্ত কালো বিড়ালটার পেট ফাঁড়া হয়ে বনে পচে পড়ে থাকার কথা ছিল, কিন্তু সে উল্টে আমার পারিবারিক সমাধি উজাড় করে ফেলল, বাকি থাকা মানবমাংস গিলে খেল আর হাড়গোড়, হাত-পা সব বিক্ষিপ্ত করে ছড়িয়ে দিল।\"\n\"তার ঠান্ডা, অন্ধকার সরু চেরা চোখের নিচে, পচা হলুদ পুঁজ ফুলে উঠছিল, আর আমি দুঃস্বপ্নে পুড়ে, আত্মা শুষে নেওয়া যন্ত্রণায় হামাগুড়ি দিয়ে সরে যাচ্ছিলাম।\"\n\"থামো... তুমি কী করছ? আমি পাগল নই! না! নিশ্চয়ই তোমরা কিছু লুকোচ্ছ! সব সত্যি—\"\nসত্যিই তাই। উন্মাদের ছায়া মিলিয়ে যেতে যেতে, তুমি পায়ের কাছে নিশ্চুপ বসে থাকা কালো বিড়ালটার সঙ্গে চোখাচোখি কর।"
  },
  Event_7332_Name = {
    Text = "রাতের বিড়ালের অভিশাপ"
  },
  Event_7333_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7333_Desc = {
    Text = "তুমি তাকে মোম জাদুঘরের পথ জিজ্ঞেস করো।\nঅদ্ভুত, আজ রাতের এটাই তোমাদের পঞ্চম দেখা। তুমি তার আগুন পাঁচবার জ্বালিয়েছ, আর পাঁচবারই পথ জিজ্ঞেস করেছ।\nতবু, যেমন করে তুমি বারবার তার সঙ্গে দেখা করে চলেছ, তেমনি এখনো মোম জাদুঘরের অবস্থান তোমার মনে থাকে না।"
  },
  Event_7333_Name = {
    Text = "পথের আলোয় ছায়ামূর্তি"
  },
  Event_7334_ChoiceDesc1 = {
    Text = "[Chase the Crows] 25টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_7334_ChoiceDesc2 = {
    Text = "[Continue chasing the child] প্রস্থান করুন"
  },
  Event_7334_Desc = {
    Text = "তৃতীয় কাকটি উড়ে গেল, দৃষ্টির আড়াল পেরিয়ে চিরন্তন অন্ধকারে মিলিয়ে গেল।"
  },
  Event_7334_Name = {
    Text = "কালো কাকের দৃষ্টি"
  },
  Event_7335_ChoiceDesc1 = {
    Text = "[Leave] 75টি কালো চিহ্ন গ্রহণ করো, কিন্তু 「(Skill.Arg2)」 নামের উপসর্গটি বিকশিত হবে"
  },
  Event_7335_Desc = {
    Text = "লোম নরম আর সূক্ষ্ম, এখনও ধরে রেখেছে কৌমের জীবনের উষ্ণতা।\nএটি গোধূলির আগে শেষ সূর্যাস্তের কিরণ, উষ্ণতার ক্ষণস্থায়ী অবশিষ্টাংশ।"
  },
  Event_7335_Name = {
    Text = "অবশিষ্ট উষ্ণতা"
  },
  Event_7336_ChoiceDesc1 = {Text = "[Chase]"},
  Event_7336_Desc = {
    Text = "তুমি দেয়ালটি মনোযোগ দিয়ে খুঁজে দেখলে এবং শেষমেশ ঝোপের আড়ালে লুকানো একটি নর্দমার প্রবেশপথ আবিষ্কার করলে। তুমি নর্দমা বেয়ে এগিয়ে গেলে, কিন্তু দানবটি ইতিমধ্যেই পালিয়ে গেছে।"
  },
  Event_7336_Name = {
    Text = "মৃতপথ"
  },
  Event_7337_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7337_Desc = {
    Text = "পাখিদের নিজস্ব নিয়ম আছে। তারা তোমার ইচ্ছা অনুযায়ী চলে না, আর তুমি প্রকৃতির বিধিতে হস্তক্ষেপ করার অধিকারও রাখো না।"
  },
  Event_7337_Name = {
    Text = "নির্বাসিত কাক"
  },
  Event_7338_ChoiceDesc1 = {
    Text = "[Overlook Reflection] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7338_ChoiceDesc2 = {
    Text = "[Are You Okay?] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_7338_Desc = {
    Text = "「শোনো তো... পাশের নতুন বস লেডিটা কখনোই বাইরে বেরোয় না... সেদিন তাকে একটা বিয়ার কিনে দিলাম, ফেনা পুরোটা মিলিয়ে যাওয়ার পর হঠাৎ খেয়াল করলাম... গ্লাসের ভেতর, তার কোনো ছায়া নেই!」"
  },
  Event_7338_Name = {
    Text = "স্মৃতি খণ্ডাংশ: বিয়ার"
  },
  Event_7339_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7339_Desc = {
    Text = "\"আমি সত্যিই আবার তোমার সঙ্গে গান গাইতে চাই...\"\nসারার উন্মাদ, বিকৃত বিলাপ হঠাৎ থেমে গেল, তার বিকৃত মুখে একটুখানি বিভ্রান্তি ভেসে উঠল।"
  },
  Event_7339_Name = {
    Text = "\"সাশা দিদি\""
  },
  Event_7340_ChoiceDesc1 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7340_Desc = {
    Text = "\"খুব খুশি! খুব খুশি!\" তীক্ষ্ণ, কর্কশ, শিশুসুলভ এক কণ্ঠ তোমার কানে বাজে, \"তোমার জন্য, তোমার জন্য!\""
  },
  Event_7340_Name = {
    Text = "নিশিযামিনীর পরী"
  },
  Event_7341_ChoiceDesc1 = {
    Text = "[Thick Record]"
  },
  Event_7341_ChoiceDesc2 = {
    Text = "[Thin Record]"
  },
  Event_7341_Desc = {
    Text = "একটি বেশ পরিচিত কণ্ঠস্বর তোমাকে ডাকে। তুমি চোখ কুঁচকে তাকাও, কিন্তু অবয়বটি স্পষ্ট করতে পারো না।\n「আমি জানি তুমি তাড়ায় আছ,」 প্রফুল্ল কণ্ঠে বলে ড. ক্লেমেন্টাইন, 「আমি প্রতিশ্রুতি দিচ্ছি, তোমার খুব বেশি সময় নেব না।」\nদু」টি হাত তোমার মনের কুয়াশা ভেদ করে এগিয়ে আসে, প্রতিটি হাতে একটি করে মেডিকেল রেকর্ড—একটি মোটা ও জীর্ণ, অন্যটি পাতলা ও নিষ্কলুষ।\n「তোমার প্রশ্নপত্রের ফলাফলের ভিত্তিতে, আমি তোমার জন্য একটি মেডিকেল রেকর্ড তৈরি করার দুঃসাহস করেছি। তবে, কোনটি তোমার, তা যেন ভুলে গেছি। কেন তুমি নিজেই বেছে নিচ্ছ না?」\nকোনো এক অজ্ঞাত কারণে, পাতলা মেডিকেল রেকর্ডটি এক অদ্ভুত পরিচিত আভা ছড়ায়, সূক্ষ্মভাবে তোমার আর সেই অবয়বের মানসিক সংযোগের সঙ্গে সুর মিলিয়ে।"
  },
  Event_7341_Name = {
    Text = "চিকিৎসার নথিপত্র"
  },
  Event_7342_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7342_Desc = {
    Text = "দেখতে সাধারণ এক দেয়াল। তুমি না চেয়ে পারলে না, গিয়ে টোকা দিলে—কিন্তু স্পর্শে তা দৃঢ় মনে হলো না।"
  },
  Event_7342_Name = {
    Text = "অদ্ভুত দেয়াল"
  },
  Event_7343_ChoiceDesc1 = {
    Text = "[I'm Not on Water] একটি এলোমেলো রৌপ্য সৃষ্টি-কে উন্নয়ন অর্জন করে সোনার রেলিক 「(RelicConfig.Arg1)」 তে রূপান্তর করো"
  },
  Event_7343_ChoiceDesc2 = {
    Text = "[Look Down] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7343_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7343_Desc = {
    Text = "\"হেহে, রক্ষক, তুমি কি এখনো উইঙ্কলের সতর্কবাণী মনে রেখেছ? শোনো, দুপুরবেলা নিজের প্রতিবিম্বের দিকে নিচে তাকিয়ো না।\""
  },
  Event_7343_Name = {
    Text = "নিরাকার প্রতিবিম্ব"
