  Event_7343_Tips1 = {
    Text = "রৌপ্য সৃষ্টি এখনও অর্জিত হয়নি"
  },
  Event_7344_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7344_Desc = {
    Text = "দূর ভবিষ্যৎ থেকে আসা এক মায়াভ্রম, লুকিয়ে আছে এলওয়ার্থের গিরিখাতে।"
  },
  Event_7344_Name = {
    Text = "আগ্নেয়গিরির প্রেতছায়া"
  },
  Event_7345_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7345_Desc = {
    Text = "তোমার তালুর ভেতর এক প্রজাপতি ভেঙে চুরমার হয়ে যায়, যেন হঠাৎ ভেঙে যাওয়া কাঁচের সিলিং—খণ্ডাংশগুলো পড়ছে, পড়ছে, পড়ছে মাটির দিকে—"
  },
  Event_7345_Name = {
    Text = "ইস্পাত সেতুর মরীচিকা"
  },
  Event_7346_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7346_Desc = {
    Text = "তাদের ছায়া থেকে উদ্ভাসিত হওয়ার অপেক্ষায় থাকা যাক।"
  },
  Event_7346_Name = {
    Text = "ল্যান্টার্ন-ক্রো"
  },
  Event_7347_ChoiceDesc1 = {
    Text = "[Switch On] বর্তমান দৃষ্টিক্ষেত্র প্রসারিত করুন।"
  },
  Event_7347_Desc = {
    Text = "একটি প্রাচীন আলোকযন্ত্র তার চারপাশের কালো কুয়াশা তাড়িয়ে দেয়।\nতার চারপাশের কুয়াশা ছন্দময়ভাবে দুলতে থাকে, যেন তার নিশ্বাসে বিঘ্নিত হয়েছে।"
  },
  Event_7347_Name = {
    Text = "সার্চলাইট"
  },
  Event_7348_ChoiceDesc1 = {
    Text = "[Point Out the Issue] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7348_ChoiceDesc2 = {
    Text = "[Swallow Doubt] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো এবং খোদাই করার প্রার্থনাগাথা বদলাও।(ব্যবহার: 2/2)"
  },
  Event_7348_Desc = {
    Text = "এখনও তুমি ভাবছো মার্ফির মুখে শোনা অতীতের বর্ণনা নিয়ে।\nস্মৃতিচারণ তোমার সঙ্গে অনুরণিত হয়, তোমার মনকে শক্ত করে শৃঙ্খলিত করে চেপে ধরে। এমনকি গোলিয়াথের মার্ফিকে বলা শেষ সান্ত্বনামূলক কথাগুলোও তোমাকে কোনো স্বস্তি দিতে পারেনি।\n...থামো, তারা তো বলেছিল পঁচিশ বছর পর নক্ষত্রপুঞ্জ এক সরলরেখায় দাঁড়াবে...\nকিন্তু তোমার সামনে দাঁড়িয়ে থাকা মার্ফি তো স্পষ্টই কেবল এক কিশোর..."
  },
  Event_7348_Name = {
    Text = "শৃঙ্খলিত জীবন"
  },
  Event_7349_ChoiceDesc1 = {
    Text = "[Leave] 3টির মধ্যে 1টি রৌপ্য সৃষ্টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_7349_Desc = {
    Text = "কাঁদার কথা ছিল তারই; কান্নার সবচেয়ে বেশি অধিকার যদি কারও থাকে, তবে তা তারই।\nতবু সে কাঁদছে না কেন? কেন সে এত উদাসীন, যেন ঐ মানুষগুলো তার সামনে হাঁটু গেড়ে বসে নেই...?"
  },
  Event_7349_Name = {
    Text = "যাত্রা-পূর্ব আচার"
  },
  Event_7350_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7350_Desc = {
    Text = "যাই হোক না কেন, অন্যের গোপনীয়তায় নাক গলানো অশোভন।"
  },
  Event_7350_Name = {
    Text = "লিখিত উপস্থিতি"
  },
  Event_7351_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7351_Desc = {
    Text = "এটি নিশ্চয়ই এক ক্ষণস্থায়ী মায়াস্বপ্ন।"
  },
  Event_7351_Name = {
    Text = "কালো কাকের দৃষ্টি"
  },
  Event_7352_ChoiceDesc1 = {
    Text = "[Leave] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_7352_Desc = {
    Text = "তার স্মৃতিচারণে সকলে তার কাছে প্রার্থনা করছিল, তার কাছে মিনতি জানাচ্ছিল। তোমারও অজান্তে হৃদয়ের গভীরে নীরব প্রার্থনা জেগে ওঠে..."
  },
  Event_7352_Name = {
    Text = "যাত্রা-পূর্ব আচার"
  },
  Event_7353_ChoiceDesc1 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7353_Desc = {
    Text = "কালো বিড়ালের নিচ থেকে, গলির মুখের নর্দমায় একটানা কালো পিচ্ছিল তরল ঝরে পড়ছে। তুমি এগিয়ে না আসায়, বিড়ালটি ফিরে তাকায়, তারপর নর্দমার ভেতর লাফিয়ে পড়ে, দৃষ্টির আড়ালে হারিয়ে যায়।"
  },
  Event_7353_Name = {
    Text = "নিশিযামিনীর পরী"
  },
  Event_7354_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7354_Desc = {
    Text = "তুমি আতঙ্কে তীক্ষ্ণ চিৎকার করে ওঠো।\nতোমার কণ্ঠে বিভ্রান্ত হয়ে, আগে যে হাতটি অস্থির ছিল তা এক মুহূর্তের জন্য থমকে যায়।\nসুযোগটি লুফে নিয়ে তুমি সঙ্গে সঙ্গে পালিয়ে যাও।"
  },
  Event_7354_Name = {
    Text = "বিষণ্ণ জলাভূমি"
  },
  Event_7355_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7355_Desc = {
    Text = "মুচড়ানো, কিলবিল করা, হামাগুড়ি দেওয়া... ওই বিরক্তিকর বাহুগুলো থেকে পালাতে তুমি সব রকম উপায়ই চেষ্টা করেছিলে।\nশেষমেশ তুমি পালাতে পেরেছিলে, বিনিময়ে হারিয়েছ একেবারে নতুন ইউনিফর্ম, দুটো পাঁজর, আর শত শত চুল।"
  },
  Event_7355_Name = {
    Text = "বিষণ্ণ জলাভূমি"
  },
  Event_7356_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7356_Desc = {
    Text = "\n「স্বাভাবিক ঘটনা। ভয় পেয়ো না, কোনো ফেজ নবীনের মতো, 」\nডল ঝুঁকে এসে তোমার ব্রোচের অবস্থান ঠিক করে। 「এটা বোঝাচ্ছে, আশেপাশে বিশেষ মাত্রার প্যাসেজ আছে। মনে হচ্ছে দিকটা আশ্রয়স্থলের দিকে।」"
  },
  Event_7356_Name = {
    Text = "অস্থির ব্রোচ"
  },
  Event_7357_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7357_Desc = {
    Text = "আলোবাহকের ভক্তদের গলাধঃকরণ করানো নিবেদন গ্রহণ করার কোনো কারণ তোমার নেই。\nএকটি কাক, তার নোংরা আর গ্রোটেস্ক স্তুপীকৃত মাথাগুলো বিরক্তিতে ঝাঁকিয়ে, কবরস্থানের মতো এক শব্দ তুলে কা কা করতে করতে উড়ে যায়।"
  },
  Event_7357_Name = {
    Text = "অভিশপ্ত দুর্কাক"
  },
  Event_7358_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7358_Desc = {
    Text = "「「এটাও ছিল আমারই সিদ্ধান্ত,」 ভালুক আঁকড়ে ধরা অবয়বটি বলে। 「কিন্তু সে হয়ে যাবে তার পুতুল, আর তারা সবাই মারা যাবে।\nআর তুমি এই ট্র্যাজেডির সহায়ক হয়ে থাকবে।」\nতীব্র অপরাধবোধ তোমাকে গ্রাস করে। ছায়ামূর্তিগুলো মিলিয়ে যায়, তোমাকে বুকে হাত চেপে ধরে রেখে যায়, তুমি নিশ্চিত নও, এটা কি ছিল কোনো প্রক্ষেপণ, নাকি মানসিক চাপে উদ্ভূত কোনো মায়াভ্রম।「"
  },
  Event_7358_Name = {
    Text = "বিভক্ত পথ"
  },
  Event_7359_ChoiceDesc1 = {
    Text = "[Keep Covering Ears] Arg1টি কালো চিহ্ন প্রাপ্ত হও; জাগরণকারীদের মধ্যে সর্বোচ্চ অ্যালিমাস মানের সমপরিমাণ।"
  },
  Event_7359_ChoiceDesc2 = {
    Text = "[Keep Covering Ears] Arg1 HP পুনরুদ্ধার করো; তোমার অধীনে থাকা কালো চিহ্নের সংখ্যার দ্বারা এই পরিমাণ বৃদ্ধি পাবে।"
  },
  Event_7359_Desc = {
    Text = "তুমি কানের কাছে অশুভ সান্ত্বনার কথায় কান দিলে, সুচের মতো তীক্ষ্ণ চিৎকার মোচড় দিয়ে তোমার কানে বিঁধে গেল।\n「থামো——এখনই থামো——আমি তো তোমার কথামতোই করেছি——থামো——」\nতুমি যন্ত্রণায় মাথা চেপে ধরলে, ঘোরের মধ্যে কাকের দলের উপহাসের শব্দ শুনতে পেলে।"
  },
  Event_7359_Name = {
    Text = "কাকদের গান"
  },
  Event_7360_ChoiceDesc1 = {
    Text = "[Catch a Crow] প্রতিটি জাগরণপ্রাপ্ত জাগরণকারীর জন্য 25টি করে কালো চিহ্ন প্রাপ্ত হও।"
  },
  Event_7360_ChoiceDesc2 = {
    Text = "[Howl] তোমার ডেকে থাকা একটি জাগরণ কার্ড বেছে নাও এবং তাতে 「সহজাত」 প্রত্যয়টি সংযোজন করো।"
  },
  Event_7360_Desc = {
    Text = "হঠাৎ তোমার মধ্যে দুষ্টুমি ভর করে, তুমি একটি কাক ধরে ফেলো।\nতোমার মুঠোর ভেতর সে মরিয়া হয়ে ছটফট করে, তারপর উষ্ণ এক ছিটকে পড়া স্রোতে ভেঙে যায়।"
  },
  Event_7360_Name = {
    Text = "কাকদের গান"
  },
  Event_7361_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7361_Desc = {
    Text = "তুমি কান দুটো ঢেকে চোখ বন্ধ করো।\nধুপ, ধুপ... তোমার হৃদস্পন্দন তীক্ষ্ণ কিচকিচ শব্দের সঙ্গে মিশে গড়ে তোলে বিশৃঙ্খল মৃত্যুসিম্ফনি।\nএই মুহূর্তে, তুমি এক অভূতপূর্ব শান্তি অনুভব করো।"
  },
  Event_7361_Name = {
    Text = "কাকদের গান"
  },
  Event_7362_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7362_Desc = {
    Text = "ডোমেইন ভরপুর বিপদে। সব আলো পথপ্রদর্শক বাতিঘর নয়।\nকিছু আলো কেবল পতঙ্গকে মৃত্যুর দিকে টেনে নেওয়া মোমবাতি।"
  },
  Event_7362_Name = {
    Text = "নিশাদ্যুতি"
  },
  Event_7363_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7363_Desc = {
    Text = "「তুমি অনেক আগেই মারা গেছ, আর বাড়িও ফিরতে পারবে না।」 তোমার কণ্ঠস্বর রস তুষারভূমির গর্জনকারী বায়ুর মতো নির্মম। পথিকের অভিব্যক্তিতে কোনো পরিবর্তন নেই, যেন এটাই স্বাভাবিক। সে আবার তোমার হাত ধরল, 「আমাকে বাঁচাও। আমি একজন সৈনিক, সুদূর পূর্বে যাওয়ার আদেশ পেয়েছিলাম……」"
  },
  Event_7363_Name = {
    Text = "গ্রাসকারী"
  },
  Event_7364_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7364_Desc = {
    Text = "টেলিগ্রাফটা ভেঙে গেছে। ঝড়ের মধ্যে তার মালিকের হতাশা কল্পনা করো… ঠিক এখনকার তোমার মতোই।"
  },
  Event_7364_Name = {
    Text = "নীরব তারবার্তা"
  },
  Event_7365_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7365_Desc = {
    Text = "\"পঞ্চাশ গজ সোজা এগিয়ে যাও, তারপর বাঁয়ে, তারপর ডানে, তারপর আবার বাঁয়ে...\nতারপর একদম শেষ পর্যন্ত হাঁটো, তোমার বাড়ি ঠিক সেখানেই।\"\nপথিক আনন্দে আত্মহারা হয়ে উঠল। সে হাত নেড়ে বিদায় জানাল, তারপর চলে গেল।\nতুমি গভীর শ্বাস নিলে, আর হঠাৎই অনুভব করলে কেউ তোমার হাত চেপে ধরেছে। সেই পরিচিত কণ্ঠস্বর আবারও তোমার কানে প্রতিধ্বনিত হলো:\n\"আমাকে বাঁচাও, প্লিজ।\nআমি এক সৈনিক, যাকে পাঠানো হয়েছে সুদূর পূর্বে...\""
  },
  Event_7365_Name = {
    Text = "গ্রাসকারী"
  },
  Event_7366_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7366_Desc = {
    Text = "অবশেষে তুমি গোলকধাঁধা থেকে বেরিয়ে আসতে পেরেছ।\nসেই মুহূর্তে হঠাৎই উপলব্ধি করো, এই মোম জাদুঘরটি জীবন্ত।\nসব অদ্ভুততা, সৌন্দর্য আর নিষ্ঠুরতা জড়িয়ে আছে এক প্রাচীন আচার অনুষ্ঠানের সুতোয়।\nআর সেই আচার অনুষ্ঠানের কেন্দ্রে রয়েছে রজার্স।"
  },
  Event_7366_Name = {
    Text = "চোখের গোলকধাঁধা"
  },
  Event_7367_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7367_Desc = {
    Text = "\"ভূমিকা-অভিনয় কি মজার, রক্ষক?\" রামোনা তোমার জামার হাতা টেনে ধরে। \"বেরোনোর পথ আর বেশি দূরে নয়। আমি আশা করি, লেডি ড্যাফোডিলের সামনে গিয়েও তুমি এই রকমই রসিকতা ধরে রাখতে পারবে।\""
  },
  Event_7367_Name = {
    Text = "স্মৃতির খণ্ডাংশ: গতকালের স্বপ্ন"
  },
  Event_7368_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7368_Desc = {
    Text = "「একজন জাগরণকারীর পক্ষে লিঙ্কারের ইচ্ছার বিরোধিতা করা কঠিন,」 তুমি জবাব দাও, 「কিন্তু আমরা ত্যাগ করব না।」"
  },
  Event_7368_Name = {
    Text = "তার পছন্দ"
  },
  Event_7369_ChoiceDesc1 = {
    Text = "[Enter] দেয়ালের মধ্য দিয়ে, আরও গভীরে যাও।"
  },
  Event_7369_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7369_Desc = {
    Text = "তুমি দেয়ালের কাছে এগিয়ে গেলে, সেটি হঠাৎ মোচড় খেয়ে যেন তোমাকে গিলে নিতে উদ্যত হয়।"
  },
  Event_7369_Name = {
    Text = "বিকৃত মহাকাশ"
  },
  Event_7370_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7370_Desc = {
    Text = "\n“না, তা ঠিক নয়। আরশোলার সঙ্গে তুলনা করলে, অন্তত তোমাদের গায়ে নরম লোম আছে।\nকেউই নরম লোমের আকর্ষণ এড়াতে পারে না।”\nইঁদুরগুলো নিজেদের মধ্যে ফিসফিস করে কথা বলল, আর শেষমেশ তোমার কথার সঙ্গে একমত হলো।\n“যদিও, খুব বেশি লোম তো আর নেই।”\nপ্রশংসা পাওয়া সবসময়ই মনোরম। বিদায় নেওয়ার আগে, ইঁদুরগুলো তোমাকে একটি ছোট উপহার দিয়ে গেল।"
  },
  Event_7370_Name = {
    Text = "প্লেগ"
  },
  Event_7371_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7371_Desc = {
    Text = "「আমি একমত! মানুষ আর ইঁদুর একসাথে থাকতে পারে না!」\nইঁদুরগুলো কিছুটা রেগে গেল, সাদা দাঁত বের করে।\n「তাহলে তুমি এখনো এখানে কেন? তোমার জিনিসপত্র নিয়ে চলে যাও, আর কখনো ফিরে এসো না।」"
  },
  Event_7371_Name = {
    Text = "প্লেগ"
  },
  Event_7372_ChoiceDesc1 = {Text = "[Confirm]"},
  Event_7372_Desc = {
    Text = "গভীর সাগরের নীচে স্বাগতম, যেখানে প্রতিটি পদক্ষেপই অসীম চাপের ভারে নুয়ে থাকে।\n\nঅভেদ্য বিশৃঙ্খলার কুয়াশা সবকিছু আড়াল করে রেখেছে; এমন চাপের মধ্যে তুমি কি এই আলোহীন সাগর পেরিয়ে পথ খুঁজে পাবে?"
  },
  Event_7372_Name = {
    Text = "জোয়ারের নীচে"
  },
  Event_7373_ChoiceDesc1 = {
    Text = "[Just Take a Look] একটি কার্ড ধ্বংস করো"
  },
  Event_7373_ChoiceDesc2 = {
    Text = "[Take a closer look] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_7373_Desc = {
    Text = "\"টাপ টাপ...\"\nটাইপরাইটারটা, যেন অতিরিক্ত হুইস্কি খাওয়া কোনো বুড়ো মাতালের মতো, তোতলাতে তোতলাতে কালো কালি উগরে দিচ্ছিল।\nতুমি দ্রুতই \"মেসন\" নামটা খেয়াল করলে এবং তাড়াতাড়ি টাইপ করা কাগজটা টেনে বের করে নিলে।"
  },
  Event_7373_Name = {
    Text = "টাইপরাইটার"
  },
  Event_7374_ChoiceDesc1 = {
    Text = "[Eye Contact] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7374_ChoiceDesc2 = {
    Text = "[Close Your Eyes] 2 জন এলোমেলো জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)「 দু」বার বিকশিত করো।"
  },
  Event_7374_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7374_Desc = {
    Text = "অগণিত চোখ তোমার কানের চারপাশে হুইসপার করে।\n\"আমরা যাত্রা করি, আমরা থামি, আমরা দশ সহস্র বছর, তারও বেশি সময় ধরে এগিয়ে চলি।\nযখন সূর্য আমাদের সতর্ক দৃষ্টির নীচে ম্লান হয়ে যায়, যখন প্রাচীন পৃথিবীর জীবন প্লাবনে গ্রাসিত হয়।\nআমরা বহু আগেই মহাবিশ্বের রহস্যে মুগ্ধ হয়ে পড়েছি।\""
  },
  Event_7374_Name = {Text = "চোখ"},
  Event_7375_ChoiceDesc1 = {
    Text = "[Follow the Instructions] সর্বোচ্চ HP Arg1 দ্বারা বৃদ্ধি করো"
  },
  Event_7375_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7375_Desc = {
    Text = "তুমি রৌপ্য চাবির অনুসন্ধানী শক্তি ব্যবহার করে নিকটতম সংযোগস্থল খুঁজতে চেষ্টা করো, কিন্তু যে তথ্য তুমি পাও, তাতে সূক্ষ্ম অস্বাভাবিকতা লুকিয়ে থাকে, যেন তা কোনো এক হস্তক্ষেপে বিকৃত হয়েছে।"
  },
  Event_7375_Name = {
    Text = "অস্বাভাবিক যোগাযোগ"
  },
  Event_7376_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7376_Desc = {
    Text = "তুমি তোমার মিথাগ ছাত্র কিটের মানক লিনেন রুমাল দিয়ে আলতো করে টাইপরাইটার মুছে দাও।\nটাইপরাইটার শান্ত হয়ে যায়। আর ময়লা রুমালটি... ডোমেইনেই থেকে যায়।"
  },
  Event_7376_Name = {
    Text = "টাইপরাইটারের মৃদুস্বর"
  },
  Event_7377_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7377_Desc = {
    Text = "তুমি চোখ কুঁচকে তাকাও, দুলতে থাকা, একে অন্যের উপর চেপে বসা কালির দাগের ফাঁক দিয়ে অস্পষ্ট এক নাম ভেসে ওঠে: \"ফিঙ্গাল·ইয়োহানসেন\"।\nএ কে?"
  },
  Event_7377_Name = {
    Text = "টাইপরাইটারের মৃদুস্বর"
  },
  Event_7378_ChoiceDesc1 = {
    Text = "[Look Up] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_7378_ChoiceDesc2 = {
    Text = "[Sun's Angle?] এক জাগরণকারীকে জাগরণ ঘটাও, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত হবে।"
  },
  Event_7378_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7378_Desc = {
    Text = "\"এখনই, দক্ষিণ-পূর্ব দিকে তাকাও। সূর্যের উন্নতি কোণ ঠিক জায়গায়।\" পুতুলের কমান্ডটি যোগাযোগকারী দিয়ে ভেসে এলো।"
  },
  Event_7378_Name = {
    Text = "উত্তরণ"
  },
  Event_7379_ChoiceDesc1 = {
    Text = "[Infection\"(Skill.Arg1)\", Gain Golden Relic \"(RelicConfig.Arg2)\"]"
  },
  Event_7379_ChoiceDesc2 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7379_Desc = {
    Text = "ইভেন্ট 354 (উন্নয়নাধীন), চূড়ান্ত প্রভাব নয়"
  },
  Event_7379_Name = {
    Text = "ইভেন্ট 354 (উন্নয়নাধীন)"
  },
  Event_7380_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7380_Desc = {
    Text = "পিয়ানোর কী-এর নিচ থেকে বালকদের কণ্ঠ ভেসে আসে।\n<Italic:\"বুড়ো চার্লির ট্যাবি, মোটা আর প্রিয়...\">\nবালকদের গানের তলায়, এক তরুণীর কোমল কণ্ঠস্বর ধীরে ধীরে মিশে যায়।\nতুমি কি ভুল শুনছ...?"
  },
  Event_7380_Name = {
    Text = "শিশুদের ছড়া"
  },
  Event_7381_ChoiceDesc1 = {
    Text = "[Turn Around] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7381_ChoiceDesc2 = {
    Text = "[Keep Going] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_7381_Desc = {
    Text = "পেছন থেকে পদধ্বনি প্রতিধ্বনিত হয়।\nছায়ার মতো, তারা ধীর, স্থির ছন্দে তোমার পিছু নেয়।\nতোমার পদধ্বনির সঙ্গে জড়িয়ে তারা শূন্য প্রদর্শনী হলে অনুরণন তোলে।"
  },
  Event_7381_Name = {
    Text = "অক্সফোর্ডস"
  },
  Event_7382_ChoiceDesc1 = {
    Text = "[Fold the Letter] যেকোনো 2টি কার্ড ধ্বংস করো"
  },
  Event_7382_ChoiceDesc2 = {
    Text = "[Save Letters] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7382_ChoiceDesc3 = {
    Text = "[Leave] Arg1টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7382_Desc = {
    Text = "একটি নতুন টাইপরাইটার।\nএর নিজস্ব এক অদ্ভুত কী–সেট আছে, অণুবীক্ষণযন্ত্রের মতো সূক্ষ্ম আর সুশ্রী।\nতুমি যখন তার নিখুঁত যান্ত্রিক গঠনে মুগ্ধ হয়ে তাকিয়ে আছ, হঠাৎ কালো অক্ষর ভেসে ওঠে।\n“প্রিয় মি. রজার্স,\nভারাক্রান্ত হৃদয়ে আপনাকে জানাচ্ছি যে আপনাকে একাডেমি থেকে বহিষ্কার করা হয়েছে।\nআপনি জানেন, @2 একাডেমি তার কঠোর একাডেমিক মানদণ্ডের জন্য সারা রাজ্যে সুবিখ্যাত, আর সেই চমকপ্রদ গুজবগুলো @3 আমাদের গভীরভাবে বিচলিত করেছে...”"
  },
  Event_7382_Name = {
    Text = "লিখিত উপস্থিতি"
  },
  Event_7383_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7383_Desc = {
    Text = "দূরে, স্থির পকেট ঘড়িটি যেন তোমাকে তাগিদ দেয়, মনে করিয়ে দেয়—সময় ও স্থানের ফাঁদে যেন তুমি না হারিয়ে যাও।"
  },
  Event_7383_Name = {
    Text = "ঐশ্বরিক দৃষ্টি"
  },
  Event_7384_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7384_Desc = {
    Text = "কালো কাদা টুপটাপ করে তোমার মুখে পড়ে, ত্বকে ঝিনঝিনে চুলকানি ধরায়।\nসহ্য করতে না পেরে তুমি প্রজাপতিটাকে ঝেড়ে ফেলতে যাও।\nপ্রজাপতিটি তোমার বৈরী আচরণ এড়িয়ে নীরবে দূরের অন্ধকারে মিলিয়ে যায়।"
  },
  Event_7384_Name = {
    Text = "অবসিডিয়ান প্রজাপতি"
  },
  Event_7385_ChoiceDesc1 = {
    Text = "[Observe Carefully]"
  },
  Event_7385_ChoiceDesc2 = {Text = "[Dig]"},
  Event_7385_Desc = {
    Text = "কৌম তোমাদের তিনজনকে নিয়ে আশ্রমের ভেতর দিয়ে এগোয়, কোনো প্রবেশপথের খোঁজে।\nহঠাৎই সে থেমে যায়, এমন আকস্মিকভাবে যে তুমি প্রায়ই তার পিঠ থেকে ছিটকে পড়তে।\nতোমার জিজ্ঞাসার মাঝখানে কৌম মাথা নিচু করে নরম মাটি শুঁকে দেখে, তারপর ঘুরে দাঁড়িয়ে ইঙ্গিত করে—মাটির নিচে কিছুর উপস্থিতির দিকে।"
  },
  Event_7385_Name = {
    Text = "গভীরে সমাহিত"
  },
  Event_7386_ChoiceDesc1 = {
    Text = "[Receive] 3টি সোনালি রেলিক থেকে 1টি অর্জন করো"
  },
  Event_7386_Desc = {
    Text = "এলাকাটি ফাঁকা, মাটির ওপর দিয়ে বয়ে যাচ্ছে কালো তরল, যা কিছুই প্রতিফলিত করছে না।\nএটা কি মায়াস্বপ্ন? তুমি অনুভব করো, কিছু একটা তোমার আঙুলের ফাঁক গলে সরে যাচ্ছে।"
  },
  Event_7386_Name = {
    Text = "আয়নাতলে"
  },
  Event_7387_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7387_Desc = {
    Text = "ভেজা গলির মাটিতে কালো ডানা ঝরে পড়ে, আর কালো কাদার মতো D-পঙ্কে রূপ নেয়।"
  },
  Event_7387_Name = {
    Text = "উন্মত্ত কাকের ঝাঁক"
  },
  Event_7388_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7388_Desc = {
    Text = "\"মিস ড্যাফোডিল তোমার রসবোধকে প্রশংসা করবেন।\" রামোনা হাত নাড়ল, আর মায়াভ্রমটি মিলিয়ে গেল। \"নিজেকে যেন মাত্রা-অতিক্রমী ভ্রমণের মূল্য না বানাও।\""
  },
  Event_7388_Name = {
    Text = "স্মৃতির খণ্ডাংশ: গতকালের স্বপ্ন"
  },
  Event_7389_ChoiceDesc1 = {
    Text = "[Receive] 3টি সোনালি রেলিক থেকে 1টি অর্জন করো"
  },
  Event_7389_Desc = {
    Text = "হ্যাঁ, ওই ঘৃণ্য প্রতিবিম্বটিই তুমি।\nউথলে ওঠা বিদ্বেষ তোমার পায়ের কাছে কালো কাদার সঙ্গে মিশে গিয়ে পেঁচিয়ে ওঠে, নাচতে থাকে। তুমি আপত্তি না করলে, সেটি তোমার কাঁধেও চড়ে বসতে চায়।"
  },
  Event_7389_Name = {
    Text = "আয়নাতলে"
  },
  Event_7390_ChoiceDesc1 = {
    Text = "[Stand Still] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7390_ChoiceDesc2 = {
    Text = "[Walk Casually] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতা বিকশিত করো।"
  },
  Event_7390_Desc = {
    Text = "তুমি নিজের ছায়াকে খণ্ডাংশে চূর্ণ করো, আর তা পড়ে যায় রাতের এক পুকুরে।\nঅন্ধকারের ছড়িয়ে থাকা টুকরোগুলোই হারিয়ে যাওয়া বিশ্বের সঙ্গে একমাত্র সংযোগ।\nতুমি কি সত্যিই এই ঘন কালো দুঃস্বপ্নের ভেতর দিয়ে হাঁটবে? তুমি এখনো তোমার পথ খুঁজে পাওনি।"
  },
  Event_7390_Name = {
    Text = "দুঃস্বপ্ন পথিক"
  },
  Event_7391_ChoiceDesc1 = {
    Text = "[Seek the Source] 「(RelicConfig.Arg1)」 নামের রৌপ্য সৃষ্টি অর্জন করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7391_ChoiceDesc2 = {
    Text = "[Replay Record] সব জাগরণকারী 50 অ্যালিমাস পাবে, তবে তুমি 「(Skill.Arg1)」 উপসর্গটি বিকশিত করবে।"
  },
  Event_7391_ChoiceDesc3 = {
    Text = "[Dismantle the Phonograph] 3টি প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_7391_Desc = {
    Text = "\nতুমি একটি পুরনো গ্রামোফোনের সামনে এসে পড়লে।\nতুমি সেটি ঘুরিয়ে চাবি দাও, আঁচড়ে ভরা ভাইনিল রেকর্ডে সুচ নামিয়ে দাও। সিম্ফনিটি বিকৃত, যেন টেপটাকে কেউ ছিঁড়ে টুকরো টুকরো করছে; পিতল ও তারের বাদ্যযন্ত্র একে অপরের সঙ্গে সংঘর্ষে লিপ্ত—এই সুর থেকে কোনো কণ্ঠই অক্ষত অবস্থায় বেরোতে পারে না।\nচড়চড়ে শব্দে ভরা সুরের শেষ প্রান্তে তুমি শুনতে পাও ছন্দময় কড়া নাড়ার শব্দ।\n\"ধাপ ধাপ... ধাপ ধাপ ধাপ... ধাপ...\"\nভ্রু কুঁচকে তুমি সুচ তুলে নাও, কিন্তু কড়া নাড়ার শব্দ একটুও বদলায় না, অব্যাহত থাকে।"
  },
  Event_7391_Name = {
    Text = "হারানো প্রতিধ্বনি"
  },
  Event_7392_ChoiceDesc1 = {
    Text = "[Gaze at Radiance] একটি রেলিককে অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」-এ রূপান্তর করো।"
  },
  Event_7392_ChoiceDesc2 = {
    Text = "[Touch the Light] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7392_ChoiceDesc3 = {
    Text = "[Turn and Leave] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7392_Desc = {
    Text = "ড্রিম ভিশনের অধীনে, ডোমেইন মিস্ট বাস্তবতাকে এক অন্ধকার পর্দায় ঢেকে দেয়। সবকিছু ঝাপসা লাগে, যেন কেবলমাত্র অনুভব করা যায়।\nসেই কুয়াশার ভেতর দিয়ে কোনো কিছুর আলো কুয়াশা ভেদ করে আসে। যেন জাহাজকে পথ দেখানো বাতিঘর, অথবা পথহারা শিশুকে ডেকে নেওয়া ধোঁয়া, তা নিরাপত্তার পথ নির্দেশ করে।"
  },
  Event_7392_Name = {
    Text = "নিশাদ্যুতি"
  },
  Event_7393_ChoiceDesc1 = {
    Text = "[Pause Music] একটি রৌপ্য সৃষ্টি-কে উন্নয়ন অর্জন করে সোনার রেলিক 「(RelicConfig.Arg1)」-এ রূপান্তর করো"
  },
  Event_7393_ChoiceDesc2 = {
    Text = "[Talking with It] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 এবং 「(Skill.Arg3)」 দক্ষতা বিকশিত করো।"
  },
  Event_7393_ChoiceDesc3 = {
    Text = "[Listen Quietly] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7393_Desc = {
    Text = "তুমি নোংরা কালো কাদার গর্ত থেকে স্মৃতির খণ্ডাংশ কুড়িয়ে তুললে।\nস্ফটিকগুলো আলোয় ঝিলমিল করছিল, ভেতরে ঘূর্ণায়মান কুয়াশা নাচছিল, আর স্মৃতির টুকরোগুলো বাতাসে ছিটকে যাওয়া বালুর মতো উড়ে বেড়াচ্ছিল।\nঅগোছালো, বিকৃত, আর শিউরে ওঠার মতো দৃশ্যগুলো চারপাশে মাথা তুলে দাঁড়াল।\nতুমি দৃষ্টি মেললে—\n"
  },
  Event_7393_Name = {
    Text = "মুন সিলভার শার্ড"
