  Event_7394_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7394_Desc = {
    Text = "তুমি কিছু ঝরে পড়া তুষারকণা ধরে কাছ থেকে তাকাও। সেগুলো স্বচ্ছ ফোঁটায় গলে না, বরং কালো, ঘন D-পঙ্কে রূপান্তরিত হয়।"
  },
  Event_7394_Name = {
    Text = "তুষার"
  },
  Event_7395_ChoiceDesc1 = {
    Text = "[I'm Not on Water] একটি এলোমেলো রৌপ্য সৃষ্টি-কে উন্নয়ন অর্জন করে সোনার রেলিক 「(RelicConfig.Arg1)」 তে রূপান্তর করো"
