  },
  Event_7395_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7395_Desc = {
    Text = "কুয়াশা সরে যায়, উন্মোচিত হয় তোমার দিকে বাড়িয়ে রাখা এক কঙ্কালসার হাত।\nমনে হয় তা ক্ষয়প্রাপ্ত, খসখসে পৃষ্ঠে লেগে আছে আঠালো কালো কাদা। সোনালি আলোয় জ্বলা আংটি ও গলার হার দিয়ে সজ্জিত।\nহাতটি তোমাকে কাছে ডাকছে।\nকেবল সংকটের ছায়াতেই গোপন সম্পদ সবচেয়ে উজ্জ্বল হয়ে ওঠে।"
  },
