  },
  Event_7396_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7396_Desc = {
    Text = "মায়াভ্রমটি মিলিয়ে যাওয়ার আগে তোমার দিকে হাত নাড়ে। কেবল ঠান্ডা তুষার আর আকাশছোঁয়া পর্বতমালা রয়ে যায়।"
