  },
  Event_7397_ChoiceDesc2 = {
    Text = "[Silver Moon Prayer] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতাটি বিকশিত করো।"
  },
  Event_7397_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7397_Desc = {
    Text = "তুমি নোংরা কালো পিচ্ছিল কাদার গর্ত থেকে স্মৃতিচারণের খণ্ডাংশ কুড়িয়ে নিলে।\nস্ফটিকগুলো মৃদু আলো ছড়াচ্ছিল, ভেতরে ঘুরপাক খাচ্ছিল সরু সরু স্রোত, আর স্মৃতির টুকরোগুলো বাতাসে বিক্ষিপ্ত বালুর মতো উড়ে বেড়াচ্ছিল।\nঅগোছালো, অদ্ভুত আর ভৌতিক সব দৃশ্য তোমার চারপাশে মাথা তুলে দাঁড়াল।\nতুমি তাকালে—"
