  Event_7398_ChoiceDesc1 = {
    Text = "[Fuel Up] 3টি প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_7398_ChoiceDesc2 = {
    Text = "[Extinguish It] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7398_Desc = {
    Text = "「আমি সেই দাসীর ছায়া, যাকে খুন করা হয়েছে, আর খুনি হল ওই প্রতারক সবুজ শিখা।」\nহালকা লাল আভা-ওয়ালা শিখাটি দুলে ওঠে, তোমার দিকে অভিযোগ তোলে।\n「আমি একসময় থাকতাম ফোলা চাঁদের প্রতিবিম্বে ঝলমল করা হ্রদের ধারে, গৌরবময় আর দীপ্তিময়।」"
  },
  Event_7398_Name = {
    Text = "বিবর্ণ অগ্নি"
  },
  Event_7399_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7399_Desc = {
    Text = "তুমি আর ছায়া রাস্তার বাতির নিচে দাঁড়িয়ে আছো, নীরব।\nআজ রাতে কোনো চাঁদ নেই, সব বাড়ি নিশ্চুপ।\nতুমি ছায়াকে হাত নেড়ে বিদায় জানিয়ে হেঁটে চলে গেলে।"
  },
  Event_7399_Name = {
    Text = "পথের আলোয় ছায়ামূর্তি"
  },
  Event_7400_ChoiceDesc1 = {
