  Event_7400_Desc = {
    Text = "কাকটি বিছানার মাথার দিকে বসে, রক্তাভ চোখে তোমার দিকে তাকিয়ে থাকে।"
  },
  Event_7400_Name = {
    Text = "ল্যান্টার্ন-ক্রো"
  },
  Event_7401_ChoiceDesc1 = {
    Text = "[I've Got No Wallet] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_7401_ChoiceDesc2 = {
    Text = "[জাল ভেঙে ফেলো]এলোমেলো 1টি কমান্ড কার্ড অরিসন লাভ করে：「(EnchantConfig.Arg1)」，সংক্রমিত হয়「(Skill.Arg2)」"
  },
  Event_7401_Desc = {
    Text = "হলুদ-কমলা এক জাল নীরবে ভেসে আছে বাতাসে, তার ফাঁকাগুলো দেয়ালের গায়ে বাসা বাঁধা মাকড়সার সূক্ষ্ম বুননের তুলনায় অনেক কম জটিল।\nতুমি হাত বাড়িয়ে দিতে নিজেকে আটকাতে পারো না; ভঙ্গুর জালটি সঙ্গে সঙ্গে দ্রবীভূত হয়ে যায়, আর তোমার কানে ভেসে আসে বালকদের হাসি।\n「সোনা, সিলভার, হলুদ, লাল, সব মানিব্যাগই আমাদের!」"
  },
  Event_7401_Name = {
    Text = "ভেগাস নেটওয়ার্ক"
  },
  Event_7402_ChoiceDesc1 = {
    Text = "[Repair the Telegraph] একটি এলোমেলো কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg2)」 খোদাই করো, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7402_ChoiceDesc2 = {
    Text = "[Bury the Telegraph] একটি এলোমেলো কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg2)」 উৎকীর্ণ করো, কিন্তু 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7402_ChoiceDesc3 = {
    Text = "[Ignore] একটি এলোমেলো কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_7402_Desc = {
    Text = "তুমি বরফঝড় থেকে সাময়িক আশ্রয় নিতে সরু গুহাচিড়ের ভেতর লুকিয়ে পড়েছ। কিন্তু জানো, এখানে বেশিক্ষণ থাকা যাবে না। যদি ওই কালো চাদর পরা ছায়াগুলো তোমাকে এখানে খুঁজে পায়, তবে পালানোর পথ নেই。\nচিড়ের এক কোণে তুমি একটি ক্ষতিগ্রস্ত টেলিগ্রাফ মেশিন আবিষ্কার করো।"
  },
  Event_7402_Name = {
    Text = "প্রাচীন উত্তরাধিকার"
  },
  Event_7403_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7403_Desc = {
    Text = "রাজ্যের ভেতরে বহু জায়গায় তুমি এমন প্রতিকৃতি দেখেছ।\n“রানী” দাঁড়িয়ে আছেন কেন্দ্রে, কালো গোলাপের ভিড়ে দীপ্তিমান।\nশুধু এক জায়গায় অমিল—তার মুখ নিষ্ঠুরভাবে খুঁচিয়ে তুলে ফেলা হয়েছে, রেখে গেছে দগ্ধ, কালো এক শূন্যতা।\nআজও তুমি রানীর প্রকৃত মুখাবয়ব দেখতে পাওনি।"
  },
  Event_7403_Name = {
    Text = "প্রতিকৃতি গ্যালারি"
  },
  Event_7404_ChoiceDesc1 = {
    Text = "[Spare Her] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7404_ChoiceDesc2 = {
    Text = "[সেকে সাহায্য করো]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_7404_ChoiceDesc3 = {
    Text = "[Walk My Own Path] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7404_Desc = {
    Text = "তিনটি অন্ধকার, ক্ষণস্থায়ী অবয়ব তোমার পথ ব্লক করে দাঁড়ায়।\n「তুমি তাকে যেতে দিতে পারো, 」 বলে যে জনের হাতে D-পঙ্কে ভেজা টেডি বিয়ার, 「সে শুধু ভীরু, দুষ্ট নয়। সে কাউকে আঘাত করতে চায় না।」\n「তুমি তাকে সাহায্য করতে পারো, 」 বলে যে জনের হাতে সুন্দর মোড়ানো ক্যান্ডির প্যাকেট, 「সে যা করতে পারে না, তুমি তা পারো। তুমি সবকিছুর ইতি টানতে পারো।」\n「তোমার আমাদের কথা শুনতেই হবে এমন নয়, 」 বলে যে জনের হাত ফাঁকা, 「তোমার নিজের পথ আছে।」"
  },
  Event_7404_Name = {
    Text = "বিভক্ত পথ"
  },
  Event_7405_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7405_Desc = {
    Text = "ড্যাফোডিলের কণ্ঠ এক মুহূর্তের জন্য থেমে গেল।\n“ওহ, তুমি এটা বেছেছ? চমৎকার নির্বাচন। পুরস্কার হিসেবে, আমি তোমাকে বিশেষ একটি উপহার দেব।”\n“ও শিশুটিকে আমি খুব চিনি না, তবে ফ্রান্সিস সম্পর্কে আমার একটি অনুমান আছে। আমি মনে করি যে আবেগটি তাকে গ্রাস করে আছে, আর তাকে ‘দেখার’ শক্তি দিচ্ছে, তা হলো তীব্র অনুতাপ। ভাবছি, এই অনুতাপকে ঘিরে সে কী নির্বাচন করবে...”"
  },
  Event_7405_Name = {
    Text = "ইঙ্গিতের সময়"
  },
  Event_74068_ChoiceDesc1 = {
    Text = "[Incorporate into Brain Vat] 「অতিরিক্ত ব্রেইন ভ্যাট」 ড্র পাইল-এ শাফল করো।"
  },
  Event_74068_Desc = {
    Text = "অলঙ্কৃত খোদাই করা খিলানের ভেতরে, লাল ইটের বাইরের দেয়ালের ঢালু ছাদের গায়ে, আর ফাঁপা প্রাচীরওয়ালা সারি বাড়িগুলোর সামনে, দীর্ঘায়িত ছায়ারা নৃত্য করে, জিজ্ঞাসার উত্তর খুঁজে ফেরে।\nমধ্যমতা কি মৃত্যুরই নাম?\nবর্তমান অবস্থায় সন্তুষ্ট থাকা কি অবধারিতভাবে নিভে যাওয়া আগুনের পরিণতি ডেকে আনে?"
  },
  Event_74068_Name = {
    Text = "অবশিষ্ট চেতনা"
  },
  Event_74069_ChoiceDesc1 = {
    Text = "[Continue Containment] সর্বোচ্চ 2টি কমান্ড কার্ড বেছে নিয়ে ডেক থেকে সরিয়ে দাও, এবং সেগুলোকে 「অতিরিক্ত ব্রেইন ভ্যাট」-এ স্থাপন করো।"
  },
  Event_74069_Desc = {
    Text = "\"আমি তাদের দেখেছি। অনেক মানুষ, অনেক ফিসফিসানি—জ্ঞানী, অগভীর, যুক্তিসংগত, উন্মাদ। কখনো কখনো, ছাইয়ের মধ্যেও আশার এক স্ফুলিঙ্গ জন্ম নেয়।\""
  },
  Event_74069_Name = {
    Text = "অবশিষ্ট চেতনা"
  },
  Event_7406_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7406_Desc = {
    Text = "তুমি সাবধানে দাঁড়িপাল্লা থেকে ইঁদুরটিকে তুলে নাও। তার শ্বাসপ্রশ্বাস স্থির, লোমশ দেহের উষ্ণতা তোমার তালু ভরে রাখে।"
  },
  Event_7406_Name = {
    Text = "যুক্তি ও আবেগ"
  },
  Event_7407_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7407_Desc = {
    Text = "ম্লান সিলভার কোর থেকে চোখ ধাঁধানো আলো বিচ্ছুরিত হলো, কিন্তু তা মুহূর্তেই মিলিয়ে গেল। হাতে শুধু বালির মতো এক মুঠো ছাই পড়ে রইল।\nসিলভার কোর তার শেষ আধ্যাত্মিক জ্ঞান নিঃশেষ করে ফেলেছে। অজানা সেই আত্মা দেহ পুনর্গঠন করতে পারেনি, তবে সম্পূর্ণ বিলীন হওয়ার আগে, নিজের অস্তিত্বের চিহ্ন রেখে গেছে।"
  },
  Event_7407_Name = {
    Text = "অস্তিত্বের প্রমাণ"
  },
  Event_7408_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7408_Desc = {
    Text = "「আমি ওই শিশুটিকে ভালো করে চিনি না, তবে ফ্রান্সিস সম্পর্কে আমার একটি অনুমান আছে। আমি মনে করি যে আবেগ তাকে নিয়ন্ত্রিত করেছিল এবং তাকে 「দেখার」 শক্তি দিয়েছিল, তা হলো গভীর অনুশোচনা। আমি ভাবছি, এই অনুশোচনার কারণে সে কী নির্বাচন করবে…「"
  },
  Event_7408_Name = {
    Text = "ইঙ্গিতের সময়"
  },
  Event_7409_ChoiceDesc1 = {
    Text = "[Pull The Paper] একটি কার্ড ধ্বংস করো"
  },
  Event_7409_ChoiceDesc2 = {
    Text = "[Not Now] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_7409_Desc = {
    Text = "তোমার স্যুটকেসের ভেতরের পোর্টেবল টাইপরাইটারটি হঠাৎ নিজে নিজে টাইপ করতে শুরু করে, তুমি টের পাওয়ার আগেই আধা পৃষ্ঠা বেঁকে যাওয়া লেখা বেরিয়ে আসে।\n「তুমি তাকে দেখেছ। সে সবসময়ই তোমার ঠিক পাশেই ছিল—উন্মাদনা আর অন্ধ উন্মত্ততায় কলুষিত সেই ছায়াগুলো... তার অবয়বের দিকে সরাসরি তাকিও না।」"
  },
  Event_7409_Name = {
    Text = "অনাহূত সতর্কবার্তা"
  },
  Event_7410_ChoiceDesc1 = {
    Text = "[Go Left] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_7410_ChoiceDesc2 = {
    Text = "[Go Right] এক জাগরণকারীকে জাগরণ ঘটাও, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত হবে।"
  },
  Event_7410_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7410_Desc = {
    Text = "মনে হচ্ছে তুমি এক গোলকধাঁধায় ঢুকে পড়েছ।\nবাঁ, ডান, আবার বাঁ... ধীরে ধীরে ধৈর্য ফুরিয়ে আসে, ঠিক তখনই তুমি মাথা তুলে চোখটা দেখতে পাও।\nচোখটি শান্ত, মহিমান্বিত ভঙ্গিতে তোমার দিকে তাকিয়ে থাকে, যেন এই স্থানের একচ্ছত্র শাসক।"
  },
  Event_7410_Name = {
    Text = "চোখের গোলকধাঁধা"
  },
  Event_7411_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7411_Desc = {
    Text = "অত্যন্ত কষ্টে তুমি হাত দুটো টেনে সরাও, আর স্পষ্ট শুনতে পাও হাড় ভাঙার শব্দ。\nতোমার কৌতূহলের জন্য এটাই তোমার চুকানো মূল্য।"
  },
  Event_7411_Name = {
    Text = "অনুপ্রেরণার বিস্ফোরণ"
  },
  Event_7412_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7412_Desc = {
    Text = "তুমি ক্যামেরাটি মনোযোগ দিয়ে পরীক্ষা করো; তার চামড়া আর কালো-সোনালি ইনলে থেকে মসৃণ এক দীপ্তি ঝরে。\nলেন্সটি তোমার দিকে তাক করা, যেন নীরবে চেয়ে আছে, গোপনে অনুসন্ধান করছে…"
  },
  Event_7412_Name = {
    Text = "নির্দোষতার নথি"
  },
  Event_7413_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7413_Desc = {
    Text = "তুমি নির্মমভাবে ক্যামেরার ভেতরে লুকিয়ে থাকা আরেকটি ফিল্ম স্ট্রিপ টেনে বের করলে, আর তাতে ফুটে ওঠা ছবিগুলো তোমার বাকরুদ্ধ কণ্ঠকে আরও ভারী করে তুলল।\nঅপ্রসেস করা সেই ফিল্ম বিশ্বস্তভাবে ধারণ করে রেখেছে— তুমি নিজে, কালো কাদার পাঁকে লুটিয়ে আছ।"
  },
  Event_7413_Name = {
    Text = "নির্দোষতার নথি"
  },
  Event_74145_ChoiceDesc1 = {
    Text = "[Read] একটি কমান্ড কার্ড ধ্বংস করো, এবং 25টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_74145_ChoiceDesc2 = {
    Text = "[Continue Typing] একটি কার্ড অনুলিপি করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_74145_Desc = {
    Text = "প্রিন্টার হিংস্রভাবে কালি উগরে দিচ্ছে।\nনোজল থেকে কালো কালি ভূতের মতো উথলে উঠছে, বাতাস ভরে তুলছে, আর ঘন, দমবন্ধ করা কালো কুয়াশা তৈরি করছে।\nকীবোর্ডের ভেতরে যেন কোনো গোপন ইঙ্গিত লুকিয়ে আছে, অপেক্ষা করছে নির্দোষ আঙুলের স্পর্শের জন্য।"
  },
  Event_74145_Name = {
    Text = "প্রেতাত্মার কালি"
  },
  Event_74146_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74146_Desc = {
    Text = "তুমি পা বাড়াও এক অন্ধকার গলিতে, কুয়াশা তোমার পোশাকে দাঁত বসায়, আর পেছনের ছায়াগুলো ভেঙে গিয়ে অসংখ্য জোড়া চোখে রূপ নেয়। মরচেধরা ঘণ্টার ধ্বনি ভেসে আসে স্যাঁতসেঁতে অশুভ বার্তা বয়ে।\n\nতুমি জানো, সব আঁকাবাঁকা পথ শেষমেশ ধসে পড়বে এক গুটিরূপ চক্রে—পচা ভোরের আগেই, তুমি আবার মুখোমুখি হবে নিজেরই প্রতিবিম্বের সঙ্গে।"
  },
  Event_74146_Name = {
    Text = "সময়ের ছাই"
  },
  Event_74147_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74147_Desc = {
    Text = "নিঃশব্দে, আপনি বুকে এক চিহ্ন আঁকেন, প্রয়াতদের জন্য নিবেদন করেন নীরব প্রার্থনা।\nএই বিলুপ্ত জগতে, এমন অসংখ্য জিনিস আছে যা আপনার সাধ্যের বহু বাইরে।\nহাড়টি মৃদু ঝলকে ওঠে, তার বহু আগে মৃত মালিকের একদা সযত্নে লুকিয়ে রাখা গোপন সম্পদের আভাস প্রকাশ করে।"
  },
  Event_74147_Name = {
    Text = "বিবর্ণ অস্থি"
  },
  Event_74148_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74148_Desc = {
    Text = "「পিতা ঈশ্বর তোমার করুণায় সন্তুষ্ট। পিতা ঈশ্বর আমাদের রক্ষা করবেন, দুঃখকষ্টের বোঝা থেকে আমাদের মুক্তি দেবেন।」\n\nতার মায়ামূর্তি ধীরে ধীরে মিলিয়ে গেল, পবিত্র সংগীতের সুরও নির্দয় বাতাসের গর্জনে হারিয়ে গেল।"
  },
  Event_74148_Name = {
    Text = "অঙ্গের প্রার্থনা"
  },
  Event_74149_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74149_Desc = {
    Text = "আপনি আলগা হয়ে থাকা কঙ্কালটিকে আলতো করে ঠেলে দেন; তা ধীরে ধীরে কালো কাদায় ডুবে যায়, বিন্দুমাত্র চিহ্ন না রেখে মিলিয়ে যায়।\nশূন্যতার মাঝেই যেন তার আত্মা শান্তি খুঁজে পায়।"
  },
  Event_74149_Name = {
    Text = "বিবর্ণ অস্থি"
  },
  Event_7414_ChoiceDesc1 = {
    Text = "[Leave] আপনি প্রতিপক্ষকে হত্যা করেছেন, এবং কিছুই ঘটেনি।"
  },
  Event_7414_Desc = {
    Text = "「মনে হচ্ছে ওটাকে কষ্টের মধ্য দিয়েই শিখতে হবে—একজন নারীর গোপন কথা এত সহজে উন্মোচিত হয় না।」\nড্যাফোডিলের কথা মিলিয়ে যেতেই, এক বিশাল দানব তোমার সামনে আবির্ভূত হয়।"
  },
  Event_7414_Name = {
    Text = "ইঙ্গিতের সময়"
  },
  Event_74150_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74150_Desc = {
    Text = "এমন বিকৃত খেলনা জেনকিন যে ঘড়িঘরে লুকিয়ে আছে, সেখানে থাকার কথা নয়; এই শব্দ আসলে জন্ম নিচ্ছে তোমার মস্তিষ্কে, তোমার স্মৃতিতে।\nতুমি মনে করো সেই অনুভূতিগুলো, যখন তুমি ছিলে এক ভ্যাটের ভেতর ভাসমান মস্তিষ্ক—শব্দতরঙ্গ থেকে রূপান্তরিত বৈদ্যুতিক স্রোত।\nসে অদ্ভুত শব্দ ধীরে ধীরে স্বাভাবিক ও সান্ত্বনাদায়ক হয়ে ওঠে, রূপ নেয় মসৃণ ধ্রুপদী সুরে, যা তোমার মনের ভেতর বারবার বেজে চলে।"
  },
  Event_74150_Name = {
    Text = "ঘণ্টাঘরের প্রতিধ্বনি"
  },
  Event_74151_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74151_Desc = {
    Text = "ওটা বিড়াল নয়……ওটা উত্তেজিত লণ্ঠন ধর্মসম্প্রদায়ের অনুসারী।\nকালো পাতলা আবরণের নিচ থেকে ঘৃণা ও শত্রুতা ঝরে পড়ছে, ফিসফিস শব্দ তোমার চেতনাকে আঁচড়ে দিচ্ছে, সাথে নিয়ে আসছে অদ্ভুত ও রহস্যময় বিভ্রম।"
  },
  Event_74151_Name = {
    Text = "বিড়ালের মৃদুস্বর"
  },
  Event_74152_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74152_Desc = {
    Text = "তারা আপনার জুতো আঁকড়ে ধরে, গোড়ালি জাপটে ধরে; তারা লোভী, তারা ক্ষুধার্ত, আর তারা প্রাণপণে চেষ্টা করে আপনাকে টেনে নামাতে সেই অতল গহ্বরে, যেখানে তারা বাস করে।\nআপনি প্রাণপণে লড়াই করে দাঁড়িয়ে থাকার চেষ্টা করেন, কয়েক কদম হোঁচট খেয়ে পেছাতে পেছাতে কোনো এক পলায়নের পথ খুঁজতে থাকেন।\nঅজান্তেই, আপনার হাত থেকে কিছু একটা পড়ে যায়।"
  },
  Event_74152_Name = {
    Text = "দুঃস্বপ্নের প্রতিবিম্ব"
  },
  Event_74153_ChoiceDesc1 = {
    Text = "[Dodge] 3টি প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_74153_ChoiceDesc2 = {
    Text = "[Stop] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে যেকোনো একটিতে খোদাই করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_74153_Desc = {
    Text = "পরিচিত দৃশ্য তোমার স্নায়ুকে ঝাঁকুনি দেয়, টেনে ধরে, আতঙ্কে সঙ্কুচিত করে ফেলে।\n「আবারও...「\nনির্দয় দুঃস্বপ্ন এসে যায়, আর এক অপ্রতিরোধ্য অসহায়তার ঢেউ তোমাকে গ্রাস করে।\nতার ভাগ্য কি সত্যিই আর কখনো পুনর্লিখন করা যাবে না?\nসময় নেই। সারার ফাটলধরা করোটির ভেতর, এক বিরাট মুখ সিলভার ঝিলিক ছড়িয়ে তোমাকে দু」টুকরো করে ফেলতে উদগ্রীব, গ্রাস করে চিবিয়ে খেতে চায়।"
  },
  Event_74153_Name = {
    Text = "দুঃস্বপ্নের পুনর্জন্ম"
  },
  Event_74154_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74154_Desc = {
    Text = "তুমি অস্বস্তিকর হুইসপার শুনতে পাও।\n\n\"আমরা এসেছি দূর নক্ষত্রের পর্বতমালা আর জলাভূমি থেকে। আমাদের দেহই লণ্ঠনের সলতে ও জ্বালানি, আর আমরা প্রজ্বলিত করব পৃথিবীর জ্বালানি কাঠ, আলোকিত করব নতুন বিশ্বের সলতের পথ।\""
  },
  Event_74154_Name = {
    Text = "বিড়ালের মৃদুস্বর"
  },
  Event_74155_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74155_Desc = {
    Text = "সূর্যাস্ত, ঘণ্টাধ্বনির মিনার, উড়ন্ত পাখি...\nমেয়েটি তার চোখের পট্টি খুলে ফেলল, আর তার ধূসর মণির দৃষ্টি তোমাকে স্থির করে দিল।\nমায়াস্বপ্নগুলো মরীচিকার মতোই দেখা দিতেই মিলিয়ে গেল, তবু থেকে যাওয়া দুশ্চিন্তাগুলো আর কাটতে চাইল না।"
  },
  Event_74155_Name = {
    Text = "সাদা চোখের পট্টি"
  },
  Event_74156_ChoiceDesc1 = {
    Text = "[Pick Up] 3টি রৌপ্য সৃষ্টি থেকে 1টি অর্জন করো"
  },
  Event_74156_ChoiceDesc2 = {
    Text = "[Recall]টি রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)「, 「(RelicConfig.Arg2)「 অর্জন করো, 「(Skill.Arg3)「-এর সাথে দু」বার চুক্তি করো।"
  },
  Event_74156_Desc = {
    Text = "কোণের ক্ষয়িষ্ণু কাদার ভেতর পড়ে আছে একটি ছোট সাদা চোখের পট্টি।\nস্মৃতিচারণ আপনার হৃদয়কে আঁকড়ে ধরে।"
  },
  Event_74156_Name = {
    Text = "সাদা চোখের পট্টি"
  },
  Event_74157_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74157_Desc = {
    Text = "স্বচ্ছ তালু কালো-সাদা কী-এর ওপর দিয়ে সুনিপুণ ভঙ্গিতে ভেসে যায়, অথচ তার উৎপন্ন শব্দতরঙ্গ ভাঙাচোরা, যেন বেসুরো কোনো মিউজিক বক্স। প্রতিটি নোট একেকটি বেসুরো আর্তনাদ ছড়ায়, যেন যন্ত্রণায় সাহায্যের জন্য চিৎকার করছে।\nঅবশেষে, পরিবেশনা হঠাৎই থেমে যায় এক অসহায় কর্ডের ওপর।\nজীবনে যা অধরা রয়ে গেছে, তা এখন এই মুহূর্তে ঝুলে থাকে, পেছনে ফেলে যায় গভীর, কুরে-কুরে খাওয়া এক আকুল আকাঙ্ক্ষা।"
  },
  Event_74157_Name = {
    Text = "আক্ষেপের সোনাটা"
  },
  Event_74158_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74158_Desc = {
    Text = "「শ্রদ্ধেয়া মিস সারা:\nআমি দরিদ্রালয়ের সেবিকা পদ থেকে পদত্যাগের আবেদন জানাচ্ছি।\nআমি আর আপনার আদর্শে বিশ্বাস রাখতে পারছি না। আপনার শিক্ষা ভুল। পূর্বাঞ্চলের শিশুদের আপনার ছায়ায় বেড়ে ওঠা উচিত নয়, তাদের নিঃস্বার্থ দান আর নিখাদ সদিচ্ছায় বিশ্বাস করা উচিত নয়।\nএকদিন না একদিন তাদের আপনার আশ্রয় ছেড়ে বেরিয়ে যেতে হবে, পূর্বাঞ্চলে টিকে থাকার নিয়ম শিখতে হবে।\n\n……」\n\nপরবর্তী লেখাগুলো কালো তরলে ভিজে ঝাপসা হয়ে গেছে।"
  },
  Event_74158_Name = {
    Text = "প্রেতাত্মার কালি"
  },
  Event_74159_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74159_Desc = {
    Text = "「বালকদের জন্য আমি যা দিতে পারি, তা শুধু বৃষ্টির হাত থেকে বাঁচার একটা ছাদ, আর এতটুকু খাবার, যাতে তারা অনাহারে না মরে। সদয় মিস্টার রজার্স যদি চিকিৎসককে না আনতেন, তবে অসুস্থ হলে তারা একটি ট্যাবলেটও পেত না।\nআমি বেশি বই পড়িনি; ওরা যাতে রাস্তায় হিমায়িত হয়ে বা না খেয়ে মরতে না হয়, সেটুকু নিশ্চিত করাই আমার সাধ্য।\nওরা কেমন মানুষ হয়ে উঠবে, তাতে আমি কখনো হস্তক্ষেপ করিনি, কিন্তু তাদের বাঁচতে হবে।\n.....」"
  },
  Event_74159_Name = {
