    Text = "[Check Letter] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7415_Desc = {
    Text = "আরেকটি চিঠি তোমার পায়ের কাছে পড়ে। ছেঁড়া কাগজটা খুলতেই এক অজানা ভয় তোমার বুক ভরে ফেলে।\n\"ও আবার এসেছে। আমার সতর্কবার্তা বৃথা যায়নি! @4 এখানেই এর শুরু, এখানেই এর শেষ।\"\n\"আমি পালাতে চাই... কাঠের আলমারির ভেতর লুকিয়েছি, আমার হাত অনিয়ন্ত্রিতভাবে কাঁপছে। কিন্তু আঠালো অঙ্গগুলো মেঝেতে থপথপ শব্দ তুলে ক্রমেই কাছে চলে আসছে... আমি একটা নাম শুনেছি! ওটাই! @5!\""
  },
  Event_7415_Name = {
    Text = "আরেকটি সাহায্যের চিঠি"
  },
  Event_74160_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74160_Desc = {
    Text = "「তোমাকে ধন্যবাদ, পিতৃদেবের সৃষ্টিশক্তি অবশেষে আমাদের রূপ পুনর্গঠন করবে, আমাদের জন্য চিরন্তন আলো ও অগ্নি বয়ে আনবে।\n\nযখন আমি যাত্রার শেষ প্রান্তে পৌঁছাব, পিতৃদেবের সম্মুখে তোমার জন্য আশীর্বাদ প্রার্থনা করব।」\n\nতার মায়ামূর্তি ধীরে ধীরে মিলিয়ে গেল, পবিত্র সংগীতের সুরও নির্মম বাতাসের গর্জনে হারিয়ে গেল।"
  },
  Event_74160_Name = {
    Text = "অঙ্গের প্রার্থনা"
  },
  Event_74161_ChoiceDesc1 = {
    Text = "[Bury] একটি কমান্ড কার্ড ধ্বংস করুন এবং Arg2 HP পুনরুদ্ধার করুন। [ExDesc1]"
  },
  Event_74161_ChoiceDesc2 = {
