  },
  Event_74161_Desc = {
    Text = "একটি ফ্যাকাশে কঙ্কাল, অর্ধেক ডুবে আছে পিচকালো D-পঙ্কের ভেতর।"
  },
  Event_74161_Name = {
    Text = "বিবর্ণ অস্থি"
  },
  Event_74162_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74162_Desc = {
    Text = "তুমি সরাসরি সেই কুয়াশার মধ্যে পা রাখলে, মায়াবী ছায়া মাকড়সার জালের মতো তোমার শরীরে জড়িয়ে ধরল, বরফশীতল স্পর্শ হাড়ের মজ্জায় প্রবেশ করল।\nতাদের ফিসফিস স্মৃতির টুকরোতে পরিণত হয়ে তোমার বুক ভেদ করে গেল।\nযখন তুমি পার হলে, পেছনে শুধু শূন্যতা রয়ে গেল, আর সামনে, ঘন কুয়াশার মধ্যে আরও অস্পষ্ট ছায়া ভেসে উঠতে লাগল, গ্রাস করার অপেক্ষায়।"
  },
  Event_74162_Name = {
    Text = "সময়ের ছাই"
  },
  Event_74163_ChoiceDesc1 = {
    Text = "[Avoid Phantasm] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতাটি বিকশিত করো।"
  },
  Event_74163_ChoiceDesc2 = {
    Text = "[Pass Through Phantasm] 3টি সোনার রেলিক থেকে 1টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_74163_ChoiceDesc3 = {
    Text = "[Leave] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_74163_Desc = {
    Text = "ধুলো জমে ভারী পর্দার মতো রাস্তাগুলোর ওপর বিছিয়ে আছে, আর প্রতিটি পা ফেলা যেন সময়ের ভস্মের ওপর পা রাখা।\nদূরে কুয়াশার ভেতর দুটো ছায়ামূর্তি ভেসে ওঠে, অতীতের মায়াভ্রমের মতো, ফিসফিসিয়ে বলে বহু আগেই বিস্মৃত কাহিনি।\nউন্মত্ত কল্পনা ভয়ংকর মায়াভ্রম রচনা করে, পেঁচিয়ে উঠে, ছড়িয়ে পড়ে, যেন ভবিষ্যৎ সর্বনাশের দূত, তোমার শ্বাসের ওপর ভারি হয়ে চেপে বসে।\nতুমি জানো সামনে পথ কেবল আরও অন্ধকার হবে, তবু তোমার পদক্ষেপ থামতে পারে না, থামা উচিতও নয়।"
  },
  Event_74163_Name = {
    Text = "সময়ের ছাই"
  },
  Event_74164_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74164_Desc = {
