  Event_74166_Desc = {
    Text = "উল্কাবৃষ্টি ঘড়িঘরের উপর ঝরে পড়ে।\nএকটি স্বচ্ছ স্ফটিক আপনার পায়ের কাছে আছড়ে পড়ে, মাটিতে ছোট্ট এক গর্ত তৈরি করে।\nআপনি এখনো নানান রূপের (ক্ষয়িত) সত্ত্বাদের দ্বারা পরিবেষ্টিত, যেন বিকৃত ছায়া। গর্জন আর হাহাকারের শব্দ এক মুহূর্তের জন্যও থামে না।\nআপনি সিদ্ধান্ত নেন—"
