  },
  Event_74167_Desc = {
    Text = "জুলিয়েটের পেছনে বিকৃত এক ঝাঁক কালো বিড়াল জড়ো হয়, অজানা জীবের মন্ত্রোচ্চারণে বিড়বিড় করতে থাকে এবং এক গোপন, অশুভ হুমকি ছড়িয়ে দেয়।"
