  Event_74168_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74168_Desc = {
    Text = "সস্তা কাপড়টি হাতে কিছুটা খসখসে লাগে, তবুও যত্ন করে পরিষ্কার করা হয়েছে।\nএটি ভালোভাবে সংরক্ষণ করো, সেই দিনের অপেক্ষায় যখন এটি তার আসল মালিকের কাছে ফিরে যাবে।"
