  },
  Event_74169_Desc = {
    Text = "তারা আপনার পায়ের নিচ থেকে ঝাঁকে ঝাঁকে উঠে আসে।\nবেদনার ঝাপসা মুখগুলোতে আপনি দেখেন আপনার নিজের ছায়া টেনে নেওয়া হচ্ছে।\nআপনি কি সত্যিই তাদের বিচার করার অধিকার রাখেন?"
