  },
  Event_7416_Desc = {
    Text = "ফ্যাকাশে অঙ্গপ্রত্যঙ্গগুলো আপনার সামনে ধীরে ধীরে কিলবিল করছে। সে ঝুঁকে পড়ে, তার ভাঙা হাতটি আপনার দিকে বাড়িয়ে দেয়। যন্ত্রণায় কুঁচকানো তার চোখ থেকে সাদা, প্লাস্টারের মতো অশ্রু উদ্বেল হয়ে ঝরছে।\n“আর... এক টুকরো পেলেই, আমি পারব...”"
