  Event_74171_ChoiceDesc2 = {
    Text = "[দৃষ্টি রাখো]এলোমেলোভাবে 1টি কমান্ড কার্ড অরিসন পায়：「(EnchantConfig.Arg1)」，1টি「(Skill.Arg2)」সংক্রমিত করো"
  },
  Event_74171_Desc = {
    Text = "「পরিসমাপ্তি ইতিমধ্যে নেমে এসেছে।」\nতোমার হৃদয় চেপে ধরে, সংকুচিত হয়।\nইউরিয়েটের দৃঢ় কণ্ঠস্বরে নিঃসন্দেহে কিছু সম্মোহন এবং মানসিক সংযোগের শক্তি নিহিত রয়েছে।\nএই মাত্রার ইউরিয়েটের উদ্দেশ্য আর অতীতে তুমি যে ইউরিয়েটকে চিনতে তার উদ্দেশ্যের মধ্যে কী পার্থক্য?\nরহস্য অনেক, বিভ্রান্তির স্তরে স্তরে।\nতুমি চোখ তুলে ইউরিয়েটকে পর্যবেক্ষণ করো, কিন্তু দেখতে পাও সেও তোমার দিকে একদৃষ্টে তাকিয়ে আছে।"
  },
