  Event_74172_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74172_Desc = {
    Text = "তুমি অস্বস্তিকর ভঙ্গিতে হাত তুলে ভ্রমময় পিয়ানোর কী-গুলোর ওপর টোকা দাও।\nকীগুলো ঝংকার তোলে ও একে অপরের সঙ্গে জড়িয়ে যায়, প্রতিটি স্বর যেন শিশিরবিন্দু—স্বচ্ছ ও নির্মল। এই দক্ষ ও সূক্ষ্ম বাজনা তোমার আঙুলের ডগা থেকে আসছে না।\nঅবচেতন এক ঘোরের মধ্যে তুমি দেখো, এক জোড়া আকারহীন, দীর্ঘায়িত হাত তোমার হাত দুটোকে ঢেকে রেখেছে, সুরের ওঠানামার সঙ্গে সঙ্গে উপরে নিচে নড়ছে।\nশেষ ক্ষীণ পিয়ানো স্বরটি মিলিয়ে যাওয়া পর্যন্ত সময় যেন হিমায়িত হয়ে থাকে।\nতুমি এক তৃপ্তির দীর্ঘশ্বাস শুনতে পাও।"
  },
  Event_74172_Name = {
    Text = "আক্ষেপের সোনাটা"
  },
  Event_74173_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74173_Desc = {
    Text = "বারবার সরে যাওয়া চেতনা অস্থির; তোমাকে অর্থহীন বিভ্রান্তি দূর করতে হবে।\nতুমি সামনে থাকা জেনকিনের ওপর মনোযোগ কেন্দ্রীভূত করো, আর ফোনোগ্রাফের শব্দ ধীরে ধীরে মিলিয়ে গিয়ে কুয়াশার ভেতর বিলীন হয়ে যায়।"
  },
  Event_74173_Name = {
    Text = "ঘণ্টাঘরের প্রতিধ্বনি"
  },
  Event_74174_ChoiceDesc1 = {
    Text = "[Locate the Source] 「(RelicConfig.Arg1)」 নামের রৌপ্য সৃষ্টি অর্জন করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_74174_ChoiceDesc2 = {
    Text = "[Reminisce] সব জাগরণকারী 50 অ্যালিমাস পাবে, তবে তুমি 「(Skill.Arg1)」 উপসর্গটি বিকশিত করবে।"
  },
  Event_74174_ChoiceDesc3 = {
    Text = "[Ignore Noise] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_74174_Desc = {
    Text = "আপনি ফোনোগ্রাফের সূচের বিকৃত শব্দ শুনতে পান।\nবাঁকানো সূচ ক্ষতিগ্রস্ত সর্পিল খাঁজের উপর দিয়ে গড়িয়ে যায়, ধীরে ধীরে এক শীতল, কাঁপন ধরানো কম্পন সৃষ্টি করে।"
  },
  Event_74174_Name = {
    Text = "ঘণ্টাঘরের প্রতিধ্বনি"
  },
  Event_74175_ChoiceDesc1 = {
    Text = "[তার জন্য বাজাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_74175_ChoiceDesc2 = {
    Text = "[Listening to the Strings] প্রতিটি জাগরণকারী, যার অ্যালিমাস 50 বা তার বেশি, তার জন্য 15টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_74175_ChoiceDesc3 = {
    Text = "[Leave] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_74175_Desc = {
    Text = "「প্রিয় জন, \nহঠাৎ টের পেলাম, তুমি আমাদের জন্য পিয়ানো বাজাওনি বহু বছর হয়ে গেছে।\nএই বছর আমার বয়স 81, আর বয়স যত বাড়ছে, যৌবনের স্মৃতিগুলোকে ততই বেশি আঁকড়ে ধরছি।\nযদি তুমি এই চিঠি পাও, তবে পরেরবার লন্ডিনিয়াম দিয়ে যাওয়ার সময় আমার অ্যাপার্টমেন্টে একবার এসো, আর আমার জন্য একটা সুর বাজিয়ে যেও।」"
  },
  Event_74175_Name = {
    Text = "আক্ষেপের সোনাটা"
  },
  Event_74176_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74176_Desc = {
    Text = "বেঁচে থাকার কামনা তোমার বুকে উচ্ছ্বাস তোলে, আর তুমি এক মুহূর্ত দেরি না করে আদেশ জারি করো।\nঅবরোধ ভেদ করে ফিরে তাকালে দেখো, সেই নক্ষত্রটি ইতিমধ্যে D-পঙ্কে ডুবে গেছে।\nঘূর্ণায়মান D-পঙ্কের ভেতর থেকে ধারালো, ছন্দময় এক শব্দ প্রতিধ্বনিত হয়।\nতুমি D-পঙ্কের পৃষ্ঠ স্পর্শ করো, আর এক ক্ষয়প্রাপ্ত নক্ষত্র তোমার তালুতে ঝরে পড়ে।"
  },
  Event_74176_Name = {
    Text = "একটি পতিত তারা"
  },
  Event_74177_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74177_Desc = {
    Text = "তুমি তারাটাকে কুড়িয়ে নাও, কিন্তু তোমার তালুতে এসে তার জ্যোতি নিভে গেছে।\nহঠাৎ এক ঢেউয়ের মতো চাপ তোমার ওপর ভেঙে পড়ে, শিরদাঁড়া বেয়ে ঠান্ডা স্রোত নেমে যায়।\nজীবন-মৃত্যুর মাঝের এক পলকের ফাঁকে তুমি সরে গিয়ে তীব্র আঘাত এড়িয়ে যাও, তবু তোমার হাতে দুই ইঞ্চি লম্বা এক আঁচড় থেকে যায়।"
  },
  Event_74177_Name = {
    Text = "একটি পতিত তারা"
  },
  Event_74178_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74178_Desc = {
    Text = "শুঁড়ের ভেতরে লুকিয়ে থাকা ধারালো দাঁত আপনার জামার হাতা ছিঁড়ে ফেলে, আর উষ্ণ রক্ত লাল সরু ঝর্ণার মতো আপনার কবজি বেয়ে গড়িয়ে পড়ে।\nআপনি সারা’র অভিব্যক্তি পড়তে পারেন না, কিন্তু ফেটে যাওয়া খুলি থেকে ক্ষীণ, কাঁপতে থাকা যন্ত্রণার আর্তনাদ বেরিয়ে আসে।"
  },
  Event_74178_Name = {
    Text = "দুঃস্বপ্নের পুনর্জন্ম"
  },
  Event_74179_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74179_Desc = {
    Text = "তুমি চারদিকে তাকাও, ডানে-বামে সরে দাঁড়াও। শব্দটা যেন ইঁদুরের সঙ্গে লুকোচুরি—কখনো বামে, কখনো ডানে, কখনো দূরে, আবার হঠাৎ একেবারে কাছে।\nতুমি এদিক-ওদিক ঘুরে বেড়াও, কিন্তু শব্দ আরও জোরে ওঠে। ধাতব ঘর্ষণের সেই আওয়াজ তোমার অস্বস্তিকে আরও গভীর করে।\nহঠাৎ খেয়ালে তুমি পকেটে হাত দাও। শব্দের উৎস না পেলেও, তুমি একটি ছোট গোপন সম্পদ তুলে আনো।"
  },
  Event_74179_Name = {
    Text = "ঘণ্টাঘরের প্রতিধ্বনি"
  },
  Event_7417_ChoiceDesc1 = {
    Text = "[Leave] Arg1 HP হারাও, এবং 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7417_Desc = {
    Text = "\n\"ভালো বাচ্চা। কিন্তু তবু, তোমাকে একটু শাস্তি তো দিতেই হবে।\"\nমাত্রিক ফাটলের ভেতর মিলিয়ে গেল ড্যাফোডিলের হালকা হাসি।"
  },
  Event_7417_Name = {
    Text = "ইঙ্গিতের সময়"
  },
  Event_74180_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74180_Desc = {
    Text = "তুমি দৃষ্টি সরিয়ে নাও, তার চোখের সঙ্গে চোখাচোখি এড়িয়ে যাও।\nতবু কোনো এক শক্তি এখনো তোমার হৃদয়কে উৎকণ্ঠায় দ্রুত স্পন্দিত করায়।"
  },
  Event_74180_Name = {
    Text = "অন্তিম দৃষ্টি"
  },
  Event_74181_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74181_Desc = {
    Text = "জুলিয়েট তোমার চোখে চোখ রাখল।\nপরের মুহূর্তেই, সে সম্পূর্ণ উন্মাদ এক হাসি ফুটিয়ে তুলল, যেন তোমার দাম্ভিকতা আর অজ্ঞতাকে উপহাস করছে।\nতবে সেই হাসি মুহূর্তেই মিলিয়ে গেল, অন্য কেউও এ নিয়ে কোনো প্রতিক্রিয়া দেখাল না……মনে হচ্ছে এটা শুধুই তোমার বিভ্রম ছিল।"
  },
  Event_74181_Name = {
    Text = "অন্তিম দৃষ্টি"
  },
