  Event_7420_ChoiceDesc1 = {
    Text = "[Dodge Butterfly Card] যেকোনো 2টি কার্ড ধ্বংস করো"
  },
  Event_7420_ChoiceDesc2 = {
    Text = "[Embrace the Butterfly] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7420_ChoiceDesc3 = {
    Text = "[Leave] Arg1টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7420_Desc = {
    Text = "মোড়ের পর মোড়, নরককুকুরের ধাওয়া যেন শেষই হয় না।\nব্যথায় জ্বালা করা গোড়ালি, ধুকপুক করা মস্তিষ্ক—এই বিশৃঙ্খলার মাঝেই তুমি আবার প্রজাপতি দেখতে পাও। তুমি জানো, ওরা উন্মাদনার বিভ্রান্তি, ডোমেইনের হুইসপার। তারা সব দিক থেকে উড়ে আসে।"
  },
  Event_7420_Name = {
    Text = "বিভ্রান্তির উদ্গীরণ"
  },
  Event_7421_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7421_Desc = {
    Text = "তুমি আলতো করে বাতাসি ঘণ্টায় চাপ দাও। তা নরম সুরে কয়েকবার বাজে, তারপর নীরব হয়ে যায়। সে ইতিমধ্যেই সরে গেছে— কেবল দুঃস্বপ্নে প্রত্যাবর্তনের জন্য।"
  },
  Event_7421_Name = {
    Text = "ছোট্ট বায়ুঘণ্টা"
  },
  Event_7422_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7422_Desc = {
    Text = "ঘণ্টাধ্বনি ক্ষণিকের জন্য বেজে স্তব্ধ হয়ে যায়। সে সরে গেছে— কেবল দুঃস্বপ্নে ফিরে আসার জন্য।"
  },
  Event_7422_Name = {
    Text = "ছোট্ট বায়ুঘণ্টা"
  },
  Event_7423_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7423_Desc = {
    Text = "\"মন্দ না, তুমি বেশ সতর্ক।\"\nহঠাৎ, বাতাসে দুলতে থাকা ঘণ্টাধ্বনি থেকে এক সুদূরের কণ্ঠস্বর ভেসে এল।\n\"সতর্কতা তোমাকে সামান্য পুরস্কার দেবে, কিন্তু তার বেশি কিছু নয়।\""
  },
  Event_7423_Name = {
    Text = "ছোট্ট বায়ুঘণ্টা"
  },
  Event_74245_ChoiceDesc1 = {
    Text = "[Leave] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_74245_Desc = {
    Text = "খটখট, পাশাগুলো কাপের ভেতর উন্মত্ত নাচে মেতে ওঠে, নাচতে নাচতে ক্লান্ত হয়ে পড়ে।\n\n“তুমি হেরেছো। তবে, আমাকে বিনোদিত রাখার পুরস্কার হিসেবে, তুমি এখনো একখানা পুরস্কার পেতে পারো।”"
  },
  Event_74245_Name = {
    Text = "N-এর বার্তা"
  },
  Event_74246_ChoiceDesc1 = {
    Text = "[Shut the Gate] একটি এলোমেলো কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg2)」 উৎকীর্ণ করো, কিন্তু 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_74246_ChoiceDesc2 = {
    Text = "[Flee in Panic] একটি এলোমেলো কমান্ড কার্ডের উপর 「(EnchantConfig.Arg2)」 নামের Orison খোদাই করুন, তবে 「(Skill.Arg1)」 বিকশিত হবে।"
  },
  Event_74246_ChoiceDesc3 = {
    Text = "[Ignore] একটি এলোমেলো কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_74246_Desc = {
    Text = "তুমি গভীরভাবে আটকে পড়েছ বাষ্প আর গিয়ারের তৈরি এক গোলকধাঁধায়, মাথার ওপর পিতলের পাইপগুলো মাকড়সার জালের মতো বেঁকে গেছে। প্রতিটি শ্বাসে দুলে ওঠে ঘন মেশিন তেলের কুয়াশা।\nদেয়ালে লাগানো নিয়ন্ত্রণহীন যান্ত্রিক ডায়ালগুলো খিঁচুনি খেয়ে কাঁপে, তাদের সূচক স্কেলের গায়ে ঘষা খেয়ে খেয়ে ছিটেফোঁটা স্ফুলিঙ্গ ছড়ায়, যেন কোনো ভিক্টোরিয়ান পরীক্ষাগারে মৃত্যুপথযাত্রী জোনাকির শেষ আলো। রিভেটের ফাঁক দিয়ে গলে পড়া তামাটে মরিচা যেন এই ইস্পাত দৈত্যের পচে যাওয়া ক্ষত, আর তোমার পকেট ঘড়ি বহু আগেই থেমে গেছে— এখানে সময় কেবল পরস্পর জড়িয়ে থাকা গিয়ারগুলোর প্রার্থনা।"
  },
  Event_74246_Name = {
    Text = "বাষ্প গোলকধাঁধা"
  },
  Event_74247_ChoiceDesc1 = {
    Text = "[Take a Gamble] 「(Skill.Arg1)」 বিকশিত করো এবং ভাগ্যকে পরীক্ষা করো"
  },
  Event_74247_ChoiceDesc2 = {
    Text = "[Forget It] 25টি কালো চিহ্ন সংগ্রহ করো"
  },
  Event_74247_Desc = {
    Text = "রাস্তার কোণে গভীর কালো কুয়াশার মধ্যে, শ্বাসরোধকারী এক আভা চারদিকে ছড়িয়ে পড়ে।\nকুয়াশার মাঝে, দুটি প্রাচীন ও শীতল পাশা নীরবে ভেসে ওঠে, তাদের পৃষ্ঠ জুড়ে অপাঠ্য প্রতীক ও বিচিত্র নকশায় ভরা।\nসেগুলো স্যাঁতসেঁতে পাথরের চাতালে নিশ্চুপ পড়ে আছে, যেন কোনো অজানা আহ্বানের অপেক্ষায়।\n「তুমি জানো আমি কে। একটু জুয়া খেলবে নাকি?」"
  },
  Event_74247_Name = {
    Text = "N-এর বার্তা"
  },
  Event_74248_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74248_Desc = {
    Text = "\"আমি স্বপ্ন দেখেছি এক মহাবিপর্যয়ের, যা সবকিছু ভাসিয়ে নিয়ে যায়, অতীতের জ্যোতিকে ডুবিয়ে দেয়। জীবনের প্রতি আমার মনে জমেছে ক্রোধ, আর আশাহীন ভবিষ্যৎকে ঘিরে অসহায়তা। ভয়ে আমার আত্মা ছিন্নভিন্ন হয়ে যাচ্ছে; এই আসন্ন ধ্বংসের প্রান্তে দাঁড়িয়ে, তুমি যেন সতর্ক থাকো এবং এই ভয়াবহ পরিণতি আগমনের আগেই রুখে দাও।\""
  },
  Event_74248_Name = {
    Text = "অন্তিম বাণীর প্রলাপ"
  },
  Event_74249_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74249_Desc = {
    Text = "কালো ধোঁয়া হতাশায় কেঁপে ওঠে。\nতারপর চোখের পলকে পাশাগুলো মিলিয়ে যায়。\n\nতোমার মনে শুধু একটাই জিজ্ঞাসা ভেসে থাকে:\nএই পাশাগুলো আসলে কী দিয়ে তৈরি?"
  },
  Event_74249_Name = {
    Text = "N-এর বার্তা"
  },
  Event_7424_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7424_Desc = {
    Text = "\"আপনি ঘুরে দাঁড়িয়ে দেখেন এক জোড়া চামড়ার জুতো, তার সঙ্গে ঝাপসা এক মানব-প্রতিচ্ছবি।\nদেখতে এক তরুণ ভদ্রলোকের মতো লাগে।\n“দুঃখিত বিরক্ত করলাম, আপনি কি কালো অক্সফোর্ড জুতোর এক জোড়া দেখেছেন?”\n“আপনার সামনে তো এক জোড়া আছে।”\n“না, না... এগুলো ছাগলের চামড়ার নয়, গরুর চামড়ার।\nআমি এই মোম জাদুঘরে বারো বছর ধরে আটকা—এগুলো নিশ্চয়ই ভুল জুতো...”\nকণ্ঠস্বর বিড়বিড় করতে করতে ধীরে ধীরে মিলিয়ে যায়।\""
  },
  Event_7424_Name = {
    Text = "পদধ্বনি"
  },
  Event_74250_ChoiceDesc1 = {
    Text = "[Discern Man's Voice] তিনটি কমান্ড কার্ডের মধ্যে 1টি অনুলিপি করো"
  },
  Event_74250_ChoiceDesc2 = {
    Text = "[নারীর কণ্ঠস্বর চেনো]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，「(Skill.Arg2)」সংক্রমিত করো"
  },
  Event_74250_ChoiceDesc3 = {
    Text = "[Discern the Elder's Voice] 25টি কালো চিহ্ন প্রাপ্ত হও।"
  },
  Event_74250_Desc = {
    Text = "তুমি একা একটি অন্ধকার জলাভূমিতে দাঁড়িয়ে আছ।\nঅস্পষ্টভাবে তুমি শুনতে পাচ্ছ বিশৃঙ্খল প্রলাপের ঢেউ তোমার দিকে ধেয়ে আসছে—কিছু আসছে অশীতিপর বৃদ্ধদের কাছ থেকে, কিছু আসছে সবে কথা বলতে শেখা শিশুদের কাছ থেকে, কিছু আসছে উদ্বিগ্ন নারীদের কাছ থেকে, আর কিছু আসছে অজানা ভয়ে ভীত পুরুষদের কাছ থেকে……"
  },
  Event_74250_Name = {
    Text = "অন্তিম বাণীর প্রলাপ"
  },
  Event_74251_ChoiceDesc1 = {
    Text = "[Advance] 3টি কমান্ড কার্ডের মধ্যে 1টি ধ্বংস করো, এবং 75টি কালো চিহ্ন প্রাপ্ত হও।"
  },
  Event_74251_ChoiceDesc2 = {
    Text = "[Rest] 3টি কমান্ড কার্ডের মধ্যে 1টি অনুলিপি করো, এবং 25টি কালো চিহ্ন প্রাপ্ত হও।"
  },
  Event_74251_ChoiceDesc3 = {
    Text = "[Look Back] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_74251_Desc = {
    Text = "তুমি জনশূন্য রাস্তায় হাঁটো, প্রতিটি পদক্ষেপে ছাইয়ের ভেতর গভীর ছাপ রেখে যাও।\n\nশহরের রাস্তা মাকড়সার জালের মতো, আর তুমি সেই জালে জড়িয়ে পড়া এক পতঙ্গ।"
  },
  Event_74251_Name = {
    Text = "বিষণ্ণ নগরী"
  },
  Event_74252_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74252_Desc = {
    Text = "বাষ্পদ্বারটি গর্জনে বন্ধ হয়ে যাওয়ার মুহূর্তে, তুমি শুনলে জড়ানো গিয়ারের ফাঁকে ফাঁকে ইঞ্চি ইঞ্চি করে তোমার ছায়া খসে পড়ছে।"
  },
  Event_74252_Name = {
    Text = "বাষ্প গোলকধাঁধা"
  },
  Event_74253_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74253_Desc = {
    Text = "একই দৃশ্য বারবার চোখের সামনে রিফ্রেশ হতে থাকে, আর তোমার পালানোর কোনো পথ নেই।"
  },
  Event_74253_Name = {
    Text = "বাষ্প গোলকধাঁধা"
  },
  Event_74254_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74254_Desc = {
    Text = "সময় এক অর্থহীন স্থানাঙ্ক; কেবল সত্যই তোমার আকাঙ্ক্ষা।"
  },
  Event_74254_Name = {
    Text = "বাষ্প গোলকধাঁধা"
  },
  Event_74255_ChoiceDesc1 = {
    Text = "[Three Points]"
  },
  Event_74255_ChoiceDesc2 = {
    Text = "[Six Points]"
  },
  Event_74255_ChoiceDesc3 = {
    Text = "[One Point]"
  },
  Event_74255_Desc = {
    Text = "কে এই দুর্ভাগ্য ও উন্মাদনার পাশা ছুড়তে সাহস করবে?\nতুমি, অবশ্যই তুমি।\nতুমি বেছে নাও——"
  },
  Event_74255_Name = {
    Text = "N-এর বার্তা"
  },
  Event_74256_ChoiceDesc1 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_74256_Desc = {
    Text = "খটখট, পাশাগুলো কাপের ভেতর উন্মত্ত নাচে মেতে ওঠে, নাচতে নাচতে ক্লান্ত হয়ে পড়ে।\n\n“তুমি হেরেছো। তবে, আমাকে বিনোদিত রাখার পুরস্কার হিসেবে, তুমি এখনো একখানা পুরস্কার পেতে পারো।”"
  },
  Event_74256_Name = {
    Text = "N-এর বার্তা"
  },
  Event_74257_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74257_Desc = {
    Text = "পেছনের পথ অন্তহীন অন্ধকার আর বিস্তীর্ণ বিশৃঙ্খলায় ভরা।\nনিজের ভাগ্য নিয়ে ভাবার সময় নেই, তোমাকে অবশ্যই ভয়কে দূর করতে হবে এবং চূড়ান্ত রায় ঘোষণার আগেই নিজের গন্তব্যে পৌঁছাতে হবে।"
  },
  Event_74257_Name = {
    Text = "বিষণ্ণ নগরী"
  },
  Event_74258_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74258_Desc = {
    Text = "「বছরের ছায়ায় বসে, মৃত্যুর বরফশীতল হাতকে ধীরে ধীরে কাছে আসতে অনুভব করি, বাইরের পৃথিবী ক্রমেই ম্লান হয়ে যায়, ভরে ওঠে বিপর্যয়ের হুইসপার-এ। আমাদের বোকামির বিচারের দিন, সেই আসন্ন বিচারকে আমি ভয় পাই। রাস্তাগুলো প্রতাপময় এক আভায় আচ্ছন্ন; আমি শঙ্কিত, আমাদের বিচার দিবস দ্রুত এগিয়ে আসছে। আমাদের সভ্যতা প্রান্তসীমায় টলছে, যেন ধ্বংসের দ্বারা গ্রাস হওয়ার উপক্রম, নিজেদেরই নির্বোধ অহংকারে বন্দি হয়ে।」"
  },
  Event_74258_Name = {
    Text = "অন্তিম বাণীর প্রলাপ"
  },
  Event_74259_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74259_Desc = {
    Text = "মৃত্যুর মুখ থেকে ফিরে আসাই কম কথা নয়, তুমি আর বেশি কিছু আশা করতে পারো না।\nভাঙা দেয়াল, ধ্বসে পড়া স্তম্ভ আর ধ্বংসাবশেষের ছায়া এখনও তোমাকে ডাকছে।"
  },
  Event_74259_Name = {
    Text = "বিষণ্ণ নগরী"
  },
  Event_7425_ChoiceDesc1 = {
    Text = "[Leave] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_7425_Desc = {
    Text = "「তাই নাকি... বেশ মজার।」\nসে প্রশ্নপত্রটা গুটিয়ে রেখে তোমাকে দেখায় বালকেরা যে দিকে চলে গিয়েছিল। তুমি তাড়াহুড়ো করে সেদিকে পা বাড়াও, প্রায়ই পেছনের হুইসপারটা কানে না এসে থেকে যায়।\n「আবার যখন আমাদের দেখা হবে, তার অপেক্ষায় থাকলাম।」"
  },
  Event_7425_Name = {
    Text = "মানসিক মূল্যায়ন"
  },
  Event_74260_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74260_Desc = {
    Text = "তুমি কোনো এক বিশাল শক্তি বা প্রবল নিয়তির অধীনে রয়েছ।\nক্ষণিকের বিশ্রাম এই পরিস্থিতি বদলাতে পারবে না, তবে অন্তত ক্লান্ত পায়ে এগিয়ে যাওয়ার প্রেরণা দিতে পারবে।"
  },
  Event_74260_Name = {
    Text = "বিষণ্ণ নগরী"
  },
  Event_74261_ChoiceDesc1 = {Text = "[Leave]"},
  Event_74261_Desc = {
    Text = "\"...এই শহর আর উষ্ণ আশ্রয় নয়, বরং গোপন কবর, যেখানে স্নেহে লালিত হয় আতঙ্ক আর হতাশা। যে স্বপ্নগুলো একসময় ছিল রঙিন, এখন সেগুলোই ভয়ের টুকরো টুকরো খণ্ড। আমি আর নির্ভীকতার ভান করতে পারি না; আমার সামনে বিস্তৃত জগৎটা যেন এক দুঃস্বপ্ন, যেখান থেকে কোনোভাবেই জাগরণ সম্ভব নয়।\""
  },
  Event_74261_Name = {
    Text = "অন্তিম বাণীর প্রলাপ"
  },
  Event_74262_ChoiceDesc1 = {
    Text = "[Leave] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_74262_Desc = {
    Text = "খটখট, পাশাগুলো কাপের ভেতর উন্মত্ত নাচে মেতে ওঠে, নাচতে নাচতে ক্লান্ত হয়ে পড়ে।\n\n“তুমি হেরেছো। তবে, আমাকে বিনোদিত রাখার পুরস্কার হিসেবে, তুমি এখনো একখানা পুরস্কার পেতে পারো।”"
  },
  Event_74262_Name = {
    Text = "N-এর বার্তা"
  },
  Event_7426_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「প্রতিবিম্ব」 একটি এলোমেলো কমান্ড কার্ডে খোদাই করো।"
  },
  Event_7426_Desc = {
    Text = "「কোনো সমস্যা নেই, আমি ইতিমধ্যেই তোমার চোখে উত্তর দেখে ফেলেছি। আমার কিছু কাজ আছে, তাই আপাতত বিদায় নিচ্ছি। তোমারও তো কিছু করার আছে, তাই না? দেখো, কেউ তোমার দিকে আসছে।」\nতুমি ঘুরে দাঁড়াও, আর আলোবাহকদের গির্জা থেকে আসা এক অবয়বকে রাস্তার শেষ প্রান্তে দেখতে পাও।"
  },
  Event_7426_Name = {
    Text = "অদ্ভুত সঙ্গী V"
  },
  Event_7427_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「গণনা」 একটি এলোমেলো কমান্ড কার্ডে খোদাই করো।"
  },
  Event_7427_Desc = {
    Text = "「দেখছি তুমি আমার কাছে নিজেকে খুলে দিতে রাজি নও। আমি হতাশ, কিন্তু তাতে কিছু যায় আসে না। তবু তোমাকে একটুখানি সদয় ইঙ্গিত দেব: আলোবাহকদের চার্চ এখানে কী খুঁজছে?」\n「ওহ, মনে হচ্ছে কেউ আমাদের আড্ডা পছন্দ করছে না। ওদিকে তাকাও—কেউ তোমার দিকে আসছে।」\nতুমি ঘুরে দাঁড়াও, আর রাস্তার শেষ প্রান্তে আলোবাহকের ভক্তদের অবয়ব স্পষ্ট হয়ে ওঠে।"
  },
  Event_7427_Name = {
    Text = "অদ্ভুত সঙ্গী V"
  },
  Event_7428_ChoiceDesc1 = {
    Text = "[Leave] এলোমেলো একটি কমান্ড কার্ডে 「Insight」 প্রার্থনাটি খোদাই করো।"
  },
  Event_7428_Desc = {
    Text = "「তুমি সৎ, আর তার একটা পুরস্কার প্রাপ্য। তাই, একটা ইঙ্গিত দিই: রাই টাউনে পৌঁছেই সে কেন তোমাকেই লক্ষ্য করল?」\n「উফ, মনে হচ্ছে কেউ আমাদের আড্ডা পছন্দ করছে না। দেখো, কেউ তোমার দিকে আসছে।」\nতুমি ঘুরে তাকিয়ে রাস্তার শেষে আলোবাহকের ভক্তদের দেখতে পাও।"
  },
  Event_7428_Name = {
    Text = "অদ্ভুত সঙ্গী V"
  },
  Event_7429_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7429_Desc = {
    Text = "অরাজক শব্দ ধীরে ধীরে মিলিয়ে যায়, তোমার হাত ফাঁকা, কিন্তু ক্ষণস্থায়ী অনুভূতিগুলো ইতোমধ্যেই রৌপ্য চাবি দ্বারা লিপিবদ্ধ হয়েছে।"
  },
  Event_7429_Name = {
    Text = "শূন্যের গ্রন্থ"
  },
  Event_7430_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7430_Desc = {
    Text = "তুমি বিশৃঙ্খলার ভেতর হাত বাড়িয়ে দাও, অদ্ভুত গঠনের কোনো কিছুকে আঁকড়ে ধরো, যা ধীরে ধীরে তোমার হাতে আকার নিতে থাকে।"
  },
  Event_7430_Name = {
    Text = "শূন্যের গ্রন্থ"
  },
  Event_7431_ChoiceDesc1 = {
    Text = "[চলে যাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_7431_Desc = {
    Text = "\"তুমি কি সাপের শিকার করার কৌশলের কথা শুনেছ? সাপ শুধু মাটিতে গড়িয়ে আর পেঁচিয়ে চলতে পারে, তাই তারা চিতার মতো হঠাৎ বিস্ফোরণ-গতিতে শিকার তাড়া করতে পারে না, নেকড়ের পালের মতো ঘিরেও ফেলতে পারে না। বদলে, সাপ শিখেছে অপেক্ষা করতে।\"\n\"তারা অপেক্ষা করে সেই মুহূর্তের জন্য, যখন শিকার তার প্রহরা নামিয়ে রাখে, তারপর হঠাৎ স্ট্রাইক করে, এক কামড়ে তাকে গিলে ফেলে।\""
  },
  Event_7431_Name = {
    Text = "অদ্ভুত সঙ্গী III"
  },
  Event_7432_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7432_Desc = {
    Text = "আতঙ্কিত হয়ে, কালো বিড়ালের চকচকে লোম তোমার আঙুলের ডগায় দগদগে অনুভূতি রেখে যায়, তারপর কুয়াশার গভীরে মিলিয়ে যায়।"
  },
  Event_7432_Name = {
    Text = "রাতের বিড়ালের অভিশাপ"
  },
  Event_7433_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7433_Desc = {
    Text = "ওগুলো কেবল উন্মাদনার সেই মূর্খ বিশ্বাসীদের অযৌক্তিক স্বপ্নমাত্র।"
  },
  Event_7433_Name = {
    Text = "সাইফার-এডিক্ট·পর্ব II"
  },
  Event_7434_ChoiceDesc1 = {
    Text = "[Keep Eavesdropping] 3টি প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_7434_ChoiceDesc2 = {
    Text = "[Cough Loudly] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে যেকোনো একটিতে খোদাই করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7434_Desc = {
    Text = "\nদেয়ালের কোণায় সূক্ষ্ম সব ফাটল ধরে খুলে গেল, রক্তনালির মতো পেঁচিয়ে পেঁচিয়ে দূরে ছড়িয়ে পড়ল।\nমৃদু গুঞ্জনধ্বনির সঙ্গে, তুমি ওপার থেকে ভেসে আসা এক পুরুষের গভীর কণ্ঠস্বর শুনতে পাও।\n「কোয়েন্টিন জেলা 5, ওয়েলিংটন জেলা 10, নরম্যান জেলা 15...\nএই মাসের সব উপকরণ লোড সম্পন্ন, প্রেরণের জন্য প্রস্তুত, কার্গো নম্বর I-0234...\n.....\nআরও, মিথাগের ওই লোকগুলোর কল্যাণে, হোয়াইটচ্যাপেল জেলা বর্তমানে সামরিক শাসনের অধীনে, আর আমরা আমাদের সবচেয়ে বড় উপকরণ-উৎস হারিয়েছি।」"
  },
  Event_7434_Name = {
    Text = "গোপন শ্রোতা"
  },
  Event_7435_ChoiceDesc1 = {
    Text = "[Chase the Crows] 20টি কালো চিহ্ন গ্রহণ করো, তবে 「(Skill.Arg2)」 বিকাশ করো।"
  },
  Event_7435_ChoiceDesc2 = {
    Text = "[Continue chasing the child] প্রস্থান করুন"
  },
  Event_7435_Desc = {
    Text = "তোমার আতঙ্কে সব কাক হুড়মুড় করে চারদিকে উড়ে গেল, তাদের ঝরে পড়া কালো পালক পচা কাদায় গলে গিয়ে টপটপ করে ঝরতে ঝরতে কালো চিহ্নের আকৃতি নিল।"
  },
  Event_7435_Name = {
    Text = "কালো কাকের দৃষ্টি"
  },
  Event_7436_ChoiceDesc1 = {
    Text = "[Give Up Resistance] একটি কমান্ড কার্ড ধ্বংস করো, এবং Arg1 কালো চিহ্ন গ্রহণ করো।"
  },
  Event_7436_ChoiceDesc2 = {
    Text = "[Pull Back Hands]"
  },
  Event_7436_Desc = {
    Text = "একটি নতুন টাইপরাইটার।\nএর কী-গুলো অদ্ভুত, যেন অণুবীক্ষণ যন্ত্রের মতো সূক্ষ্ম ও মার্জিত।\nকৌতূহলবশত তুমি হাত রাখো তার ওপর, আর সঙ্গে সঙ্গেই দেখো, তোমার আঙুলগুলো নিয়ন্ত্রণহীনভাবে কীবোর্ডের ওপর উড়ে বেড়াচ্ছে, ক্রমেই দ্রুততর, আরও দ্রুততর..."
  },
  Event_7436_Name = {
    Text = "অনুপ্রেরণার বিস্ফোরণ"
  },
  Event_7437_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7437_Desc = {
    Text = "শুধু এক টলমল প্রাণী, যে বিশ্রামের জন্য ভরসা করার মতো এক টুকরো ভাসমান কাঠ খুঁজছে...\nতুমি দীর্ঘশ্বাস ফেলো, আর প্রজাপতির লেজ থেকে ঝরে পড়া কালো তরল তোমার গালে টুপটাপ পড়ে।"
  },
  Event_7437_Name = {
    Text = "অবসিডিয়ান প্রজাপতি"
  },
  Event_7438_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7438_Desc = {
    Text = "তুমি স্কুল থেকে আসা যোগাযোগ অনুরোধটি গ্রহণ করেছ। পরিচিত কণ্ঠস্বর তোমার মনকে শান্ত করে। তুমি মনোবল সঞ্চয় করে সামনে এগিয়ে যাও।"
  },
  Event_7438_Name = {
    Text = "সংযোগস্থল"
  },
  Event_7439_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7439_Desc = {
    Text = "তুমি স্কুল থেকে আসা যোগাযোগ অনুরোধটি গ্রহণ করেছ। পরিচিত কণ্ঠস্বর তোমার মনকে শান্ত করে। তুমি মনোবল সঞ্চয় করে সামনে এগিয়ে যাও।"
  },
  Event_7439_Name = {
    Text = "সংযোগস্থল"
  },
  Event_7440_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7440_Desc = {
    Text = "তোমার সংশয়গুলো বাতাসে ঝুলে থাকে, উত্তরহীন। জানালা ভেদ করে উষ্ণ হলুদ আলো ঢুকে পড়ে, স্মৃতিচারণের মতোই সান্ত্বনাদায়ক।"
  },
  Event_7440_Name = {
    Text = "আগ্নেয়গিরির স্মৃতি"
  },
  Event_7441_ChoiceDesc1 = {
    Text = "[Pick Up] রৌপ্য রেলিক 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7441_ChoiceDesc2 = {
    Text = "[Hesitate] 25টি কালো চিহ্ন গ্রহণ করুন"
  },
  Event_7441_Desc = {
    Text = "গলির কোণের কাঠের পিপেতে এক অদ্ভুত রঙের বস্তু ভাসছে। তার অস্বাভাবিক চেহারা যেন সতর্ক করে দিচ্ছে, “স্পর্শ কোরো না”।"
  },
  Event_7441_Name = {
    Text = "পিপার ভাসমান বস্তু"
  },
  Event_7442_ChoiceDesc1 = {
    Text = "[Leave It to Her] 3টি রৌপ্য সৃষ্টির মধ্যে থেকে 1টি অর্জন করো"
  },
  Event_7442_ChoiceDesc2 = {
    Text = "[Interesting Situation] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)「 ও 「(RelicConfig.Arg2)「 অর্জন করো, তবে 「(Skill.Arg3)「 দু」বার বিকশিত করো।"
  },
  Event_7442_Desc = {
    Text = "「এটি মিথ্যাগ থেকে প্রেরিত যোগাযোগ। আমি এরিকা। জাগরণকারী লোটানের গ্নোসিস সূচকে অস্বাভাবিক ওঠানামা সনাক্ত হয়েছে। আপনার কি সহায়তা প্রয়োজন?」"
  },
  Event_7442_Name = {
    Text = "সহায়তা যোগাযোগ"
  },
  Event_7443_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7443_Desc = {
    Text = "তুমি কানের কাছে অশুভ সান্ত্বনার কথায় কান দিলে, সুচের মতো তীক্ষ্ণ চিৎকার মোচড় দিয়ে তোমার কানে বিঁধে গেল।\n「থামো——এখনই থামো——আমি তো তোমার কথামতোই করেছি——থামো——」\nতুমি যন্ত্রণায় মাথা চেপে ধরলে, ঘোরের মধ্যে কাকের দলের উপহাসের শব্দ শুনতে পেলে।"
  },
  Event_7443_Name = {
    Text = "কাকঝাঁকের গান"
  },
  Event_7444_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7444_Desc = {
    Text = "এখানে রাখা এই বস্তুটির দুটি সম্ভাবনা আছে: হয় অবহেলিত, নয়তো অতি সযত্নে লালিত। যদি দ্বিতীয়টি সত্যি হয়, তবে সেটি তার মালিকের কাছেই থাকা ভালো।"
  },
  Event_7444_Name = {
    Text = "নিঃসঙ্গ সিলভার কোর"
  },
  Event_7445_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7445_Desc = {
    Text = "অজ্ঞরাই সবচেয়ে সুখী।"
  },
  Event_7445_Name = {
    Text = "আড়চোখে তাকাও"
  },
  Event_7446_ChoiceDesc1 = {
    Text = "[Spawn Normal Monster]"
  },
  Event_7446_ChoiceDesc2 = {
    Text = "[Spawn Blank Tile]"
  },
  Event_7446_ChoiceDesc3 = {
    Text = "[Spawn Void]"
  },
  Event_7446_Desc = {
    Text = "দেখা যাক কী সৃষ্টি করা যায়।"
  },
  Event_7446_Name = {
    Text = "[To Be Packaged]"
  },
  Event_7447_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7447_Desc = {
    Text = "\"শান্ত হও,\" রামোনা আপনার মাথায় টোকা দেয়, \"এগুলো শুধু অতীতের খণ্ডাংশ। কে যে এগুলো এই মাত্রিক পথের ভেতর ফেলে গেছে, জানি না।\"\nনিশ্চয়ই, বাতাসে এক নস্টালজিক গন্ধ ভাসছে।"
  },
  Event_7447_Name = {
    Text = "স্মৃতির খণ্ডাংশ: হুইস্কি"
  },
  Event_7448_ChoiceDesc1 = {
    Text = "[Collect] একটি রৌপ্য রেলিককে সোনার রেলিক 「(RelicConfig.Arg1)」-এ উন্নীত করো।"
  },
  Event_7448_ChoiceDesc2 = {
    Text = "[Throw Them Away] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 এবং 「(Skill.Arg3)」 বিকশিত হবে।"
  },
  Event_7448_ChoiceDesc3 = {
    Text = "[Observe Carefully] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7448_Desc = {
    Text = "এখানে অনেক ভাঙাচোরা সিলভার আছে।\nনিস্তেজ, ভগ্ন... স্পষ্টতই উচ্চমানের পণ্যসামগ্রী নয়।\nহয়তো এদেরই কোনো অংশের কারণে এই মোম ভাস্কর্য দল 「জীবন্ত」 হতে পারে।\nসবচেয়ে খসখসে সিলভারও অলৌকিক ঘটনা সৃষ্টি করার সম্ভাবনা বহন করে।"
  },
  Event_7448_Name = {
    Text = "বন্দী আত্মা"
  },
  Event_7449_ChoiceDesc1 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7449_Desc = {
    Text = "কৌম তার সাধ্যের সবকিছুই দিয়েছে।\nএখন, তার উৎসর্গ যেন বৃথা না যায়, তা নিশ্চিত করার পালা তোমার।"
  },
  Event_7449_Name = {
    Text = "অবশিষ্ট উষ্ণতা"
  },
  Event_7450_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7450_Desc = {
    Text = "হাওয়া আর তুষার তোমাকে দিক চিরস্থায়ী নীরব প্রশান্তি।"
  },
  Event_7450_Name = {
    Text = "প্রাচীন উত্তরাধিকার"
  },
  Event_7451_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7451_Desc = {
    Text = "তুমি অবিচল থাকো, মন্ত্রোচ্চারণ করতে করতে নিজের সত্তার প্রতি সৎ থাকো।\nতুমি কানে ভেসে আসা হুইসপার-গুলোর ওপর ভরসা করো না, নির্ভর করো কেবল মানবীয় যুক্তির ওপর।\nতবু... যখন তোমার ভরসার দৃঢ় মাটি ঘন কালো কাদায় গ্রাস হয়ে যাবে, তখন শেষ মুহূর্তে পর্যবেক্ষণ-এর যন্ত্র হিসেবে ব্যবহার করার জন্য নিজের চোখ উপড়ে নেওয়াই হবে তোমার একমাত্র নির্বাচন।"
  },
  Event_7451_Name = {
    Text = "কাকঝাঁকের গান"
  },
  Event_7452_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7452_Desc = {
    Text = "তুমি টেনে সরিয়ে নেওয়ায় কৌম অল্পের জন্য আঘাত এড়াল। সে কৃতজ্ঞতায় তোমার দিকে মাথা নেড়ে আবারও পরীক্ষামূলক জীবটির দিকে ঝাঁপিয়ে পড়ল।"
  },
  Event_7452_Name = {
    Text = "অ্যারেনা"
  },
  Event_7453_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7453_Desc = {
    Text = "টিং টিং...\nমুদ্রা ঝনঝন করে মানিব্যাগে পড়ে, কানে লাগে খাস্তা, মনোহর শব্দ।\nমানিব্যাগ তৃপ্তি ভরে চিবোয়, তারপর এক ঢেঁকুর তোলে।\nতোমার উদারতায় আপ্লুত হয়ে, সে সম্পূর্ণভাবে তার সতর্কতা নামিয়ে রাখে।\nএখন, সে তোমার আদেশের অপেক্ষায়।"
  },
  Event_7453_Name = {
    Text = "পেটুক থলি"
  },
  Event_7454_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7454_Desc = {
    Text = "একটি পিতলের মুদ্রা তলহীন অতল গহ্বরে পড়ে গেল, কোনো শব্দ হলো না।\nতুমি ধৈর্য ধরে পাঁচ মিনিট অপেক্ষা করলে। মানিব্যাগটি যন্ত্রণায় গোঙাতে গোঙাতে শেষে এক পুকুর কালো আঁশটে তরল উগরে দিল।\nএটাই ছিল তার নীরব প্রতিবাদ"
  },
  Event_7454_Name = {
    Text = "পেটুক থলি"
  },
  Event_7455_ChoiceDesc1 = {
    Text = "[Look into the Distance]"
  },
  Event_7455_ChoiceDesc2 = {
    Text = "[Listen Carefully]"
  },
  Event_7455_Desc = {
    Text = "সেলেস্ট হাতে ধরা কম্পাসটা ঝাঁকায়। সে কিছু বলে না, তবু তার চারপাশে ক্ষীণ এক গান প্রতিধ্বনিত হয়।\nএখানে নাবিকদের গান সময়ের সীমানা পেরিয়ে গিয়ে একে অপরের সঙ্গে জড়িয়ে যায়, বিশৃঙ্খল অথচ প্রবল এক শ্যান্টি তোমাদের পথ দেখায়, আর তোমার দৃষ্টি টেনে নিয়ে যায় জাহাজের অপর প্রান্তে।"
  },
  Event_7455_Name = {
    Text = "নাবিকদের গান"
  },
  Event_7456_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7456_Desc = {
    Text = "তুমি ভেতরে ঢুকে ছোট্ট অনুশীলন সেশনটাকে থামিয়ে দাও।\nআঙুলের ভঙ্গি থেকে শুরু করে প্রাথমিক সঙ্গীত তত্ত্ব পর্যন্ত, তুমি নির্মমভাবে প্রতিটি খুঁটিনাটি সমালোচনা করো।\nসুর হঠাৎ থেমে যায়, আর ছেলেটা আর শিক্ষক দুজনেই একই রকম ভৌতিক হাসি নিয়ে তোমার দিকে ঘুরে তাকায়।\n১৩৩, ৩৫৫, ২৪৪...\nপিয়ানো আবার বেজে ওঠে, এখনও ভয়াবহভাবে বেসুরো।\nশেষমেশ বোঝা যায়, তারা কিছুই শুনতে পায় না।"
  },
  Event_7456_Name = {
    Text = "পিয়ানো পাঠ"
  },
  Event_7457_ChoiceDesc1 = {Text = "[Take It]"},
  Event_7457_Desc = {
    Text = "ডোমেইনে পাওয়া একটি কালো চিহ্নকে রেলিক বা অন্যান্য আধ্যাত্মিক প্রক্ষেপণের বিনিময়ে ডি-মার্কের কাছে উৎসর্গ করা যায়। বর্তমান এলাকা ত্যাগ করার পর অল্প সময়ের মধ্যেই এটি কালো কাদায় দ্রবীভূত হয়ে যাবে।"
  },
  Event_7457_Name = {
    Text = "কালো চিহ্ন"
  },
  Event_7458_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7458_Desc = {
    Text = "এই মুহূর্তে সেই রহস্যময় ব্যক্তিকে খুঁজে পাওয়াটাই বেশি জরুরি। এই ভাবনা নিয়ে, রামোনা দ্রুত সরে গেল।"
  },
  Event_7458_Name = {
    Text = "অপরের কান"
  },
  Event_7459_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7459_Desc = {
    Text = "চেতনায় লিপ্ত হয়ে, নীরব প্রার্থনার সলতের পথ ধরে ডুবে যাও গভীর সাগরে।\nতুমি দেখো তলিয়ে যাওয়া সোনালি দেশ, দেখো অমর পাথরের ভাস্কর্য, এবং শেষমেশ মুখোমুখি হও ছায়ার মিটমিট চোখের...\n「যারা এখনো দেবরক্ত ঝরায়নি... সরে যাও, সরে যাও।」"
  },
  Event_7459_Name = {
    Text = "স্বপ্নলোক প্রার্থনা"
  },
  Event_7460_ChoiceDesc1 = {
    Text = "[Leave] 3টি অভিশপ্ত নিদর্শনের মধ্যে 1টি অর্জন করো, তবে উপসর্গ 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7460_Desc = {
    Text = "রামোনা এক বিঁধে পরীক্ষামূলক দেহটির গলা ভেদ করল। কৌম নিথর দেহটিকে ছুড়ে ফেলে দিয়ে পরের লক্ষ্যবস্তুর দিকে ঝাঁপিয়ে পড়ল।"
  },
  Event_7460_Name = {
    Text = "অ্যারেনা"
  },
  Event_7461_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7461_Desc = {
    Text = "কাকটি নিজের পালক ছিঁড়ে খায়, যেমন মানুষ নিজের শরীরকেই কুরে কুরে খায়।\nভয়ের এই জগতে এমন দৃশ্য নিত্যনৈমিত্তিক। তুমি সব জীবকে রক্ষা করতে পারবে না।"
  },
  Event_7461_Name = {
    Text = "গলিত অশ্রু"
  },
  Event_7462_ChoiceDesc1 = {
    Text = "[Soothe Koum]"
  },
  Event_7462_ChoiceDesc2 = {
    Text = "[Shout for Koum]"
  },
  Event_7462_Desc = {
    Text = "বিশাল দানবটি ছোট্ট অবয়বটির দিকে মরিয়া হয়ে গর্জন করে, তার প্রাক্তন সঙ্গীদের জাগিয়ে তুলতে চায়। কিন্তু ক্ষতিগ্রস্ত স্বরযন্ত্র থেকে বেরোয় শুধু নিচু, অদ্ভুত গোঁ গোঁ শব্দ।"
  },
  Event_7462_Name = {
    Text = "বন্ধুত্বের আহ্বান"
  },
  Event_7463_ChoiceDesc1 = {
    Text = "[Leave] সার্চলাইট খুঁজুন"
  },
  Event_7463_ChoiceDesc2 = {
    Text = "[Break into Mist] Arg2 HP হারান"
  },
  Event_7463_Desc = {
    Text = "সামনে ঘন কালো কুয়াশা; হঠাৎ ঢুকে পড়া সর্বনাশ ডেকে আনবে।\nহয়তো তোমার উচিত কুয়াশা সরাতে একটি 「সার্চলাইট」 খুঁজে নেওয়া।"
  },
  Event_7463_Name = {Text = "???"},
  Event_7464_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7464_Desc = {
    Text = "「তোমার মতো কড়মড়ে চোয়াল? জীবনে এমন কিছু দেখিনি।」\nতুমি মিস্টার জ-হাড়ের অশোভন অনুরোধ প্রত্যাখ্যান করলে। মিস্টার জ-হাড় ভীষণ হতাশ হলেও কোনোভাবে তার স্থিরচিত্ততা বজায় রাখল।\nতোমার ধৈর্যশীল শ্রবণের জন্য কৃতজ্ঞতাস্বরূপ, সে তোমাকে একটি ছোট উপহার দিল।"
  },
  Event_7464_Name = {
    Text = "কড়মড় শব্দ"
  },
  Event_7465_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7465_Desc = {
    Text = "তুমি এই অদ্ভুত অনুরোধে সম্মতি জানালে এবং সঙ্গে করে নিয়ে এলে মিস্টার চোয়ালের হাড়কে।\nসে তোমার পকেটে বিশ্রাম নিচ্ছে, অবিরাম খটখট শব্দ তুলছে। তোমার সঙ্গীর অনুবাদ অনুযায়ী, তার কথার বেশিরভাগই কৃতজ্ঞতা, নস্টালজিয়া আর অনুতাপের বহিঃপ্রকাশ।\nসে কেন এমন পরিণতিতে পৌঁছাল—এই প্রশ্নে? মিস্টার চোয়ালের হাড় বিস্তারিত বলতে অনিচ্ছুক, শুধু এতটুকুই বলে:\n“তুমি জানো। যখন তুমি @2-এর দিকে তাকাও, @2-ও তোমার দিকে তাকিয়ে থাকে।”"
  },
  Event_7465_Name = {
    Text = "কড়মড় শব্দ"
  },
  Event_7466_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7466_Desc = {
    Text = "এটা যেন রেশমের টুকরোর মতো তোমার ব্যাগে গলে ঢুকে গেল, ওজনের সামান্য বৃদ্ধি প্রায় টেরই পাওয়া যায় না, যেন নরম স্বরে একটি ধন্যবাদ ফিসফিস করে গেল।\nতারপর সবকিছু নিস্তব্ধ হয়ে গেল।"
  },
  Event_7466_Name = {
    Text = "কেওসের আত্মা"
  },
  Event_7467_ChoiceDesc1 = {Text = "[Advance]"},
  Event_7467_Desc = {
    Text = "Click.\nতুমি চাবিটি তালায় প্রবেশ করিয়ে ধীরে ধীরে দ্বার উন্মুক্ত করো।\nসমগ্র প্রক্রিয়াটি নির্বিঘ্নে সম্পন্ন হয়, সামনে থাকা তদন্তের জন্য তোমার আত্মবিশ্বাস বাড়িয়ে তোলে।"
  },
  Event_7467_Name = {
    Text = "মরিচা ধরা দ্বার"
  },
  Event_7468_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7468_Desc = {
    Text = "সেই কণ্ঠস্বর গহীনভাবে খিলখিলিয়ে উঠল, আর তোমার পায়ের কাছে তরলের উপর ঢেউ খেলল।\n\"তুমি খুব শিগগিরই বুঝবে, মৃত্যুর মুখোমুখি হওয়া ছাড়া তোমার আর কিছুই করার নেই।\""
  },
  Event_7468_Name = {
    Text = "যা তোমার খোঁজা উচিত নয়"
  },
  Event_7469_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7469_Desc = {
    Text = "তুমি এই স্মৃতিটি বাতিল করো, ভ্রমময় স্বস্তি থেকে নিজের চেতনাকে টেনে বের করে আনো।"
  },
  Event_7469_Name = {
    Text = "অতীতের আলিঙ্গন"
  },
  Event_7470_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7470_Desc = {
    Text = "শুধু একটুখানি তন্দ্রা। সান্ত্বনা না থাকলে, কীভাবে তুমি এই অন্তহীন রাত সহ্য করবে...?"
  },
  Event_7470_Name = {
    Text = "অতীতের আলিঙ্গন"
  },
  Event_7471_ChoiceDesc1 = {
    Text = "[Pick up the Photo] 3টি কমান্ড কার্ডের মধ্যে 1টিতে 「(EnchantConfig.Arg1)」 নামের প্রার্থনা খোদাই করো।"
  },
  Event_7471_Desc = {
    Text = "এটা একটি দলগত ছবি।\nহতাশ মানুষরা লোহার শিকের আড়ালে গুটিয়ে বসে আছে, তাদের মুখ ভরা যন্ত্রণায়।\nএকটি ছবি তোমার চোখে পড়ে। সে এক কৃশকায় তরুণী, মুখে কোনো অভিব্যক্তি নেই।\nনিন্দিত অঙ্কুরোদ্গম তার দেহ জুড়ে জড়িয়ে আছে।\nতুমি তার মুখ দেখতে পাও না, তবু কল্পনা করো—তার মুখ নিশ্চয়ই অভিব্যক্তিহীন।"
  },
  Event_7471_Name = {
    Text = "হুবহু নথি"
  },
  Event_7472_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7472_Desc = {
    Text = "ওটা পাখির অবশিষ্ট দেহ।"
  },
  Event_7472_Name = {
    Text = "উন্মত্ত কাকের ঝাঁক"
  },
  Event_7473_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7473_Desc = {
    Text = "তুমি ঠান্ডাভাবে পিয়ানিস্টের অনুরোধ প্রত্যাখ্যান করলে।\nপিয়ানিস্ট সম্পূর্ণ ভেঙে পড়ল। সে নিজের অন্য কানটিও ছিঁড়ে ফেলে, দুটোই জানালা দিয়ে ছুড়ে দিল।\n\"আমার এগুলোর দরকারই নেই।\"\nবিষণ্ন পিয়ানিস্ট, গাল বেয়ে অশ্রু গড়াতে গড়াতে, একের পর এক শোকাতুর সুর বাজাতে লাগল।"
  },
  Event_7473_Name = {
    Text = "কান পেতে শোনো"
  },
  Event_7474_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7474_Desc = {
    Text = "কেওসের আত্মার আর্তনাদ ক্রমে আরও ধারালো হয়ে উঠল, শেষে তা চারদিক জুড়ে প্রতিধ্বনিত এক বিদারক চিৎকারে রূপ নিল।\nতোমার নিবেদিত কবিতা আর অনিবার্য শোকের ভারে, তা আবার কাদার অতলে ডুবে গেল।"
  },
  Event_7474_Name = {
    Text = "কেওসের আত্মা"
  },
  Event_7475_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7475_Desc = {
    Text = "এটি একটি একমুখী প্যাসেজ; এর মাধ্যমে তুমি প্রবেশদ্বারে ফিরে যেতে পারবে না।"
  },
  Event_7475_Name = {
    Text = "প্যাসেজ"
  },
  Event_7476_ChoiceDesc1 = {
    Text = "[Leave] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_7476_Desc = {
    Text = "“তাহলে, অনুগ্রহ করে চোখ বন্ধ করো, আর নীরবে অনুভব করো তার এগিয়ে আসা পদধ্বনি।”\nপরামর্শ মেনে তুমি চোখ বন্ধ করলে। মুহূর্তেই কানে ভেসে এলো অদ্ভুত জন্তুর কর্কশ শ্বাসপ্রশ্বাস।\nতুমি চমকে চোখ খুলতেই দেখো, আগের সেই মানুষটি ইতিমধ্যে উধাও।"
  },
  Event_7476_Name = {
    Text = "অদ্ভুত সঙ্গী I"
  },
  Event_7477_ChoiceDesc1 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7477_Desc = {
    Text = "\"তা সত্যিই দুঃখজনক।\"\nলোকটি চশমা ঠিক করে, নিচু স্বরে বলল।\n\"তবু, যদি আপনি এটার নামই না শুনে থাকেন, তবে এত রাতে এখানে এলেন কেন?\"\nকোনো উত্তর অপেক্ষা না করেই সে সরে দাঁড়াল।"
  },
  Event_7477_Name = {
    Text = "অদ্ভুত সঙ্গী I"
  },
  Event_7478_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7478_Desc = {
    Text = "তুমি দৃঢ়চেতা পদক্ষেপে সামনে এগিয়ে যাও。\nএক পা, দুই পা, তিন পা…\nতোমার পেছনের পদধ্বনি অন্ধকারের ভেতর মিলিয়ে যায়。\nতোমাদের আবার দেখা হবে।"
  },
  Event_7478_Name = {
    Text = "অক্সফোর্ডস"
  },
  Event_7479_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7479_Desc = {
    Text = "তুমি অর্ধেক ঝুঁকে সালাম দাও, পাশের টেবিল থেকে ট্রেটা তুলে নাও, আর মুহূর্তেই রূপ নাও রাজকুমারীর প্রহরীতে।\nসৌভাগ্যবতী রাজকুমারী হল কে—তা তো স্বাভাবিকভাবেই, তোমার সবচেয়ে অনুগত সঙ্গীই।\n\"আর একবার চা আমার মুখে ফেলে দিলে, পরের মাসের ক্লাস নোটের কথা ভুলেই যাও।\"\nওটাই তোমার প্রতি রাজকুমারীর সতর্কবার্তা।"
  },
  Event_7479_Name = {
    Text = "নিখুঁত ছদ্মবেশ"
  },
  Event_7480_ChoiceDesc1 = {
    Text = "[Listening Quietly] একটি এলোমেলো কার্ডের প্রার্থনাগাথা গুণমান উন্নত করো।"
  },
  Event_7480_ChoiceDesc2 = {
    Text = "[সেই সে]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমিত করুন「(Skill.Arg2)」"
  },
  Event_7480_Desc = {
    Text = "সারার আর্তচিৎকার তোমার মস্তিষ্কে প্রতিধ্বনিত হয়। কোথা থেকে যেন ক্ষীণ, পরিচিত কণ্ঠস্বর ভেসে আসে, দুর্বল স্বরে হুইসপার করে, 「সাশা দিদি」, 「সাশা দিদি।」\n「সাশা দিদি, তুমি কোথায়?」"
  },
  Event_7480_Name = {
    Text = "\"সাশা দিদি\""
  },
  Event_7481_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7481_Desc = {
    Text = "「...পুরোটাই মিথ্যে বলব না, তবু শুধু কামনা দিয়ে তোমার(ক্ষয়িত) সত্তার সমস্যা মিটবে না। চল, কিছু বাস্তব কাজ করি।」"
  },
  Event_7481_Name = {
    Text = "রোগসের নিয়ম"
  },
  Event_7482_ChoiceDesc1 = {
    Text = "[Tune] 100টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7482_ChoiceDesc2 = {
    Text = "[এলোমেলো 2টি কমান্ড কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg1)」]"
  },
  Event_7482_Desc = {
    Text = "স্থিতিশীল নসিস থেকে গঠিত রেলিক হয়তো একদিন বয়ে আনবে সুরেলা সুরধ্বনি।"
  },
  Event_7482_Name = {
    Text = "অসঙ্গতি"
  },
  Event_7483_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7483_Desc = {
    Text = "\"এটা এমন কারও স্মৃতিচারণের খণ্ডাংশ, যে এই মাত্রায় প্রবেশ করেছে,\" রামোনা জবাব দিল, \"মাত্রা পেরোতে গিয়ে এমন জিনিসের মুখোমুখি হওয়া খুবই সহজ। সাবধান, যেন নিজের স্মৃতিচারণের সঙ্গে গুলিয়ে না ফেলো।\""
  },
  Event_7483_Name = {
    Text = "স্মৃতির খণ্ডাংশ: হুইস্কি"
  },
  Event_7484_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7484_Desc = {
    Text = "হৃদস্পন্দনের ছন্দ অনুসরণ করো, আর গ্লিমারকে তাড়া করো। তোমরা বিচ্ছিন্ন হবে না, যেমন কেউই দিন আর রাতের সীমানা নিখুঁতভাবে আলাদা করতে পারে না।"
  },
  Event_7484_Name = {
    Text = "বাম অলিন্দ"
  },
  Event_7485_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7485_Desc = {
    Text = "তুমি সেই অস্থির হাতগুলোতে হাত বুলিয়ে যেতে থাকো, ওদের শান্ত করার চেষ্টা করো।\nঅল্প সময়েই তোমার জগৎ সম্পূর্ণ নীরব হয়ে যায়।\nভালোবাসা সবসময় নিজের পুরস্কার নিজেই বয়ে আনে।"
  },
  Event_7485_Name = {
    Text = "বিষণ্ণ জলাভূমি"
  },
  Event_7486_ChoiceDesc1 = {
    Text = "[Struggle] রৌপ্য সৃষ্টি 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকাশ করো।"
  },
  Event_7486_ChoiceDesc2 = {
    Text = "[Give Up] রৌপ্য সৃষ্টি 「(RelicConfig.Arg2)」 অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকাশ করো।"
  },
  Event_7486_ChoiceDesc3 = {
    Text = "[Be Wary] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7486_Desc = {
    Text = "তোমার মস্তিষ্ক নোংরায় প্লাবিত, এক স্পষ্ট পচনের অনুভূতি।\nঘোলা, দুর্গন্ধময় তরল ভেতরে ঢুকে পড়ে এবং সম্পূর্ণভাবে তোমার চিন্তাকে গ্রাস করে। যন্ত্রণার ঢেউ ভয়ে বিকৃত তোমার মুখজুড়ে ছড়িয়ে পড়ে, তুমি আটকে পড়ো দুঃস্বপ্নের চক্রের অন্তহীন ঘূর্ণিতে, যেখান থেকে মুক্তি পাওয়া অসম্ভব।"
  },
  Event_7486_Name = {
    Text = "করোটির ক্ষত"
  },
  Event_7487_ChoiceDesc1 = {
    Text = "[It's the Memphis Ritual Mirror]"
  },
  Event_7487_ChoiceDesc2 = {
    Text = "[It's a True North Compass]"
  },
  Event_7487_ChoiceDesc3 = {
    Text = "[I Haven't Dropped Anything]"
  },
  Event_7487_Desc = {
    Text = "「হে মাত্রা অতিক্রমের অগ্রদূত।」\n\nপ্রাচীন কণ্ঠস্বর প্রতিধ্বনিত হয় তোমার কানে, যেন প্রাগৈতিহাসিক যুগ থেকে, যুগ-যুগান্তর অতিক্রম করে এসেছে।\n\nচরম উত্তেজনার মধ্যে, তুমি শুনতে পাও সেই কণ্ঠস্বর এক অদ্ভুতভাবে পরিচিত জিজ্ঞাসা করছে।\n\n「এই টার্ন অবজেক্টটা কী, যা তুমি ফেলে দিয়েছ, আর যা তোমাকে টার্নের শুরুতে কার্ড ড্র করতে দেয়?」"
  },
  Event_7487_Name = {
    Text = "সীমানার ওপারের কণ্ঠস্বর"
  },
  Event_7488_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7488_Desc = {
    Text = "「এটা কোনো স্ক্র্যাপইয়ার্ড না, 」 ডল বিড়বিড় করে, তবু সেটা গ্রহণ করে, 「তবু ঠিক আছে, এর ভেতর থেকেও কিছু দরকারি জিনিস টেনে বের করতে পারব।」"
  },
  Event_7488_Name = {
    Text = "নেমপ্লেট"
  },
  Event_7489_ChoiceDesc1 = {
    Text = "দৈবচয়নকৃত সাধারণ প্রার্থনাগাথা"
  },
  Event_7490_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7490_Desc = {
    Text = "\nতুমি জীর্ণ, ছেঁড়া কাগজটি পড়লে: 「যমজ」, 「ভিজে যাও」, 「উৎসর্গ」, 「অকার্যকর」...\nখণ্ডিত ধারণা আর দুর্বোধ্য গদ্যের এক জটলা; কেবল ধুকপুক করা মস্তিষ্কই প্রমাণ দেয় যে তুমি এই কাগজের টুকরোটি সত্যিই পড়েছ।"
  },
  Event_7490_Name = {
    Text = "সাইফার-এডিক্ট·পর্ব II"
  },
  Event_7491_ChoiceDesc1 = {
    Text = "[What Price Are You Willing to Pay?] একটি এলোমেলো কার্ডের প্রার্থনাগাথা গুণমান উন্নত করো।"
  },
  Event_7491_ChoiceDesc2 = {
    Text = "[তাদের একটি মেয়াদোত্তীর্ণ ব্লাডি মেরি পান করতে দাও]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমিত করুন「(Skill.Arg2)」"
  },
  Event_7491_Desc = {
    Text = "\"স্বাগত জানাও, আমার অমূল্য অতিথি। নির্দ্বিধায় বেছে নাও; এই সব ঝলমলে আয়োজন কেবল তোমার প্রতীক্ষাতেই বিদ্যমান।\"\n\"আহ, বিরক্ত করলাম, একটু জানতে চাই... আপনি কি লেডি ড্যাফোডিলের যমজ বোন?\"\n\"আমি নিজেই লেডি ড্যাফোডিল। জানতে পারি, আজ কী কারণে এসেছ...?\"\n\"দুঃখিত, দুঃখিত, আপনি আগের চেয়েও অনেক বেশি মোহনীয় হয়ে উঠেছেন। আমি চিনতে পারিনি। মনে আছে? বিশ বছর আগে, আপনি আমার বারের এক বিকৃত অতিথিকে তাড়িয়ে দিয়েছিলেন... গতকাল, সেই দুঃস্বপ্ন ফিরে এসেছে। সে বারে দখল নিয়েছে, সঙ্গে এনেছে তার আপন জাতের অগণিত সঙ্গী...\""
  },
  Event_7491_Name = {
    Text = "স্মৃতির খণ্ডাংশ: গতকালের স্বপ্ন"
  },
  Event_7492_ChoiceDesc1 = {
    Text = "[Chase the Crows] 30টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_7492_ChoiceDesc2 = {
    Text = "[Continue chasing the child] প্রস্থান করুন"
  },
  Event_7492_Desc = {
    Text = "দ্বিতীয় কাকটি প্রয়াত আত্মা হলো, তার লেজের পালকে হাড়ের মতো ফ্যাকাশে সাদা আভা ফুটে উঠল।"
  },
  Event_7492_Name = {
    Text = "কালো কাকের দৃষ্টি"
  },
  Event_7493_ChoiceDesc1 = {
    Text = "[Take a Gamble] 「(Skill.Arg1)」 বিকশিত করো এবং ভাগ্যকে পরীক্ষা করো"
  },
  Event_7493_ChoiceDesc2 = {
    Text = "[Forget It] 25টি কালো চিহ্ন সংগ্রহ করো"
  },
  Event_7493_Desc = {
    Text = "\n「একটা বাজি ধরবে? আমাদের সংখ্যা আন্দাজ করো! সামান্য দামে!」\nফেলে দেওয়া পাশাগুলো গুনগুন করে উঠল, যেন তোমার সঙ্গে কথা বলছে।\n「আমায় ঘোরাও! আমায় ঘোরাও!」\n「একটাই! শেষটা!」\nঠিক আছে, একবারই তো...\nতুমি একটা চিপ তুলে নিলে। তুমি সিদ্ধান্ত নাও..."
  },
  Event_7493_Name = {
    Text = "অনন্ত জুয়া"
  },
  Event_7494_ChoiceDesc1 = {
    Text = "[Resist Malice] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকাশ করো।"
  },
  Event_7494_ChoiceDesc2 = {
    Text = "[Embrace Malice] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকাশ করো।"
  },
  Event_7494_ChoiceDesc3 = {
    Text = "[Clear-Minded Departure] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7494_Desc = {
    Text = "অশুভ চিন্তাগুলো ব্লেডে, বা ধারালো দাঁতে রূপ নেয়。\nতারা ডোমেইনের ক্ষয়িষ্ণু সুস্থ মস্তিষ্ককে কুরে কুরে খায়, অবশিষ্ট ইচ্ছাশক্তিকে গ্রাস করে, যেমন বাস্তবতা তোমার ওপর নিষ্ঠুরতা আরোপ করে…"
  },
  Event_7494_Name = {
    Text = "অযাচিত চিন্তা"
  },
  Event_7495_ChoiceDesc1 = {
    Text = "[Struggle Fully] একটি কমান্ড কার্ড ধ্বংস করো এবং Arg1টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_7495_ChoiceDesc2 = {
    Text = "[Light the Web] একটি কমান্ড কার্ড নকল করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকাশ করো।"
  },
  Event_7495_ChoiceDesc3 = {
    Text = "[Wait Quietly] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_7495_Desc = {
    Text = "মাকড়সার জালের মতো সূক্ষ্ম সুতো তোমাকে জড়িয়ে ধরে; এই মুহূর্তে, তুমি স্পষ্টই ডোমেইনের শিকার হয়ে গেছ।"
  },
  Event_7495_Name = {
    Text = "গভীরে আটকানো"
  },
  Event_7496_ChoiceDesc1 = {
    Text = "[Recipient: ∞] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_7496_ChoiceDesc2 = {
    Text = "[Recipient: Self] একটি কার্ড ধ্বংস করো"
  },
  Event_7496_ChoiceDesc3 = {
    Text = "[Recipient: Teacher] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7496_Desc = {
    Text = "সে ডোমেইন ওয়াকারকে একটি সুযোগ দিয়েছিল: অজানার সঙ্গে সংযোগের এক সুযোগ।\nকয়েকটি ছেঁড়াফাটা কাগজ, কালি ঝরানো এক টাইপরাইটার, আর এক অজানা, একমুখী প্রাপক।\nহয়তো ইচ্ছাশক্তিই নির্ধারণ করতে পারে, তোমার বার্তা কোথায় পৌঁছাবে।"
  },
  Event_7496_Name = {
    Text = "স্বগতোক্তি"
  },
  Event_7497_ChoiceDesc1 = {Text = "[Accept]"},
  Event_7497_ChoiceDesc2 = {Text = "[Reject]"},
  Event_7497_Desc = {
    Text = "শূন্য প্রাঙ্গণে হুইসপার প্রতিধ্বনিত হয়。\n\"ও যে বোকা সারাক্ষণ 'জিতো বা মরে যাও' বলে বকবক করে, সেই কুখ্যাত জুয়াড়ি। তার থেকে দূরে থাকাই ভালো তোমার।\"\nএকটি কৃশ, কুঁজো দেহী অবয়ব তোমার দিকে কয়েকটি মুদ্রা ছুড়ে দেয়, ধাতব ঠং শব্দ করে তা এসে পড়ে তোমার তালুতে。\n\"চলো, এক দফা খেলা হোক।\""
  },
  Event_7497_Name = {
    Text = "কুখ্যাত জুয়াড়ি"
  },
  Event_7498_ChoiceDesc1 = {
    Text = "[আমরা সবাই নিরাপদ]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_7498_ChoiceDesc2 = {
    Text = "[তুমি কে？]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করো：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_7498_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7498_Desc = {
    Text = "টাইপরাইটার হঠাৎ কালি উগরে দেয়, চোখে বিঁধে যাওয়ার মতো সংখ্যক বিস্ময়বোধক চিহ্নসহ.\n「ডল, তুমি ঠিক আছ তো??? রক্ষকও যখন গায়েব, তখন তুমিও কেন উধাও হয়ে গেলে??? প্লিজ, যদি নিরাপদে থাকো, একটা বার্তা পাঠাও!!! উইলিয়াম সিনিয়রের চুল আর অপেক্ষা সহ্য করতে পারবে না!!!」"
  },
  Event_7498_Name = {
    Text = "জরুরি বার্তা"
  },
  Event_7499_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7499_Desc = {
    Text = "তুমি শেষ প্লাস্টারের টুকরোটি লাগিয়ে দাও। সে হঠাৎ তীক্ষ্ণ হাসিতে ফেটে পড়ে, কালো কুয়াশা সর্পিল হয়ে উপরে জড়িয়ে ওঠে, আর তার ভাসমান অবয়ব তোমার দৃষ্টির আড়াল হয়ে যায়।"
  },
  Event_7499_Name = {
    Text = "দেহ পুনর্গঠন"
  },
  Event_7500_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7500_Desc = {
    Text = "তুমি রৌপ্য চাবি বের করো, শোক ও শ্রদ্ধায় তাকে আঁকড়ে ধরো। এক মৃদু, কুয়াশার মতো আভা তোমাকে আচ্ছন্ন করে।\nনীরবতার মাঝে কেবল একটি দীর্ঘশ্বাস ভেসে থাকে।"
  },
  Event_7500_Name = {
    Text = "পর্যবেক্ষকের দৃষ্টি"
  },
  Event_7501_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7501_Desc = {
    Text = "লেগে থাকা দৃষ্টিগুলো অবিরত তোমাকে পর্যবেক্ষণ করে, আর তোমার চামড়ার নিচের কোষগুলো চিৎকার করে পালাতে থাকে, শিরাগুলো কিলবিল করতে থাকে কৃমির মতো।\nতুমি অনুভব করো শক্তির এক স্রোত, যা উথলে উঠে বিস্ফোরিত হচ্ছে তোমার অঙ্গপ্রত্যঙ্গের গ্রোটেস্ক বিকৃতির ভেতর দিয়ে।"
  },
  Event_7501_Name = {
    Text = "পর্যবেক্ষকের দৃষ্টি"
  },
  Event_7502_ChoiceDesc1 = {
    Text = "[Avoid Gaze] যেকোনো এক জন জাগরণকারীকে এলোমেলোভাবে জাগরণ ঘটাও"
  },
  Event_7502_ChoiceDesc2 = {
    Text = "[Stare] জাগরণ ঘটানোর জন্য একটি জাগরণকারী বেছে নাও, সেই কার্ডের অ্যারিথমেটিকা ব্যয় 2 কমাও, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7502_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7502_Desc = {
    Text = "অগণিত মাত্রা সুড়ঙ্গের সুতোয় গাঁথা, আর তুমি যখন সেই সর্বোচ্চ প্যাসেজ বেয়ে গোপনে এগিয়ে যাও, অসংখ্য চোখ তোমার দিকে তীক্ষ্ণ দৃষ্টিতে চেয়ে থাকে।"
  },
  Event_7502_Name = {
    Text = "ঐশ্বরিক দৃষ্টি"
  },
  Event_7503_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7503_Desc = {
    Text = "এটা বিশৃঙ্খলা, সম্পূর্ণ বিশৃঙ্খলা।\nসব চিন্তা এক মুহূর্তে ঝড়ের স্রোতে ভেসে যায়, মস্তিষ্কের প্লাবনে গিলে খায়।\nমস্তিষ্কের গভীরে কেবল অন্তহীন বিভ্রান্তি আর যন্ত্রণা থেকে যায়, একসাথে ডুবে যেতে থাকে।"
  },
  Event_7503_Name = {
    Text = "অনুপ্রেরণার বিস্ফোরণ"
  },
  Event_7504_ChoiceDesc1 = {Text = "[Take It]"},
  Event_7504_Desc = {
    Text = "অতিরিক্ত স্যাচুরেটেড D-পঙ্কের ভেতরে যেন কিছু আছে... রৌপ্য চাবি ব্যবহার করে সেটিকে তোমার নিজস্ব শক্তিতে রূপান্তর করো।"
  },
  Event_7504_Name = {
