  },
  Event_7505_ChoiceDesc2 = {
    Text = "[Continue chasing the child] প্রস্থান করুন"
  },
  Event_7505_Desc = {
    Text = "একটি কাক উড়ে গেল, রেখে গেল একটি একাকী কালো পালক, যা ধীরে ধীরে নিচে ভেসে নামছে।"
  },
  Event_7505_Name = {
    Text = "কালো কাকের দৃষ্টি"
  },
  Event_7506_ChoiceDesc1 = {Text = "[Confirm]"},
  Event_7506_Desc = {
    Text = "এখানেই অতল যুদ্ধক্ষেত্র, যেখানে যুদ্ধ দাবি করে সাহস আর প্রজ্ঞা দুটোই।\n\nদৃষ্টি শাণিত করো, প্রতিপক্ষকে পর্যবেক্ষণ করো। তোমাকে সবাইকে হারাতে হবে না; শুধু তাদের নেতাকে মাটিতে ফেলো!"
  },
  Event_7506_Name = {
    Text = "অসুরীয় বিচার"
  },
  Event_7507_ChoiceDesc1 = {
    Text = "[Connect] Arg2 HP পুনরুদ্ধার করো।"
  },
  Event_7507_Desc = {
    Text = "কুয়াশা ভারী হয়ে ঝুলে থাকে, আর তোমার ব্যাজে মিটমিট করে ফ্যাকাশে সিলভার আভা। যোগাযোগকারীটা কড়কড় শব্দ তুলে জেগে ওঠে। কেউ একজন ডাকছে।"
  },
  Event_7507_Name = {
    Text = "সংযোগস্থল"
  },
  Event_7508_ChoiceDesc1 = {Text = "[Tail Him]"},
  Event_7508_ChoiceDesc2 = {
    Text = "[Greet Them]"
  },
  Event_7508_Desc = {
    Text = "ঠক্। ঠক্। ঠক্।\nঘন কুয়াশার ভেতর দিয়ে ধীরে ধীরে এগিয়ে আসে এক সাদা অবয়ব, যেন নীরব রাতে ভেসে চলা কোনো জাহাজ।\nপেছন থেকে দেখে মনে হয়, সে এক কিশোর।\nতার ক্লান্ত পদধ্বনি শুনে, তুমি মনে মনে একটি সিদ্ধান্ত নাও।"
  },
  Event_7508_Name = {
    Text = "অন্তিম I"
  },
  Event_7509_ChoiceDesc1 = {
    Text = "[Hesitantly Agree]"
  },
  Event_7509_ChoiceDesc2 = {
    Text = "[Express Caution]"
  },
  Event_7509_Desc = {
    Text = "(ক্ষয়িত)টি পড়তে পড়তে আর্তনাদ করে, আর তুমি বিস্ময়ে দেখো তার পেছনে দাঁড়িয়ে আছে ক্লেমেন্টাইন।\n「বিদায় জানাতে এসেছি, 」 সে বলে। 「কৃতজ্ঞতার নিদর্শন হিসেবে তোমাকে কিছু সূত্র দিতে পারি। তবে... তার জন্য তোমার বিশ্বাস দরকার।\nআমাকে তোমাকে হিপনোটাইজ করতে দাও, আমি যা জানি সবই তোমার সঙ্গে ভাগ করে নেব।」\nতুমি কি তাকে বিশ্বাস করতে পারো?\n「সাবধান থেকো, 」 রামোনা সতর্ক করেছিল, 「তার নিশ্চয়ই গোপন উদ্দেশ্য আছে।」"
  },
  Event_7509_Name = {
    Text = "সম্মোহন চিকিৎসা"
  },
  Event_7510_ChoiceDesc1 = {Text = "[Confirm]"},
  Event_7510_Desc = {
    Text = "তুমি মনোযোগ কেন্দ্রীভূত করো, আর মায়াস্বপ্নটি জলের ভেতর কালি গলে যাওয়ার মতো মিলিয়ে যায়। তুমি সামনে এগিয়ে যাও, কিন্তু হৃদয়ের উপর আঁকা ছায়াটি থেকে যায়।"
  },
  Event_7510_Name = {
    Text = "বিভ্রম"
  },
  Event_7511_ChoiceDesc1 = {
    Text = "[Pitiful Creature?]"
  },
  Event_7511_ChoiceDesc2 = {
    Text = "[Evolved Human?]"
  },
  Event_7511_ChoiceDesc3 = {
    Text = "[Who are you?]"
  },
  Event_7511_Desc = {
    Text = "তুমি যার সঙ্গে ষষ্ঠবারের মতো দেখা পেলে, সে ইস্পাতের ফ্রেমের চূড়ায় দাঁড়িয়ে ভূমিকে অবলোকন করছিল। প্রচণ্ড বাতাস তার লম্বা চুলকে পেছনে উড়িয়ে দিল, আর তাতে প্রকাশ পেল এক সাপের প্রকৃত রূপ।\nতার দৃষ্টি প্রথমে তোমার ওপর স্থির হলো, তারপর সরে গিয়ে দূরের অন্ধকারের দিকে নিবদ্ধ হলো।\n「আহ, কী করুণ এক প্রাণী ওটা।\nবিশ্বাসঘাতকতার স্বাদ নিশ্চয়ই <Bold:উন্নত> মানবের স্বাদের মতোই মধুর।」"
  },
  Event_7511_Name = {
    Text = "অদ্ভুত সঙ্গী VI"
  },
  Event_7512_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7512_Desc = {
    Text = "নরককুকুরের দৃষ্টির নিচে পড়ে থাকা এক টুকরো ফিল্মের রোলের দিকে আর কে-ই বা নজর দেবে?"
  },
  Event_7512_Name = {
    Text = "স্মৃতির ছায়ামূর্তি"
  },
  Event_7513_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7513_Desc = {
    Text = "দেখো না, আলোচনা কোরো না, শোনো না, এমনকি ভাবতেও যেয়ো না— জ্ঞানীদের নির্বাচন এটাই।"
  },
  Event_7513_Name = {
    Text = "রুন উন্মাদনা"
  },
  Event_7514_ChoiceDesc1 = {
    Text = "[Leave] যেকোনো 2টি কার্ড ধ্বংস করো"
  },
  Event_7514_Desc = {
    Text = "অসংখ্য শব্দের কোলাহলের ভেতর দিয়ে তুমি কষ্টে এক অদ্ভুত গুঞ্জন টের পাও, যেন কোনো পোকামাকড়ের ডানার শব্দ। রৌপ্য চাবি তোমার বুকে প্রচণ্ডভাবে কাঁপতে থাকে; কোনো অদৃশ্য শক্তির টানে তুমি মুখ তুলে তাকাও, আর আকাশে হঠাৎই ফুটে ওঠা এক বিশাল, কালো গহ্বর দেখতে পাও।\n「দুঃখজনক, নিঃসন্দেহে, কিন্তু তাতে কিছু যায় আসে না। আমরা আবার মিলিত হব, আমার শ্রদ্ধেয় তারারন্ধ্রহীন চোখ।」"
  },
  Event_7514_Name = {
    Text = "সম্মোহন চিকিৎসা"
  },
  Event_7515_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7515_Desc = {
    Text = "তুমি চারপাশের সবকিছু উপেক্ষা করতে পারো, কিন্তু নিজের হৃদস্পন্দনকে নয়। তার ছন্দ দ্রুততর হয়, তাড়না আর ভর্ৎসনায় তোমাকে ধাক্কা দেয়।"
  },
  Event_7515_Name = {
    Text = "বাম অলিন্দ"
  },
  Event_7516_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7516_Desc = {
    Text = "「দারুণ হয়েছে!!! উইলিয়াম সিনিয়রের চুল এখন নিরাপদ!!」\nটেলিগ্রামের লেখা সংক্ষিপ্ত, কিন্তু শব্দগুলো যেন কাগজের গা থেকে কেঁপে উঠে বেরিয়ে আসতে চায়।"
  },
  Event_7516_Name = {
    Text = "জরুরি বার্তা"
  },
  Event_7517_ChoiceDesc1 = {
    Text = "[Tell Him the Truth] এলোমেলো এক জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7517_ChoiceDesc2 = {
    Text = "[Conceal the Truth] 3টি প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_7517_Desc = {
    Text = "「আমাকে বাঁচান, দয়া করে।」\nবিষণ্ন পথিকটি আপনার হাত শক্ত করে ধরল। শত শত বছর ধরে সে এখানে ঘুরে বেড়াচ্ছিল।\n「আমি এক সৈনিক, আমাকে দূর প্রাচ্যে পাঠানো হয়েছিল ধর্মদ্রোহীদের বিরুদ্ধে যুদ্ধ করতে।\nঘন অরণ্য পেরিয়েছি, নদী বেয়ে হেঁটেছি, তবু পথ হারিয়ে বারবার একই জায়গায় ফিরে এসেছি।\nকিছু একটা আমাকে অন্ধকার থেকে দেখছে। আমি তাকে দেখতে পাই না, কিন্তু জানি—সবসময়ই সে আমাকে দেখেছে।\nএখন আমি শুধু বাড়ি ফিরতে চাই...」\nআপনি তার পেছনে ভাসমান ছায়াগুলোর দিকে তাকান। প্রথমে সেগুলো ছিল ঝাপসা, তারপর ধীরে ধীরে স্পষ্ট হয়ে উঠল—ওটা এক বিশাল ফাঁক-মুখ, ক্ষুধার্তভাবে প্রতীক্ষা করছে শতবর্ষ ধরে সংরক্ষিত হারিয়ে যাওয়া আত্মাদের জন্য।「"
  },
  Event_7517_Name = {
    Text = "গ্রাসকারী"
  },
  Event_7518_ChoiceDesc1 = {
    Text = "[Into the Darkness]"
  },
  Event_7518_ChoiceDesc2 = {Text = "[Farewell]"},
  Event_7518_Desc = {
    Text = "「সেলেস্ট, এবার তুমি আমাকে সাহায্য করবে, তাই তো?」\nমেয়েটি অস্থির পায়ে এদিক-ওদিক পায়চারি করছে, মাঝে মাঝে চুপচাপ দাঁড়িয়ে থাকা জাগরণকারীর দিকে ফিরে তাকাচ্ছে।\nসে মেয়েটির প্রশ্নের জবাব দেয় না, কিন্তু মেয়েটির অভিব্যক্তি যত বেশি উদ্বিগ্ন হয়ে ওঠে, এক ঝিরঝিরে হাওয়া সাদা ঘোমটা তুলে দেয়, তাকে আলতো করে এক নির্দিষ্ট দিকে ঠেলে দেয়।\n「আমি তোমাকে রক্ষা করব।」\nআমি তোমাকে রক্ষা করব, যদিও একসময় এই 「রক্ষা」 নামের ব্যাপারেই আমি ব্যর্থ হয়েছি।\nকিন্তু এবার, আমি তোমাকে আর একা অন্ধকারে হারিয়ে যেতে দেব না।"
  },
  Event_7518_Name = {
    Text = "জাহাজের পবিত্র কন্যার আশীর্বাদ"
  },
  Event_7519_ChoiceDesc1 = {
    Text = "[Leave] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7519_Desc = {
    Text = "কিছু গান প্রাচীন, প্লাবনের আগেই হারিয়ে গেছে; কিছু আবার একেবারে নতুন—গত নববর্ষের, যখন এক স্ত্রী লন্ডিনিয়াম ডিপার্টমেন্ট স্টোর থেকে নতুন দস্তানা কিনেছিল... অনুভূতির এই বিশৃঙ্খল জটিলতা শেষে গিয়ে হৃদয়ে ফেলে রেখে যায় শুধু এক শূন্য শূন্যতা।"
  },
  Event_7519_Name = {
    Text = "নাবিকদের গান"
  },
  Event_7520_ChoiceDesc1 = {
    Text = "[Expel Colors] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতাটি বিকশিত করো।"
  },
  Event_7520_ChoiceDesc2 = {
    Text = "[Embrace Colors] 3টি সোনার রেলিক থেকে 1টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7520_ChoiceDesc3 = {
    Text = "[Turn and Leave] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_7520_Desc = {
    Text = "মার্ফি পেছন পেছন এগোচ্ছিল, কিন্তু এক মোড়ে এসে হঠাৎ স্থির হয়ে গেল।\nবহুরঙা প্রবাহমান আভা ঘুরপাক খাচ্ছিল, বাতাসকে দীর্ঘশ্বাস ফেলতে বাধ্য করে।\n「মার@1...」\nওটা কি সোনা-নিল-এ ডুবে-মরা কোনো প্রয়াত আত্মার ভূত? নাকি জীবিতদের পিছু নেওয়া কোনো প্রিয় প্রয়াত আত্মা?"
  },
  Event_7520_Name = {
