  },
  Event_7521_ChoiceDesc1 = {
    Text = "[Keep Searching] সর্বোচ্চ HP Arg1 পরিমাণ বাড়াও, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7521_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7521_Desc = {
    Text = "একটি পরিচিত কণ্ঠস্বর আমার কানে হুইসপার করল, উষ্ণ আর সান্ত্বনাদায়ক। কিন্তু আমি যখন তাকে অনুসরণ করতে চাইলাম, শব্দটি হঠাৎ করেই থেমে গেল।"
  },
  Event_7521_Name = {
    Text = "অস্বাভাবিক যোগাযোগ"
  },
  Event_7522_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7522_Desc = {
    Text = "\"ওটা ছিল এক নাস্তিক্যবাদী সুর।\"\nতুমি কান ঢেকে রাখো, রক্ত ঝরতে থাকে, আর নিঃসন্দেহে এ কথাই উচ্চারণ করো।"
  },
  Event_7522_Name = {
    Text = "নিষিদ্ধ সুর"
  },
  Event_7523_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7523_Desc = {
    Text = "রঙগুলো অস্পষ্টভাবে মোচড় খেয়ে দু’টি মানবসদৃশ অবয়বে রূপ নেয়, কিন্তু তারা সেই কোণায় নিশ্চল থাকে, দৃষ্টির মাধ্যমে তোমাকে তাদের শেষ আশীর্বাদ অর্পণ করে।"
  },
  Event_7523_Name = {
    Text = "স্মৃতির রঙ"
  },
  Event_7524_ChoiceDesc1 = {
    Text = "[Listen] 3টি সোনালি রেলিক থেকে 1টি অর্জন করো"
  },
  Event_7524_Desc = {
    Text = "ড্যাফোডিলের কণ্ঠস্বর এক মুহূর্তের জন্য থেমে গেল।\n\"ওহ, তুমি এটা বেছেছ? ভালো পছন্দ। পুরস্কার হিসেবে, আমি তোমাকে বিশেষ একটি উপহার দেব।\""
  },
  Event_7524_Name = {
    Text = "ইঙ্গিতের সময়"
  },
  Event_7525_ChoiceDesc1 = {
    Text = "[Keep Asking] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_7525_ChoiceDesc2 = {
    Text = "[Abandon Inquiry] একটি কার্ড ধ্বংস করো"
  },
  Event_7525_Desc = {
    Text = "\"হুঁ, বিচক্ষণ সিদ্ধান্ত। এমন দুর্ধর্ষ শত্রুর মুখোমুখি হয়ে, নিশ্চয়ই তুমি নিজেকে আর প্রতিপক্ষকে জানতে চাইবে? তবে, মাত্রা সম্পর্কে অতিরিক্ত গোপন তথ্য জানা কিন্তু তোমার মানসিক ভারসাম্য নষ্ট করতে পারে, বুঝলে?\""
  },
  Event_7525_Name = {
    Text = "ইঙ্গিতের সময়"
  },
  Event_7526_ChoiceDesc1 = {
    Text = "[Persistent Inquiry] বার ড্যাফোডিলকে ক্রোধান্বিত করে যুদ্ধ শুরু করো।"
  },
  Event_7526_ChoiceDesc2 = {
    Text = "[Give up asking] একটি ছোট শাস্তি গ্রহণ করো"
  },
  Event_7526_Desc = {
    Text = "\"ওহ? এখনো পর্যন্ত, তুমি আমার গতিপথের নিয়ম নিয়ে ভাবছ? ছোট্টটি, অতিরিক্ত লোভী হওয়া ভালো নয়, জানো তো?\""
  },
  Event_7526_Name = {
    Text = "ইঙ্গিতের সময়"
  },
  Event_7527_ChoiceDesc1 = {
    Text = "[Focus] সর্বোচ্চ HP Arg1 দ্বারা বৃদ্ধি করো"
  },
  Event_7527_ChoiceDesc2 = {
    Text = "[উপেক্ষা করো]এলোমেলো 2টি কমান্ড কার্ড অরিসন পাবে：「(EnchantConfig.Arg1)」，2টি「(Skill.Arg2)」সংক্রমিত করো"
  },
  Event_7527_Desc = {
    Text = "তুমি ছোট শহরের রাস্তায় নরককুকুরের পিছু নাও।\nআকাশ থেকে ঠান্ডা তুষারকণা ঝরতে শুরু করে, আলতো করে এসে পড়ে তোমার গাল আর বুকে, অস্থির হৃদয়টাকে কিছুটা শান্ত করে দেয়।"
  },
  Event_7527_Name = {
    Text = "তুষার"
  },
  Event_7528_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7528_Desc = {
    Text = "তুমি হাত নাড়িয়ে এই বিরক্তিকর কাকগুলোকে তাড়ানোর চেষ্টা করো।\nতারা কর্কশ স্বরে ডেকে ওঠে, যেন তোমার বোকামি আর দুর্বলতাকে নিয়ে হাসছে।\nতবু, তোমার সাহস তাদের নাড়া দেয়, আর তুমি তার উপযুক্ত পুরস্কার পাও।"
  },
  Event_7528_Name = {
    Text = "কাকদের গান"
  },
  Event_7529_ChoiceDesc1 = {
    Text = "[About Lily] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_7529_ChoiceDesc2 = {
    Text = "[About Hellhound] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো"
  },
  Event_7529_Desc = {
    Text = "\nঅন্তহীন দরজা পেরিয়ে, দূরবর্তী ও অধরা এক স্থান থেকে ড্যাফোডিলের কণ্ঠ ভেসে আসে।\n\"এটি ড্যাফোডিলের ইঙ্গিতের সময়।\""
  },
  Event_7529_Name = {
    Text = "ইঙ্গিতের সময়"
  },
  Event_7530_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7530_Desc = {
    Text = "তুমি অবিচল থাকো, মন্ত্রোচ্চারণ করতে করতে নিজের সত্তার প্রতি সৎ থাকো।\nতুমি কানে ভেসে আসা হুইসপার-গুলোর ওপর ভরসা করো না, নির্ভর করো কেবল মানবীয় যুক্তির ওপর।\nতবু... যখন তোমার ভরসার দৃঢ় মাটি ঘন কালো কাদায় গ্রাস হয়ে যাবে, তখন শেষ মুহূর্তে পর্যবেক্ষণ-এর যন্ত্র হিসেবে ব্যবহার করার জন্য নিজের চোখ উপড়ে নেওয়াই হবে তোমার একমাত্র নির্বাচন।"
  },
  Event_7530_Name = {
    Text = "কাকদের গান"
  },
  Event_7531_ChoiceDesc1 = {
    Text = "[Stare Down the Hellhound Source] 「(RelicConfig.Arg1)」 নামের সোনার রেলিক অর্জন করো কিন্তু 「(Skill.Arg2)」 বিকশিত হবে"
  },
  Event_7531_ChoiceDesc2 = {
    Text = "[Focus on Battle] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 3টি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7531_Desc = {
    Text = "নরককুকুরের ছায়া বদলে যায়।\nতার দেহ দেয়ালের ফাটলগুলোকে জুড়ে দেয়, উন্মোচন করে শিউরে-ওঠা মায়াস্বপ্ন।"
  },
  Event_7531_Name = {
    Text = "দৃষ্টিকোণ থেকে"
  },
  Event_7532_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7532_Desc = {
    Text = "“ম্যাঁও, ম্যাঁও ম্যাঁও, ম্যাঁও ম্যাঁও ম্যাঁও...”\nতুমি গলা চেপে ধরলে, প্রাণপণে দুর্বল আর নিরীহ শোনানোর চেষ্টা করলে।\n“ম্যাঁও! ম্যাঁও ম্যাঁও! ম্যাঁও ম্যাঁও ম্যাঁও!”\nবিড়ালগুলোর দল যেন তোমার শুভেচ্ছা মেনে নিল, উচ্ছ্বসিত ডাকে সাড়া দিল। তোমার আর তাদের আর্তনাদ প্রতিধ্বনিত হতে থাকল এপার-ওপার, দিনরাত একটানা, এমনকি চাঁদটাকেও ভয় দেখিয়ে মেঘের আড়ালে লুকিয়ে ফেলল।"
  },
  Event_7532_Name = {
    Text = "বিড়ালের শহর"
  },
  Event_7533_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7533_Desc = {
    Text = "শুধু এক টলমল প্রাণী, যে বিশ্রামের জন্য ভরসা করার মতো এক টুকরো ভাসমান কাঠ খুঁজছে...\nতুমি দীর্ঘশ্বাস ফেলো, আর প্রজাপতির লেজ থেকে ঝরে পড়া কালো তরল তোমার গালে টুপটাপ পড়ে।"
  },
  Event_7533_Name = {
    Text = "অবসিডিয়ান প্রজাপতি"
  },
  Event_7534_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7534_Desc = {
    Text = "তুমি সর্বশক্তি দিয়ে বিড়ালদের দল থেকে অনেক দূরে সরে গেলে।\nপেছনে তাকিয়ে দেখলে, বিড়ালগুলো ইতিমধ্যেই তাদের স্বাভাবিক কাজকর্মে ফিরে গেছে: লোম গোছানো, টুকটুক ঘুম, এমনকি একে অপরের সঙ্গে মারামারি...\nসত্যি বলতে, তারা মানুষের তোয়াক্কাই করে না।"
  },
  Event_7534_Name = {
    Text = "বিড়ালের শহর"
  },
  Event_7535_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7535_Desc = {
    Text = "তুমি বাকি থাকা মাংসের টুকরোগুলো বিড়ালের ঝাঁকের দিকে ছুড়ে দাও।\nবিড়ালগুলো কালো জোয়ারের মতো ঝাঁপিয়ে পড়ে, উন্মত্তভাবে মাংস ছিঁড়ে খেতে থাকে, তারপর দ্রুত ছত্রভঙ্গ হয়ে যায়।\nদুর্ভাগ্যবশত, মাংসটি পচা। তা তাদের খালি পেট ভরায়, কিন্তু তৃপ্তি এনে দিতে পারে না।"
  },
  Event_7535_Name = {
    Text = "বিড়ালের শহর"
  },
  Event_7536_ChoiceDesc1 = {
    Text = "[Eye Contact] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7536_ChoiceDesc2 = {
    Text = "[Stop Resisting] 2 জন এলোমেলো জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)「 দু」বার বিকশিত করো।"
  },
  Event_7536_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7536_Desc = {
    Text = "অগণিত চোখ তোমার কানের চারপাশে হুইসপার করে।\n\"আমরা যাত্রা করি, আমরা থামি, আমরা দশ সহস্র বছর, তারও বেশি সময় ধরে এগিয়ে চলি।\nযখন সূর্য আমাদের সতর্ক দৃষ্টির নীচে ম্লান হয়ে যায়, যখন প্রাচীন পৃথিবীর জীবন প্লাবনে গ্রাসিত হয়।\nআমরা বহু আগেই মহাবিশ্বের রহস্যে মুগ্ধ হয়ে পড়েছি।\""
  },
  Event_7536_Name = {Text = "চোখ"},
  Event_7537_ChoiceDesc1 = {
    Text = "[Feel Panic] যেকোনো এক জন জাগরণকারীকে এলোমেলোভাবে জাগরণ ঘটাও"
  },
  Event_7537_ChoiceDesc2 = {
    Text = "[Feel Content] জাগরণ ঘটানোর জন্য একটি জাগরণকারী বেছে নাও, সেই কার্ডের অ্যারিথমেটিকা ব্যয় 2 কমাও, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_7537_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7537_Desc = {
    Text = "তুমি এমন এক আকাশ দেখেছ, যেখানে চাঁদ নেই, নক্ষত্রপুঞ্জ নেই, কেবল অসংখ্য বিশাল তারারন্ধ্র ঝুলে আছে উপরে。\nমনে হয়, হাত বাড়ালেই সেগুলো টেনে নামাতে পারবে, রক্ত আর মাংস ছিটকে পড়বে চারদিকে。\nকিন্তু হাত মেলে ধরলে দেখো, সেখানে কিছুই নেই。\nভাগ্যের চোখ তোমার দিকে পলকহীন দৃষ্টিতে চেয়ে থাকে, বিশৃঙ্খল মহাবিশ্বের ভেতর খুঁজে পেয়েছে এক ঝলমলে বালুকণা।"
  },
  Event_7537_Name = {
    Text = "গম্বুজের চোখ"
  },
  Event_7538_ChoiceDesc1 = {
    Text = "[Lower Hands] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_7538_ChoiceDesc2 = {
    Text = "[Keep Covering Ears] 75টি কালো চিহ্ন গ্রহণ করো, কিন্তু 「(Skill.Arg2)」 নামের উপসর্গটি বিকশিত হবে"
  },
  Event_7538_Desc = {
    Text = "কর্কশ চিৎকার, অন্তহীন কর্কশ চিৎকার—\nচকচকে কালো পালকে মোড়া র‍্যাভেন গায়ক, তার ধারালো ঠোঁটে ঠান্ডা আলো ঝলসে ওঠে, প্রতিটি বিলাপময় ডাক তোমার কানের পর্দা বিদীর্ণ করে।\nকান ঢেকে রেখো না!\nরাত্রির কাকের কোরাস তোমার সঙ্কুচিত দেহের ভেতরের কাঁচা কম্পনের জন্য ক্ষুধার্ত।"
  },
  Event_7538_Name = {
    Text = "কাকঝাঁকের গান"
  },
  Event_7539_ChoiceDesc1 = {
    Text = "[Imitate Cat's Call] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7539_ChoiceDesc2 = {
    Text = "[Feed] 75টি কালো চিহ্ন গ্রহণ করো, কিন্তু 「(Skill.Arg2)」 নামের উপসর্গটি বিকশিত হবে"
  },
  Event_7539_Desc = {
    Text = "\"তুমি অসাবধানে কালো বিড়ালের ডোমেইনে ঢুকে পড়েছ।\nঅন্ধকারে অসংখ্য চোখ খুলে গেল, ভরা কৌতূহল, অনুসন্ধান আর সতর্কতায়... কিন্তু বিন্দুমাত্র মমতা নেই।\nপান্না সবুজ, অ্যাম্বার হলুদ, ময়ূর নীল...\nতোমার মনে হলো, যেন তুমি ঝলমলে রত্নের সাগরে নিমজ্জিত হয়ে আছো।\nপালানোর জন্য, তুমি—\""
  },
  Event_7539_Name = {
    Text = "বিড়ালের শহর"
  },
  Event_7540_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7540_Desc = {
    Text = "তুমি এক অদ্ভুত হাত লক্ষ্য করো। তা কোমল, ফর্সা, আর পুরো সময়টাতেই অটল শান্ত।\nতার চেয়েও গুরুত্বপূর্ণ—তুমি বুঝতে পারো, এটা তোমারই হাত।\nবিনা দ্বিধায় তুমি তা হঠাৎ মোচড় দিয়ে ছিঁড়ে ফেলো।\nঅগণিত কর্কশ আর্তনাদ প্রতিধ্বনিত হয়, আর শেষমেশ জলাভূমি মিলিয়ে যায়।"
  },
  Event_7540_Name = {
    Text = "বিষণ্ণ জলাভূমি"
  },
  Event_7541_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7541_Desc = {
    Text = "「「একটি প্রজ্ঞাময় নির্বাচন,」 বলে খালি হাতে দাঁড়ানো অবয়বটি। 「পূর্বনির্ধারিত নির্বাচন পূর্বনির্ধারিত পরিণতির দিকে নিয়ে যায়, আর অনির্দেশ্য কর্ম নতুন ভবিষ্যতের পথ খুলে দেয়।」\nএকটি সূক্ষ্ম, কোমল আকাঙ্ক্ষা তোমাকে আলতো করে আচ্ছন্ন করে। ছায়ামূর্তিগুলো মিলিয়ে যায়, তোমাকে বুকে হাত চেপে ধরে রেখে যায়, তুমি নিশ্চিত নও, এটা কি ছিল কোনো প্রক্ষেপণ, নাকি মানসিক চাপে উদ্ভূত কোনো মায়াভ্রম।「"
  },
  Event_7541_Name = {
    Text = "বিভক্ত পথ"
  },
  Event_7542_ChoiceDesc1 = {
    Text = "[Praise It] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7542_ChoiceDesc2 = {
    Text = "[Taunt It] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো এবং খোদাই করার প্রার্থনাগাথা পরিবর্তন করো।(ব্যবহার: 2/2)"
  },
  Event_7542_Desc = {
    Text = "মন বলে: শৃঙ্খল আমার প্রিফ্রন্টাল লোব, ব্রেইনস্টেম, সেরিব্রাল কর্টেক্সকে বেঁধে রেখেছে, তবু তারা বেঁধে রাখতে পারে না সত্যের পেছনে ছুটে চলা ১০ বিলিয়নেরও বেশি ক্ষুদ্র কোষকে।\nতুমি বলো: কে তোমাকে এখানে বন্দি করেছে? তোমার শরীরের কী হল?\nমন বলে: শরীর? মজা করো না! আগে তারা আমাকে ডাকত “বুড়ো জনি, শুয়োরের মাংসওয়ালা” বলে।\nযখন আমার শরীর ছিল, তখন দশের নিচের অঙ্কও আমার বোধগম্য ছিল না।\nকিন্তু কিউরেটর যখন আমার অতিরিক্ত মাংস কেটে ফেলল, দেখো আমি কী হয়ে গেছি! এক পদার্থবিদ, এক দার্শনিক, আর এক অপেশাদার কবি।"
  },
  Event_7542_Name = {
