  Event_7543_ChoiceDesc2 = {
    Text = "[Journey's End] এলোমেলো একটি কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_7543_ChoiceDesc3 = {
    Text = "[Refuse to Ask] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7543_Desc = {
    Text = "তুমি স্পিরিট বোর্ডটি হাতে তুলতেই, এক তরুণী কণ্ঠস্বর ঝড়ের মতো তোমার মস্তিষ্কে ঢুকে পড়ল।\n「আমাকে যেকোনো কিছু জিজ্ঞেস করো। আমি সব জানি।」\n「আমার উত্তরের মধ্য দিয়েই তুমি নিয়তির উপহার পাবে।」"
  },
  Event_7543_Name = {
    Text = "স্পিরিট বোর্ড"
  },
  Event_7544_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7544_Desc = {
    Text = "তুমি ছেঁড়া, খণ্ডাংশে বিভক্ত কাগজটি পড়তে থাকো, ভাঙা বাক্যগুলো তোমার মুখ থেকে গড়িয়ে পড়ে। 「পূর্বপুরুষ」, 「ডিভুস」, 「চিরমৃত্যু」 এবং 「দীর্ঘ স্মৃতি」র মতো শব্দ তোমার মস্তিষ্কে ঢেউ তোলে, দুঃস্বপ্নে জর্জরিত তোমার ইতিমধ্যেই ভঙ্গুর স্নায়ুকে আরও আলোড়িত করে তোলে।"
  },
  Event_7544_Name = {
    Text = "সাইফার-এডিক্ট·পর্ব I"
  },
  Event_7545_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7545_Desc = {
    Text = "কালো কাদা টুপটাপ করে তোমার মুখে পড়ে, ত্বকে ঝিনঝিনে চুলকানি ধরায়।\nসহ্য করতে না পেরে তুমি প্রজাপতিটাকে ঝেড়ে ফেলতে যাও।\nপ্রজাপতিটি তোমার বৈরী আচরণ এড়িয়ে নীরবে দূরের অন্ধকারে মিলিয়ে যায়।"
  },
