  },
  Event_7548_Desc = {
    Text = "একটি কাক ঝাড়বাতিতে বসে আছে।\nদুটি কাক ঝাড়বাতিতে বসে আছে।\nতিনটি কাক ঝাড়বাতিতে বসে আছে।\n.....\nকালো প্রাণীগুলো গলির ঝাড়বাতি থেকে গলিয়ে নেওয়া ঘাড় মুচড়ে কুৎসিত দৃষ্টিতে চেয়ে আছে। তাদের ছায়াচ্ছন্ন মাথাগুলো যেন একটিমাত্র দেহ ভাগ করে নিয়েছে, যা D-পঙ্কের ভেতর ডুবে আছে।"
