  },
  Event_7549_Desc = {
    Text = "তুমি চিহ্নটিকে উপেক্ষা করে সামনে এগিয়ে গেলে।\n<Italic:জাগ্রত জ্ঞানের ভার কতই না গভীর>, তোমার পদচারণার সাথে সাথে চিহ্নটি প্রসারিত ও বেঁকে যেতে লাগল, যেন যে কোনো মুহূর্তে সেই ফাটল থেকে একটি হাত বেরিয়ে এসে তোমাকে টেনে নিয়ে যাবে অতল গহ্বরে।"
  },
  Event_7549_Name = {
