  },
  Event_7550_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7550_Desc = {
    Text = "তুমি এক দৃষ্টি অনুভব করো—ডোমেইনেরও ঊর্ধ্বে, এক অতীন্দ্রিয় নজর—যা তোমার আর তোমার সামনে দাঁড়ানো মেয়েটির দিকে তাকিয়ে আছে।\nতোমার শ্বাস দ্রুত হয়ে ওঠে, আর আদিম ভয় তোমার মনের গভীর থেকে আর্তনাদ করে ওঠে।"
  },
