  },
  Event_7552_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7552_Desc = {
    Text = "তাঁদের মন্ত্রোচ্চারণ নরম স্বরে প্রতিধ্বনিত হতে হতে, উষ্ণ স্রোত তোমার কাছে নিয়ে আসে ঘরের আশীর্বাদ।"
