  Event_7559_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7559_Desc = {
    Text = "কাগজের অক্ষরগুলো হঠাৎই সম্পন্ন ও জীবন্ত হয়ে ওঠে, এমন সব ভয়াবহ শব্দে রূপ নেয় যা কোনো অজ্ঞান কষ্টভোগীর বিশ্বাস আর ভিত্তিকে সহজেই বিচলিত করে দিতে পারে। যতই তুমি পড়ো, ততই তুমি বিভ্রান্ত আর আতঙ্কগ্রস্ত হয়ে ওঠো, অজান্তেই নিজের মাথার তালু চুলকে চলেছ।\nহঠাৎ, সেই অভিশপ্ত চিহ্নগুলো মিলিয়ে যায়। রামোনা তোমার পাঠে হস্তক্ষেপ করে, আর জোর করে পাতাগুলো স্যুটকেসের ভেতর গুঁজে দেয়।"
  },
  Event_7559_Name = {
    Text = "সাইফার-এডিক্ট·পর্ব II"
  },
  Event_7560_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7560_Desc = {
    Text = "আনন্দ, শোক, বেদনা, ক্লেশ... এগুলোই তোমার অনুভূতি।\nতুমি, আর অসংখ্য ভিন্ন মাত্রায় ছড়িয়ে থাকা তোমারই অগণিত রূপ।"
  },
  Event_7560_Name = {
    Text = "আসক্তি"
  },
  Event_7561_ChoiceDesc1 = {
    Text = "[চুপচাপ শোনা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_7561_ChoiceDesc2 = {
    Text = "[সে এখানে আছে]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পান：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_7561_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7561_Desc = {
    Text = "ডিসলুটদের আর্তচিৎকার তোমার মনের ভেতর প্রতিধ্বনিত হয়। কালো অন্ধকারের গভীর থেকে এক ক্ষীণ অথচ পরিচিত কণ্ঠস্বর ভেসে আসে, দুর্বল স্বরে হুইসপার করে—\n「সাশা দিদি, 」 「সাশা দিদি...」\n「সাশা দিদি, তুমি কোথায়?」"
  },
  Event_7561_Name = {
    Text = "\"সাশা দিদি\""
  },
  Event_7562_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7562_Desc = {
    Text = "\"তাঁর সঙ্গে যুক্ত হও, তাদের সঙ্গে যুক্ত হও, আমাদের সঙ্গে যুক্ত হও।\nতাঁর রক্ষাকারী হও, তাঁর প্রতিনিধি হও।\nতাঁর স্বপ্ন তোমার পথনির্দেশ হোক...\"\nঅরাজক নীরব প্রার্থনা তোমার মনকে আলোড়িত করে। কণ্ঠস্বরগুলো মিলিয়ে যাওয়ার পর তুমি নিজেকে ঘামে ভেজা অবস্থায় আবিষ্কার করো।"
  },
  Event_7562_Name = {
    Text = "স্বপ্নলোক প্রার্থনা"
  },
  Event_7563_ChoiceDesc1 = {
    Text = "[Never Heard of It]"
  },
  Event_7563_ChoiceDesc2 = {
    Text = "[I've heard of it]"
  },
  Event_7563_Desc = {
    Text = "『মাফ করবেন, আপনার একটু সময় নিতে পারি?\nকিছু স্থানীয় লোককথা শোনাতে আপনাকে কয়েক মিনিটের জন্য আটকে রাখতে চাই।\nআপনি কি 'সার্বেরাস' নামের এক প্রাণীর কথা শুনেছেন?』"
  },
  Event_7563_Name = {
    Text = "অদ্ভুত সঙ্গী I"
  },
  Event_7564_ChoiceDesc1 = {
    Text = "[Quit Thinking] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7564_ChoiceDesc2 = {
    Text = "[অনুপ্রেরণার পিছু নাও]যেকোনো 1টি কমান্ড কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg1)」"
  },
  Event_7564_Desc = {
    Text = "বন্দরটি আক্রমণের মুখে, এক রহস্যময় মালবাহী জাহাজ আসা-যাওয়া করছে আর পাখনাওয়ালা ‘নতুন বন্ধু’রা ঘোরাফেরা করছে... এটি কি নিখুঁতভাবে প্রস্তুত করা ফাঁদ? নাকি আরেকটি অপ্রত্যাশিত বিপদসংকুল যাত্রা?\nবাস্তবতা ও যুক্তি একে অন্যকে টেনে মুচড়ে ধরছে, মনের গভীর থেকে অসংখ্য অনুপ্রেরণা ও চিন্তা উথলে উঠছে।"
  },
  Event_7564_Name = {
    Text = "অনুপ্রেরণার বিস্ফোরণ"
  },
  Event_7565_ChoiceDesc1 = {
    Text = "[Elworth's Volcano?] সর্বোচ্চ HP Arg1 দ্বারা বৃদ্ধি করুন"
  },
  Event_7565_ChoiceDesc2 = {
    Text = "[মনে করার চেষ্টা]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমণ「(Skill.Arg2)」"
  },
  Event_7565_Desc = {
    Text = "লিলির গাল বেয়ে কালো অশ্রু গড়িয়ে পড়ে। \"আমরা দেখেছি, মা,\" সে আস্তে করে হুইসপার করে, \"এলওয়ার্থের আগ্নেয়গিরিতে...\""
  },
  Event_7565_Name = {
    Text = "আগ্নেয়গিরির স্মৃতি"
  },
  Event_7566_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7566_Desc = {
    Text = "「সি@1... ফ্যার...」\nতোমার চোখের সামনে রুনগুলো কখনো জ্বলে ওঠে, কখনো মিলিয়ে যায়; তুমি না চেয়েও হাত বাড়িয়ে শূন্যে সেগুলোকে আঁকড়ে ধরার চেষ্টা কর—\n「কি করছ তুমি?! ওরা কিন্তু ধরে ফেলতে চলেছে!」\nএক রহস্যময়ী মেয়ে তোমাকে ডেকের অন্য প্রান্তের দিকে টেনে নিয়ে যায়, রুনগুলোর সঙ্গে তোমার সংযোগ ছিন্ন করে।\nকিন্তু নিঃসন্দেহে কোনো এক শক্তি তোমার আঙুলের ডগায় তার চিহ্ন রেখে গেছে।"
  },
  Event_7566_Name = {
    Text = "রুন উন্মাদনা"
  },
  Event_7567_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7567_Desc = {
    Text = "ওই সব রহস্যময় বকবকানিতে তোমার কোনো আগ্রহ নেই, আর অন্ধকার রাতে পা বাড়িয়ে উন্মাদনার ঝুঁকিও নিতে চাও না।"
  },
  Event_7567_Name = {
    Text = "একটি সাহায্যের চিঠি"
  },
  Event_7568_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7568_Desc = {
    Text = "যাই হোক না কেন, রক্ষকের দায়িত্ব তোমার বুকে ফুলে ওঠে। প্রেরককে খুঁজে পাওয়ার আশা তুমি ত্যাগ করতে পারো না, যদিও তা এতটাই অস্পষ্ট আর দুর্বোধ্য।"
  },
  Event_7568_Name = {
    Text = "একটি সাহায্যের চিঠি"
  },
  Event_7569_ChoiceDesc1 = {
    Text = "[Observe It] 25টি কালো চিহ্ন পাওয়ার 100% সম্ভাবনা"
  },
  Event_7569_ChoiceDesc2 = {
    Text = "[Pet It] 50% সম্ভাবনায় 50টি কালো চিহ্ন পাবে, 50% সম্ভাবনায় কিছুই পাবে না।"
  },
  Event_7569_Desc = {
    Text = "একটি কালো বিড়াল হঠাৎ পাশের গলির অন্ধকার থেকে লাফিয়ে বেরিয়ে এসে স্নেহভরে তোমার পায়ের সঙ্গে জড়িয়ে গেল। তার ভৌতিক সবুজ উল্লম্ব মণি শীতল আলোয় ঝলসে উঠল, যেন বলছে, \"আমাকে তাড়া কোরো না, এসো, একটু আমার সঙ্গে খেলো।\"\n\"তুমি ইতিমধ্যেই তাঁকে দেখেছ। তিনি ঠিক তোমার পাশেই—যারা উন্মাদনায় দূষিত, সেই উন্মত্ত ছায়ারা... তাঁর অবয়বের দিকে সরাসরি তাকিও না।\""
  },
  Event_7569_Name = {
    Text = "নিশিযামিনীর পরী"
  },
  Event_7570_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7570_Desc = {
    Text = "「অসম্ভব, অবিশ্বাস্য!」 কণ্ঠস্বর চিৎকার করল, 「যে মহিলা আমাকে এই দানবের কাছে পাঠিয়েছে, সে মোটেও সাশা দিদি নয়!」"
  },
  Event_7570_Name = {
    Text = "\"সাশা দিদি\""
  },
  Event_7571_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7571_Desc = {
    Text = "\"গ্রহণ করা হয়েছে। আমরা সাধারণ সামগ্রী সরবরাহ প্রক্রিয়া শুরু করছি। অনুগ্রহ করে পরীক্ষা করে নিশ্চিত করুন।\""
  },
  Event_7571_Name = {
    Text = "সহায়তা যোগাযোগ"
  },
  Event_7572_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7572_Desc = {
    Text = "এটি আর কোনো কাজে আসবে না।"
  },
  Event_7572_Name = {
    Text = "প্রাচীন উত্তরাধিকার"
  },
  Event_7573_ChoiceDesc1 = {
    Text = "[Look Closely] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_7573_ChoiceDesc2 = {
    Text = "[পোস্টার ছিঁড়ে ফেলো]এলোমেলো 1টি কমান্ড কার্ড অরিসন লাভ করে：「(EnchantConfig.Arg1)」，সংক্রমিত হয়「(Skill.Arg2)」"
  },
  Event_7573_Desc = {
    Text = "মোম জাদুঘরে প্রায়ই দেখা যায় এমন এক ক্যান্ডেলাব্রাম।\nভৌতিক কমলা আভায় তুমি দেয়ালে টাঙানো হাতে আঁকা একটি পোস্টার দেখতে পাও।"
  },
  Event_7573_Name = {
    Text = "অন্ধকারে হাসি"
  },
  Event_7574_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7574_Desc = {
    Text = "「লিলির নিজের হৃদয় আছে; তাকে কারও কথা শুনতে হবে না।」 তুমি শান্তভাবে উত্তর দাও।\nফ্রান্সিস নাক সিটকায়, কোনো জবাব দেয় না।"
  },
  Event_7574_Name = {
    Text = "তার পছন্দ"
  },
  Event_7575_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7575_Desc = {
    Text = "এটা একটি দলগত ছবি।\nহতাশ মানুষরা লোহার শিকের আড়ালে গুটিয়ে বসে আছে, তাদের মুখ ভরা যন্ত্রণায়।\nএকটি ছবি তোমার চোখে পড়ে। সে এক কৃশকায় তরুণী, মুখে কোনো অভিব্যক্তি নেই।\nনিন্দিত অঙ্কুরোদ্গম তার দেহ জুড়ে জড়িয়ে আছে।\nতুমি তার মুখ দেখতে পাও না, তবু কল্পনা করো—তার মুখ নিশ্চয়ই অভিব্যক্তিহীন।"
  },
  Event_7575_Name = {
    Text = "হুবহু নথি"
  },
  Event_7576_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7576_Desc = {
    Text = "তুমি মুগ্ধ হয়ে এই চকচকে গহনাগুলোর দিকে তাকিয়ে আছো, একটু অসাবধান হতেই, শুকনো কালো আঠালো হাতটি ধরে ফেলেছো।\nআর সে শুধু সামান্য হাত চেপে ধরলো, তারপর ছেড়ে দিলো।\nকিছুই ঘটলো না, শুধু একটুকরো কালো বাষ্প, তোমার আঙুলের ডগা বেয়ে হাতার ভেতরে ঢুকে গেলো।"
  },
  Event_7576_Name = {
    Text = "উলটপালট দানবীয় থাবা"
  },
  Event_7577_ChoiceDesc1 = {
    Text = "[Play a Few Notes] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_7577_ChoiceDesc2 = {
    Text = "[Close the Lid] 3টি প্রার্থনাগাথার মধ্যে 1টি খোদাই করো"
  },
  Event_7577_Desc = {
    Text = "দেয়ালের পাশে রাখা পিয়ানোর ঢাকনা খোলা। তার কী-গুলো হলদেটে, প্রান্তগুলো ফেটে কাঠের গায়ে পৌঁছে গেছে, তবু প্রতিটি কী যত্নে মুছে পরিষ্কার রাখা হয়েছে।\nএটি অগণিত মানুষের আনন্দের উৎস।"
  },
  Event_7577_Name = {
    Text = "শিশুদের ছড়া"
  },
  Event_7578_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7578_Desc = {
    Text = "বর্শাধারী কাতর স্বরে গোঙাচ্ছে, যেন নির্যাতিত কোনো শিশুর কান্না।\nশব্দটি মুহূর্তেই মিলিয়ে যায়, আর বাকি দুই সাগরচারীও অদৃশ্য হয়ে যায়... আসলে সবই ছিল ডোমেইনে প্রতিফলিত এক মায়াস্বপ্ন।"
