  },
  Event_7579_Desc = {
    Text = "「সঠিক উত্তর।」\nকণ্ঠের মালিক এই উত্তরে অত্যন্ত সন্তুষ্ট হলেন, একটি ঝকঝকে জিনিস জলের উপরে ছুড়ে দেওয়া হলো।\n「মনে রেখো, সবকিছুরই একটা মূল্য আছে।」"
