  Event_7580_ChoiceDesc2 = {Text = "[Leave]"},
  Event_7580_Desc = {
    Text = "ঝাপসা মুখগুলো হঠাৎই আবির্ভূত হয়, তোমাকে ঘিরে ধরে আর অস্তিত্বহীন স্বরযন্ত্র দিয়ে মরিয়া আর্তনাদ তোলে।"
  },
  Event_7580_Name = {
    Text = "বিভ্রম"
  },
  Event_7581_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7581_Desc = {
    Text = "তুমি চিহ্নটিকে উপেক্ষা করে সামনে এগিয়ে যাও।\nকিন্তু যেন ক্রোধে ফেটে পড়ে তা, তোমার প্রতিটি পায়ের ধাপে ফুলে ওঠে আর বেঁকে যায়, যেন ফাটল থেকে কোনো হাত বাড়িয়ে তোমাকে ভেতরে টেনে নিতে চায়।"
  },
  Event_7581_Name = {
    Text = "বিচরণকারী ফাটল"
  },
  Event_7582_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7582_Desc = {
    Text = "তুমি ফাঁদে পড়োনি। দৃঢ়ভাবে ঘুরে দাঁড়িয়ে সেখান থেকে সরে গিয়েছিলে।"
  },
  Event_7582_Name = {
    Text = "বিচরণকারী ফাটল"
  },
  Event_7583_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7583_Desc = {
    Text = "তুমি অস্বাভাবিক ফাটলটি খেয়াল করে তা পরীক্ষা করতে বসে পড়ো। অদ্ভুতভাবে, যে ফাটলটি কিছুক্ষণ আগেও ছড়িয়ে পড়ছিল, হঠাৎই তার বিস্তার থেমে যায়, এবং চিরন্তন নীরবতায় ডুবে যায়।"
  },
  Event_7583_Name = {
    Text = "বিচরণকারী ফাটল"
  },
  Event_7584_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7584_Desc = {
    Text = "না, এটা এক স্বচ্ছ মন। কেবল দৃঢ় সংকল্প দিয়ে তুমি সেই ক্ষয়িত সত্তার মোকাবিলা করতে পারবে না, রক্ষক। তোমার কৌশল নির্ধারণ ভেবে দেখো।"
  },
  Event_7584_Name = {
    Text = "রোগসের নিয়ম"
  },
  Event_7585_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7585_Desc = {
    Text = "তুমি ভেতরের তাগিদকে আর প্রতিহত করতে পারো না।\nতোমার আঙুলগুলো অরণ্যে পথহারা বালকের মতো কীবোর্ডের ওপর ঘুরে বেড়ায়, বাজতে থাকে...\nধীরে ধীরে, টাইপরাইটার থেকে প্রজাপতির উদ্ভাসন ঘটে।\nএকটি, দুটি, তিনটি...\nতোমার মুখে, তোমার আঙুলে, প্রজাপতির ঝাঁক আতশবাজির মতো ঝলসে ওঠে, অন্ধকারে রত্নের মতো দীপ্তি ছড়ায়।\nএই টাইপরাইটারের কোনো বাস্তব প্রয়োগ নেই, কিন্তু সৌন্দর্য সৃষ্টি করার ক্ষেত্রে সে এক অতুলনীয় শিল্পী।"
  },
