  },
  Event_7589_Desc = {
    Text = "ঝড় থেকে বাঁচতে তুমি আশ্রয় নাও পাথরের ফাটলের ভেতর এক সরু গুহায়। কিন্তু তুমি জানো, এখানে বেশিক্ষণ থাকা যাবে না—ওই কালো চাদর পরা লোকগুলো যদি তোমাকে খুঁজে পায়, তবে পালানোর পথ নেই।\nফাটলের এক কোণে তুমি অপ্রত্যাশিতভাবে একটি টেলিগ্রাফ মেশিন আবিষ্কার করো।"
