  },
  Event_7591_ChoiceDesc2 = {
    Text = "[নর্তকীর পদক্ষেপে হোঁচট খাওয়ানো]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」"
  },
  Event_7591_ChoiceDesc3 = {
    Text = "[Steal the Poet's Manuscript] 50টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_7591_Desc = {
    Text = "তুমি তিনটি আঠালো অবয়বের দ্বারা পথরুদ্ধ হও।\nএকটি অবয়ব কর্কশ কণ্ঠে ভৌতিক গানের কথা গাইছে। তুমি কান ঢেকে তাকে এড়িয়ে পাশ কাটিয়ে যাও।\nআরেকটি অবয়ব কাঠের পুতুলের মতো কড়া নড়াচড়ায় দ্বিধাগ্রস্ত পায়ে নৃত্য করছে। তুমি চোখ বন্ধ করে তাকে ফাঁকি দিয়ে সরে যাও।\nশেষ অবয়বটি ভাঙাচোরা বাক্যে খণ্ডিত কবিতা আবৃত্তি করছে। আর সহ্য করতে না পেরে, তুমি—"
  },
  Event_7591_Name = {
    Text = "সংকীর্ণ পথের দুর্বৃত্ত"
  },
  Event_7592_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7592_Desc = {
    Text = "「\n「না! মানবতার দীপ্তির অগ্রগতি ইতিহাস বা প্রযুক্তির ওপর নির্ভর করে না, বরং ইঁদুরের ওপর নির্ভর করে।「\n「ইঁদুরই অন্ধকার যুগের সূচনা করেছিল, আর কেবল তার পরেই মানবতা পুনরুত্থানের ভোরকে স্বাগত জানালো।「\n「মানবতার দীপ্তি তোমাকে প্রয়োজন করে—যদিও সকলে তা বোঝে না।「\nতোমার দীর্ঘ বক্তৃতায় ইঁদুরগুলো কিছুটা বিভ্রান্ত হয়েছিল, তবু তারা শেষ পর্যন্ত তোমাকে ছেড়ে দিল।"
  },
  Event_7592_Name = {
