  },
  Event_7595_ChoiceDesc3 = {
    Text = "[Turn Your Back] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7595_Desc = {
    Text = "তোমার নক্ষত্র দেখার কথা নয়।\nসোনা-নিলের ডোমেইনে আকাশ বয়ে চলা জ্যোতির ঝিলিক দিয়ে ঝিকমিক করে, নক্ষত্র আর চাঁদকে গোপন করে রাখে।\nএই ম্লান কেবিনেও তোমার নক্ষত্র দেখা সম্ভব হওয়ার কথা নয়।\nএখানে থাকার কথা শুধু ছড়িয়ে–ছিটিয়ে থাকা ইনক্যান্ডেসেন্ট বাল্ব আর পুরোনো লণ্ঠন—তবু কেন তুমি এখনো ওপর থেকে নেমে আসা সেই দৃষ্টিকে অনুভব করছ?"
  },
  Event_7595_Name = {
    Text = "আড়চোখে তাকাও"
  },
  Event_7596_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7596_Desc = {
    Text = "\nতুমি সাহস করে চোখগুলোর দিকে সোজা তাকাতে বেছে নিলে।\nওগুলো উজ্জ্বল তারকারাজি, অন্ধকারে ঝিলমিল করছে।\nতারপর তারা হেসে উঠল, আর অসংখ্য অর্ধচন্দ্রে রূপ নিল।\nচোখগুলো বলল, “তুমি দৃষ্টিকে ভয় পাও না। তোমার ভয় পাওয়া উচিত নয়… অনেক দিন পর দেখা, @2।”\nঅদৃশ্য হওয়ার আগে, তারা তোমাকে “পুনর্মিলনের স্মারক” হিসেবে একটি ছোট্ট স্মারক উপহার দিল।"
  },
  Event_7596_Name = {Text = "চোখ"},
  Event_7597_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7597_Desc = {
    Text = "রেলওয়ে সেতু, লেন্ডিনিয়ামের শিরা ও স্নায়ু, শহরের হৃদয় ও অঙ্গ-প্রত্যঙ্গকে সংযুক্ত করে। যতদিন এই স্থান থেকে সূর্য অস্ত না যায়, ততদিন লেন্ডিনিয়ামের হৃদয় চিরকাল উদ্দীপ্ত হয়ে স্পন্দিত হতে থাকবে।"
