  Event_7597_Name = {
    Text = "ইস্পাত সেতুর মরীচিকা"
  },
  Event_7598_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7598_Desc = {
    Text = "একটি অপূর্ব ফিউগ, সুরকার অজানা।\nঅগণিত কণ্ঠস্বর একই থিমে জড়িয়ে গেছে, প্রতিটি নোট সার্জনের স্ক্যালপেলের মতোই শীতল ও নির্ভুল।\nনির্ভুল ও জাঁকজমকপূর্ণ—এটাই রজার্সের নান্দনিকতা।\nফিউগা, উড়ে যাও!"
  },
  Event_7598_Name = {
    Text = "বাজে রুচি"
  },
  Event_7599_ChoiceDesc1 = {
    Text = "[Greet Out Loud]"
  },
  Event_7599_ChoiceDesc2 = {
    Text = "[Seek Help]"
  },
  Event_7599_Desc = {
    Text = "তুমি যখন জাহাজের রেলিংয়ে হেলান দাও, তখনই দেখতে পাও সাদা পোশাক পরা এক মেয়েকে।\nঅভিজাত, নির্মল, অতীন্দ্রিয়... এবং অদ্ভুতভাবে পরিচিত।\nতাকে আগে কোথায় দেখেছ? বিশৃঙ্খল স্মৃতিচারণের স্তূপে হাতড়াতে হাতড়াতে তুমি উত্তর খুঁজতে থাকো, ঠিক তখনই সে যেন হঠাৎ তোমার উপস্থিতি টের পায়, শূন্যতার ওপার থেকে চোখ মেলায় তোমার সঙ্গে।\nতার চোখ বসন্তের শুরুর সাগরের মতো শান্ত, অথচ তুমি অদ্ভুতভাবে সেখানে অন্য কিছুর আভাস পাও...\nমনে হয় সে তোমার অভিবাদনের অপেক্ষায় আছে, অন্তত আজকের আবহাওয়া নিয়েই হোক কিছু কথা।"
  },
  Event_7599_Name = {
    Text = "সাদা পোশাকের কিশোরী"
  },
  Event_7600_ChoiceDesc1 = {
    Text = "[Praise It] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_7600_ChoiceDesc2 = {
    Text = "[Taunt It] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো এবং খোদাই করার প্রার্থনাগাথা পরিবর্তন করো।(ব্যবহার: 1/2)"
  },
  Event_7600_Desc = {
    Text = "জেনকিন বলে: জনি! তুমি আগের থেকে সত্যিই... অনেক আলাদা, যেকোনো দিক থেকে দেখলেই।\nতুমি বলো: তুমি সত্যিই একটি পরিশ্রমী এবং উচ্চাকাঙ্ক্ষী মস্তিষ্ক।\nমস্তিষ্কটি কয়েকবার লজ্জায় মোচড় দিয়ে নড়ে উঠল, স্পষ্টতই অত্যন্ত খুশি।\nমস্তিষ্ক বলে: এসো! যেহেতু তোমরা আমার বর্তমান অর্জনকে এতটা স্বীকৃতি দিচ্ছ, তাহলে আমি তোমাদের আমার সারাজীবনের শিক্ষা প্রদান করব..."
  },
  Event_7600_Name = {
    Text = "দার্শনিকের মস্তিষ্ক"
  },
  Event_7601_ChoiceDesc1 = {
    Text = "[Graceful Fugue] 「(RelicConfig.Arg1)」 নামের রৌপ্য সৃষ্টি অর্জন করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7601_ChoiceDesc2 = {
    Text = "[Simple Serenade] সব জাগরণকারী 50 অ্যালিমাস পাবে, তবে তুমি 「(Skill.Arg1)」 উপসর্গটি বিকশিত করবে।"
  },
  Event_7601_ChoiceDesc3 = {
    Text = "[Meaningless Noise] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_7601_Desc = {
    Text = "「ব্যক্তিগতভাবে, আমি কিউরেটরের সঙ্গীতের রুচির সঙ্গে খুব একটা একমত নই, জানো তো...\nখুব বেশি ঝলমলে, আর আমি মাটির মানুষ।」\nএক ক্লান্ত পুরুষ কণ্ঠস্বর ভেসে এল কড়মড়ে গ্রামোফোন থেকে, একাকী বিলাপ করে।\n「কিন্তু এটাই আমার কাজ... আচ্ছা, সময় বাঁচাই, একটা বেছে নিই।」"
  },
  Event_7601_Name = {
    Text = "বাজে রুচি"
  },
  Event_7602_ChoiceDesc1 = {
    Text = "[Special Relic] একটি সোনালি রেলিক অর্জন করো 「(RelicConfig.Arg1)」"
  },
  Event_7602_ChoiceDesc2 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7602_Desc = {
    Text = "ইভেন্ট 253 (উন্নয়নাধীন), চূড়ান্ত প্রভাব নয়"
  },
  Event_7602_Name = {
    Text = "ইভেন্ট 253 (উন্নয়নাধীন)"
  },
  Event_7603_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7603_Desc = {
    Text = "তুমি যত দ্রুত পারো দৌড়ে পালাও।\nএখন তুমি মুখোমুখি হয়েছ সবচেয়ে ঝামেলাপূর্ণ আর জঘন্য দানবেদের—ঝাঁকে ঝাঁকে আসা মোমের ভাস্কর্যগুলি।\nওদের তুলনায়, এই কাঁচা মাটির পুতুলগুলো কিছুই না।\nঅগ্রাধিকার নির্ধারণ—এটা এমন এক নীতি, যা প্রতিটি রক্ষককেই মেনে চলতে হয়।"
  },
  Event_7603_Name = {
    Text = "খসড়া"
  },
  Event_7604_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7604_Desc = {
    Text = "রৌপ্য চাবি ঝলমল করে, সমগ্র স্থানকে রৌপ্যময় আভায় ভরে তোলে এবং ঘন, প্রবহমান রঙগুলোকে নির্মল রৌপ্যে রূপান্তরিত করে।\nআলো এক মুহূর্তে মিলিয়ে যায়, রেখে যায় শুধু বাতাসের শোকাতুর আর্তনাদ।"
  },
  Event_7604_Name = {
    Text = "স্মৃতির রঙ"
  },
  Event_7605_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7605_Desc = {
    Text = "রঙধনু-ঝলক আপনাকে চোখ-ধাঁধানো আলোয় আচ্ছন্ন করে, আর আপনি টের পাওয়ার আগেই, আপনি মোহগ্রস্ত হয়ে পড়েছেন..."
  },
  Event_7605_Name = {
    Text = "নক্ষত্রের চৌরাস্তা"
  },
  Event_7606_ChoiceDesc1 = {
    Text = "[Descend Further] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_7606_ChoiceDesc2 = {
    Text = "[Pull Away] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7606_Desc = {
    Text = "「তুমি」 তোমাকে ডেকে নিয়ে যায় আরও গভীরে.\nসর্পিলের অন্তঃস্থলে, অতীত আর ভবিষ্যতের 「তুমি」 ভিন্ন ভিন্ন মাত্রা থেকে তোমার কাছে পাঠায় 「উপহার」।"
  },
  Event_7606_Name = {
    Text = "অতল গহ্বর"
  },
  Event_7607_ChoiceDesc1 = {
    Text = "[Understanding] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 দক্ষতাটি বিকশিত করো।"
  },
  Event_7607_ChoiceDesc2 = {
    Text = "[Innocence] 3টি সোনার রেলিক থেকে 1টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7607_ChoiceDesc3 = {
    Text = "[Leave] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_7607_Desc = {
    Text = "দুটি সিলভারি জ্যোতির্ময় অবয়ব তোমার চোখের সামনে উদ্ভাসিত হয়, আঠালো তরল দেহ নিয়ে, বাতাসে ভেসে থাকে।\n“ঠিক এই জায়গাতেই আমি মারা গিয়েছিলাম।” এক অবয়ব নিচু হয়ে বসে।\n“রোগমুক্ত ঈশ্বরের রাজ্যে কামনা আর হারানোর কোনো অস্তিত্ব নেই। তুমি সত্যিই বোঝো না—অস্তিত্বহীন হয়ে যাওয়া মানে কী।”\nঅন্য অবয়বটি দীর্ঘশ্বাস ফেলে, তাঁর দৃষ্টি তোমার দিকে ফেরায়।"
  },
  Event_7607_Name = {
    Text = "বিলুপ্ত দেবলোক"
  },
  Event_7608_ChoiceDesc1 = {
    Text = "[Leave] সার্চলাইট খুঁজুন"
  },
  Event_7608_ChoiceDesc2 = {
    Text = "[Enter the Mist] উপসর্গ 「(Skill.Arg2)」 বিকশিত করো"
  },
  Event_7608_ChoiceDesc3 = {
    Text = "[Enter Directly]"
  },
  Event_7608_Desc = {
    Text = "সামনে ঘন কালো কুয়াশা; হঠাৎ ঢুকে পড়া সর্বনাশ ডেকে আনবে।\nহয়তো তোমার উচিত কুয়াশা সরাতে একটি 「সার্চলাইট」 খুঁজে নেওয়া।"
  },
  Event_7608_Name = {Text = "???"},
  Event_7609_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7609_Desc = {
    Text = "\"ওটা স্মৃতির প্রক্ষেপণ,\" র‍্যামোনা তোমাকে ব্যাখ্যা করল, \"ওটা হয়তো কোনো এক ব্যক্তির, আবার কয়েকজনেরও যৌথ স্মৃতি হতে পারে।\"\nমূল্যবান স্মৃতিগুলো প্রাপ্য সূক্ষ্ম প্রহরার।"
  },
  Event_7609_Name = {
    Text = "আমাদের স্মৃতি"
  },
  Event_7610_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7610_Desc = {
    Text = "এখনই তুমি তা পড়তে না পারলেও, হাল ছাড়ো না। তুমি চিঠিটিকে যত্ন করে ভাঁজ করে পকেটে গুঁজে রাখো, ঠিক করো স্কুলে ফিরে অন্য কোনো উপায়ে তা পড়ার চেষ্টা করবে।\nকিন্তু চিঠিটি যখন রহস্যময়ভাবে মাঝআকাশেই কুঁচকে যেতে থাকে, তোমার বুকে হালকা এক ব্যথা জন্ম নিতে শুরু করে।"
  },
  Event_7610_Name = {
    Text = "দাগলাগা চিঠি"
  },
  Event_7611_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7611_Desc = {
    Text = "দাঁড়িপাল্লা থেকে আলগা হওয়ার মুহূর্তেই মোমবাতিটা জ্বলে ওঠে, দুধসাদা অশ্রু ঝরতে থাকে দ্রুত, তোমার আঙুলের ফাঁক গলে নেমে গিয়ে অদৃশ্য হয়ে যায়।"
  },
  Event_7611_Name = {
    Text = "যুক্তি ও আবেগ"
  },
  Event_7612_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7612_Desc = {
    Text = "তাড়াহুড়ো করে তুমি কাগজটা টাইপরাইটার থেকে টেনে বের কর—কিন্তু যন্ত্রটা চলতেই থাকে। আতঙ্কের সেই ক্ষণে একটি কমান্ড কার্ড ভেতরে গিয়ে পড়ে, আর সবচেয়ে কালো কালি মেখে সম্পূর্ণ অযোগ্য হয়ে যায়।\nতুমি একটু সময় নিয়ে সাবধানে সেটাকে ফেলে দাও, তবু তার গায়ে এখন লেখা প্রতাপময়, পুনরাবৃত্ত সেই বাক্যগুলো চোখ এড়ায় না;\n<Bold:সরাসরি তাকিও না>\n<Bold:সরাসরি তাকিও না>\n<Bold:সরাসরি তাকিও না>\n<Bold:সরাসরি তাকিও না>\n<Bold:সরাসরি তাকিও না>\n<Bold:সরাসরি তাকিও না>\n<Bold:সরাসরি তাকিও না>\n<Bold:সরাসরি তাকিও না>"
  },
  Event_7612_Name = {
    Text = "অনাহূত সতর্কবার্তা"
  },
  Event_7613_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7613_Desc = {
    Text = "তোমার আঙুল যখন কাপের বরফশীতল কিনারায় ছুঁল, এমন ঠান্ডা যে অস্থিমজ্জা পর্যন্ত হিমায়িত হয়ে যায়, তুমি কেঁপে উঠে হঠাৎ সজাগ হলে।\nতবু, এটাকে রাস্তার ধারে ফেলে রাখা ঠিক হবে না। স্যুটকেসে তুলে রাখা-ই ভালো।"
  },
  Event_7613_Name = {
    Text = "মধু মিড"
  },
  Event_7614_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7614_Desc = {
    Text = "তুমি প্রচণ্ড কাশতে থাকো।\nশব্দটা যেন আতঙ্কিত হয়ে থমকে যায়, তারপর নিস্তব্ধতায় ডুবে যায়।\nতোমার মনে হয় তুমি কোনো গুরুত্বপূর্ণ সূত্র হারিয়ে ফেলেছ...\nকিন্তু জীবন তো সবসময়ই হারানো আর আক্ষেপে ভরা, তাই না?"
  },
  Event_7614_Name = {
    Text = "গোপন শ্রোতা"
  },
  Event_7615_ChoiceDesc1 = {
    Text = "[Keep Silent] 25টি কালো চিহ্ন পাওয়ার 100% সম্ভাবনা"
  },
  Event_7615_ChoiceDesc2 = {
    Text = "[Reach Out and Touch] 50% সম্ভাবনায় 50টি কালো চিহ্ন পাবে, 50% সম্ভাবনায় কিছুই পাবে না।"
  },
  Event_7615_Desc = {
    Text = "\"আমি শুধু একটা নীতি বলব—কেউই একটা বিড়ালকে মেরে ফেলতে পারে না!\"\n\"ওই অভিশপ্ত কালো বিড়ালটার পেট ফাঁড়া হয়ে বনে পচে পড়ে থাকার কথা ছিল, কিন্তু সে উল্টে আমার পারিবারিক সমাধি উজাড় করে ফেলল, বাকি থাকা মানবমাংস গিলে খেল আর হাড়গোড়, হাত-পা সব বিক্ষিপ্ত করে ছড়িয়ে দিল।\"\n\"তার ঠান্ডা, অন্ধকার সরু চেরা চোখের নিচে, পচা হলুদ পুঁজ ফুলে উঠছিল, আর আমি দুঃস্বপ্নে পুড়ে, আত্মা শুষে নেওয়া যন্ত্রণায় হামাগুড়ি দিয়ে সরে যাচ্ছিলাম।\"\n\"থামো... তুমি কী করছ? আমি পাগল নই! না! নিশ্চয়ই তোমরা কিছু লুকোচ্ছ! সব সত্যি—\"\nসত্যিই তাই। উন্মাদের ছায়া মিলিয়ে যেতে যেতে, তুমি পায়ের কাছে নিশ্চুপ বসে থাকা কালো বিড়ালটার সঙ্গে চোখাচোখি কর।"
  },
  Event_7615_Name = {
    Text = "রাতের বিড়ালের অভিশাপ"
  },
  Event_7616_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7616_Desc = {
    Text = "তোমার দ্বিধার ফাঁকে, সেটি দ্রবীভূত হয়ে D-চিহ্নে মিশে দ্রুত অদৃশ্য হয়ে গেল।"
  },
  Event_7616_Name = {
    Text = "পিপার ভাসমান বস্তু"
  },
  Event_7617_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7617_Desc = {
    Text = "হতাশায় তুমি চিঠিটা মুঠো করে কুঁচকে পায়ের কাছে ছুড়ে ফেলো।"
  },
  Event_7617_Name = {
    Text = "দাগলাগা চিঠি"
  },
  Event_7618_ChoiceDesc1 = {Text = "[Confirm]"},
  Event_7618_Desc = {
    Text = "তুমি মনোযোগ কেন্দ্রীভূত করো, আর মায়াস্বপ্নটি জলের ভেতর কালি গলে যাওয়ার মতো মিলিয়ে যায়। তুমি সামনে এগিয়ে যাও, কিন্তু হৃদয়ের উপর আঁকা ছায়াটি থেকে যায়।"
  },
  Event_7618_Name = {
    Text = "বিভ্রম"
  },
  Event_7619_ChoiceDesc1 = {
    Text = "[Examine Carefully] 「(RelicConfig.Arg1)」 নামের রৌপ্য সৃষ্টি অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_7619_ChoiceDesc2 = {
    Text = "[Avoid Shadows] 「(RelicConfig.Arg1)」 নামের রৌপ্য সৃষ্টি অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত হবে।"
  },
  Event_7619_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7619_Desc = {
    Text = "রামোনার স্নায়ু টানটান, সে সাবধানে আশ্রয়স্থলের ভেতর দিয়ে এগোয়, জনতাকে এড়িয়ে।\nসে চুপিসারে একটি ছোট ঘরে ঢুকে পড়ে।\nহঠাৎ জানালার বাইরে একটি ছায়া ভেসে ওঠে।"
  },
  Event_7619_Name = {
    Text = "জানালার প্রতিবিম্ব"
  },
  Event_7620_ChoiceDesc1 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_7620_Desc = {
    Text = "এখন সবচেয়ে জরুরি কাজ হলো অপরাধীকে ন্যায়বিচারের মুখোমুখি করা। কিন্তু ক্রোধের বীজ ইতিমধ্যেই তোমার হৃদয়ে শেকড় গেড়েছে। তোমার উত্তর না অপেক্ষা করেই লোকটি ঘুরে দাঁড়াল এবং চলে গেল।"
  },
  Event_7620_Name = {
    Text = "দৈত্যপশুর পদচিহ্ন"
  },
  Event_7621_ChoiceDesc1 = {
    Text = "[Leave] 75টি কালো চিহ্ন গ্রহণ করো, কিন্তু 「(Skill.Arg2)」 নামের উপসর্গটি বিকশিত হবে"
  },
  Event_7621_Desc = {
    Text = "মিথ্যাগে শৈশব থেকে পাওয়া শিক্ষাই তোমার পক্ষে এই ছাপকে উপেক্ষা করা অসম্ভব করে তুলেছে। তুমি ধুলোমাখা পদচিহ্নগুলো মুছে দিলে, আর সেই মুহূর্তে, যেন দূরবর্তী কোনো মাত্রা থেকে একটি সাড়া শুনতে পাও—“ধন্যবাদ”।"
  },
  Event_7621_Name = {
    Text = "দৈত্যপশুর পদচিহ্ন"
  },
  Event_7622_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7622_Desc = {
    Text = "তুমি রৌপ্য চাবি শক্ত করে ধরলে; তার নরম রুপালি আলো আর ক্ষীণ কম্পন তোমাকে সান্ত্বনা দেয়। দৃষ্টি যেন মিলিয়ে যায়, তবু থেকে যায়, তোমার ওপর রেখে যায় এক অদৃশ্য ছাপ।"
  },
  Event_7622_Name = {
    Text = "কার দৃষ্টি?"
  },
  Event_7623_ChoiceDesc1 = {
    Text = "[Find the Secret Path]"
  },
  Event_7623_Desc = {
    Text = "তুমি, রামোনা আর লোটান নরককুকুরটাকে তাড়া করতে আলাদা হয়ে যাও।\n\nতুমি দৌড়ে পার হও কয়েকটি গলি, সামনে হঠাৎই এক বিশাল দেহ ভেসে ওঠে।\nতুমি তাড়া করতে করতে তাকে মোড় ঘুরতে দেখো।\nতুমি গিয়ে ধরো, কিন্তু সামনে এক মৃতপথ—তিন দিকের উঁচু প্রাচীর ঘিরে রেখেছে আকাশের সরু এক চৌকো টুকরো।"
  },
  Event_7623_Name = {
    Text = "মৃতপথ"
  },
  Event_7624_ChoiceDesc1 = {
    Text = "[Walk Past]"
  },
  Event_7624_ChoiceDesc2 = {Text = "[Pat]"},
  Event_7624_Desc = {
    Text = "পরিষ্কার, নরম অপারেশন টেবিলের পাশে পড়ে আছে ইতিমধ্যেই ঢলে পড়া কৌমের দেহ।\nসে এখনও লম্বা, ছোট্ট পাহাড়ের মতো, যেমনটা তুমি প্রথম দেখার সময় মনে রেখেছিলে।\nকিন্তু আকাশের সত্যিকারের 「নরককুকুর」-দের তুলনায়, সে এতই ছোট, যেন কোনো শিশুর মতো।"
  },
  Event_7624_Name = {
    Text = "অবশিষ্ট উষ্ণতা"
  },
  Event_7625_ChoiceDesc1 = {
    Text = "[Get Silver]"
  },
  Event_7625_Desc = {
    Text = "হুঁ, সামনে অনেক ঝকঝকে জিনিস দেখা যাচ্ছে!\nশুঁক... গন্ধটা বেশ ভালো।\nচাট... বরফের মতো শীতল!\nদেখতে খুব দামী কিছু লাগছে। তাড়াতাড়ি এটা ছোট জেনকিনের কাছে নিয়ে চলো, হয়তো আমরা অনেক পনির পেতে পারব, স্কুইক!"
  },
  Event_7625_Name = {
    Text = "ঝলমলে জিনিস"
  },
  Event_7626_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7626_Desc = {
    Text = "অপরিচিত এক হতাশার ঢেউ হৃদয়ে ভেসে ওঠে, আর মায়াবী জাল ধীরে ধীরে বিলীন হয়ে গিয়ে সামনে এগোনোর সলতের পথ উন্মোচন করে।"
  },
  Event_7626_Name = {
    Text = "ভেগাস নেটওয়ার্ক"
  },
  Event_7627_ChoiceDesc1 = {
    Text = "[Comprehend it] এলোমেলো এক জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_7627_ChoiceDesc2 = {
    Text = "[Ignore It] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_7627_Desc = {
    Text = "মাছের আকৃতির সেই জীবের গর্জন থেকে রুনগুলো ঝরে পড়ে, তোমার কান, নাসারন্ধ্র আর গলাকে ভরে ফেলে। তারা তোমার দেহকে দগ্ধ করে। মাত্র দশ সেকেন্ডের মধ্যেই তুমি এই গর্জনের অন্তর্নিহিত গভীর অর্থ অনুধাবন করবে..."
  },
  Event_7627_Name = {
    Text = "রুন উন্মাদনা"
  },
  Event_7628_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7628_Desc = {
    Text = "তুমি দাঁত চেপে বিশৃঙ্খল মায়াভ্রমের প্রতিরোধের চেষ্টা করো। রামোনা তোমার তালুতে একটি ঠান্ডা বস্তু চাপিয়ে দেয়।\n「এই অবশিষ্টাংশটি আমি আবিষ্কার করেছি, হয়তো তোমার কাজে লাগতে পারে।」"
  },
  Event_7628_Name = {
    Text = "মাত্রিক মায়াচিত্র"
  },
  Event_7629_ChoiceDesc1 = {
    Text = "একটি উন্নত প্রার্থনাগাথা বেছে নিন"
  },
  Event_7630_ChoiceDesc1 = {
    Text = "[কাককে চেপে ধরো]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন পাও：「(EnchantConfig.Arg1)」，সংক্রমিত করো「(Skill.Arg2)」"
  },
  Event_7630_ChoiceDesc2 = {
    Text = "[Kill Crow] 3টি প্রার্থনাগাথা থেকে 1টি খোদাই করো"
  },
  Event_7630_ChoiceDesc3 = {Text = "[Leave]"},
  Event_7630_Desc = {
    Text = "একাকী কাকটি কর্কশ স্বরে ডাকে, একে একে নিজের কালো পালক ছিঁড়ে ফেলে।\nব্যথায় কাঁপতে কাঁপতে, তার উন্মত্ত নড়াচড়া যত বাড়ে, ততই নিয়ন্ত্রণহীন চিৎকার ছুটে বেরোয়।\n\"কা—কা—\"\nতার চোখ থেকে নীল অশ্রু ও কালো পিচ্ছিল তরল ধারা বেয়ে নামে, যার সাক্ষী তুমি ছাড়া আর কেউ নয়।"
  },
  Event_7630_Name = {
    Text = "গলিত অশ্রু"
  },
  Event_7631_ChoiceDesc1 = {
    Text = "[Leave] সর্বোচ্চ HP Arg1 বৃদ্ধি পায়"
  },
  Event_7631_Desc = {
    Text = "「আমার ওপর ছেড়ে দাও,」 তুমি আলতো করে দানবটির মেরুদণ্ডে হাত বুলিয়ে দাও, যেন রাগী বিড়ালছানাকে শান্ত করছ, 「সে জেগে উঠবে। আমরা তাকে আঘাত করব না।」"
  },
  Event_7631_Name = {
    Text = "বন্ধুত্বের আহ্বান"
  },
  Event_7632_ChoiceDesc1 = {
    Text = "[Leave] সর্বোচ্চ HP Arg1 দ্বারা বৃদ্ধি করো, তবে 「(Skill.Arg2)」 এবং 「(Skill.Arg3)」 বিকশিত করো।"
  },
  Event_7632_Desc = {
    Text = "「জেগে ওঠো, লিলি। কৌমও চায় তুমি তাড়াতাড়ি জেগে ওঠো—」"
  },
  Event_7632_Name = {
    Text = "বন্ধুত্বের আহ্বান"
  },
  Event_7633_ChoiceDesc1 = {Text = "[Leave]"},
  Event_7633_Desc = {
    Text = "এটি আর কোনো কাজে আসবে না।"
  },
  Event_7633_Name = {
    Text = "নীরব তারবার্তা"
  },
  Event_79429_ChoiceDesc1 = {
    Text = "একজন জাগরণকারী বেছে নাও এবং জীবন আচার-এর মাধ্যমে 「কীটজাতি」 রূপে রূপান্তরিত হও। 「কীটজাতি」র কমান্ড কার্ড-এর খরচ 1 কম অ্যারিথমেটিকা, কিন্তু ব্যবহার শেষে সেগুলো ক্ষয়প্রাপ্ত হয়।"
  },
  Event_79429_Desc = {
    Text = "「স্ব-সচেতনতার প্রক্রিয়া সবসময়ই যন্ত্রণার সঙ্গে জড়িত; রূপান্তর আর মৃত্তিকা বিদীর্ণ পুনর্জন্মের ক্ষেত্রেও তাই।」\nসে স্নিগ্ধ হাসে, স্নেহভরে তোমার মুখে হাত বুলিয়ে দেয়।\n「ভয় পেয়ো না, আমি ঠিক তোমার পাশেই আছি, তাই তোমার আত্মাকে উন্মুক্ত করো, ওদের গ্রহণ করো।」\n「ভালো সন্তান, আমি তোমার মৃত্তিকা বিদীর্ণ পুনর্জন্মের প্রতীক্ষা করছি, প্রতীক্ষা করছি তুমি... আমাদের একজন হয়ে ওঠার।」"
  },
  Event_79429_Name = {
    Text = "আত্মান্তরণ"
  },
  Event_80463_ChoiceDesc1 = {
    Text = "[Leave] 3টির মধ্যে 1টি রৌপ্য সৃষ্টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_80463_Desc = {
    Text = "তুমি এক পথ বেছে নাও, ছোট্ট উইলিয়াম সিনিয়রকে টেনে নিয়ে উন্মত্তের মতো দৌড়াও।\nসৌভাগ্যক্রমে, তোমার নির্বাচন সঠিক ছিল।\nওই মানসিক বিকৃতিগুলো, ওই একের পর এক অভিন্ন ক্লেমেন্টাইন, শেষ পর্যন্ত তুমি তাদের ঝেড়ে ফেলতে পেরেছ।\nঅবশ্যই, তার জন্য তোমাকে মূল্য দিতে হয়েছে।"
  },
  Event_80463_Name = {
    Text = "「ক্লেমেন্টাইন」রা"
  },
  Event_80464_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80464_Desc = {
    Text = "বোধের সীমা ছাড়ানো এক স্মৃতি তোমার মস্তিষ্কে ঢুকিয়ে দেওয়া হয়, যা সরাসরি তোমার যুক্তিবোধকে গুঁড়িয়ে দেয়।\nসে দ্রুতগতির দৃশ্যের ভেতর তুমি কেবল একটি দৃশ্যই মনে রাখতে পারো: ত্রিভুজাকার মন্দির।\nএটি ছিল শ্যাগ@2আইসদের নির্মিত এক মহাসাধনা, অন্ধ মূর্খ দেবতা @4-এর উদ্দেশে।"
  },
  Event_80464_Name = {
    Text = "গভীর স্মৃতি"
  },
  Event_80465_ChoiceDesc1 = {
