  Event_80466_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80466_Desc = {
    Text = "「ক্লিক। ক্লিক। ক্লিক」\n「কাজ」 অবশেষে শেষ হয়, কিন্তু 「কাজ」 ছাড়া তুমি আসলে আর কী পেলে?"
  },
  Event_80466_Name = {
    Text = "চিরন্তন যন্ত্রণা"
  },
  Event_80467_ChoiceDesc1 = {
    Text = "[Leave] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_80467_Desc = {
    Text = "「তোমার আন্তরিক উত্তর শুনে আমি আনন্দিত।」\n「আমাদের পরের সাক্ষাতের অপেক্ষায় রইলাম।」"
  },
  Event_80467_Name = {
    Text = "স্বপ্নের আহ্বান"
  },
  Event_80468_ChoiceDesc1 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_80468_Desc = {
    Text = "「আহ, কী ভণ্ডামি-ভরা বাচ্চা তুমি।」\n「কিন্তু তাতে কিছু যায় আসে না, পরের বার আমি তোমাকে সত্য বলাতে বাধ্য করব।」\n「তোমার হৃদয় আর আত্মা থেকে উগরে ওঠা সব সত্যই।」"
  },
  Event_80468_Name = {
    Text = "স্বপ্নের আহ্বান"
  },
  Event_80469_ChoiceDesc1 = {
    Text = "[Start \"Working\"] একটি কমান্ড কার্ড ধ্বংস করো এবং Arg1 কালো চিহ্ন লাভ করো।"
  },
  Event_80469_ChoiceDesc2 = {
    Text = "[Retreat Far Away]"
  },
  Event_80469_Desc = {
    Text = "「ক্লিক।」\nটাইপরাইটারের শব্দ বেজে ওঠে, আর 「কাজ」 শেষ না হওয়া পর্যন্ত তুমি চিরদিন তার দাস হয়ে থাকবে।"
  },
  Event_80469_Name = {
    Text = "চিরন্তন যন্ত্রণা"
  },
  Event_80470_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80470_Desc = {
    Text = "\"কি দুঃখের কথা, তোমার সতর্কতা তোমাকে সত্য জানার একমাত্র সুযোগটি হারাতে বাধ্য করেছে।\"\nসে দীর্ঘশ্বাস ফেলে, নীরবে বিলীন হয়ে যায়।"
  },
  Event_80470_Name = {
    Text = "গভীর স্মৃতি"
  },
  Event_80471_ChoiceDesc1 = {
    Text = "[All-Out Attack]"
  },
  Event_80471_ChoiceDesc2 = {
    Text = "[Fight and Retreat]"
  },
  Event_80471_Desc = {
    Text = "অপ্রত্যাশিত এক অবয়ব তোমার সামনে এসে দাঁড়াল—সে ক্লেমেন্টাইন।\n\"অবাক হয়ো না, আমি শুধু একটা বিশেষ পরীক্ষা নিতে চাই।\"\n\"পরীক্ষাটা কী নিয়ে, সেটা গোপন।\" ক্লেমেন্টাইন হাসল, \"তোমার জন্য এই পরীক্ষার একমাত্র বিষয়—\"\n\"বেঁচে থাকা।\""
  },
  Event_80471_Name = {
    Text = "বিশেষ পরীক্ষা"
  },
  Event_80472_ChoiceDesc1 = {
    Text = "[Recall the Past]"
  },
  Event_80472_ChoiceDesc2 = {
    Text = "[Pull out the Scales]"
  },
  Event_80472_Desc = {
    Text = "\"দয়া করে আমাকে বিশ্বাস করো, আমি কোনো ক্ষতি করতে চাই না, আমি শুধু তোমাকে সাহায্য করতে চাই।\"\nক্লেমেন্টাইন তোমার পিছু ধাওয়া করে, উচ্চস্বরে চিৎকার করতে থাকে।\nতার ভয়েস অবিশ্বাস্য রকম আন্তরিক শোনায়, তবু তুমি আর কিছুই বিশ্বাস করতে পারো না।\n\"Embodied Cognition Theory\" তোমার নৈতিক বোধকে চূর্ণবিচূর্ণ করে দিয়েছে, আর তোমার সুস্থ মস্তিষ্ক ভেঙে পড়ার প্রান্তে দুলছে।\nতোমাকে অবশ্যই, অবশ্যই কিছু একটা করতে হবে—মাংসে গজিয়ে ওঠা পোকামাকড়ের আঁশের বিরুদ্ধে প্রতিরোধ গড়ে তুলতে, ধীরে ধীরে আত্মায় প্রবেশ করা উন্মাদনা আর হতাশার বিরুদ্ধে দাঁড়াতে।"
  },
  Event_80472_Name = {
    Text = "সংগ্রামী আত্মারা"
  },
  Event_80473_ChoiceDesc1 = {
    Text = "[Leave] যেকোনো 2টি কার্ড ধ্বংস করো"
  },
  Event_80473_Desc = {
    Text = "「চূড়ান্ত যুদ্ধের জন্য শক্তি ধরে রাখতে চাও?」\n「বুদ্ধিমান সিদ্ধান্ত। কিন্তু পাওয়ার সঙ্গে সঙ্গে হারাতেও হয়।」\n「কারণ এই জ্বলন্ত, নিষ্ঠুর পৃথিবীতে টিকে থাকাটাই এক ধরনের মূল্য দাবি করে।」"
  },
  Event_80473_Name = {
    Text = "বিশেষ পরীক্ষা"
  },
  Event_80474_ChoiceDesc1 = {
    Text = "[Ignore It] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_80474_ChoiceDesc2 = {
    Text = "[এটি স্পর্শ করো]এলোমেলো 1টি কমান্ড কার্ড অরিসন লাভ করে：「(EnchantConfig.Arg1)」，সংক্রমিত হয়「(Skill.Arg2)」"
  },
  Event_80474_Desc = {
    Text = "স্পোরের মতো দেখতে এক অদ্ভুত বস্তু তোমার দৃষ্টি কেড়ে নেয়।\nওটা যেন মাংস আর রক্ত দিয়ে গড়া এক সূক্ষ্ম জেলিফিশ, আবার মস্তিষ্কের গভীরে সংকেত বহনকারী স্নায়ুতন্তুর মতোও লাগে।\n\"এসো, আমাকে ছুঁয়ে দেখো,\" নীরবে প্রলুব্ধ করে সে, \"আমি তোমাকে এক নিষ্ঠুর স্মৃতি দেখাব।\""
  },
  Event_80474_Name = {
    Text = "গভীর স্মৃতি"
  },
  Event_80475_ChoiceDesc1 = {
    Text = "[Leave] 3টি প্রার্থনাগাথা থেকে 1টি Engrave করো"
  },
  Event_80475_Desc = {
    Text = "\"“রামোনা, পুতুল, লোটান, ওজিয়ে...”\nআপনি উৎকণ্ঠায় এই নামগুলোই বারবার হুইসপার করতে থাকেন।\nভগ্নবুদ্ধি আর তাদের মুখচ্ছবি স্মরণ করতে পারে না, তবু তারা যে অস্তিত্বের প্রতিনিধিত্ব করে, তা এখনো আপনার হৃদয় ও আত্মাকে উষ্ণ রাখে।\nতারা ছিল, তারা হেসেছিল, তারা... এই মুহূর্তে আপনার মানবতার দীপ্তি অটুট রাখার ন্যূনতম রেখা ও নোঙর।\""
  },
  Event_80475_Name = {
    Text = "সংগ্রামী আত্মারা"
  },
  Event_80476_ChoiceDesc1 = {
    Text = "[Leave] 3টির মধ্যে 1টি রৌপ্য সৃষ্টি অর্জন করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকশিত করো।"
  },
  Event_80476_Desc = {
    Text = "「আআআআআ—」\nতুমি মুখ খুলে চিৎকার করলে; সেই শব্দ, আর্তনাদের চেয়ে, বরং বেশি এক কর্কশ কিচিরমিচিরের মতো。\nউপড়ে ফেলা পোকামাকড়ের আঁশগুলো আবার গজিয়ে ওঠে, আর তোমার ভাঙা সুস্থবুদ্ধি চিরতরে হারিয়ে যায়।"
  },
  Event_80476_Name = {
    Text = "সংগ্রামী আত্মারা"
  },
  Event_80477_ChoiceDesc1 = {
    Text = "[Leave] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_80477_Desc = {
    Text = "তুমি কিছুই গোপন রাখো না, সর্বশক্তি দিয়ে ঝাঁপিয়ে পড়ো। এই ভঙ্গি স্পষ্টতই ক্লেমেন্টাইনকে সন্তুষ্ট করে।\n“কি ভালো বালক।”\n“সে ক্ষেত্রে, তোমাকে একটু পুরস্কার দিই। অবশ্যই, এরও একটা মূল্য আছে।”\n“এই দাউদাউ করে জ্বলা নিষ্ঠুর জগতে, বেঁচে থাকাটাই এক ধরনের মূল্য দাবি করে।”"
  },
