  Event_80479_ChoiceDesc2 = {
    Text = "[Run to the Right]"
  },
  Event_80479_Desc = {
    Text = "এক পরিচিত অবয়ব নিরলসভাবে তোমাকে তাড়া করে—একটা-দুটো নয়, ডজন ডজন, শত শত।\nএতগুলো 「ক্লেমেন্টাইন「-কে সরু করিডর ধারণ করতে পারে না, তাই কিছু 「ক্লেমেন্টাইন「 মাটিতে ধাক্কা খেয়ে পড়ে, কিছু আবার পদদলনে কাদায় মিশে যায়।\nকিন্তু তারা সবাই একসঙ্গে তোমাকে ডাকে, বারবার উচ্চারণ করে সেই বাক্য, যা তোমার মস্তিষ্কে বিষক্রিয়া ছড়ায়।\n「তুমি দৌড়াচ্ছ কেন? আমি তো শুধু তোমাকে একবার পরামর্শ দিতে চেয়েছিলাম।「\nআর তুমি স্যানাটোরিয়ামের করিডর জুড়ে উন্মত্তের মতো দৌড়াও, সামনে দ্বিখণ্ডিত পথের নির্বাচন মুখোমুখি হয়ে।"
  },
