  },
  Event_80480_Desc = {
    Text = "「সংশোধন! কাজ! থেমো না!」\nঅগণিত গুঞ্জন তোমার কানে প্রতিধ্বনিত হয়, তোমাকে টেনে নিয়ে যায় হঠাৎ উদ্ভূত টাইপরাইটারের দিকে।\n「কি করি, কি করি, সকাল থেকে রাত পর্যন্ত টাইপ করে যাচ্ছি, তবু কাজ যেন শেষই হয় না।」\n「সংশোধন! সংশোধন! পরিকল্পনা সংশোধন করো, দাবি পেশ করো, কাজ সম্পন্ন করো!」\n「কাজ! কাজ!! কাজ!!」\nগুঞ্জনরত আত্মা অবিরাম টাইপ করতে থাকা টাইপরাইটারের গায়ে আছড়ে পড়ে, আর অবশেষে সেই টাইপরাইটার থেমে যায়।\nকিন্তু এক মুহূর্ত পরই, সেই টাইপরাইটার আবারও সচল হয়।\n「সংশোধন! কাজ! থেমো না!」\nকারণ কাজের কোনো শেষ নেই।"
  },
  Event_80480_Name = {
    Text = "চিরন্তন যন্ত্রণা"
  },
  Event_80481_ChoiceDesc1 = {
    Text = "[Answer Honestly]"
  },
  Event_80481_ChoiceDesc2 = {
    Text = "[Refuse to Answer]"
  },
  Event_80481_Desc = {
    Text = "এক নিমেষে তোমার সামনে থাকা দৃশ্য ঝাপসা ও মায়াবী হয়ে ওঠে।\nতুমি প্রথমে ভাবো ঘরটাই বুঝি মোচড়াচ্ছে, সরে যাচ্ছে; কিন্তু পরে বুঝতে পারো, আক্রমণ করা হয়েছে তোমার দৃষ্টিনাড়িকে।\n「আবার দেখা হলো।」\nঝাপসা দৃষ্টিক্ষেত্রে ক্লেমেন্টাইন মৃদু হাসে।\n「যদিও আমাদের দেখা হওয়ার কথা ছিল আরও পরে, তবু আমি খুবই আনন্দিত। ভাবছি, তুমি, %player%, কি একই অনুভব করছো?」"
  },
  Event_80481_Name = {
    Text = "স্বপ্নের আহ্বান"
  },
  Event_80595_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80595_Desc = {
    Text = "\nতোমার তাড়িয়ে দেওয়ার প্রতিক্রিয়ায় প্রজাপতি নির্বিকার থাকে।\nসে অবিরাম তাড়া করে তোমার তালু, আর তোমার হাতের তালুর ভেতরেই হারিয়ে ফেলে তার প্রাণশক্তি।\n\"আহ, কত উষ্ণ...\"\nএটাই ছিল তার শেষ হুইসপার।"
  },
  Event_80595_Name = {
    Text = "প্রজাপতির স্বপ্ন"
  },
  Event_80596_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80596_Desc = {
    Text = "「আমি চাই ফুল চিরকাল ফুটে থাকুক, আমি চাই হাসি চিরন্তন হোক।」\n「আমি চাই ক্ষয়রোগে আক্রান্ত সকলে সুস্থ ও নিরাপদ হোক, আমি চাই এই পৃথিবী আবার আগের মতো হোক, আর জ্বলতে না থাকুক।」\n「আমি চাই……」\nছোট্ট প্রজাপতিটি তার ডানা ঝাপটাতে ঝাপটাতে তোমার হাতের তালুতে প্রাণ হারিয়ে ফেলল।\nঅন্তত, কেউ একজন তার কণ্ঠস্বর শুনেছিল।"
  },
  Event_80596_Name = {
    Text = "প্রজাপতির স্বপ্ন"
  },
  Event_80597_ChoiceDesc1 = {
    Text = "[প্রজাপতি তাড়াও]এলোমেলোভাবে 1টি কমান্ড কার্ড অরিসন পায়：「(EnchantConfig.Arg1)」，「(Skill.Arg2)」সংক্রমিত করো"
  },
  Event_80597_ChoiceDesc2 = {
    Text = "[Listen to Their Wish] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_80597_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_80597_Desc = {
    Text = "ছোট্ট প্রজাপতিটিরও অনেক স্বপ্ন আছে।\nএই স্বপ্নগুলো ছড়িয়ে আছে ফুলের সমুদ্রে, হাসপাতালের কক্ষে, আর রক্তমাংসে পরিপূর্ণ @2 বেদিতে।\nআর আজ, সে অবশেষে তার বন্ধনের মানুষটিকে পেয়েছে। জানি না তুমি তার ছোট্ট, ছোট্ট ইচ্ছাটি শুনতে রাজি কিনা।"
  },
  Event_80597_Name = {
    Text = "প্রজাপতির স্বপ্ন"
  },
  Event_80610_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80610_Desc = {
    Text = "\"যুক্তিবাদ? মজার উত্তর।\"\n\"আশা করি তুমি তোমার নির্বাচন নিয়ে অনুতপ্ত হবে না।\""
  },
  Event_80610_Name = {
    Text = "মানবতার মূল্য"
  },
  Event_80612_ChoiceDesc1 = {
    Text = "[Feed Them] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো, তবে 3টি উপসর্গের মধ্যে 1টি বিকশিত করো।"
  },
  Event_80612_ChoiceDesc2 = {
    Text = "[Pay No Mind] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো, তবে 「(Skill.Arg2)」 উপসর্গটি বিকশিত করো।"
  },
  Event_80612_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_80612_Desc = {
    Text = "বাসিন্দারা আসে আর যায়, অথচ ইঁদুরের ঝাঁকটি যেন অনন্ত পর্যন্ত প্রসারিত।\nমানুষের তুলনায়, এই দুর্গের প্রকৃত \"স্থানীয়\" তো তারাই।\nকিন্তু মানুষ এখানে এসে বাসা বাঁধলে তাদের কোনো আপত্তি নেই।\nকারণ ওই নরম আর সাদা কুৎসিত জিনিসগুলো তাদের খাওয়াবে ঠিক ততটাই নরম আর সাদা কুৎসিত জিনিস।\n\"আর তুমি, কুৎসিত জিনিস, তুমি কোন দলে পড়ো?\""
  },
  Event_80612_Name = {
    Text = "প্রাচীন দুর্গের রহস্য"
  },
  Event_80613_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80613_Desc = {
    Text = "\nঅন্ধকারের ভেতর থেকে কোমল এক হাসি ভেসে আসে।\n\"আমি তোমার প্রতীক্ষায় আছি, আমার সঙ্গে দেখা করতে।\"\n\"সাহসী ছোট্ট পোকা।\""
  },
  Event_80613_Name = {
    Text = "「তাঁর」 দৃষ্টি"
  },
  Event_80614_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80614_Desc = {
    Text = "「চুপ কর, চুপ কর, তোমার আওয়াজ ভয়াবহ।」\nকালো বিড়ালটি অদ্ভুতভাবে মানবসুলভ ভঙ্গিতে নিজের কান দুটো থাবা দিয়ে চেপে ধরে।\n「মানুষ, তোমার বিড়াল-ভাষা খুবই খারাপ, তুমি যা বলছ তার কোনো মানে হয় না!」\nএ কথা বললেও, কালো বিড়ালের অভিব্যক্তি কিছুটা নরম হয়ে আসে।\n「যেহেতু তুমি আমাকে খুশি করতে মিউ মিউ করেছ, আমি তোমাকে একটি উপহার দিয়ে যাচ্ছি।」\n「উপহারের ভেতরে কী আছে, তা তোমার ভাগ্যের ওপর নির্ভর করছে।」"
  },
  Event_80614_Name = {
    Text = "নিগেলম্যান"
  },
  Event_80615_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80615_Desc = {
    Text = "\n\"মাতৃদর্শন, বন্ধু, স্বামী আর পুত্রকে হারানোর পর, আজ আমি চিরতরে হারালাম ডায়ানাকে, আমার ছোট্ট কন্যাকে।\"\n\"যখন সে আমার চোখের সামনে ভস্ম হয়ে গেল, আমার মস্তিষ্ক শূন্য হয়ে গেল...\" পরের লেখা আর পাঠোদ্ধারযোগ্য নয়।\nতুমি কেবল পরের লাইনটায় চোখ বুলাও।\nআমি সিদ্ধান্ত নিয়ে ফেলেছি। যদি আবার তোমার সঙ্গে দেখা হয়, দয়া করে আমাকে দোষ দিও না; আমি শুধু... তোমাদের সবাইকে ভীষণ মিস করি।"
  },
  Event_80615_Name = {
    Text = "বিলীন স্মৃতিকাতরতা"
  },
  Event_80616_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80616_Desc = {
    Text = "তোমার তাড়িয়ে দেওয়ার আচার কার্যকর হয়। কয়েকটি অস্পষ্ট দেহ মোচড়াতে মোচড়াতে পালিয়ে যায়, অধিকাংশই থেকে যায়।\nতারা আর হাসে না, মন্ত্রোচ্চারণও করে না, বরং হাউমাউ করে কাঁদে।\nএক শিশুর কান্না তোমার কানে ফেটে পড়ে, বারবার উচ্চারণ করে মাত্র একটি বাক্য।\n\"দানবটাকে মেরে ফেলো!\""
  },
  Event_80616_Name = {
    Text = "「তাঁর」শৈশব"
  },
  Event_80617_ChoiceDesc1 = {
    Text = "[Leave] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_80617_ChoiceDesc2 = {
    Text = "[Leave] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_80617_ChoiceDesc3 = {
    Text = "[Leave] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো"
  },
  Event_80617_Desc = {
    Text = "তোমার ভোজন ইঁদুরের ঝাঁককে সন্তুষ্ট করে。\nবিশাল ঝাঁকটি কিলবিলিয়ে ওঠে, আর তোমাকে দেয় অমার্জিতভাবে মোড়ানো এক উপহার。\nতুমি তার আকার বুঝতে পারো না, শুধু দেখো মোড়কজুড়ে গাঢ় রক্তের দাগ চুঁইয়ে উঠেছে।"
  },
  Event_80617_Name = {
    Text = "প্রাচীন দুর্গের রহস্য"
  },
  Event_80618_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80618_Desc = {
    Text = "「...」 \n「...」\n「......」\nছায়াটি নীরব থাকে, কাঁদতে চায়, কিন্তু আর কান্নার ক্ষমতা নেই.\nশেষমেশ সে কেবল গভীর এক দীর্ঘশ্বাস ফেলে.\n「বন্ধু, আশা করি তুমি তোমার সবচেয়ে মূল্যবান জিনিসগুলো রক্ষা করতে পারবে।」"
  },
  Event_80618_Name = {
    Text = "ফাঁপা মানুষ"
  },
  Event_80619_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80619_Desc = {
    Text = "আপনার ধমক কোনো কাজে আসেনি, বরং তাদের আরও উন্মত্ত ও উল্লসিত করে তুলেছে।\nহাসি-ঠাট্টা আর গানের সুর আরও উচ্চ হয়ে উঠল, তারা আরেকটি ছড়া গাইতে লাগল।\n「ছোট্ট উইলিয়াম, পুরনো দুর্গে থাকে, মানুষখেকো ইঁদুর, দেয়ালের মাঝে ছোটে।\nযখন আসে নরবলির সময়, সবাইকে কুরে কুরে খায় তারা সমূলে।」"
  },
  Event_80619_Name = {
    Text = "「তাঁর」শৈশব"
  },
  Event_80620_ChoiceDesc1 = {
    Text = "[Avoid Gaze] যেকোনো এক জন জাগরণকারীকে এলোমেলোভাবে জাগরণ ঘটাও"
  },
  Event_80620_ChoiceDesc2 = {
    Text = "[Stare] জাগরণ ঘটানোর জন্য একটি জাগরণকারী বেছে নাও, সেই কার্ডের অ্যারিথমেটিকা ব্যয় 2 কমাও, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_80620_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_80620_Desc = {
    Text = "স্যানাটোরিয়ামের সবকিছুই তার নিয়ন্ত্রণ ও নজরদারির আওতায়। অবশ্যই, তুমিও।\nকিন্তু তোমার ক্ষেত্রে সে একটুখানি অন্ধ চোখ হতে রাজি।\nশেষ পর্যন্ত, খেলা তখনই বেশি আকর্ষণীয় হয়, যখন তা দু’পক্ষের জন্যই সমান হয়।"
  },
  Event_80620_Name = {
    Text = "「তাঁর」 দৃষ্টি"
  },
  Event_80621_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80621_Desc = {
    Text = "তুমি খামটি আবার আগের জায়গায় রেখে চলে যেতে উদ্যত হও, কিন্তু হঠাৎই স্বপ্নলোকের মতো এক অস্পষ্ট গুঞ্জন শোনো।\n「আমার অনুরোধে, ডা. ক্লেমেন্টাইন শেষ পর্যন্ত নরম হলেন।\nতিনি যে বিশাল, রহস্যময় মহাবিশ্বের কথা আমাকে বর্ণনা করেছেন, সেখানে নিশ্চয়ই তোমাদের সবাইকে বাঁচানোর কোনো পথ আছে।\nআমি ইতিমধ্যেই 」মৃত্তিকা বিদীর্ণ পুনর্জন্ম「-এর জন্য প্রস্তুত। যত আলোকবর্ষ ভেসে বেড়াতে হোক না কেন, আমি আবার একবার তোমাদের দেখতে আকুল।」"
  },
  Event_80621_Name = {
    Text = "বিলীন স্মৃতিকাতরতা"
  },
  Event_80622_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80622_Desc = {
    Text = "ড. ক্লেমেন্টাইন আমাকে বাঁচিয়েছেন।\nতিনি সত্যিই খুব, খুব ভালো মানুষ, আমার কথা শুনতে রাজি।\nআমি খুব চাই কিছু আনন্দের, সুখের কথা বলতে, অথচ এই মুহূর্তে আমার কাছে আছে শুধু যন্ত্রণা আর হতাশা।\nআমি ভয় পাচ্ছি, আমি হয়তো চিকিৎসকের প্রত্যাশা পূরণ করতে পারব না।\nতোমাকে হারানোর পর, আমার কাছে জীবন হয়ে গেছে এক বিরান প্রান্তর।"
  },
  Event_80622_Name = {
    Text = "বিলীন স্মৃতিকাতরতা"
  },
  Event_80623_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80623_Desc = {
    Text = "「তুমি, তুমি...」\n「হুঁ, মন্দ না কৌশল—এইবার, তুমি পাস করলে। পরের বার কিন্তু এত সহজ হবে না!」\nকালো বিড়ালটি চটপট লাফিয়ে সরে যায়, আর বাকিরাও তার অনুসরণ করে।"
  },
  Event_80623_Name = {
    Text = "নিগেলম্যান"
  },
  Event_80624_ChoiceDesc1 = {
    Text = "[Attack the Cat] 50% সম্ভাবনায় 125টি কালো চিহ্ন প্রাপ্ত হও, 50% সম্ভাবনায় 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_80624_ChoiceDesc2 = {
    Text = "[Meow Like a Cat] 75% সম্ভাবনায় 100টি কালো চিহ্ন প্রাপ্ত হও, 25% সম্ভাবনায় 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_80624_ChoiceDesc3 = {
    Text = "[Attempt to Pet the Cat] 50টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_80624_Desc = {
    Text = "「এই! তুমি, ওখানেই থামো।」\nকালো বিড়ালগুলো ছায়া থেকে লাফিয়ে বেরিয়ে এসে তোমার পথ ব্লক করে।\nতারা সুশ্রী ভঙ্গিতে থাবা চেটে নেয়, তাদের আচরণ উদ্ধত আর গর্বিত।\n「সামনের সলতের পথ ভরা বিপদে, তা কোনো দুর্বল মানুষের অনুসন্ধানের বিষয় নয়।」\nতুমি এগিয়ে যাওয়ার অভিপ্রায় প্রকাশ করো। বিড়ালের দঙ্গলটির নেতার তারারন্ধ্র সরে যায়, শিকার নিয়ে খেলা করার নিষ্ঠুর অভিপ্রায় উন্মোচিত হয়। 「তাহলে আমাদের তোমার অভিপ্রায় দেখাও।」"
  },
  Event_80624_Name = {
    Text = "নিগেলম্যান"
  },
  Event_80625_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80625_Desc = {
    Text = "\nতোমার অবহেলায় ইঁদুরের ঝাঁক ক্রুদ্ধ হয়ে কিচিরমিচির করতে করতে তোমার দিকে ঝাঁপিয়ে আসে, আর তুমি, ইঁদুরের জোয়ার ওঠার অনেক আগেই বহু দূরে পালিয়ে গিয়েছ।"
  },
  Event_80625_Name = {
    Text = "প্রাচীন দুর্গের রহস্য"
  },
  Event_80626_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80626_Desc = {
    Text = "「আহ, ঠিক এভাবেই, আমার ডানা ভেঙে দাও।」\n「সময়, স্বাস্থ্য, মর্যাদা, জীবন—ওরা আমার কাছ থেকে খুব বেশি কেড়ে নিয়েছে।」\n「এই শেষ স্বপ্নটি, অবশ্যই, আমার নয়।」\n「কারণ আমি তো কেবল এক পাখি, বন্দী, স্বাধীনতা থেকে বঞ্চিত।」"
  },
  Event_80626_Name = {
    Text = "ফাঁপা মানুষ"
  },
  Event_80627_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80627_Desc = {
    Text = "「অনুভূতিপ্রবণ? মজার উত্তর।」\n「আশা করি তুমি তোমার নির্বাচন নিয়ে অনুতপ্ত হবে না।」"
  },
  Event_80627_Name = {
    Text = "মানবতার মূল্য"
  },
  Event_80628_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80628_Desc = {
    Text = "「আমি তোমার প্রার্থনা গ্রহণ করছি।」\nগুঞ্জনধ্বনি কাছে এগিয়ে এল, ধীরে ধীরে কানের পথ ধরে মস্তিষ্কে গেঁথে যেতে লাগল।\nতোমার মস্তিষ্ক কেঁপে উঠল, আর সেই কম্পনের ভেতর তুমি শুনলে মহাবিশ্বের 「কণ্ঠস্বর」।\n「আমার সঙ্গে সংযোগ স্থাপন করো।」"
  },
  Event_80628_Name = {
    Text = "অন্ধকার মুক্তি"
  },
  Event_80629_ChoiceDesc1 = {
    Text = "[Pray] এলোমেলো এক জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো।"
  },
  Event_80629_ChoiceDesc2 = {
    Text = "[Refuse] 3টি প্রার্থনাগাথা থেকে 1টি খোদাই করো"
  },
  Event_80629_Desc = {
    Text = "「এভাবে হওয়ার কথা ছিল না, এভাবে হওয়ার কথা ছিল না।」\n「আমার তো স্পষ্ট, স্পষ্টভাবেই এই নীচু মানবজীবন থেকে বিচ্ছিন্ন হয়ে আরও উচ্চতর কিছুতে বিবর্তিত হওয়ার কথা ছিল...」\nঅন্ধকারে যন্ত্রণাময় হাউমাউ কান্নার শব্দ প্রতিধ্বনিত হয়।\nসেই কান্নাগুলো জমে উঠে, ফুলে ফেঁপে এক বিরাট গুঞ্জনে রূপ নেয়।\n「এই জ্বলন্ত পৃথিবী, এক অতৃপ্ত কৃষ্ণগহ্বরের মতো, প্রতিটি মানুষকে একে একে গ্রাস করে, তাই—」\n「আমার কাছে প্রার্থনা করো, অসীম মহাবিশ্ব তোমাকে মুক্তি দেবে।」"
  },
  Event_80629_Name = {
    Text = "অন্ধকার মুক্তি"
  },
  Event_80630_ChoiceDesc1 = {
    Text = "[Open the Envelope] সোনালি নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_80630_ChoiceDesc2 = {
    Text = "[Read] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_80630_ChoiceDesc3 = {
    Text = "[Put it back] ৫০টি কালো মুদ্রা অর্জন করো"
  },
  Event_80630_Desc = {
    Text = "একটি অবহেলিত কোণে, একটি চিঠি পড়ে আছে।\nচিঠির বহু শব্দ আর পড়া যায় না, কিন্তু একটি শব্দ রয়ে গেছে। তা কাগজ ভেদ করে বেরিয়ে এসেছে।\nসেই শব্দটি হলো \"মা\"।"
  },
  Event_80630_Name = {
    Text = "বিলীন স্মৃতিকাতরতা"
  },
  Event_80631_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80631_Desc = {
    Text = "「হুঁহ, তুচ্ছ মানব, তুমি ভুল নির্বাচন করেছ।」\nকালো বিড়ালগুলো শীতল চোখে তোমার দিকে তাকিয়ে থাকে, তারপর হঠাৎই পাল্টা আঘাত হানে.\n「সাহসীদের প্রতি আমাদের সম্মান আছে বটে, কিন্তু তার মূল্য তোমাকেই চুকাতে হবে।」"
  },
  Event_80631_Name = {
    Text = "নিগেলম্যান"
  },
  Event_80632_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80632_Desc = {
    Text = "\nঅন্ধকারের ভেতর থেকে কোমল এক হাসি ভেসে আসে।\n\"আমি তোমার প্রতীক্ষায় আছি, আমার সঙ্গে দেখা করতে।\"\n\"সুন্দর ছোট্ট পোকা।\""
  },
  Event_80632_Name = {
    Text = "「তাঁর」 দৃষ্টি"
  },
  Event_80633_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80633_Desc = {
    Text = "তোমার আক্রমণের নিচে, এই বিকৃত ও বিকলাঙ্গ অবয়বগুলো অবশেষে মুক্তি পেল।\nচারপাশ নিস্তব্ধ, কেবল তোমার হৃদস্পন্দন নীরবে ক্রন্দন করছে।\nপ্রকাশ পেল, এটাই ছিল 「তাঁর」শৈশব।"
  },
  Event_80633_Name = {
    Text = "「তাঁর」শৈশব"
  },
  Event_80635_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80635_Desc = {
    Text = "「আহা, ছোট্ট লেখার ফাঁদটা ধরা পড়ে গেল।」\n「এটা এক পুরস্কার। কারণ...」\n「প্রতিটি নির্বাচন করতেই হবে, এমন কোনো নিয়ম নেই।」"
  },
  Event_80635_Name = {
    Text = "মানবতার মূল্য"
  },
  Event_80636_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80636_Desc = {
    Text = "“@3 বিদ্রোহী”\nগুঞ্জনধ্বনি ধীরে ধীরে ক্ষীণ হয়ে মিলিয়ে যায়, রেখে যায় কেবল শেষ কথাগুলো।\n“মানবতার দীপ্তি আঁকড়ে ধরে থাকলে এই নিষ্ঠুর জগতে টিকে থাকা যায় না।”"
  },
  Event_80636_Name = {
    Text = "অন্ধকার মুক্তি"
  },
  Event_80637_ChoiceDesc1 = {
    Text = "[Refuse] একটি কমান্ড কার্ড ধ্বংস করো এবং Arg1টি কালো চিহ্ন গ্রহণ করো।"
  },
  Event_80637_ChoiceDesc2 = {
    Text = "[Comply] একটি কমান্ড কার্ড নকল করো, কিন্তু 「(Skill.Arg1)」 উপসর্গ বিকাশ করো।"
  },
  Event_80637_ChoiceDesc3 = {
    Text = "[Embrace] 3টি কমান্ড কার্ডের মধ্যে 1টিতে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_80637_Desc = {
    Text = "「আমি এক খাঁচাবন্দি পাখি, অনেক কক্ষ-ঘেরা এক উঠোনে আটকে আছি।」\nঅন্ধকারে অস্পষ্ট অবয়বেরা ঘুরে বেড়ায়—মৃতদের আবেশের অবশিষ্টাংশ।\n「ওরা বলে এটা আশ্রয়স্থল, কিন্তু আমি জানি, এটা মানুষের জন্য এক বিশেষ খাঁচা, যে খাঁচায় সমাজের নিয়মাবলী মানতে না চাওয়া মুক্ত পাখিদের বন্দি করে রাখা হয়।」\n「কিন্তু কোনো পাখি যদি উড়তে না পারে, তাকে কি তখনও পাখি বলা যায়?」\nআবেশগুলো তোমার চারপাশে জড়ো হয়, মুক্তির জন্য মিনতি জানায়।\n「দয়া করে আমার ডানা ভেঙে দাও, আমি উড়তে উড়তে ক্লান্ত।」"
  },
  Event_80637_Name = {
    Text = "ফাঁপা মানুষ"
  },
  Event_80638_ChoiceDesc1 = {Text = "[Leave]"},
  Event_80638_Desc = {
    Text = "「...」 \n「...」\n「......」\nছায়াটি হঠাৎ কেঁপে ওঠে এবং গলে গিয়ে তোমার দেহে মিশে যায়.\n「বন্ধু, এগিয়ে চলো, তোমার সবচেয়ে মূল্যবান জিনিসগুলো রক্ষা করার জন্য।」\n「আমরা যদিও বহু আগেই বিলীন হয়েছি, তবু তোমার স্বপ্নের জন্য আমাদের শেষ আশীর্বাদটুকু দিতে রাজি আছি...」"
  },
  Event_80638_Name = {
    Text = "ফাঁপা মানুষ"
  },
  Event_80639_ChoiceDesc1 = {
    Text = "[Choose Emotion] Arg1 HP পুনরুদ্ধার করো"
  },
  Event_80639_ChoiceDesc2 = {
    Text = "[Maintain Rationality] একটি এলোমেলো কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 উৎকীর্ণ করো।"
  },
  Event_80639_ChoiceDesc3 = {
    Text = "[Refuse to Choose] 25টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_80639_Desc = {
    Text = "\"নির্বাচন করো, নির্বাচন করো।\"\nদৌড়ে চলা অন্ধকারের ভেতর, অসংখ্য হুইসপার প্রতিধ্বনিত হতে থাকে।\nভয়েসটি কোমল, সম্মোহনী, যেন অসীম জাদু বয়ে আনে, যা তোমার ভেতরে এক ধরনের উন্মত্ত মায়াভ্রম জাগিয়ে তোলে।\nতোমার মস্তিষ্ক উন্মাদনায় ডুবে যায়, দেহ থেকে কিলবিলিয়ে সরে যেতে থাকে, আর হৃদয় যেন নিজস্ব এক চেতনা অর্জন করেছে—চিৎকার করছে, তোমাকে ডাকছে।\n\"নির্বাচন করো, নির্বাচন করো।\"\n\"যুক্তিবোধ নাকি অনুভূতি; তোমাকে একটি নির্বাচন করতেই হবে।\""
  },
  Event_80639_Name = {
    Text = "মানবতার মূল্য"
  },
  Event_80641_ChoiceDesc1 = {
    Text = "[Scold \"Them\"] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg2)「 অর্জন করো, কিন্তু 「(Skill.Arg1)「 বিকশিত করো।"
  },
  Event_80641_ChoiceDesc2 = {
    Text = "[Drive \"Them\" Away] রৌপ্য সৃষ্টি 「(RelicConfig.Arg2)「 এবং 「(RelicConfig.Arg3)「 অর্জন করো, কিন্তু 「(Skill.Arg1)「 দু」বার বিকশিত করো।"
  },
  Event_80641_ChoiceDesc3 = {
    Text = "[Attack \"Them\"] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো।"
  },
  Event_80641_Desc = {
    Text = "「ছোট্ট উইলিয়াম, কী যে বিকার, \nঘুমায় কবরেতে, শীতল অন্ধকার।\nকেউ তাকে ভালোবাসে না, দূরে থাকো তাই, \nনইলে একদিন পেছন থেকে ছুরি বসাবে ভাই।」\nআকৃতিগুলো, যাদের রূপ ঝাপসা আর দেহ বিকৃত, বালকেরা-সুলভ কণ্ঠে কথা বলে।\nতারা বিদ্রূপ করে আর মন্ত্রোচ্চারণের মতো গেয়ে চলে, তোমার দিকে তাকিয়ে থাকে অবজ্ঞা আর এক অদ্ভুত লালসায় ভরা চোখে।\nতাদের দেহ থেকে নিখাদ বিদ্বেষ বিকিরিত হয়।"
  },
  Event_80641_Name = {
    Text = "「তাঁর」শৈশব"
  },
  Event_90571_ChoiceDesc1 = {
    Text = "[Indulge] আপনার ডেকে 1টি 「সোলসফিস্ট স্পেশাল ব্লেন্ড」 শাফল করুন।"
  },
  Event_90571_Desc = {
    Text = "একটি বিশাল ভোজের টেবিল, প্রাণচঞ্চল নৃত্যমঞ্চ, আড়ম্বরপূর্ণ বাসনকোসন, আর পচা দেহের ঘন গন্ধ...\nওহ, জানি তুমি আর অপেক্ষা করতে পারছ না, কিন্তু আরেকটু ধৈর্য ধরো, প্রিয় অতিথি।\nএই পানীয়টি, ভোজসভার স্বয়ং আয়োজকের বিশেষ প্রস্তুতি, সম্মানিত অতিথিদের জন্য একচেটিয়া উপহার।\nএটিকে হাতে নাও। চুমুক দাও। আর তার দীর্ঘস্থায়ী আফটারটেস্টে, নিজেকে ডুবিয়ে দাও এই উল্লাসময় আসরে!"
  },
  Event_90571_Name = {
    Text = "ভোজপূর্ব আচার"
  },
  Event_91460_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91460_Desc = {
    Text = "তোমার কোনো প্রতিরক্ষা নেই, তুমি শুধু সেই শব্দকে তোমার ভেতর দিয়ে ভেদ করে যেতে দিতে পারো।\nএকটা তীক্ষ্ণ আর্তনাদ তোমার মস্তিষ্ক চিরে ফেলে, আর কোনো বিস্মৃত আতঙ্ক সেখানে থেকে উথলে ওঠে—তুমি তার ক্ষুধা অনুভব করো।\nএক ভয়াবহ নরখাদক সত্তা..."
  },
  Event_91460_Name = {
    Text = "নীরব স্বীকারোক্তি"
  },
  Event_91461_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91461_Desc = {
    Text = "তুমি আর নিজেকে আটকে রাখো না, সেই জ্বলন্ত আবেগকে সম্পূর্ণভাবে মুক্ত করো, অউচ্চারিত সব শব্দ নিরন্তর বিস্ফোরিত হতে থাকে তোমার মনের গভীর থেকে।\nতুমি এক অপূর্ব অন্তর্দৃষ্টি অনুভব করো, পিকম্যানের প্রতিভায় নিজেকে ডুবিয়ে দাও।"
  },
  Event_91461_Name = {
    Text = "সুপ্ত আগ্নেয়গিরি"
  },
  Event_91462_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91462_Desc = {
    Text = "আগুনের শিখা কালির দাগ ঘিরে পাক খেয়ে, পেছনে রেখে যায় রক্তছিটার রেখা।\nসেই মুহূর্তে, তুমি পড়ে গেলে স্বপ্নলোক আর বাস্তবতার সীমানায়। তুমি দেখলে, তুমি নিজেই এক ছোট্ট মেয়েতে রূপান্তরিত হয়েছ, ডোরেসেইন-এর হাত ধরে তার সঙ্গে নাচছ।\nজেগে উঠে যখন আবার ডোরেসেইন-এর দিকে তাকালে, এক ভারী বিষণ্নতা তোমার মনকে আচ্ছন্ন করে ফেলল।"
  },
  Event_91462_Name = {
    Text = "স্বপ্নের প্রত্যাদেশ"
  },
  Event_91463_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91463_Desc = {
    Text = "তুমি ঝাঁপিয়ে এগিয়ে যাও, শিখাগুলো তোমার ত্বকের নিচে মিলিয়ে যায়। আর সেই ছবিটি—যে-ই দেখুক না কেন, তার কাছে তা কেবলই একটি সাধারণ প্রতিকৃতি বলে মনে হয়।\nপরবর্তী স্বপ্নগুলোতে তুমি নিজেকেই বারবার জ্বলতে দেখো—পরিপূর্ণভাবে ভাজা—একদিন নিজেরই ডাইনিং টেবিলে পরিবেশিত হওয়ার আগে।"
  },
  Event_91463_Name = {
    Text = "জ্বলন্ত প্রতিকৃতি"
  },
  Event_91464_ChoiceDesc1 = {
    Text = "[Listen] 30টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_91464_ChoiceDesc2 = {
    Text = "[Ignore] প্রস্থান"
  },
  Event_91464_Desc = {
    Text = "নিঃশব্দ কোলাহলের ভেতর, তুমি ধীরে ধীরে কাকের কথাগুলো বুঝতে শুরু করো..."
  },
  Event_91464_Name = {
    Text = "নীরব স্বীকারোক্তি"
  },
  Event_91465_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91465_Desc = {
    Text = "তুমি একটি পাথর কুড়িয়ে নাও, আর মনোযোগী, কুরে খাওয়া ইঁদুরের ছায়াদের জাগরণ ঘটাও।\nতারা লোভী চোখে তোমার দিকে তাকিয়ে থাকে।\nতাদের দেহ থেকে ভেসে আসে স্যাঁতসেঁতে, নোংরা গন্ধ, যেন কোনো অশুভ পূর্বলক্ষণ।"
  },
  Event_91465_Name = {
    Text = "নির্বাসিত রাজ্য"
  },
  Event_91466_ChoiceDesc1 = {
    Text = "[Listen] 25টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_91466_ChoiceDesc2 = {
    Text = "[Ignore] প্রস্থান"
  },
  Event_91466_Desc = {
    Text = "ওটা স্বাগত জানাচ্ছে। কাকে স্বাগত?\nঅবশ্যই, তোমাকেই!\nহয়তো সে তোমাকে আগামীকালের সুস্বাদু খাদ্য হিসেবে দেখছে।"
  },
  Event_91466_Name = {
    Text = "নীরব স্বীকারোক্তি"
  },
  Event_91467_ChoiceDesc1 = {
    Text = "[হাতের তালু কাটুন]3টি কমান্ড কার্ড থেকে 1টি বেছে নিয়ে অরিসন লাভ করে：「(EnchantConfig.Arg1)」，সংক্রমিত হয়「(Skill.Arg2)」"
  },
  Event_91467_ChoiceDesc2 = {
    Text = "[Accept Growth] সিলভার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_91467_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_91467_Desc = {
    Text = "ওই প্রজাপতিটা উড়ে আসেনি, বরং ধীরে ধীরে গজিয়েছে তোমার হাতের তালু থেকে।\nশুরুতে তুমি ভেবেছিলে ওটা শুধু ঘাম, কিন্তু আঙুলের ফাঁকে দেখলে কালো তরল শিরার উল্টো স্রোতের মতো চুঁইয়ে বেরোচ্ছে, জমাট বেঁধে ঠান্ডা, স্পন্দিত ডানায় রূপ নিচ্ছে।\nপ্রতিবার সে ডানা ঝাপটায়, তোমার রক্তপ্রবাহ জুড়ে ঢেউ খেলে যায়।"
  },
  Event_91467_Name = {
    Text = "পরজীবী"
  },
  Event_91468_ChoiceDesc1 = {
    Text = "[প초상 উদ্ধার]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমিত করুন「(Skill.Arg2)」"
  },
  Event_91468_ChoiceDesc2 = {
    Text = "[শূন্যতা গ্রহণ]3টি কমান্ড কার্ড থেকে 1টি বেছে অরিসন অর্জন করুন：「(EnchantConfig.Arg1)」，সংক্রমিত করুন「(Skill.Arg2)」"
  },
  Event_91468_ChoiceDesc3 = {
    Text = "[Leave] ২৫টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_91468_Desc = {
    Text = "তুমি দাঁড়িয়ে আছ পিকম্যানের উপহারের সামনে。\nএটি রক্তে আঁকা এক প্রতিকৃতি, যার গাঢ় কালো শিখা নীরবে জ্বলছে。\nচিত্রের মানুষের ফাঁপা চোখের গহ্বর দিয়ে তুমি দেখতে পাও—\nনিজের স্মৃতিগুলো উথলে উঠছে আর জ্বলছে, প্রসারিত হচ্ছে, বিকৃত হচ্ছে, দীপ্ত হচ্ছে, যেন কোনো আকারহীন আগুন তোমার মনের করিডরগুলো চেটে বেড়াচ্ছে। বিভোরতার মধ্যে তুমি একটি কণ্ঠস্বর শোনো。\n「রান্না শুরু করার সময় হয়েছে। আঁচ এখন একদম ঠিক।」\nএটাই তোমার নিজ হাতে নির্মিত স্মৃতির দৃশ্য—তুমি শিখার ভেতর পেঁচিয়ে ওঠো, মোচড়াও।"
  },
  Event_91468_Name = {
    Text = "জ্বলন্ত প্রতিকৃতি"
  },
  Event_91469_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91469_Desc = {
    Text = "তুমি উত্তর দিতে অস্বীকার করো, চুপচাপ তাকিয়ে থাকো তার কম্পনের দিকে, যতক্ষণ না তা থেমে যায়।\nএত বছর ধরে তুমি উন্মাদনার বিরুদ্ধে লড়াই করতে শিখে গেছো।"
  },
  Event_91469_Name = {
    Text = "মিসড কল"
  },
  Event_91470_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91470_Desc = {
    Text = "তুমি এক পা পিছিয়ে এসে ক্যানভাসটিকে আগুনে পুড়তে দাও।\nতুমি দেখো, তোমার নিজের ছবিটি কীভাবে লোভনীয় সোনালি-বাদামি রঙে রূপ নিচ্ছে, চর্বি সসস শব্দে ফেটে ফেটে ঝলসে উঠছে। যেন ক্যানভাসের ওপার থেকেও ভাজা মাংসের গন্ধ নাকে এসে লাগে।\nডোরেসেইন কি এমনই প্রলোভন অনুভব করে?"
  },
  Event_91470_Name = {
    Text = "জ্বলন্ত প্রতিকৃতি"
  },
  Event_91471_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91471_Desc = {
    Text = "প্রায় অবমাননাকর কৌতূহলে, অথবা হয়তো অজানার মুখোমুখি হওয়ার এক মরিয়া সাহসে তাড়িত হয়ে, তুমি অতীতের ছায়ার ভেতর থেকে প্রত্যাদেশ খুঁজতে থাকো।\nতুমি দেখো এক মেয়ে নাচছে এক লম্বা পুরুষের সঙ্গে, যার মুখ অস্পষ্ট; আর এক অকারণ উল্লাস তোমার হৃদয় ভরে ফেলে।"
  },
  Event_91471_Name = {
    Text = "অতীতের ছায়া"
  },
  Event_91472_ChoiceDesc1 = {
    Text = "[End Record] যেকোনো 2টি কার্ড ধ্বংস করো"
  },
  Event_91472_ChoiceDesc2 = {
    Text = "[Continue Writing] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_91472_ChoiceDesc3 = {
    Text = "[Leave] Arg1টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_91472_Desc = {
    Text = "তুমি অবশেষে কষ্টেসৃষ্টে সাময়িকভাবে ঘুলদের বাজার থেকে পালিয়ে আসতে পেরেছ, একটি নির্জন কোণ খুঁজে নিয়ে আগের মতোই লিপিবদ্ধ করতে বসেছ।\nটাইপরাইটারটি হঠাৎ প্রচণ্ড কাঁপতে শুরু করল, তার কী-গুলো নিজে নিজেই ওপর-নিচে উঠানামা করছে, আর ফাঁকফোকর থেকে উগরে পড়ছে কালো আঠালো তরল, যা ছিটকে পড়ছে তোমার আঙুলের ডগায়, ভিজিয়ে দিচ্ছে তোমার সুস্থ বিবেচনাকে।\nতুমি দেখলে কাগজের ওপর ধীরে ধীরে উদ্ভাসিত হচ্ছে এক প্রজাপতির ছায়া, ক্রমে হয়ে উঠছে স্পষ্ট ও জীবন্ত..."
  },
  Event_91472_Name = {
    Text = "প্রজাপতির ছায়া"
  },
  Event_91473_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91473_Desc = {
    Text = "অদ্ভুত, এ ভাষা তুমি কখনও শেখোনি, তবু কোনোভাবে তার অর্থ বুঝতে পারছো।\nপংক্তিগুলো ভরা প্রিয়জনের জন্য আকুলতায়—এক এমন আকুলতা, যা জীবন-মৃত্যুকেও অতিক্রম করে, তোমার স্বপ্নের মাধ্যমে তোমার কাছে পৌঁছে যায়।\nকবিতার শেষে থাকা হাতের লেখা তুমি অস্পষ্টভাবে চিনতে পারো—\nওটা সেলিনার।"
  },
  Event_91473_Name = {
    Text = "স্বপ্নের প্রত্যাদেশ"
  },
  Event_91474_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91474_Desc = {
    Text = "তুমি সহনশীলতা নিয়ে নিজের তালুর চামড়া চিরে ফেলো, আগুনের শিখা দিয়ে পুড়িয়ে দাও সদ্য গজানো ডানাওয়ালা মাংস।\nকালো তরল বাষ্প হয়ে উড়ে যায় আর প্রজাপতিগুলো ভেঙে চুরমার হয়।\nসবকিছু আবার হয়ে ওঠে পরিষ্কার আর দাগহীন, তবু তুমি তালুতে এক ক্ষীণ ডানা ঝাপটানোর অনুভূতি এড়াতে পারো না, যেন কোনো কখনো পুরোপুরি ডিম ফোটানো না-হওয়া চিন্তা এখনো ধীরে ধীরে শ্বাস নিচ্ছে তোমার শিরায়।\nডোরেসেইন এ বিষয়ে কোনো মতামত দেয় না, শুধু নিয়ে নেয় তোমার ফেলে যাওয়া রক্ত।"
  },
  Event_91474_Name = {
    Text = "পরজীবী"
  },
  Event_91475_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91475_Desc = {
    Text = "তুমি জানো, উন্মত্ত অন্তর্দৃষ্টি সবসময় মহাবিপর্যয় ডেকে আনে, তাই তুমি সবকিছু যুক্তির শৃঙ্খলে সিল করে দাও।"
  },
  Event_91475_Name = {
    Text = "সুপ্ত আগ্নেয়গিরি"
  },
  Event_91476_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91476_Desc = {
    Text = "তুমি স্থির দৃষ্টিতে চোখটির দিকে তাকিয়ে তার বার্তাটি বোঝার চেষ্টা করো।\nযদিও তুমি বহুদিন ধরেই যুদ্ধে পাকা, তবু এবার গোলিয়াথের মুখোমুখি হয়ে... ভয় তোমার হৃদয়কে চেপে ধরে।\n「প্রায় স্বাভাবিক— মহাবিপর্যয় ঘটার আগে এটাই সবচেয়ে নীরব রূপ।」"
  },
  Event_91476_Name = {
    Text = "প্রায় স্বাভাবিক"
  },
  Event_91477_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91477_Desc = {
    Text = "তুমি চোখ বন্ধ করে ঘুরে দাঁড়াও, প্রান্তরের ভেতর হাঁটতে শুরু করো।\nতুমি গোপন কামনা আর অশুভ পূর্বলক্ষণ টের পাও, কিন্তু নিজের হাতে তুমি তা কখনোই প্রশমিত করতে পারবে না।\nতুমি চারপাশের নামহীন সমাধিফলকগুলোর দিকে তাকাও। হয়তো এভাবেই তোমার গল্পের সমাপ্তি লেখা আছে।"
  },
  Event_91477_Name = {
    Text = "দাঁড়কাকের ভোজ"
  },
  Event_91478_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91478_Desc = {
    Text = "তুমি ধীরে ধীরে মাথা তোলো। সেই মুহূর্তে, আলো তোমার মণিতে বিদ্ধ হয়, আর দগ্ধ তাপ তোমার মস্তিষ্কের ভেতরে এক শূন্যতার ফুল ফোটায়।\nনেক্রোভিয়ার নক্ষত্রগুলো অন্য কোথাওয়ের নক্ষত্রের থেকে ভিন্ন নয়, তবু তথাকথিত চিরন্তন ঘুলেরাও কেবল ওই নক্ষত্রের নীচেই বাঁচতে পারে, মুক্তি ছাড়াই।"
  },
  Event_91478_Name = {
    Text = "নক্ষত্রের রাত"
  },
  Event_91479_ChoiceDesc1 = {
    Text = "[Throw into the Flames] একটি কার্ড ধ্বংস করো"
  },
  Event_91479_ChoiceDesc2 = {
    Text = "[Attempt Interpretation] রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, কিন্তু 「(Skill.Arg2)」 উপসর্গ বিকশিত করো।"
  },
  Event_91479_Desc = {
    Text = "তোমার চেতনা ভেসে বেড়ায় অন্তহীন কালো কুয়াশার সাগরে, অগণিত জীবিত আর মৃত আত্মার মানসিক ভূদৃশ্য পেরিয়ে যায়।\nতোমার স্বপ্নে, এক অদ্ভুত টাইপরাইটার অজানা কবিতার এক প্যাসেজ টুকে চলে। এ কার গল্প?\nঅজানা জীব কাগজের ওপর তা ছাপ হয়ে থাকে, বিকৃত হস্তাক্ষর যেন এক সজাগ মাতালের লেখা।\nস্বপ্নের ভেতরের এক অবর্ণনীয় তাড়নায় তুমি কাগজটা তুলে নাও—চুলোর মিটমিট আলোয় কালি যেন নেচে ওঠে।"
  },
  Event_91479_Name = {
    Text = "স্বপ্নের প্রত্যাদেশ"
  },
  Event_91480_ChoiceDesc1 = {
    Text = "[Apply] এলোমেলো একটি কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg2)」 খোদাই করো, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_91480_ChoiceDesc2 = {
    Text = "[Drive] এলোমেলো একটি কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg2)」 খোদাই করো, তবে 「(Skill.Arg1)」 বিকশিত করো।"
  },
  Event_91480_ChoiceDesc3 = {
    Text = "[Ostracise] এলোমেলো একটি কমান্ড কার্ডে প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 খোদাই করো।"
  },
  Event_91480_Desc = {
    Text = "তুমি শুনতে পাও হাড়ের বাঁশির ক্ষীণ, দূরাগত শব্দ।\nকালো কাদামাটি থেকে ইঁদুরের ঝাঁক উঠে আসে, সেই শব্দে আকৃষ্ট হয়ে শুকনো নদীর তলায় পড়ে থাকা নামহীন মৃতদেহটিকে কুরে কুরে খেতে থাকে।\nতারা একটি বৃত্ত গঠন করে—কেন্দ্রে ফাঁপা অবশিষ্ট দেহ, আর পরিধি জুড়ে বিস্মৃতির বিধানে শাসিত এক নতুন রাজ্যের সীমানা আঁকা হয়।\nআর তুমি দাঁড়িয়ে আছ এই রাজ্যের প্রবেশদ্বারে।"
  },
  Event_91480_Name = {
    Text = "নির্বাসিত রাজ্য"
  },
  Event_91481_ChoiceDesc1 = {
    Text = "[Look Up] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_91481_ChoiceDesc2 = {
    Text = "[Black Sigil] 75টি কালো চিহ্ন গ্রহণ করো, কিন্তু 「(Skill.Arg2)」 নামের উপসর্গটি বিকশিত হবে"
  },
  Event_91481_Desc = {
    Text = "আকাশে কাকেরা ঘুরপাক খায় দ্বিধাগ্রস্ত করাতের মতো, বারবার কেটে চলে স্বর্গের মেরুদণ্ড।\nতারা তোমার চারপাশে নিচু হয়ে উড়ে, যেন তোমার মৃত্যুকে আগাম দেখে ফেলেছে, ধৈর্য ধরে ভোজের সূচনার অপেক্ষায়।"
  },
  Event_91481_Name = {
    Text = "দাঁড়কাকের ভোজ"
  },
  Event_91482_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91482_Desc = {
    Text = "তুমি তাকে লিখে যেতে দিলে—তোমার নাড়ির স্পন্দন, তোমার যন্ত্রণাবোধ, তোমার অতীত আর তোমার কল্পনাশক্তি দিয়ে।\nপ্রজাপতি কাগজের বন্ধন ছিঁড়ে বেরিয়ে আসে, আর তোমার আত্মা তার সঙ্গে উড়ে যায়।\nতুমি নিজেকে কল্পনা করতে শুরু করো বিনোদন পার্কে আনন্দ উপভোগ করতে। ডোরেসেইনকে তুমি যা বলোনি, তা হলো—আসলে তুমি সত্যিই বিনোদন পার্ক পছন্দ করো, এমনকি সেটা যদি লাশ-থিমেরও হয়...\nআশা করি... সেটা খুব বেশি বিকৃত হবে না।"
  },
  Event_91482_Name = {
    Text = "প্রজাপতির ছায়া"
  },
  Event_91483_ChoiceDesc1 = {
    Text = "[Reobserve] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে যেকোনো একটিতে খোদাই করো।"
  },
  Event_91483_Desc = {
    Text = "একদা স্বচ্ছ যে নৈশভোজ, তা রক্তাক্ত, অস্পষ্ট এক ভোজসভায় রূপ নিয়েছে। তুমি চুলোর ওপর থাকা উপকরণগুলোর কথা মনে করো, আর পচনের দুর্গন্ধ তোমার নাকে আক্রমণ করে।\nভয় তোমার হৃদয় চেপে ধরে—তোমাকে একটি নির্বাচন করতেই হবে।"
  },
  Event_91483_Name = {
    Text = "অতীতের ছায়া"
  },
  Event_91484_ChoiceDesc1 = {
    Text = "[Ignore the Ring] 3টি উন্নত প্রার্থনাগাথা থেকে 1টি খোদাই করো"
  },
  Event_91484_ChoiceDesc2 = {
    Text = "[Pick up the Receiver] 「(RelicConfig.Arg1)」 নামের সোনার রেলিক অর্জন করো, কিন্তু 「(Skill.Arg2)」 বিকশিত হবে"
  },
  Event_91484_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_91484_Desc = {
    Text = "ওটা বাজা উচিত ছিল না—ক্যানভাসের পেছনে গুটিয়ে থাকা টেলিফোনটা।\nতার তার মোটা যন্ত্রদেহের চারপাশে জংধরা নাভিরজ্জুর মতো পেঁচিয়ে আছে, যেন তোমার নিজের মস্তিষ্ক থেকে প্রসারিত হয়েছে।\nতুমি সাবধানে কম্পনের কম্পাঙ্ক নির্ণয় করো; সেই অদ্ভুত শব্দ তোমাকে পিকম্যানের অতিবাস্তব শিল্পের কথা মনে করিয়ে দেয়।"
  },
  Event_91484_Name = {
    Text = "মিসড কল"
  },
  Event_91485_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91485_Desc = {
    Text = "তুমি দোলনার মতো আগলে নাও ঠান্ডা মস্তিষ্কটিকে, কিন্তু মুহূর্তের মধ্যেই তা জলে পরিণত হয়ে নীরবে আঙুল ফাঁক গলে সরে যায়。\nদাঁড়িপাল্লা সঙ্গে সঙ্গে ভারসাম্য হারায়, আর হৃদয়টি পচা ফলের মতো ভেঙে পড়ে, গলে গিয়ে হয়ে যায় নিঃশব্দ, কালো জলের এক পুকুর。\nসব ক্ষুধা মিলিয়ে যায়; তুমি এখন ধারণ করো শীতল এক স্থিরতা, অনুতাপহীন, আর ক্ষণিকের এক স্বচ্ছতা।"
  },
  Event_91485_Name = {
    Text = "ক্ষুধার খেলা"
  },
  Event_91486_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91486_Desc = {
    Text = "কোনো শব্দ নেই, কোনো সাড়া নেই। তবে কি এটা শুধু এক প্রহসন ছিল?\nতুমি রিসিভারটা নামিয়ে রাখতেই এক ভারী আবেগ ঢেউয়ের মতো ফিরে এসে তোমাকে ভিজিয়ে দেয়।"
  },
  Event_91486_Name = {
    Text = "মিসড কল"
  },
  Event_91487_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91487_Desc = {
    Text = "কাকটি অদৃশ্য হয়ে যায়।\nকিন্তু তুমি দেখো আরেক রাতের আয়নায় দাঁড়িয়ে থাকা নিজেকে, সেই কাকটির দিকে তাকিয়ে।\nসে এখনো নীরবে চিৎকার করে চলে, যেন তোমার প্রতিক্রিয়ার প্রতীক্ষায়।"
  },
  Event_91487_Name = {
    Text = "নীরব স্বীকারোক্তি"
  },
  Event_91488_ChoiceDesc1 = {
    Text = "[Reobserve] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে যেকোনো একটিতে খোদাই করো।"
  },
  Event_91488_ChoiceDesc2 = {
    Text = "[Give Up] 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো এবং যে প্রার্থনাগাথা খোদাই করা হবে তা বদলাও।(ব্যবহার: 1/2)"
  },
  Event_91488_Desc = {
    Text = "তুমি দৃঢ়চেতা হয়ে দৃষ্টি ফিরিয়ে নাও, তবু সেই সব ছবি ভূতের মতো দৃষ্টিক্ষেত্রে লেগে থাকে...\nএটা এক শোকাবহ দ্বৈত সঙ্গীত।"
  },
  Event_91488_Name = {
    Text = "অতীতের ছায়া"
  },
  Event_91489_ChoiceDesc1 = {
    Text = "[Consume] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_91489_ChoiceDesc2 = {
    Text = "[Decline] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো এবং খোদাই করার প্রার্থনাগাথা পরিবর্তন করো।(ব্যবহার: 2/2)"
  },
  Event_91489_Desc = {
    Text = "ওটা ডোরেসেইন অত্যন্ত যত্ন নিয়ে প্রস্তুত করেছিল তোমার কঠোর তদন্তের পুরস্কার হিসেবে।\nমসলা-বিহীন তবু গন্ধহীন, ডোরেসেইনের ভাষায়, এ-ই সর্বোত্তম উপাদান।\nভোজসভা তোমার জন্য সাজানো, আর থালায় নীরবে শুয়ে আছে মস্তিষ্ক।\n「স্বাদ নিয়ে দেখতে চাও?」"
  },
  Event_91489_Name = {
    Text = "উপাদেয় আহারের স্বাদ নিন"
  },
  Event_91490_ChoiceDesc1 = {
    Text = "[Listen] 40টি কালো চিহ্ন গ্রহণ করো, 「(Skill.Arg2)」 বিকাশ করো এবং নির্বাচন চালিয়ে যাও।"
  },
  Event_91490_ChoiceDesc2 = {
    Text = "[Disregard] 25টি কালো চিহ্ন গ্রহণ করে চলে যাও।"
  },
  Event_91490_Desc = {
    Text = "ওটা এক কাক।\nখুলি-আকৃতির প্রদীপের ওপর দাঁড়িয়ে, সে ঠোঁট মেলে, কিন্তু কোনো শব্দ বেরোয় না।"
  },
  Event_91490_Name = {
    Text = "নীরব স্বীকারোক্তি"
  },
  Event_91491_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91491_Desc = {
    Text = "তুমি ধীরে ধীরে হাত বাড়াও সেই এখনো‑উষ্ণ হৃদয়ের দিকে; তা ধুকপুক করে, সংকুচিত হয়, অবশেষে সুগন্ধি উষ্ণ বাষ্পে মিলিয়ে যায়。\nদাঁড়িপাল্লা প্রচণ্ডভাবে কেঁপে ওঠে, আর তোমার মস্তিষ্ক ধেয়ে পড়ে অন্তহীন অন্ধকারে。\nপরিতৃপ্তির অনুভূতি ক্ষুধাকে প্রতিস্থাপন করে, আর তুমি অনুধাবন করো আবেগ, যন্ত্রণা, আর প্রকৃত স্মৃতিচারণ।"
  },
  Event_91491_Name = {
    Text = "ক্ষুধার খেলা"
  },
  Event_91492_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91492_Desc = {
    Text = "তুমি মাথা উঁচু করো, নীরব ঘূর্ণনকে স্বাগত জানিয়ে, যেন কোনো প্রাচীন আচার অনুষ্ঠানের তীর্থযাত্রী।\nতারা আনন্দে তোমার মাংসে ভোজ দেয়; তুমি যন্ত্রণা অনুভব করো, তবু এক অদ্ভুত স্বচ্ছতা।\nতুমি দেখো তোমার হারিয়ে যাওয়া সত্তাকে—যে অংশগুলো মরতে ব্যর্থ হয়েছিল—অবশেষে ছিনিয়ে নেওয়া হচ্ছে।\nচেতনা ফিরে এলে তুমি নিজেকে অক্ষত অবস্থায় পাও।"
  },
  Event_91492_Name = {
    Text = "দাঁড়কাকের ভোজ"
  },
  Event_91493_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91493_Desc = {
    Text = "তুমি স্মৃতি আর আবেগের সিমেন্ট দিয়ে চাবির ছিদ্র সিল করে দিলে, সত্যকে প্রলোভনের শক্তিহীন করে।\nভয়ংকর শত্রুর মুখোমুখি হওয়ার মতো তোমার ভঙ্গি দেখে ডোরেসেইন ঠোঁট চাটল।\n「আরেকবার চেষ্টা করে দেখতে চাও? এটি বিশেষভাবে প্রস্তুত ব্রেইনলিফ মোৎজারেলা, একান্তই গোপনরক্ষক {Male=মহোদয়, Female=মিস} মহাশয়ের জন্য।」"
  },
  Event_91493_Name = {
    Text = "প্রত্যাদেশ"
  },
  Event_91494_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91494_Desc = {
    Text = "আসলে, ঘুল হয়ে ওঠার অভিজ্ঞতা নিয়ে তুমি সবসময়ই কৌতূহলী ছিলে।\n「তাই তুমি ইঁদুরের ঝাঁকের ভেতর পা বাড়াও, আর তাদেরই একজন হয়ে যাও—」\nস্বীকার করতেই হবে, সাগরচারীর আগমন তোমার চিন্তাকে কিছুটা ঝাপসা করে দিয়েছে।"
  },
  Event_91494_Name = {
    Text = "নির্বাসিত রাজ্য"
  },
  Event_91495_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91495_Desc = {
    Text = "তুমি পচন আর কেওসের কলুষে নিজেকে দাগাতে অস্বীকার করো।\nঅনেক আগেই তুমি এতে অভ্যস্ত হয়ে গেছ; সব ক্ষয়ই এখন তোমার কাছে স্বাভাবিক বলে মনে হয়।"
  },
  Event_91495_Name = {
    Text = "নির্বাসিত রাজ্য"
  },
  Event_91496_ChoiceDesc1 = {
    Text = "[Consume] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে 1টিতে খোদাই করো।"
  },
  Event_91496_ChoiceDesc2 = {
    Text = "[Decline] উপসর্গ 「(Skill.Arg1)」 বিকশিত করো এবং খোদাই করার প্রার্থনাগাথা পরিবর্তন করো।(ব্যবহার: 1/2)"
  },
  Event_91496_Desc = {
    Text = "ডোরেসেইন সযত্ন ভঙ্গিতে তোমার জন্য 「মস্তিষ্কের」 এক টুকরো কেটে দেয়।\nওই মিষ্টি স্বাদ...\nওই নরম, সূক্ষ্ম গঠন...\nতোমার ভীষণ ইচ্ছে করে আরেক কামড় নিতে।"
  },
  Event_91496_Name = {
    Text = "উপাদেয় আহারের স্বাদ নিন"
  },
  Event_91497_ChoiceDesc1 = {
    Text = "[I'm Dreaming] রৌপ্য সৃষ্টি 「(RelicConfig.Arg1)」 অর্জন করো"
  },
  Event_91497_ChoiceDesc2 = {
    Text = "[This is Not Normal] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_91497_Desc = {
    Text = "একটি মসৃণ সমাধিফলকে প্রতিফলিত হয় এক চোখ, যা ধীরে ধীরে বিকৃত হয়ে যাচ্ছে।\nযেন দৃষ্টির বর্ণনার অতীত কোনো ছবি বহন করছে, এক স্মৃতি যা তোমার নয়, গভীরভাবে বসে গেছে তোমার চোখের ভাঁজে।\nতুমি পলক ফেলে, আঙুলের ডগা দিয়ে তা মুছে ফেলতে চাও, কিন্তু সেই চোখ আর তোমার নয়—তা প্রতিফলিত করতে শুরু করে এক ক্যালাইডোস্কোপিক দৃশ্য।"
  },
  Event_91497_Name = {
    Text = "প্রায় স্বাভাবিক"
  },
  Event_91498_ChoiceDesc1 = {
    Text = "[Continue Observation] প্রার্থনাগাথা 「(EnchantConfig.Arg1)」 তিনটি কমান্ড কার্ডের মধ্যে যেকোনো একটিতে খোদাই করো।"
  },
  Event_91498_ChoiceDesc2 = {
    Text = "[Look Away] 「(Skill.Arg1)」 উপসর্গটি বিকশিত করো এবং যে প্রার্থনাগাথা খোদাই করা হবে তা বদলাও।(ব্যবহার: 2/2)"
  },
  Event_91498_Desc = {
    Text = "প্রাচীন দুর্গের স্যাঁতসেঁতে এক কোণে, তুমি আবিষ্কার করলে সেই ফিল্মের রোলটি।\nছবিগুলো যেন সময়ের নদীতে ডুবে থাকা প্রেতাত্মা, ধীরগতির জমাট বাঁধা—কখনও বর্ণনাতীত বিশাল আকারে প্রসারিত হয়, কখনও ভেঙে পড়ে মিটমিট করা নক্ষত্রপুঞ্জে।\nতাদের ভেতরে হারিয়ে যেতে যেতে, হঠাৎ এক মাথা ঘোরা তোমাকে সময়ের প্যাসেজের কথা মনে করিয়ে দিল।"
  },
  Event_91498_Name = {
    Text = "অতীতের ছায়া"
  },
  Event_91499_ChoiceDesc1 = {
    Text = "[Gaze at the Stars] সোনার রেলিক 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_91499_ChoiceDesc2 = {
    Text = "[Close Your Eyes] 2 জন এলোমেলো জাগরণকারীকে জাগরণ ঘটাও, তবে 「(Skill.Arg1)「 দু」বার বিকশিত করো।"
  },
  Event_91499_ChoiceDesc3 = {
    Text = "[Leave] ৫০টি কালো চিহ্ন গ্রহণ করো"
  },
  Event_91499_Desc = {
    Text = "তুমি দাঁড়িয়ে আছ এক পরিত্যক্ত কবরস্থানে, যেখানে তারাদের উপস্থিতি রাতকে দিনসম উজ্জ্বল করে তুলেছে。\nসময়ের অতল গহ্বরে ভাসমান আলোর গোলকগুলো নীরব, তবু স্বপ্নের প্রলাপের মতো অন্তহীন ঘূর্ণনের মধ্য দিয়ে ধীরে ধীরে এক বিন্দুতে মিলিত হচ্ছে。\nতারা দৃষ্টিপাত করছে বিস্মৃত, একাকী নক্ষত্রটির দিকে。\nসে দৃষ্টিপাত করছে তোমার দিকে, সমস্ত মৃত্যু আর অনন্তের দিকে।"
  },
  Event_91499_Name = {
    Text = "নক্ষত্রের রাত"
  },
  Event_91500_ChoiceDesc1 = {
    Text = "[Listen] 20টি কালো চিহ্ন গ্রহণ করো, তবে 「(Skill.Arg2)」 বিকাশ করো।"
  },
  Event_91500_ChoiceDesc2 = {
    Text = "[Ignore] প্রস্থান"
  },
  Event_91500_Desc = {
    Text = "তোমার দৃষ্টির সঙ্গে তার দৃষ্টি আটকে যায়।\nঘন কালো অন্ধকারে তুমি দেখো লোভী বুনো আগুন।"
  },
  Event_91500_Name = {
    Text = "নীরব স্বীকারোক্তি"
  },
  Event_91501_ChoiceDesc1 = {
    Text = "[Open Socket] অভিশপ্ত নিদর্শন 「(RelicConfig.Arg1)」 অর্জন করো, তবে 「(Skill.Arg2)」 বিকশিত করো।"
  },
  Event_91501_ChoiceDesc2 = {
    Text = "[চাবির ছিদ্র বন্ধ করো]যেকোনো 1টি কার্ড অরিসন অর্জন করে：「(EnchantConfig.Arg1)」"
  },
  Event_91501_Desc = {
    Text = "ডোরেসেইন যখন তোমার দিকে মস্তিষ্কের লোব বাড়িয়ে দেয়, তুমি বারবার প্রতিরোধ করো, কিন্তু শেষ পর্যন্ত জ্ঞানের প্রলোভন সহ্য করতে পারো না।\nপ্রজ্ঞা ধীরে ধীরে নয়, হঠাৎ করেই ঝরে পড়ে তোমার উপর।\nতোমার মাথা ব্যথা করতে শুরু করে, আর তোমার চিন্তাধারা ফুলে ওঠা পাউরুটির মতো প্রসারিত হতে থাকে। অবশেষে যখন তুমি ভেঙে পড়ো, যন্ত্রণার ঢেউ সরে যায় জোয়ারের মতো, আর তোমার চেতনার গভীরে রয়ে যায় এক ফাঁপা, প্রাচীন চাবির ছিদ্র।\nএই তো জ্ঞানের আকৃতি! তুমি অনুভব করো এক অভূতপূর্ব প্রজ্ঞার স্রোত।\nহয়তো... তুমি আরও বেশি কিছু অর্জন করতে পারবে?"
  },
  Event_91501_Name = {
    Text = "প্রত্যাদেশ"
  },
  Event_91502_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91502_Desc = {
    Text = "তোমার চেতনার ঝুলে থাকা ব্লেড ব্যবহার করে তুমি উঁকি দিলে সেই চাবির ছিদ্রের ভেতর।\nচাবি কী, তুমি জানতেই না, তাই কেবল আবেশের জোরেই চেষ্টা চালালে।\nসেই মুহূর্তে, তোমার সব চিন্তা পুড়ে ছাই হয়ে গেল, ফাঁপা চাবির ছিদ্রের ভেতর কেবল অমানবিক কিছু হুইসপার করে যেতে লাগল।\nএটাই কি প্রত্যাদেশের অনুভূতি? তুমি আগ্রহভরে তা ভাগ করে নিলে ডোরেসেইন-এর সঙ্গে।\n「চেষ্টা করে দেখতে চাও? এটা গোপনরক্ষক {Male=মহোদয়,Female=মিস} মহাশয়ের জন্য বানানো বিশেষ মস্তিষ্কের মোৎজারেলা।」"
  },
  Event_91502_Name = {
    Text = "প্রত্যাদেশ"
