  Event_91503_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91503_Desc = {
    Text = "তুমি তা না বিস্ফোরিত করো, না দমন করো।\nএক সূক্ষ্ম, বিচ্ছিন্ন পর্যবেক্ষণের অবস্থায়, তুমি উথলে ওঠা চিন্তাগুলোকে আবহাওয়ার পরিবর্তনেরই অংশ বলে মনে করো, তাদের স্বাভাবিকভাবে বয়ে যেতে দাও এক অজানা জীবের মতো পরিণতির দিকে।\nরক্ত-মাংসের সেই ছবির ভেতরে, তুমি অনন্তের শিল্পকে উপলব্ধি করো।"
  },
  Event_91503_Name = {
    Text = "সুপ্ত আগ্নেয়গিরি"
