  Event_91504_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91504_Desc = {
    Text = "চাবিগুলো হঠাৎ থেমে যায়, আর প্রজাপতির ছায়া এক মুহূর্তে মিলিয়ে যায়।\nওটা কি মায়াস্বপ্ন ছিল? তোমার মধ্যে এক শূন্যতার অনুভূতি জেগে ওঠে।\nহয়তো ডোরেসেইনের কথা শুনে স্মৃতির ক্যানজাত দোকান থেকে কিছু মস্তিষ্কপাতা কিনে আনা উচিত।\n「না, আমি এসব কী ভাবছি?」"
  },
