  Event_91505_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91505_Desc = {
    Text = "তুমি ছটফটানি থামিয়ে দাও এবং ডানা ও কালো তরলকে তোমার তালু ভেদ করে বেরিয়ে আসতে দাও।\nতুমি তার পাত্রে পরিণত হও, আর সে তোমাকে খোলস হিসেবে ব্যবহার করে নিজের চিন্তাধারা চালিয়ে যায়।\nপ্রজাপতিটি ক্রমেই বড় হতে থাকে, যতক্ষণ না তুমি তার ওজন আর বহন করতে পারো না।\nএ দৃশ্য দেখে ডোরেসেইন আগ্রহভরে ডিনার নাইফ দিয়ে তোমার আর প্রজাপতির মধ্যে থাকা সংযোগটি কেটে দেয়। তার চোখের ক্ষুধার্ত দৃষ্টি স্পষ্টই তার কামনা প্রকাশ করে...\nতুমি তার অনুরোধ প্রত্যাখ্যান করো।"
