  Event_91507_ChoiceDesc1 = {Text = "[Leave]"},
  Event_91507_Desc = {
    Text = "তুমি চোখ বুজে পা বাড়াও অন্তহীন, নরম ধুলোর কুয়াশার ভেতর, যেখানে নীহারিকা তোমাকে আলিঙ্গন করে, আর তুমি হারিয়ে ফেলো নিজের আকার—তোমার দেহের চেয়েও স্থিতিশীল এক সত্তা নীরবে বসে যায় তোমার অন্তরে।\nসেই রাতে, নক্ষত্রপুঞ্জ ঘুরতেই থাকে, আগের মতোই উজ্জ্বল।\nএক অমর সত্তার কাছে, নক্ষত্রখচিত আকাশের মানে কী? হয়তো তোমার ডোরেসেইন-এর কাছে গিয়ে জিজ্ঞেস করা উচিত।"
