  Event_91509_Desc = {
    Text = "তুমি পিকম্যানের ছবির দিকে স্থির দৃষ্টিতে তাকিয়ে থাকো, আর ক্ষয়ের বমি উদ্রেককারী দুর্গন্ধ তোমাকে স্তব্ধ করে দেয়।\nচিন্তাগুলো ধীরে ধীরে মাথা থেকে উঠতে থাকে—প্রথমে শুধু উত্তাপ, তারপর কুয়াশা, এবং পরে—"
