  },
  Event_91660_Desc = {
    Text = "「আত্মাকে চালিত করো—তোমাকেই মৃতদের শেষ প্রান্তে পৌঁছে দিতে হবে।」\nডোরেসেইনের কণ্ঠের সঙ্গে সঙ্গে তোমার ভেতরে হঠাৎ এক প্রজ্ঞোদয় জেগে ওঠে।\nএটি না জ্ঞান, না স্মৃতি—বরং যেন এক ভার, চোখ দিয়ে ঢুকে স্রোতের মতো মস্তিষ্ক ভরে দিচ্ছে।\nতোমার আবেগ আর এই মুহূর্তের বলে মনে হয় না; সেগুলো সরে গিয়ে মহাবিশ্বের চোখ এড়ানো এক ফাঁক উন্মোচন করে।\nতোমার অনুভবের সবকিছু যেন ঠিক সেখানেই থেমে যায়, যেন তুমি পথের একেবারে শেষ প্রান্তে এসে দাঁড়িয়েছ।"
